@dataclass
class FixedCycleHedgeConfig:
    symbol: str = "BTCUSDT"
    category: str = "linear"
    bot_name: str = ""
    side: str = ""
    strategy_side: str = ""
    strategy: str = ""
    strategy_class: str = "FixedCycleHedgeStrategy"
    dynamic_symbol_enabled: bool = False
    best_coin_file: str = "logs/best_coin.json"
    best_coin_max_age_minutes: int = 45

    base_notional_usdt: float = 100.0
    hedge_ratio_short: float = 0.5
    initial_entry_order_type: str = "Market"
    initial_entry_reference_price: float = 0.0

    # New fixed-cycle settings
    reduction_pct_per_fill: float = 0.25
    long_cycle_qty_pct_of_initial: float = 25.0
    short_cycle_qty_pct_of_initial: float = 25.0
    long_fill_distance_pct: float = 0.5
    short_fill_distance_pct: float = 0.5
    recovery_activation_timing: str = "before_short_reduce_fill"
    max_pre_recovery_long_reduce_distance_pct: float = 5.0
    max_post_recovery_long_reduce_distance_pct: float = 5.0

    market_fallback_slippage_type: str = "Percent"
    market_fallback_slippage_value: float = 0.05
    second_order_safety_offset_pct: float = 0.05

    # Target logic
    long_exit_reduce_only: bool = True
    short_exit_reduce_only: bool = True
    tp_profit_target_pct: float = 0.5
    tp_buffer_pct: float = 0.0  # optional extra buffer on top of BE+profit target
    fee_safety_buffer_pct: float = 0.14
    order_fee_rate_pct: float = 0.055
    target_profit_usdt: float = 0.002
    net_realized_pnl_target: float = 0.0

    # Live short-TP relief (disabled by default).
    cycle_short_tp_relief_enabled: bool = False
    cycle_short_tp_relief_start_cycle_index: int = 4
    cycle_short_tp_relief_max_distance_pct_from_long_fill: float = 4.0
    cycle_short_tp_relief_carry_uncovered_loss_to_exit: bool = True

    hard_stop_cycle: int = 8
    hard_stop_pct: float = 1.0
    max_cycles: int = 10

    leverage_long: float = 3.0
    leverage_short: float = 3.0

    use_reduce_only: bool = True

    rest_poll_after_fill_ms: int = 250
    ws_enabled: bool = True
    restart: bool = True  # persist cycle state across restarts when enabled
    order_refresh_cooldown_ms: int = 750

    price_tick_size: float = 0.1
    # Number of ticks between SHORT_SL_EXIT and LONG_TP_EXIT in the final basket exit.
    # 0.0 = both final exits use the same trigger price.
    # 1.0 = LONG_TP_EXIT is kept one tick above SHORT_SL_EXIT.
    final_exit_tick_offset: float = 0.0
    trailing_stop_dist: float = 0.003
    short_tp_fallback_activation_drop_pct: float = 0.001
    short_tp_fallback_stop_offset_pct: float = 0.0025
    short_tp_min_threshold_pct_after_long_reduce: float = 0.006
    fallback_stale_seconds: float = 8.0
    qty_step: float = 0.001
    min_order_qty: float = 0.001
    min_notional_usdt: float = 5.0
    dynamic_symbol_hold_minutes: int = 10
    # Minutes after which a still-open trade becomes eligible for a time/distance-based
    # refill trigger. 0 or negative disables this trigger.
    time_distance_refill_trigger_minutes: int = 0
    # Optionaler Test-Override für den Recovery-/Time-Distance-Trigger.
    recovery_mode_trigger_override_enabled: bool = False
    recovery_mode_trigger_override_pct: float | None = None
    recovery_mode_trigger_override_ticks: int | None = None

    # Optional interner Safety-Watchdog, standardmäßig nur Logging.
    internal_safety_watchdog_enabled: bool = False
    internal_safety_watchdog_mode: str = "log_only"

    def __post_init__(self) -> None:
        allowed_recovery_timings = {
            "before_short_reduce_fill",
            "after_short_reduce_fill",
            "after_first_leg_reduce_fill",
        }
        if self.recovery_activation_timing not in allowed_recovery_timings:
            raise ValueError(
                "recovery_activation_timing must be one of "
                f"{sorted(allowed_recovery_timings)}"
            )
        if self.max_pre_recovery_long_reduce_distance_pct < 0:
            raise ValueError("max_pre_recovery_long_reduce_distance_pct must be >= 0")
        if self.max_post_recovery_long_reduce_distance_pct < 0:
            raise ValueError("max_post_recovery_long_reduce_distance_pct must be >= 0")

    @classmethod
    def from_json_file(cls, path: str | Path | None, *, enforce_expected_path: bool = True) -> "FixedCycleHedgeConfig":
        if not path:
            return cls()
        path_obj = Path(path).resolve()
        expected_path = EXPECTED_CONFIG_PATH.resolve()
        if enforce_expected_path:
            if not (
                path_obj == expected_path
                or _is_per_bot_config(path_obj)
                or _is_per_bot_runtime_config(path_obj)
            ):
                error_message = (
                    f"Invalid config path: {path_obj}\n"
                    f"Expected: {expected_path} or "
                    "live_bots/*/*/config/fixed_cycle_config.json or "
                    "live_bots/*/*/run/fixed_cycle_config.runtime.json"
                )
                raise ValueError(error_message)

        payload = json.loads(path_obj.read_text(encoding="utf-8"))
        if not isinstance(payload, dict):
            raise ValueError("Fixed-cycle config must be a JSON object")
        return cls(**payload)


