def _emit_analyzer_event(logger: logging.Logger, event: str, payload: dict[str, Any]) -> None:
    data = {
        "event": event,
        "timestamp": datetime.now(timezone.utc).isoformat(),
        **payload,
    }
    logger.info(json.dumps(data))


def _log_event(
    event: str,
    payload: dict[str, Any],
    *,
    runtime_state: RuntimeState | None = None,
) -> None:
    if event == "fixed_cycle_refill_gate_state_after_reconcile":
        before = payload.get("before") or {}
        after = payload.get("after") or {}
        if before == after:
            logger.debug("%s %s", event, payload)
            return
        logger.info("%s %s", event, payload)
        return

    if log_throttle.is_debug_only_event(event):
        logger.debug("%s %s", event, payload)
        return

    if log_throttle.is_throttled_info_event(event):
        strategy_state = runtime_state.strategy_state if runtime_state is not None else None
        throttle_state = log_throttle.resolve_throttle_state(payload, strategy_state)
        decision = log_throttle.should_log_throttled_event(event, payload, throttle_state)
        if not decision.should_log:
            return
        log_payload = dict(payload)
        if decision.suppressed_count > 0:
            log_payload["suppressed_count"] = decision.suppressed_count
            log_payload["throttle_interval_sec"] = decision.throttle_interval_sec
        logger.info("%s %s", event, log_payload)
        return

    logger.info("%s %s", event, payload)


def _log_warning_event(event: str, payload: dict[str, Any]) -> None:
    logger.warning("%s %s", event, payload)


def _resolve_confirmed_pnl_history_target(
    *,
    route_side: str,
    default_bot: str,
    base_path: Path,
) -> tuple[str, Path]:
    """
    Bestimme das Ziel-Bot-Label (long_bot_N/short_bot_N) und die History-Datei
    für Confirmed-PnL-Einträge auf Basis von side/purpose und default_bot.
    """
    normalized_side = str(route_side or "").strip().lower()
    target_bot_name = default_bot
    target_path = base_path
    try:
        match = re.search(r"_(\d+)$", str(default_bot or "").strip().lower())
        index = match.group(1) if match else None
        if index and normalized_side in {"long", "short"}:
            # Basis-Verzeichnis des aktuell laufenden Bots, z.B.
            # .../live_bots/100_50_hedge_bot/long_bot_1/logs/confirmed_order_pnl_history.jsonl
            group_root_candidate = base_path.parent.parent.parent
            live_bots_root = group_root_candidate.parent

            # Langfristiges Mapping:
            # - long_bot_N  -> live_bots/100_50_hedge_bot/long_bot_N
            # - short_bot_N -> live_bots/short_hedge_bot/short_bot_N
            if group_root_candidate.name == "100_50_hedge_bot":
                long_group_root = group_root_candidate
                short_group_root = live_bots_root / "short_hedge_bot"
            elif group_root_candidate.name == "short_hedge_bot":
                short_group_root = group_root_candidate
                long_group_root = live_bots_root / "100_50_hedge_bot"
            else:
                # Unerwarteter Pfad – zur Sicherheit keine Umlenkung.
                return default_bot, base_path

            if normalized_side == "short":
                target_bot_name = f"short_bot_{index}"
                target_logs_dir = short_group_root / target_bot_name / "logs"
            else:
                target_bot_name = f"long_bot_{index}"
                target_logs_dir = long_group_root / target_bot_name / "logs"

            target_logs_dir.mkdir(parents=True, exist_ok=True)
            target_path = target_logs_dir / "confirmed_order_pnl_history.jsonl"
    except Exception:
        # Fallback: im Zweifel bleibt der ursprüngliche Pfad/Bot bestehen.
        target_bot_name = default_bot
        target_path = base_path
    return target_bot_name, target_path


def _safe_audit_value(value: Any) -> Any:
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, dict):
        return {str(key): _safe_audit_value(val) for key, val in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_safe_audit_value(val) for val in value]
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, (int, float, bool, str)) or value is None:
        return value
    return str(value)


def _audit_calc(event: str, data: dict[str, Any], *, level: int = logging.INFO) -> None:
    payload = {"event": event, "timestamp": datetime.now(timezone.utc).isoformat()}
    payload["timestamp_ms"] = int(time.time() * 1000)
    payload.update({key: _safe_audit_value(value) for key, value in data.items()})
    try:
        calc_audit_logger.log(level, json.dumps(payload, ensure_ascii=False))
    except Exception as exc:
        logger.warning(
            "calc_audit_logging_failed",
            extra={
                "event": event,
                "error": str(exc),
                "data": {key: str(val) for key, val in data.items()},
            },
        )


class FixedCycleHedgeStrategy(HedgeStrategy):
    name = "fixed_cycle"

    STATE_INIT = "INIT"
    STATE_OPENING_HEDGE = "OPENING_HEDGE"
    STATE_PREPLACING_DOWNSIDE_ORDERS = "PREPLACING_DOWNSIDE_ORDERS"
    STATE_RUNNING = "RUNNING"
    STATE_RECONCILING_AFTER_FILL = "RECONCILING_AFTER_FILL"
    STATE_RESETTING_EXITS = "RESETTING_EXITS"
    STATE_REFILL_PENDING = "REFILL_PENDING"
    STATE_REFILL_IN_PROGRESS = "REFILL_IN_PROGRESS"
    STATE_HARD_STOP_MODE = "HARD_STOP_MODE"
    STATE_EXITED = "EXITED"
    STATE_ERROR = "ERROR"
    EMERGENCY_EXIT_STATUSES = {"CANCELED", "CANCELLED", "REJECTED", "EXPIRED", "DEACTIVATED"}
    EMERGENCY_REJECT_REASON = "EC_NOIMMEDIATEQTYTOFILL"
    EMERGENCY_EXIT_MAX_RETRIES = 3
    EMERGENCY_FLAT_LONG_PURPOSE = "EMERGENCY_FLAT_LONG"
    EMERGENCY_FLAT_SHORT_PURPOSE = "EMERGENCY_FLAT_SHORT"

    FINAL_EXIT_MISSING_FRESH_ENTRY_BLOCK_SEC = 8.0
    FINAL_EXIT_MISSING_REBUILD_BLOCK_SEC = 3.0
    FINAL_EXIT_MISSING_FORCE_BLOCK_SEC = 4.0

    def _set_final_exit_missing_block(self, runtime_state: RuntimeState, duration_seconds: float) -> None:
        if duration_seconds <= 0:
            return
        state = runtime_state.strategy_state
        active_snapshot_order_purposes: list[str] = []
        active_runtime_order_purposes: list[str] = []
        now = time.monotonic()
        existing_until = float(state.get("final_exit_missing_block_until") or 0.0)
        target_until = now + duration_seconds
        if target_until > existing_until:
            state["final_exit_missing_block_until"] = target_until

    def _is_final_exit_missing_block_active(self, runtime_state: RuntimeState) -> bool:
        until = float(runtime_state.strategy_state.get("final_exit_missing_block_until") or 0.0)
        return until > time.monotonic()

    LONG_ENTRY_PURPOSE = "INITIAL_LONG_ENTRY"
    SHORT_ENTRY_PURPOSE = "INITIAL_SHORT_ENTRY"
    LONG_TP_EXIT_PURPOSE = "LONG_TP_EXIT"
    LONG_SL_EXIT_PURPOSE = "LONG_SL_EXIT"
    SHORT_TP_EXIT_PURPOSE = "SHORT_TP_EXIT"
    SHORT_SL_EXIT_PURPOSE = "SHORT_SL_EXIT"
    LONG_TP_EXIT_RECOVERY_PURPOSE = "LONG_TP_EXIT_RECOVERY"
    SHORT_SL_EXIT_RECOVERY_PURPOSE = "SHORT_SL_EXIT_RECOVERY"
    SHORT_HARD_STOP_PURPOSE = "SHORT_HARD_STOP_EXIT"

    # Historische Namen (kompatibel zu bestehenden Logs/State).
    RECOVERY_REFILL_LONG: ClassVar[str] = "RECOVERY_REFILL_LONG"
    RECOVERY_REFILL_SHORT: ClassVar[str] = "RECOVERY_REFILL_SHORT"
    # Bevorzugte neuen Purposes für Recovery Capital Reload.
    RECOVERY_RELOAD_LONG_ENTRY: ClassVar[str] = "RECOVERY_RELOAD_LONG_ENTRY"
    RECOVERY_RELOAD_SHORT_ENTRY: ClassVar[str] = "RECOVERY_RELOAD_SHORT_ENTRY"

    def _is_recovery_reload_long_purpose(self, purpose: Any) -> bool:
        text = str(purpose or "").upper()
        return text in {
            str(self.RECOVERY_REFILL_LONG).upper(),
            str(self.RECOVERY_RELOAD_LONG_ENTRY).upper(),
        }

    def _is_recovery_reload_short_purpose(self, purpose: Any) -> bool:
        text = str(purpose or "").upper()
        return text in {
            str(self.RECOVERY_REFILL_SHORT).upper(),
            str(self.RECOVERY_RELOAD_SHORT_ENTRY).upper(),
        }

    def _is_recovery_reload_purpose(self, purpose: Any) -> bool:
        return self._is_recovery_reload_long_purpose(purpose) or self._is_recovery_reload_short_purpose(purpose)

    @staticmethod
    def _recovery_reload_legacy_key(new_key: str) -> str | None:
        if new_key.startswith("recovery_reload_"):
            return "recovery_refill_" + new_key[len("recovery_reload_") :]
        return None

    def _get_recovery_reload_state_value(
        self,
        state: dict[str, Any],
        cycle_state: dict[str, Any],
        new_key: str,
        *,
        default: Any = None,
    ) -> Any:
        legacy_key = self._recovery_reload_legacy_key(new_key)
        for key in (new_key, legacy_key):
            if key and key in state:
                return state.get(key)
            if key and key in cycle_state:
                return cycle_state.get(key)
        return default

    def _set_recovery_reload_state_value(
        self,
        state: dict[str, Any],
        cycle_state: dict[str, Any],
        new_key: str,
        value: Any,
        *,
        mirror_legacy: bool = True,
    ) -> None:
        state[new_key] = value
        cycle_state[new_key] = value
        legacy_key = self._recovery_reload_legacy_key(new_key)
        if mirror_legacy and legacy_key:
            state[legacy_key] = value
            cycle_state[legacy_key] = value

    def _perform_verified_flat_runtime_reset(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        reason: str,
        allow_unknown_final_pnl: bool = True,
    ) -> bool:
        return perform_verified_flat_runtime_reset(
            snapshot=snapshot,
            runtime_state=runtime_state,
            context=context,
            reason=reason,
            logger=logger,
            reset_cycle_state=lambda: self._reset_cycle_state(runtime_state),
            force_fresh_start_reset=lambda: self._force_fresh_start_reset(runtime_state),
            clear_startup_zero_state_residuals=lambda: self._clear_startup_zero_state_residuals(
                runtime_state,
                preserve_audit_history=True,
            ),
            state_init_value=self.STATE_INIT,
            allow_unknown_final_pnl=allow_unknown_final_pnl,
        )

    # Final-Exit-Purpose-Resolver (direction-aware, von Short-Strategie überschreibbar)
    def _get_final_long_exit_purpose(self) -> str:
        return self.LONG_TP_EXIT_PURPOSE

    def _get_final_short_exit_purpose(self) -> str:
        return self.SHORT_SL_EXIT_PURPOSE

    def _get_final_exit_purposes(self) -> set[str]:
        return {
            self._get_final_long_exit_purpose(),
            self._get_final_short_exit_purpose(),
        }

    def __init__(self, config: FixedCycleHedgeConfig | None = None) -> None:
        self.config = config or FixedCycleHedgeConfig()
        logger = logging.getLogger(__name__)
        config_fields = [field.name for field in fields(self.config)]
        long_attr = hasattr(self.config, "long_exit_reduce_only")
        short_attr = hasattr(self.config, "short_exit_reduce_only")
        logger.debug(
            "[RUNTIME_CONFIG_DEBUG] file=%s type=%s module=%s fields=%s long_attr=%s short_attr=%s long_value=%s short_value=%s",
            __file__,
            type(self.config),
            self.config.__class__.__module__,
            config_fields,
            long_attr,
            short_attr,
            getattr(self.config, "long_exit_reduce_only", None),
            getattr(self.config, "short_exit_reduce_only", None),
        )
        self.realized_long_loss_total = 0.0
        direction = direction_config.get_direction_config()
        self._sequence_config = CycleSequenceConfig(
            cycle_prefix="CYCLE",
            first_leg=direction.cycle_first_leg,
            second_leg=direction.cycle_second_leg,
        )

    def _get_short_tp_fallback_state(self, runtime_state: RuntimeState) -> ShortTpFallbackState:
        return ShortTpFallbackState.from_dict(runtime_state.strategy_state.get("short_tp_fallback_state"))

    def _store_short_tp_fallback_state(
        self, runtime_state: RuntimeState, fallback_state: ShortTpFallbackState
    ) -> None:
        runtime_state.strategy_state["short_tp_fallback_state"] = fallback_state.to_dict()

    def _reset_initial_entry_reconcile_state(
        self,
        runtime_state: RuntimeState,
        *,
        reset_submission_state: bool,
    ) -> None:
        state = runtime_state.strategy_state
        if reset_submission_state:
            state["initial_entry_submitted"] = False
            state["initial_entry_confirmed"] = False
        state["initial_long_entry_reconciled"] = False
        state["initial_short_entry_reconciled"] = False
        state["initial_structure_built"] = False

    def _mark_initial_entry_reconciled_from_terminal_order(
        self,
        runtime_state: RuntimeState,
        snapshot: HedgeSnapshot | None,
        *,
        purpose: str | None,
        exchange_order_id: str | None,
        client_order_id: str | None,
        source: str,
    ) -> None:
        if purpose not in {self.LONG_ENTRY_PURPOSE, self.SHORT_ENTRY_PURPOSE}:
            return
        state = runtime_state.strategy_state
        long_qty = float(snapshot.long_qty if snapshot else 0.0)
        short_qty = float(snapshot.short_qty if snapshot else 0.0)
        changed = False
        if purpose == self.LONG_ENTRY_PURPOSE and long_qty > 0:
            state["initial_entry_submitted"] = True
            if not state.get("initial_long_entry_reconciled"):
                state["initial_long_entry_reconciled"] = True
                changed = True
        if purpose == self.SHORT_ENTRY_PURPOSE and short_qty > 0:
            state["initial_entry_submitted"] = True
            if not state.get("initial_short_entry_reconciled"):
                state["initial_short_entry_reconciled"] = True
                changed = True
        if changed:
            _log_event(
                "fixed_cycle_initial_entry_reconciled_flag_set",
                {
                    "purpose": purpose,
                    "source": source,
                    "exchange_order_id": exchange_order_id,
                    "client_order_id": client_order_id,
                    "long_qty": long_qty,
                    "short_qty": short_qty,
                    "initial_long_entry_reconciled": bool(state.get("initial_long_entry_reconciled")),
                    "initial_short_entry_reconciled": bool(state.get("initial_short_entry_reconciled")),
                    "initial_structure_built": bool(state.get("initial_structure_built")),
                },
            )

    def _clear_short_tp_fallback_order_context(self, runtime_state: RuntimeState) -> None:
        runtime_state.strategy_state.pop("short_tp_fallback_order_context", None)

    def _register_short_tp_fallback_order(self, runtime_state: RuntimeState) -> None:
        fallback_state = self._get_short_tp_fallback_state(runtime_state)
        context = runtime_state.strategy_state.get("short_tp_fallback_order_context") or {}
        client_order_id = fallback_state.client_order_id
        if not client_order_id:
            return
        managed_order = ManagedOrder(
            client_order_id=client_order_id,
            side="short",
            qty=float(fallback_state.qty or 0.0),
            purpose=str(context.get("purpose") or "SHORT_TP_FALLBACK"),
            price=float(fallback_state.original_trigger_price or 0.0),
            order_type="Market",
            reduce_only=True,
            exchange_order_id=fallback_state.exchange_order_id,
            status="OPEN",
            remaining_qty=float(fallback_state.qty or 0.0),
            metadata={
                "cycle_index": int(context.get("cycle_index") or 0),
                "cycle_role": "short_reduce",
                "short_tp_fallback": True,
            },
        )
        runtime_state.active_orders[client_order_id] = managed_order
        if fallback_state.exchange_order_id:
            runtime_state.exchange_to_client_id[fallback_state.exchange_order_id] = client_order_id

    def _force_fresh_start_reset(self, runtime_state: RuntimeState) -> None:
        state = runtime_state.strategy_state
        preserved_last_trade = self._preserve_last_trade_pnl_fields(state)
        self._clear_emergency_state(runtime_state)
        state["startup_flat_reset_applied"] = False
        state["full_exit_reset_in_progress"] = False
        state["block_exit_rebuild_until_pnl_ready"] = False
        state["force_exit_rebuild"] = False
        state["long_add_locked"] = False
        state["long_add_pending"] = False
        state["cycle_waiting_for_short_tp"] = False
        state["short_tp_pending_cycle"] = 0
        state["exit_locked"] = False
        state["exit_rebuild_allowed"] = True
        state["trailing_active"] = None
        state["refill_pending"] = False
        state["refill_required"] = False
        state["refill_in_progress"] = False
        state["refill_exit_orders_cancel_required"] = False
        state["refill_required"] = False
        state["refill_pending"] = False
        state["refill_in_progress"] = False
        state["refill_fills_complete"] = False
        state["refill_completion_pending_reconcile"] = False
        state["refill_completed"] = True
        state["refill_completed"] = False
        state["cycle_block_status"] = None
        state["refill_long_filled"] = False
        state["refill_short_filled"] = False
        state["force_short_tp_rebuild"] = False
        state["cycle_long_add_filled"] = False
        state["cycle_short_tp_filled"] = False
        state["cycle_pair_count"] = 0
        state["cycle_completed_count"] = 0
        state["current_long_cycle_index"] = 0
        state["current_short_cycle_index"] = 0
        state["current_effective_cycle"] = 0
        state["pending_long_cycle_index"] = 0
        state["pending_short_cycle_index"] = 0
        state["last_exit_signature"] = None
        state["last_fill_info"] = {}
        state["latest_break_even_price"] = 0.0
        state["latest_tp_price"] = 0.0
        state["last_short_tp_trigger_price"] = 0.0
        state["last_expected_short_tp_net"] = 0.0
        state["last_short_tp_qty"] = 0.0
        state["short_tp_fallback_state"] = None
        state["short_tp_fallback_order_context"] = None
        state["pending_cycle_loss_usdt"] = 0.0
        state["short_exit_recovery_submitted"] = False
        state["long_exit_recovery_submitted"] = False
        state["exit_recovery_marker"] = False
        state["pending_loss_updated_in_fill"] = False
        state["pending_loss_exit_old_signature"] = None
        state["pending_loss_exit_rebuild_reason"] = None
        state["initial_entry_confirmed"] = False
        state["initial_entry_submitted"] = False
        self._reset_initial_entry_reconcile_state(runtime_state, reset_submission_state=True)
        state["current_trade_pnl_state_reset_for_entry"] = False
        state["entry_reference_price"] = 0.0
        state["initial_long_qty"] = 0.0
        state["initial_short_qty"] = 0.0
        state["cycle_states"] = {}
        state["processed_cycle_purposes"] = []
        state.pop("completed_cycle_purposes", None)
        state["last_confirmed_short_fill_price"] = 0.0
        state["last_confirmed_short_fill_cycle_index"] = 0
        state["last_confirmed_short_fill_purpose"] = None
        state["last_confirmed_short_fill_price"] = 0.0
        state["last_confirmed_short_fill_cycle_index"] = 0
        state["last_confirmed_short_fill_purpose"] = None
        state.pop("flat_waiting_order_cleanup_logged", None)
        state.pop("flat_waiting_final_pnl_logged", None)
        state.pop("flat_final_pnl_ready_logged", None)
        state.pop("final_pnl_context_missing_logged", None)
        state["final_exit_pnl_fetch_attempts"] = 0
        state["final_exit_pnl_fetch_deferred_cleanup"] = False
        state["final_exit_pnl_deferred_allows_fresh_entry"] = False
        state["last_trade_pnl_pending"] = False
        state.pop("final_exit_context_missing_but_flat_confirmed", None)
        state.pop("final_exit_fallback_reason", None)
        state.pop("final_exit_fallback_applied_at", None)
        state.pop("pending_rest_fill_confirmations", None)
        state.pop("rest_fill_dispatch_keys", None)
        self._restore_last_trade_pnl_fields(state, preserved_last_trade)

    def _in_emergency_final_exit_context(self, state: dict[str, Any]) -> bool:
        return bool(
            state.get("emergency_flat_required")
            or state.get("emergency_exit_reason")
            or state.get("final_exit_pnl_fetch_deferred_cleanup")
        )

    def _clear_startup_zero_state_residuals(
        self, runtime_state: RuntimeState, *, preserve_audit_history: bool = False
    ) -> None:
        state = runtime_state.strategy_state
        keys_to_pop = [
            "final_trade_pnl_audited",
            "final_long_exit_audited",
            "final_short_exit_audited",
            "final_long_exit_order_context",
            "final_short_exit_order_context",
            "final_exit_closed_pnl_signatures",
            "audit_processed_exit_fill_ids",
            "audit_completed_cycle_indices",
            "processed_pnl_exec_ids",
            "processed_pnl_exec_ids_order",
            "trade_block_id",
            "last_trade_block_id",
            "post_exit_cleanup_required",
            "post_exit_cleanup_verified",
            "post_exit_cleanup_in_progress",
            "post_exit_cleanup_attempts",
            "post_exit_cleanup_started_at",
            "post_exit_cleanup_verified_at",
            "post_exit_cleanup_verified_snapshot_updated_at",
            "restart_delayed_pending_final_pnl_logged",
            "short_exit_recovery_submitted",
            "long_exit_recovery_submitted",
            "exit_recovery_marker",
            "final_exit_context_missing_but_flat_confirmed",
            "final_exit_fallback_reason",
            "final_exit_fallback_applied_at",
            "pending_rest_fill_confirmations",
            "rest_fill_dispatch_keys",
        ]
        for key in keys_to_pop:
            state.pop(key, None)
        state["cycle_states"] = {}
        state["processed_cycle_purposes"] = []
        state.pop("completed_cycle_purposes", None)
        self._clear_second_leg_followup_residuals(runtime_state, clear_cycle_states=False)
        if not preserve_audit_history:
            for key in list(state.keys()):
                if key.startswith("last_trade_"):
                    state.pop(key, None)
            state["audit_pnl_ledger"] = {
                "cycle_long_reduce_pnl": {},
                "cycle_short_tp_pnl": {},
                "cycle_pnl_entries": {},
                "final_long_exit_pnl": None,
                "final_short_exit_pnl": None,
                "total_realized_pnl": 0.0,
            }
        state["startup_flat_reset_applied"] = True
        self._reset_initial_entry_reconcile_state(runtime_state, reset_submission_state=True)

    def prepare_for_clean_startup(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> bool:
        if (
            snapshot.long_qty > 0
            or snapshot.short_qty > 0
            or self._has_nonterminal_snapshot_orders(snapshot)
        ):
            return False
        state = runtime_state.strategy_state
        cycle_state = state.get("cycle_state") or {}
        stale_runtime_orders = [
            order.purpose or order.client_order_id
            for order in runtime_state.active_orders.values()
            if order.status not in {"FILLED", "CANCELED", "CANCELLED", "REJECTED"}
        ]
        stale_details = {
            "initial_entry_confirmed": bool(state.get("initial_entry_confirmed")),
            "initial_entry_submitted": bool(state.get("initial_entry_submitted")),
            "cycle_completed_count": int(state.get("cycle_completed_count") or 0),
            "cycle_waiting_for_short_tp": self._get_second_leg_waiting(state, cycle_state),
            "short_tp_pending_cycle": self._get_second_leg_pending_cycle(state, cycle_state),
            "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
            "cycle_state_trade_active": bool(cycle_state.get("trade_active")),
            "cycle_state_long_add_pending": self._get_first_leg_pending(state, cycle_state),
            "cycle_state_waiting_for_short_tp": self._get_second_leg_waiting(state, cycle_state),
            "cycle_state_short_tp_pending_cycle": self._get_second_leg_pending_cycle(state, cycle_state),
            "stale_runtime_orders": stale_runtime_orders,
        }
        logger.info("fixed_cycle_startup_zero_state_reset_started %s", stale_details)
        if not self._perform_verified_flat_runtime_reset(
            snapshot=snapshot,
            runtime_state=runtime_state,
            context=context,
            reason="startup_flat_state_reset",
            allow_unknown_final_pnl=True,
        ):
            return False
        logger.info(
            "fixed_cycle_startup_zero_state_reset_cleared_old_exit_manifest %s",
            {
                "symbol": self.config.symbol,
                "final_long_exit_order_context_present": bool(state.get("final_long_exit_order_context")),
                "final_short_exit_order_context_present": bool(state.get("final_short_exit_order_context")),
                "final_long_exit_audited": bool(state.get("final_long_exit_audited")),
                "final_short_exit_audited": bool(state.get("final_short_exit_audited")),
                "final_exit_closed_pnl_signatures": state.get("final_exit_closed_pnl_signatures"),
                "trade_block_id": state.get("trade_block_id"),
                "last_trade_block_id": state.get("last_trade_block_id"),
            },
        )
        logger.info(
            "fixed_cycle_startup_zero_state_reset_cleared_old_intents %s",
            {
                "symbol": self.config.symbol,
                "active_order_count": len(runtime_state.active_orders),
                "stale_runtime_orders": stale_runtime_orders,
                "cycle_state": state.get("cycle_state"),
                "initial_entry_confirmed": bool(state.get("initial_entry_confirmed")),
                "initial_entry_submitted": bool(state.get("initial_entry_submitted")),
            },
        )
        logger.info(
            "fixed_cycle_restart_state_cleanup_complete %s",
            {
                "symbol": self.config.symbol,
                "long_add_locked": state.get("long_add_locked"),
            "long_add_pending": self._get_first_leg_pending(state, cycle_state),
            "cycle_waiting_for_short_tp": self._get_second_leg_waiting(state, cycle_state),
            "short_tp_pending_cycle": self._get_second_leg_pending_cycle(state, cycle_state),
                "pending_cycle_loss_usdt": state.get("pending_cycle_loss_usdt"),
                "exit_locked": state.get("exit_locked"),
                "exit_rebuild_allowed": state.get("exit_rebuild_allowed"),
                "trailing_active": state.get("trailing_active"),
                "refill_pending": state.get("refill_pending"),
                "refill_in_progress": state.get("refill_in_progress"),
                "cycle_completed_count": state.get("cycle_completed_count"),
                "cycle_pair_count": state.get("cycle_pair_count"),
                "current_long_cycle_index": state.get("current_long_cycle_index"),
                "current_short_cycle_index": state.get("current_short_cycle_index"),
                "current_effective_cycle": state.get("current_effective_cycle"),
                "cycle_state": state.get("cycle_state"),
            },
        )

        logger.info(
            "fixed_cycle_clean_startup_reset_complete %s",
            {
                "symbol": self.config.symbol,
                "cycle_completed_count": state.get("cycle_completed_count"),
            "cycle_waiting_for_short_tp": self._get_second_leg_waiting(state, cycle_state),
            "short_tp_pending_cycle": self._get_second_leg_pending_cycle(state, cycle_state),
                "pending_cycle_loss_usdt": state.get("pending_cycle_loss_usdt"),
                "active_order_count": len(runtime_state.active_orders),
                "startup_flat_reset_applied": bool(state.get("startup_flat_reset_applied")),
            },
        )
        return True

    def _log_short_tp_fallback_event(
        self,
        event_name: str,
        fallback_state: ShortTpFallbackState,
        current_price: float,
        *,
        extra: dict[str, Any] | None = None,
    ) -> None:
        payload: dict[str, Any] = {
            "original_trigger_price": fallback_state.original_trigger_price,
            "activation_price": fallback_state.activation_price,
            "trailing_distance": fallback_state.trailing_distance,
            "qty": fallback_state.qty,
            "current_price": current_price,
            "lowest_price": fallback_state.lowest_price,
            "submitted": fallback_state.submitted,
            "submit_failed": fallback_state.submit_failed,
            "position_idx": fallback_state.position_idx,
        }
        if extra:
            payload.update(extra)
        log_method = logger.info
        if event_name == "SHORT_TP_FALLBACK_ACTIVE":
            log_method = logger.debug
        elif event_name == "SHORT_TP_FALLBACK_SUBMIT_FAILED":
            log_method = logger.warning
        log_method("%s %s", event_name, payload)

    def _maybe_run_short_tp_fallback(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> None:
        fallback_state = self._get_short_tp_fallback_state(runtime_state)
        if not fallback_state.active:
            return
        current_price = float(snapshot.current_price or 0.0)
        if current_price <= 0:
            return
        now_ms = int(time.time() * 1000)
        start_ms = fallback_state.started_at_ms or now_ms
        age_seconds = (now_ms - start_ms) / 1000
        order_manager = context.order_manager

        def _reset_fallback(*, cancel_existing_order: bool = True) -> None:
            cancel_success = True
            if cancel_existing_order and fallback_state.exchange_order_id and order_manager:
                try:
                    cancel_success = bool(
                        order_manager.cancel_order(
                            fallback_state.exchange_order_id,
                            symbol=self.config.symbol,
                            category=self.config.category,
                        )
                    )
                except Exception as exc:
                    cancel_success = False
                    logger.warning(
                        "SHORT_TP_FALLBACK_CANCEL_FAILED %s",
                        {
                            "exchange_order_id": fallback_state.exchange_order_id,
                            "error": str(exc),
                        },
                    )
            if not cancel_success:
                return
            reset_short_tp_fallback(fallback_state)
            self._store_short_tp_fallback_state(runtime_state, fallback_state)
            self._clear_short_tp_fallback_order_context(runtime_state)
            has_short_tp = any(
                "SHORT_TP" in str(getattr(order, "purpose", "") or "")
                and getattr(order, "status", None) not in {"FILLED", "CANCELED", "CANCELLED", "REJECTED"}
                for order in runtime_state.active_orders.values()
            ) or any(
                "SHORT_TP" in str(getattr(order, "purpose", "") or "")
                and getattr(order, "status", None) not in {"FILLED", "CANCELED", "CANCELLED", "REJECTED"}
                for order in snapshot.active_orders
            )
            if not has_short_tp:
                runtime_state.strategy_state["force_short_tp_rebuild"] = True

        if not fallback_state.submitted:
            log_extra = {
                "original_trigger_price": fallback_state.original_trigger_price,
                "activation_price": fallback_state.activation_price,
                "lowest_price": fallback_state.lowest_price,
                "current_price": current_price,
                "age_seconds": round(age_seconds, 2),
                "submitted": fallback_state.submitted,
            }
            if fallback_state.original_trigger_price > 0 and current_price >= (
                fallback_state.original_trigger_price
            ):
                self._log_short_tp_fallback_event(
                    "SHORT_TP_FALLBACK_RETRY_NORMAL_TP", fallback_state, current_price, extra=log_extra
                )
                _reset_fallback()
                return
            if age_seconds >= float(self.config.fallback_stale_seconds or 0.0):
                self._log_short_tp_fallback_event(
                    "SHORT_TP_FALLBACK_STALE_RESET", fallback_state, current_price, extra=log_extra
                )
                _reset_fallback()
                return
        if fallback_state.submitted and snapshot.short_qty <= 0:
            self._log_short_tp_fallback_event("SHORT_TP_FALLBACK_FILLED", fallback_state, current_price)
            _reset_fallback()
            return
        if snapshot.short_qty <= 0:
            self._log_short_tp_fallback_event("SHORT_TP_FALLBACK_ABORTED", fallback_state, current_price)
            _reset_fallback()
            return
        self._log_short_tp_fallback_event("SHORT_TP_FALLBACK_ACTIVE", fallback_state, current_price)
        if fallback_state.submitted and not fallback_state.submit_failed:
            if fallback_state.exchange_order_id:
                return
        if (
            fallback_state.last_submit_attempt_ms
            and now_ms - int(fallback_state.last_submit_attempt_ms) < 1000
        ):
            return
        fallback_state.last_submit_attempt_ms = now_ms
        submitted, response = update_short_tp_fallback(
            fallback_state,
            order_manager=context.order_manager,
            symbol=self.config.symbol,
            category=self.config.category,
            current_price=current_price,
            activation_drop_pct=self.config.short_tp_fallback_activation_drop_pct,
            stop_offset_pct=self.config.short_tp_fallback_stop_offset_pct,
        )
        self._store_short_tp_fallback_state(runtime_state, fallback_state)
        if submitted:
            self._register_short_tp_fallback_order(runtime_state)
            self._log_short_tp_fallback_event(
                "SHORT_TP_FALLBACK_SUBMITTED",
                fallback_state,
                current_price,
                extra={"response": response},
            )
        elif fallback_state.submit_failed:
            self._log_short_tp_fallback_event(
                "SHORT_TP_FALLBACK_SUBMIT_FAILED",
                fallback_state,
                current_price,
                extra={"response": response},
            )
        elif response:
            self._log_short_tp_fallback_event(
                "SHORT_TP_FALLBACK_ACTIVE",
                fallback_state,
                current_price,
                extra={"response": response},
            )

    def _maybe_trigger_emergency_flat_on_incomplete_final_exit_structure(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent] | None:
        state = runtime_state.strategy_state
        if state.get("emergency_flat_required"):
            return None
        if state.get("fresh_restart_required"):
            return None
        long_qty = float(snapshot.long_qty or 0.0)
        short_qty = float(snapshot.short_qty or 0.0)
        if long_qty <= 0 or short_qty <= 0:
            return None

        final_exit_orders: list[Any] = []
        seen_final_exit_order_keys: set[str] = set()

        def _collect_final_exit_order(order: Any) -> None:
            if not self._is_final_exit_only_order(order):
                return
            status = getattr(order, "status", None)
            if self._is_terminal_order_status(status):
                return
            exchange_id = str(getattr(order, "exchange_order_id", "") or "").strip()
            client_id = str(getattr(order, "client_order_id", "") or "").strip()
            purpose = str(getattr(order, "purpose", "") or "").strip()
            price = getattr(order, "price", None)
            qty = getattr(order, "qty", None)
            order_key = (
                exchange_id
                or client_id
                or f"{purpose}:{price}:{qty}"
            )
            if order_key in seen_final_exit_order_keys:
                return
            seen_final_exit_order_keys.add(order_key)
            final_exit_orders.append(order)

        for order in runtime_state.active_orders.values():
            _collect_final_exit_order(order)
        for order in snapshot.active_orders:
            _collect_final_exit_order(order)

        if len(final_exit_orders) != 1:
            state.pop("incomplete_final_exit_structure_first_seen_at", None)
            return None

        active_snapshot_order_purposes, active_runtime_order_purposes = (
            self._collect_active_strategy_order_purposes(snapshot, runtime_state)
        )
        bot_state = state.get("bot_state")
        block_reason: str | None = None
        if self._is_final_exit_missing_block_active(runtime_state):
            block_reason = "final_exit_missing_block_active"
        elif state.get("full_exit_reset_in_progress"):
            block_reason = "full_exit_reset_in_progress"
        elif state.get("force_exit_rebuild"):
            block_reason = "force_exit_rebuild"
        elif state.get("fresh_restart_required"):
            block_reason = "fresh_restart_required"
        elif bot_state in {
            self.STATE_INIT,
            self.STATE_OPENING_HEDGE,
            self.STATE_PREPLACING_DOWNSIDE_ORDERS,
            self.STATE_RESETTING_EXITS,
            self.STATE_RECONCILING_AFTER_FILL,
        }:
            block_reason = "early_bot_state"

        payload_base = {
            "symbol": self.config.symbol,
            "long_qty": long_qty,
            "short_qty": short_qty,
            "active_final_exit_order_count": len(final_exit_orders),
            "active_final_exit_orders": [
                self._strategy_order_summary(order) for order in final_exit_orders
            ],
            "bot_state": bot_state,
            "fresh_restart_required": bool(state.get("fresh_restart_required")),
            "full_exit_reset_in_progress": bool(state.get("full_exit_reset_in_progress")),
            "force_exit_rebuild": bool(state.get("force_exit_rebuild")),
            "exit_rebuild_allowed": bool(state.get("exit_rebuild_allowed")),
            "final_exit_missing_block_until": state.get(
                "final_exit_missing_block_until"
            ),
            "incomplete_final_exit_structure_first_seen_at": state.get(
                "incomplete_final_exit_structure_first_seen_at"
            ),
            "active_runtime_purposes": active_runtime_order_purposes,
            "active_exchange_purposes": active_snapshot_order_purposes,
        }

        if block_reason:
            _log_event(
                "fixed_cycle_incomplete_final_exit_structure_blocked",
                {**payload_base, "block_reason": block_reason},
            )
            state.pop("incomplete_final_exit_structure_first_seen_at", None)
            return None

        now = time.monotonic()
        first_seen = float(state.get("incomplete_final_exit_structure_first_seen_at") or 0.0)
        if first_seen <= 0:
            state["incomplete_final_exit_structure_first_seen_at"] = now
            _log_event(
                "fixed_cycle_incomplete_final_exit_structure_waiting",
                {
                    **payload_base,
                    "elapsed_seconds": 0.0,
                },
            )
            return None

        elapsed = now - first_seen
        if elapsed < 7.0:
            _log_event(
                "fixed_cycle_incomplete_final_exit_structure_waiting",
                {
                    **payload_base,
                    "elapsed_seconds": elapsed,
                },
            )
            return None

        _log_event(
            "fixed_cycle_incomplete_final_exit_structure_grace_expired",
            {
                **payload_base,
                "elapsed_seconds": elapsed,
            },
        )

        self._trigger_emergency_flat_for_remaining_positions(
            snapshot,
            runtime_state,
            context,
            "incomplete_final_exit_structure_one_order_remaining",
        )
        return self._maybe_handle_emergency_exit_tick(snapshot, runtime_state, context)

    def on_start(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent]:

        state = runtime_state.strategy_state
        state.setdefault("bot_state", self.STATE_INIT)
        state.setdefault("current_long_cycle_index", 0)
        state.setdefault("current_short_cycle_index", 0)
        state.setdefault("current_effective_cycle", 0)
        state.setdefault("completed_cycles", 0)
        state.setdefault("cycle_waiting_for_short_tp", False)
        state.setdefault("pending_long_cycle_index", 0)
        state.setdefault("short_tp_pending_cycle", 0)
        state.setdefault("long_add_pending", False)
        state.setdefault("cycle_completed_count", 0)
        state.setdefault("cycle_pair_count", 0)
        state.setdefault("cycle_long_add_filled", False)
        state.setdefault("cycle_short_tp_filled", False)
        state.setdefault("refill_pending", False)
        state.setdefault("refill_required", False)
        state.setdefault("refill_in_progress", False)
        state.setdefault("cycle_block_status", None)
        state.setdefault("refill_long_filled", False)
        state.setdefault("refill_short_filled", False)
        state.setdefault("refill_state", {})
        state.setdefault("open_long_qty", snapshot.long_qty)
        state.setdefault("open_short_qty", snapshot.short_qty)
        state.setdefault("long_avg", snapshot.long_avg)
        state.setdefault("short_avg", snapshot.short_avg)
        state.setdefault("realized_pnl_total", snapshot.realized_pnl_total)
        state.setdefault("entry_reference_price", 0.0)
        state.setdefault("initial_long_qty", 0.0)
        state.setdefault("initial_short_qty", 0.0)
        state.setdefault("initial_total_notional_usdt", 0.0)
        state.setdefault("last_structure_refresh_ms", 0)
        state.setdefault("initial_entry_submitted", False)
        state.setdefault("initial_entry_confirmed", False)
        state.setdefault("initial_long_entry_reconciled", False)
        state.setdefault("initial_short_entry_reconciled", False)
        state.setdefault("initial_structure_built", False)
        state.setdefault("initial_entry_retry_count", 0)
        state.setdefault("last_exit_signature", None)
        state.setdefault("net_long_loss_balance", 0.0)
        state.setdefault("net_short_loss_balance", 0.0)
        state.setdefault("pending_cycle_loss_usdt", 0.0)
        state.setdefault(
            "audit_pnl_ledger",
            {
                "cycle_long_reduce_pnl": {},
                "cycle_short_tp_pnl": {},
                "cycle_pnl_entries": {},
                "final_long_exit_pnl": None,
                "final_short_exit_pnl": None,
                "total_realized_pnl": 0.0,
            },
        )
        state.setdefault("audit_processed_exit_fill_ids", [])
        state.setdefault("block_exit_rebuild_until_pnl_ready", False)
        state.setdefault("force_exit_rebuild", False)
        state.setdefault("pending_loss_updated_in_fill", False)
        state.setdefault("pending_loss_exit_old_signature", None)
        state.setdefault("pending_loss_exit_rebuild_reason", None)
        state.setdefault("realized_long_loss_total", 0.0)
        self.realized_long_loss_total = float(state.get("realized_long_loss_total") or 0.0)
        state.setdefault("processed_pnl_exec_ids", [])
        state.setdefault("processed_pnl_exec_ids_order", [])
        state["recovery_marker_emitted"] = False
        state["block_closed_marker_emitted"] = False
        state["exit_armed_marker_emitted"] = False
        state.setdefault("exit_rebuild_allowed", True)
        state.setdefault("exit_rebuild_allowed", True)
        state.setdefault("fresh_restart_required", False)
        state.setdefault("final_exit_pnl_fetch_attempts", 0)
        state.setdefault("final_exit_pnl_fetch_deferred_cleanup", False)
        state.setdefault("final_exit_pnl_deferred_allows_fresh_entry", False)
        self._retry_pending_cycle_closed_pnl_fills(runtime_state, context)
        if state.get("fresh_restart_required"):
            if state.get("full_exit_reset_in_progress"):
                return []
            if snapshot.long_qty > 0 or snapshot.short_qty > 0:
                return []
            cleanup_snapshot = self._ensure_post_exit_cleanup_ready_for_fresh_restart(
                snapshot,
                runtime_state,
                context,
                reason="on_start_fresh_restart_required",
            )
            if cleanup_snapshot is None:
                return []
            snapshot = cleanup_snapshot
            if not self._perform_verified_flat_runtime_reset(
                snapshot,
                runtime_state,
                context,
                reason="on_start_fresh_restart_required",
                allow_unknown_final_pnl=True,
            ):
                return []
            if not self._dynamic_symbol_entry_gate_allows_entry(runtime_state, context, "fresh_restart"):
                return []
            self._maybe_update_symbol_from_best_coin(runtime_state, context, "fresh_restart")
            state["full_exit_reset_in_progress"] = True
            try:
                logger.info("fixed_cycle_full_exit_reset_start", {})
                runtime_state.realized_long_pnl_total = 0.0
                runtime_state.realized_short_pnl_total = 0.0
                self._reset_initial_entry_reconcile_state(runtime_state, reset_submission_state=True)
                intents = self._build_entry_intents(snapshot, runtime_state, context)
                if intents:
                    state["initial_entry_submitted"] = True
                    state["fresh_restart_required"] = False
                    state["dynamic_entry_hold_initialized"] = False
                    state.pop("next_dynamic_entry_allowed_at", None)
                    state["verified_flat_runtime_reset_done"] = False
                    self._set_final_exit_missing_block(
                        runtime_state, self.FINAL_EXIT_MISSING_FRESH_ENTRY_BLOCK_SEC
                    )
                return intents
            finally:
                state["full_exit_reset_in_progress"] = False

        self._ensure_cycle_state(runtime_state)
        context.audit.log_event(
            "fixed_cycle_start",
            strategy=self.name,
            config=asdict(self.config),
            snapshot=snapshot,
        )

        has_existing_positions = snapshot.long_qty > 0 or snapshot.short_qty > 0
        has_existing_orders = bool(snapshot.active_orders)
        block_type = "recovered_position_block" if has_existing_positions else "fresh_entry"
        cycle_index = int(state.get("current_effective_cycle") or 0)
        _emit_analyzer_event(
            logger,
            "analyzer_block_started",
            {
                "symbol": self.config.symbol,
                "strategy": self.name,
                "block_type": block_type,
                "has_existing_positions": has_existing_positions,
                "has_existing_orders": has_existing_orders,
                "long_size": snapshot.long_qty,
                "short_size": snapshot.short_qty,
                "long_avg_price": snapshot.long_avg,
                "short_avg_price": snapshot.short_avg,
                "bot_state": state.get("bot_state"),
                "cycle_index": cycle_index,
            },
        )

        self._update_initial_entry_confirmation(snapshot, runtime_state)
        if snapshot.long_qty > 0 and snapshot.short_qty > 0:
            context.audit.log_event(
                "fixed_cycle_initial_entry_skipped",
                strategy=self.name,
                reason="existing_positions_on_exchange",
                long_qty=snapshot.long_qty,
                short_qty=snapshot.short_qty,
            )
            state["initial_entry_confirmed"] = True
            context.audit.log_event(
                "fixed_cycle_initial_entry_skipped",
                strategy=self.name,
                reason="positions_already_exist",
                long_qty=snapshot.long_qty,
                short_qty=snapshot.short_qty,
            )
            self._seed_initial_reference_if_missing(snapshot, runtime_state)
            self._sync_state_from_snapshot(snapshot, runtime_state)
            state["bot_state"] = self.STATE_PREPLACING_DOWNSIDE_ORDERS
            return self._rebuild_structure(snapshot, runtime_state, context, reason="startup_existing_positions")

        if self._has_open_initial_entry_orders(snapshot, runtime_state):
            state["initial_entry_submitted"] = True
            context.audit.log_event(
                "fixed_cycle_initial_entry_skipped",
                strategy=self.name,
                reason="open_initial_orders_exist",
            )
            return []

        state["bot_state"] = self.STATE_OPENING_HEDGE
        if not self._dynamic_symbol_entry_gate_allows_entry(runtime_state, context, "startup"):
            return []
        self._maybe_update_symbol_from_best_coin(runtime_state, context, "startup")
        retry_count = int(state.get("initial_entry_retry_count") or 0) + 1
        state["initial_entry_retry_count"] = retry_count
        context.audit.log_event(
            "fixed_cycle_initial_entry_forced",
            strategy=self.name,
            current_price=snapshot.current_price,
            retry_count=retry_count,
        )
        self._reset_initial_entry_reconcile_state(runtime_state, reset_submission_state=True)
        intents = self._build_entry_intents(snapshot, runtime_state, context)
        if intents:
            state["initial_entry_submitted"] = True
            context.audit.log_event(
                "fixed_cycle_initial_entry_submitted",
                strategy=self.name,
                current_price=snapshot.current_price,
                intent_count=len(intents),
                retry_count=retry_count,
            )
            state["dynamic_entry_hold_initialized"] = False
            state.pop("next_dynamic_entry_allowed_at", None)
        long_intents = [intent for intent in intents if intent.side == "long"]
        short_intents = [intent for intent in intents if intent.side == "short"]
        first_long_purpose = self._cycle_purpose("long", 1)
        first_short_purpose = self._cycle_purpose("short", 1)
        logger.debug(
            "fixed_cycle_downside_build_result %s",
            {
                "long_intent_count": len(long_intents),
                "short_intent_count": len(short_intents),
                "total_intent_count": len(intents),
                "purposes": [intent.purpose for intent in intents],
                "first_long_cycle_present": any(intent.purpose == first_long_purpose for intent in intents),
                "first_short_cycle_present": any(intent.purpose == first_short_purpose for intent in intents),
            },
        )
        return intents

    def _short_followup_active_for_cycle(
        self,
        cycle_index: int,
        runtime_state: RuntimeState,
        snapshot: HedgeSnapshot,
    ) -> bool:
        if cycle_index <= 0:
            return False
        purpose = self._cycle_purpose("short", cycle_index)
        normalized_purpose = self._normalize_cycle_purpose(purpose)
        for order in runtime_state.active_orders.values():
            order_purpose = str(getattr(order, "purpose", "") or "").upper()
            if order_purpose != normalized_purpose:
                continue
            if self._is_terminal_order_status(getattr(order, "status", None)):
                continue
            return True
        for order in snapshot.active_orders:
            order_purpose = str(getattr(order, "purpose", "") or "").upper()
            if order_purpose != normalized_purpose:
                continue
            if self._is_terminal_order_status(getattr(order, "status", None)):
                continue
            return True
        return False

    def on_tick(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent]:
        state = runtime_state.strategy_state
        self._sync_state_from_snapshot(snapshot, runtime_state)
        self._update_initial_entry_confirmation(snapshot, runtime_state)
        self._retry_pending_cycle_closed_pnl_fills(runtime_state, context)
        self._maybe_run_short_tp_fallback(snapshot, runtime_state, context)
        incomplete_exit_intents = self._maybe_trigger_emergency_flat_on_incomplete_final_exit_structure(
            snapshot,
            runtime_state,
            context,
        )
        if incomplete_exit_intents is not None:
            return incomplete_exit_intents
        expected_cancel_intents = self._check_expected_cancel_replacement_timeouts(
            snapshot,
            runtime_state,
            context,
        )
        if expected_cancel_intents is not None:
            return expected_cancel_intents
        emergency_intents = self._maybe_handle_emergency_exit_tick(snapshot, runtime_state, context)
        if emergency_intents is not None:
            return emergency_intents
        # Optional interner Safety-Watchdog: standardmäßig deaktiviert bzw. nur Logging.
        if self.config.internal_safety_watchdog_enabled:
            safety_intents = self._safety_structure_watchdog(snapshot, runtime_state, context)
            if safety_intents is not None:
                return safety_intents
        self._maybe_clear_second_leg_waiting_without_orders(snapshot, runtime_state)
        if state.pop("force_short_tp_rebuild", False):
            return self._rebuild_structure(snapshot, runtime_state, context, reason="short_tp_fallback_reset")
        if state.get("fresh_restart_required"):
            if snapshot.long_qty > 0 or snapshot.short_qty > 0:
                return []
            cleanup_snapshot = self._ensure_post_exit_cleanup_ready_for_fresh_restart(
                snapshot,
                runtime_state,
                context,
                reason="on_tick_fresh_restart_required",
            )
            if cleanup_snapshot is None:
                return []
            snapshot = cleanup_snapshot
            if not self._perform_verified_flat_runtime_reset(
                snapshot,
                runtime_state,
                context,
                reason="on_tick_fresh_restart_required",
                allow_unknown_final_pnl=True,
            ):
                return []

            logger.info("fixed_cycle_full_exit_reset_start", {"source": "on_tick_fresh_restart_required"})
            state["full_exit_reset_in_progress"] = True
            try:
                runtime_state.realized_long_pnl_total = 0.0
                runtime_state.realized_short_pnl_total = 0.0

                if not self._dynamic_symbol_entry_gate_allows_entry(
                    runtime_state, context, "fresh_restart_tick"
                ):
                    return []

                self._maybe_update_symbol_from_best_coin(runtime_state, context, "fresh_restart_tick")
                self._reset_initial_entry_reconcile_state(runtime_state, reset_submission_state=True)
                intents = self._build_entry_intents(snapshot, runtime_state, context)
                if intents:
                    state["initial_entry_submitted"] = True
                    state["fresh_restart_required"] = False
                    state["final_exit_pnl_deferred_allows_fresh_entry"] = False
                    state["dynamic_entry_hold_initialized"] = False
                    state.pop("next_dynamic_entry_allowed_at", None)
                    state["verified_flat_runtime_reset_done"] = False
                    self._set_final_exit_missing_block(
                        runtime_state, self.FINAL_EXIT_MISSING_FRESH_ENTRY_BLOCK_SEC
                    )
                    return intents
                return []
            finally:
                state["full_exit_reset_in_progress"] = False

        # Optional time-distance-refill-Trigger zusätzlich auf Tick-Ebene prüfen,
        # damit der Midpoint auch ohne aktiven Downside-Build erreicht werden kann.
        triggered_refill = self._maybe_trigger_time_distance_refill(snapshot, runtime_state, context)
        if triggered_refill or self._cycle_build_block_active(state):
            reason = "time_distance_refill_triggered_tick" if triggered_refill else "refill_required_tick"
            return self._maybe_refresh_structure(snapshot, runtime_state, context, reason=reason)

        if snapshot.long_qty <= 0 and snapshot.short_qty <= 0:
            if self._block_flat_restart_until_final_pnl(
                snapshot, runtime_state, context, reason="on_tick_flat_before_entry"
            ):
                return []

        if (
            snapshot.long_qty <= 0
            and snapshot.short_qty <= 0
            and not state.get("initial_entry_confirmed")
        ):
            # Wenn der aktuelle Symbol-Initial-Entry aufgrund eines Permission-Errors geblockt ist,
            # keine weiteren Initial-Entry-Retries auf diesem Symbol ausführen.
            blocked_symbol = str(state.get("initial_entry_blocked_symbol") or "").upper()
            current_symbol = str(self.config.symbol or "").upper()
            if state.get("initial_entry_retry_blocked") and blocked_symbol and blocked_symbol == current_symbol:
                context.audit.log_event(
                    "fixed_cycle_initial_entry_retry_skipped_blocked_symbol",
                    strategy=self.name,
                    symbol=current_symbol,
                    blocked_symbol=blocked_symbol,
                )
                return []
            if self._has_open_initial_entry_orders(snapshot, runtime_state):
                state["initial_entry_submitted"] = True
                context.audit.log_event(
                    "fixed_cycle_initial_entry_skipped",
                    strategy=self.name,
                    reason="open_initial_orders_exist",
                )
                return []

            if not self._dynamic_symbol_entry_gate_allows_entry(runtime_state, context, "tick_retry"):
                return []
            self._maybe_update_symbol_from_best_coin(runtime_state, context, "tick_retry")

            retry_count = int(state.get("initial_entry_retry_count") or 0) + 1
            state["initial_entry_retry_count"] = retry_count
            context.audit.log_event(
                "fixed_cycle_initial_entry_retry",
                strategy=self.name,
                current_price=snapshot.current_price,
                retry_count=retry_count,
            )
            self._reset_initial_entry_reconcile_state(runtime_state, reset_submission_state=True)
            intents = self._build_entry_intents(snapshot, runtime_state, context)
            if intents:
                state["initial_entry_submitted"] = True
                context.audit.log_event(
                    "fixed_cycle_initial_entry_submitted",
                    strategy=self.name,
                    current_price=snapshot.current_price,
                    intent_count=len(intents),
                    retry_count=retry_count,
                )
                state["dynamic_entry_hold_initialized"] = False
                state.pop("next_dynamic_entry_allowed_at", None)
                self._set_final_exit_missing_block(
                    runtime_state, self.FINAL_EXIT_MISSING_FRESH_ENTRY_BLOCK_SEC
                )
            return intents

        if state.get("initial_entry_submitted") and not state.get("initial_structure_built"):
            return self._maybe_build_initial_structure_once(
                snapshot,
                runtime_state,
                context,
                purpose=None,
                source="tick",
                reason="tick_initial_entry_reconcile",
                rebuild_reason="initial_entry_complete_tick",
                allow_build=False,
            )

        if state.get("bot_state") == self.STATE_EXITED:
            return []

        if snapshot.long_qty <= 0 and snapshot.short_qty <= 0:
            if self._block_flat_restart_until_final_pnl(
                snapshot, runtime_state, context, reason="on_tick_flat_exit_state"
            ):
                return []
            state["bot_state"] = self.STATE_EXITED
            return []

        if snapshot.long_qty <= 0 or snapshot.short_qty <= 0:
            return self._maybe_refresh_structure(snapshot, runtime_state, context, reason="tick_partial_structure")

        if self._has_no_strategy_orders(snapshot):
            return self._maybe_refresh_structure(snapshot, runtime_state, context, reason="tick_missing_strategy_orders")

        return []

    def on_fill(
        self,
        fill_event: FillEvent,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent]:
        state = runtime_state.strategy_state
        state["bot_state"] = self.STATE_RECONCILING_AFTER_FILL
        metadata = fill_event.metadata or {}
        purpose = fill_event.purpose or ""
        if purpose in {self.LONG_ENTRY_PURPOSE, self.SHORT_ENTRY_PURPOSE}:
            state["initial_entry_submitted"] = True
            if purpose == self.LONG_ENTRY_PURPOSE and fill_event.status == "FILLED":
                state["initial_long_entry_reconciled"] = True
            if purpose == self.SHORT_ENTRY_PURPOSE and fill_event.status == "FILLED":
                state["initial_short_entry_reconciled"] = True
            context.audit.log_event(
                "fixed_cycle_fill_handling_started",
                strategy=self.name,
                fill=fill_event.to_dict(),
                bot_state=state["bot_state"],
            )
            if self.config.rest_poll_after_fill_ms > 0:
                time.sleep(self.config.rest_poll_after_fill_ms / 1000.0)
            refreshed_snapshot = (
                context.refresh_snapshot("fixed_cycle_post_fill_rest") if context.refresh_snapshot else snapshot
            )
            self._seed_initial_reference_if_missing(refreshed_snapshot, runtime_state)
            self._sync_state_from_snapshot(refreshed_snapshot, runtime_state)
            return self._maybe_build_initial_structure_once(
                refreshed_snapshot,
                runtime_state,
                context,
                purpose=purpose,
                source="fill",
                reason="initial_entry_fill_reconcile",
                rebuild_reason="initial_entry_complete",
            )
        if self._is_recovery_reload_purpose(purpose):
            self._handle_recovery_refill_fill(fill_event, snapshot, runtime_state, context)
            return []
        self._enrich_fill_event_for_confirmed_pnl(fill_event)
        try:
            self._audit_exit_pnl_summary(fill_event, runtime_state, context)
        except Exception as exc:  # pragma: no cover - audit must never block
            logger.warning(
                "exit_pnl_audit_failed_non_blocking",
                {
                    "error": str(exc),
                    "purpose": fill_event.purpose,
                    "client_order_id": fill_event.client_order_id,
                    "exchange_order_id": fill_event.exchange_order_id,
                    "exec_id": fill_event.exec_id,
                },
            )
        fill_type, cycle_index = self._classify_exit_fill_for_audit(fill_event)
        cycle_order_already_confirmed = False
        if fill_type == "cycle_short_tp":
            cycle_order_already_confirmed = self._cycle_order_confirmed(
                runtime_state,
                fill_event.exchange_order_id,
                fill_event.purpose,
            )
            if cycle_order_already_confirmed:
                _log_event(
                    "fixed_cycle_cycle_closed_pnl_already_confirmed_for_order",
                    {
                        "cycle_index": cycle_index,
                        "purpose": fill_event.purpose,
                        "client_order_id": fill_event.client_order_id,
                        "exchange_order_id": fill_event.exchange_order_id,
                        "exec_id": fill_event.exec_id,
                    },
                )
                self._remove_pending_cycle_closed_pnl_for_order(
                    runtime_state,
                    exchange_order_id=fill_event.exchange_order_id,
                    purpose=fill_event.purpose,
                )
            if (
                not cycle_order_already_confirmed
                and not self._has_confirmed_cycle_closed_pnl(fill_event, fill_type)
            ):
                event_name = "fixed_cycle_short_reduce_pnl_waiting_for_closed_pnl"
                blocks_cycle_advance = (
                    cycle_index > 0
                    and self._get_first_leg_cycle_role() == "short_reduce"
                    and self._get_second_leg_cycle_role() == "long_reduce"
                    and self._normalize_cycle_purpose(
                        fill_event.purpose,
                        {"cycle_index": cycle_index, **(fill_event.metadata or {})},
                    )
                    == self._normalize_cycle_purpose(
                        self._get_first_leg_purpose(cycle_index),
                        {
                            "cycle_index": cycle_index,
                            "cycle_role": self._get_first_leg_cycle_role(),
                        },
                    )
                )
                self._queue_pending_cycle_closed_pnl_fill(
                    fill_event,
                    runtime_state,
                    fill_type=fill_type,
                    cycle_index=cycle_index,
                )
                _log_event(
                    event_name,
                    {
                        "cycle_index": cycle_index,
                        "purpose": fill_event.purpose,
                        "client_order_id": fill_event.client_order_id,
                        "exchange_order_id": fill_event.exchange_order_id,
                        "exec_id": fill_event.exec_id,
                        "runtime_calculated_pnl": (fill_event.metadata or {}).get("runtime_calculated_pnl"),
                        "exec_pnl": (fill_event.metadata or {}).get("exec_pnl"),
                        "reason": (
                            "queue_closed_pnl_retry_blocking_cycle_advance"
                            if blocks_cycle_advance
                            else "queue_closed_pnl_retry_without_blocking_cycle_advance"
                        ),
                    },
                )
                context.audit.log_event(
                    event_name,
                    strategy=self.name,
                    cycle_index=cycle_index,
                    purpose=fill_event.purpose,
                    client_order_id=fill_event.client_order_id,
                    exchange_order_id=fill_event.exchange_order_id,
                    exec_id=fill_event.exec_id,
                )
        is_staged_second_leg = bool(metadata.get("is_staged_second_leg_tp"))
        is_normal_split_second_leg = bool(metadata.get("normal_cycle_second_leg_split"))
        normal_split_completed = False
        if is_staged_second_leg and metadata.get("second_leg_cycle_role") == self._get_second_leg_cycle_role():
            # Direction-neutrale Validation für gestagte Second-Leg-TPs
            expected = float(metadata.get("stage_expected_net") or 0.0)
            total_required = float(metadata.get("stage_required_net_total") or 0.0)
            actual, actual_source = self._extract_realized_fill_pnl(fill_event, fill_type)
            delta = actual - expected
            delta_pct = (delta / expected) if expected > 0 else 0.0
            filled_price = float(fill_event.exec_price or 0.0)
            filled_qty = float(fill_event.exec_qty or 0.0)

            logger.debug(
                "staged_second_leg_tp_fill_validation %s",
                {
                    "expected_profit_usdt": expected,
                    "actual_profit_usdt": actual,
                    "actual_source": actual_source,
                    "delta": delta,
                    "delta_pct": delta_pct,
                    "stage_index": metadata.get("stage_index"),
                    "stage_count": metadata.get("stage_count"),
                    "cycle_index": metadata.get("cycle_index"),
                },
            )
            _audit_calc(
                "staged_second_leg_tp_fill_validation",
                {
                    "cycle_index": metadata.get("cycle_index"),
                    "purpose": purpose,
                    "stage_index": metadata.get("stage_index"),
                    "stage_count": metadata.get("stage_count"),
                    "expected_profit_usdt": expected,
                    "actual_profit_usdt": actual,
                    "actual_source": actual_source,
                    "delta": delta,
                    "delta_pct": delta_pct,
                    "filled_price": filled_price,
                    "filled_qty": filled_qty,
                    "confirmed_pnl": getattr(fill_event, "confirmed_pnl", None),
                    "closed_pnl": metadata.get("closed_pnl"),
                    "exec_price": fill_event.exec_price,
                    "fee": metadata.get("fee"),
                    "order_id": fill_event.client_order_id,
                    "metadata": metadata,
                },
            )
            # Kumulative Stage-PnL pro Cycle führen
            cycle_key = str(metadata.get("cycle_index") or cycle_index or 0)
            realized_map = state.setdefault("staged_second_leg_tp_realized_net", {})
            total_before = float(realized_map.get(cycle_key) or 0.0)
            total_after = total_before + actual
            realized_map[cycle_key] = total_after

            filled_map = state.setdefault("staged_second_leg_tp_filled_stages", {})
            filled_list = list(filled_map.get(cycle_key) or [])
            stage_index = int(metadata.get("stage_index") or 0)
            if stage_index not in filled_list:
                filled_list.append(stage_index)
            filled_map[cycle_key] = filled_list

            remaining_required_net = max(total_required - total_after, 0.0) if total_required else 0.0
            logger.info(
                "staged_second_leg_tp_realized_updated",
                {
                    "cycle_index": metadata.get("cycle_index"),
                    "stage_index": stage_index,
                    "stage_count": metadata.get("stage_count"),
                    "expected_stage_net": expected,
                    "actual_stage_net": actual,
                    "realized_total_net": total_after,
                    "required_total_net": total_required,
                    "remaining_required_net": remaining_required_net,
                },
            )
            _audit_calc(
                "staged_second_leg_tp_realized_updated",
                {
                    "cycle_index": metadata.get("cycle_index"),
                    "stage_index": stage_index,
                    "stage_count": metadata.get("stage_count"),
                    "expected_stage_net": expected,
                    "actual_stage_net": actual,
                    "realized_total_net": total_after,
                    "required_total_net": total_required,
                    "remaining_required_net": remaining_required_net,
                },
            )

            # Cycle-Abschluss-Flag nur setzen, wenn alle Stages gefüllt oder Nettoprofit gedeckt ist
            all_stages_done = int(metadata.get("stage_count") or 0) > 0 and len(filled_list) >= int(
                metadata.get("stage_count") or 0
            )
            completed_by_pnl = total_required > 0 and total_after >= total_required - 1e-8
            if all_stages_done or completed_by_pnl:
                state["cycle_short_tp_filled"] = True
                logger.info(
                    "staged_second_leg_tp_completed",
                    {
                        "cycle_index": metadata.get("cycle_index"),
                        "stage_count": metadata.get("stage_count"),
                        "realized_total_net": total_after,
                        "required_total_net": total_required,
                    },
                )

        is_short_reduce_cover_leg = (
            isinstance(purpose, str)
            and "SHORT" in purpose
            and metadata.get("cycle_role") == "short_reduce"
            and self._get_second_leg_cycle_role() == "short_reduce"
        )
        if is_short_reduce_cover_leg:
            is_staged = bool(metadata.get("is_staged_second_leg_tp"))
            is_normal_split = bool(metadata.get("normal_cycle_second_leg_split"))
            expected = 0.0
            if not is_staged and not is_normal_split:
                expected = float(state.get("last_expected_short_tp_net") or 0.0)

            if (
                not is_staged
                and not is_normal_split
                and expected > PNL_VALIDATION_THRESHOLD_USDT
            ):
                actual, actual_source = self._extract_realized_fill_pnl(fill_event, fill_type)
                delta = actual - expected
                delta_pct = (delta / expected) if expected > 0 else 0.0
                filled_price = float(fill_event.exec_price or 0.0)
                filled_qty = float(fill_event.exec_qty or 0.0)
                expected_qty = float(state.get("last_short_tp_qty") or 0.0)
                validation_payload = {
                    "expected_profit_usdt": expected,
                    "actual_profit_usdt": actual,
                    "actual_source": actual_source,
                    "delta": delta,
                    "delta_pct": delta_pct,
                    "trigger_price": state.get("last_short_tp_trigger_price"),
                    "filled_price": filled_price,
                    "qty": filled_qty,
                    "cycle_index": metadata.get("cycle_index"),
                    "purpose": purpose,
                }

                logger.debug("short_reduce_cover_pnl_validation %s", validation_payload)
                _audit_calc(
                    "short_tp_fill_validation",
                    {
                        "cycle_index": metadata.get("cycle_index"),
                        "purpose": purpose,
                        "expected_profit_usdt": expected,
                        "actual_profit_usdt": actual,
                        "actual_source": actual_source,
                        "delta": delta,
                        "delta_pct": delta_pct,
                        "expected_trigger_price": state.get("last_short_tp_trigger_price"),
                        "filled_price": filled_price,
                        "expected_qty": expected_qty,
                        "filled_qty": filled_qty,
                        "confirmed_pnl": getattr(fill_event, "confirmed_pnl", None),
                        "closed_pnl": metadata.get("closed_pnl"),
                        "exec_price": fill_event.exec_price,
                        "fee": metadata.get("fee"),
                        "order_id": fill_event.client_order_id,
                        "metadata": metadata,
                    },
                    level=logging.DEBUG,
                )
                if abs(delta) > PNL_VALIDATION_THRESHOLD_USDT:
                    mismatch_payload = {
                        "expected": expected,
                        "actual": actual,
                        "delta": delta,
                        "delta_pct": delta_pct,
                        "threshold": PNL_VALIDATION_THRESHOLD_USDT,
                        "cycle_index": metadata.get("cycle_index"),
                        "trigger_price": state.get("last_short_tp_trigger_price"),
                        "filled_price": filled_price,
                        "qty": filled_qty,
                        "purpose": purpose,
                        "actual_source": actual_source,
                        "validation_scope": "long_primary_short_reduce_cover_leg",
                    }
                    logger.debug("short_tp_pnl_mismatch %s", mismatch_payload)
                    _audit_calc(
                        "short_tp_pnl_mismatch",
                        mismatch_payload,
                        level=logging.DEBUG,
                    )
        if fill_type == "cycle_long_reduce":
            cycle_order_already_confirmed = self._cycle_order_confirmed(
                runtime_state,
                fill_event.exchange_order_id,
                fill_event.purpose,
            )
            if cycle_order_already_confirmed:
                _log_event(
                    "fixed_cycle_cycle_closed_pnl_already_confirmed_for_order",
                    {
                        "cycle_index": cycle_index,
                        "purpose": fill_event.purpose,
                        "client_order_id": fill_event.client_order_id,
                        "exchange_order_id": fill_event.exchange_order_id,
                        "exec_id": fill_event.exec_id,
                    },
                )
                self._remove_pending_cycle_closed_pnl_for_order(
                    runtime_state,
                    exchange_order_id=fill_event.exchange_order_id,
                    purpose=fill_event.purpose,
                )
            elif self._has_confirmed_cycle_closed_pnl(fill_event, fill_type):
                try:
                    self._audit_exit_pnl_summary(fill_event, runtime_state, context)
                except Exception as exc:  # pragma: no cover - audit must never block
                    logger.warning(
                        "exit_pnl_reaudit_failed_non_blocking",
                        {
                            "error": str(exc),
                            "purpose": fill_event.purpose,
                            "client_order_id": fill_event.client_order_id,
                            "exchange_order_id": fill_event.exchange_order_id,
                            "exec_id": fill_event.exec_id,
                        },
                    )
            elif not cycle_order_already_confirmed:
                event_name = "fixed_cycle_long_reduce_pnl_waiting_for_closed_pnl"
                self._queue_pending_cycle_closed_pnl_fill(
                    fill_event,
                    runtime_state,
                    fill_type=fill_type,
                    cycle_index=cycle_index,
                )
                _log_event(
                    event_name,
                    {
                        "cycle_index": cycle_index,
                        "purpose": fill_event.purpose,
                        "client_order_id": fill_event.client_order_id,
                        "exchange_order_id": fill_event.exchange_order_id,
                        "exec_id": fill_event.exec_id,
                        "runtime_calculated_pnl": (fill_event.metadata or {}).get("runtime_calculated_pnl"),
                        "exec_pnl": (fill_event.metadata or {}).get("exec_pnl"),
                        "reason": "waiting_for_long_reduce_bybit_closed_pnl",
                    },
                )
                context.audit.log_event(
                    event_name,
                    strategy=self.name,
                    cycle_index=cycle_index,
                    purpose=fill_event.purpose,
                    client_order_id=fill_event.client_order_id,
                    exchange_order_id=fill_event.exchange_order_id,
                    exec_id=fill_event.exec_id,
                )
        self._advance_cycle_from_fill(fill_event, runtime_state, context)
        if (
            fill_event.status == "FILLED"
            and self._is_cycle_fill_purpose(fill_event.purpose)
        ):
            self._force_exit_rebuild_after_cycle_fill(runtime_state, fill_event)
        self._log_post_fill_next_action_decision(fill_event, snapshot, runtime_state)
        if fill_event.metadata.get("short_tp_fallback") and fill_event.status == "FILLED":
            fallback_state = self._get_short_tp_fallback_state(runtime_state)
            self._log_short_tp_fallback_event(
                "SHORT_TP_FALLBACK_FILLED",
                fallback_state,
                float(snapshot.current_price or fill_event.exec_price or 0.0),
                extra={
                    "client_order_id": fill_event.client_order_id,
                    "exchange_order_id": fill_event.exchange_order_id,
                },
            )
            reset_short_tp_fallback(fallback_state)
            self._store_short_tp_fallback_state(runtime_state, fallback_state)
            self._clear_short_tp_fallback_order_context(runtime_state)

        context.audit.log_event(
            "fixed_cycle_fill_handling_started",
            strategy=self.name,
            fill=fill_event.to_dict(),
            bot_state=state["bot_state"],
        )

        if self.config.rest_poll_after_fill_ms > 0:
            time.sleep(self.config.rest_poll_after_fill_ms / 1000.0)

        refreshed_snapshot = context.refresh_snapshot("fixed_cycle_post_fill_rest") if context.refresh_snapshot else snapshot
        self._seed_initial_reference_if_missing(refreshed_snapshot, runtime_state)
        self._sync_state_from_snapshot(refreshed_snapshot, runtime_state)
        state = runtime_state.strategy_state
        self._log_post_fill_next_action_decision(fill_event, refreshed_snapshot, runtime_state)

        fast_intents = self._fast_path_second_order(fill_event, refreshed_snapshot, runtime_state, context)
        old_exit_trigger_prices = self._collect_exit_trigger_prices_from_snapshot(refreshed_snapshot)
        self._log_realized_state(
            tag="fixed_cycle_fill_state",
            snapshot=refreshed_snapshot,
            runtime_state=runtime_state,
            stage="fill",
            reason=fill_event.purpose,
            old_exit_trigger_prices=old_exit_trigger_prices,
            new_exit_trigger_prices={},
            basket_tp_price=float(state.get("latest_tp_price") or 0.0),
        )

        rebuild_intents = self._rebuild_structure(refreshed_snapshot, runtime_state, context, reason="fill_reconcile")
        returned_intents = fast_intents + rebuild_intents

        # Wenn ein Rebuild nach Fill/Refill neue Basket-Exits setzt, muss der
        # nächste erwartete First-Leg-Cycle ebenfalls wieder aktiv sein.
        # Sonst steht der State zwar auf CYCLE_N_LONG_ADD, aber es existiert
        # keine echte Order dafür.
        next_required_purpose = str(state.get("next_required_purpose") or "").strip().upper()
        returned_or_active_purposes = {
            str(getattr(intent, "purpose", "") or "").strip().upper()
            for intent in returned_intents
        }
        returned_or_active_purposes.update(
            str(getattr(order, "purpose", "") or "").strip().upper()
            for order in [
                *getattr(refreshed_snapshot, "active_orders", []),
                *runtime_state.active_orders.values(),
            ]
            if getattr(order, "purpose", None)
            and not self._is_terminal_order_status(getattr(order, "status", None))
        )
        rebuilt_final_exits = any(
            str(getattr(intent, "purpose", "") or "").strip().upper()
            in {
                self._get_final_long_exit_purpose(),
                self._get_final_short_exit_purpose(),
            }
            for intent in returned_intents
        )

        if (
            rebuilt_final_exits
            and next_required_purpose.startswith("CYCLE_")
            and next_required_purpose.endswith("_LONG_ADD")
            and next_required_purpose not in returned_or_active_purposes
        ):
            cycle_index = 0
            parts = next_required_purpose.split("_")
            if len(parts) >= 3:
                try:
                    cycle_index = int(parts[1])
                except (TypeError, ValueError):
                    cycle_index = 0

            blocking_cycle = self._blocking_cycle_before_long_add(runtime_state, cycle_index)
            if blocking_cycle is not None:
                blocked_cycle_index, blocked_entry = blocking_cycle
                _log_event(
                    "fixed_cycle_fill_reconcile_long_add_rebuild_blocked",
                    {
                        "symbol": self.config.symbol,
                        "purpose": fill_event.purpose,
                        "next_required_purpose": next_required_purpose,
                        "cycle_index": cycle_index,
                        "blocked_cycle_index": blocked_cycle_index,
                        "blocked_entry": blocked_entry,
                        "active_cycle_index": state.get("active_cycle_index"),
                        "returned_intents": [intent.purpose for intent in returned_intents],
                    },
                )
            else:
                cycle_intent = self._build_cycle_long_add_intent(
                    refreshed_snapshot,
                    runtime_state,
                    context,
                    cycle_index=cycle_index,
                )
                if cycle_intent is not None:
                    self._annotate_post_refill_structure_intents(
                        runtime_state,
                        [cycle_intent],
                    )
                    returned_intents.append(cycle_intent)
                    _log_event(
                        "fixed_cycle_fill_reconcile_long_add_rebuild_triggered",
                        {
                            "symbol": self.config.symbol,
                            "purpose": fill_event.purpose,
                            "cycle_intent_purpose": cycle_intent.purpose,
                            "cycle_index": cycle_index,
                            "trigger_price": cycle_intent.trigger_price,
                            "qty": cycle_intent.qty,
                            "active_cycle_index": state.get("active_cycle_index"),
                            "next_required_purpose": next_required_purpose,
                        },
                    )
                else:
                    _log_event(
                        "fixed_cycle_fill_reconcile_long_add_rebuild_skipped",
                        {
                            "symbol": self.config.symbol,
                            "purpose": fill_event.purpose,
                            "next_required_purpose": next_required_purpose,
                            "cycle_index": cycle_index,
                            "active_cycle_index": state.get("active_cycle_index"),
                            "reason": "builder_returned_none",
                            "returned_intents": [intent.purpose for intent in returned_intents],
                        },
                    )

        _log_event(
            "fixed_cycle_fill_reconcile_completed",
            {
                "symbol": self.config.symbol,
                "purpose": fill_event.purpose,
                "exec_id": fill_event.exec_id,
                "exchange_order_id": fill_event.exchange_order_id,
                "client_order_id": fill_event.client_order_id,
                "bot_state": state.get("bot_state"),
                "returned_intent_count": len(returned_intents),
                "fast_intent_count": len(fast_intents),
                "rebuild_intent_count": len(rebuild_intents),
                "long_qty": refreshed_snapshot.long_qty,
                "short_qty": refreshed_snapshot.short_qty,
                "reason": "fill_reconcile",
            },
        )
        active_refill_purposes = self._collect_active_refill_order_purposes(
            refreshed_snapshot, runtime_state
        )
        _log_event(
            "fixed_cycle_refill_completion_post_rebuild_checkpoint",
            {
                "symbol": self.config.symbol,
                "refill_pending": bool(state.get("refill_pending")),
                "refill_in_progress": bool(state.get("refill_in_progress")),
                "refill_fills_complete": bool(state.get("refill_fills_complete")),
                "refill_completion_pending_reconcile": bool(
                    state.get("refill_completion_pending_reconcile")
                ),
                "active_refill_orders_count": len(active_refill_purposes),
                "active_refill_purposes": active_refill_purposes,
                "long_qty": refreshed_snapshot.long_qty,
                "short_qty": refreshed_snapshot.short_qty,
            },
        )
        post_refill_rebuild_needed = self._maybe_complete_refill_after_reconcile(
            refreshed_snapshot,
            runtime_state,
            context,
            reason="fill_reconcile",
        )
        if post_refill_rebuild_needed:
            post_refill_snapshot = runtime_state.last_snapshot or refreshed_snapshot
            post_refill_intents = self._rebuild_structure(
                post_refill_snapshot,
                runtime_state,
                context,
                reason="post_refill_normal_rebuild",
            )

            # Nach einem abgeschlossenen Refill muss nicht nur die Exit-Struktur
            # neu stehen, sondern auch der nächste erwartete Cycle-First-Leg.
            # _rebuild_structure() kann in der Post-Refill-Situation nur die
            # Basket-Exits zurückgeben. Wenn der Sequenz-State bereits auf
            # CYCLE_N_LONG_ADD steht, bauen wir diese Order hier explizit nach.
            next_required_purpose = str(state.get("next_required_purpose") or "").strip().upper()
            post_refill_existing_purposes = {
                str(getattr(intent, "purpose", "") or "").strip().upper()
                for intent in post_refill_intents
            }
            post_refill_existing_purposes.update(
                str(getattr(order, "purpose", "") or "").strip().upper()
                for order in [
                    *getattr(post_refill_snapshot, "active_orders", []),
                    *runtime_state.active_orders.values(),
                ]
                if getattr(order, "purpose", None)
                and not self._is_terminal_order_status(getattr(order, "status", None))
            )

            if (
                next_required_purpose.startswith("CYCLE_")
                and next_required_purpose.endswith("_LONG_ADD")
                and next_required_purpose not in post_refill_existing_purposes
            ):
                cycle_index = 0
                parts = next_required_purpose.split("_")
                if len(parts) >= 3:
                    try:
                        cycle_index = int(parts[1])
                    except (TypeError, ValueError):
                        cycle_index = 0

                blocking_cycle = self._blocking_cycle_before_long_add(runtime_state, cycle_index)
                if blocking_cycle is not None:
                    blocked_cycle_index, blocked_entry = blocking_cycle
                    _log_event(
                        "fixed_cycle_post_refill_long_add_rebuild_blocked",
                        {
                            "symbol": self.config.symbol,
                            "purpose": fill_event.purpose,
                            "next_required_purpose": next_required_purpose,
                            "cycle_index": cycle_index,
                            "blocked_cycle_index": blocked_cycle_index,
                            "blocked_entry": blocked_entry,
                            "active_cycle_index": state.get("active_cycle_index"),
                        },
                    )
                else:
                    cycle_intent = self._build_cycle_long_add_intent(
                        post_refill_snapshot,
                        runtime_state,
                        context,
                        cycle_index=cycle_index,
                    )
                    if cycle_intent is not None:
                        self._annotate_post_refill_structure_intents(
                            runtime_state,
                            [cycle_intent],
                        )
                        post_refill_intents.append(cycle_intent)
                        _log_event(
                            "fixed_cycle_post_refill_long_add_rebuild_triggered",
                            {
                                "symbol": self.config.symbol,
                                "purpose": fill_event.purpose,
                                "cycle_intent_purpose": cycle_intent.purpose,
                                "cycle_index": cycle_index,
                                "trigger_price": cycle_intent.trigger_price,
                                "qty": cycle_intent.qty,
                                "active_cycle_index": state.get("active_cycle_index"),
                                "next_required_purpose": next_required_purpose,
                            },
                        )
                    else:
                        _log_event(
                            "fixed_cycle_post_refill_long_add_rebuild_skipped",
                            {
                                "symbol": self.config.symbol,
                                "purpose": fill_event.purpose,
                                "next_required_purpose": next_required_purpose,
                                "cycle_index": cycle_index,
                                "active_cycle_index": state.get("active_cycle_index"),
                                "reason": "builder_returned_none",
                            },
                        )

            if post_refill_intents:
                returned_intents += post_refill_intents
                _log_event(
                    "fixed_cycle_post_refill_normal_rebuild_triggered",
                    {
                        "symbol": self.config.symbol,
                        "purpose": fill_event.purpose,
                        "post_refill_intent_count": len(post_refill_intents),
                        "post_refill_intents": [intent.purpose for intent in post_refill_intents],
                        "next_required_purpose": state.get("next_required_purpose"),
                        "active_cycle_index": state.get("active_cycle_index"),
                    },
                )
        return returned_intents

    def _log_post_fill_next_action_decision(
        self,
        fill_event: FillEvent,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> None:
        state = runtime_state.strategy_state
        metadata = fill_event.metadata or {}
        fill_cycle_index = int(metadata.get("cycle_index") or 0)
        fill_cycle_role = str(metadata.get("cycle_role") or "")
        bot_state = state.get("bot_state")
        long_qty = float(getattr(snapshot, "long_qty", 0.0) or 0.0)
        short_qty = float(getattr(snapshot, "short_qty", 0.0) or 0.0)
        cycle_waiting_for_short_tp = self._get_second_leg_waiting(state)
        short_tp_pending_cycle = self._get_second_leg_pending_cycle(state)
        refill_pending = bool(state.get("refill_pending"))
        refill_in_progress = bool(state.get("refill_in_progress"))
        last_refill_completed_cycle_index = int(state.get("last_refill_completed_cycle_index") or 0)
        completed_cycles = int(state.get("cycle_completed_count") or 0)
        cycles_since_last_refill = completed_cycles - last_refill_completed_cycle_index

        if state.get("emergency_flat_required"):
            expected_next_action = "emergency_flat"
        elif refill_pending or bot_state == self.STATE_REFILL_PENDING:
            expected_next_action = "refill"
        elif cycle_waiting_for_short_tp or short_tp_pending_cycle > 0:
            expected_next_action = "build_short_followup"
        elif cycles_since_last_refill >= 2:
            expected_next_action = "refill"
        elif long_qty > 0 and short_qty > 0:
            expected_next_action = "rebuild_basket_exits_or_next_cycle"
        elif long_qty <= 0 and short_qty <= 0:
            expected_next_action = "flat_cleanup_or_restart"
        else:
            expected_next_action = "partial_structure_recovery"

        _log_event(
            "fixed_cycle_post_fill_next_action_decision",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "fill_purpose": fill_event.purpose,
                "fill_status": fill_event.status,
                "fill_cycle_index": fill_cycle_index,
                "fill_cycle_role": fill_cycle_role,
                "bot_state": bot_state,
                "long_qty": long_qty,
                "short_qty": short_qty,
                "cycle_completed_count": completed_cycles,
                "cycle_pair_count": int(state.get("cycle_pair_count") or 0),
                "cycle_waiting_for_short_tp": cycle_waiting_for_short_tp,
                "short_tp_pending_cycle": short_tp_pending_cycle,
                "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
                "refill_pending": refill_pending,
                "refill_in_progress": refill_in_progress,
                "expected_next_action": expected_next_action,
                "last_refill_completed_cycle_index": last_refill_completed_cycle_index,
                "cycles_since_last_refill": cycles_since_last_refill,
            },
        )

    def _extract_realized_fill_pnl(
        self,
        fill_event: FillEvent,
        fill_type: str,
    ) -> tuple[float, str]:
        metadata = fill_event.metadata or {}

        def _first_usable(*candidates: tuple[str, Any]) -> tuple[float, str]:
            for source, value in candidates:
                if value is None:
                    continue
                try:
                    return float(value), source
                except (TypeError, ValueError):
                    continue
            return 0.0, ""

        if fill_type == "cycle_long_reduce":
            return _first_usable(
                ("confirmed_pnl", getattr(fill_event, "confirmed_pnl", None)),
                ("closed_pnl", metadata.get("closed_pnl")),
                ("confirmed_closed_pnl", metadata.get("confirmed_closed_pnl")),
                ("long_closed_pnl", metadata.get("long_closed_pnl")),
                ("long_reduce_closed_pnl", metadata.get("long_reduce_closed_pnl")),
                ("provisional_runtime_calculated_pnl", metadata.get("runtime_calculated_pnl")),
                ("provisional_exec_pnl", metadata.get("exec_pnl")),
            )
        if fill_type == "cycle_short_tp":
            return _first_usable(
                ("confirmed_pnl", getattr(fill_event, "confirmed_pnl", None)),
                ("short_closed_pnl", metadata.get("short_closed_pnl")),
                ("short_reduce_closed_pnl", metadata.get("short_reduce_closed_pnl")),
                ("closed_pnl", metadata.get("closed_pnl")),
                ("confirmed_closed_pnl", metadata.get("confirmed_closed_pnl")),
                ("provisional_runtime_calculated_pnl", metadata.get("runtime_calculated_pnl")),
                ("provisional_exec_pnl", metadata.get("exec_pnl")),
            )
        if fill_type in {"final_long_exit", "final_short_exit"}:
            return _first_usable(
                ("confirmed_pnl", getattr(fill_event, "confirmed_pnl", None)),
                ("closed_pnl", metadata.get("closed_pnl")),
                ("confirmed_closed_pnl", metadata.get("confirmed_closed_pnl")),
            )
        return _first_usable(
            ("confirmed_pnl", getattr(fill_event, "confirmed_pnl", None)),
            ("closed_pnl", metadata.get("closed_pnl")),
            ("confirmed_closed_pnl", metadata.get("confirmed_closed_pnl")),
            ("exec_pnl", metadata.get("exec_pnl")),
            ("runtime_calculated_pnl", metadata.get("runtime_calculated_pnl")),
        )

    def _merge_cycle_closed_pnl_metadata(
        self,
        fill_event: FillEvent,
        *,
        cycle_index: int,
        cycle_role: str,
        confirmed_closed_pnl: float | None,
        closed_qty: float | None = None,
        closed_avg_price: float | None = None,
        confirmed_pnl_updated_time: int | None = None,
        pnl_source: str | None = None,
    ) -> bool:
        metadata = dict(fill_event.metadata or {})
        updated = False

        metadata["cycle_index"] = int(metadata.get("cycle_index") or cycle_index or 0)
        metadata.setdefault("cycle_role", cycle_role or "long_reduce")

        def _assign(key: str, value: Any) -> None:
            nonlocal updated
            if value is None:
                return
            if metadata.get(key) != value:
                metadata[key] = value
                updated = True

        _assign("closed_pnl", confirmed_closed_pnl)
        _assign("confirmed_closed_pnl", confirmed_closed_pnl)
        if cycle_role == "long_reduce":
            _assign("long_closed_pnl", confirmed_closed_pnl)
            _assign("long_reduce_closed_pnl", confirmed_closed_pnl)
        elif cycle_role == "short_reduce":
            _assign("short_closed_pnl", confirmed_closed_pnl)
            _assign("short_reduce_closed_pnl", confirmed_closed_pnl)

        _assign("confirmed_closed_qty", closed_qty)
        _assign("confirmed_closed_avg_price", closed_avg_price)
        _assign("confirmed_closed_pnl_updated_time", confirmed_pnl_updated_time)
        if pnl_source:
            _assign("closed_pnl_source", pnl_source)
            _assign("pnl_source", pnl_source)

        if confirmed_closed_pnl is not None:
            if getattr(fill_event, "confirmed_pnl", None) != confirmed_closed_pnl:
                fill_event.confirmed_pnl = confirmed_closed_pnl
                updated = True

        if updated:
            fill_event.metadata = metadata
        return updated

    def _hydrate_cycle_fill_metadata_from_state(
        self,
        fill_event: FillEvent,
        runtime_state: RuntimeState,
        *,
        fill_type: str,
        cycle_index: int,
        ledger: dict[str, Any],
    ) -> bool:
        if fill_type not in {"cycle_long_reduce", "cycle_short_tp"} or cycle_index <= 0:
            return False

        if self._has_confirmed_cycle_closed_pnl(fill_event, fill_type):
            return False

        cycle_order_confirmed = self._cycle_order_confirmed(
            runtime_state,
            fill_event.exchange_order_id,
            fill_event.purpose,
        )
        if not cycle_order_confirmed:
            return False

        cycle_key = str(cycle_index)
        entries_key = "cycle_long_reduce_pnl" if fill_type == "cycle_long_reduce" else "cycle_short_tp_pnl"
        cycle_state = self._ensure_cycle_state(runtime_state)
        fill_map_key = "long_fills" if fill_type == "cycle_long_reduce" else "short_fills"
        fill_map = (cycle_state.get(fill_map_key) or {}).get(cycle_key) or {}
        confirmed_value = self._safe_float(fill_map.get("confirmed_closed_pnl"), None)
        if confirmed_value is None:
            confirmed_value = self._safe_float(ledger.get(entries_key, {}).get(cycle_key), None)

        if confirmed_value is None:
            return False

        closed_qty = self._safe_float(fill_map.get("confirmed_closed_qty"), None) if fill_map else None
        closed_avg_price = self._safe_float(fill_map.get("confirmed_closed_avg_price"), None) if fill_map else None
        updated_time = self._safe_int(fill_map.get("confirmed_closed_pnl_updated_time"), None) if fill_map else None
        source = (
            fill_map.get("pnl_source")
            or fill_map.get("closed_pnl_source")
            or "confirmed_order"
        )

        metadata_updated = self._merge_cycle_closed_pnl_metadata(
            fill_event,
            cycle_index=cycle_index,
            cycle_role="long_reduce" if fill_type == "cycle_long_reduce" else "short_reduce",
            confirmed_closed_pnl=float(confirmed_value),
            closed_qty=closed_qty,
            closed_avg_price=closed_avg_price,
            confirmed_pnl_updated_time=updated_time,
            pnl_source=source,
        )

        _log_event(
            "fixed_cycle_cycle_pnl_already_confirmed_dedupe_skip",
            {
                "cycle_index": cycle_index,
                "fill_type": fill_type,
                "exchange_order_id": fill_event.exchange_order_id,
                "client_order_id": fill_event.client_order_id,
                "exec_id": fill_event.exec_id,
                "confirmed_pnl": float(confirmed_value),
                "source": source,
                "metadata_updated": metadata_updated,
                "dedupe_key": f"{fill_event.exchange_order_id or ''}:{fill_event.purpose or ''}",
            },
        )
        return True

    def _enrich_fill_event_for_confirmed_pnl(self, fill_event: FillEvent) -> None:
        enrich_fill_for_confirmed_pnl(
            fill_event,
            strategy_name=self.name,
            direction=getattr(self, "_direction_config", None),
        )

    def _classify_exit_fill_for_audit(self, fill_event: FillEvent) -> tuple[str, int]:
        return classify_exit_fill_for_confirmed_pnl(
            fill_event.purpose or "",
            fill_event.metadata or {},
            direction=getattr(self, "_direction_config", None),
        )

    @staticmethod
    def _is_confirmed_cycle_pnl_source(source: str) -> bool:
        return source in {
            "confirmed_pnl",
            "closed_pnl",
            "confirmed_closed_pnl",
            "long_closed_pnl",
            "long_reduce_closed_pnl",
            "short_closed_pnl",
            "short_reduce_closed_pnl",
        }

    def _has_confirmed_cycle_closed_pnl(self, fill_event: FillEvent, fill_type: str) -> bool:
        metadata = fill_event.metadata or {}
        if getattr(fill_event, "confirmed_pnl", None) is not None:
            return True
        confirmed_keys = (
            "closed_pnl",
            "confirmed_closed_pnl",
            "short_closed_pnl",
            "short_reduce_closed_pnl",
            "long_closed_pnl",
            "long_reduce_closed_pnl",
        )
        return any(metadata.get(key) is not None for key in confirmed_keys)

    def _cycle_has_confirmed_pair_pnl(self, runtime_state: RuntimeState, cycle_index: int) -> bool:
        if cycle_index <= 0:
            return False
        ledger = (runtime_state.strategy_state.get("audit_pnl_ledger") or {})
        cycle_key = str(cycle_index)
        long_entries = ledger.get("cycle_long_reduce_pnl") or {}
        short_entries = ledger.get("cycle_short_tp_pnl") or {}
        return cycle_key in long_entries and cycle_key in short_entries

    def _queue_pending_cycle_closed_pnl_fill(
        self,
        fill_event: FillEvent,
        runtime_state: RuntimeState,
        *,
        fill_type: str,
        cycle_index: int,
    ) -> None:
        state = runtime_state.strategy_state
        queue = state.setdefault("pending_cycle_closed_pnl_fills", [])
        fill_dict = fill_event.to_dict()
        fill_symbol = self._active_trade_symbol(runtime_state.last_snapshot, runtime_state, fill_event=fill_event)
        fill_dict["symbol"] = fill_symbol
        fill_metadata = dict(fill_dict.get("metadata") or {})
        fill_metadata.setdefault("symbol", fill_symbol)
        fill_dict["metadata"] = fill_metadata
        cycle_queue_key: str | None = None
        if fill_type in {"cycle_long_reduce", "cycle_short_tp"}:
            queue_key_parts = []
            if fill_event.exchange_order_id:
                queue_key_parts.append(str(fill_event.exchange_order_id))
            elif fill_event.client_order_id:
                queue_key_parts.append(str(fill_event.client_order_id))
            if fill_event.purpose:
                queue_key_parts.append(str(fill_event.purpose))
            if queue_key_parts:
                cycle_queue_key = ":".join(queue_key_parts)
        queue_key = (
            cycle_queue_key
            or str(fill_event.exec_id or "").strip()
            or str(fill_event.exchange_order_id or "").strip()
            or str(fill_event.client_order_id or "").strip()
            or f"{fill_event.purpose}:{fill_event.exec_price}:{fill_event.exec_qty}"
        )
        now = _current_time_ms()
        for entry in queue:
            if str(entry.get("queue_key") or "") == queue_key:
                existing_fill = dict(entry.get("fill") or {})
                existing_fill.update(fill_dict)
                entry["fill"] = existing_fill
                entry.setdefault("first_seen_ts", entry.get("first_seen_ts", now))
                entry["last_try_ts"] = now
                entry["cycle_index"] = cycle_index
                entry["fill_type"] = fill_type
                return
        queue.append(
            {
                "queue_key": queue_key,
                "fill_type": fill_type,
                "cycle_index": cycle_index,
                "fill": fill_dict,
                "first_seen_ts": now,
                "next_attempt_ts": now + CONFIRMED_CLOSED_PNL_RETRY_INITIAL_DELAY_MS,
                "attempt_count": 0,
            }
        )
        if len(queue) > 50:
            del queue[:-50]

    def _cycle_pending_queue_key(
        self,
        *,
        exchange_order_id: str | None,
        client_order_id: str | None,
        purpose: str | None,
    ) -> str | None:
        parts: list[str] = []
        if exchange_order_id:
            parts.append(str(exchange_order_id))
        elif client_order_id:
            parts.append(str(client_order_id))
        if purpose:
            parts.append(str(purpose))
        return ":".join(parts) if parts else None

    def _queue_key_from_payload(self, payload: dict[str, Any]) -> str | None:
        fill = payload.get("fill") or {}
        return self._cycle_pending_queue_key(
            exchange_order_id=str(fill.get("exchange_order_id") or ""),
            client_order_id=str(fill.get("client_order_id") or ""),
            purpose=str(fill.get("purpose") or ""),
        )

    def _cycle_order_confirmed(self, runtime_state: RuntimeState, exchange_order_id: str | None, purpose: str | None) -> bool:
        if not exchange_order_id or not purpose:
            return False
        dedupe_key = f"{exchange_order_id}:{purpose}"
        processed = runtime_state.strategy_state.get("processed_confirmed_order_keys") or []
        if dedupe_key in processed:
            return True
        return self._confirmed_history_file_has_dedupe_key(dedupe_key)

    def _confirmed_history_file_has_dedupe_key(self, dedupe_key: str) -> bool:
        if not dedupe_key:
            return False
        path = confirmed_order_pnl_history_path
        if not path.exists():
            return False
        try:
            lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
        except OSError:
            return False
        for line in lines[-1000:]:
            if not line.strip():
                continue
            try:
                payload = json.loads(line)
            except json.JSONDecodeError:
                continue
            existing_key = str(payload.get("dedupe_key") or "").strip()
            if not existing_key:
                existing_key = f"{payload.get('exchange_order_id')}:{payload.get('purpose')}"
            if existing_key == dedupe_key:
                return True
        return False

    def _confirmed_history_has_purpose(
        self,
        runtime_state: RuntimeState,
        purpose: str,
        *,
        exchange_order_id: str | None = None,
    ) -> bool:
        normalized_purpose = str(purpose or "").strip().upper()
        if not normalized_purpose:
            return False
        if exchange_order_id and self._cycle_order_confirmed(
            runtime_state,
            exchange_order_id,
            normalized_purpose,
        ):
            return True
        path = confirmed_order_pnl_history_path
        if not path.exists():
            return False
        trade_block_id = self._resolve_active_trade_block_id(runtime_state.strategy_state)
        try:
            lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
        except OSError:
            return False
        for line in lines[-1000:]:
            if not line.strip():
                continue
            try:
                payload = json.loads(line)
            except json.JSONDecodeError:
                continue
            if str(payload.get("purpose") or "").upper() != normalized_purpose:
                continue
            if exchange_order_id and str(payload.get("exchange_order_id") or "") != str(exchange_order_id):
                continue
            if trade_block_id and str(payload.get("trade_block_id") or "") not in {
                str(trade_block_id),
                "unknown",
            }:
                continue
            return True
        return False

    def _reconcile_processed_cycle_purposes_confirmed_history(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> None:
        state = runtime_state.strategy_state
        processed = list(state.get("processed_cycle_purposes") or [])
        if not processed:
            return
        stale_purposes: list[str] = []
        for purpose in processed:
            normalized = str(purpose or "").strip().upper()
            if not purpose_requires_confirmed_history_row(normalized):
                continue
            if self._confirmed_history_has_purpose(runtime_state, normalized):
                continue
            stale_purposes.append(normalized)
        if not stale_purposes:
            return
        _log_warning_event(
            "fixed_cycle_processed_purpose_missing_confirmed_history",
            {
                "stale_purposes": stale_purposes,
                "processed_cycle_purposes": processed,
                "trade_block_id": state.get("trade_block_id"),
                "last_trade_block_id": state.get("last_trade_block_id"),
            },
        )
        queue = state.setdefault("pending_cycle_closed_pnl_fills", [])
        for purpose in stale_purposes:
            backfilled = self._attempt_confirmed_history_backfill_for_purpose(
                runtime_state,
                context,
                purpose=purpose,
            )
            if backfilled:
                continue
            processed_set = {
                str(item or "").upper() for item in (state.get("processed_cycle_purposes") or [])
            }
            if purpose in processed_set:
                processed_set.discard(purpose)
                state["processed_cycle_purposes"] = sorted(processed_set)

    def _attempt_confirmed_history_backfill_for_purpose(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        purpose: str,
    ) -> bool:
        normalized_purpose = str(purpose or "").strip().upper()
        if not normalized_purpose or self._confirmed_history_has_purpose(runtime_state, normalized_purpose):
            return True
        pending = runtime_state.strategy_state.get("pending_cycle_closed_pnl_fills") or []
        for payload in pending:
            fill = dict(payload.get("fill") or {})
            if str(fill.get("purpose") or "").upper() != normalized_purpose:
                continue
            fill_event = self._pending_cycle_fill_from_payload(payload)
            self._enrich_fill_event_for_confirmed_pnl(fill_event)
            try:
                self._audit_exit_pnl_summary(fill_event, runtime_state, context)
            except Exception:
                return False
            return self._confirmed_history_has_purpose(
                runtime_state,
                normalized_purpose,
                exchange_order_id=fill_event.exchange_order_id,
            )
        managed_order = self._find_filled_managed_order_for_purpose(runtime_state, normalized_purpose)
        if managed_order is None:
            return False
        fill_event = FillEvent(
            exchange_order_id=str(managed_order.exchange_order_id or ""),
            client_order_id=managed_order.client_order_id,
            side=str(managed_order.side or ""),
            purpose=str(managed_order.purpose or normalized_purpose),
            exec_qty=float(managed_order.qty or 0.0),
            exec_price=float(managed_order.price or 0.0),
            order_type=str(managed_order.order_type or "Limit"),
            reduce_only=bool(managed_order.reduce_only),
            status="FILLED",
            metadata=dict(managed_order.metadata or {}),
        )
        self._enrich_fill_event_for_confirmed_pnl(fill_event)
        try:
            self._audit_exit_pnl_summary(fill_event, runtime_state, context)
        except Exception:
            return False
        return self._confirmed_history_has_purpose(
            runtime_state,
            normalized_purpose,
            exchange_order_id=fill_event.exchange_order_id,
        )

    def _find_filled_managed_order_for_purpose(
        self,
        runtime_state: RuntimeState,
        purpose: str,
    ) -> ManagedOrder | None:
        normalized_purpose = str(purpose or "").strip().upper()
        snapshot = runtime_state.last_snapshot
        candidates: list[ManagedOrder] = []
        for order in runtime_state.active_orders.values():
            candidates.append(order)
        if snapshot is not None:
            candidates.extend(snapshot.active_orders)
        for order in candidates:
            order_purpose = str(order.purpose or "").strip().upper()
            if not order_purpose:
                recovered = recover_purpose_from_client_order_id(
                    str(order.client_order_id or ""),
                    self.name,
                )
                order_purpose = recovered.upper()
            if order_purpose != normalized_purpose:
                continue
            if str(order.status or "").upper() in {"FILLED", "PROCESSED"}:
                return order
        return None

    def _remove_pending_cycle_closed_pnl_for_order(
        self,
        runtime_state: RuntimeState,
        *,
        exchange_order_id: str | None,
        purpose: str | None,
    ) -> None:
        key = self._cycle_pending_queue_key(
            exchange_order_id=exchange_order_id,
            client_order_id=None,
            purpose=purpose,
        )
        if not key:
            return
        queue = runtime_state.strategy_state.get("pending_cycle_closed_pnl_fills") or []
        filtered = [
            entry
            for entry in queue
            if str(entry.get("queue_key") or "") != key
        ]
        if len(filtered) != len(queue):
            runtime_state.strategy_state["pending_cycle_closed_pnl_fills"] = filtered

    def _pending_cycle_fill_from_payload(self, payload: dict[str, Any]) -> FillEvent:
        fill = dict(payload.get("fill") or {})
        occurred_at_raw = fill.get("occurred_at")
        occurred_at = (
            datetime.fromisoformat(occurred_at_raw)
            if isinstance(occurred_at_raw, str) and occurred_at_raw
            else datetime.now(timezone.utc)
        )
        event = FillEvent(
            exchange_order_id=str(fill.get("exchange_order_id") or ""),
            client_order_id=fill.get("client_order_id"),
            side=str(fill.get("side") or ""),
            purpose=str(fill.get("purpose") or ""),
            exec_qty=float(fill.get("exec_qty") or 0.0),
            exec_price=float(fill.get("exec_price") or 0.0),
            order_type=str(fill.get("order_type") or ""),
            reduce_only=bool(fill.get("reduce_only")),
            status=str(fill.get("status") or ""),
            cumulative_qty=fill.get("cumulative_qty"),
            incremental_qty=fill.get("incremental_qty"),
            exec_id=fill.get("exec_id"),
            metadata=dict(fill.get("metadata") or {}),
            occurred_at=occurred_at,
        )
        payload_symbol = str(fill.get("symbol") or "").strip()
        if payload_symbol and not event.metadata.get("symbol"):
            event.metadata["symbol"] = payload_symbol
        confirmed_pnl = (fill.get("metadata") or {}).get("confirmed_closed_pnl")
        if confirmed_pnl is not None:
            event.confirmed_pnl = confirmed_pnl
        return event

    def _retry_pending_cycle_closed_pnl_fills(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        _reconcile_depth: int = 0,
    ) -> None:
        state = runtime_state.strategy_state
        pending = list(state.get("pending_cycle_closed_pnl_fills") or [])
        if not pending and _reconcile_depth == 0:
            self._reconcile_processed_cycle_purposes_confirmed_history(runtime_state, context)
            return
        if not pending:
            return
        remaining: list[dict[str, Any]] = []
        resolved_keys: set[str] = set()
        now = _current_time_ms()
        for payload in pending:
            next_attempt = payload.get("next_attempt_ts", payload.get("first_seen_ts", now))
            if now < next_attempt:
                remaining.append(payload)
                continue
            first_seen = payload.get("first_seen_ts", now)
            attempt_count = payload.get("attempt_count", 0) + 1
            payload["attempt_count"] = attempt_count
            payload["last_try_ts"] = now
            payload["next_attempt_ts"] = now + CONFIRMED_CLOSED_PNL_RETRY_INTERVAL_MS
            age_ms = now - first_seen
            log_metadata = {
                "queue_key": payload.get("queue_key"),
                "exchange_order_id": payload.get("fill", {}).get("exchange_order_id"),
                "client_order_id": payload.get("fill", {}).get("client_order_id"),
                "purpose": payload.get("fill", {}).get("purpose"),
                "cycle_index": payload.get("cycle_index"),
                "attempt_count": attempt_count,
                "age_seconds": round(age_ms / 1000, 1),
            }
            if age_ms >= CONFIRMED_CLOSED_PNL_FINAL_WARNING_MS and not payload.get("final_warning_logged"):
                warning_meta = dict(log_metadata)
                warning_meta["delay_level"] = "final"
                _log_event("fixed_cycle_closed_pnl_wait_exceeded_expected_delay", warning_meta)
                payload["final_warning_logged"] = True
            elif age_ms >= CONFIRMED_CLOSED_PNL_WARNING_MS and not payload.get("warning_logged"):
                warning_meta = dict(log_metadata)
                warning_meta["delay_level"] = "warning"
                _log_event("fixed_cycle_closed_pnl_wait_exceeded_expected_delay", warning_meta)
                payload["warning_logged"] = True
            _log_event("fixed_cycle_closed_pnl_retry_attempt", log_metadata)
            fill_event = self._pending_cycle_fill_from_payload(payload)
            fill_symbol = self._active_trade_symbol(
                runtime_state.last_snapshot,
                runtime_state,
                fill_event=fill_event,
                payload=payload,
            )
            if fill_symbol and fill_symbol != str(self.config.symbol or "").upper():
                _log_event(
                    "fixed_cycle_closed_pnl_retry_uses_fill_symbol",
                    {
                        **log_metadata,
                        "fill_symbol": fill_symbol,
                        "config_symbol": str(self.config.symbol or "").upper(),
                    },
                )
            try:
                self._audit_exit_pnl_summary(fill_event, runtime_state, context)
            except Exception:
                remaining.append(payload)
                continue
            fill_type = str(payload.get("fill_type") or "")
            if fill_type not in {"cycle_short_tp", "cycle_long_reduce"}:
                continue
            if not self._has_confirmed_cycle_closed_pnl(fill_event, fill_type):
                if age_ms >= CONFIRMED_CLOSED_PNL_PROVISIONAL_FALLBACK_MS:
                    self._maybe_write_provisional_confirmed_cycle_order_pnl(
                        fill_event,
                        runtime_state,
                        fill_type=fill_type,
                        cycle_index=int(payload.get("cycle_index") or 0),
                        reason="closed_pnl_retry_provisional_fallback",
                    )
                if not self._has_confirmed_cycle_closed_pnl(fill_event, fill_type):
                    updated_payload = dict(payload)
                    updated_payload["fill"] = fill_event.to_dict()
                    remaining.append(updated_payload)
                    continue
            exchange_order_id = fill_event.exchange_order_id
            purpose = fill_event.purpose
            self._remove_pending_cycle_closed_pnl_for_order(
                runtime_state,
                exchange_order_id=exchange_order_id,
                purpose=purpose,
            )
            resolved_key = self._cycle_pending_queue_key(
                exchange_order_id=exchange_order_id,
                client_order_id=fill_event.client_order_id,
                purpose=purpose,
            )
            if resolved_key:
                resolved_keys.add(resolved_key)
                self._try_complete_cycle_pair_after_confirmed_pnl(
                    runtime_state,
                    int(payload.get("cycle_index") or 0),
                    purpose,
                )
        filtered_remaining = []
        for entry in remaining:
            queue_key = self._queue_key_from_payload(entry)
            if queue_key and queue_key in resolved_keys:
                continue
            filtered_remaining.append(entry)
        state["pending_cycle_closed_pnl_fills"] = filtered_remaining
        if _reconcile_depth == 0:
            self._reconcile_processed_cycle_purposes_confirmed_history(runtime_state, context)
        self._recompute_cycle_pnl_ledger_totals(ledger)

    @staticmethod
    def _repair_vwap_fill_entry(entry: dict[str, Any]) -> dict[str, Any]:
        """Fix doubled total_qty when commit and advance both counted the same fill."""
        if not entry:
            return entry
        repaired = dict(entry)
        weighted_price_sum = float(repaired.get("weighted_price_sum") or 0.0)
        fill_qty = float(repaired.get("qty") or repaired.get("exec_qty") or 0.0)
        total_qty = float(repaired.get("total_qty") or 0.0)
        price = float(repaired.get("price") or 0.0)

        if fill_qty <= 0:
            return repaired

        if weighted_price_sum > 0 and total_qty > fill_qty * 1.001:
            repaired["total_qty"] = fill_qty
            repaired["avg_price"] = weighted_price_sum / fill_qty
            repaired["price"] = float(repaired["avg_price"])
            return repaired

        if weighted_price_sum > 0:
            expected_avg = weighted_price_sum / fill_qty
            if price > 0 and price < expected_avg * 0.75:
                repaired["avg_price"] = expected_avg
                repaired["price"] = expected_avg
        return repaired

    def _recompute_cycle_pnl_ledger_totals(self, ledger: dict[str, Any]) -> None:
        cycle_long_reduce_totals: dict[str, float] = {}
        cycle_short_tp_totals: dict[str, float] = {}
        for entry_key, entry in (ledger.get("cycle_pnl_entries") or {}).items():
            try:
                fill_type, cycle_key, _ = str(entry_key).split(":", 2)
            except ValueError:
                continue
            pnl = float((entry or {}).get("pnl") or 0.0)
            if fill_type == "cycle_long_reduce":
                cycle_long_reduce_totals[cycle_key] = (
                    cycle_long_reduce_totals.get(cycle_key, 0.0) + pnl
                )
            elif fill_type == "cycle_short_tp":
                cycle_short_tp_totals[cycle_key] = (
                    cycle_short_tp_totals.get(cycle_key, 0.0) + pnl
                )
        ledger["cycle_long_reduce_pnl"] = cycle_long_reduce_totals
        ledger["cycle_short_tp_pnl"] = cycle_short_tp_totals

        cycle_net = sum(cycle_long_reduce_totals.values()) + sum(cycle_short_tp_totals.values())
        final_exit_net = sum(
            float(value)
            for value in (
                ledger.get("final_long_exit_pnl"),
                ledger.get("final_short_exit_pnl"),
            )
            if value is not None
        )
        ledger["total_realized_pnl"] = cycle_net + final_exit_net

    def _get_short_tp_relief_state(self, runtime_state: RuntimeState) -> dict[str, Any]:
        state = runtime_state.strategy_state
        relief = state.setdefault(
            "short_tp_relief_state",
            {
                "carry_loss_by_trade_block": {},
                "cumulative_carry_loss": 0.0,
                "applied_relief_keys_by_trade_block": {},
                "cycle_records": [],
            },
        )
        relief.setdefault("carry_loss_by_trade_block", {})
        relief.setdefault("cumulative_carry_loss", 0.0)
        relief.setdefault("applied_relief_keys_by_trade_block", {})
        relief.setdefault("cycle_records", [])
        return relief

    def _get_short_tp_relief_carry_loss_usdt(self, runtime_state: RuntimeState | None) -> float:
        if (
            not runtime_state
            or not getattr(self.config, "cycle_short_tp_relief_enabled", False)
            or str(getattr(self.config, "strategy_side", "") or "").lower() != "long"
        ):
            return 0.0
        state = runtime_state.strategy_state
        trade_block_id = str(state.get("trade_block_id") or "")
        if not trade_block_id:
            return 0.0
        relief = state.get("short_tp_relief_state") or {}
        by_block = relief.get("carry_loss_by_trade_block") or {}
        return float(by_block.get(trade_block_id) or 0.0)

    def _get_effective_pending_cycle_loss_usdt(self, runtime_state: RuntimeState | None) -> float:
        if not runtime_state:
            return 0.0
        state = runtime_state.strategy_state
        base_pending = float(state.get("pending_cycle_loss_usdt") or 0.0)
        carry = self._get_short_tp_relief_carry_loss_usdt(runtime_state)
        return base_pending + carry

    def _short_tp_relief_build_applied_key(
        self,
        *,
        trade_block_id: str,
        cycle_index: int,
        purpose: str,
        capped_short_reduce_price: float,
        short_reduce_qty: float,
        order_id: str | None = None,
    ) -> str:
        normalized_purpose = str(purpose or "").upper()
        if order_id:
            return f"{trade_block_id}|order:{order_id}"
        return (
            f"{trade_block_id}|cycle:{cycle_index}|{normalized_purpose}|"
            f"cap:{float(capped_short_reduce_price):.8f}|qty:{float(short_reduce_qty):.8f}"
        )

    def _short_tp_relief_register_carry_loss(
        self,
        runtime_state: RuntimeState,
        *,
        trade_block_id: str,
        applied_key: str,
        uncovered_loss: float,
        record: dict[str, Any],
    ) -> tuple[float, bool]:
        relief = self._get_short_tp_relief_state(runtime_state)
        applied_by_block: dict[str, dict[str, bool]] = relief.setdefault(
            "applied_relief_keys_by_trade_block", {}
        )
        block_applied: dict[str, bool] = applied_by_block.setdefault(trade_block_id, {})
        by_block: dict[str, float] = relief.setdefault("carry_loss_by_trade_block", {})
        cumulative = float(by_block.get(trade_block_id) or 0.0)
        if block_applied.get(applied_key):
            return cumulative, False
        block_applied[applied_key] = True
        cumulative = cumulative + float(uncovered_loss or 0.0)
        by_block[trade_block_id] = cumulative
        relief["cumulative_carry_loss"] = float(
            sum(float(value or 0.0) for value in by_block.values())
        )
        records: list[dict[str, Any]] = relief.setdefault("cycle_records", [])
        records.append(dict(record))
        return cumulative, True

    def _apply_live_short_tp_relief(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        intents: list[StrategyIntent],
    ) -> list[StrategyIntent]:
        if not intents:
            return intents
        if not getattr(self.config, "cycle_short_tp_relief_enabled", False):
            return intents
        if str(getattr(self.config, "strategy_side", "") or "").lower() != "long":
            return intents

        state = runtime_state.strategy_state
        trade_block_id = str(state.get("trade_block_id") or "")
        if not trade_block_id:
            return intents

        start_cycle_index = int(
            getattr(self.config, "cycle_short_tp_relief_start_cycle_index", 0) or 0
        )
        max_distance_pct = float(
            getattr(
                self.config,
                "cycle_short_tp_relief_max_distance_pct_from_long_fill",
                0.0,
            )
            or 0.0
        )
        carry_enabled = bool(
            getattr(
                self.config,
                "cycle_short_tp_relief_carry_uncovered_loss_to_exit",
                True,
            )
        )
        if max_distance_pct <= 0:
            return intents

        updated: list[StrategyIntent] = []
        for intent in intents:
            purpose = str(getattr(intent, "purpose", "") or "")
            purpose_upper = purpose.upper()
            if not purpose_upper.startswith("CYCLE_") or "SHORT_REDUCE" not in purpose_upper:
                updated.append(intent)
                continue

            metadata = dict(getattr(intent, "metadata", {}) or {})
            cycle_index = int(metadata.get("cycle_index") or 0)
            if cycle_index <= 0:
                match = re.match(r"^CYCLE_(\d+)_", purpose_upper)
                if match:
                    try:
                        cycle_index = int(match.group(1))
                    except (TypeError, ValueError):
                        cycle_index = 0
            if cycle_index < start_cycle_index or cycle_index <= 0:
                updated.append(intent)
                continue

            # Resolve prices and quantities with conservative guards.
            long_fill_price = float(
                metadata.get("first_leg_fill_price")
                or metadata.get("long_fill_price")
                or self._get_first_leg_fill_price(runtime_state, cycle_index)
                or 0.0
            )
            normal_short_reduce_price = float(
                getattr(intent, "trigger_price", None)
                or metadata.get("trigger_price")
                or metadata.get("trigger_price_normalized")
                or metadata.get("raw_trigger_price")
                or getattr(intent, "price", None)
                or 0.0
            )
            short_avg_price = float(
                metadata.get("short_entry_price")
                or getattr(snapshot, "short_avg", 0.0)
                or state.get("short_avg")
                or 0.0
            )
            short_reduce_qty = float(
                getattr(intent, "qty", None)
                or metadata.get("short_qty")
                or metadata.get("qty")
                or 0.0
            )
            pending_cycle_loss_usdt = float(state.get("pending_cycle_loss_usdt") or 0.0)
            target_profit_usdt = float(self.config.target_profit_usdt or 0.0)
            required_profit = max(pending_cycle_loss_usdt + target_profit_usdt, 0.0)

            if (
                long_fill_price <= 0
                or normal_short_reduce_price <= 0
                or short_avg_price <= 0
                or short_reduce_qty <= 0
            ):
                updated.append(intent)
                continue

            capped_price_theoretical = long_fill_price * (1.0 - max_distance_pct / 100.0)
            # Relief greift nur, wenn der normale Short-TP tiefer liegt als der Cap.
            if normal_short_reduce_price + 1e-12 >= capped_price_theoretical:
                updated.append(intent)
                continue

            uncovered_loss = max(
                short_reduce_qty * (capped_price_theoretical - normal_short_reduce_price),
                0.0,
            )
            if uncovered_loss <= 0:
                updated.append(intent)
                continue

            capped_price_normalized = self._normalize_price(
                capped_price_theoretical, runtime_state
            )
            intent.trigger_price = capped_price_normalized
            metadata["trigger_price"] = capped_price_normalized
            metadata["raw_trigger_price"] = capped_price_normalized

            cumulative_carry_loss = 0.0
            newly_applied = False
            if carry_enabled:
                applied_key = self._short_tp_relief_build_applied_key(
                    trade_block_id=trade_block_id,
                    cycle_index=cycle_index,
                    purpose=purpose,
                    capped_short_reduce_price=capped_price_normalized,
                    short_reduce_qty=short_reduce_qty,
                    order_id=str(
                        metadata.get("order_id")
                        or metadata.get("client_order_id")
                        or ""
                    )
                    or None,
                )
                record = {
                    "cycle_index": cycle_index,
                    "trade_block_id": trade_block_id,
                    "purpose": purpose,
                    "normal_short_reduce_price": normal_short_reduce_price,
                    "capped_short_reduce_price": capped_price_normalized,
                    "short_reduce_qty": short_reduce_qty,
                    "required_profit": required_profit,
                    "uncovered_loss": uncovered_loss,
                }
                cumulative_carry_loss, newly_applied = self._short_tp_relief_register_carry_loss(
                    runtime_state,
                    trade_block_id=trade_block_id,
                    applied_key=applied_key,
                    uncovered_loss=uncovered_loss,
                    record=record,
                )

            effective_pending = self._get_effective_pending_cycle_loss_usdt(runtime_state)
            metadata.update(
                {
                    "cycle_short_tp_relief_enabled": True,
                    "short_tp_relief_cap_applied": True,
                    "normal_short_reduce_price": normal_short_reduce_price,
                    "capped_short_reduce_price": capped_price_normalized,
                    "max_short_reduce_distance_pct_from_long_fill": max_distance_pct,
                    "uncovered_loss": uncovered_loss,
                    "cumulative_carry_loss": cumulative_carry_loss,
                    "carry_uncovered_loss_to_exit": carry_enabled,
                    "effective_pending_cycle_loss_usdt": effective_pending,
                }
            )
            if carry_enabled and uncovered_loss > 0 and not newly_applied:
                metadata["short_tp_relief_carry_already_applied"] = True

            intent.metadata = metadata
            updated.append(intent)

        return updated

    def _record_cycle_pnl_entry(
        self,
        ledger: dict[str, Any],
        *,
        fill_type: str,
        cycle_index: int,
        fill_event: FillEvent,
        pnl: float,
        pnl_source: str,
    ) -> None:
        cycle_entries = ledger.setdefault("cycle_pnl_entries", {})
        order_key = (
            str(fill_event.exchange_order_id or "").strip()
            or str(fill_event.client_order_id or "").strip()
            or str(fill_event.exec_id or "").strip()
            or f"{fill_event.purpose}:{fill_event.exec_price}:{fill_event.exec_qty}"
        )
        entry_key = f"{fill_type}:{cycle_index}:{order_key}"
        is_confirmed = self._is_confirmed_cycle_pnl_source(pnl_source)
        if fill_type in {"cycle_long_reduce", "cycle_short_tp"} and not is_confirmed:
            _log_event(
                "fixed_cycle_unconfirmed_cycle_pnl_not_recorded",
                {
                    "fill_type": fill_type,
                    "cycle_index": cycle_index,
                    "purpose": fill_event.purpose,
                    "client_order_id": fill_event.client_order_id,
                    "exchange_order_id": fill_event.exchange_order_id,
                    "exec_id": fill_event.exec_id,
                    "pnl": pnl,
                    "pnl_source": pnl_source,
                },
            )
            return
        existing = cycle_entries.get(entry_key)
        if existing:
            existing_source = str(existing.get("source") or "")
            existing_confirmed = bool(existing.get("is_confirmed"))
            if existing_source == pnl_source and abs(float(existing.get("pnl") or 0.0) - pnl) <= 1e-12:
                return
            if existing_confirmed and not is_confirmed:
                return
            if is_confirmed and not existing_confirmed:
                cycle_entries[entry_key] = {
                    "pnl": pnl,
                    "source": pnl_source,
                    "is_confirmed": True,
                }
                self._recompute_cycle_pnl_ledger_totals(ledger)
                return
            if not existing_confirmed and not is_confirmed:
                cycle_entries[entry_key] = {
                    "pnl": float(existing.get("pnl") or 0.0) + pnl,
                    "source": pnl_source,
                    "is_confirmed": False,
                }
                self._recompute_cycle_pnl_ledger_totals(ledger)
                return
            return
        cycle_entries[entry_key] = {
            "pnl": pnl,
            "source": pnl_source,
            "is_confirmed": is_confirmed,
        }
        self._recompute_cycle_pnl_ledger_totals(ledger)

    def _ensure_confirmed_cycle_pnl_ledger_entry(
        self,
        runtime_state: RuntimeState,
        *,
        fill_type: str,
        cycle_index: int,
        fill_event: FillEvent,
        pnl: float,
        pnl_source: str,
    ) -> None:
        if fill_type not in {"cycle_long_reduce", "cycle_short_tp"}:
            return
        if cycle_index <= 0:
            cycle_index = cycle_index_from_purpose(fill_event.purpose or "")
        if cycle_index <= 0:
            return
        if not self._is_confirmed_cycle_pnl_source(pnl_source):
            return
        ledger = runtime_state.strategy_state.setdefault(
            "audit_pnl_ledger",
            {
                "cycle_long_reduce_pnl": {},
                "cycle_short_tp_pnl": {},
                "cycle_pnl_entries": {},
                "final_long_exit_pnl": None,
                "final_short_exit_pnl": None,
                "total_realized_pnl": 0.0,
            },
        )
        self._record_cycle_pnl_entry(
            ledger,
            fill_type=fill_type,
            cycle_index=cycle_index,
            fill_event=fill_event,
            pnl=pnl,
            pnl_source=pnl_source,
        )

    def _audit_exit_pnl_summary(
        self,
        fill_event: FillEvent,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> None:
        status = str(fill_event.status or "").upper()
        if status not in {"FILLED", "PARTIAL", "PARTIALLY_FILLED", "PARTIAL_FILLED"}:
            return
        self._enrich_fill_event_for_confirmed_pnl(fill_event)
        state = runtime_state.strategy_state
        processed = state.setdefault("audit_processed_exit_fill_ids", [])
        metadata = fill_event.metadata or {}
        confirmed_pnl_value = getattr(fill_event, "confirmed_pnl", None)
        confirmed_marker_value = confirmed_pnl_value
        if confirmed_marker_value is None:
            confirmed_marker_value = metadata.get("confirmed_closed_pnl")

        fill_type, cycle_index = self._classify_exit_fill_for_audit(fill_event)
        if fill_type == "ignore":
            return

        if (
            fill_type in {"cycle_long_reduce", "cycle_short_tp"}
            and fill_event.exec_id
        ):
            confirmed_marker_str = (
                str(confirmed_marker_value)
                if confirmed_marker_value is not None
                else "pending"
            )
            fill_id = f"{fill_event.exec_id}|{fill_event.exchange_order_id or ''}|{fill_event.purpose or ''}|{confirmed_marker_str}"
        elif fill_event.exec_id:
            fill_id = str(fill_event.exec_id)
        elif fill_event.exchange_order_id:
            fill_id = f"{fill_event.exchange_order_id}|{fill_event.exec_price}|{fill_event.exec_qty}|{confirmed_marker_value}"
        elif fill_event.client_order_id:
            fill_id = str(fill_event.client_order_id)
        else:
            fill_id = f"{fill_event.purpose or ''}|{fill_event.exec_price or 0.0}|{fill_event.exec_qty or 0.0}|{confirmed_marker_value or 0.0}"
        if fill_id in processed:
            return
        refresh_success = True
        if fill_type == "cycle_short_tp":
            refresh_success = self._refresh_short_reduce_closed_pnl(
                fill_event=fill_event,
                runtime_state=runtime_state,
                context=context,
                cycle_index=cycle_index,
            )
        if fill_type == "cycle_long_reduce":
            cycle_state = self._ensure_cycle_state(runtime_state)
            long_fills = cycle_state.get("long_fills", {})
            long_fill = dict(long_fills.get(str(cycle_index)) or {})
            refresh_success = self._refresh_long_fill_closed_pnl(
                cycle_index=cycle_index,
                long_fill=long_fill,
                runtime_state=runtime_state,
                context=context,
                occurred_at_ms=int(fill_event.occurred_at.timestamp() * 1000)
                if getattr(fill_event, "occurred_at", None)
                else None,
                exec_id=fill_event.exec_id,
                fill_event=fill_event,
            )
        if refresh_success or fill_type not in {"cycle_short_tp", "cycle_long_reduce"}:
            processed.append(fill_id)
            if len(processed) > 500:
                del processed[:-500]
        ledger = state.setdefault(
            "audit_pnl_ledger",
            {
                "cycle_long_reduce_pnl": {},
                "cycle_short_tp_pnl": {},
                "cycle_pnl_entries": {},
                "final_long_exit_pnl": None,
                "final_short_exit_pnl": None,
                "total_realized_pnl": 0.0,
            },
        )
        ledger.setdefault("cycle_pnl_entries", {})
        self._hydrate_cycle_fill_metadata_from_state(
            fill_event,
            runtime_state,
            fill_type=fill_type,
            cycle_index=cycle_index,
            ledger=ledger,
        )
        metadata = fill_event.metadata or {}
        pnl, pnl_source = self._extract_realized_fill_pnl(fill_event, fill_type)
        snapshot = runtime_state.last_snapshot
        metadata_keys = sorted(metadata.keys())
        if fill_type in {"cycle_long_reduce", "cycle_short_tp"} and self._is_confirmed_cycle_pnl_source(pnl_source):
            _log_event(
                "fixed_cycle_cycle_pnl_confirmed_seen_after_refresh",
                {
                    "cycle_index": cycle_index,
                    "fill_type": fill_type,
                    "exchange_order_id": fill_event.exchange_order_id,
                    "client_order_id": fill_event.client_order_id,
                    "exec_id": fill_event.exec_id,
                    "pnl": pnl,
                    "pnl_source": pnl_source,
                    "metadata_keys": metadata_keys,
                    "confirmed_closed_pnl": metadata.get("confirmed_closed_pnl"),
                    "closed_pnl": metadata.get("closed_pnl"),
                },
            )
        if fill_type in {"cycle_long_reduce", "cycle_short_tp"} and pnl_source in {
            "provisional_runtime_calculated_pnl",
            "provisional_exec_pnl",
        }:
            _log_event(
                "fixed_cycle_cycle_pnl_using_provisional_runtime_pnl",
                {
                    "cycle_index": cycle_index,
                    "fill_type": fill_type,
                    "exchange_order_id": fill_event.exchange_order_id,
                    "client_order_id": fill_event.client_order_id,
                    "exec_id": fill_event.exec_id,
                    "pnl": pnl,
                    "pnl_source": pnl_source,
                    "runtime_calculated_pnl": metadata.get("runtime_calculated_pnl"),
                    "exec_pnl": metadata.get("exec_pnl"),
                    "metadata_keys": metadata_keys,
                    "reason": "provisional_runtime_pnl_logged_only_not_confirmed",
                },
            )
        if fill_type in {"cycle_long_reduce", "cycle_short_tp"}:
            self._ensure_confirmed_cycle_pnl_ledger_entry(
                runtime_state,
                fill_type=fill_type,
                cycle_index=cycle_index,
                fill_event=fill_event,
                pnl=pnl,
                pnl_source=pnl_source,
            )
        if fill_type in {"cycle_long_reduce", "cycle_short_tp"} and abs(pnl) <= 1e-12:
            _log_warning_event(
                "fixed_cycle_cycle_pnl_missing_confirmed_closed_pnl",
                {
                    "purpose": fill_event.purpose,
                    "fill_type": fill_type,
                    "cycle_index": cycle_index,
                    "client_order_id": fill_event.client_order_id,
                    "exchange_order_id": fill_event.exchange_order_id,
                    "exec_id": fill_event.exec_id,
                    "exec_qty": fill_event.exec_qty,
                    "exec_price": fill_event.exec_price,
                    "reduce_only": fill_event.reduce_only,
                    "metadata_keys": sorted(metadata.keys()),
                    "runtime_calculated_pnl": metadata.get("runtime_calculated_pnl"),
                    "exec_pnl": metadata.get("exec_pnl"),
                    "confirmed_closed_pnl": metadata.get("confirmed_closed_pnl"),
                    "closed_pnl": metadata.get("closed_pnl"),
                    "pnl_source": pnl_source,
                    "reason": "cycle fill has no usable pnl value",
                },
            )
        occurred_at_iso = (
            fill_event.occurred_at.isoformat() if getattr(fill_event, "occurred_at", None) else None
        )
        if fill_type == "final_long_exit":
            state["final_long_exit_order_context"] = {
                "symbol": str((snapshot.symbol if snapshot else None) or self.config.symbol or ""),
                "side": "long",
                "purpose": str(fill_event.purpose or ""),
                "exchange_order_id": str(fill_event.exchange_order_id or ""),
                "client_order_id": str(fill_event.client_order_id or ""),
                "exec_id": str(fill_event.exec_id or ""),
                "exec_price": float(fill_event.exec_price or 0.0),
                "exec_qty": float(fill_event.exec_qty or 0.0),
                "trigger_price": float(self._safe_float(metadata.get("trigger_price"), 0.0) or 0.0),
                "basket_tp_price": float(self._safe_float(metadata.get("basket_tp_price"), 0.0) or 0.0),
                "basket_break_even_price": float(
                    self._safe_float(metadata.get("basket_break_even_price"), 0.0) or 0.0
                ),
                "occurred_at": occurred_at_iso,
                "source": "final_long_exit",
            }
        elif fill_type == "final_short_exit":
            state["final_short_exit_order_context"] = {
                "symbol": str((snapshot.symbol if snapshot else None) or self.config.symbol or ""),
                "side": "short",
                "purpose": str(fill_event.purpose or ""),
                "exchange_order_id": str(fill_event.exchange_order_id or ""),
                "client_order_id": str(fill_event.client_order_id or ""),
                "exec_id": str(fill_event.exec_id or ""),
                "exec_price": float(fill_event.exec_price or 0.0),
                "exec_qty": float(fill_event.exec_qty or 0.0),
                "trigger_price": float(self._safe_float(metadata.get("trigger_price"), 0.0) or 0.0),
                "basket_tp_price": float(self._safe_float(metadata.get("basket_tp_price"), 0.0) or 0.0),
                "basket_break_even_price": float(
                    self._safe_float(metadata.get("basket_break_even_price"), 0.0) or 0.0
                ),
                "occurred_at": occurred_at_iso,
                "source": "final_short_exit",
            }

        cycle_long_total = sum(
            float(value or 0.0) for value in ledger["cycle_long_reduce_pnl"].values()
        )
        cycle_short_total = sum(
            float(value or 0.0) for value in ledger["cycle_short_tp_pnl"].values()
        )
        cycle_net = cycle_long_total + cycle_short_total

        raw_final_long_exit_pnl = ledger.get("final_long_exit_pnl")
        raw_final_short_exit_pnl = ledger.get("final_short_exit_pnl")
        final_long_exit_pnl = (
            float(raw_final_long_exit_pnl) if raw_final_long_exit_pnl is not None else None
        )
        final_short_exit_pnl = (
            float(raw_final_short_exit_pnl) if raw_final_short_exit_pnl is not None else None
        )
        final_exit_net = sum(
            value
            for value in (
                final_long_exit_pnl,
                final_short_exit_pnl,
            )
            if value is not None
        )

        total_net = cycle_net + final_exit_net
        ledger["total_realized_pnl"] = total_net

        all_cycle_keys = sorted(
            set(ledger["cycle_long_reduce_pnl"].keys()) | set(ledger["cycle_short_tp_pnl"].keys()),
            key=lambda key: int(key) if str(key).isdigit() else key,
        )
        cycle_breakdown: list[dict[str, Any]] = []
        for key in all_cycle_keys:
            try:
                cycle_idx = int(key)
            except ValueError:
                cycle_idx = key
            long_reduce_pnl = float(ledger["cycle_long_reduce_pnl"].get(key, 0.0))
            short_tp_pnl = float(ledger["cycle_short_tp_pnl"].get(key, 0.0))
            cycle_breakdown.append(
                {
                    "cycle_index": cycle_idx,
                    "long_add_loss_or_profit": long_reduce_pnl,
                    "short_tp_profit_or_loss": short_tp_pnl,
                    "cycle_net_pnl": long_reduce_pnl + short_tp_pnl,
                }
            )
        expected = None
        delta = None
        delta_pct = None
        if fill_type == "cycle_short_tp":
            expected = float(state.get("last_expected_short_tp_net") or 0.0)
            delta = pnl - expected
            delta_pct = (delta / expected) if expected > 0 else 0.0
        expected_vs_actual = {
            "expected_short_tp_net": expected if fill_type == "cycle_short_tp" else None,
            "actual_fill_pnl": pnl,
            "actual_fill_pnl_source": pnl_source,
            "delta": delta if fill_type == "cycle_short_tp" else None,
            "delta_pct": delta_pct if fill_type == "cycle_short_tp" else None,
            "fill_type": fill_type,
        }
        completed = state.setdefault("audit_completed_cycle_indices", [])
        for entry in cycle_breakdown:
            cycle_key = str(entry["cycle_index"])
            cycle_confirmed = (
                cycle_key in (ledger["cycle_long_reduce_pnl"] or {})
                and cycle_key in (ledger["cycle_short_tp_pnl"] or {})
            )
            if (
                cycle_confirmed
                and cycle_key not in completed
            ):
                completed.append(cycle_key)
                _audit_calc(
                    "cycle_completed",
                    {
                        "cycle_index": entry["cycle_index"],
                        "long_add_loss_or_profit": entry["long_add_loss_or_profit"],
                        "short_tp_profit_or_loss": entry["short_tp_profit_or_loss"],
                        "cycle_net_pnl": entry["cycle_net_pnl"],
                        "total_realized_pnl": total_net,
                        "latest_fill_purpose": fill_event.purpose,
                        "latest_fill_status": fill_event.status,
                    },
                )

        def _fmt(value: float | None) -> str:
            return "pending" if value is None else f"{value:+.4f}"

        latest_fill_info = {
            "purpose": fill_event.purpose,
            "fill_type": fill_type,
            "cycle_index": cycle_index,
            "pnl_this_fill": pnl,
            "pnl_source": pnl_source,
            "exec_price": float(fill_event.exec_price or 0.0),
            "qty": float(fill_event.exec_qty or 0.0),
            "client_order_id": fill_event.client_order_id,
            "exchange_order_id": fill_event.exchange_order_id,
            "metadata": fill_event.metadata or {},
            "exec_id": fill_event.exec_id,
            "confirmed_pnl": confirmed_pnl_value,
            "closed_pnl": (fill_event.metadata or {}).get("closed_pnl"),
            "fill_status": fill_event.status,
            "expected_short_tp_net": expected if fill_type == "cycle_short_tp" else None,
            "expected_actual_delta": delta if fill_type == "cycle_short_tp" else None,
            "expected_trigger_price": (
                float(state.get("last_short_tp_trigger_price") or 0.0)
                if fill_type == "cycle_short_tp"
                else None
            ),
            "filled_price": float(fill_event.exec_price or 0.0),
            "trigger_vs_fill_delta": (
                float(fill_event.exec_price or 0.0)
                - float(state.get("last_short_tp_trigger_price") or 0.0)
                if fill_type == "cycle_short_tp"
                and float(state.get("last_short_tp_trigger_price") or 0.0) > 0
                else None
            ),
        }

        summary_lines: list[str] = []
        for entry in cycle_breakdown:
            idx = entry.get("cycle_index")
            summary_lines.append(f"Cycle {idx}:")
            summary_lines.append(f"LONG_ADD_{idx} Verlust/Profit: {_fmt(entry['long_add_loss_or_profit'])}")
            summary_lines.append(f"SHORT_TP_{idx} Profit/Loss: {_fmt(entry['short_tp_profit_or_loss'])}")
            summary_lines.append(f"Cycle Net: {_fmt(entry['cycle_net_pnl'])}")
            cycle_key = str(idx)
            status = (
                "COMPLETED"
                if (
                    cycle_key in (ledger["cycle_long_reduce_pnl"] or {})
                    and cycle_key in (ledger["cycle_short_tp_pnl"] or {})
                )
                else "OPEN / WAITING"
            )
            summary_lines.append(f"Status: {status}")
            summary_lines.append("")
        summary_lines.append("Final exits:")
        summary_lines.append(f"LONG_EXIT Profit/Loss: {_fmt(final_long_exit_pnl)}")
        summary_lines.append(f"SHORT_EXIT Profit/Loss: {_fmt(final_short_exit_pnl)}")
        summary_lines.append(f"Final Exit Net: {_fmt(final_exit_net)}")
        summary_lines.append("")
        summary_lines.append("Total:")
        summary_lines.append(f"Cycle Net Total: {_fmt(cycle_net)}")
        summary_lines.append(f"Final Exit Net: {_fmt(final_exit_net)}")
        summary_lines.append(f"BOT TOTAL REALIZED PNL: {_fmt(total_net)}")
        if fill_type == "cycle_short_tp":
            summary_lines.append("")
            summary_lines.append("Expected vs Actual:")
            summary_lines.append(f"Expected SHORT_TP Net: {_fmt(expected or 0.0)}")
            summary_lines.append(f"Actual Fill PnL: {_fmt(pnl)}")
            summary_lines.append(f"Delta: {_fmt(delta or 0.0)}")
        summary_text = "\n".join(summary_lines)

        payload = {
            "latest_fill": latest_fill_info,
            "cycle_breakdown": cycle_breakdown,
            "totals": {
                "cycle_long_reduce_total": cycle_long_total,
                "cycle_short_tp_total": cycle_short_total,
                "cycle_net_pnl": cycle_net,
                "final_long_exit_pnl": final_long_exit_pnl,
                "final_short_exit_pnl": final_short_exit_pnl,
                "final_exit_net_pnl": final_exit_net,
                "total_realized_pnl": total_net,
            },
            "summary_text": summary_text,
            "expected_vs_actual": expected_vs_actual,
            "pnl_source": pnl_source,
        }
        _audit_calc("exit_pnl_summary", payload)

    def on_reconcile(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent]:
        self._seed_initial_reference_if_missing(snapshot, runtime_state)
        self._sync_state_from_snapshot(snapshot, runtime_state)
        return self._maybe_refresh_structure(snapshot, runtime_state, context, reason="reconcile_guard")

    def _build_entry_intents(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent]:
        state = runtime_state.strategy_state
        current_symbol = str(self.config.symbol or "").upper()
        blocked_symbol = state.get("initial_entry_blocked_symbol")
        if blocked_symbol and blocked_symbol == current_symbol:
            return []
        if blocked_symbol and blocked_symbol != current_symbol:
            keys_to_clear = [
                "initial_entry_blocked_symbol",
                "initial_entry_retry_blocked",
                "dynamic_symbol_reselection_reason",
            ]
            for key in keys_to_clear:
                state.pop(key, None)
        self._ensure_cycle_sequence_state(runtime_state)
        cycle_block_status = state.get("cycle_block_status")
        if (
            cycle_block_status == "REFILL_REQUIRED"
            and not state.get("refill_pending")
            and not state.get("refill_required")
            and not state.get("refill_in_progress")
            and not self._collect_refill_requested_flags(state.get("refill_state") or {})
        ):
            cycle_completed_count = int(state.get("cycle_completed_count") or 0)
            cycle_pair_count = int(state.get("cycle_pair_count") or 0)
            last_refill_completed_cycle_index = int(
                state.get("last_refill_completed_cycle_index") or 0
            )
            last_refill_completed_cycle_pair_count = int(
                state.get("last_refill_completed_cycle_pair_count") or 0
            )
            cycles_since_last_refill = cycle_completed_count - last_refill_completed_cycle_index
            pair_cycles_since_last_refill = (
                cycle_pair_count - last_refill_completed_cycle_pair_count
            )
            if cycles_since_last_refill >= 2 or pair_cycles_since_last_refill >= 2:
                self._mark_refill_required_after_cycle_pair(
                    runtime_state,
                    cycle_index=max(cycle_pair_count, cycle_completed_count),
                    trigger_purpose="entry_refill_repair",
                    reason="entry_refill_repair",
                )
                return []
            self._clear_refill_gate_state(runtime_state, preserve_pending=False)
        if state.get("fresh_entry_blocked_until_next_tick"):
            _log_event(
                "fixed_cycle_fresh_entry_blocked_until_next_tick",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "category": self.config.category,
                    "active_cycle_index": state.get("active_cycle_index"),
                    "cycle_step": state.get("cycle_step"),
                    "next_required_purpose": state.get("next_required_purpose"),
                },
            )
            state["fresh_entry_blocked_until_next_tick"] = False
            state["post_exit_reset_in_progress"] = False
            self._persist_cycle_sequence_state(runtime_state)
            return []
        if state.get("fresh_entry_blocked_until_next_tick"):
            _log_event(
                "fixed_cycle_fresh_entry_blocked_until_next_tick",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "category": self.config.category,
                    "active_cycle_index": state.get("active_cycle_index"),
                    "cycle_step": state.get("cycle_step"),
                    "next_required_purpose": state.get("next_required_purpose"),
                },
            )
            state["fresh_entry_blocked_until_next_tick"] = False
            state["post_exit_reset_in_progress"] = False
            self._persist_cycle_sequence_state(runtime_state)
            return []
        if state.get("emergency_flat_required"):
            _log_event(
                "fixed_cycle_fresh_entry_blocked_emergency_flat",
                {
                    "symbol": self.config.symbol,
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                    "emergency_attempts": state.get("emergency_exit_attempts"),
                },
            )
            return []
        if self._post_exit_cleanup_pending(runtime_state):
            if not self._attempt_post_exit_cleanup(snapshot, runtime_state, context):
                return []
        if (
            not state.get("refill_pending")
            and (snapshot.long_qty > 0 or snapshot.short_qty > 0)
        ):
            _log_warning_event(
                "fixed_cycle_initial_entry_blocked_open_position",
                {
                    "reason": "build_entry_intents_open_position_guard",
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                    "long_avg": snapshot.long_avg,
                    "short_avg": snapshot.short_avg,
                    "current_price": snapshot.current_price,
                    "bot_state": state.get("bot_state"),
                    "initial_entry_confirmed": bool(state.get("initial_entry_confirmed")),
                    "initial_entry_submitted": bool(state.get("initial_entry_submitted")),
                    "fresh_restart_required": bool(state.get("fresh_restart_required")),
                },
            )
            return []
        final_pnl_ready = (
            self._final_pnl_ready_for_restart(runtime_state)
            or bool(state.get("verified_flat_runtime_reset_done"))
        )
        if not final_pnl_ready and state.get("current_trade_pnl_state_reset_for_entry"):
            final_pnl_ready = (
                bool(state.get("final_trade_pnl_audited"))
                and bool(state.get("last_trade_pnl_complete"))
                and state.get("last_trade_pnl_usdt") is not None
            )
        if not state.get("refill_pending"):
            active_snapshot_order_purposes, active_runtime_order_purposes = (
                self._collect_active_strategy_order_purposes(snapshot, runtime_state)
            )
            if active_snapshot_order_purposes or active_runtime_order_purposes:
                _log_event(
                    "fixed_cycle_fresh_entry_blocked_active_strategy_orders",
                    {
                        "symbol": self.config.symbol,
                        "reason": "active_strategy_orders",
                        "active_snapshot_order_purposes": active_snapshot_order_purposes,
                        "active_runtime_order_purposes": active_runtime_order_purposes,
                        "long_qty": snapshot.long_qty,
                        "short_qty": snapshot.short_qty,
                        "last_trade_pnl_complete": bool(state.get("last_trade_pnl_complete")),
                        "final_trade_pnl_audited": bool(state.get("final_trade_pnl_audited")),
                        "current_trade_pnl_state_reset_for_entry": bool(
                            state.get("current_trade_pnl_state_reset_for_entry")
                        ),
                    },
                )
                return []
        if (
            not state.get("refill_pending")
            and snapshot.long_qty <= 0
            and snapshot.short_qty <= 0
        ):
            if (
                not self._has_nonterminal_snapshot_orders(snapshot)
                and not self._has_nonterminal_runtime_orders(runtime_state)
                and not active_snapshot_order_purposes
                and not active_runtime_order_purposes
                and not state.get("verified_flat_runtime_reset_done")
            ):
                if self._perform_verified_flat_runtime_reset(
                    snapshot=snapshot,
                    runtime_state=runtime_state,
                    context=context,
                    reason="pre_initial_entry_flat_gate",
                    allow_unknown_final_pnl=True,
                ):
                    _log_event(
                        "fixed_cycle_pre_entry_flat_state_clean_reset_applied",
                        {
                            "reason": "pre_initial_entry_flat_gate",
                            "symbol": self.config.symbol,
                            "long_qty": snapshot.long_qty,
                            "short_qty": snapshot.short_qty,
                        },
                    )
            if (
                self._previous_trade_evidence_present(runtime_state)
                and not state.get("startup_flat_reset_applied")
                and not state.get("verified_flat_runtime_reset_done")
            ):
                ledger = state.get("audit_pnl_ledger") or {}
                final_long_exit_pnl = ledger.get("final_long_exit_pnl")
                final_short_exit_pnl = ledger.get("final_short_exit_pnl")
                if not final_pnl_ready:
                    _log_event(
                        "fixed_cycle_fresh_entry_blocked_pending_final_exit_settlement",
                        {
                            "symbol": self.config.symbol,
                            "reason": "final_pnl_pending",
                            "final_long_exit_pnl": final_long_exit_pnl,
                            "final_short_exit_pnl": final_short_exit_pnl,
                            "final_trade_pnl_audited": bool(state.get("final_trade_pnl_audited")),
                            "last_trade_pnl_complete": bool(state.get("last_trade_pnl_complete")),
                            "last_trade_pnl_usdt": state.get("last_trade_pnl_usdt"),
                            "trade_block_id": state.get("trade_block_id"),
                            "last_trade_block_id": state.get("last_trade_block_id"),
                            "pnl_ready_for_current_trade": False,
                        },
                    )
                    return []
                snapshot_purposes, runtime_purposes = self._collect_active_final_exit_purposes(
                    snapshot, runtime_state
                )
                if snapshot_purposes or runtime_purposes:
                    _log_event(
                        "fixed_cycle_fresh_entry_blocked_pending_final_exit_settlement",
                        {
                            "symbol": self.config.symbol,
                            "reason": "final_exit_orders_pending",
                            "pending_snapshot_final_exit_purposes": snapshot_purposes,
                            "pending_runtime_final_exit_purposes": runtime_purposes,
                            "final_long_exit_pnl": final_long_exit_pnl,
                            "final_short_exit_pnl": final_short_exit_pnl,
                            "trade_block_id": state.get("trade_block_id"),
                            "last_trade_block_id": state.get("last_trade_block_id"),
                            "pnl_ready_for_current_trade": True,
                        },
                    )
                    return []
            if not state.get("current_trade_pnl_state_reset_for_entry"):
                self._reset_current_trade_pnl_state(
                    runtime_state,
                    reason="before_initial_entry",
                )
                state["current_trade_pnl_state_reset_for_entry"] = True

        refill_required = self._cycle_build_block_active(state)
        if refill_required:
            gate_details = self._reconcile_refill_gate_state(snapshot, runtime_state)
            context.audit.log_event(
                "fixed_cycle_refill_required_after_cycle_pair",
                strategy=self.name,
                cycle_completed_count=state.get("cycle_completed_count"),
                cycle_pair_count=state.get("cycle_pair_count"),
                refill_pending=bool(state.get("refill_pending")),
                refill_required=bool(state.get("refill_required")),
                bot_state=state.get("bot_state"),
                active_refill_orders_count=gate_details["active_refill_orders_count"],
                stale_detected=gate_details["stale_detected"],
            )
            if gate_details["active_refill_orders_count"] > 0:
                context.audit.log_event(
                    "fixed_cycle_refill_block_details",
                    strategy=self.name,
                    **gate_details,
                )
                return []
            current_price = float(snapshot.current_price or 0.0)
            initial_long_qty = float(state.get("initial_long_qty") or 0.0)
            initial_short_qty = float(state.get("initial_short_qty") or 0.0)

            current_long_qty = float(snapshot.long_qty or 0.0)
            current_short_qty = float(snapshot.short_qty or 0.0)

            residual = self._apply_refill_dust_residual_filter(
                self._refill_residual_snapshot_payload(snapshot, runtime_state),
                runtime_state,
                reason="refill_qty_calculation",
            )
            missing_long_qty = residual["missing_long_qty"]
            missing_short_qty = residual["missing_short_qty"]
            refill_long_qty = residual["refill_long_qty"]
            refill_short_qty = residual["refill_short_qty"]

            refill_payload = {
                "current_price": current_price,
                "initial_long_qty": initial_long_qty,
                "initial_short_qty": initial_short_qty,
                "current_long_qty": current_long_qty,
                "current_short_qty": current_short_qty,
                "missing_long_qty": missing_long_qty,
                "missing_short_qty": missing_short_qty,
                "refill_long_qty": refill_long_qty,
                "refill_short_qty": refill_short_qty,
                "cycle_completed_count": state.get("cycle_completed_count"),
                "cycle_pair_count": state.get("cycle_pair_count"),
                "trigger_purpose": state.get("refill_trigger_purpose"),
            }
            _log_event("fixed_cycle_refill_qty_calculated", refill_payload)

            if self._try_complete_refill_after_dust_residual(
                snapshot,
                runtime_state,
                context,
                reason="refill_qty_calculation_dust_only",
                residual_payload=refill_payload,
            ):
                return []

            if current_price <= 0:
                _log_warning_event(
                    "fixed_cycle_refill_submit_failed",
                    {**refill_payload, "reason": "current_price_missing"},
                )
                self._clear_refill_gate_state(runtime_state, preserve_pending=True)
                return []

            if missing_long_qty <= 0 and missing_short_qty <= 0:
                state["refill_long_filled"] = True
                state["refill_short_filled"] = True
                state["refill_fills_complete"] = True
                state["refill_completion_pending_reconcile"] = True
                _log_event("fixed_cycle_refill_no_qty_needed", refill_payload)
                _log_event(
                    "fixed_cycle_refill_completion_deferred_from_entry_zero_qty",
                    {
                        "symbol": self.config.symbol,
                        "reason": "entry_zero_quantity_waiting_for_post_rebuild_reconcile",
                        "refill_pending": bool(state.get("refill_pending")),
                        "refill_in_progress": bool(state.get("refill_in_progress")),
                        "refill_fills_complete": True,
                        "refill_completion_pending_reconcile": True,
                        "long_qty": current_long_qty,
                        "short_qty": current_short_qty,
                    },
                )
                return []

            if state.get("refill_exit_orders_cancel_required"):
                active_orders = [
                    *snapshot.active_orders,
                    *runtime_state.active_orders.values(),
                ]
                guard_payload = {
                    "symbol": self.config.symbol,
                    "category": context.category or self.config.category,
                    "refill_pending": bool(state.get("refill_pending")),
                    "refill_required": bool(state.get("refill_required")),
                    "refill_in_progress": bool(state.get("refill_in_progress")),
                    "bot_state": state.get("bot_state"),
                    "refill_exit_orders_cancel_required": True,
                    "active_order_purposes": sorted(
                        {
                            getattr(order, "purpose", None)
                            for order in active_orders
                            if getattr(order, "purpose", None)
                        }
                    ),
                    "active_order_count": len(active_orders),
                }
                _log_event("fixed_cycle_refill_exit_order_cancel_required_detected", guard_payload)
                cancel_ok = self._cancel_refill_exit_orders(runtime_state, context, state)
                if not cancel_ok:
                    _log_event("fixed_cycle_refill_blocked_waiting_for_exit_order_cancel", guard_payload)
                    return []

            intents: list[StrategyIntent] = []
            expected_purposes: list[str] = []
            if state.get("refill_completion_pending_reconcile") or state.get("refill_fills_complete"):
                if not state.get("refill_long_filled"):
                    state["refill_long_filled"] = missing_long_qty <= 0
                if not state.get("refill_short_filled"):
                    state["refill_short_filled"] = missing_short_qty <= 0
            else:
                state["refill_long_filled"] = missing_long_qty <= 0
                state["refill_short_filled"] = missing_short_qty <= 0

            pending_registry_entries = self._refill_registry_pending_entries(state)
            if pending_registry_entries:
                _log_event(
                    "fixed_cycle_refill_waiting_for_registered_intents",
                    {
                        "symbol": self.config.symbol,
                        "refill_batch_id": state.get("refill_batch_id"),
                        "pending_registry_entries": pending_registry_entries,
                        "refill_pending": bool(state.get("refill_pending")),
                        "refill_in_progress": bool(state.get("refill_in_progress")),
                    },
                )
                return []

            registry = state.get("refill_intent_registry") or {}
            if registry:
                active_refill_state = (
                    bool(state.get("refill_fills_complete"))
                    or bool(state.get("refill_completion_pending_reconcile"))
                    or bool(state.get("refill_in_progress"))
                )
                if active_refill_state:
                    _log_event(
                        "fixed_cycle_refill_waiting_for_registered_intents",
                        {
                            "symbol": self.config.symbol,
                            "refill_batch_id": state.get("refill_batch_id"),
                            "pending_registry_entries": [
                                {
                                    "purpose": purpose,
                                    "status": entry.get("status"),
                                }
                                for purpose, entry in registry.items()
                            ],
                            "refill_fills_complete": bool(state.get("refill_fills_complete")),
                            "refill_completion_pending_reconcile": bool(
                                state.get("refill_completion_pending_reconcile")
                            ),
                        },
                    )
                    return []
                return []
            batch_id, _ = self._prepare_refill_batch_for_new_intents(state)

            def _build_refill_intent(
                purpose: str,
                side: str,
                qty: float,
                position_idx: int,
            ) -> StrategyIntent | None:
                existing = self._refill_registry_entry(state, purpose)
                if existing and existing.get("status") in {
                    "REQUESTED",
                    "SUBMITTED",
                    "FILLED",
                }:
                    _log_event(
                        "fixed_cycle_refill_duplicate_intent_blocked_by_registry",
                        {
                            "symbol": self.config.symbol,
                            "purpose": purpose,
                            "status": existing.get("status"),
                            "refill_batch_id": batch_id,
                            "existing_entry": {
                                "qty": existing.get("qty"),
                                "order_type": existing.get("order_type"),
                                "created_at_ms": existing.get("created_at_ms"),
                            },
                        },
                    )
                    return None
                self._register_refill_intent(state, purpose, qty, "Market", None)
                metadata = {
                    "entry_role": f"refill_{side}",
                    "refill_batch_id": batch_id,
                    "refill_purpose": purpose,
                }
                return StrategyIntent(
                    side=side,
                    qty=qty,
                    price=None,
                    purpose=purpose,
                    order_type="Market",
                    reduce_only=False,
                    position_idx=position_idx,
                    metadata=metadata,
                )


            if refill_long_qty > 0 and not self._refill_qty_below_min_notional(
                refill_long_qty, current_price, runtime_state
            ):
                intent = _build_refill_intent(
                    purpose="REFILL_LONG",
                    side="long",
                    qty=refill_long_qty,
                    position_idx=1,
                )
                if intent:
                    if state.get("refill_trigger_reason") == "time_distance_refill":
                        _log_event(
                            "recovery_refill_order_build_started",
                            {
                                "symbol": self.config.symbol,
                                "cycle_index": int(state.get("active_cycle_index") or 0) or None,
                                "refill_side": "long",
                                "refill_purpose": "REFILL_LONG",
                                "refill_price": getattr(intent, "price", None),
                                "refill_qty": refill_long_qty,
                                "source": "recovery_mode_midpoint",
                            },
                        )
                    expected_purposes.append("REFILL_LONG")
                    intents.append(intent)

            if refill_short_qty > 0 and not self._refill_qty_below_min_notional(
                refill_short_qty, current_price, runtime_state
            ):
                intent = _build_refill_intent(
                    purpose="REFILL_SHORT",
                    side="short",
                    qty=refill_short_qty,
                    position_idx=2,
                )
                if intent:
                    if state.get("refill_trigger_reason") == "time_distance_refill":
                        _log_event(
                            "recovery_refill_order_build_started",
                            {
                                "symbol": self.config.symbol,
                                "cycle_index": int(state.get("active_cycle_index") or 0) or None,
                                "refill_side": "short",
                                "refill_purpose": "REFILL_SHORT",
                                "refill_price": getattr(intent, "price", None),
                                "refill_qty": refill_short_qty,
                                "source": "recovery_mode_midpoint",
                            },
                        )
                    expected_purposes.append("REFILL_SHORT")
                    intents.append(intent)

            if not intents:
                if self._try_complete_refill_after_dust_residual(
                    snapshot,
                    runtime_state,
                    context,
                    reason="refill_intent_build_no_actionable_qty",
                    residual_payload=refill_payload,
                ):
                    return []
                _log_warning_event(
                    "fixed_cycle_refill_submit_failed",
                    {**refill_payload, "reason": "normalized_qty_zero_or_below_min"},
                )
                self._clear_refill_gate_state(runtime_state, preserve_pending=True)
                state["refill_fills_complete"] = True
                state["refill_completion_pending_reconcile"] = True
                _log_event(
                    "fixed_cycle_refill_completion_deferred_from_entry_zero_qty",
                    {
                        "symbol": self.config.symbol,
                        "reason": "entry_zero_quantity_waiting_for_post_rebuild_reconcile",
                        "refill_pending": bool(state.get("refill_pending")),
                        "refill_in_progress": bool(state.get("refill_in_progress")),
                        "refill_fills_complete": True,
                        "refill_completion_pending_reconcile": True,
                        "long_qty": current_long_qty,
                        "short_qty": current_short_qty,
                    },
                )
                return []

            state["refill_in_progress"] = True
            state["refill_state"] = {
                "REQUESTED": True,
                "expected_purposes": expected_purposes,
                "created_at_ms": _current_time_ms(),
            }
            if state.get("refill_trigger_reason") == "time_distance_refill":
                _log_event(
                    "recovery_refill_order_submitted",
                    {
                        "symbol": self.config.symbol,
                        "cycle_index": int(state.get("active_cycle_index") or 0) or None,
                        "expected_purposes": expected_purposes,
                        "intent_count": len(intents),
                        "source": "recovery_mode_midpoint",
                    },
                )
            _log_event(
                "fixed_cycle_refill_intents_created",
                {
                    **refill_payload,
                    "refill_batch_id": batch_id,
                    "expected_purposes": expected_purposes,
                    "intent_count": len(intents),
                    "intents": [
                        {
                            "purpose": intent.purpose,
                            "qty": intent.qty,
                            "side": intent.side,
                            "position_idx": intent.position_idx,
                        }
                        for intent in intents
                    ],
                },
            )
            return intents

        entry_reference_price = float(runtime_state.strategy_state.get("entry_reference_price") or 0.0)
        resolved_price = snapshot.current_price if snapshot.current_price > 0 else 0.0
        if resolved_price <= 0 and runtime_state.last_snapshot and runtime_state.last_snapshot.current_price > 0:
            resolved_price = runtime_state.last_snapshot.current_price
        if resolved_price <= 0 and entry_reference_price > 0:
            resolved_price = entry_reference_price
        if resolved_price <= 0 and self.config.initial_entry_reference_price > 0:
            resolved_price = self.config.initial_entry_reference_price
        if resolved_price <= 0:
            context.audit.log_event(
                "fixed_cycle_entry_deferred_no_price",
                strategy=self.name,
                current_price=snapshot.current_price,
                last_snapshot_price=runtime_state.last_snapshot.current_price if runtime_state.last_snapshot else 0.0,
                entry_reference_price=entry_reference_price,
            )
            return []
        if resolved_price != snapshot.current_price:
            context.audit.log_event(
                "fixed_cycle_entry_price_fallback_used",
                strategy=self.name,
                current_price=snapshot.current_price,
                resolved_price=resolved_price,
                last_snapshot_price=runtime_state.last_snapshot.current_price if runtime_state.last_snapshot else 0.0,
                entry_reference_price=entry_reference_price,
            )

        if not state.get("trade_block_id"):
            state["trade_block_id"] = str(uuid4())
        if not state.get("trade_started_at"):
            state["trade_started_at"] = datetime.now(timezone.utc).isoformat()
        self._capture_recovery_wallet_baseline(
            state.get("trade_block_id"),
            snapshot,
            runtime_state,
            context,
            baseline_context="initial_entry_before_submit",
        )

        long_qty = self._normalize_qty(
            self.config.base_notional_usdt / resolved_price, runtime_state
        )
        short_qty = self._normalize_qty(
            (self.config.base_notional_usdt * self.config.hedge_ratio_short) / resolved_price,
            runtime_state,
        )

        if long_qty <= 0 or short_qty <= 0:
            runtime_state.strategy_state["bot_state"] = self.STATE_ERROR
            context.audit.log_event(
                "fixed_cycle_entry_failed",
                strategy=self.name,
                reason="normalized_entry_qty_zero",
                long_qty=long_qty,
                short_qty=short_qty,
            )
            return []

        runtime_state.strategy_state["entry_reference_price"] = resolved_price
        runtime_state.strategy_state["initial_long_qty"] = long_qty
        runtime_state.strategy_state["initial_short_qty"] = short_qty
        runtime_state.strategy_state["initial_total_notional_usdt"] = (
            (long_qty * resolved_price) + (short_qty * resolved_price)
        )

        order_type = self.config.initial_entry_order_type
        price = self._normalize_price(resolved_price, runtime_state) if order_type == "Limit" else None

        traces = [
            CalculationTrace(
                name="initial_hedge_sizes",
                formula="qty = notional / current_price",
                inputs={
                    "base_notional_usdt": self.config.base_notional_usdt,
                    "hedge_ratio_short": self.config.hedge_ratio_short,
                    "current_price": resolved_price,
                },
                result={"long_qty": long_qty, "short_qty": short_qty},
            )
        ]

        context.audit.log_event(
            "fixed_cycle_entry_planned",
            strategy=self.name,
            current_price=snapshot.current_price,
            resolved_price=resolved_price,
            base_notional_usdt=self.config.base_notional_usdt,
            long_qty_raw=self.config.base_notional_usdt / resolved_price,
            long_qty_formula="base_notional_usdt / current_price",
            hedge_ratio_short=self.config.hedge_ratio_short,
            short_qty_raw=(self.config.base_notional_usdt * self.config.hedge_ratio_short) / resolved_price,
            short_qty_formula="(base_notional_usdt * hedge_ratio_short) / current_price",
            normalized_long_qty=long_qty,
            normalized_short_qty=short_qty,
            order_type=order_type,
            entry_price_raw=resolved_price,
            entry_price_normalized=price,
        )

        return [
            StrategyIntent(
                side="long",
                qty=long_qty,
                price=price,
                purpose=self.LONG_ENTRY_PURPOSE,
                order_type=order_type,
                reduce_only=False,
                metadata={"entry_role": "initial_long"},
                trace=traces,
            ),
            StrategyIntent(
                side="short",
                qty=short_qty,
                price=price,
                purpose=self.SHORT_ENTRY_PURPOSE,
                order_type=order_type,
                reduce_only=False,
                metadata={"entry_role": "initial_short"},
                trace=traces,
            ),
        ]

    def _maybe_refresh_structure(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        reason: str,
    ) -> list[StrategyIntent]:
        state = runtime_state.strategy_state
        if state.get("initial_entry_submitted") and not state.get("initial_structure_built"):
            source = "tick" if reason.startswith("tick_") else "reconcile"
            return self._maybe_build_initial_structure_once(
                snapshot,
                runtime_state,
                context,
                purpose=None,
                source=source,
                reason=reason,
                rebuild_reason="initial_entry_complete_tick" if source == "tick" else "initial_entry_complete",
                allow_build=False,
            )
        now_ms = int(time.time() * 1000)
        last_ms = int(runtime_state.strategy_state.get("last_structure_refresh_ms") or 0)
        if now_ms - last_ms < self.config.order_refresh_cooldown_ms:
            return []
        runtime_state.strategy_state["last_structure_refresh_ms"] = now_ms
        return self._rebuild_structure(snapshot, runtime_state, context, reason=reason)

    def _get_realized_net_pnl_total(
        self, runtime_state: RuntimeState | None, snapshot: HedgeSnapshot | None = None
    ) -> float:
        total = 0.0
        if runtime_state:
            total = float(
                (runtime_state.realized_long_pnl_total or 0.0)
                + (runtime_state.realized_short_pnl_total or 0.0)
            )
        if abs(total) <= 1e-12 and snapshot:
            total = float(snapshot.realized_pnl_total or 0.0)
        return total

    @staticmethod
    def _resolve_active_trade_block_id(strategy_state: dict[str, Any] | None) -> str | None:
        return resolve_active_trade_block_id(strategy_state)

    @staticmethod
    def _final_pnl_ready_for_restart(runtime_state: RuntimeState) -> bool:
        state = runtime_state.strategy_state
        current_trade_block_id = state.get("trade_block_id")
        last_trade_block_id = state.get("last_trade_block_id")
        return (
            bool(state.get("final_trade_pnl_audited"))
            and bool(state.get("last_trade_pnl_complete"))
            and state.get("last_trade_pnl_usdt") is not None
            and bool(current_trade_block_id)
            and last_trade_block_id == current_trade_block_id
        )

    @staticmethod
    def _is_active_final_exit_order(order: Any) -> bool:
        purpose = str(getattr(order, "purpose", "") or "").upper()
        status = str(getattr(order, "status", "") or "").upper()
        return (
            purpose
            in {
                FixedCycleHedgeStrategy.LONG_TP_EXIT_PURPOSE,
                FixedCycleHedgeStrategy.LONG_TP_EXIT_RECOVERY_PURPOSE,
                FixedCycleHedgeStrategy.LONG_SL_EXIT_PURPOSE,
                FixedCycleHedgeStrategy.SHORT_TP_EXIT_PURPOSE,
                FixedCycleHedgeStrategy.SHORT_SL_EXIT_PURPOSE,
                FixedCycleHedgeStrategy.SHORT_SL_EXIT_RECOVERY_PURPOSE,
                FixedCycleHedgeStrategy.SHORT_HARD_STOP_PURPOSE,
            }
            and status not in {"FILLED", "CANCELED", "CANCELLED", "REJECTED", "EXPIRED"}
        )

    def _collect_active_final_exit_purposes(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> tuple[list[str], list[str]]:
        snapshot_purposes: list[str] = []
        runtime_purposes: list[str] = []
        for order in snapshot.active_orders:
            if self._is_active_final_exit_order(order):
                snapshot_purposes.append(
                    str(getattr(order, "purpose", "") or getattr(order, "client_order_id", "") or "")
                )
        for order in runtime_state.active_orders.values():
            if self._is_active_final_exit_order(order):
                runtime_purposes.append(
                    str(getattr(order, "purpose", "") or getattr(order, "client_order_id", "") or "")
                )
        return snapshot_purposes, runtime_purposes

    def _has_active_final_exit_orders(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> bool:
        snapshot_purposes, runtime_purposes = self._collect_active_final_exit_purposes(
            snapshot, runtime_state
        )
        return bool(snapshot_purposes or runtime_purposes)

    def _previous_trade_evidence_present(self, runtime_state: RuntimeState) -> bool:
        state = runtime_state.strategy_state
        audit_pnl_ledger = state.get("audit_pnl_ledger") or {}
        cycle_long_reduce_total = sum(
            float(value or 0.0)
            for value in (audit_pnl_ledger.get("cycle_long_reduce_pnl") or {}).values()
        )
        cycle_short_tp_total = sum(
            float(value or 0.0)
            for value in (audit_pnl_ledger.get("cycle_short_tp_pnl") or {}).values()
        )
        return any(
            [
                bool(state.get("initial_entry_confirmed")),
                bool(state.get("final_long_exit_order_context")),
                bool(state.get("final_short_exit_order_context")),
                float(audit_pnl_ledger.get("final_long_exit_pnl") or 0.0) != 0.0,
                float(audit_pnl_ledger.get("final_short_exit_pnl") or 0.0) != 0.0,
                cycle_long_reduce_total != 0.0,
                cycle_short_tp_total != 0.0,
                bool(state.get("final_long_exit_audited")),
                bool(state.get("final_short_exit_audited")),
                bool(state.get("exit_locked")),
                bool(state.get("fresh_restart_required")),
                bool(state.get("last_trade_block_id")),
                bool(state.get("trade_block_id")),
            ]
        )

    @staticmethod
    def _is_terminal_order_status(status: Any) -> bool:
        return str(status or "").upper() in {
            "FILLED",
            "CANCELED",
            "CANCELLED",
            "REJECTED",
            "DEACTIVATED",
            "EXPIRED",
        }

    @staticmethod
    def _has_nonterminal_snapshot_orders(
        snapshot: HedgeSnapshot,
    ) -> bool:
        return any(
            not FixedCycleHedgeStrategy._is_terminal_order_status(getattr(order, "status", None))
            for order in snapshot.active_orders
        )

    @staticmethod
    def _has_nonterminal_runtime_orders(runtime_state: RuntimeState) -> bool:
        return any(
            not FixedCycleHedgeStrategy._is_terminal_order_status(getattr(order, "status", None))
            for order in runtime_state.active_orders.values()
        )

    def _is_strategy_order_purpose(self, purpose: Any) -> bool:
        text = str(purpose or "").upper()
        return (
            text
            in {
                self.LONG_ENTRY_PURPOSE,
                self.SHORT_ENTRY_PURPOSE,
                self.LONG_TP_EXIT_PURPOSE,
                self.LONG_TP_EXIT_RECOVERY_PURPOSE,
                self.LONG_SL_EXIT_PURPOSE,
                self.SHORT_TP_EXIT_PURPOSE,
                self.SHORT_SL_EXIT_PURPOSE,
                self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
                self.SHORT_HARD_STOP_PURPOSE,
                "REFILL_LONG",
                "REFILL_SHORT",
                "SHORT_TP_FALLBACK",
            }
            or text.startswith("CYCLE_")
        )

    def _collect_active_refill_order_purposes(
        self,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState,
    ) -> list[str]:
        purposes = {"REFILL_LONG", "REFILL_SHORT"}
        active: list[str] = []
        seen: set[str] = set()

        def _append(purpose: Any, status: Any) -> None:
            purpose_text = str(purpose or "").upper()
            if purpose_text not in purposes:
                return
            if self._is_terminal_order_status(status):
                return
            if purpose_text in seen:
                return
            seen.add(purpose_text)
            active.append(purpose_text)

        for order in runtime_state.active_orders.values():
            _append(getattr(order, "purpose", None), getattr(order, "status", None))
        if snapshot is not None:
            for order in snapshot.active_orders:
                _append(getattr(order, "purpose", None), getattr(order, "status", None))
        return active

    @staticmethod
    def _collect_refill_requested_flags(refill_state: dict[str, Any]) -> list[str]:
        flags: list[str] = []
        if refill_state.get("REQUESTED"):
            flags.append("REQUESTED")
        for purpose in ("REFILL_LONG", "REFILL_SHORT"):
            if refill_state.get(purpose):
                flags.append(purpose)
        return flags

    def _clear_refill_gate_state(
        self,
        runtime_state: RuntimeState,
        *,
        preserve_pending: bool,
    ) -> None:
        state = runtime_state.strategy_state
        state["refill_in_progress"] = False
        state["refill_state"] = {}
        state["refill_intent_registry"] = {}
        state.pop("refill_batch_id", None)
        if not preserve_pending:
            state["refill_pending"] = False
            state["refill_required"] = False
            state["refill_exit_orders_cancel_required"] = False
            previous_cycle_block_status = state.get("cycle_block_status")
            state["cycle_block_status"] = None
            _log_event(
                "fixed_cycle_refill_gate_state_cleared",
                {
                    "symbol": self.config.symbol,
                    "preserve_pending": preserve_pending,
                    "previous_cycle_block_status": previous_cycle_block_status,
                },
            )

    def _reconcile_refill_gate_state(
        self,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState,
        *,
        preserve_pending: bool = True,
    ) -> dict[str, Any]:
        state = runtime_state.strategy_state
        refill_state = state.get("refill_state") or {}
        active_refill_purposes = self._collect_active_refill_order_purposes(snapshot, runtime_state)
        requested_flags = self._collect_refill_requested_flags(refill_state)
        active_refill_orders_count = len(active_refill_purposes)
        refill_pending = bool(state.get("refill_pending"))
        refill_required = bool(state.get("refill_required"))
        refill_in_progress = bool(state.get("refill_in_progress"))
        cycle_block_status = state.get("cycle_block_status")
        before_reconcile = {
            "refill_required": refill_required,
            "refill_pending": refill_pending,
            "refill_in_progress": refill_in_progress,
            "cycle_block_status": cycle_block_status,
            "cycle_block_reason": state.get("cycle_block_reason"),
            "last_refill_completed_cycle_index": state.get("last_refill_completed_cycle_index"),
            "active_cycle_index": state.get("active_cycle_index"),
            "next_required_purpose": state.get("next_required_purpose"),
        }
        pending_registry_entries = self._refill_registry_pending_entries(state)
        stale_detected = False
        if active_refill_orders_count == 0:
            if pending_registry_entries:
                _log_event(
                    "fixed_cycle_refill_waiting_for_registered_intents",
                    {
                        "symbol": self.config.symbol,
                        "refill_batch_id": state.get("refill_batch_id"),
                        "pending_registry_entries": pending_registry_entries,
                        "refill_pending": refill_pending,
                        "refill_in_progress": refill_in_progress,
                    },
                )
            elif (
                (refill_in_progress or requested_flags)
                and bool(state.get("refill_long_filled"))
                and bool(state.get("refill_short_filled"))
            ):
                state["refill_fills_complete"] = True
                state["refill_completion_pending_reconcile"] = True
                _log_event(
                    "fixed_cycle_refill_stale_gate_converted_to_completion_pending",
                    {
                        "symbol": self.config.symbol,
                        "refill_pending": refill_pending,
                        "refill_required": refill_required,
                        "refill_in_progress": refill_in_progress,
                        "requested_flags": requested_flags,
                        "active_refill_orders_count": active_refill_orders_count,
                        "refill_long_filled": bool(state.get("refill_long_filled")),
                        "refill_short_filled": bool(state.get("refill_short_filled")),
                        "refill_fills_complete": bool(state.get("refill_fills_complete")),
                        "refill_completion_pending_reconcile": bool(
                            state.get("refill_completion_pending_reconcile")
                        ),
                    },
                )
            elif refill_in_progress or requested_flags:
                stale_detected = True
            elif (
                cycle_block_status == "REFILL_REQUIRED"
                and not refill_pending
                and not refill_required
                and not refill_in_progress
                and not requested_flags
            ):
                stale_detected = True
                _log_warning_event(
                    "fixed_cycle_stale_refill_block_detected",
                    {
                        "symbol": self.config.symbol,
                        "cycle_block_status": cycle_block_status,
                        "refill_pending": refill_pending,
                        "refill_required": refill_required,
                        "refill_in_progress": refill_in_progress,
                        "requested_flags": requested_flags,
                    },
                )
        details = {
            "cycle_completed_count": state.get("cycle_completed_count"),
            "cycle_pair_count": state.get("cycle_pair_count"),
            "refill_in_progress": bool(state.get("refill_in_progress")),
            "requested_flags": requested_flags,
            "active_refill_purposes": active_refill_purposes,
            "active_refill_orders_count": active_refill_orders_count,
            "stale_detected": stale_detected,
            "bot_state": state.get("bot_state"),
            "refill_pending": bool(state.get("refill_pending")),
        }
        if pending_registry_entries:
            details["pending_registry_entries"] = pending_registry_entries
        if stale_detected:
            _log_warning_event("fixed_cycle_refill_stale_state_reset", details)
            self._clear_refill_gate_state(runtime_state, preserve_pending=preserve_pending)
            details["refill_in_progress"] = False
            details["requested_flags"] = []
            details["active_refill_purposes"] = []
            details["active_refill_orders_count"] = 0
        after_state = {
            "refill_required": bool(state.get("refill_required")),
            "refill_pending": bool(state.get("refill_pending")),
            "refill_in_progress": bool(state.get("refill_in_progress")),
            "cycle_block_status": state.get("cycle_block_status"),
            "cycle_block_reason": state.get("cycle_block_reason"),
            "last_refill_completed_cycle_index": state.get("last_refill_completed_cycle_index"),
            "active_cycle_index": state.get("active_cycle_index"),
            "next_required_purpose": state.get("next_required_purpose"),
        }
        _log_event(
            "fixed_cycle_refill_gate_state_after_reconcile",
            {
                "symbol": self.config.symbol,
                "before": before_reconcile,
                "after": after_state,
                "preserve_pending": preserve_pending,
            },
        )
        return details

    def _refill_registry_pending_entries(
        self, state: dict[str, Any]
    ) -> list[dict[str, Any]]:
        registry = state.get("refill_intent_registry") or {}
        batch_id = state.get("refill_batch_id")
        pending_entries: list[dict[str, Any]] = []
        for purpose, entry in registry.items():
            if batch_id and entry.get("refill_batch_id") != batch_id:
                continue
            if entry.get("status") in {"REQUESTED", "SUBMITTED"}:
                pending_entries.append(
                    {
                        "purpose": purpose,
                        "status": entry.get("status"),
                        "qty": entry.get("qty"),
                        "created_at_ms": entry.get("created_at_ms"),
                    }
                )
        return pending_entries

    def _prepare_refill_batch_for_new_intents(
        self, state: dict[str, Any]
    ) -> tuple[str, dict[str, Any]]:
        registry = state.setdefault("refill_intent_registry", {})
        batch_id = state.get("refill_batch_id")
        if not registry:
            batch_id = str(uuid4())
            state["refill_batch_id"] = batch_id
        elif not batch_id:
            batch_id = str(uuid4())
            state["refill_batch_id"] = batch_id
        return batch_id, registry

    def _register_refill_intent(
        self,
        state: dict[str, Any],
        purpose: str,
        qty: float,
        order_type: str,
        trigger_price: float | None,
    ) -> dict[str, Any]:
        registry = state.setdefault("refill_intent_registry", {})
        batch_id = state.get("refill_batch_id")
        entry = {
            "status": "REQUESTED",
            "qty": float(qty or 0.0),
            "order_type": order_type,
            "trigger_price": trigger_price,
            "refill_batch_id": batch_id,
            "created_at_ms": _current_time_ms(),
        }
        registry[purpose] = entry
        return entry

    def _refill_registry_entry(
        self, state: dict[str, Any], purpose: str
    ) -> dict[str, Any] | None:
        registry = state.get("refill_intent_registry") or {}
        entry = registry.get(purpose)
        if not entry or entry.get("refill_batch_id") != state.get("refill_batch_id"):
            return None
        return entry

    def _update_refill_registry_status(
        self,
        state: dict[str, Any],
        purpose: str,
        status: str,
        **fields: Any,
    ) -> dict[str, Any] | None:
        registry = state.get("refill_intent_registry") or {}
        entry = registry.get(purpose)
        if not entry or entry.get("refill_batch_id") != state.get("refill_batch_id"):
            return None
        entry.update(
            {key: value for key, value in fields.items() if value is not None}
        )
        entry["status"] = status
        return entry

    def _clear_refill_intent_registry(self, state: dict[str, Any]) -> None:
        state["refill_intent_registry"] = {}
        state.pop("refill_batch_id", None)

    def _maybe_reset_stale_refill_state(
        self,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState,
    ) -> bool:
        details = self._reconcile_refill_gate_state(snapshot, runtime_state)
        return bool(details.get("stale_detected"))

    def _is_final_exit_only_order(self, order: Any) -> bool:
        purpose = str(getattr(order, "purpose", "") or "").upper()
        reduce_only = bool(getattr(order, "reduce_only", False))
        final_exit_purposes = {
            self.LONG_TP_EXIT_PURPOSE,
            self.LONG_TP_EXIT_RECOVERY_PURPOSE,
            self.LONG_SL_EXIT_PURPOSE,
            self.SHORT_TP_EXIT_PURPOSE,
            self.SHORT_SL_EXIT_PURPOSE,
            self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
            self.SHORT_HARD_STOP_PURPOSE,
            "FINAL_LONG_EXIT",
            "FINAL_SHORT_EXIT",
        }
        if purpose in final_exit_purposes:
            return True
        return bool(
            reduce_only
            and "EXIT" in purpose
            and not purpose.startswith("CYCLE_")
            and not purpose.startswith("INITIAL_")
            and not purpose.startswith("REFILL_")
        )

    def _only_final_exit_orders_remain(self, active_orders: list[Any]) -> bool:
        return bool(active_orders) and all(self._is_final_exit_only_order(order) for order in active_orders)

    def _is_unsettled_strategy_order(self, order: Any) -> bool:
        purpose = getattr(order, "purpose", None)
        if not self._is_strategy_order_purpose(purpose):
            return False
        remaining_qty = float(getattr(order, "remaining_qty", 0.0) or 0.0)
        if remaining_qty > 1e-9:
            return True
        return not self._is_terminal_order_status(getattr(order, "status", None))

    def _clear_final_exit_trading_stop_state(self, state: dict[str, Any]) -> None:
        state.pop("final_exit_trading_stop_active", None)
        state.pop("final_exit_trading_stop_signature", None)
        state.pop("final_exit_trading_stop_long_tp", None)
        state.pop("final_exit_trading_stop_short_sl", None)
        state.pop("final_exit_trading_stop_context", None)
        state.pop("final_exit_context_missing_but_flat_confirmed", None)
        state.pop("final_exit_fallback_reason", None)
        state.pop("final_exit_fallback_applied_at", None)

    def _record_final_exit_trading_stop_submission(
        self,
        runtime_state: RuntimeState,
        snapshot: HedgeSnapshot | None,
        *,
        purpose: str,
        side: str,
        client_order_id: str | None,
        exchange_order_id: str | None,
        trigger_price: float | None,
        position_idx: int | None,
    ) -> None:
        state = runtime_state.strategy_state
        symbol = str((snapshot.symbol if snapshot else None) or self.config.symbol or "")
        trade_block_id = state.get("trade_block_id")
        now_ms = _current_time_ms()
        now_iso = datetime.now(timezone.utc).isoformat()
        existing_context = state.get("final_exit_trading_stop_context") or {}
        if (
            existing_context.get("trade_block_id") != trade_block_id
            or str(existing_context.get("symbol") or "").upper() != symbol.upper()
        ):
            existing_context = {}

        context = {
            **existing_context,
            "symbol": symbol,
            "trade_block_id": trade_block_id,
            "set_time_ms": int(existing_context.get("set_time_ms") or now_ms),
            "set_time": existing_context.get("set_time") or now_iso,
            "flat_detected_time_ms": existing_context.get("flat_detected_time_ms"),
            "flat_detected_at": existing_context.get("flat_detected_at"),
            "final_long_exit_purpose": self._get_final_long_exit_purpose(),
            "final_short_exit_purpose": self._get_final_short_exit_purpose(),
            "long_position_idx": 1,
            "short_position_idx": 2,
            "long_expected_side": "Sell",
            "short_expected_side": "Buy",
            "long_qty_before": float(
                existing_context.get("long_qty_before")
                if existing_context.get("long_qty_before") is not None
                else (snapshot.long_qty if snapshot else 0.0)
            ),
            "short_qty_before": float(
                existing_context.get("short_qty_before")
                if existing_context.get("short_qty_before") is not None
                else (snapshot.short_qty if snapshot else 0.0)
            ),
        }
        side_key = "long" if str(side or "").lower() == "long" else "short"
        expected_purpose = (
            self._get_final_long_exit_purpose()
            if side_key == "long"
            else self._get_final_short_exit_purpose()
        )
        expected_side = "Sell" if side_key == "long" else "Buy"
        if side_key == "long" and snapshot is not None:
            context["long_qty_before"] = float(snapshot.long_qty or 0.0)
        if side_key == "short" and snapshot is not None:
            context["short_qty_before"] = float(snapshot.short_qty or 0.0)
        context[f"{side_key}_submission"] = {
            "purpose": expected_purpose,
            "client_order_id": str(client_order_id or ""),
            "exchange_order_id": str(exchange_order_id or ""),
            "trigger_price": float(trigger_price or 0.0),
            "position_idx": int(position_idx or (1 if side_key == "long" else 2)),
            "set_time_ms": now_ms,
            "set_time": now_iso,
        }
        state["final_exit_trading_stop_context"] = context
        order_context = {
            "symbol": symbol,
            "side": side_key,
            "purpose": expected_purpose,
            "exchange_order_id": str(exchange_order_id or ""),
            "client_order_id": str(client_order_id or ""),
            "exec_id": "",
            "exec_price": float(trigger_price or 0.0),
            "exec_qty": float(
                context.get("long_qty_before" if side_key == "long" else "short_qty_before") or 0.0
            ),
            "trigger_price": float(trigger_price or 0.0),
            "basket_tp_price": 0.0,
            "basket_break_even_price": 0.0,
            "occurred_at": now_iso,
            "source": "trading_stop_submission",
            "position_idx": int(position_idx or (1 if side_key == "long" else 2)),
            "expected_side": expected_side,
            "trade_block_id": trade_block_id,
            "set_time_ms": int(context.get("set_time_ms") or now_ms),
        }
        if side_key == "long":
            state["final_long_exit_order_context"] = order_context
        else:
            state["final_short_exit_order_context"] = order_context
        _log_event(
            "fixed_cycle_trading_stop_final_exit_context_recorded",
            {
                "symbol": symbol,
                "trade_block_id": trade_block_id,
                "side": side_key,
                "purpose": expected_purpose,
                "position_idx": order_context["position_idx"],
                "qty_before": order_context["exec_qty"],
                "set_time_ms": order_context["set_time_ms"],
            },
        )

    def _mark_trading_stop_flat_detected(
        self,
        state: dict[str, Any],
        *,
        symbol: str,
        reason: str,
        long_qty: float,
        short_qty: float,
    ) -> dict[str, Any]:
        context = dict(state.get("final_exit_trading_stop_context") or {})
        if not context:
            return context
        if not context.get("flat_detected_time_ms"):
            context["flat_detected_time_ms"] = _current_time_ms()
            context["flat_detected_at"] = datetime.now(timezone.utc).isoformat()
            state["final_exit_trading_stop_context"] = context
            _log_event(
                "fixed_cycle_trading_stop_final_exit_flat_state_recorded",
                {
                    "symbol": symbol,
                    "reason": reason,
                    "trade_block_id": context.get("trade_block_id"),
                    "long_qty": float(long_qty or 0.0),
                    "short_qty": float(short_qty or 0.0),
                    "flat_detected_time_ms": context.get("flat_detected_time_ms"),
                },
            )
        return context

    def _finalize_trading_stop_basket_exit(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        reason: str,
        unsettled_runtime_orders: list[dict[str, Any]] | None = None,
        unsettled_snapshot_orders: list[dict[str, Any]] | None = None,
    ) -> bool:
        """
        Finalisiert einen über Trading-Stop ausgelösten Basket-Exit, sobald beide
        Positionen flat sind.

        Ziel:
        - Trading-Stop-Flat-Zeitpunkt festhalten
        - logische Trading-Stop-Exit-Orders aus dem Runtime-State entfernen
        - verbliebene Cycle-/Reduce-Orders bei flat Position bereinigen
        - einen Block-Close-Analyzer-Event emittieren
        - einen frischen Restart erlauben, auch wenn Exit-Kontext/PnL noch nicht
          vollständig auditierbar ist.
        """
        state = runtime_state.strategy_state
        if not state.get("final_exit_trading_stop_active"):
            return False
        if snapshot.long_qty > 0 or snapshot.short_qty > 0:
            return False
        unsettled_runtime_orders = unsettled_runtime_orders or []
        unsettled_snapshot_orders = unsettled_snapshot_orders or []
        trading_stop_context = self._mark_trading_stop_flat_detected(
            state,
            symbol=self.config.symbol,
            reason=reason,
            long_qty=float(snapshot.long_qty or 0.0),
            short_qty=float(snapshot.short_qty or 0.0),
        )
        if trading_stop_context.get("flat_detected_time_ms") and not unsettled_runtime_orders and not unsettled_snapshot_orders:
            if state.get("final_exit_context_missing_but_flat_confirmed"):
                return False

        active_runtime_summaries = list(unsettled_runtime_orders)
        active_snapshot_summaries = list(unsettled_snapshot_orders)

        _log_event(
            "fixed_cycle_trading_stop_final_exit_flat_detected",
            {
                "symbol": self.config.symbol,
                "reason": reason,
                "long_qty": float(snapshot.long_qty or 0.0),
                "short_qty": float(snapshot.short_qty or 0.0),
                "unsettled_runtime_orders": active_runtime_summaries,
                "unsettled_snapshot_orders": active_snapshot_summaries,
            },
        )
        _log_event(
            "fixed_cycle_trading_stop_final_exit_finalize_started",
            {
                "symbol": self.config.symbol,
                "reason": reason,
                "trade_block_id": state.get("trade_block_id"),
                "last_trade_block_id": state.get("last_trade_block_id"),
            },
        )

        # 1) Trading-Stop-basierte Exit-Orders (LONG_TP_EXIT/SHORT_SL_EXIT) aus
        # dem Runtime-State entfernen.
        removed_trading_stop_orders: list[dict[str, Any]] = []
        to_remove_ts: list[str] = []
        for client_id, order in runtime_state.active_orders.items():
            metadata = getattr(order, "metadata", None) or {}
            if metadata.get("trading_stop_api"):
                removed_trading_stop_orders.append(self._strategy_order_summary(order))
                to_remove_ts.append(client_id)
        for client_id in to_remove_ts:
            order = runtime_state.active_orders.pop(client_id, None)
            if order and getattr(order, "exchange_order_id", None):
                runtime_state.exchange_to_client_id.pop(order.exchange_order_id, None)

        # 2) Verbliebene offene Cycle-/Reduce-Orders bei flat Position bereinigen,
        # damit sie den Flat-Reset nicht blockieren.
        removed_cycle_orders: list[dict[str, Any]] = []
        cycle_purposes: set[str] = set()
        for client_id, order in list(runtime_state.active_orders.items()):
            purpose = str(getattr(order, "purpose", "") or "").upper()
            if not purpose.startswith("CYCLE_"):
                continue
            cycle_purposes.add(purpose)
            removed_cycle_orders.append(self._strategy_order_summary(order))
            runtime_state.active_orders.pop(client_id, None)
            if getattr(order, "exchange_order_id", None):
                runtime_state.exchange_to_client_id.pop(order.exchange_order_id, None)
        if cycle_purposes and context.cancel_open_orders_by_purpose:
            try:
                context.cancel_open_orders_by_purpose(sorted(cycle_purposes))
            except Exception as exc:  # pragma: no cover - reine Diagnose
                logger.exception(
                    "fixed_cycle_trading_stop_cycle_cancel_failed %s",
                    {
                        "symbol": self.config.symbol,
                        "cycle_purposes": sorted(cycle_purposes),
                        "error": str(exc),
                    },
                )

        # 3) Trading-Stop-Marker bewusst NICHT sofort zurücksetzen.
        # Die finale Closed-PnL muss ggf. erst im Flat-Reconcile per REST geholt werden.

        # 4) Analyzer-Block schließen, auch ohne klassischen Exit-Order-Kontext.
        if not state.get("block_closed_marker_emitted"):
            cycle_index = int(state.get("current_effective_cycle") or 0)
            payload = {
                "symbol": self.config.symbol,
                "strategy": self.name,
                "cycle_index": cycle_index,
                "positions_flat": True,
                "long_final_size": float(snapshot.long_qty or 0.0),
                "short_final_size": float(snapshot.short_qty or 0.0),
                "long_realized_pnl": float(snapshot.realized_long_pnl_total or 0.0),
                "short_realized_pnl": float(snapshot.realized_short_pnl_total or 0.0),
                "net_realized_pnl": float(snapshot.realized_pnl_total or 0.0),
                "trading_stop_final_exit": True,
                "reason": reason,
            }
            _emit_analyzer_event(logger, "analyzer_block_closed", payload)
            state["block_closed_marker_emitted"] = True

        # 5) PnL-Kontext ggf. nachgelagert erlauben, aber Flat-Reset nicht blockieren.
        state["fresh_restart_required"] = True
        state["final_exit_pnl_deferred_allows_fresh_entry"] = True
        state["final_exit_context_missing_but_flat_confirmed"] = True
        state["final_exit_fallback_reason"] = "trading_stop_flat_exit"
        state["final_exit_fallback_applied_at"] = datetime.now(timezone.utc).isoformat()
        _log_event(
            "fixed_cycle_trading_stop_final_exit_pnl_deferred_flat_reset_allowed",
            {
                "symbol": self.config.symbol,
                "reason": reason,
                "trade_block_id": (trading_stop_context or {}).get("trade_block_id"),
                "long_qty": float(snapshot.long_qty or 0.0),
                "short_qty": float(snapshot.short_qty or 0.0),
                "removed_trading_stop_orders": removed_trading_stop_orders,
                "removed_cycle_orders": removed_cycle_orders,
            },
        )

        # 6) Sofort versuchen, den finalen Exit-PnL über den bestehenden Fetch-Pfad
        # zu ermitteln, bevor der normale Flat-Reset-/Cleanup-Pfad weiterläuft.
        self._emit_final_trade_pnl_if_complete_or_fetch(
            runtime_state,
            context,
            reason="trading_stop_flat_exit",
        )

        # 7) Post-Exit-Cleanup anfordern, damit der normale Flat-Reset-Pfad greifen kann.
        self._ensure_post_exit_cleanup_required(
            runtime_state, reason="trading_stop_flat_exit"
        )

        return True

    @staticmethod
    def _strategy_order_summary(order: Any) -> dict[str, Any]:
        return {
            "client_order_id": getattr(order, "client_order_id", None),
            "exchange_order_id": getattr(order, "exchange_order_id", None),
            "purpose": getattr(order, "purpose", None),
            "status": getattr(order, "status", None),
            "filled_qty": float(getattr(order, "filled_qty", 0.0) or 0.0),
            "remaining_qty": float(getattr(order, "remaining_qty", 0.0) or 0.0),
            "qty": float(getattr(order, "qty", 0.0) or 0.0),
        }

    def _collect_unsettled_strategy_orders(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        unsettled_runtime_orders = [
            self._strategy_order_summary(order)
            for order in runtime_state.active_orders.values()
            if self._is_unsettled_strategy_order(order)
        ]
        unsettled_snapshot_orders = [
            self._strategy_order_summary(order)
            for order in snapshot.active_orders
            if self._is_unsettled_strategy_order(order)
        ]
        return unsettled_runtime_orders, unsettled_snapshot_orders

    def _force_cleanup_flat_final_exit_orders(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        reason: str,
    ) -> bool:
        state = runtime_state.strategy_state
        active_snapshot_orders = [
            order for order in snapshot.active_orders if self._is_unsettled_strategy_order(order)
        ]
        active_runtime_orders = [
            order for order in runtime_state.active_orders.values() if self._is_unsettled_strategy_order(order)
        ]
        remaining_orders = [*active_snapshot_orders, *active_runtime_orders]
        if not self._only_final_exit_orders_remain(remaining_orders):
            return False

        symbol = context.symbol or self.config.symbol
        category = context.category or self.config.category
        canceled_exchange_order_ids: list[str] = []
        cancel_errors: list[dict[str, Any]] = []
        seen_exchange_order_ids: set[str] = set()
        for order in remaining_orders:
            exchange_order_id = str(getattr(order, "exchange_order_id", "") or "")
            status = str(getattr(order, "status", "") or "").upper()
            if (
                exchange_order_id
                and exchange_order_id not in seen_exchange_order_ids
                and not self._is_terminal_order_status(status)
                and context.order_manager
            ):
                seen_exchange_order_ids.add(exchange_order_id)
                try:
                    context.order_manager.cancel_order(
                        exchange_order_id,
                        symbol=symbol,
                        category=category,
                    )
                    canceled_exchange_order_ids.append(exchange_order_id)
                except Exception as exc:
                    cancel_errors.append(
                        {
                            "exchange_order_id": exchange_order_id,
                            "error": str(exc),
                        }
                    )

        removed_orders: list[dict[str, Any]] = []
        for client_order_id, managed_order in list(runtime_state.active_orders.items()):
            if not self._is_unsettled_strategy_order(managed_order):
                continue
            if not self._is_final_exit_only_order(managed_order):
                continue
            removed_orders.append(self._strategy_order_summary(managed_order))
            runtime_state.active_orders.pop(client_order_id, None)
            if managed_order.exchange_order_id:
                runtime_state.exchange_to_client_id.pop(managed_order.exchange_order_id, None)
            _log_event(
                "fixed_cycle_post_exit_state_order_terminalized",
                {
                    "symbol": symbol,
                    "category": category,
                    "client_order_id": client_order_id,
                    "exchange_order_id": getattr(managed_order, "exchange_order_id", None),
                    "purpose": getattr(managed_order, "purpose", None),
                    "status": getattr(managed_order, "status", None),
                    "filled_qty": float(getattr(managed_order, "filled_qty", 0.0) or 0.0),
                    "remaining_qty": float(getattr(managed_order, "remaining_qty", 0.0) or 0.0),
                    "reason": reason,
                },
            )

        state["exit_locked"] = False
        state["exit_rebuild_allowed"] = False
        state["force_exit_rebuild"] = False
        state["long_exit_filled"] = False
        state["short_exit_filled"] = False
        state["short_exit_recovery_submitted"] = False
        state["long_exit_recovery_submitted"] = False
        state["exit_recovery_marker"] = False
        state.pop("flat_waiting_order_cleanup_logged", None)
        _log_event(
            "fixed_cycle_flat_final_exit_order_cleanup_forced",
            {
                "reason": reason,
                "long_qty": snapshot.long_qty,
                "short_qty": snapshot.short_qty,
                "canceled_exchange_order_ids": canceled_exchange_order_ids,
                "cancel_errors": cancel_errors,
                "removed_orders": removed_orders,
                "remaining_snapshot_orders": [
                    self._strategy_order_summary(order) for order in active_snapshot_orders
                ],
            },
        )
        return True

    def _collect_active_strategy_order_purposes(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> tuple[list[str], list[str]]:
        active_snapshot_order_purposes: list[str] = []
        active_runtime_order_purposes: list[str] = []
        for order in snapshot.active_orders:
            if not self._is_unsettled_strategy_order(order):
                continue
            purpose = getattr(order, "purpose", None)
            active_snapshot_order_purposes.append(
                str(purpose or getattr(order, "client_order_id", None) or "")
            )
        for order in runtime_state.active_orders.values():
            if not self._is_unsettled_strategy_order(order):
                continue
            purpose = getattr(order, "purpose", None)
            active_runtime_order_purposes.append(
                str(purpose or getattr(order, "client_order_id", None) or "")
            )
        return active_snapshot_order_purposes, active_runtime_order_purposes

    def _has_active_strategy_orders(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> bool:
        active_snapshot_order_purposes, active_runtime_order_purposes = (
            self._collect_active_strategy_order_purposes(snapshot, runtime_state)
        )
        return bool(active_snapshot_order_purposes or active_runtime_order_purposes)

    def _release_exit_lock_if_unprotected_open_position(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        reason: str,
    ) -> bool:
        state = runtime_state.strategy_state
        if snapshot.long_qty <= 0 and snapshot.short_qty <= 0:
            return False
        snapshot_purposes, runtime_purposes = self._collect_active_final_exit_purposes(
            snapshot, runtime_state
        )
        if snapshot_purposes or runtime_purposes:
            state.pop("unprotected_open_position_first_seen_ms", None)
            return False

        exit_locked_before = bool(state.get("exit_locked"))
        exit_rebuild_allowed_before = bool(state.get("exit_rebuild_allowed", True))
        signature_before = bool(state.get("last_exit_signature"))
        refill_orders_active = any(
            "REFILL" in str(getattr(order, "purpose", "") or "").upper()
            for order in (*snapshot.active_orders, *runtime_state.active_orders.values())
        )
        refill_active = self._is_refill_mode_active(state) or refill_orders_active
        if (
            (exit_locked_before or not exit_rebuild_allowed_before or signature_before)
            and not refill_active
        ):
            state["exit_locked"] = False
            state["exit_rebuild_allowed"] = True
            state["force_exit_rebuild"] = True
            state["last_exit_signature"] = None
            state["pending_loss_exit_old_signature"] = None
            state["pending_loss_exit_rebuild_reason"] = "stale_exit_lock_cleared"
            payload = {
                "symbol": snapshot.symbol or self.config.symbol,
                "long_qty": snapshot.long_qty,
                "short_qty": snapshot.short_qty,
                "active_order_purposes": [
                    getattr(order, "purpose", None)
                    for order in runtime_state.active_orders.values()
                ],
                "snapshot_active_order_purposes": [
                    getattr(order, "purpose", None)
                    for order in snapshot.active_orders
                ],
                "exit_locked_before": exit_locked_before,
                "exit_rebuild_allowed_before": exit_rebuild_allowed_before,
                "last_exit_signature_present_before": signature_before,
                "refill_pending": bool(state.get("refill_pending")),
                "refill_required": bool(state.get("refill_required")),
                "refill_in_progress": bool(state.get("refill_in_progress")),
                "reason": reason,
            }
            context.audit.log_event("fixed_cycle_stale_exit_lock_released_for_unprotected_position", **payload)
            return True
        if (
            (exit_locked_before or not exit_rebuild_allowed_before or signature_before)
            and refill_active
        ):
            payload = {
                "symbol": snapshot.symbol or self.config.symbol,
                "long_qty": snapshot.long_qty,
                "short_qty": snapshot.short_qty,
                "refill_pending": bool(state.get("refill_pending")),
                "refill_required": bool(state.get("refill_required")),
                "refill_in_progress": bool(state.get("refill_in_progress")),
                "refill_orders_active": refill_orders_active,
                "reason": reason,
            }
            context.audit.log_event("fixed_cycle_stale_exit_lock_release_skipped_refill_active", **payload)
        return False

    def _has_active_order_for_purpose(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        purpose: str,
    ) -> bool:
        normalized = (purpose or "").upper()
        for order in snapshot.active_orders:
            order_purpose = str(getattr(order, "purpose", "") or "").upper()
            if order_purpose == normalized and not self._is_terminal_order_status(
                getattr(order, "status", None)
            ):
                return True
        for order in runtime_state.active_orders.values():
            order_purpose = str(getattr(order, "purpose", "") or "").upper()
            if order_purpose == normalized and not self._is_terminal_order_status(
                getattr(order, "status", None)
            ):
                return True
        return False

    def _iter_active_orders_for_purpose(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        purpose: str,
    ):
        normalized = (purpose or "").upper()
        for order in snapshot.active_orders:
            order_purpose = str(getattr(order, "purpose", "") or "").upper()
            if order_purpose == normalized and not self._is_terminal_order_status(
                getattr(order, "status", None)
            ):
                yield order
        for order in runtime_state.active_orders.values():
            order_purpose = str(getattr(order, "purpose", "") or "").upper()
            if order_purpose == normalized and not self._is_terminal_order_status(
                getattr(order, "status", None)
            ):
                yield order

    def _missing_normal_split_stage_indices(
        self,
        state: dict[str, Any],
        runtime_state: RuntimeState,
        snapshot: HedgeSnapshot,
        *,
        cycle_index: int,
        purpose: str,
        cycle_role: str,
    ) -> list[int]:
        cycle_key = str(cycle_index)
        stage_count_map = state.get("normal_cycle_second_leg_split_stage_count") or {}
        filled_map = state.get("normal_cycle_second_leg_split_filled_stages") or {}
        stage_count = int(stage_count_map.get(cycle_key) or 0)
        filled_stages = {int(idx) for idx in (filled_map.get(cycle_key) or [])}
        active_stage_indices: set[int] = set()

        for order in self._iter_active_orders_for_purpose(snapshot, runtime_state, purpose):
            metadata = getattr(order, "metadata", None)
            metadata = metadata if isinstance(metadata, dict) else {}
            if not bool(metadata.get("normal_cycle_second_leg_split")):
                continue
            try:
                split_stage_index = int(metadata.get("split_stage_index"))
            except (TypeError, ValueError):
                continue
            active_stage_indices.add(split_stage_index)
            if stage_count <= 0:
                try:
                    stage_count = int(
                        metadata.get("split_stage_count") or metadata.get("stage_count") or 0
                    )
                except (TypeError, ValueError):
                    stage_count = 0

        if stage_count <= 0:
            return []

        covered = filled_stages | active_stage_indices
        return sorted(idx for idx in range(stage_count) if idx not in covered)

    def _should_attach_replace_open_purpose(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        purpose: str,
        *,
        cycle_index: int | None = None,
        cycle_role: str | None = None,
    ) -> bool:
        state = runtime_state.strategy_state
        if state.get("exit_orders_submitted_once"):
            if cycle_index is not None:
                missing_stages = self._missing_normal_split_stage_indices(
                    state,
                    runtime_state,
                    snapshot,
                    cycle_index=cycle_index,
                    purpose=purpose,
                    cycle_role=cycle_role or self._get_second_leg_cycle_role(),
                )
                if missing_stages:
                    return False
            return True
        if cycle_index is not None:
            missing_stages = self._missing_normal_split_stage_indices(
                state,
                runtime_state,
                snapshot,
                cycle_index=cycle_index,
                purpose=purpose,
                cycle_role=cycle_role or self._get_second_leg_cycle_role(),
            )
            if missing_stages:
                return False
        return self._has_active_order_for_purpose(snapshot, runtime_state, purpose)

    def _short_followup_pending_in_intents(
        self,
        cycle_index: int,
        pending_intents: list[StrategyIntent] | None,
    ) -> bool:
        if cycle_index <= 0 or not pending_intents:
            return False
        expected_purpose = self._normalize_cycle_purpose(self._cycle_purpose("short", cycle_index))
        for intent in pending_intents:
            intent_purpose = self._normalize_cycle_purpose(getattr(intent, "purpose", "") or "")
            if intent_purpose == expected_purpose:
                return True
        return False

    def _mark_exit_orders_stale_after_structure_fill(
        self,
        runtime_state: RuntimeState,
        *,
        fill_event: FillEvent,
        cycle_index: int,
        structure_segment: str,
    ) -> None:
        state = runtime_state.strategy_state
        state["force_exit_rebuild"] = True
        state["exit_rebuild_allowed"] = True
        state["exit_orders_stale_after_structure_fill"] = True
        _log_event(
            "fixed_cycle_exit_orders_marked_stale_after_structure_fill",
            {
                "symbol": self.config.symbol,
                "purpose": fill_event.purpose,
                "structure_segment": structure_segment,
                "cycle_index": cycle_index,
                "force_exit_rebuild": True,
                "exit_rebuild_allowed": True,
            },
        )

    def _block_flat_restart_until_final_pnl(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        reason: str,
    ) -> bool:
        if snapshot.long_qty > 0 or snapshot.short_qty > 0:
            return False
        state = runtime_state.strategy_state
        final_long_context_present = bool(state.get("final_long_exit_order_context"))
        final_short_context_present = bool(state.get("final_short_exit_order_context"))
        audit_pnl_ledger = state.get("audit_pnl_ledger") or {}
        active_snapshot_order_purposes, active_runtime_order_purposes = (
            self._collect_active_strategy_order_purposes(snapshot, runtime_state)
        )
        fallback_marker = bool(state.get("final_exit_context_missing_but_flat_confirmed"))
        last_exit_signature = state.get("last_exit_signature")
        latest_tp_price = float(state.get("latest_tp_price") or 0.0)
        latest_break_even_price = float(state.get("latest_break_even_price") or 0.0)
        active_order_count = len(active_snapshot_order_purposes) + len(active_runtime_order_purposes)
        trade_evidence_present = (
            self._previous_trade_evidence_present(runtime_state)
            or any(
                [
                    float(runtime_state.realized_long_pnl_total or 0.0) != 0.0,
                    float(runtime_state.realized_short_pnl_total or 0.0) != 0.0,
                ]
            )
            or fallback_marker
        )
        flat_snapshot = snapshot.long_qty <= 0 and snapshot.short_qty <= 0
        no_active_strategy_orders = (
            not snapshot.active_orders
            and not runtime_state.active_orders
            and not active_snapshot_order_purposes
            and not active_runtime_order_purposes
        )
        missing_final_context = not (final_long_context_present and final_short_context_present)
        has_final_exit_signature = bool(last_exit_signature)
        had_final_exit_structure = bool(state.get("exit_orders_submitted_once")) or has_final_exit_signature
        has_exit_prices = latest_tp_price > 0 or latest_break_even_price > 0
        if (
            flat_snapshot
            and no_active_strategy_orders
            and missing_final_context
            and not fallback_marker
            and has_final_exit_signature
            and had_final_exit_structure
            and has_exit_prices
        ):
            state["final_exit_context_missing_but_flat_confirmed"] = True
            state["final_exit_fallback_reason"] = "flat_snapshot_after_unmatched_final_exit"
            state["final_exit_fallback_applied_at"] = datetime.now(timezone.utc).isoformat()
            _log_event(
                "fixed_cycle_flat_finalization_fallback_without_exit_context",
                {
                    "symbol": self.config.symbol,
                    "reason": "flat_snapshot_after_unmatched_final_exit",
                    "last_exit_signature": last_exit_signature,
                    "latest_tp_price": latest_tp_price,
                    "latest_break_even_price": latest_break_even_price,
                    "final_long_exit_order_context_present": final_long_context_present,
                    "final_short_exit_order_context_present": final_short_context_present,
                    "active_order_count": active_order_count,
                    "active_order_purposes": active_snapshot_order_purposes + active_runtime_order_purposes,
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                },
            )
            state["fresh_restart_required"] = True
            _log_event(
                "fixed_cycle_final_pnl_unknown_but_flat_restart_allowed",
                {
                    "symbol": self.config.symbol,
                    "reason": "flat_snapshot_after_unmatched_final_exit",
                    "final_long_exit_order_context_present": final_long_context_present,
                    "final_short_exit_order_context_present": final_short_context_present,
                },
            )
            fallback_marker = True
            trade_evidence_present = True

        if (
            snapshot.long_qty <= 0
            and snapshot.short_qty <= 0
            and not snapshot.active_orders
            and not runtime_state.active_orders
            and not active_snapshot_order_purposes
            and not active_runtime_order_purposes
            and not state.get("verified_flat_runtime_reset_done")
        ):
            if context and self._perform_verified_flat_runtime_reset(
                snapshot=snapshot,
                runtime_state=runtime_state,
                context=context,
                reason=f"{reason}_flat_state_reset",
                allow_unknown_final_pnl=True,
            ):
                _log_event(
                    "fixed_cycle_pre_entry_flat_state_clean_reset_applied",
                    {
                        "reason": f"{reason}_flat_state_reset",
                        "symbol": self.config.symbol,
                        "long_qty": snapshot.long_qty,
                        "short_qty": snapshot.short_qty,
                    },
                )
                return False
        if state.get("verified_flat_runtime_reset_done"):
            if (
                snapshot.long_qty <= 0
                and snapshot.short_qty <= 0
                and not self._has_nonterminal_snapshot_orders(snapshot)
                and not self._has_nonterminal_runtime_orders(runtime_state)
            ):
                return False
        if active_snapshot_order_purposes or active_runtime_order_purposes:
            if (
                bool(state.get("fresh_restart_required"))
                and self._final_pnl_ready_for_restart(runtime_state)
                and self._force_cleanup_flat_final_exit_orders(
                    snapshot,
                    runtime_state,
                    context,
                    reason=reason,
                )
            ):
                active_snapshot_order_purposes = []
                active_runtime_order_purposes = []
            else:
                if trade_evidence_present:
                    self._emit_final_trade_pnl_if_complete_or_fetch(runtime_state, context, reason)
                state.pop("flat_waiting_final_pnl_logged", None)
                state.pop("flat_final_pnl_ready_logged", None)
                if not state.get("flat_waiting_order_cleanup_logged"):
                    pnl_ready_for_current_trade = self._final_pnl_ready_for_restart(runtime_state)
                    _log_event(
                        "fixed_cycle_flat_waiting_for_order_cleanup",
                        {
                            "reason": reason,
                            "long_qty": snapshot.long_qty,
                            "short_qty": snapshot.short_qty,
                            "active_snapshot_order_purposes": active_snapshot_order_purposes,
                            "active_runtime_order_purposes": active_runtime_order_purposes,
                            "final_trade_pnl_audited": state.get("final_trade_pnl_audited"),
                            "final_long_exit_audited": state.get("final_long_exit_audited"),
                            "final_short_exit_audited": state.get("final_short_exit_audited"),
                            "last_trade_pnl_complete": state.get("last_trade_pnl_complete"),
                            "last_trade_pnl_usdt": state.get("last_trade_pnl_usdt"),
                            "final_long_exit_order_context_present": final_long_context_present,
                            "final_short_exit_order_context_present": final_short_context_present,
                            "trade_block_id": state.get("trade_block_id"),
                            "last_trade_block_id": state.get("last_trade_block_id"),
                            "pnl_ready_for_current_trade": pnl_ready_for_current_trade,
                        },
                    )
                    state["flat_waiting_order_cleanup_logged"] = True
                state["bot_state"] = self.STATE_EXITED
                state["fresh_restart_required"] = True
                return True
        state.pop("flat_waiting_order_cleanup_logged", None)
        if not trade_evidence_present:
            state.pop("flat_waiting_final_pnl_logged", None)
            state.pop("flat_final_pnl_ready_logged", None)
            state.pop("final_pnl_context_missing_logged", None)
            return False

        self._emit_final_trade_pnl_if_complete_or_fetch(runtime_state, context, reason)
        if not self._final_pnl_ready_for_restart(runtime_state):
            if (
                (
                    final_long_context_present
                    or final_short_context_present
                    or bool(state.get("final_long_exit_audited"))
                    or bool(state.get("final_short_exit_audited"))
                    or float(audit_pnl_ledger.get("final_long_exit_pnl") or 0.0) != 0.0
                    or float(audit_pnl_ledger.get("final_short_exit_pnl") or 0.0) != 0.0
                    or bool(state.get("last_trade_block_id"))
                )
                and (not final_long_context_present or not final_short_context_present)
                and not state.get("final_pnl_context_missing_logged")
            ):
                _log_warning_event(
                    "fixed_cycle_final_pnl_context_missing",
                    {
                        "reason": reason,
                        "final_long_exit_order_context_present": final_long_context_present,
                        "final_short_exit_order_context_present": final_short_context_present,
                        "active_snapshot_order_purposes": active_snapshot_order_purposes,
                        "active_runtime_order_purposes": active_runtime_order_purposes,
                        "last_fill_info": state.get("last_fill_info"),
                        "audit_pnl_ledger": audit_pnl_ledger,
                        "trade_block_id": state.get("trade_block_id"),
                        "last_trade_block_id": state.get("last_trade_block_id"),
                        "pnl_ready_for_current_trade": self._final_pnl_ready_for_restart(runtime_state),
                    },
                )
                state["final_pnl_context_missing_logged"] = True
            state.pop("flat_final_pnl_ready_logged", None)
            if not state.get("flat_waiting_final_pnl_logged"):
                pnl_ready_for_current_trade = self._final_pnl_ready_for_restart(runtime_state)
                _log_event(
                    "fixed_cycle_flat_waiting_for_final_pnl",
                    {
                        "reason": reason,
                        "final_trade_pnl_audited": state.get("final_trade_pnl_audited"),
                        "final_long_exit_audited": state.get("final_long_exit_audited"),
                        "final_short_exit_audited": state.get("final_short_exit_audited"),
                        "last_trade_pnl_complete": state.get("last_trade_pnl_complete"),
                        "last_trade_pnl_usdt": state.get("last_trade_pnl_usdt"),
                        "long_qty": snapshot.long_qty,
                        "short_qty": snapshot.short_qty,
                        "active_snapshot_order_purposes": active_snapshot_order_purposes,
                        "active_runtime_order_purposes": active_runtime_order_purposes,
                        "final_long_exit_order_context_present": final_long_context_present,
                        "final_short_exit_order_context_present": final_short_context_present,
                        "trade_block_id": state.get("trade_block_id"),
                        "last_trade_block_id": state.get("last_trade_block_id"),
                        "pnl_ready_for_current_trade": pnl_ready_for_current_trade,
                    },
                )
                state["flat_waiting_final_pnl_logged"] = True
            state["bot_state"] = self.STATE_EXITED
            state["fresh_restart_required"] = True
            return True

        state.pop("flat_waiting_final_pnl_logged", None)
        state.pop("final_pnl_context_missing_logged", None)
        if not state.get("flat_final_pnl_ready_logged"):
            pnl_ready_for_current_trade = self._final_pnl_ready_for_restart(runtime_state)
            _log_event(
                "fixed_cycle_flat_final_pnl_ready_for_restart",
                {
                    "reason": reason,
                    "last_trade_pnl_usdt": state.get("last_trade_pnl_usdt"),
                    "last_trade_pnl_finalized_at": state.get("last_trade_pnl_finalized_at"),
                    "trade_block_id": state.get("trade_block_id"),
                    "last_trade_block_id": state.get("last_trade_block_id"),
                    "pnl_ready_for_current_trade": pnl_ready_for_current_trade,
                },
            )
            state["flat_final_pnl_ready_logged"] = True
        return False

    def _required_remaining_profit(
        self, runtime_state: RuntimeState | None, snapshot: HedgeSnapshot | None = None
    ) -> float:
        required_target = float(self.config.target_profit_usdt or 0.0)
        net_pnl = self._get_realized_net_pnl_total(runtime_state, snapshot)
        return max(required_target - net_pnl, 0.0)

    def _collect_exit_trigger_prices_from_snapshot(
        self, snapshot: HedgeSnapshot | None
    ) -> dict[str, float]:
        prices: dict[str, float] = {}
        if not snapshot:
            return prices
        exit_purposes = set(self._exit_purposes())
        for order in snapshot.active_orders:
            if not order or order.purpose not in exit_purposes:
                continue
            trigger = getattr(order, "trigger_price", None) or getattr(order, "price", None)
            if trigger is None:
                continue
            prices[order.purpose] = float(trigger)
        return prices

    def _collect_exit_trigger_prices_from_intents(
        self, intents: list[StrategyIntent]
    ) -> dict[str, float]:
        prices: dict[str, float] = {}
        exit_purposes = set(self._exit_purposes())
        for intent in intents:
            if not intent or intent.purpose not in exit_purposes:
                continue
            trigger = intent.trigger_price or intent.price
            if trigger is None:
                continue
            prices[intent.purpose] = float(trigger)
        return prices

    def _log_realized_state(
        self,
        *,
        tag: str,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState,
        stage: str,
        reason: str | None,
        old_exit_trigger_prices: dict[str, float],
        new_exit_trigger_prices: dict[str, float],
        basket_tp_price: float | None = None,
    ) -> None:
        state = runtime_state.strategy_state
        fill_info = state.get("last_fill_info") or {}
        long_pnl = float(runtime_state.realized_long_pnl_total or 0.0)
        short_pnl = float(runtime_state.realized_short_pnl_total or 0.0)
        net_pnl = self._get_realized_net_pnl_total(runtime_state, snapshot)
        pending_loss = float(state.get("pending_cycle_loss_usdt") or 0.0)
        target_profit = float(self.config.target_profit_usdt or 0.0)
        required_remaining_profit = pending_loss + target_profit
        long_qty = float(snapshot.long_qty if snapshot else state.get("open_long_qty") or 0.0)
        short_qty = float(snapshot.short_qty if snapshot else state.get("open_short_qty") or 0.0)
        payload = {
            "stage": stage,
            "reason": reason,
            "fill_purpose": fill_info.get("fill_purpose"),
            "confirmed_closed_pnl": fill_info.get("confirmed_closed_pnl"),
            "realized_long_pnl_total": long_pnl,
            "realized_short_pnl_total": short_pnl,
            "realized_net_pnl_total": net_pnl,
            "target_profit_usdt": float(self.config.target_profit_usdt or 0.0),
            "required_remaining_profit": required_remaining_profit,
            "long_qty": long_qty,
            "short_qty": short_qty,
            "net_qty": long_qty - short_qty,
            "old_exit_trigger_prices": old_exit_trigger_prices or {},
            "new_exit_trigger_prices": new_exit_trigger_prices or {},
            "basket_tp_price": basket_tp_price,
        }
        logger.debug("%s %s", tag, payload)

    def _emit_throttled_strategy_audit(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext,
        event_name: str,
        payload: dict[str, Any],
        *,
        signature_key: str,
        interval_ms: int = 120000,
    ) -> None:
        state = runtime_state.strategy_state
        now_ms = int(time.time() * 1000)
        try:
            signature = json.dumps(payload, sort_keys=True, default=str)
        except Exception:
            signature = repr(payload)
        last_sig_key = f"last_{signature_key}_signature"
        last_ms_key = f"last_{signature_key}_logged_ms"
        last_sig = state.get(last_sig_key)
        last_ms = int(state.get(last_ms_key) or 0)
        if signature != last_sig or now_ms - last_ms >= interval_ms:
            context.audit.log_event(event_name, strategy=self.name, **payload)
            state[last_sig_key] = signature
            state[last_ms_key] = now_ms

    def _pending_second_pair_short_reduce_exit_defer_payload(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        *,
        recent_cycle_fill: bool = False,
    ) -> dict[str, Any] | None:
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        if state.get("refill_pending") or state.get("refill_in_progress"):
            return None
        if int(state.get("cycle_pair_count") or 0) != 1:
            return None
        if recent_cycle_fill:
            _log_event(
                "fixed_cycle_exit_rebuild_not_blocked_by_pending_short_followup",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "short_tp_pending_cycle": self._get_second_leg_pending_cycle(state, cycle_state),
                    "cycle_waiting_for_short_tp": self._get_second_leg_waiting(state, cycle_state),
                    "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
                    "reason": "recent_cycle_fill",
                },
            )
            return None

        protected_cycle = 2
        symbol = str(snapshot.symbol or self.config.symbol or "")
        cycle_pair_count = int(state.get("cycle_pair_count") or 0)
        cycle_completed_count = int(state.get("cycle_completed_count") or 0)
        current_effective_cycle = int(state.get("current_effective_cycle") or 0)
        current_long_cycle_index = int(state.get("current_long_cycle_index") or 0)
        current_short_cycle_index = int(state.get("current_short_cycle_index") or 0)
        pending_long_cycle_index = int(state.get("pending_long_cycle_index") or 0)
        pending_short_cycle_index = int(state.get("pending_short_cycle_index") or 0)
        short_tp_pending_cycle = self._get_second_leg_pending_cycle(state, cycle_state)
        cycle_waiting_for_short_tp = self._get_second_leg_waiting(state, cycle_state)
        cycle_long_add_filled = bool(state.get("cycle_long_add_filled"))
        cycle_short_tp_filled = bool(state.get("cycle_short_tp_filled"))
        pending_cycle_loss_usdt = float(state.get("pending_cycle_loss_usdt") or 0.0)
        short_reduce_purpose = self._cycle_purpose("short", protected_cycle)
        active_order_purposes = sorted(
            {
                str(getattr(order, "purpose", "") or "")
                for order in [
                    *snapshot.active_orders,
                    *runtime_state.active_orders.values(),
                ]
                if str(getattr(order, "purpose", "") or "")
                and not self._is_terminal_order_status(getattr(order, "status", None))
            }
        )

        def _has_active_short_reduce_order() -> bool:
            def _matches(order: Any) -> bool:
                if getattr(order, "purpose", None) != short_reduce_purpose:
                    return False
                if self._is_terminal_order_status(getattr(order, "status", None)):
                    return False
                remaining_qty = float(getattr(order, "remaining_qty", 0.0) or 0.0)
                filled_qty = float(getattr(order, "filled_qty", 0.0) or 0.0)
                qty = float(getattr(order, "qty", 0.0) or 0.0)
                return remaining_qty > 1e-9 or qty <= 0.0 or filled_qty < qty

            return any(_matches(order) for order in snapshot.active_orders) or any(
                _matches(order) for order in runtime_state.active_orders.values()
            )

        has_active_short_reduce_order = _has_active_short_reduce_order()
        cycle_two_active = any(
            value == protected_cycle
            for value in (
                current_long_cycle_index,
                pending_long_cycle_index,
                short_tp_pending_cycle,
            )
        ) or has_active_short_reduce_order
        if not cycle_two_active or current_short_cycle_index >= protected_cycle:
            return None

        trigger_ready = cycle_long_add_filled or pending_cycle_loss_usdt > 0.0
        short_reduce_pending_or_buildable = has_active_short_reduce_order or (
            cycle_waiting_for_short_tp and short_tp_pending_cycle == protected_cycle
        )
        if not trigger_ready or not short_reduce_pending_or_buildable:
            return None

        return {
            "symbol": symbol,
            "cycle_pair_count": cycle_pair_count,
            "cycle_completed_count": cycle_completed_count,
            "protected_cycle": protected_cycle,
            "current_effective_cycle": current_effective_cycle,
            "current_long_cycle_index": current_long_cycle_index,
            "current_short_cycle_index": current_short_cycle_index,
            "pending_long_cycle_index": pending_long_cycle_index,
            "pending_short_cycle_index": pending_short_cycle_index,
            "short_tp_pending_cycle": short_tp_pending_cycle,
            "cycle_waiting_for_short_tp": cycle_waiting_for_short_tp,
            "cycle_long_add_filled": cycle_long_add_filled,
            "cycle_short_tp_filled": cycle_short_tp_filled,
            "pending_cycle_loss_usdt": pending_cycle_loss_usdt,
            "short_reduce_purpose": short_reduce_purpose,
            "short_reduce_open": has_active_short_reduce_order,
            "short_reduce_should_follow_up_build": (
                not has_active_short_reduce_order
                and cycle_waiting_for_short_tp
                and short_tp_pending_cycle == protected_cycle
            ),
            "refill_pending": bool(state.get("refill_pending")),
            "refill_in_progress": bool(state.get("refill_in_progress")),
            "active_order_purposes": active_order_purposes,
            "bot_state": state.get("bot_state"),
        }

    def _rebuild_structure(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        reason: str,
    ) -> list[StrategyIntent]:
        state = runtime_state.strategy_state
        self._seed_initial_reference_if_missing(snapshot, runtime_state)
        self._sync_state_from_snapshot(snapshot, runtime_state)
        self._update_initial_entry_confirmation(snapshot, runtime_state)
        cycle_state = self._ensure_cycle_state(runtime_state)
        has_no_strategy_orders = self._has_no_strategy_orders(snapshot)
        unsettled_runtime_orders, unsettled_snapshot_orders = self._collect_unsettled_strategy_orders(
            snapshot, runtime_state
        )
        if (
            snapshot.long_qty <= 0
            and snapshot.short_qty <= 0
            and state.get("final_exit_trading_stop_active")
        ):
            if self._finalize_trading_stop_basket_exit(
                snapshot,
                runtime_state,
                context,
                reason=reason,
                unsettled_runtime_orders=unsettled_runtime_orders,
                unsettled_snapshot_orders=unsettled_snapshot_orders,
            ):
                # Nach erfolgreichem Trading-Stop-Finalizer sollen logische
                # Trading-Stop- und Cycle-Orders den Flat-Reset nicht mehr blockieren.
                unsettled_runtime_orders = []
                unsettled_snapshot_orders = []
        active_order_purposes = [
            order.purpose
            for order in snapshot.active_orders
            if order.purpose and self._is_unsettled_strategy_order(order)
        ]
        logger.debug(
            "fixed_cycle_rebuild_entry %s",
            {
                "reason": reason,
                "bot_state": state.get("bot_state"),
                "hard_stop_active": state.get("bot_state") == self.STATE_HARD_STOP_MODE,
                "current_price": snapshot.current_price,
                "long_qty": snapshot.long_qty,
                "short_qty": snapshot.short_qty,
                "long_avg": snapshot.long_avg,
                "short_avg": snapshot.short_avg,
                "realized_long_pnl_total": snapshot.realized_long_pnl_total,
                "realized_short_pnl_total": snapshot.realized_short_pnl_total,
                "current_long_cycle_index": int(state.get("current_long_cycle_index") or 0),
                "current_short_cycle_index": int(state.get("current_short_cycle_index") or 0),
                "current_effective_cycle": int(state.get("current_effective_cycle") or 0),
                "cycle_waiting_for_short_tp": self._get_second_leg_waiting(state, cycle_state),
                "initial_entry_confirmed": bool(state.get("initial_entry_confirmed")),
                "has_no_strategy_orders": has_no_strategy_orders,
                "active_order_count": len(snapshot.active_orders),
                "active_order_purposes": active_order_purposes,
            },
        )

        current_cycle = int(state.get("current_effective_cycle") or 0)

        open_initial_orders = self._collect_open_initial_entry_orders(snapshot)
        if open_initial_orders:
            self._emit_throttled_strategy_audit(
                runtime_state,
                context,
                "fixed_cycle_structure_skip",
                {
                    "skip_reason": "initial_entry_order_still_open",
                    "open_initial_orders": open_initial_orders,
                },
                signature_key="structure_skip",
                interval_ms=120000,
            )
            return []

        if (
            snapshot.long_qty > 0
            and snapshot.short_qty > 0
            and not state.get("initial_entry_confirmed")
            and not state.get("recovery_marker_emitted")
        ):
            open_purposes = [
                order.purpose
                for order in snapshot.active_orders
                if getattr(order, "purpose", None)
                and not self._is_terminal_order_status(getattr(order, "status", None))
            ]
            cycle_index = int(state.get("current_effective_cycle") or 0)
            _emit_analyzer_event(
                logger,
                "analyzer_recovery_detected",
                {
                    "symbol": self.config.symbol,
                    "strategy": self.name,
                    "existing_long_size": snapshot.long_qty,
                    "existing_short_size": snapshot.short_qty,
                    "existing_long_avg_price": snapshot.long_avg,
                    "existing_short_avg_price": snapshot.short_avg,
                    "existing_open_orders": open_purposes,
                    "cycle_index": cycle_index,
                },
            )
            state["recovery_marker_emitted"] = True
        initial_long_qty = float(state.get("initial_long_qty") or 0.0)
        initial_short_qty = float(state.get("initial_short_qty") or 0.0)
        seeded_cycle_state = False
        if snapshot.long_qty > 0 and snapshot.short_qty > 0:
            entry_price = float(cycle_state.get("entry_price") or 0.0)
            desired_entry_price = snapshot.long_avg if snapshot.long_avg > 0 else snapshot.current_price
            if entry_price <= 0 and desired_entry_price > 0:
                cycle_state["entry_price"] = desired_entry_price
                seeded_cycle_state = True
            if initial_long_qty <= 0:
                state["initial_long_qty"] = snapshot.long_qty
                seeded_cycle_state = True
            if initial_short_qty <= 0:
                state["initial_short_qty"] = snapshot.short_qty
                seeded_cycle_state = True
            if seeded_cycle_state:
                self._write_cycle_state(cycle_state)
            initial_long_qty = float(state.get("initial_long_qty") or 0.0)
            initial_short_qty = float(state.get("initial_short_qty") or 0.0)
        if snapshot.long_qty <= 0 and snapshot.short_qty <= 0 and (initial_long_qty <= 0 or initial_short_qty <= 0):
            context.audit.log_event(
                "fixed_cycle_initial_entry",
                strategy=self.name,
                reason="initial_entry_phase",
                snapshot=snapshot,
            )
            if not self._dynamic_symbol_entry_gate_allows_entry(
                runtime_state, context, "structure_initial_entry"
            ):
                return []
            self._maybe_update_symbol_from_best_coin(runtime_state, context, "structure_initial_entry")
            self._reset_initial_entry_reconcile_state(runtime_state, reset_submission_state=True)
            intents = self._build_entry_intents(snapshot, runtime_state, context)
            if intents:
                state["dynamic_entry_hold_initialized"] = False
                state.pop("next_dynamic_entry_allowed_at", None)
            return intents

        if (
            snapshot.long_qty <= 0
            and snapshot.short_qty <= 0
            and not self._has_nonterminal_snapshot_orders(snapshot)
            and not unsettled_snapshot_orders
            and not unsettled_runtime_orders
            and not state.get("full_exit_reset_in_progress")
        ):
            self._maybe_start_dynamic_symbol_hold_after_flat(snapshot, runtime_state, context, reason)
            state["fresh_restart_required"] = True
            logger.info(
                "fixed_cycle_full_exit_detected",
                {
                    "strategy": self.name,
                    "fresh_restart_required": True,
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                },
            )
        if snapshot.long_qty <= 0 and snapshot.short_qty <= 0:
            if unsettled_runtime_orders or unsettled_snapshot_orders:
                context.audit.log_event(
                    "fixed_cycle_flat_waiting_unsettled_strategy_orders",
                    strategy=self.name,
                    reason=reason,
                    long_qty=snapshot.long_qty,
                    short_qty=snapshot.short_qty,
                    unsettled_runtime_orders=unsettled_runtime_orders,
                    unsettled_snapshot_orders=unsettled_snapshot_orders,
                )
                return []
            self._cancel_all_pending_orders(context, snapshot, runtime_state)
            state["bot_state"] = self.STATE_EXITED
            context.audit.log_event("fixed_cycle_exited", strategy=self.name, reason=reason, snapshot=snapshot)
            self._reset_after_full_exit_for_next_trade(runtime_state, snapshot, reason=reason)
            self._ensure_recovery_wallet_baseline(snapshot, runtime_state, context)
            return []

        hard_stop_active = current_cycle >= self.config.hard_stop_cycle
        if hard_stop_active and context.cancel_open_orders_by_purpose:
            self._register_expected_exit_order_deactivations(runtime_state, purposes=self._all_cycle_purposes())
            context.cancel_open_orders_by_purpose(self._all_cycle_purposes())

        state["bot_state"] = self.STATE_HARD_STOP_MODE if hard_stop_active else self.STATE_RESETTING_EXITS
        refill_required = self._cycle_build_block_active(state)

        if (
            state.get("bot_state") == self.STATE_EXITED
            and snapshot.long_qty <= 0
            and snapshot.short_qty <= 0
        ):
            _log_event(
                "fixed_cycle_post_exit_reconcile_short_circuited",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "strategy": self.name,
                    "reason": "post_exit_snapshot_flat",
                    "bot_state": state.get("bot_state"),
                },
            )
            return []

        if state.get("recovery_required") or cycle_state.get("recovery_required"):
            recovery_payload = {
                "symbol": snapshot.symbol or self.config.symbol,
                "reason": reason,
                "recovery_activation_timing": state.get("recovery_activation_timing")
                or cycle_state.get("recovery_activation_timing"),
                "recovery_activation_reason": state.get("recovery_activation_reason")
                or cycle_state.get("recovery_activation_reason"),
                "recovery_reference_cycle_index": state.get("recovery_reference_cycle_index")
                or cycle_state.get("recovery_reference_cycle_index"),
                "recovery_reference_price": state.get("recovery_reference_price")
                or cycle_state.get("recovery_reference_price"),
            }
            debug_payload = self._build_recovery_debug_payload(
                runtime_state, snapshot, cycle_state
            )
            _log_event(
                "fixed_cycle_recovery_builder_started",
                {**recovery_payload, **debug_payload},
            )
            _log_event(
                "fixed_cycle_recovery_required_normal_cycle_blocked",
                {**recovery_payload, **debug_payload},
            )
            _log_event(
                "fixed_cycle_recovery_required_waiting_for_recovery_builder",
                {**recovery_payload, **debug_payload},
            )
            recovery_actions = self._build_recovery_refill_intents(
                snapshot, runtime_state, context
            )
            if recovery_actions:
                # Wichtig: Frisch gebaute Recovery-Reload-Intents werden erst nach dem
                # Return dieses Builder-Durchlaufs von der Runtime submitted und in
                # runtime_state.active_orders sichtbar. Eine Stale-Cleanup-Heuristik
                # im selben Tick würde daher fälschlich "pending_flag_true_but_no_active_order"
                # sehen und die gerade gesetzten Pending-Flags zu früh löschen.
                debug_payload = self._build_recovery_debug_payload(
                    runtime_state, snapshot, cycle_state
                )
                _log_event(
                    "fixed_cycle_recovery_refill_intents_built",
                    {**recovery_payload, **debug_payload},
                )
                return recovery_actions
            # Debug-Payload nach möglicher State-Änderung aktualisieren
            debug_payload = self._build_recovery_debug_payload(
                runtime_state, snapshot, cycle_state
            )
            if debug_payload.get("missing_recovery_order_reason") == "pending_flag_true_but_no_active_order":
                self._clear_stale_recovery_reload_pending_flags(runtime_state, cycle_state, debug_payload)
            if recovery_actions is None:
                _log_event(
                    "fixed_cycle_recovery_refill_no_safe_size",
                    {**recovery_payload, **debug_payload},
                )
                return []
            wallet_transfer_pending = bool(state.get("recovery_wallet_transfer_pending"))
            has_recovery_pending = bool(
                debug_payload.get("recovery_reload_pending")
                or debug_payload.get("recovery_refill_pending")
            )
            has_recovery_orders = bool(
                debug_payload.get("runtime_recovery_active_orders")
                or debug_payload.get("snapshot_recovery_active_orders")
            )
            if has_recovery_pending or has_recovery_orders:
                _log_event(
                    "fixed_cycle_recovery_reload_waiting_for_fill",
                    {**recovery_payload, **debug_payload},
                )
                _log_event(
                    "fixed_cycle_recovery_refill_existing_order_detected",
                    {**recovery_payload, **debug_payload},
                )
                _log_event(
                    "fixed_cycle_recovery_refill_waiting_for_fill",
                    {**recovery_payload, **debug_payload},
                )
                return []
            if wallet_transfer_pending:
                _log_event(
                    "fixed_cycle_recovery_reload_blocked_by_wallet_transfer",
                    {**recovery_payload, **debug_payload},
                )
                _log_event(
                    "fixed_cycle_recovery_refill_blocked_by_wallet_baseline",
                    {**recovery_payload, **debug_payload},
                )
                return []
            _log_event(
                "fixed_cycle_recovery_refill_no_intents_no_orders",
                {**recovery_payload, **debug_payload},
            )
            return []

        downside_intents: list[StrategyIntent] = []
        if not hard_stop_active:
            downside_intents = self._build_downside_cycle_intents(snapshot, runtime_state, context)
            refill_required = self._cycle_build_block_active(state)
            _log_event(
                "fixed_cycle_refill_required_rechecked_after_downside_build",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "refill_required": bool(refill_required),
                    "refill_pending": bool(state.get("refill_pending")),
                    "cycle_block_status": state.get("cycle_block_status"),
                    "cycle_completed_count": state.get("cycle_completed_count"),
                    "cycle_pair_count": state.get("cycle_pair_count"),
                    "reason": reason,
                },
            )
        pending_loss_updated = bool(state.pop("pending_loss_updated_in_fill", False))
        pending_loss_reason = state.pop("pending_loss_exit_rebuild_reason", None)
        pending_loss_old_signature = state.get("pending_loss_exit_old_signature")
        force_exit_rebuild = bool(state.pop("force_exit_rebuild", False))
        if pending_loss_updated:
            logger.info(
                "pending_loss_exit_rebuild_forced",
                {
                    "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
                    "reason": pending_loss_reason,
                    "old_last_exit_signature": pending_loss_old_signature,
                    "force_exit_rebuild": force_exit_rebuild,
                },
            )
        logger.debug(
            "fixed_cycle_pre_break_even_state",
            {
                "reason": reason,
                "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
                "force_exit_rebuild": force_exit_rebuild,
                "pending_loss_updated_in_fill": pending_loss_updated,
                "long_qty": snapshot.long_qty,
                "short_qty": snapshot.short_qty,
                "long_avg": snapshot.long_avg,
                "short_avg": snapshot.short_avg,
                "denominator": snapshot.long_qty - snapshot.short_qty,
                "realized_long_pnl_total": snapshot.realized_long_pnl_total,
                "realized_short_pnl_total": snapshot.realized_short_pnl_total,
                "realized_net_pnl_total": float(snapshot.realized_long_pnl_total or 0.0)
                + float(snapshot.realized_short_pnl_total or 0.0),
            },
        )
        break_even_price, break_even_traces = self._calculate_break_even(snapshot, runtime_state)
        tp_price = self._calculate_tp_price(break_even_price, snapshot, runtime_state)
        logger.debug(
            "fixed_cycle_post_tp_state",
            {
                "reason": reason,
                "break_even_price": break_even_price,
                "tp_price": tp_price,
                "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
                "latest_break_even_price": break_even_price,
                "latest_tp_price": tp_price,
                "force_exit_rebuild": force_exit_rebuild,
            },
        )
        state["latest_break_even_price"] = break_even_price
        state["latest_tp_price"] = tp_price

        exit_intents: list[StrategyIntent] = []
        if not refill_required:
            exit_intents = self._build_exit_intents(
                snapshot,
                runtime_state,
                current_cycle,
                break_even_price,
                tp_price,
                hard_stop_active,
                context,
                force_exit_rebuild=force_exit_rebuild,
                pending_loss_old_signature=pending_loss_old_signature,
                pending_cycle_intents=downside_intents,
            )
            if pending_loss_updated and exit_intents:
                _log_event(
                    "fixed_cycle_exit_orders_replaced_after_cycle_fill",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "break_even_price": break_even_price,
                        "tp_price": tp_price,
                        "pending_cycle_loss_usdt": float(
                            state.get("pending_cycle_loss_usdt") or 0.0
                        ),
                        "exit_purposes": [intent.purpose for intent in exit_intents],
                        "reason": "pending_cycle_loss_rebuild",
                    },
                )
            if exit_intents and state.get("exit_orders_stale_after_structure_fill"):
                _log_event(
                    "fixed_cycle_structure_fill_exit_rebuild_completed",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "force_exit_rebuild": bool(state.get("force_exit_rebuild")),
                        "exit_orders_stale_after_structure_fill": True,
                        "exit_purposes": [intent.purpose for intent in exit_intents],
                    },
                )
                state["force_exit_rebuild"] = False
                state["exit_rebuild_allowed"] = False
                state["exit_orders_stale_after_structure_fill"] = False
            elif state.get("exit_orders_stale_after_structure_fill"):
                state["force_exit_rebuild"] = True
                state["exit_rebuild_allowed"] = True
        downside_intents = self._annotate_post_refill_structure_intents(
            runtime_state, downside_intents
        )
        exit_intents = self._annotate_post_refill_structure_intents(
            runtime_state, exit_intents
        )
        intents = exit_intents + downside_intents
        if (
            (snapshot.long_qty > 0 or snapshot.short_qty > 0)
            and not self._has_active_strategy_orders(snapshot, runtime_state)
            and not intents
            and not bool(state.get("post_refill_structure_rebuild_required"))
        ):
            _log_event(
                "fixed_cycle_downside_cycle_intent_build_blocked",
                {
                    "symbol": self.config.symbol,
                    "block_reason": "open_position_without_orders_recovery",
                    "next_required_purpose": state.get("next_required_purpose"),
                    "active_cycle_index": state.get("active_cycle_index"),
                    "refill_required": bool(state.get("refill_required")),
                    "cycle_block_status": state.get("cycle_block_status"),
                    "cycle_block_reason": state.get("cycle_block_reason"),
                    "last_refill_completed_cycle_index": state.get("last_refill_completed_cycle_index"),
                    "cycles_since_last_refill": state.get("cycles_since_last_refill"),
                },
            )
            _log_event(
                "fixed_cycle_open_position_without_orders_recovery_triggered",
                {
                    "symbol": self.config.symbol,
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                    "cycle_completed_count": state.get("cycle_completed_count"),
                    "cycle_pair_count": state.get("cycle_pair_count"),
                    "bot_state": state.get("bot_state"),
                    "active_snapshot_order_purposes": [
                        order.purpose for order in snapshot.active_orders
                    ],
                    "runtime_order_count": len(runtime_state.active_orders),
                },
            )
            cycle_index = max(
                int(state.get("cycle_completed_count") or 0),
                int(state.get("cycle_pair_count") or 0),
            )
            self._mark_refill_required_after_cycle_pair(
                runtime_state,
                cycle_index=cycle_index,
                trigger_purpose="open_position_without_orders_recovery",
                reason="open_position_without_orders_recovery",
            )
            state["force_exit_rebuild"] = True
            state["exit_rebuild_allowed"] = True
            return []
        _log_event(
            "fixed_cycle_rebuild_intent_merge_summary",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "reason": reason,
                "cycle_intents": [intent.purpose for intent in downside_intents],
                "exit_intents": [intent.purpose for intent in exit_intents],
                "final_intents": [intent.purpose for intent in intents],
                "tp_price": tp_price,
                "break_even_price": break_even_price,
            },
        )
        state = runtime_state.strategy_state
        if state.get("post_refill_structure_rebuild_required"):
            is_recovery_reload = bool(state.get("recovery_reload_completed")) or bool(
                state.get("recovery_lifecycle_state")
            )
            recovery_cycle_index = int(
                state.get("recovery_reload_cycle_index")
                or self._ensure_cycle_state(runtime_state).get("recovery_reference_cycle_index")
                or 0
            )
            if is_recovery_reload:
                _log_event(
                    "fixed_cycle_recovery_post_reload_rebuild_started",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "bot_name": self.config.bot_name,
                        "trade_block_id": state.get("trade_block_id"),
                        "recovery_reload_id": state.get("recovery_reload_id"),
                        "recovery_cycle_index": recovery_cycle_index or None,
                        "next_required_purpose_before": state.get("next_required_purpose"),
                        "cycle_step_before": state.get("cycle_step"),
                    },
                )
            expected_purposes = self._expected_post_refill_structure_purposes(runtime_state)
            if expected_purposes:
                final_purposes = [p for p in [intent.purpose for intent in intents] if p]
                active_order_purposes_raw = [
                    getattr(order, "purpose", None)
                    for order in (*snapshot.active_orders, *runtime_state.active_orders.values())
                    if getattr(order, "purpose", None)
                    and not self._is_terminal_order_status(getattr(order, "status", None))
                ]
                active_order_purposes = self._dedupe_preserve_order(active_order_purposes_raw)
                confirmed_purposes = []
                for purpose in final_purposes + active_order_purposes:
                    if purpose and purpose not in confirmed_purposes:
                        confirmed_purposes.append(purpose)
                missing = [
                    purpose
                    for purpose in expected_purposes
                    if purpose not in confirmed_purposes
                ]
                log_payload = {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "expected_purposes": expected_purposes,
                    "confirmed_purposes": confirmed_purposes,
                    "active_order_purposes": active_order_purposes,
                    "final_intents": final_purposes,
                    "cycle_intents": [intent.purpose for intent in downside_intents],
                    "exit_intents": [intent.purpose for intent in exit_intents],
                    "next_required_purpose": state.get("next_required_purpose"),
                    "active_cycle_index": state.get("active_cycle_index"),
                    "missing_purposes": missing,
                }
                if not missing and expected_purposes[0] in confirmed_purposes:
                    state["post_refill_structure_rebuild_required"] = False
                    state["post_refill_structure_rebuild_confirmed_purposes"] = confirmed_purposes
                    _log_event(
                        "fixed_cycle_post_refill_structure_rebuild_completed",
                        log_payload,
                    )
                    # Nur Recovery-Lifecycle beobachten: bei rein normalen Refills
                    # bleibt recovery_lifecycle_state in der Regel unset/None.
                    if state.get("recovery_lifecycle_state") is not None:
                        self._set_recovery_lifecycle_state(
                            state,
                            "COMPLETED",
                            event="post_refill_structure_rebuild_completed",
                        )
                    if is_recovery_reload:
                        last_snapshot = getattr(runtime_state, "last_snapshot", None) or snapshot
                        _log_event(
                            "fixed_cycle_recovery_post_reload_rebuild_completed",
                            {
                                **log_payload,
                                "bot_name": self.config.bot_name,
                                "trade_block_id": state.get("trade_block_id"),
                                "recovery_reload_id": state.get("recovery_reload_id"),
                                "recovery_cycle_index": recovery_cycle_index or None,
                                "actual_long_qty": float(
                                    getattr(last_snapshot, "long_qty", 0.0) or 0.0
                                ),
                                "actual_short_qty": float(
                                    getattr(last_snapshot, "short_qty", 0.0) or 0.0
                                ),
                                "actual_long_avg": float(
                                    getattr(last_snapshot, "long_avg", 0.0) or 0.0
                                ),
                                "actual_short_avg": float(
                                    getattr(last_snapshot, "short_avg", 0.0) or 0.0
                                ),
                                "next_required_purpose_after": state.get(
                                    "next_required_purpose"
                                ),
                                "cycle_step_after": state.get("cycle_step"),
                            },
                        )
                else:
                    _log_event(
                        "fixed_cycle_post_refill_structure_rebuild_waiting",
                        log_payload,
                    )
        if exit_intents:
            if state.get("post_refill_structure_rebuild_required") and bool(
                state.get("recovery_reload_completed")
            ):
                _log_event(
                    "fixed_cycle_recovery_post_reload_exit_rebuild_started",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "bot_name": self.config.bot_name,
                        "trade_block_id": state.get("trade_block_id"),
                        "recovery_reload_id": state.get("recovery_reload_id"),
                        "recovery_cycle_index": state.get("recovery_reload_cycle_index"),
                        "exit_intents": [intent.purpose for intent in exit_intents],
                    },
                )
            self._set_final_exit_missing_block(
                runtime_state, self.FINAL_EXIT_MISSING_REBUILD_BLOCK_SEC
            )
        if pending_loss_old_signature is not None:
            state.pop("pending_loss_exit_old_signature", None)

        if hard_stop_active:
            state["bot_state"] = self.STATE_HARD_STOP_MODE
        elif refill_required:
            state["bot_state"] = self.STATE_REFILL_PENDING
        else:
            state["bot_state"] = self.STATE_RUNNING

        has_real_structure_change = bool(downside_intents or exit_intents)
        if has_real_structure_change:
            context.audit.log_event(
                "fixed_cycle_structure_rebuilt",
                strategy=self.name,
                reason=reason,
                hard_stop_active=hard_stop_active,
                break_even_price=break_even_price,
                tp_price=tp_price,
                current_long_cycle_index=state.get("current_long_cycle_index"),
                current_short_cycle_index=state.get("current_short_cycle_index"),
                current_effective_cycle=state.get("current_effective_cycle"),
                intents=intents,
                traces=[trace.to_dict() for trace in break_even_traces],
            )
        else:
            logger.debug(
                "fixed_cycle_structure_rebuilt skipped (no new intents) %s",
                {"reason": reason},
            )

        logger.debug(
            "fixed_cycle_rebuild_result_detailed %s",
            {
                "downside_intent_count": len(downside_intents),
                "exit_intent_count": len(exit_intents),
                "total_intent_count": len(intents),
                "downside_purposes": [intent.purpose for intent in downside_intents],
                "exit_purposes": [intent.purpose for intent in exit_intents],
                "has_long_cycle_purpose": any("_LONG_" in (intent.purpose or "") for intent in intents),
                "has_short_cycle_purpose": any("_SHORT_" in (intent.purpose or "") for intent in intents),
                "only_exit_intents": len(downside_intents) == 0 and len(exit_intents) > 0,
            },
        )
        old_exit_trigger_prices = self._collect_exit_trigger_prices_from_snapshot(snapshot)
        new_exit_trigger_prices = self._collect_exit_trigger_prices_from_intents(exit_intents)
        self._log_realized_state(
            tag="fixed_cycle_rebuild_state",
            snapshot=snapshot,
            runtime_state=runtime_state,
            stage="rebuild",
            reason=reason,
            old_exit_trigger_prices=old_exit_trigger_prices,
            new_exit_trigger_prices=new_exit_trigger_prices,
            basket_tp_price=tp_price,
        )
        _log_event(
            "fixed_cycle_downside_cycle_intent_build_result",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "reason": reason,
                "next_required_purpose": state.get("next_required_purpose"),
                "active_cycle_index": state.get("active_cycle_index"),
                "cycle_intents": [intent.purpose for intent in downside_intents],
                "cycle_intent_count": len(downside_intents),
                "exit_intents": [intent.purpose for intent in exit_intents],
                "final_intents": [intent.purpose for intent in intents],
            },
        )
        return intents

    def _expected_post_refill_structure_purposes(
        self, runtime_state: RuntimeState
    ) -> list[str]:
        state = runtime_state.strategy_state
        purposes: list[str] = []
        next_required = str(state.get("next_required_purpose") or "").strip()
        if next_required:
            purposes.append(next_required)
        for purpose in (
            self._get_final_long_exit_purpose(),
            self._get_final_short_exit_purpose(),
        ):
            if purpose not in purposes:
                purposes.append(purpose)
        return purposes

    def _annotate_post_refill_structure_intents(
        self,
        runtime_state: RuntimeState,
        intents: list[StrategyIntent],
    ) -> list[StrategyIntent]:
        state = runtime_state.strategy_state
        if not state.get("post_refill_structure_rebuild_required"):
            return intents
        expected_purposes = self._expected_post_refill_structure_purposes(runtime_state)
        for intent in intents:
            if intent.purpose not in expected_purposes:
                continue
            metadata = dict(intent.metadata or {})
            metadata["post_refill_structure_rebuild_required"] = True
            metadata["post_refill_expected_purposes"] = expected_purposes
            intent.metadata = metadata
        return intents

    def _build_cycle_long_add_intent(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        cycle_index: int,
    ) -> StrategyIntent | None:
        if cycle_index <= 0 or cycle_index > self.config.max_cycles:
            return None
        state = runtime_state.strategy_state
        entry_reference_price = float(state.get("entry_reference_price") or 0.0)
        initial_long_qty = float(state.get("initial_long_qty") or 0.0)
        initial_short_qty = float(state.get("initial_short_qty") or 0.0)
        if entry_reference_price <= 0 or initial_long_qty <= 0 or initial_short_qty <= 0:
            return None
        cycle_state = self._ensure_cycle_state(runtime_state)
        long_fill_price = self._cycle_state_last_fill_price(cycle_state.get("long_fills") or {})
        short_fill_price = self._cycle_state_last_fill_price(cycle_state.get("short_fills") or {})
        reference_price = snapshot.current_price if snapshot.current_price > 0 else entry_reference_price
        cycle_entry_price = float(cycle_state.get("entry_price") or entry_reference_price)
        last_cycle_reference_price = float(cycle_state.get("last_cycle_reference_price") or 0.0)
        if (
            last_cycle_reference_price <= 0
            and not (cycle_state.get("long_fills") or cycle_state.get("short_fills"))
            and snapshot.long_avg > 0
        ):
            last_cycle_reference_price = float(snapshot.long_avg)
            cycle_state["last_cycle_reference_price"] = last_cycle_reference_price
        short_avg = snapshot.short_avg
        short_qty = snapshot.short_qty
        long_reference_candidate = last_cycle_reference_price
        reference_source = "last_cycle_reference"
        reference_cycle_index: int | None = None
        reference_purpose: str | None = None
        if cycle_index > 1:
            previous_short_fill_price = self._get_confirmed_previous_short_reduce_fill_price(
                runtime_state, cycle_index
            )
            if previous_short_fill_price is None:
                previous_entry = self._get_cycle_sequence_entry(runtime_state, cycle_index - 1)
                _log_event(
                    "fixed_cycle_long_add_reference_missing",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "expected_previous_cycle_index": cycle_index - 1,
                        "expected_field": "short_reduce_fill_price",
                        "short_reduce_fill_confirmed": bool(
                            previous_entry.get("short_reduce_fill_confirmed")
                        ),
                        "processed_cycle_purposes": list(
                            state.get("processed_cycle_purposes") or []
                        ),
                        "active_order_purposes": [
                            order.purpose
                            for order in runtime_state.active_orders.values()
                            if getattr(order, "purpose", None)
                        ],
                        "next_required_purpose": state.get("next_required_purpose"),
                    },
                )
                return None
            long_reference_candidate = previous_short_fill_price
            reference_source = "previous_short_reduce_fill"
            reference_cycle_index = cycle_index - 1
            reference_purpose = self._cycle_purpose("short", reference_cycle_index)
        long_reference = long_reference_candidate
        if long_reference <= 0:
            return None
        long_distance_pct_config = self.config.long_fill_distance_pct
        long_distance_pct = self._clamp_pct_fraction(self._pct(long_distance_pct_config))
        reference_price_for_long_add = long_reference
        long_qty = self._fixed_long_cycle_qty(
            initial_long_qty,
            snapshot.long_qty,
            reference_price,
            runtime_state,
        )
        raw_trigger_price = reference_price_for_long_add * (1 - long_distance_pct)
        trigger_price = self._normalize_price(raw_trigger_price, runtime_state)
        if trigger_price <= 0 or long_qty <= 0:
            skip_reason = (
                "trigger_price_non_positive" if trigger_price <= 0 else "long_qty_non_positive"
            )
            skip_payload = {
                "strategy": self.name,
                "skip_reason": skip_reason,
                "cycle_number": cycle_index,
                "side": "long",
                "reference_price_used": long_reference,
                "raw_trigger_price": raw_trigger_price,
                "normalized_trigger_price": trigger_price,
                "computed_qty_normalized": long_qty,
                "purpose": self._get_first_leg_purpose(cycle_index),
            }
            context.audit.log_event("fixed_cycle_downside_skip", **skip_payload)
            return None
        purpose = self._get_first_leg_purpose(cycle_index)
        context.audit.log_event(
            "fixed_cycle_long_reduce_planned",
            {
                "strategy": self.name,
                "cycle_index": cycle_index,
                "side": self._get_first_leg_side(),
                "purpose": purpose,
                "entry_reference_price": entry_reference_price,
                "distance_pct": long_distance_pct_config,
                "distance_pct_used": long_distance_pct,
                "long_fill_price": long_fill_price,
                "cycle_entry_price": cycle_entry_price,
                "live_reference_price": reference_price,
                "final_long_reference": long_reference,
                "reference_source": reference_source,
                "reference_cycle_index": reference_cycle_index,
                "reference_purpose": reference_purpose,
                "reference_price": reference_price_for_long_add,
                "long_fill_distance_pct": self.config.long_fill_distance_pct,
                "trigger_price": trigger_price,
                "trigger_formula": "final_long_reference * (1 - distance_pct)",
                "trigger_price_raw": raw_trigger_price,
                "trigger_price_normalized": trigger_price,
                "qty_formula": "current_long_qty * reduction_pct_per_fill",
                "qty_raw": snapshot.long_qty * self._pct(self.config.reduction_pct_per_fill),
                "qty_normalized": long_qty,
                "order_type": "Limit",
                "reduce_only": True,
            },
        )
        intent = self._create_cycle_first_leg_intent(
            runtime_state=runtime_state,
            cycle_index=cycle_index,
            side=self._get_first_leg_side(),
            position_idx=self._get_first_leg_position_idx(),
            role=self._get_first_leg_cycle_role(),
            purpose=purpose,
            qty=long_qty,
            trigger_price=trigger_price,
            entry_reference_price=entry_reference_price,
            reference_source=reference_source,
            reference_cycle_index=reference_cycle_index,
            reference_purpose=reference_purpose,
            reference_price=reference_price_for_long_add,
            replace_open_purpose=purpose
            if self._should_attach_replace_open_purpose(
                snapshot,
                runtime_state,
                purpose,
                cycle_index=cycle_index,
                cycle_role=self._get_first_leg_cycle_role(),
            )
            else None,
        )
        return intent

    def _create_cycle_first_leg_intent(
        self,
        *,
        runtime_state: RuntimeState,
        cycle_index: int,
        side: str,
        position_idx: int,
        role: str,
        purpose: str,
        qty: float,
        trigger_price: float,
        entry_reference_price: float,
        reference_source: str,
        reference_cycle_index: int,
        reference_purpose: str,
        reference_price: float,
        replace_open_purpose: str | None = None,
        field_name: str | None = None,
        rebuild_flag_field: str | None = "long_add_rebuild_allowed",
    ) -> StrategyIntent:
        state = runtime_state.strategy_state
        metadata: dict[str, Any] = {
            "cycle_index": cycle_index,
            "cycle_role": role,
            "entry_reference_price": entry_reference_price,
            "reference_source": reference_source,
            "reference_cycle_index": reference_cycle_index,
            "reference_purpose": reference_purpose,
            "reference_price": reference_price,
        }
        if replace_open_purpose:
            metadata["replace_open_purpose"] = replace_open_purpose
        if field_name is None:
            field_name = self._get_first_leg_status_field()
        normalized_purpose = self._normalize_cycle_purpose(
            purpose,
            {"cycle_index": cycle_index, "cycle_role": role},
        )
        self._reserve_cycle_intent_slot(
            runtime_state,
            cycle_index=cycle_index,
            field_name=field_name,
            normalized_purpose=normalized_purpose,
            qty=qty,
            trigger_price=trigger_price,
        )
        if rebuild_flag_field:
            state[rebuild_flag_field] = False
        return StrategyIntent(
            side=side,
            qty=qty,
            purpose=purpose,
            order_type="Market",
            reduce_only=True,
            trigger_price=trigger_price,
            trigger_direction=2,
            trigger_by="LastPrice",
            close_on_trigger=True,
            position_idx=position_idx,
            metadata=metadata,
        )

    def _build_downside_cycle_intents(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent]:
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        reason = getattr(context, "reason", None) or getattr(context, "trigger_reason", None) or getattr(
            context, "purpose", None
        )
        # Recovery-Reload: solange der REST-Reconcile nicht bestätigt ist, keine neuen
        # Cycle-/Exit-Builds zulassen. Versuche bei jedem Aufruf einen erneuten
        # REST-Reconcile, bevor geblockt wird.
        if state.get("recovery_reload_rest_reconcile_required") and not state.get(
            "recovery_reload_rest_reconcile_confirmed"
        ):
            refresh_snapshot = getattr(context, "refresh_snapshot", None)
            last_snapshot = getattr(runtime_state, "last_snapshot", None) or snapshot
            trade_block_id = state.get("trade_block_id")
            recovery_reload_id = state.get("recovery_reload_id")
            reconcile_base_payload: dict[str, Any] = {
                "symbol": last_snapshot.symbol or self.config.symbol,
                "trade_block_id": trade_block_id,
                "cycle_index": int(state.get("recovery_completed_cycle_index") or 0) or None,
                "recovery_reload_id": recovery_reload_id,
                "prev_long_qty": float(getattr(last_snapshot, "long_qty", 0.0) or 0.0),
                "prev_short_qty": float(getattr(last_snapshot, "short_qty", 0.0) or 0.0),
                "prev_long_avg": float(getattr(last_snapshot, "long_avg", 0.0) or 0.0),
                "prev_short_avg": float(getattr(last_snapshot, "short_avg", 0.0) or 0.0),
            }
            if callable(refresh_snapshot):
                _log_event(
                    "fixed_cycle_recovery_reload_rest_reconcile_started",
                    reconcile_base_payload,
                )
                try:
                    reconciled_snapshot = refresh_snapshot("recovery_reload_rest")
                    runtime_state.last_snapshot = reconciled_snapshot
                    state["recovery_reload_rest_reconcile_confirmed"] = True
                    state["recovery_reload_rest_reconcile_required"] = False
                    state.pop("recovery_reload_rest_reconcile_error", None)
                    reconcile_completed_payload = {
                        **reconcile_base_payload,
                        "actual_long_qty": float(reconciled_snapshot.long_qty or 0.0),
                        "actual_short_qty": float(reconciled_snapshot.short_qty or 0.0),
                        "actual_long_avg_price": float(reconciled_snapshot.long_avg or 0.0),
                        "actual_short_avg_price": float(reconciled_snapshot.short_avg or 0.0),
                        "snapshot_source": getattr(reconciled_snapshot, "source", None),
                    }
                    _log_event(
                        "fixed_cycle_recovery_reload_rest_reconcile_completed",
                        reconcile_completed_payload,
                    )
                    snapshot = reconciled_snapshot
                except Exception as exc:  # pragma: no cover - Reconcile darf nie blockierend fehlschlagen
                    state["recovery_reload_rest_reconcile_error"] = str(exc)
                    _log_event(
                        "fixed_cycle_recovery_reload_rest_reconcile_failed",
                        {
                            **reconcile_base_payload,
                            "error": str(exc),
                        },
                    )
                    _log_event(
                        "fixed_cycle_recovery_reload_rest_reconcile_blocking_cycle_build",
                        reconcile_base_payload,
                    )
                    return []
            else:
                _log_event(
                    "fixed_cycle_recovery_reload_rest_reconcile_failed",
                    {**reconcile_base_payload, "error": "refresh_snapshot_missing"},
                )
                _log_event(
                    "fixed_cycle_recovery_reload_rest_reconcile_blocking_cycle_build",
                    reconcile_base_payload,
                )
                return []
        if state.get("recovery_required") or cycle_state.get("recovery_required"):
            recovery_payload = {
                "symbol": snapshot.symbol or self.config.symbol,
                "cycle_index": int(state.get("active_cycle_index") or 0),
                "recovery_activation_timing": state.get("recovery_activation_timing")
                or cycle_state.get("recovery_activation_timing"),
                "recovery_activation_reason": state.get("recovery_activation_reason")
                or cycle_state.get("recovery_activation_reason"),
                "recovery_reference_price": state.get("recovery_reference_price")
                or cycle_state.get("recovery_reference_price"),
            }
            _log_event("fixed_cycle_recovery_required_normal_cycle_blocked", recovery_payload)
            _log_event(
                "fixed_cycle_recovery_required_waiting_for_recovery_builder",
                recovery_payload,
            )
            return []
        intent_context = {
            "reason": reason,
            "next_required_purpose": state.get("next_required_purpose"),
            "active_cycle_index": state.get("active_cycle_index"),
            "last_completed_purpose": state.get("last_completed_purpose"),
            "current_effective_cycle": state.get("current_effective_cycle"),
            "cycle_completed_count": state.get("cycle_completed_count"),
            "cycle_pair_count": state.get("cycle_pair_count"),
            "last_refill_completed_cycle_index": state.get("last_refill_completed_cycle_index"),
            "cycles_since_last_refill": state.get("cycles_since_last_refill"),
            "refill_required": bool(state.get("refill_required")),
            "refill_pending": bool(state.get("refill_pending")),
            "refill_in_progress": bool(state.get("refill_in_progress")),
            "refill_completed": bool(state.get("refill_completed")),
            "refill_long_filled": bool(state.get("refill_long_filled")),
            "refill_short_filled": bool(state.get("refill_short_filled")),
            "cycle_block_status": state.get("cycle_block_status"),
            "cycle_block_reason": state.get("cycle_block_reason"),
            "force_exit_rebuild": bool(state.get("force_exit_rebuild")),
            "exit_rebuild_allowed": bool(state.get("exit_rebuild_allowed")),
            "post_refill_structure_rebuild_required": bool(
                state.get("post_refill_structure_rebuild_required")
            ),
            "active_order_purposes": [order.purpose for order in runtime_state.active_orders.values()],
            "processed_cycle_purposes": state.get("processed_cycle_purposes"),
        }
        _log_event("fixed_cycle_downside_cycle_intent_build_attempt", intent_context)
        intents: list[StrategyIntent] = []
        state = runtime_state.strategy_state
        self._ensure_cycle_sequence_state(runtime_state)
        # Optional time/distance-based refill trigger using the existing refill mode.
        # This is a simple additional trigger that reuses the established refill lifecycle.
        self._maybe_trigger_time_distance_refill(snapshot, runtime_state, context)
        gate_details = self._reconcile_refill_gate_state(snapshot, runtime_state)
        refill_required = self._cycle_build_block_active(state)
        if refill_required:
            _log_event(
                "fixed_cycle_downside_cycle_intent_build_blocked",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "reason": reason,
                    "next_required_purpose": state.get("next_required_purpose"),
                    "active_cycle_index": state.get("active_cycle_index"),
                    "cycle_completed_count": state.get("cycle_completed_count"),
                    "cycle_pair_count": state.get("cycle_pair_count"),
                    "refill_required": True,
                    "refill_pending": bool(state.get("refill_pending")),
                    "refill_in_progress": bool(state.get("refill_in_progress")),
                    "cycle_block_status": state.get("cycle_block_status"),
                    "cycle_block_reason": state.get("cycle_block_reason"),
                    "last_refill_completed_cycle_index": state.get("last_refill_completed_cycle_index"),
                    "cycles_since_last_refill": state.get("cycles_since_last_refill"),
                },
            )
            _log_event(
                "fixed_cycle_refill_block_cycle_build",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_pair_count": state.get("cycle_pair_count"),
                    "cycle_completed_count": state.get("cycle_completed_count"),
                    "refill_pending": bool(state.get("refill_pending")),
                    "refill_required": bool(state.get("refill_required")),
                    "refill_in_progress": bool(state.get("refill_in_progress")),
                    "bot_state": state.get("bot_state"),
                    "cycle_block_status": state.get("cycle_block_status"),
                    "reason": "refill_required",
                },
            )
            context.audit.log_event(
                "fixed_cycle_refill_required_after_cycle_pair",
                strategy=self.name,
                cycle_completed_count=state.get("cycle_completed_count"),
                cycle_pair_count=state.get("cycle_pair_count"),
                refill_pending=bool(state.get("refill_pending")),
                refill_required=bool(state.get("refill_required")),
                bot_state=state.get("bot_state"),
                active_refill_orders_count=gate_details["active_refill_orders_count"],
                stale_detected=gate_details["stale_detected"],
            )
            if gate_details["active_refill_orders_count"] > 0:
                context.audit.log_event(
                    "fixed_cycle_refill_block",
                    strategy=self.name,
                    cycle_completed_count=state.get("cycle_completed_count"),
                    cycle_pair_count=state.get("cycle_pair_count"),
                    reason="refill_in_progress",
                )
                context.audit.log_event(
                    "fixed_cycle_refill_block_details",
                    strategy=self.name,
                    **gate_details,
                )
                return []
            return self._build_entry_intents(snapshot, runtime_state, context)
        if gate_details["active_refill_orders_count"] > 0:
            context.audit.log_event(
                "fixed_cycle_refill_block",
                strategy=self.name,
                cycle_completed_count=state.get("cycle_completed_count"),
                cycle_pair_count=state.get("cycle_pair_count"),
                reason="refill_in_progress",
            )
            context.audit.log_event(
                "fixed_cycle_refill_block_details",
                strategy=self.name,
                **gate_details,
            )
            return []

        if state.get("trailing_active"):
            return intents
        open_initial_orders = self._collect_open_initial_entry_orders(snapshot)
        if open_initial_orders:
            context.audit.log_event(
                "fixed_cycle_downside_skip",
                strategy=self.name,
                skip_reason="initial_entry_order_still_open",
                open_initial_orders=open_initial_orders,
            )
            return intents
        if (
            not bool(state.get("initial_entry_confirmed"))
            or float(snapshot.long_qty or 0.0) <= 0.0
            or float(snapshot.short_qty or 0.0) <= 0.0
        ):
            _log_event(
                "fixed_cycle_cycle_build_blocked_until_initial_entry_rest_confirmed",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "initial_entry_confirmed": bool(state.get("initial_entry_confirmed")),
                    "long_qty": float(snapshot.long_qty or 0.0),
                    "short_qty": float(snapshot.short_qty or 0.0),
                    "open_initial_orders": open_initial_orders,
                },
            )
            return intents

        if state.get("sequence_recovery_blocked"):
            _log_event(
                "fixed_cycle_sequence_recovery_blocked",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "category": context.category or self.config.category,
                    "active_cycle_index": int(state.get("active_cycle_index") or 1),
                    "cycle_step": state.get("cycle_step"),
                    "next_required_purpose": state.get("next_required_purpose"),
                    "last_completed_purpose": state.get("last_completed_purpose"),
                    "sequence_recovery_blocked": True,
                    "processed_cycle_purposes": list(state.get("processed_cycle_purposes") or []),
                    "active_order_purposes": [
                        str(getattr(order, "purpose", "") or "")
                        for order in runtime_state.active_orders.values()
                    ],
                },
            )
            return intents

        last_refill_completed_cycle_index = int(state.get("last_refill_completed_cycle_index") or 0)
        completed_cycles_guard = int(state.get("cycle_completed_count") or 0)
        pair_count_guard = int(state.get("cycle_pair_count") or 0)
        cycles_since_last_refill = completed_cycles_guard - last_refill_completed_cycle_index
        if (
            bool(state.get("refill_pending"))
            or bool(state.get("refill_required"))
            or state.get("bot_state") == self.STATE_REFILL_PENDING
            or cycles_since_last_refill >= 2
        ):
            _log_event(
                "fixed_cycle_long_add_blocked_refill_required",
                {
                    "cycle_completed_count": completed_cycles_guard,
                    "cycle_pair_count": pair_count_guard,
                    "last_refill_completed_cycle_index": last_refill_completed_cycle_index,
                    "cycles_since_last_refill": cycles_since_last_refill,
                    "refill_pending": bool(state.get("refill_pending")),
                    "refill_required": bool(state.get("refill_required")),
                    "bot_state": state.get("bot_state"),
                },
            )
            self._mark_refill_required_after_cycle_pair(
                runtime_state,
                cycle_index=max(pair_count_guard, completed_cycles_guard),
                trigger_purpose="build_downside_cycle_guard",
                reason="long_add_blocked_refill_required",
            )
            return intents

        cycle_waiting_for_short_tp = self._get_second_leg_waiting(state)
        short_tp_pending_cycle = self._get_second_leg_pending_cycle(state)
        if short_tp_pending_cycle > 0:
            pending_cycle_entry = self._get_cycle_sequence_entry(runtime_state, short_tp_pending_cycle)
            if bool(pending_cycle_entry.get("complete")):
                cycle_waiting_for_short_tp = False

        if not state.get("long_add_rebuild_allowed", True):
            if cycle_waiting_for_short_tp and short_tp_pending_cycle > 0:
                _log_event(
                    "fixed_cycle_long_add_rebuild_locked_but_short_followup_allowed",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "short_tp_pending_cycle": short_tp_pending_cycle,
                        "cycle_waiting_for_short_tp": short_followup_pending,
                        "processed_cycle_purposes": list(state.get("processed_cycle_purposes") or []),
                    },
                )
                short_intents = self._build_short_tp_follow_up(snapshot, runtime_state, context)
                short_intents = self._apply_live_short_tp_relief(
                    snapshot,
                    runtime_state,
                    short_intents,
                )
                intents.extend(short_intents)
                if not short_intents:
                    short_followup_active = self._short_followup_active_for_cycle(
                        short_tp_pending_cycle, runtime_state, snapshot
                    )
                    if short_followup_active:
                        cycle_entry = self._get_cycle_sequence_entry(
                            runtime_state, short_tp_pending_cycle
                        )
                        next_required_purpose = str(
                            state.get("next_required_purpose") or ""
                        ).upper()
                        normalized_first_leg_purpose = self._normalize_cycle_purpose(
                            self._get_first_leg_purpose(short_tp_pending_cycle),
                            {
                                "cycle_index": short_tp_pending_cycle,
                                "cycle_role": self._get_first_leg_cycle_role(),
                            },
                        )
                        normalized_second_leg_purpose = self._normalize_cycle_purpose(
                            self._get_second_leg_purpose(short_tp_pending_cycle),
                            {
                                "cycle_index": short_tp_pending_cycle,
                                "cycle_role": self._get_second_leg_cycle_role(),
                            },
                        )
                        processed_cycle_purposes = [
                            str(purpose or "").upper()
                            for purpose in (state.get("processed_cycle_purposes") or [])
                        ]
                        first_leg_processed = (
                            normalized_first_leg_purpose in processed_cycle_purposes
                        )
                        second_leg_processed = (
                            normalized_second_leg_purpose in processed_cycle_purposes
                        )
                        short_tp_status = str(
                            (cycle_entry.get("short_tp_status") or "NONE")
                        ).upper()
                        active_cycle_index = int(state.get("active_cycle_index") or 0)
                        last_completed_cycle = int(state.get("cycle_completed_count") or 0)
                        # Stale-Pending-Schutz: Wenn der Pending-Cycle bereits hinter dem aktiven
                        # Cycle liegt oder als complete markiert ist, darf er den Build des
                        # nächsten First-Leg-/Second-Leg-Paares nicht mehr blockieren.
                        is_stale_pending = (
                            active_cycle_index > short_tp_pending_cycle
                            or last_completed_cycle >= short_tp_pending_cycle
                            or bool(cycle_entry.get("complete"))
                            or second_leg_processed
                        )
                        if is_stale_pending:
                            cycle_state = self._ensure_cycle_state(runtime_state)
                            previous_flags = {
                                "state_cycle_waiting_for_short_tp": bool(
                                    state.get("cycle_waiting_for_short_tp")
                                ),
                                "state_short_tp_pending_cycle": int(
                                    state.get("short_tp_pending_cycle") or 0
                                ),
                                "state_pending_short_cycle_index": int(
                                    state.get("pending_short_cycle_index") or 0
                                ),
                                "cycle_state_cycle_waiting_for_short_tp": bool(
                                    cycle_state.get("cycle_waiting_for_short_tp")
                                ),
                                "cycle_state_short_tp_pending_cycle": int(
                                    cycle_state.get("short_tp_pending_cycle") or 0
                                ),
                                "cycle_state_pending_short_cycle_index": int(
                                    cycle_state.get("pending_short_cycle_index") or 0
                                ),
                            }
                            state["cycle_waiting_for_short_tp"] = False
                            state["short_tp_pending_cycle"] = 0
                            state["pending_short_cycle_index"] = 0
                            cycle_state["cycle_waiting_for_short_tp"] = False
                            cycle_state["short_tp_pending_cycle"] = 0
                            cycle_state["pending_short_cycle_index"] = 0
                            self._persist_cycle_sequence_state(runtime_state)
                            _log_event(
                                "fixed_cycle_second_leg_pending_state_cleared_as_stale",
                                {
                                    "symbol": snapshot.symbol or self.config.symbol,
                                    "pending_cycle": short_tp_pending_cycle,
                                    "short_tp_status": short_tp_status,
                                    "cycle_waiting_for_short_tp": cycle_waiting_for_short_tp,
                                    "next_required_purpose": next_required_purpose,
                                    "first_leg_processed": first_leg_processed,
                                    "second_leg_processed": second_leg_processed,
                                    "active_cycle_index": active_cycle_index,
                                    "cycle_completed_count": last_completed_cycle,
                                    "previous_flags": previous_flags,
                                },
                            )
                        else:
                            _log_event(
                                "fixed_cycle_second_leg_pending_skip_rebuild",
                                {
                                    "symbol": snapshot.symbol or self.config.symbol,
                                    "pending_cycle": short_tp_pending_cycle,
                                    "short_tp_status": short_tp_status,
                                    "cycle_waiting_for_short_tp": cycle_waiting_for_short_tp,
                                    "next_required_purpose": next_required_purpose,
                                    "first_leg_processed": first_leg_processed,
                                    "second_leg_processed": second_leg_processed,
                                    "active_runtime_order_purposes": [
                                        order.purpose
                                        for order in runtime_state.active_orders.values()
                                        if order.purpose
                                        and order.purpose.upper()
                                        == self._normalize_cycle_purpose(
                                            self._cycle_purpose("short", short_tp_pending_cycle)
                                        )
                                    ],
                                    "active_snapshot_order_purposes": [
                                        order.purpose
                                        for order in snapshot.active_orders
                                        if order.purpose
                                        and order.purpose.upper()
                                        == self._normalize_cycle_purpose(
                                            self._cycle_purpose("short", short_tp_pending_cycle)
                                        )
                                    ],
                                    "reason": "waiting_for_second_leg_fill_or_confirmation",
                                },
                                runtime_state=runtime_state,
                            )
                            return intents
                    else:
                        _log_event(
                            "fixed_cycle_short_followup_missing_after_downside_rebuild_error",
                            {
                                "symbol": snapshot.symbol or self.config.symbol,
                                "short_tp_pending_cycle": short_tp_pending_cycle,
                                "cycle_waiting_for_short_tp": cycle_waiting_for_short_tp,
                            },
                        )
                    return intents
            context.audit.log_event(
                "fixed_cycle_downside_skip",
                strategy=self.name,
                skip_reason="long_add_locked",
            )
            return intents

        entry_reference_price = float(state.get("entry_reference_price") or 0.0)
        initial_long_qty = float(state.get("initial_long_qty") or 0.0)
        initial_short_qty = float(state.get("initial_short_qty") or 0.0)
        completed_cycles = int(state.get("cycle_completed_count") or 0)
        long_fill_price = self._cycle_state_last_fill_price(cycle_state.get("long_fills") or {})
        short_fill_price = self._cycle_state_last_fill_price(cycle_state.get("short_fills") or {})
        long_add_pending = self._get_first_leg_pending(state, cycle_state)
        short_tp_pending_cycle = self._get_second_leg_pending_cycle(state, cycle_state)
        waiting_for_short_tp = self._get_second_leg_waiting(state, cycle_state)
        if short_tp_pending_cycle > 0:
            pending_cycle_entry = self._get_cycle_sequence_entry(runtime_state, short_tp_pending_cycle)
            if bool(pending_cycle_entry.get("complete")):
                waiting_for_short_tp = False

        if completed_cycles >= self.config.max_cycles:
            logger.debug(
                "fixed_cycle_downside_skip %s",
                {
                    "skip_reason": "max_cycles_reached",
                    "completed_cycles": completed_cycles,
                    "max_cycles": self.config.max_cycles,
                },
            )
            return intents

        if entry_reference_price <= 0 or initial_long_qty <= 0 or initial_short_qty <= 0:
            logger.debug(
                "fixed_cycle_downside_skip %s",
                {
                    "skip_reason": "initial_quantities_missing",
                    "entry_reference_price": entry_reference_price,
                    "initial_long_qty": initial_long_qty,
                    "initial_short_qty": initial_short_qty,
                },
            )
            context.audit.log_event(
                "fixed_cycle_cycle_skipped",
                strategy=self.name,
                reason="initial_quantities_missing",
                entry_reference_price=entry_reference_price,
                initial_long_qty=initial_long_qty,
                initial_short_qty=initial_short_qty,
            )
            return intents

        reference_price = snapshot.current_price if snapshot.current_price > 0 else entry_reference_price
        cycle_entry_price = float(cycle_state.get("entry_price") or entry_reference_price)
        last_cycle_reference_price = float(cycle_state.get("last_cycle_reference_price") or 0.0)
        if (
            last_cycle_reference_price <= 0
            and not (cycle_state.get("long_fills") or cycle_state.get("short_fills"))
            and snapshot.long_avg > 0
        ):
            last_cycle_reference_price = float(snapshot.long_avg)
            cycle_state["last_cycle_reference_price"] = last_cycle_reference_price
        long_reference_candidate = last_cycle_reference_price
        long_reference = long_reference_candidate
        short_reference = (
            short_fill_price
            or cycle_entry_price
            or reference_price
        )
        logger.debug(
            "fixed_cycle_downside_build_inputs %s",
            {
                "entry_reference_price": entry_reference_price,
                "reference_price": reference_price,
                "cycle_entry_price": cycle_entry_price,
                "last_cycle_reference_price": last_cycle_reference_price,
                "cycle_long_fill_price": long_fill_price,
                "cycle_short_fill_price": short_fill_price,
                "current_long_cycle_index": int(state.get("current_long_cycle_index") or 0),
                "current_short_cycle_index": int(state.get("current_short_cycle_index") or 0),
                "max_cycles": self.config.max_cycles,
                "hard_stop_cycle": self.config.hard_stop_cycle,
                "long_fill_distance_pct": self.config.long_fill_distance_pct,
                "short_fill_distance_pct": self.config.short_fill_distance_pct,
                "long_cycle_qty_pct_of_initial": self.config.long_cycle_qty_pct_of_initial,
                "short_cycle_qty_pct_of_initial": self.config.short_cycle_qty_pct_of_initial,
                "long_qty": snapshot.long_qty,
                "short_qty": snapshot.short_qty,
                "long_avg": snapshot.long_avg,
                "short_avg": snapshot.short_avg,
                "initial_long_qty": initial_long_qty,
                "initial_short_qty": initial_short_qty,
                "long_add_pending": long_add_pending,
                "short_tp_pending_cycle": short_tp_pending_cycle,
                "cycle_waiting_for_short_tp": waiting_for_short_tp,
            },
        )
        long_distance_pct_config = self.config.long_fill_distance_pct
        long_distance_pct = self._clamp_pct_fraction(self._pct(long_distance_pct_config))
        completed_cycles = int(state.get("cycle_completed_count") or 0)
        current_long_cycle_index = int(state.get("current_long_cycle_index") or 0)
        long_cycle_number = max(current_long_cycle_index, completed_cycles) + 1
        next_required_purpose = str(state.get("next_required_purpose") or "").strip().upper()
        if (
            state.get("post_refill_structure_rebuild_required")
            and next_required_purpose.startswith("CYCLE_")
            and next_required_purpose.endswith("_LONG_ADD")
        ):
            parts = next_required_purpose.split("_")
            if len(parts) >= 3:
                try:
                    long_cycle_number = int(parts[1])
                except (TypeError, ValueError):
                    pass
        last_refill_completed_cycle_index = int(state.get("last_refill_completed_cycle_index") or 0)
        cycles_since_last_refill = completed_cycles - last_refill_completed_cycle_index
        _log_event(
            "fixed_cycle_long_add_allowed_after_refill_continuation",
            {
                "cycle_completed_count": completed_cycles,
                "cycle_pair_count": int(state.get("cycle_pair_count") or 0),
                "last_refill_completed_cycle_index": last_refill_completed_cycle_index,
                "cycles_since_last_refill": cycles_since_last_refill,
                "next_long_cycle_number": long_cycle_number,
                "refill_pending": bool(state.get("refill_pending")),
                "refill_required": bool(state.get("refill_required")),
                "post_refill_structure_rebuild_required": bool(
                    state.get("post_refill_structure_rebuild_required")
                ),
            },
        )
        short_intents = self._build_short_tp_follow_up(snapshot, runtime_state, context)
        short_intents = self._apply_live_short_tp_relief(
            snapshot,
            runtime_state,
            short_intents,
        )
        intents.extend(short_intents)
        sequence_state = get_cycle_sequence_state(state, self._sequence_config)

        # Wenn die Sequenz bereits klar auf dem Second-Leg steht und keine aktive
        # Second-Leg-Order mehr existiert, darf der Bot nach einem Refill nicht
        # mit leeren Intents stehen bleiben. In diesem Fall wird explizit der
        # Second-Leg-Purpose aus dem Sequenz-State neu aufgebaut, anstatt einen
        # weiteren First-Leg (LONG_ADD) zu versuchen.
        second_leg_rebuild_done = False
        if (
            not short_intents
            and bool(state.get("post_refill_structure_rebuild_required"))
        ):
            cycle_step = sequence_state.get("cycle_step")
            next_required = str(sequence_state.get("next_required_purpose") or "").upper()
            if cycle_step == STEP_WAITING_FOR_PAIR_SECOND_LEG and next_required:
                seq_cycle_index, seq_field = self._extract_cycle_sequence_target(next_required, {})
                if (
                    seq_cycle_index > 0
                    and seq_field == self._get_second_leg_status_field()
                ):
                    normalized_next = self._normalize_cycle_purpose(
                        next_required,
                        {
                            "cycle_index": seq_cycle_index,
                            "cycle_role": self._get_second_leg_cycle_role(),
                        },
                    )
                    if self._is_second_leg_purpose(normalized_next):
                        active_purposes = [
                            str(getattr(order, "purpose", "") or "").upper()
                            for order in runtime_state.active_orders.values()
                            if getattr(order, "purpose", None)
                        ]
                        if next_required not in active_purposes:
                            # Triggerpreis ausschließlich aus Sequenz-/State-Daten rekonstruieren.
                            cycle_entry = self._get_cycle_sequence_entry(
                                runtime_state, seq_cycle_index
                            )
                            trigger_price = float(
                                cycle_entry.get("short_tp_trigger_price")
                                or state.get("last_short_tp_trigger_price")
                                or 0.0
                            )
                            if trigger_price <= 0:
                                _log_event(
                                    "fixed_cycle_second_leg_rebuild_missing_state_trigger_price",
                                    {
                                        "symbol": snapshot.symbol or self.config.symbol,
                                        "cycle_index": seq_cycle_index,
                                        "cycle_step": cycle_step,
                                        "next_required_purpose": next_required,
                                        "active_order_purposes": active_purposes,
                                        "cycle_entry": dict(cycle_entry),
                                        "state_last_short_tp_trigger_price": float(
                                            state.get("last_short_tp_trigger_price") or 0.0
                                        ),
                                    },
                                )
                            else:
                                second_intent = self._build_short_tp_pair_intent(
                                    snapshot=snapshot,
                                    state=state,
                                    runtime_state=runtime_state,
                                    trigger_price=trigger_price,
                                    long_cycle_number=seq_cycle_index,
                                    context=context,
                                )
                                if second_intent is not None:
                                    intents.append(second_intent)
                                    second_leg_rebuild_done = True
                                    _log_event(
                                        "fixed_cycle_second_leg_rebuild_from_sequence_state",
                                        {
                                            "symbol": snapshot.symbol or self.config.symbol,
                                            "cycle_index": seq_cycle_index,
                                            "cycle_step": cycle_step,
                                            "next_required_purpose": next_required,
                                            "normalized_next_required_purpose": normalized_next,
                                            "trigger_price": trigger_price,
                                            "active_order_purposes": active_purposes,
                                            "processed_cycle_purposes": list(
                                                state.get("processed_cycle_purposes") or []
                                            ),
                                        },
                                    )

        if second_leg_rebuild_done:
            return intents

        if long_cycle_number <= self.config.max_cycles:
            purpose = self._get_first_leg_purpose(long_cycle_number)
            if not is_attempted_purpose_matching_sequence(purpose, sequence_state):
                _log_event(
                    "fixed_cycle_sequence_purpose_mismatch_blocked",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "category": context.category or self.config.category,
                        "active_cycle_index": sequence_state["active_cycle_index"],
                        "cycle_step": sequence_state["cycle_step"],
                        "next_required_purpose": sequence_state["next_required_purpose"],
                        "attempted_purpose": purpose,
                        "last_completed_purpose": sequence_state["last_completed_purpose"],
                        "current_effective_cycle": int(state.get("current_effective_cycle") or 0),
                        "current_long_cycle_index": int(state.get("current_long_cycle_index") or 0),
                        "current_short_cycle_index": int(state.get("current_short_cycle_index") or 0),
                        "cycle_pair_count": int(state.get("cycle_pair_count") or 0),
                        "completed_cycle_purposes": list(state.get("completed_cycle_purposes") or []),
                        "processed_cycle_purposes": list(state.get("processed_cycle_purposes") or []),
                        "active_order_purposes": [
                            str(getattr(order, "purpose", "") or "")
                            for order in runtime_state.active_orders.values()
                        ],
                    },
                )
                return intents
            cycle_sequence_entry, _, _ = self._reconcile_cycle_intent_reservation(
                snapshot,
                runtime_state,
                cycle_index=long_cycle_number,
                field_name="long_add_status",
                purpose=purpose,
                cycle_role="long_reduce",
            )
            blocking_cycle = self._blocking_cycle_before_long_add(runtime_state, long_cycle_number)
            previous_short_purpose = self._cycle_purpose("short", long_cycle_number - 1) if long_cycle_number > 1 else None
            previous_cycle_complete = False
            if long_cycle_number > 1:
                previous_cycle_entry = self._get_cycle_sequence_entry(runtime_state, long_cycle_number - 1)
                previous_cycle_complete = bool(previous_cycle_entry.get("complete"))
            skip_signature: dict[str, Any] | None = None
            skip_event_kwargs: dict[str, Any] | None = None
            if self._has_cycle_purpose_already_filled_or_processed(
                runtime_state,
                purpose,
                {"cycle_index": long_cycle_number, "cycle_role": "long_reduce"},
            ):
                _log_event(
                    "fixed_cycle_duplicate_cycle_purpose_blocked",
                    {
                        "cycle_index": long_cycle_number,
                        "purpose": purpose,
                        "phase": "long_add_status",
                        "reason": "cycle_long_add_already_processed",
                    },
                )
                skip_signature = {
                    "reason": "cycle_long_add_already_processed",
                    "cycle_number": long_cycle_number,
                    "purpose": purpose,
                }
                skip_event_kwargs = {
                    "strategy": self.name,
                    "skip_reason": "cycle_long_add_already_processed",
                    "cycle_number": long_cycle_number,
                    "purpose": purpose,
                }
                self._purge_filled_long_add_orders(runtime_state, long_cycle_number, purge_stale=True)
                _log_event(
                    "fixed_cycle_duplicate_cycle_long_add_blocked_after_fill",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": long_cycle_number,
                        "long_purpose": purpose,
                        "processed_cycle_purposes": list(state.get("processed_cycle_purposes") or []),
                        "active_order_ids": list(runtime_state.active_orders.keys()),
                        "reason": "long_add_already_processed",
                    },
                )
            elif blocking_cycle is not None:
                blocking_index, blocking_entry = blocking_cycle
                _log_event(
                    "fixed_cycle_waiting_for_short_tp_before_next_long_add",
                    {
                        "requested_cycle_index": long_cycle_number,
                        "blocking_cycle_index": blocking_index,
                        "blocking_cycle_state": dict(blocking_entry),
                        "purpose": purpose,
                    },
                )
                skip_signature = {
                    "reason": "waiting_for_short_tp_before_next_long_add",
                    "cycle_number": long_cycle_number,
                    "purpose": purpose,
                    "blocking_cycle_index": blocking_index,
                }
                skip_event_kwargs = {
                    "strategy": self.name,
                    "skip_reason": "waiting_for_short_tp_before_next_long_add",
                    "cycle_number": long_cycle_number,
                    "purpose": purpose,
                    "blocking_cycle_index": blocking_index,
                }
            elif waiting_for_short_tp and short_tp_pending_cycle > 0:
                skip_signature = {
                    "reason": "waiting_for_short_tp",
                    "cycle_number": long_cycle_number,
                    "purpose": purpose,
                    "short_tp_pending_cycle": short_tp_pending_cycle,
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                }
                skip_event_kwargs = {
                    "strategy": self.name,
                    "skip_reason": "waiting_for_short_tp",
                    "cycle_number": long_cycle_number,
                    "purpose": purpose,
                    "short_tp_pending_cycle": short_tp_pending_cycle,
                }
            elif (
                previous_short_purpose
                and snapshot.has_open_purpose(previous_short_purpose)
                and not previous_cycle_complete
            ):
                skip_signature = {
                    "reason": "short_cycle_order_still_open",
                    "cycle_number": long_cycle_number,
                    "purpose": purpose,
                    "blocking_purpose": previous_short_purpose,
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                }
                skip_event_kwargs = {
                    "strategy": self.name,
                    "skip_reason": "short_cycle_order_still_open",
                    "cycle_number": long_cycle_number,
                    "purpose": purpose,
                    "blocking_purpose": previous_short_purpose,
                }
            elif (
                previous_short_purpose
                and snapshot.has_open_purpose(previous_short_purpose)
                and previous_cycle_complete
            ):
                _log_event(
                    "fixed_cycle_previous_short_order_stale_ignored_for_next_long_add",
                    {
                        "previous_short_purpose": previous_short_purpose,
                        "next_long_cycle": long_cycle_number,
                        "previous_cycle_complete": previous_cycle_complete,
                    },
                )
            if skip_signature and skip_event_kwargs:
                previous_signature = state.get("last_downside_skip_signature")
                if previous_signature != skip_signature:
                    state["last_downside_skip_signature"] = skip_signature
                    context.audit.log_event("fixed_cycle_downside_skip", **skip_event_kwargs)
            else:
                state.pop("last_downside_skip_signature", None)
                first_leg_side = self._get_first_leg_side()
                first_leg_position_idx = self._get_first_leg_position_idx()
                first_leg_cycle_role = self._get_first_leg_cycle_role()
                first_leg_status_field = self._get_first_leg_status_field()
                first_leg_is_long = first_leg_side == "long"
                first_leg_distance_pct_config = (
                    self.config.long_fill_distance_pct
                    if first_leg_is_long
                    else self.config.short_fill_distance_pct
                )
                first_leg_distance_pct = self._clamp_pct_fraction(
                    self._pct(first_leg_distance_pct_config)
                )
                short_avg = float(snapshot.short_avg or 0.0)
                short_qty = float(snapshot.short_qty or 0.0)
                reference_source = "last_cycle_reference"
                reference_cycle_index: int | None = None
                reference_purpose: str | None = None
                first_leg_reference_candidate = (
                    long_reference_candidate if first_leg_is_long else short_reference
                )
                if (
                    not first_leg_is_long
                    and short_avg
                    and short_qty and float(short_qty) > 0
                ):
                    first_leg_reference_candidate = float(short_avg)
                    reference_source = "short_avg"
                if long_cycle_number > 1:
                    previous_cycle_index = long_cycle_number - 1
                    if first_leg_is_long:
                        previous_first_leg_reference = (
                            self._get_confirmed_previous_short_reduce_fill_price(
                                runtime_state, long_cycle_number
                            )
                        )
                    else:
                        previous_entry = self._get_cycle_sequence_entry(
                            runtime_state, previous_cycle_index
                        )
                        previous_long_reduce_fill_price = float(
                            previous_entry.get("long_reduce_fill_price") or 0.0
                        )
                        previous_long_reduce_fill_confirmed = bool(
                            previous_entry.get("long_reduce_fill_confirmed")
                        )
                        previous_first_leg_reference = (
                            previous_long_reduce_fill_price
                            if previous_long_reduce_fill_confirmed
                            and previous_long_reduce_fill_price > 0
                            else None
                        )
                    if previous_first_leg_reference is None:
                        previous_entry = self._get_cycle_sequence_entry(
                            runtime_state, previous_cycle_index
                        )
                        _log_event(
                            "fixed_cycle_long_add_reference_missing",
                            {
                                "symbol": snapshot.symbol or self.config.symbol,
                                "cycle_index": long_cycle_number,
                                "expected_previous_cycle_index": previous_cycle_index,
                                "expected_field": (
                                    "short_reduce_fill_price"
                                    if first_leg_is_long
                                    else "long_reduce_fill_price"
                                ),
                                "short_reduce_fill_confirmed": bool(
                                    previous_entry.get("short_reduce_fill_confirmed")
                                ),
                                "long_reduce_fill_confirmed": bool(
                                    previous_entry.get("long_reduce_fill_confirmed")
                                ),
                                "processed_cycle_purposes": list(
                                    state.get("processed_cycle_purposes") or []
                                ),
                                "active_order_purposes": [
                                    order.purpose
                                    for order in runtime_state.active_orders.values()
                                    if getattr(order, "purpose", None)
                                ],
                                "next_required_purpose": sequence_state.get(
                                    "next_required_purpose"
                                ),
                            },
                        )
                        return intents
                    first_leg_reference_candidate = previous_first_leg_reference
                    reference_source = (
                        "previous_short_reduce_fill"
                        if first_leg_is_long
                        else "previous_long_reduce_fill"
                    )
                    reference_cycle_index = previous_cycle_index
                    reference_purpose = self._get_second_leg_purpose(
                        reference_cycle_index
                    )
                first_leg_reference = first_leg_reference_candidate
                first_leg_qty = (
                    self._fixed_long_cycle_qty(
                        initial_long_qty,
                        snapshot.long_qty,
                        reference_price,
                        runtime_state,
                    )
                    if first_leg_is_long
                    else self._fixed_short_cycle_qty(
                        initial_short_qty,
                        snapshot.short_qty,
                        reference_price,
                        runtime_state=runtime_state,
                    )
                )
                raw_trigger_price = (
                    first_leg_reference * (1 - first_leg_distance_pct)
                    if first_leg_is_long
                    else first_leg_reference * (1 + first_leg_distance_pct)
                )
                trigger_price = self._normalize_price(raw_trigger_price, runtime_state)
                avg_reference_price = float(
                    (snapshot.long_avg if first_leg_is_long else snapshot.short_avg) or 0.0
                )
                _log_event(
                    "fixed_cycle_cycle_order_price_guard_check",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "purpose": purpose,
                        "current_price": float(snapshot.current_price or 0.0),
                        "reference_price": float(first_leg_reference or 0.0),
                        "avg_price": avg_reference_price,
                        "trigger_price": float(trigger_price or 0.0),
                        "order_type": "Market",
                        "trigger_direction": 2 if first_leg_is_long else 1,
                    },
                )
                if not first_leg_is_long:
                    short_price_floor = max(
                        float(snapshot.current_price or 0.0),
                        float(first_leg_reference or 0.0),
                        avg_reference_price,
                    )
                    if trigger_price <= short_price_floor:
                        _log_event(
                            "fixed_cycle_cycle_order_price_guard_blocked",
                            {
                                "symbol": snapshot.symbol or self.config.symbol,
                                "purpose": purpose,
                                "current_price": float(snapshot.current_price or 0.0),
                                "reference_price": float(first_leg_reference or 0.0),
                                "avg_price": avg_reference_price,
                                "trigger_price": float(trigger_price or 0.0),
                                "order_type": "Market",
                                "trigger_direction": 1,
                                "reason": "short_first_leg_trigger_not_above_reference",
                            },
                        )
                        trigger_price = 0.0
                raw_qty = (
                    snapshot.long_qty if first_leg_is_long else snapshot.short_qty
                ) * self._pct(self.config.reduction_pct_per_fill)
                will_append_intent = trigger_price > 0 and first_leg_qty > 0
                skip_reason: str | None = None
                if (
                    not first_leg_is_long
                    and self.config.recovery_activation_timing == "before_short_reduce_fill"
                    and will_append_intent
                ):
                    _log_event(
                        "fixed_cycle_recovery_activation_timing_selected",
                        {
                            "symbol": snapshot.symbol or self.config.symbol,
                            "cycle_index": long_cycle_number,
                            "recovery_activation_timing": self.config.recovery_activation_timing,
                            "max_pre_recovery_long_reduce_distance_pct": self.config.max_pre_recovery_long_reduce_distance_pct,
                            "max_post_recovery_long_reduce_distance_pct": self.config.max_post_recovery_long_reduce_distance_pct,
                        },
                    )
                    initial_long_qty = float(state.get("initial_long_qty") or 0.0)
                    current_long_qty = (
                        float(snapshot.long_qty or 0.0)
                        if float(snapshot.long_qty or 0.0) > 0
                        else initial_long_qty
                    )
                    long_avg = float(snapshot.long_avg or state.get("long_avg") or 0.0)
                    recovery_reference_price, projection_reference_source = (
                        self._select_pre_recovery_reference_price(
                            runtime_state,
                            cycle_state,
                            cycle_index=long_cycle_number,
                            first_leg_reference=float(first_leg_reference or 0.0),
                            entry_reference_price=float(entry_reference_price or 0.0),
                        )
                    )
                    projected_long_reduce_qty = self._fixed_long_cycle_qty(
                        initial_long_qty,
                        current_long_qty,
                        long_avg,
                        runtime_state,
                    )
                    projection = self._build_long_reduce_cover_projection(
                        current_price=float(snapshot.current_price or 0.0),
                        long_avg=long_avg,
                        short_avg=short_avg,
                        current_long_qty=current_long_qty,
                        current_short_qty=short_qty,
                        projected_short_reduce_fill_price=float(trigger_price or 0.0),
                        projected_short_reduce_qty=float(first_leg_qty or 0.0),
                        projected_long_reduce_qty=projected_long_reduce_qty,
                        last_relevant_fill_price=float(recovery_reference_price or 0.0),
                        runtime_state=runtime_state,
                    )
                    would_set_recovery_required = (
                        projection["distance_pct_from_last_fill"]
                        > float(self.config.max_pre_recovery_long_reduce_distance_pct or 0.0)
                    )
                    _log_event(
                        "fixed_cycle_pre_short_reduce_projection",
                        {
                            "symbol": snapshot.symbol or self.config.symbol,
                            "cycle_index": long_cycle_number,
                            "current_price": projection["current_price"],
                            "long_avg": projection["long_avg"],
                            "short_avg": projection["short_avg"],
                            "current_long_qty": projection["current_long_qty"],
                            "current_short_qty": projection["current_short_qty"],
                            "last_relevant_fill_price": recovery_reference_price,
                            "projection_reference_source": projection_reference_source,
                            "projected_short_reduce_qty": projection["projected_short_reduce_qty"],
                            "projected_long_reduce_qty": projection["projected_long_reduce_qty"],
                            "projected_short_reduce_fill_price": projection["projected_short_reduce_fill_price"],
                            "projected_short_reduce_loss_usdt": projection["projected_short_reduce_loss_usdt"],
                            "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
                            "target_profit_usdt": projection["target_profit_usdt"],
                            "projected_required_profit_to_cover_loss": projection["projected_required_profit_to_cover_loss"],
                            "projected_loss_per_long_reduce_unit": projection["projected_loss_per_long_reduce_unit"],
                            "projected_required_long_reduce_price": projection["projected_required_long_reduce_price"],
                            "projected_cover_distance_pct_from_last_fill": projection["distance_pct_from_last_fill"],
                            "projected_cover_distance_pct_from_long_avg": projection["distance_pct_from_long_avg"],
                            "projected_cover_distance_pct_from_current_price": projection["distance_pct_from_current_price"],
                            "remaining_short_qty_after_projected_reduce": projection["remaining_short_qty_after_projected_reduce"],
                            "remaining_long_qty_after_projected_reduce": projection["remaining_long_qty_after_projected_reduce"],
                            "fee_rate_used": projection["fee_rate_used"],
                            "estimated_fee_component": projection["estimated_fee_component"],
                            "included_realized_cycle_net": projection["included_realized_cycle_net"],
                            "included_buffer": projection["included_buffer"],
                            "guard_threshold_cover_distance_pct": self.config.max_pre_recovery_long_reduce_distance_pct,
                            "would_set_recovery_required": would_set_recovery_required,
                            "guard_reason": (
                                "pre_short_reduce_long_reduce_distance_too_wide"
                                if would_set_recovery_required
                                else None
                            ),
                        },
                    )
                    # Root-fix: keep projection diagnostics, but do not auto-activate
                    # recovery purely because the distance threshold was exceeded.
                cycle_state_long_fills = cycle_state.setdefault("long_fills", {})
                cycle_state_short_fills = cycle_state.setdefault("short_fills", {})
                long_fill_exists = str(long_cycle_number) in cycle_state_long_fills
                short_fill_exists = str(long_cycle_number) in cycle_state_short_fills
                first_leg_fill_exists = (
                    long_fill_exists if first_leg_is_long else short_fill_exists
                )
                cycle_waiting_for_short_tp_flag = waiting_for_short_tp
                short_tp_cycle = self._get_second_leg_pending_cycle(state, cycle_state)
                cycle_state_waiting = self._get_second_leg_waiting(state, cycle_state)
                active_cycle_index = int(state.get("active_cycle_index") or 0)
                last_completed_cycle = int(state.get("cycle_completed_count") or 0)
                cycle_step = str(state.get("cycle_step") or "")
                if short_tp_cycle > 0:
                    pending_cycle_entry = self._get_cycle_sequence_entry(
                        runtime_state, short_tp_cycle
                    )
                    stale_pending_second_leg = (
                        active_cycle_index > short_tp_cycle
                        or last_completed_cycle >= short_tp_cycle
                        or bool(pending_cycle_entry.get("complete"))
                    )
                    if stale_pending_second_leg:
                        previous_pending_state = {
                            "cycle_waiting_for_short_tp": cycle_waiting_for_short_tp_flag,
                            "short_tp_pending_cycle": short_tp_cycle,
                            "cycle_state_waiting": cycle_state_waiting,
                            "active_cycle_index": active_cycle_index,
                            "cycle_completed_count": last_completed_cycle,
                            "cycle_step": cycle_step,
                        }
                        self._set_second_leg_waiting_state(
                            state,
                            cycle_state,
                            waiting=False,
                            cycle_index=0,
                        )
                        state["pending_short_cycle_index"] = 0
                        cycle_state["pending_short_cycle_index"] = 0
                        self._persist_cycle_sequence_state(runtime_state)
                        _log_event(
                            "fixed_cycle_duplicate_long_reduce_stale_pending_cleared",
                            {
                                "symbol": snapshot.symbol or self.config.symbol,
                                "pending_cycle": short_tp_cycle,
                                "active_cycle_index": active_cycle_index,
                                "cycle_completed_count": last_completed_cycle,
                                "cycle_step": cycle_step,
                                "previous_pending_state": previous_pending_state,
                            },
                        )
                        cycle_waiting_for_short_tp_flag = False
                        short_tp_cycle = 0
                        cycle_state_waiting = False
                pending_second_leg_blocks_current_cycle = (
                    short_tp_cycle > 0
                    and short_tp_cycle == active_cycle_index
                    and (
                        cycle_step == STEP_WAITING_FOR_PAIR_SECOND_LEG
                        or cycle_waiting_for_short_tp_flag
                        or cycle_state_waiting
                    )
                )
                allow_long_reduce = not (
                    first_leg_fill_exists
                    or self._cycle_status_blocks_build(
                        cycle_sequence_entry.get(first_leg_status_field)
                    )
                    or pending_second_leg_blocks_current_cycle
                )
                guard_payload = {
                    "cycle_index": long_cycle_number,
                    "long_fill_exists": long_fill_exists,
                    "short_fill_exists": short_fill_exists,
                    "first_leg_fill_exists": first_leg_fill_exists,
                    "cycle_waiting_for_short_tp": cycle_waiting_for_short_tp_flag,
                    "short_tp_pending_cycle": short_tp_cycle,
                    "current_long_cycle_index": int(state.get("current_long_cycle_index") or 0),
                    "current_short_cycle_index": int(state.get("current_short_cycle_index") or 0),
                    "current_effective_cycle": int(state.get("current_effective_cycle") or 0),
                    "active_cycle_index": active_cycle_index,
                    "cycle_step": cycle_step,
                    "pending_second_leg_blocks_current_cycle": (
                        pending_second_leg_blocks_current_cycle
                    ),
                    "cycle_sequence_entry": dict(cycle_sequence_entry),
                    "allow_long_reduce": allow_long_reduce,
                    "first_leg_side": first_leg_side,
                    "first_leg_cycle_role": first_leg_cycle_role,
                }
                self._emit_throttled_strategy_audit(
                    runtime_state,
                    context,
                    "fixed_cycle_long_reduce_guard_check",
                    guard_payload,
                    signature_key=f"long_reduce_guard_check_{long_cycle_number}",
                    interval_ms=120000,
                )
                if not allow_long_reduce:
                    duplicate_payload = {
                        "symbol": self.config.symbol,
                        "cycle_index": long_cycle_number,
                        "long_purpose": purpose,
                        "short_tp_pending_cycle": short_tp_cycle,
                        "cycle_waiting_for_short_tp": cycle_waiting_for_short_tp_flag,
                        "cycle_state_long_fill_present": first_leg_fill_exists,
                        "active_runtime_purposes": [
                            str(getattr(order, "purpose", "") or "")
                            for order in runtime_state.active_orders.values()
                        ],
                        "active_snapshot_purposes": [
                            str(getattr(order, "purpose", "") or "")
                            for order in snapshot.active_orders
                        ],
                        "reason": f"{first_leg_cycle_role}_already_filled_waiting_second_leg",
                        "first_leg_side": first_leg_side,
                    }
                    self._emit_throttled_strategy_audit(
                        runtime_state,
                        context,
                        "fixed_cycle_duplicate_long_reduce_blocked_waiting_short_tp",
                        duplicate_payload,
                        signature_key=f"duplicate_long_reduce_blocked_{long_cycle_number}",
                        interval_ms=120000,
                    )
                if not will_append_intent:
                    skip_reason = (
                        "trigger_price_non_positive"
                        if trigger_price <= 0
                        else f"{first_leg_side}_qty_non_positive"
                    )
                elif not allow_long_reduce:
                    skip_reason = f"{first_leg_cycle_role}_already_filled_waiting_second_leg"
                gate_allowed, gate_reason, gate_payload = self._can_submit_cycle_intent(
                    runtime_state,
                    snapshot,
                    purpose=purpose,
                    cycle_index=long_cycle_number,
                    cycle_role=first_leg_cycle_role,
                )
                gate_payload = {
                    **gate_payload,
                    "symbol": snapshot.symbol or self.config.symbol,
                }
                if not gate_allowed:
                    gate_payload["reason"] = gate_reason or f"{first_leg_cycle_role}_gate_blocked"
                    _log_event("fixed_cycle_state_gate_intent_blocked", gate_payload)
                    skip_reason = gate_reason or f"{first_leg_cycle_role}_gate_blocked"
                    will_append_intent = False
                else:
                    gate_payload["reason"] = f"{first_leg_cycle_role}_allowed"
                    _log_event("fixed_cycle_state_gate_intent_allowed", gate_payload)
                logger.debug(
                    "fixed_cycle_downside_cycle_evaluated %s",
                    {
                        "cycle_number": long_cycle_number,
                        "step_index": 1,
                        "side": first_leg_side,
                        "long_fill_price": long_fill_price,
                        "cycle_entry_price": cycle_entry_price,
                        "live_reference_price": reference_price,
                        "long_reference_candidate": first_leg_reference_candidate,
                        "final_long_reference": first_leg_reference,
                        "distance_pct_used": first_leg_distance_pct,
                        "safety_offset_used": 0.0,
                        "raw_trigger_price": raw_trigger_price,
                        "normalized_trigger_price": trigger_price,
                        "computed_qty_raw": raw_qty,
                        "computed_qty_normalized": first_leg_qty,
                        "purpose": purpose,
                        "reduce_only": True,
                        "will_append_intent": will_append_intent,
                        "skip_reason": skip_reason,
                    },
                )
                if not will_append_intent or not allow_long_reduce:
                    context.audit.log_event(
                        "fixed_cycle_downside_skip",
                        strategy=self.name,
                        skip_reason=skip_reason,
                        cycle_number=long_cycle_number,
                        side=first_leg_side,
                        reference_price_used=first_leg_reference,
                        raw_trigger_price=raw_trigger_price,
                        normalized_trigger_price=trigger_price,
                        computed_qty_normalized=first_leg_qty,
                        purpose=purpose,
                    )
                else:
                    context.audit.log_event(
                        "fixed_cycle_long_reduce_planned",
                        strategy=self.name,
                        cycle_index=long_cycle_number,
                        side=first_leg_side,
                        purpose=purpose,
                        entry_reference_price=entry_reference_price,
                        distance_pct=first_leg_distance_pct_config,
                        distance_pct_used=first_leg_distance_pct,
                        long_fill_price=long_fill_price,
                        cycle_entry_price=cycle_entry_price,
                        live_reference_price=reference_price,
                        final_long_reference=first_leg_reference,
                        reference_source=reference_source,
                        reference_cycle_index=reference_cycle_index,
                        reference_purpose=reference_purpose,
                        reference_price=first_leg_reference,
                        long_fill_distance_pct=first_leg_distance_pct_config,
                        trigger_price=trigger_price,
                        trigger_formula=(
                            "final_long_reference * (1 - distance_pct)"
                            if first_leg_is_long
                            else "final_short_reference * (1 + distance_pct)"
                        ),
                        trigger_price_raw=raw_trigger_price,
                        trigger_price_normalized=trigger_price,
                        qty_formula=(
                            "current_long_qty * reduction_pct_per_fill"
                            if first_leg_is_long
                            else "current_short_qty * reduction_pct_per_fill"
                        ),
                        qty_raw=raw_qty,
                        qty_normalized=first_leg_qty,
                        order_type="Limit",
                        reduce_only=True,
                        short_avg=short_avg,
                        current_short_qty=short_qty,
                        real_distance_from_short_avg_pct=(
                            (
                                (first_leg_reference - short_avg)
                                / short_avg
                                * 100
                            )
                            if short_avg
                            else None
                        )
                        if not first_leg_is_long
                        else None,
                    )
                    self._reserve_cycle_intent_slot(
                        runtime_state,
                        cycle_index=long_cycle_number,
                        field_name=first_leg_status_field,
                        normalized_purpose=self._normalize_cycle_purpose(
                            purpose,
                            {
                                "cycle_index": long_cycle_number,
                                "cycle_role": first_leg_cycle_role,
                            },
                        ),
                        qty=first_leg_qty,
                        trigger_price=trigger_price,
                    )
                    intent = StrategyIntent(
                        side=first_leg_side,
                        qty=first_leg_qty,
                        purpose=purpose,
                        order_type="Market",
                        reduce_only=True,
                        trigger_price=trigger_price,
                        trigger_direction=2 if first_leg_is_long else 1,
                        trigger_by="LastPrice",
                        close_on_trigger=True,
                        position_idx=first_leg_position_idx,
                        metadata={
                            "cycle_index": long_cycle_number,
                            "cycle_role": first_leg_cycle_role,
                            **(
                                {"replace_open_purpose": purpose}
                                if self._should_attach_replace_open_purpose(
                                    snapshot,
                                    runtime_state,
                                    purpose,
                                    cycle_index=long_cycle_number,
                                    cycle_role=first_leg_cycle_role,
                                )
                                else {}
                            ),
                            "entry_reference_price": entry_reference_price,
                        },
                    )
                    intents.append(intent)
                    if self._get_first_leg_side() == "short":
                        _log_event(
                            "fixed_cycle_short_first_leg_side_check",
                            {
                                "symbol": snapshot.symbol or self.config.symbol,
                                "cycle_index": long_cycle_number,
                                "side": self._get_first_leg_side(),
                                "purpose": intent.purpose,
                                "qty": intent.qty,
                                "trigger_price": intent.trigger_price,
                                "reference_price": first_leg_reference,
                                "current_long_qty": snapshot.long_qty,
                                "current_short_qty": snapshot.short_qty,
                                "cycle_role": first_leg_cycle_role,
                                "qty_formula": (
                                    "current_long_qty * reduction_pct_per_fill"
                                    if first_leg_is_long
                                    else "current_short_qty * reduction_pct_per_fill"
                                ),
                            },
                        )
                    state["long_add_rebuild_allowed"] = False
        long_intents = [intent for intent in intents if intent.side == "long"]
        short_intents = [intent for intent in intents if intent.side == "short"]
        first_long_purpose = self._cycle_purpose("long", 1)
        first_short_purpose = self._cycle_purpose("short", 1)
        context.audit.log_event(
            "fixed_cycle_downside_build_result",
            strategy=self.name,
            long_intent_count=len(long_intents),
            short_intent_count=len(short_intents),
            total_intent_count=len(intents),
            purposes=[intent.purpose for intent in intents],
            first_long_cycle_present=any(intent.purpose == first_long_purpose for intent in intents),
            first_short_cycle_present=any(intent.purpose == first_short_purpose for intent in intents),
            long_reference=long_reference,
            short_reference=short_reference,
        )
        logger.debug(
            "fixed_cycle_downside_build_result %s",
            {
                "long_intent_count": len(long_intents),
                "short_intent_count": len(short_intents),
                "total_intent_count": len(intents),
                "purposes": [intent.purpose for intent in intents],
                "first_long_cycle_present": any(intent.purpose == first_long_purpose for intent in intents),
                "first_short_cycle_present": any(intent.purpose == first_short_purpose for intent in intents),
                "long_reference": long_reference,
                "short_reference": short_reference,
            },
        )
        self._write_cycle_state(cycle_state)
        return intents

    def _build_short_tp_follow_up(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent]:
        state = runtime_state.strategy_state
        self._ensure_cycle_sequence_state(runtime_state)
        cycle_state = self._ensure_cycle_state(runtime_state)
        long_fills = cycle_state.get("long_fills") or {}
        short_fills = cycle_state.get("short_fills") or {}
        processed_purposes = {
            self._normalize_cycle_purpose(item)
            for item in state.get("processed_cycle_purposes") or []
            if str(item or "")
        }
        short_tp_pending_cycle = self._get_second_leg_pending_cycle(state, cycle_state)
        cycle_index = short_tp_pending_cycle
        first_leg_purpose = self._get_first_leg_purpose(cycle_index) if cycle_index > 0 else None
        second_leg_purpose = self._get_second_leg_purpose(cycle_index) if cycle_index > 0 else None
        purpose = second_leg_purpose
        long_purpose = self._cycle_purpose("long", cycle_index) if cycle_index > 0 else None
        # Defensive Initialisierung für Staging-/Split-Hilfsvariablen, die in
        # Fallback-Logs und Metadaten verwendet werden können.
        stages: list[dict[str, Any]] = []
        rejected_stage_indices: list[int] = []
        rejected_stage_notionals: list[float] = []
        min_notional: float = 0.0
        intents: list[StrategyIntent] = []
        # Wenn noch kein Pending-Cycle gesetzt ist, die Sequenz aber klar einen Second-Leg
        # für einen bestimmten Cycle verlangt, diesen Cycle als Kandidaten übernehmen.
        if cycle_index <= 0:
            next_required_seq = str(state.get("next_required_purpose") or "").upper()
            if next_required_seq:
                seq_cycle_index, seq_field = self._extract_cycle_sequence_target(next_required_seq, {})
                if (
                    seq_cycle_index > 0
                    and seq_field == self._get_second_leg_status_field()
                ):
                    normalized_next_seq = self._normalize_cycle_purpose(
                        next_required_seq,
                        {
                            "cycle_index": seq_cycle_index,
                            "cycle_role": self._get_second_leg_cycle_role(),
                        },
                    )
                    if self._is_second_leg_purpose(normalized_next_seq):
                        cycle_index = seq_cycle_index
                        short_tp_pending_cycle = seq_cycle_index
                        first_leg_purpose = self._get_first_leg_purpose(cycle_index)
                        second_leg_purpose = self._get_second_leg_purpose(cycle_index)
                        purpose = second_leg_purpose
                        long_purpose = self._cycle_purpose("long", cycle_index)
        active_order_purposes = [
            getattr(order, "purpose", None)
            for order in runtime_state.active_orders.values()
            if getattr(order, "purpose", None)
        ]
        processed_cycle_purposes = list(state.get("processed_cycle_purposes") or [])
        _log_event(
            "fixed_cycle_short_followup_entered_after_long_reduce_fill",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "cycle_waiting_for_short_tp": self._get_second_leg_waiting(state, cycle_state),
                "short_tp_pending_cycle": short_tp_pending_cycle,
                "cycle_index": cycle_index,
                "active_order_purposes": active_order_purposes,
                "processed_cycle_purposes": processed_cycle_purposes,
            },
        )
        if self._cycle_build_block_active(state):
            _log_event(
                "fixed_cycle_refill_block_cycle_build",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "purpose": purpose,
                    "cycle_role": "short_reduce",
                    "cycle_pair_count": state.get("cycle_pair_count"),
                    "cycle_completed_count": state.get("cycle_completed_count"),
                    "refill_pending": bool(state.get("refill_pending")),
                    "refill_required": bool(state.get("refill_required")),
                    "refill_in_progress": bool(state.get("refill_in_progress")),
                    "bot_state": state.get("bot_state"),
                    "cycle_block_status": state.get("cycle_block_status"),
                    "reason": "refill_required",
                },
            )
            return []

        def _emit_short_tp_follow_up_skip(reason: str, **extra: Any) -> None:
            runtime_active_orders = list(runtime_state.active_orders.values())
            extra.pop("pending_cycle_loss_usdt", None)
            context.audit.log_event(
                "fixed_cycle_short_tp_follow_up_skip",
                strategy=self.name,
                reason=reason,
                symbol=extra.pop("symbol", snapshot.symbol or self.config.symbol),
                cycle_index=cycle_index,
                purpose=purpose,
                long_purpose=long_purpose,
                cycle_waiting_for_short_tp=self._get_second_leg_waiting(state),
                short_tp_pending_cycle=short_tp_pending_cycle,
                current_long_cycle_index=int(state.get("current_long_cycle_index") or 0),
                current_short_cycle_index=int(state.get("current_short_cycle_index") or 0),
                cycle_long_add_filled=bool(state.get("cycle_long_add_filled")),
                cycle_short_tp_filled=bool(state.get("cycle_short_tp_filled")),
                long_add_pending=self._get_first_leg_pending(state, cycle_state),
                pending_cycle_loss_usdt=float(state.get("pending_cycle_loss_usdt") or 0.0),
                pending_loss_updated_in_fill=bool(state.get("pending_loss_updated_in_fill")),
                force_exit_rebuild=bool(state.get("force_exit_rebuild")),
                force_short_tp_rebuild=bool(state.get("force_short_tp_rebuild")),
                refill_pending=bool(state.get("refill_pending")),
                refill_in_progress=bool(state.get("refill_in_progress")),
                active_order_purposes=[
                    order.purpose for order in runtime_active_orders if getattr(order, "purpose", None)
                ],
                runtime_active_order_ids=list(runtime_state.active_orders.keys()),
                snapshot_active_order_purposes=[
                    order.purpose for order in snapshot.active_orders if getattr(order, "purpose", None)
                ],
                **extra,
            )

        cycle_step = str(state.get("cycle_step") or "")
        next_required_guard = str(state.get("next_required_purpose") or "").upper()
        active_idx = int(state.get("active_cycle_index") or cycle_index or 1)
        if active_idx <= 0:
            active_idx = max(cycle_index, 1)
        expected_first_leg = self._normalize_cycle_purpose(
            self._get_first_leg_purpose(active_idx),
            {"cycle_index": active_idx, "cycle_role": self._get_first_leg_cycle_role()},
        )
        sequence_waits_for_first_leg = cycle_step == STEP_WAITING_FOR_PAIR_FIRST_LEG or (
            next_required_guard and next_required_guard == expected_first_leg
        )
        first_leg_already_filled = False
        if sequence_waits_for_first_leg:
            first_leg_already_filled = self._has_cycle_purpose_already_filled_or_processed(
                runtime_state,
                expected_first_leg,
                {
                    "cycle_index": active_idx,
                    "cycle_role": self._get_first_leg_cycle_role(),
                },
            )

        if sequence_waits_for_first_leg and not first_leg_already_filled:
            _emit_short_tp_follow_up_skip(
                "sequence_waiting_for_first_leg",
                cycle_step=cycle_step,
                next_required_purpose=next_required_guard,
                expected_first_leg_purpose=expected_first_leg,
            )
            return []

        fallback_state = self._get_short_tp_fallback_state(runtime_state)
        if fallback_state.active:
            current_price = float(snapshot.current_price or 0.0)

            if current_price >= fallback_state.original_trigger_price:
                logger.info("Fallback cancel → price recovered above trigger")
                reset_short_tp_fallback(fallback_state)
                self._store_short_tp_fallback_state(runtime_state, fallback_state)
                self._clear_short_tp_fallback_order_context(runtime_state)
            else:
                _emit_short_tp_follow_up_skip(
                    "fallback_state_active_blocking_short_tp_build",
                    fallback_active=True,
                    fallback_original_trigger_price=float(
                        fallback_state.original_trigger_price or 0.0
                    ),
                    current_price=current_price,
                )
                return []
        if cycle_index <= 0:
            _emit_short_tp_follow_up_skip("cycle_index_non_positive")
            return []
        cycle_waiting_for_short_tp = self._get_second_leg_waiting(state)
        short_followup_pending = cycle_waiting_for_short_tp or (
            short_tp_pending_cycle > 0 and short_tp_pending_cycle == cycle_index
        )
        if not short_followup_pending:
            # Zusätzlicher Fallback: Wenn die Sequenz klar sagt, dass als Nächstes ein Second-Leg
            # gebaut werden soll, aber keine Pending-Flags mehr existieren und keine aktive
            # Second-Leg-Order vorhanden ist, stellen wir den Pending-State aus der Sequenz
            # wieder her.
            next_required = str(state.get("next_required_purpose") or "").upper()
            if next_required:
                # Prüfen, ob next_required eindeutig ein Second-Leg-Purpose ist und zu diesem Cycle passt.
                seq_cycle_index, seq_field = self._extract_cycle_sequence_target(next_required, {})
                if (
                    seq_cycle_index > 0
                    and seq_field == self._get_second_leg_status_field()
                    and seq_cycle_index == cycle_index
                ):
                    normalized_next = self._normalize_cycle_purpose(
                        next_required, {"cycle_index": cycle_index, "cycle_role": self._get_second_leg_cycle_role()}
                    )
                    if self._is_second_leg_purpose(normalized_next):
                        # Bestätigen, dass das First-Leg für diesen Cycle wirklich gefüllt/verarbeitet ist.
                        first_leg_purpose_seq = self._get_first_leg_purpose(cycle_index)
                        first_leg_filled = self._has_cycle_purpose_already_filled_or_processed(
                            runtime_state,
                            first_leg_purpose_seq,
                            {"cycle_index": cycle_index, "cycle_role": self._get_first_leg_cycle_role()},
                        )
                        if first_leg_filled:
                            # Sicherstellen, dass keine aktive Second-Leg-Order mehr existiert.
                            if not self._short_followup_active_for_cycle(cycle_index, runtime_state, snapshot):
                                cycle_entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
                                second_leg_status = self._get_second_leg_status(cycle_entry)
                                # Nur wenn Second-Leg noch nicht final abgeschlossen ist.
                                if not self._cycle_status_finalized(second_leg_status):
                                    waiting_before = cycle_waiting_for_short_tp
                                    pending_before = short_tp_pending_cycle
                                    self._set_second_leg_waiting_state(
                                        state,
                                        cycle_state,
                                        waiting=True,
                                        cycle_index=cycle_index,
                                    )
                                    waiting_after = self._get_second_leg_waiting(state, cycle_state)
                                    pending_after = self._get_second_leg_pending_cycle(state, cycle_state)
                                    snapshot_active_purposes = [
                                        getattr(order, "purpose", None)
                                        for order in snapshot.active_orders
                                        if getattr(order, "purpose", None)
                                    ]
                                    all_active_purposes = [
                                        purpose
                                        for purpose in (
                                            list(active_order_purposes) + snapshot_active_purposes
                                        )
                                        if purpose
                                    ]
                                    _log_event(
                                        "fixed_cycle_second_leg_forced_from_sequence_state",
                                        {
                                            "symbol": snapshot.symbol or self.config.symbol,
                                            "cycle_index": cycle_index,
                                            "next_required_purpose": next_required,
                                            "normalized_next_required_purpose": normalized_next,
                                            "first_leg_purpose": first_leg_purpose_seq,
                                            "first_leg_filled": True,
                                            "second_leg_status_before": second_leg_status,
                                            "second_leg_purpose": self._get_second_leg_purpose(cycle_index),
                                            "seq_cycle_index": seq_cycle_index,
                                            "cycle_waiting_for_short_tp_before": waiting_before,
                                            "cycle_waiting_for_short_tp_after": waiting_after,
                                            "short_tp_pending_cycle_before": pending_before,
                                            "short_tp_pending_cycle_after": pending_after,
                                            "active_order_purposes": all_active_purposes,
                                            "processed_cycle_purposes": processed_cycle_purposes,
                                        },
                                    )
                                    # Pending-State wiederhergestellt → als pending behandeln.
                                    cycle_waiting_for_short_tp = waiting_after
                                    short_tp_pending_cycle = pending_after
                                    short_followup_pending = True
        if not short_followup_pending:
            _emit_short_tp_follow_up_skip("cycle_waiting_for_short_tp_false")
            return []
        cycle_sequence_entry, _, _ = self._reconcile_cycle_intent_reservation(
            snapshot,
            runtime_state,
            cycle_index=cycle_index,
            field_name=self._get_second_leg_status_field(),
            purpose=purpose or "",
            cycle_role="short_reduce",
        )
        long_add_status = str(cycle_sequence_entry.get("long_add_status") or "NONE").upper()
        short_tp_status = self._get_second_leg_status(cycle_sequence_entry)
        second_leg_status_field = self._get_second_leg_status_field()
        entry_status = str(cycle_sequence_entry.get(second_leg_status_field) or "NONE").upper()
        first_leg_cycle_role = self._get_first_leg_cycle_role()
        cycle_long_add_filled = long_add_status in {"FILLED", "PROCESSED"} or self._has_cycle_purpose_already_filled_or_processed(
            runtime_state,
            first_leg_purpose or "",
            {"cycle_index": cycle_index, "cycle_role": first_leg_cycle_role},
        )
        normalized_first_leg_purpose = self._normalize_cycle_purpose(
            self._get_first_leg_purpose(cycle_index),
            {"cycle_index": cycle_index, "cycle_role": self._get_first_leg_cycle_role()},
        )
        normalized_second_leg_purpose = self._normalize_cycle_purpose(
            self._get_second_leg_purpose(cycle_index),
            {
                "cycle_index": cycle_index,
                "cycle_role": self._get_second_leg_cycle_role(),
            },
        )
        second_leg_is_long = "LONG" in normalized_second_leg_purpose
        second_leg_fill_exists = (
            str(cycle_index) in long_fills if second_leg_is_long else str(cycle_index) in short_fills
        )
        second_leg_processed = (
            normalized_second_leg_purpose in processed_purposes or second_leg_fill_exists
        )
        second_leg_reserved = self._cycle_status_blocks_build(entry_status)
        if second_leg_processed or second_leg_reserved:
            # Root-Fix: Wenn der Second-Leg bereits als FILLED bestätigt ist
            # (Fill-Eintrag vorhanden), aber der Cycle-Zustand noch nicht als
            # abgeschlossen/processed persistiert wurde, darf der Followup-Builder
            # nicht einfach mit "already_processed" abbrechen. Stattdessen wird
            # die bestehende Completion-Logik über _try_complete_cycle_pair_after_confirmed_pnl
            # erneut angestoßen.
            if second_leg_processed and not second_leg_reserved:
                entry_complete = bool(cycle_sequence_entry.get("complete"))
                processed_cycle_purposes = set(state.get("processed_cycle_purposes") or [])
                if normalized_second_leg_purpose not in processed_cycle_purposes or not entry_complete:
                    self._try_complete_cycle_pair_after_confirmed_pnl(
                        runtime_state,
                        cycle_index,
                        trigger_purpose=normalized_second_leg_purpose,
                    )
            reason = (
                "short_reduce_slot_reserved"
                if entry_status in {
                    "INTENT_BUILT",
                    "SUBMITTING",
                    "SUBMITTED",
                    "OPEN",
                    "NEW",
                    "UNTRIGGERED",
                    "PARTIALLY_FILLED",
                }
                else "cycle_short_tp_already_processed"
            )
            _emit_short_tp_follow_up_skip(
                reason,
                cycle_sequence_entry=dict(cycle_sequence_entry),
            )
            return []

        pending_before = float(state.get("pending_cycle_loss_usdt") or 0.0)

        current_short_cycle_index = int(state.get("current_short_cycle_index") or 0)
        current_long_cycle_index = int(state.get("current_long_cycle_index") or 0)
        cycle_state_short_index = int(cycle_state.get("short_cycle_index") or 0)
        cycle_state_long_index = int(cycle_state.get("long_cycle_index") or 0)
        current_second_leg_index = (
            current_long_cycle_index if second_leg_is_long else current_short_cycle_index
        )
        cycle_state_second_leg_index = (
            cycle_state_long_index if second_leg_is_long else cycle_state_short_index
        )
        skip_reason = (
            "long_cycle_already_filled" if second_leg_is_long else "short_cycle_already_filled"
        )

        if max(current_second_leg_index, cycle_state_second_leg_index) >= cycle_index:
            _emit_short_tp_follow_up_skip(
                skip_reason,
                cycle_state_short_index=cycle_state_short_index,
                cycle_state_long_index=cycle_state_long_index,
                current_short_cycle_index=current_short_cycle_index,
                current_long_cycle_index=current_long_cycle_index,
            )
            context.audit.log_event(
                "fixed_cycle_downside_skip",
                strategy=self.name,
                skip_reason=skip_reason,
                cycle_number=cycle_index,
                purpose=purpose,
                current_second_leg_cycle_index=current_second_leg_index,
                cycle_state_second_leg_index=cycle_state_second_leg_index,
                current_short_cycle_index=current_short_cycle_index,
                cycle_state_short_index=cycle_state_short_index,
                current_long_cycle_index=current_long_cycle_index,
                cycle_state_long_index=cycle_state_long_index,
            )
            return []

        def _has_pending_order(purpose_name: str) -> bool:
            for order in snapshot.active_orders:
                if order.purpose != purpose_name:
                    continue
                status = order.status
                if status in {"FILLED", "CANCELED", "CANCELLED", "REJECTED", "EXPIRED"}:
                    continue
                if float(order.remaining_qty or 0.0) <= 0:
                    continue
                return True
            return False

        def _resolve_second_leg_eps() -> tuple[float, float]:
            symbol, rules, _ = self._resolve_instrument_rules(runtime_state)
            tick_decimal = (
                rules.get("tick_size")
                if isinstance(rules, dict) and rules.get("tick_size")
                else None
            )
            try:
                price_tick_size = float(tick_decimal) if tick_decimal is not None else float(
                    self.config.price_tick_size or 0.0
                )
            except (TypeError, ValueError):
                price_tick_size = float(self.config.price_tick_size or 0.0)
            if price_tick_size <= 0:
                price_tick_size = 1e-8
            price_epsilon = max(price_tick_size * 0.5, 1e-10)

            qty_step_decimal = (
                rules.get("qty_step")
                if isinstance(rules, dict) and rules.get("qty_step")
                else None
            )
            try:
                qty_step = float(qty_step_decimal) if qty_step_decimal is not None else 0.0
            except (TypeError, ValueError):
                qty_step = 0.0
            qty_epsilon = max((qty_step or 0.0) * 0.5, 1e-12)
            return price_epsilon, qty_epsilon

        def _has_equivalent_second_leg_order(
            trigger_price: float,
            qty: float,
        ) -> bool:
            """
            Guard against duplicate second-leg rebuilds for the same cycle
            based on already active orders.
            """
            if cycle_index <= 0 or not purpose or trigger_price <= 0 or qty <= 0:
                return False

            normalized_purpose = self._normalize_cycle_purpose(
                purpose,
                {
                    "cycle_index": cycle_index,
                    "cycle_role": self._get_second_leg_cycle_role(),
                },
            )

            price_epsilon, qty_epsilon = _resolve_second_leg_eps()

            def _iter_candidate_orders() -> Iterable[Any]:
                for order in runtime_state.active_orders.values():
                    yield order
                for order in snapshot.active_orders:
                    yield order

            for order in _iter_candidate_orders():
                order_purpose = getattr(order, "purpose", None)
                if not order_purpose:
                    continue
                normalized_order_purpose = self._normalize_cycle_purpose(order_purpose)
                if normalized_order_purpose != normalized_purpose:
                    continue
                status = str(getattr(order, "status", "") or "").upper()
                if status in {"FILLED", "CANCELED", "CANCELLED", "REJECTED", "EXPIRED"}:
                    continue
                remaining_qty = getattr(order, "remaining_qty", None)
                if remaining_qty is not None and float(remaining_qty or 0.0) <= 0:
                    continue
                order_trigger_price = getattr(order, "trigger_price", None)
                if order_trigger_price is None:
                    order_trigger_price = getattr(order, "price", None)
                if order_trigger_price is None:
                    continue
                order_qty = getattr(order, "qty", None)
                if order_qty is None:
                    continue
                try:
                    if abs(float(order_trigger_price) - float(trigger_price)) > price_epsilon:
                        continue
                    if abs(float(order_qty) - float(qty)) > qty_epsilon:
                        continue
                except (TypeError, ValueError):
                    continue
                return True
            return False

        def _equivalent_second_leg_followup_planned(
            normalized_purpose: str,
            trigger_price: float,
            qty: float,
        ) -> bool:
            """Check state-based followup signature for this cycle."""
            if cycle_index <= 0 or trigger_price <= 0 or qty <= 0:
                return False
            planned = state.get("planned_second_leg_followups") or {}
            entry = planned.get(str(cycle_index))
            if not isinstance(entry, dict):
                return False
            if str(entry.get("purpose") or "") != normalized_purpose:
                return False
            price_epsilon, qty_epsilon = _resolve_second_leg_eps()
            try:
                if abs(float(entry.get("trigger_price") or 0.0) - float(trigger_price)) > price_epsilon:
                    return False
                if abs(float(entry.get("qty") or 0.0) - float(qty)) > qty_epsilon:
                    return False
            except (TypeError, ValueError):
                return False
            return True

        def _record_second_leg_followup_planned(
            normalized_purpose: str,
            trigger_price: float,
            qty: float,
        ) -> None:
            if cycle_index <= 0 or trigger_price <= 0 or qty <= 0:
                return
            planned = state.setdefault("planned_second_leg_followups", {})
            planned[str(cycle_index)] = {
                "purpose": normalized_purpose,
                "trigger_price": float(trigger_price or 0.0),
                "qty": float(qty or 0.0),
            }

        def _dedupe_second_leg_intents(intents: list[StrategyIntent]) -> list[StrategyIntent]:
            """
            Collapse duplicate second-leg intents within a single builder pass.

            Only applies to the current second-leg purpose for this cycle; staging
            and split-intents with distinct trigger/qty combinations are preserved.
            """
            if not intents or cycle_index <= 0 or not purpose:
                return intents
            normalized_second_leg = self._normalize_cycle_purpose(
                self._get_second_leg_purpose(cycle_index),
                {"cycle_index": cycle_index, "cycle_role": self._get_second_leg_cycle_role()},
            )
            price_epsilon, qty_epsilon = _resolve_second_leg_eps()
            seen: list[tuple[float, float]] = []
            deduped: list[StrategyIntent] = []
            for intent in intents:
                intent_purpose = getattr(intent, "purpose", None)
                normalized_intent_purpose = self._normalize_cycle_purpose(intent_purpose)
                if normalized_intent_purpose != normalized_second_leg:
                    deduped.append(intent)
                    continue
                try:
                    tp = float(getattr(intent, "trigger_price", 0.0) or 0.0)
                    q = float(getattr(intent, "qty", 0.0) or 0.0)
                except (TypeError, ValueError):
                    deduped.append(intent)
                    continue
                duplicate = False
                for seen_tp, seen_q in seen:
                    if abs(tp - seen_tp) <= price_epsilon and abs(q - seen_q) <= qty_epsilon:
                        duplicate = True
                        break
                if duplicate:
                    _emit_short_tp_follow_up_skip(
                        "duplicate_second_leg_intent_collapsed_in_builder",
                        symbol=snapshot.symbol or self.config.symbol,
                        duplicate_purpose=normalized_intent_purpose,
                        duplicate_trigger_price=tp,
                        duplicate_qty=q,
                    )
                    continue
                seen.append((tp, q))
                deduped.append(intent)
            return deduped

        def _long_pending_should_block() -> bool:
            if not _has_pending_order(long_purpose):
                return False
            if self._has_cycle_purpose_already_filled_or_processed(
                runtime_state,
                long_purpose or "",
                {"cycle_index": cycle_index, "cycle_role": "long_reduce"},
            ):
                self._purge_filled_long_add_orders(
                    runtime_state, cycle_index, purge_stale=True
                )
                _log_event(
                    "fixed_cycle_short_followup_ignoring_stale_long_order",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "long_purpose": long_purpose,
                        "active_order_ids": list(runtime_state.active_orders.keys()),
                        "order_statuses": [
                            {
                                "client_order_id": getattr(order, "client_order_id", None),
                                "exchange_order_id": getattr(order, "exchange_order_id", None),
                                "status": getattr(order, "status", None),
                                "purpose": getattr(order, "purpose", None),
                            }
                            for order in runtime_state.active_orders.values()
                        ],
                        "processed_cycle_purposes": list(
                            state.get("processed_cycle_purposes") or []
                        ),
                        "reason": "long_purpose_already_processed",
                    },
                )
                return False
            return True

        if _long_pending_should_block():
            _emit_short_tp_follow_up_skip(
                "long_cycle_order_still_open",
                blocking_purpose=long_purpose,
            )
            context.audit.log_event(
                "fixed_cycle_downside_skip",
                strategy=self.name,
                skip_reason="long_cycle_order_still_open",
                cycle_number=cycle_index,
                purpose=purpose,
                blocking_purpose=long_purpose,
            )
            return []
        if _has_pending_order(purpose):
            _emit_short_tp_follow_up_skip(
                "short_tp_order_already_active",
                blocking_purpose=purpose,
            )
            return []

        if second_leg_is_long and self._get_first_leg_cycle_role() == "short_reduce":
            if state.get("recovery_required") or cycle_state.get("recovery_required"):
                recovery_payload = {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "recovery_activation_timing": state.get("recovery_activation_timing")
                    or cycle_state.get("recovery_activation_timing"),
                    "recovery_activation_reason": state.get("recovery_activation_reason")
                    or cycle_state.get("recovery_activation_reason"),
                    "recovery_reference_price": state.get("recovery_reference_price")
                    or cycle_state.get("recovery_reference_price"),
                }
                _log_event("fixed_cycle_recovery_required_normal_cycle_blocked", recovery_payload)
                _log_event(
                    "fixed_cycle_recovery_required_waiting_for_recovery_builder",
                    recovery_payload,
                )
                return []
            confirmed_short_reduce_pnl = self._safe_float(
                cycle_sequence_entry.get("long_add_confirmed_pnl"), None
            )
            pending_cycle_loss_usdt = float(state.get("pending_cycle_loss_usdt") or 0.0)
            if confirmed_short_reduce_pnl is None:
                _log_event(
                    "fixed_cycle_long_reduce_blocked_until_confirmed_pnl",
                    {
                        "cycle_index": cycle_index,
                        "purpose": purpose,
                        "first_leg_purpose": first_leg_purpose,
                        "pending_cycle_loss_usdt": pending_cycle_loss_usdt,
                        "reason": "confirmed_short_reduce_closed_pnl_missing",
                    },
                )
                _emit_short_tp_follow_up_skip(
                    "long_reduce_blocked_until_confirmed_pnl",
                    confirmed_short_reduce_pnl=confirmed_short_reduce_pnl,
                )
                return []

            initial_long_qty = float(state.get("initial_long_qty") or 0.0)
            current_long_qty = (
                float(snapshot.long_qty or 0.0)
                if float(snapshot.long_qty or 0.0) > 0
                else initial_long_qty
            )
            long_entry_price = float(snapshot.long_avg or state.get("long_avg") or 0.0)
            qty_cap_source = "_fixed_long_cycle_qty"
            long_reduce_qty = self._fixed_long_cycle_qty(
                initial_long_qty,
                current_long_qty,
                long_entry_price,
                runtime_state,
            )
            target_profit_usdt = float(self.config.target_profit_usdt or 0.0)
            fee_rate = 0.00055
            required_profit_to_cover_loss = max(
                pending_cycle_loss_usdt + target_profit_usdt,
                0.0,
            )
            confirmed_short_reduce_loss = max(-float(confirmed_short_reduce_pnl), 0.0)
            if (
                required_profit_to_cover_loss <= 0.0
                and confirmed_short_reduce_loss > 0.0
            ):
                required_profit_to_cover_loss = confirmed_short_reduce_loss + target_profit_usdt

            if long_reduce_qty <= 0 or long_entry_price <= 0 or fee_rate >= 1.0:
                _emit_short_tp_follow_up_skip(
                    "long_reduce_invalid_initial_inputs",
                    confirmed_short_reduce_pnl=confirmed_short_reduce_pnl,
                    long_reduce_qty=long_reduce_qty,
                    long_entry_price=long_entry_price,
                    fee_rate=fee_rate,
                )
                return []

            trigger_price = (
                (required_profit_to_cover_loss / long_reduce_qty)
                + (long_entry_price * (1.0 + fee_rate))
            ) / (1.0 - fee_rate)
            if trigger_price <= 0:
                _emit_short_tp_follow_up_skip(
                    "long_reduce_invalid_trigger_price",
                    long_reduce_qty=long_reduce_qty,
                    long_entry_price=long_entry_price,
                    trigger_price=trigger_price,
                )
                return []

            _, rules, _ = self._resolve_instrument_rules(runtime_state)
            instrument_tick_size = (
                float(rules["tick_size"]) if rules and rules.get("tick_size") else 0.0
            )
            price_tick_size = instrument_tick_size or float(self.config.price_tick_size or 0.0)
            if price_tick_size <= 0:
                price_tick_size = 0.01
            trigger_price = self._normalize_price(trigger_price, runtime_state)
            initial_trigger_price = trigger_price
            short_reduce_fill_price = self._safe_float(
                cycle_sequence_entry.get("short_reduce_fill_price"),
                None,
            )
            if short_reduce_fill_price is None or short_reduce_fill_price <= 0:
                short_reduce_fill_price = float(
                    cycle_state.get("last_confirmed_short_fill_price") or 0.0
                )

            def compute_expected_long_reduce_profit(tp: float, qty: float | None = None) -> float:
                effective_qty = long_reduce_qty if qty is None else qty
                return (
                    (tp - long_entry_price) * effective_qty
                    - (long_entry_price * effective_qty * fee_rate)
                    - (tp * effective_qty * fee_rate)
                )

            def _evaluate_post_short_reduce_recovery(trigger_price: float) -> bool:
                short_reduce_fill_price = self._safe_float(
                    cycle_sequence_entry.get("short_reduce_fill_price"),
                    None,
                )
                if short_reduce_fill_price is None or short_reduce_fill_price <= 0:
                    short_reduce_fill_price = float(
                        cycle_state.get("last_confirmed_short_fill_price") or 0.0
                    )
                post_distance_pct_from_last_fill = (
                    ((trigger_price - short_reduce_fill_price) / short_reduce_fill_price) * 100.0
                    if short_reduce_fill_price and short_reduce_fill_price > 0
                    else 0.0
                )
                if long_entry_price > 0:
                    post_distance_pct_from_long_avg = (
                        ((trigger_price - long_entry_price) / long_entry_price) * 100.0
                    )
                else:
                    post_distance_pct_from_long_avg = 0.0
                recovery_completed_cycle_index = int(
                    state.get("recovery_completed_cycle_index")
                    or cycle_state.get("recovery_completed_cycle_index")
                    or 0
                )
                normalized_next_required_purpose = self._normalize_cycle_purpose(
                    state.get("next_required_purpose") or ""
                )
                normalized_first_leg_purpose = self._normalize_cycle_purpose(
                    first_leg_purpose or "",
                    {
                        "cycle_index": cycle_index,
                        "cycle_role": self._get_first_leg_cycle_role(),
                    },
                )
                recovery_reactivation_skip = (
                    cycle_index > 0
                    and int(state.get("active_cycle_index") or 0) == cycle_index
                    and recovery_completed_cycle_index == cycle_index
                    and normalized_next_required_purpose == self._normalize_cycle_purpose(
                        purpose or "",
                        {
                            "cycle_index": cycle_index,
                            "cycle_role": self._get_second_leg_cycle_role(),
                        },
                    )
                    and normalized_first_leg_purpose in processed_purposes
                )
                confirmed_short_reduce_loss_for_state = max(
                    confirmed_short_reduce_loss,
                    pending_cycle_loss_usdt,
                )
                would_set_recovery_required = (
                    post_distance_pct_from_last_fill
                    > float(self.config.max_post_recovery_long_reduce_distance_pct or 0.0)
                )
                _log_event(
                    "fixed_cycle_post_short_reduce_projection",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "current_price": float(snapshot.current_price or 0.0),
                        "long_avg": long_entry_price,
                        "short_avg": float(snapshot.short_avg or 0.0),
                        "short_reduce_fill_price": short_reduce_fill_price,
                        "required_long_reduce_price": trigger_price,
                        "post_long_reduce_distance_pct_from_last_fill": post_distance_pct_from_last_fill,
                        "post_long_reduce_distance_pct_from_long_avg": post_distance_pct_from_long_avg,
                        "max_post_recovery_long_reduce_distance_pct": self.config.max_post_recovery_long_reduce_distance_pct,
                        "confirmed_short_reduce_loss": confirmed_short_reduce_loss,
                        "pending_cycle_loss_usdt": pending_cycle_loss_usdt,
                        "would_set_recovery_required": would_set_recovery_required,
                    },
                )
                if would_set_recovery_required and recovery_reactivation_skip:
                    _log_event(
                        "fixed_cycle_recovery_reactivation_skipped_after_completed_refill",
                        {
                            "symbol": snapshot.symbol or self.config.symbol,
                            "cycle_index": cycle_index,
                            "active_cycle_index": state.get("active_cycle_index"),
                            "next_required_purpose": state.get("next_required_purpose"),
                            "recovery_completed_cycle_index": recovery_completed_cycle_index,
                            "processed_cycle_purposes": list(
                                state.get("processed_cycle_purposes") or []
                            ),
                            "short_reduce_fill_price": short_reduce_fill_price,
                            "required_long_reduce_price": trigger_price,
                            "post_long_reduce_distance_pct_from_last_fill": post_distance_pct_from_last_fill,
                            "threshold_pct": self.config.max_post_recovery_long_reduce_distance_pct,
                        },
                    )
                    return False
                return False

            expected_long_reduce_profit = compute_expected_long_reduce_profit(trigger_price)
            iterations = 0
            while (
                expected_long_reduce_profit + 1e-9 < required_profit_to_cover_loss
                and iterations < 50
            ):
                trigger_price += price_tick_size
                trigger_price = math.ceil(trigger_price / price_tick_size) * price_tick_size
                trigger_price = self._normalize_price(trigger_price, runtime_state)
                expected_long_reduce_profit = compute_expected_long_reduce_profit(trigger_price)
                iterations += 1
                _log_event(
                    "fixed_cycle_recovery_activation_timing_selected",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "recovery_activation_timing": self.config.recovery_activation_timing,
                        "max_pre_recovery_long_reduce_distance_pct": self.config.max_pre_recovery_long_reduce_distance_pct,
                        "max_post_recovery_long_reduce_distance_pct": self.config.max_post_recovery_long_reduce_distance_pct,
                    },
                )
                short_reduce_fill_price = self._safe_float(
                    cycle_sequence_entry.get("short_reduce_fill_price"),
                    None,
                )
                if short_reduce_fill_price is None or short_reduce_fill_price <= 0:
                    short_reduce_fill_price = float(
                        cycle_state.get("last_confirmed_short_fill_price") or 0.0
                    )
                post_distance_pct_from_last_fill = (
                    ((trigger_price - short_reduce_fill_price) / short_reduce_fill_price) * 100.0
                    if short_reduce_fill_price and short_reduce_fill_price > 0
                    else 0.0
                )
                post_distance_pct_from_long_avg = (
                    ((trigger_price - long_entry_price) / long_entry_price) * 100.0
                    if long_entry_price > 0
                    else 0.0
                )
                recovery_completed_cycle_index = int(
                    state.get("recovery_completed_cycle_index")
                    or cycle_state.get("recovery_completed_cycle_index")
                    or 0
                )
                normalized_next_required_purpose = self._normalize_cycle_purpose(
                    state.get("next_required_purpose") or ""
                )
                normalized_first_leg_purpose = self._normalize_cycle_purpose(
                    first_leg_purpose or "",
                    {
                        "cycle_index": cycle_index,
                        "cycle_role": self._get_first_leg_cycle_role(),
                    },
                )
                recovery_reactivation_skip = (
                    cycle_index > 0
                    and int(state.get("active_cycle_index") or 0) == cycle_index
                    and recovery_completed_cycle_index == cycle_index
                    and normalized_next_required_purpose == self._normalize_cycle_purpose(
                        purpose or "",
                        {
                            "cycle_index": cycle_index,
                            "cycle_role": self._get_second_leg_cycle_role(),
                        },
                    )
                    and normalized_first_leg_purpose in processed_purposes
                )
                confirmed_short_reduce_loss_for_state = max(
                    confirmed_short_reduce_loss,
                    pending_cycle_loss_usdt,
                )
                would_set_recovery_required = (
                    post_distance_pct_from_last_fill
                    > float(self.config.max_post_recovery_long_reduce_distance_pct or 0.0)
                )
                _log_event(
                    "fixed_cycle_post_short_reduce_projection",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "current_price": float(snapshot.current_price or 0.0),
                        "long_avg": long_entry_price,
                        "short_avg": float(snapshot.short_avg or 0.0),
                        "short_reduce_fill_price": short_reduce_fill_price,
                        "required_long_reduce_price": trigger_price,
                        "post_long_reduce_distance_pct_from_last_fill": post_distance_pct_from_last_fill,
                        "post_long_reduce_distance_pct_from_long_avg": post_distance_pct_from_long_avg,
                        "max_post_recovery_long_reduce_distance_pct": self.config.max_post_recovery_long_reduce_distance_pct,
                        "confirmed_short_reduce_loss": confirmed_short_reduce_loss,
                        "pending_cycle_loss_usdt": pending_cycle_loss_usdt,
                        "would_set_recovery_required": would_set_recovery_required,
                    },
                )
                if _evaluate_post_short_reduce_recovery(trigger_price):
                    return []

            if _evaluate_post_short_reduce_recovery(trigger_price):
                return []

            trigger_price, long_reduce_qty, long_reduce_cover_adjustment = (
                self._enforce_long_reduce_loss_cover_invariant(
                    trigger_price=trigger_price,
                    long_qty=long_reduce_qty,
                    long_entry_price=long_entry_price,
                    required_net=required_profit_to_cover_loss,
                    fee_rate=fee_rate,
                    runtime_state=runtime_state,
                    snapshot=snapshot,
                    price_tick_size=price_tick_size,
                )
            )
            expected_long_reduce_profit = compute_expected_long_reduce_profit(
                trigger_price,
                long_reduce_qty,
            )
            if long_reduce_cover_adjustment.get("adjusted"):
                _log_event(
                    "fixed_cycle_long_reduce_loss_cover_invariant_adjusted",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "purpose": purpose,
                        **long_reduce_cover_adjustment,
                    },
                )

            _log_event(
                "fixed_cycle_long_reduce_sized_from_confirmed_loss",
                {
                    "cycle_index": cycle_index,
                    "purpose": purpose,
                    "confirmed_short_reduce_pnl": confirmed_short_reduce_pnl,
                    "pending_cycle_loss_usdt": pending_cycle_loss_usdt,
                    "required_profit_to_cover_loss": required_profit_to_cover_loss,
                    "expected_long_reduce_profit": expected_long_reduce_profit,
                    "long_reduce_qty": long_reduce_qty,
                    "qty_cap_source": qty_cap_source,
                    "reduction_pct_per_fill": self.config.reduction_pct_per_fill,
                    "long_entry_price": long_entry_price,
                    "trigger_price": trigger_price,
                    "trigger_price_adjusted_for_loss_cover": (
                        abs(trigger_price - initial_trigger_price) > 1e-12
                    ),
                },
            )

            # Loss-basierter Long-Reduce-Pfad: gemeinsames Metadata-Dict für Split- und Fallback-Intent.
            symbol_value = snapshot.symbol or self.config.symbol
            current_price = float(snapshot.current_price or 0.0)
            metadata_long_reduce = {
                "cycle_index": cycle_index,
                "cycle_role": self._get_second_leg_cycle_role(),
                "symbol": symbol_value,
                "source": "loss_based_second_leg_recovery",
                "parent_second_leg_purpose": purpose,
                "first_leg_cycle_role": self._get_first_leg_cycle_role(),
                "second_leg_cycle_role": self._get_second_leg_cycle_role(),
                "first_leg_fill_price": short_reduce_fill_price,
                "entry_price": long_entry_price,
                "entry_price_for_pnl": long_entry_price,
                "snapshot_price": current_price,
                "trigger_price": trigger_price,
                "trigger_direction": 1,
                "trigger_by": "LastPrice",
                "close_on_trigger": True,
                "position_idx": 1,
                "required_profit_to_cover_loss": required_profit_to_cover_loss,
                "pending_cycle_loss_usdt": pending_cycle_loss_usdt,
                "expected_long_reduce_profit": expected_long_reduce_profit,
                "qty": long_reduce_qty,
                "long_reduce_loss_cover_invariant_adjusted": bool(
                    long_reduce_cover_adjustment.get("adjusted")
                ),
                **(
                    {
                        key: long_reduce_cover_adjustment[key]
                        for key in (
                            "original_long_qty",
                            "adjusted_long_qty",
                            "original_trigger_price",
                            "adjusted_trigger_price",
                            "expected_net_after_adjustment",
                            "reason",
                        )
                        if key in long_reduce_cover_adjustment
                    }
                    if long_reduce_cover_adjustment.get("adjusted")
                    else {}
                ),
            }

            gate_allowed, gate_reason, gate_payload = self._can_submit_cycle_intent(
                runtime_state,
                snapshot,
                purpose=purpose,
                cycle_index=cycle_index,
                cycle_role=self._get_second_leg_cycle_role(),
            )
            gate_payload = {
                **gate_payload,
                "symbol": snapshot.symbol or self.config.symbol,
                "required_profit_to_cover_loss": required_profit_to_cover_loss,
                "expected_long_reduce_profit": expected_long_reduce_profit,
            }
            if not gate_allowed:
                gate_payload["reason"] = gate_reason or "long_reduce_followup_not_ready"
                gate_payload["expected_next_action"] = (
                    gate_payload.get("expected_next_action") or "build_long_reduce_followup"
                )
                _log_event("fixed_cycle_state_gate_intent_blocked", gate_payload)
                return []
            gate_payload["reason"] = "long_reduce_followup_allowed"
            _log_event("fixed_cycle_state_gate_intent_allowed", gate_payload)
            normalized_second_leg_purpose = self._normalize_cycle_purpose(
                purpose,
                {
                    "cycle_index": cycle_index,
                    "cycle_role": self._get_second_leg_cycle_role(),
                },
            )
            if _equivalent_second_leg_followup_planned(
                normalized_second_leg_purpose,
                trigger_price,
                long_reduce_qty,
            ):
                _emit_short_tp_follow_up_skip(
                    "equivalent_second_leg_followup_already_planned",
                    blocking_purpose=purpose,
                    blocking_trigger_price=trigger_price,
                    blocking_qty=long_reduce_qty,
                )
                return []
            if _has_equivalent_second_leg_order(trigger_price, long_reduce_qty):
                _emit_short_tp_follow_up_skip(
                    "equivalent_second_leg_order_already_active",
                    blocking_purpose=purpose,
                    blocking_trigger_price=trigger_price,
                    blocking_qty=long_reduce_qty,
                )
                return []
            self._reserve_cycle_intent_slot(
                runtime_state,
                cycle_index=cycle_index,
                field_name=self._get_second_leg_status_field(),
                normalized_purpose=normalized_second_leg_purpose,
                qty=long_reduce_qty,
                trigger_price=trigger_price,
            )
            _record_second_leg_followup_planned(
                normalized_second_leg_purpose,
                trigger_price,
                long_reduce_qty,
            )
            use_loss_based_staging_plan = bool(
                metadata_long_reduce.get("source") == "loss_based_second_leg_recovery"
                and (
                    required_profit_to_cover_loss > 0.0
                    or pending_cycle_loss_usdt > 0.0
                    or confirmed_short_reduce_loss > 0.0
                )
            )
            if not use_loss_based_staging_plan:
                split_intents = self._maybe_build_normal_cycle_second_leg_split_intents(
                    cycle_index=cycle_index,
                    purpose=purpose,
                    qty=long_reduce_qty,
                    trigger_price=trigger_price,
                    snapshot=snapshot,
                    runtime_state=runtime_state,
                    side="long",
                    position_idx=1,
                    trigger_direction=1,
                    metadata=metadata_long_reduce,
                )
                if split_intents:
                    return split_intents

            # Richtung-neutrale Staging-Entscheidung für Long-Second-Leg (Mirror-Short-Bot)
            first_leg_fill_price = self._get_first_leg_fill_price(runtime_state, cycle_index)
            if first_leg_fill_price <= 0:
                first_leg_fill_price = float(cycle_state.get("last_cycle_reference_price") or 0.0)
            if first_leg_fill_price > 0 and trigger_price > 0:
                distance_pct_signed = (
                    (trigger_price - first_leg_fill_price) / first_leg_fill_price
                ) * 100.0
                distance_pct_abs = abs(distance_pct_signed)
            else:
                distance_pct_abs = 0.0
            post_first_leg_recovery_distance_pct = float(
                self.config.max_post_recovery_long_reduce_distance_pct or 0.0
            )
            stage_count = 1
            if post_first_leg_recovery_distance_pct > 0 and distance_pct_abs > 0:
                stage_count = 3

            # Staging für Long-Second-Leg: 1–3 Teil-TPs, direction-neutral mit Min-Notional-Validierung.
            if first_leg_fill_price <= 0 or trigger_price <= 0:
                _emit_short_tp_follow_up_skip(
                    "staged_second_leg_tp_invalid_inputs",
                    symbol=snapshot.symbol or self.config.symbol,
                    long_fill_price=long_entry_price,
                    short_qty=long_reduce_qty,
                    trigger_price=trigger_price,
                    first_leg_fill_price=first_leg_fill_price,
                )
                return []

            symbol, rules, _ = self._resolve_instrument_rules(runtime_state)
            min_order_qty = float(
                rules["min_order_qty"]
                if rules and rules.get("min_order_qty")
                else float(self.config.min_order_qty or 0.0)
            )
            min_notional = float(
                rules["min_notional"]
                if rules and rules.get("min_notional")
                else float(self.config.min_notional_usdt or 0.0)
            )

            best_plan: list[dict[str, Any]] = []
            best_stage_count = 0

            def _build_even_stage_qtys(candidate_stage_count: int) -> list[float]:
                if candidate_stage_count <= 0:
                    return []
                normalized_total_qty = self._normalize_qty(long_reduce_qty, runtime_state)
                if normalized_total_qty <= 0:
                    return []
                if candidate_stage_count == 1:
                    return [normalized_total_qty]
                remaining_qty = normalized_total_qty
                candidate_qtys: list[float] = []
                desired_stage_qty = normalized_total_qty / float(candidate_stage_count)
                for idx in range(candidate_stage_count):
                    if idx == candidate_stage_count - 1:
                        stage_qty = remaining_qty
                    else:
                        stage_qty = self._normalize_qty(desired_stage_qty, runtime_state)
                    if stage_qty <= 0 or stage_qty > remaining_qty + 1e-12:
                        return []
                    candidate_qtys.append(stage_qty)
                    remaining_qty = max(remaining_qty - stage_qty, 0.0)
                if remaining_qty > 1e-12:
                    return []
                return candidate_qtys

            def _build_distinct_stage_prices(candidate_stage_count: int) -> list[float]:
                if candidate_stage_count <= 0:
                    return []
                if candidate_stage_count == 1:
                    normalized_final_price = self._normalize_price(trigger_price, runtime_state)
                    return [normalized_final_price] if normalized_final_price > 0 else []
                direction = 1.0 if trigger_price >= first_leg_fill_price else -1.0
                tick = price_tick_size if price_tick_size > 0 else 0.0
                if tick <= 0:
                    return []
                delta = trigger_price - first_leg_fill_price
                adjusted_prices: list[float] = []
                for idx in range(candidate_stage_count):
                    ratio = float(idx + 1) / float(candidate_stage_count)
                    stage_trigger_price_raw = first_leg_fill_price + ratio * delta
                    stage_trigger_price = self._normalize_price(
                        stage_trigger_price_raw, runtime_state
                    )
                    if stage_trigger_price <= 0:
                        return []
                    if adjusted_prices:
                        previous_price = adjusted_prices[-1]
                        attempts = 0
                        while (
                            (direction > 0 and stage_trigger_price <= previous_price + 1e-12)
                            or (direction < 0 and stage_trigger_price >= previous_price - 1e-12)
                        ) and attempts < 50:
                            stage_trigger_price = self._normalize_price(
                                previous_price + direction * tick * float(attempts + 1),
                                runtime_state,
                            )
                            attempts += 1
                        if (
                            (direction > 0 and stage_trigger_price <= previous_price + 1e-12)
                            or (direction < 0 and stage_trigger_price >= previous_price - 1e-12)
                        ):
                            return []
                    adjusted_prices.append(stage_trigger_price)
                normalized_final_price = self._normalize_price(trigger_price, runtime_state)
                if not adjusted_prices or normalized_final_price <= 0:
                    return []
                if direction > 0 and adjusted_prices[-1] < normalized_final_price:
                    adjusted_prices[-1] = normalized_final_price
                elif direction < 0 and adjusted_prices[-1] > normalized_final_price:
                    adjusted_prices[-1] = normalized_final_price
                return adjusted_prices

            def _build_plan(candidate_stage_count: int) -> list[dict[str, Any]]:
                nonlocal trigger_price, first_leg_fill_price
                if candidate_stage_count <= 0:
                    return []
                stage_qtys = _build_even_stage_qtys(candidate_stage_count)
                stage_prices = _build_distinct_stage_prices(candidate_stage_count)
                if not stage_qtys or not stage_prices or len(stage_qtys) != len(stage_prices):
                    return []

                direction = 1.0 if trigger_price >= first_leg_fill_price else -1.0
                tick = price_tick_size if price_tick_size > 0 else 0.0
                if tick <= 0:
                    return []
                normalized_final_trigger_price = self._normalize_price(trigger_price, runtime_state)
                if normalized_final_trigger_price <= 0:
                    return []
                max_allowed_stage_price: float | None = (
                    self._normalize_price(
                        normalized_final_trigger_price + direction * tick,
                        runtime_state,
                    )
                    if candidate_stage_count > 1
                    else normalized_final_trigger_price
                )
                if post_first_leg_recovery_distance_pct > 0 and first_leg_fill_price > 0:
                    gate_distance_cap: float | None = None
                    if direction > 0:
                        gate_distance_cap = self._normalize_price(
                            first_leg_fill_price
                            * (1.0 + (post_first_leg_recovery_distance_pct / 100.0)),
                            runtime_state,
                        )
                    else:
                        gate_distance_cap = self._normalize_price(
                            first_leg_fill_price
                            * (1.0 - (post_first_leg_recovery_distance_pct / 100.0)),
                            runtime_state,
                        )
                    if gate_distance_cap and gate_distance_cap > 0:
                        if direction > 0:
                            max_allowed_stage_price = min(
                                float(max_allowed_stage_price or gate_distance_cap),
                                gate_distance_cap,
                            )
                        else:
                            max_allowed_stage_price = max(
                                float(max_allowed_stage_price or gate_distance_cap),
                                gate_distance_cap,
                            )

                def _build_stages_from_prices(prices: list[float]) -> list[dict[str, Any]]:
                    built_stages: list[dict[str, Any]] = []
                    for idx, (stage_qty, stage_trigger_price) in enumerate(
                        zip(stage_qtys, prices)
                    ):
                        if stage_qty <= 0 or stage_trigger_price <= 0:
                            return []
                        built_stages.append(
                            {
                                "index": idx,
                                "trigger_price": stage_trigger_price,
                                "qty": stage_qty,
                                "expected_net": compute_expected_long_reduce_profit(
                                    stage_trigger_price, stage_qty
                                ),
                            }
                        )
                    return built_stages

                stages = _build_stages_from_prices(stage_prices)
                if not stages:
                    return []

                total_expected_net = sum(
                    float(stage.get("expected_net") or 0.0) for stage in stages
                )
                adjust_iterations = 0
                last_stage_price_adjusted = False
                while (
                    total_expected_net + 1e-8 < required_profit_to_cover_loss
                    and adjust_iterations < 200
                ):
                    previous_price = stage_prices[-2] if len(stage_prices) > 1 else 0.0
                    next_stage_price = self._normalize_price(
                        stage_prices[-1] + direction * tick, runtime_state
                    )
                    if len(stage_prices) > 1 and (
                        (direction > 0 and next_stage_price <= previous_price + 1e-12)
                        or (direction < 0 and next_stage_price >= previous_price - 1e-12)
                    ):
                        next_stage_price = self._normalize_price(
                            previous_price + direction * tick, runtime_state
                        )
                    if (
                        max_allowed_stage_price is not None
                        and (
                            (direction > 0 and next_stage_price > max_allowed_stage_price + 1e-12)
                            or (
                                direction < 0
                                and next_stage_price < max_allowed_stage_price - 1e-12
                            )
                        )
                    ):
                        _log_event(
                            "loss_based_second_leg_staging_plan_rejected_price_cap",
                            {
                                "symbol": snapshot.symbol or self.config.symbol,
                                "purpose": purpose,
                                "cycle_index": cycle_index,
                                "stage_count": candidate_stage_count,
                                "first_leg_fill_price": first_leg_fill_price,
                                "final_required_trigger_price": normalized_final_trigger_price,
                                "attempted_last_stage_price": next_stage_price,
                                "max_allowed_stage_price": max_allowed_stage_price,
                                "required_profit_to_cover_loss": required_profit_to_cover_loss,
                                "total_expected_net": total_expected_net,
                                "reason": "required_profit_not_reachable_within_price_cap",
                            },
                        )
                        return []
                    if abs(next_stage_price - stage_prices[-1]) <= 1e-12:
                        _log_event(
                            "loss_based_second_leg_staging_plan_rejected_price_cap",
                            {
                                "symbol": snapshot.symbol or self.config.symbol,
                                "purpose": purpose,
                                "cycle_index": cycle_index,
                                "stage_count": candidate_stage_count,
                                "first_leg_fill_price": first_leg_fill_price,
                                "final_required_trigger_price": normalized_final_trigger_price,
                                "attempted_last_stage_price": stage_prices[-1],
                                "max_allowed_stage_price": max_allowed_stage_price,
                                "required_profit_to_cover_loss": required_profit_to_cover_loss,
                                "total_expected_net": total_expected_net,
                                "reason": "last_stage_price_no_longer_adjustable",
                            },
                        )
                        return []
                    stage_prices[-1] = next_stage_price
                    last_stage_price_adjusted = True
                    stages = _build_stages_from_prices(stage_prices)
                    if not stages:
                        return []
                    total_expected_net = sum(
                        float(stage.get("expected_net") or 0.0) for stage in stages
                    )
                    adjust_iterations += 1
                if last_stage_price_adjusted:
                    _log_event(
                        "loss_based_second_leg_staging_price_cap_applied",
                        {
                            "symbol": snapshot.symbol or self.config.symbol,
                            "purpose": purpose,
                            "cycle_index": cycle_index,
                            "stage_count": candidate_stage_count,
                            "first_leg_fill_price": first_leg_fill_price,
                            "final_required_trigger_price": normalized_final_trigger_price,
                            "attempted_last_stage_price": stage_prices[-1],
                            "max_allowed_stage_price": max_allowed_stage_price,
                            "required_profit_to_cover_loss": required_profit_to_cover_loss,
                            "total_expected_net": total_expected_net,
                            "reason": "last_stage_adjusted_within_price_cap",
                        },
                    )
                return stages

            # Kandidaten-Pläne mit fallender Stage-Anzahl prüfen.
            for candidate_stage_count in range(stage_count, 0, -1):
                stages = _build_plan(candidate_stage_count)
                if not stages:
                    _log_event(
                        "staged_second_leg_tp_candidate_rejected_min_notional",
                        {
                            "symbol": snapshot.symbol or self.config.symbol,
                            "cycle_index": cycle_index,
                            "candidate_stage_count": candidate_stage_count,
                            "reason": "empty_plan",
                        },
                    )
                    continue

                # Min-Notional- und Profit-Validierung.
                valid = True
                sum_expected_net = 0.0
                rejected_stages: list[int] = []
                for stage in stages:
                    idx = int(stage.get("index") or 0)
                    stage_trigger_price = float(stage.get("trigger_price") or 0.0)
                    stage_qty = float(stage.get("qty") or 0.0)
                    stage_net = float(stage.get("expected_net") or 0.0)
                    if stage_qty <= 0 or stage_trigger_price <= 0:
                        valid = False
                        rejected_stages.append(idx)
                        continue
                    stage_notional = stage_qty * stage_trigger_price
                    if (min_order_qty > 0 and stage_qty < min_order_qty) or (
                        min_notional > 0 and stage_notional < min_notional
                    ):
                        valid = False
                        rejected_stages.append(idx)
                        continue
                    sum_expected_net += stage_net

                if not valid or sum_expected_net + 1e-8 < required_profit_to_cover_loss:
                    event_name = (
                        "staged_second_leg_tp_candidate_rejected_min_notional"
                        if rejected_stages
                        else "staged_second_leg_tp_candidate_rejected_insufficient_profit"
                    )
                    _log_event(
                        event_name,
                        {
                            "symbol": snapshot.symbol or self.config.symbol,
                            "cycle_index": cycle_index,
                            "candidate_stage_count": candidate_stage_count,
                            "rejected_stages": rejected_stages,
                            "sum_expected_net": sum_expected_net,
                            "required_profit_to_cover_loss": required_profit_to_cover_loss,
                            "min_order_qty": min_order_qty,
                            "min_notional": min_notional,
                            "stages": stages,
                        },
                    )
                    continue

                best_plan = stages
                best_stage_count = len(stages)
                if best_stage_count < stage_count:
                    _log_event(
                        "staged_second_leg_tp_stage_count_reduced",
                        {
                            "symbol": snapshot.symbol or self.config.symbol,
                            "cycle_index": cycle_index,
                            "original_stage_count": stage_count,
                            "final_stage_count": best_stage_count,
                        },
                    )
                break

            if not best_plan:
                _log_event(
                    "staged_second_leg_tp_no_valid_min_notional_stage",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "required_profit_to_cover_loss": required_profit_to_cover_loss,
                        "long_reduce_qty": long_reduce_qty,
                        "min_order_qty": min_order_qty,
                        "min_notional": min_notional,
                    },
                )
                _emit_short_tp_follow_up_skip(
                    "staged_second_leg_tp_no_valid_min_notional_stage",
                    symbol=snapshot.symbol or self.config.symbol,
                    long_fill_price=long_entry_price,
                    short_qty=long_reduce_qty,
                    trigger_price=trigger_price,
                )
                return []

            # Gesamt-required_net und Stage-Count für Exit-Pricing pro Cycle merken
            cycle_key = str(cycle_index)
            required_map = state.setdefault("staged_second_leg_tp_required_net_total", {})
            required_map[cycle_key] = required_profit_to_cover_loss
            stage_count_map = state.setdefault("staged_second_leg_tp_stage_count", {})
            stage_count_map[cycle_key] = best_stage_count
            # Reset Realized/Filled-Maps für diesen Cycle
            realized_map = state.setdefault("staged_second_leg_tp_realized_net", {})
            realized_map[cycle_key] = 0.0
            filled_map = state.setdefault("staged_second_leg_tp_filled_stages", {})
            filled_map[cycle_key] = []

            sum_expected_net = sum(float(stage.get("expected_net") or 0.0) for stage in best_plan)

            _log_event(
                "loss_based_second_leg_staging_plan_selected",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "purpose": purpose,
                    "cycle_index": cycle_index,
                    "stage_count": best_stage_count,
                    "stage_prices": [
                        float(stage.get("trigger_price") or 0.0) for stage in best_plan
                    ],
                    "stage_qtys": [float(stage.get("qty") or 0.0) for stage in best_plan],
                    "expected_stage_net": [
                        float(stage.get("expected_net") or 0.0) for stage in best_plan
                    ],
                    "total_expected_net": sum_expected_net,
                    "required_profit_to_cover_loss": required_profit_to_cover_loss,
                    "first_leg_fill_price": first_leg_fill_price,
                    "trigger_price": trigger_price,
                    "entry_price_for_pnl": long_entry_price,
                },
            )

            logger.info(
                "staged_second_leg_tp_final_plan_selected",
                extra={
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "stage_count": best_stage_count,
                    "distance_pct_abs": distance_pct_abs,
                    "threshold_pct": post_first_leg_recovery_distance_pct,
                    "required_net_profit": required_profit_to_cover_loss,
                     "sum_expected_net": sum_expected_net,
                    "first_leg_fill_price": first_leg_fill_price,
                    "final_second_leg_trigger_price": trigger_price,
                    "stages": [
                        {
                            "stage_index": int(stage.get("index") or 0),
                            "qty": float(stage.get("qty") or 0.0),
                            "trigger_price": float(stage.get("trigger_price") or 0.0),
                            "expected_net": float(stage.get("expected_net") or 0.0),
                            "notional": float(stage.get("qty") or 0.0)
                            * float(stage.get("trigger_price") or 0.0),
                        }
                        for stage in best_plan
                    ],
                },
            )

            intents: list[StrategyIntent] = []
            first_leg_cycle_role = self._get_first_leg_cycle_role()
            second_leg_cycle_role = self._get_second_leg_cycle_role()
            for new_index, stage in enumerate(best_plan):
                stage_trigger_price = float(stage.get("trigger_price") or 0.0)
                stage_qty = float(stage.get("qty") or 0.0)
                stage_expected_net = float(stage.get("expected_net") or 0.0)
                if stage_qty <= 0 or stage_trigger_price <= 0:
                    continue
                stage_metadata = {
                    "cycle_index": cycle_index,
                    "cycle_role": second_leg_cycle_role,
                    "symbol": snapshot.symbol or self.config.symbol,
                    "is_staged_second_leg_tp": True,
                    "stage_index": new_index,
                    "stage_count": best_stage_count,
                    "stage_expected_net": stage_expected_net,
                    "stage_required_net_total": required_profit_to_cover_loss,
                    "stage_trigger_price": stage_trigger_price,
                    "first_leg_fill_price": first_leg_fill_price,
                    "final_second_leg_trigger_price": trigger_price,
                    "distance_pct_abs": distance_pct_abs,
                    "threshold_pct": post_first_leg_recovery_distance_pct,
                    "first_leg_cycle_role": first_leg_cycle_role,
                    "second_leg_cycle_role": second_leg_cycle_role,
                    "parent_second_leg_purpose": purpose,
                }
                intent = StrategyIntent(
                    side="long",
                    qty=stage_qty,
                    purpose=purpose,
                    order_type="Market",
                    reduce_only=True,
                    trigger_price=stage_trigger_price,
                    trigger_direction=1,
                    trigger_by="LastPrice",
                    close_on_trigger=True,
                    position_idx=1,
                    metadata=stage_metadata,
                )
                intents.append(intent)
            if not intents:
                _emit_short_tp_follow_up_skip(
                    "staged_second_leg_tp_intents_empty",
                    symbol=snapshot.symbol or self.config.symbol,
                    long_fill_price=long_entry_price,
                    short_qty=long_reduce_qty,
                    trigger_price=trigger_price,
                )
                return []
            _log_event(
                "staged_second_leg_tp_intents_created",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "purpose": purpose,
                    "stage_count": len(intents),
                    "stages": [
                        {
                            "stage_index": st.metadata.get("stage_index") if hasattr(st, "metadata") else None,
                            "qty": getattr(st, "qty", None),
                            "trigger_price": getattr(st, "trigger_price", None),
                        }
                        for st in intents
                    ],
                },
            )
            return intents

        long_fill = (cycle_state.get("long_fills") or {}).get(str(cycle_index)) or {}
        self._seed_long_fill_closed_pnl_fields(
            long_fill,
            long_fill.get("order_id") or long_fill.get("exchange_order_id"),
        )
        active_trade_symbol = self._active_trade_symbol(snapshot, runtime_state, payload=long_fill)
        long_fill_price = float(long_fill.get("price") or 0.0)
        original_long_fill_price = long_fill_price
        fallback_source = None
        if long_fill_price <= 0:
            for key in (
                "confirmed_closed_avg_price",
                "closed_avg_price",
                "exec_price",
                "entry_price_for_pnl",
                "fill_price",
                "trigger_price",
            ):
                candidate = self._safe_float(long_fill.get(key), None)
                if candidate and candidate > 0:
                    long_fill_price = candidate
                    fallback_source = key
                    break
        fallback_used = False
        if long_fill_price <= 0:
            snapshot_price = float(snapshot.current_price or 0.0)
            if snapshot_price > 0:
                long_fill_price = snapshot_price
                fallback_source = "snapshot.current_price"
                fallback_used = True
        if fallback_used:
            _log_event(
                "fixed_cycle_short_followup_long_fill_price_fallback_used",
                {
                    "cycle_index": cycle_index,
                    "original_long_fill_price": original_long_fill_price,
                    "fallback_source": fallback_source,
                    "fallback_price": long_fill_price,
                    "long_fill_keys": sorted(long_fill.keys()),
                },
            )
        if long_fill_price <= 0:
            _emit_short_tp_follow_up_skip(
                "missing_long_fill_price_for_short_tp",
                symbol=active_trade_symbol or snapshot.symbol or self.config.symbol,
                long_fill_price=long_fill_price,
            )
            context.audit.log_event(
                "fixed_cycle_downside_skip",
                strategy=self.name,
                skip_reason="missing_long_fill_price_for_short_tp",
                cycle_number=cycle_index,
                purpose=purpose,
            )
            return []

        closed_pnl_ready = bool(long_fill.get("closed_pnl_ready"))
        if not closed_pnl_ready:
            closed_pnl_ready = self._refresh_long_fill_closed_pnl(
                cycle_index=cycle_index,
                long_fill=long_fill,
                runtime_state=runtime_state,
                context=context,
            )
            self._write_cycle_state(cycle_state)
            if not closed_pnl_ready:
                pending_meta = {
                    "order_id": long_fill.get("order_id"),
                    "cycle_index": cycle_index,
                    "symbol": active_trade_symbol,
                    "closed_pnl": long_fill.get("closed_pnl"),
                    "closed_qty": long_fill.get("closed_qty"),
                    "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
                }
                logger.info(
                    "fixed_cycle_long_closed_pnl_pending_but_short_followup_allowed %s",
                    pending_meta,
                )
                context.audit.log_event(
                    "fixed_cycle_long_closed_pnl_pending_but_short_followup_allowed",
                    strategy=self.name,
                    cycle_number=cycle_index,
                    purpose=purpose,
                    order_id=long_fill.get("order_id"),
                    pending_cycle_loss_usdt=float(state.get("pending_cycle_loss_usdt") or 0.0),
                )
        config_symbol = str(self.config.symbol or "").upper()
        snapshot_symbol = str(snapshot.symbol or "").upper()
        if active_trade_symbol and config_symbol and active_trade_symbol != config_symbol:
            _emit_short_tp_follow_up_skip(
                "symbol_mismatch_order_blocked",
                symbol=active_trade_symbol,
                config_symbol=config_symbol,
                snapshot_symbol=snapshot_symbol,
                fill_symbol=str(long_fill.get("symbol") or "").upper(),
                exchange_order_id=long_fill.get("order_id"),
                client_order_id=long_fill.get("client_order_id"),
            )
            _log_warning_event(
                "fixed_cycle_symbol_mismatch_order_blocked",
                {
                    "config_symbol": config_symbol,
                    "fill_symbol": str(long_fill.get("symbol") or "").upper(),
                    "snapshot_symbol": snapshot_symbol,
                    "active_trade_symbol": active_trade_symbol,
                    "purpose": purpose,
                    "exchange_order_id": long_fill.get("order_id"),
                    "client_order_id": long_fill.get("client_order_id"),
                    "cycle_index": cycle_index,
                },
            )
            return []
        state["block_exit_rebuild_until_pnl_ready"] = False

        reduction_multiplier = 1.0
        effective_reduction_pct = self.config.reduction_pct_per_fill * reduction_multiplier
        short_qty = self._fixed_short_cycle_qty(
            float(state.get("initial_short_qty") or 0.0),
            snapshot.short_qty,
            long_fill_price,
            reduction_multiplier=reduction_multiplier,
            runtime_state=runtime_state,
        )
        long_reduce_qty = 0.0
        long_reduce_qty_source = "missing"
        for qty_source, qty_value in (
            ("incremental_qty", self._safe_float(long_fill.get("incremental_qty"), None)),
            ("exec_qty", self._safe_float(long_fill.get("exec_qty"), None)),
            ("cumulative_qty", self._safe_float(long_fill.get("cumulative_qty"), None)),
            ("runtime_filled_qty", self._safe_float(long_fill.get("runtime_filled_qty"), None)),
            ("total_qty", self._safe_float(long_fill.get("total_qty"), None)),
            ("qty", self._safe_float(long_fill.get("qty"), None)),
            ("confirmed_closed_qty", self._safe_float(long_fill.get("confirmed_closed_qty"), None)),
            ("closed_qty", self._safe_float(long_fill.get("closed_qty"), None)),
        ):
            if qty_value is not None and qty_value > 0:
                long_reduce_qty = float(qty_value)
                long_reduce_qty_source = qty_source
                break
        _log_event(
            "fixed_cycle_short_followup_qty_source",
            {
                "cycle_index": cycle_index,
                "purpose": purpose,
                "long_reduce_qty_source": long_reduce_qty_source,
                "long_fill_qty": long_fill.get("qty"),
                "long_fill_total_qty": long_fill.get("total_qty"),
                "long_fill_incremental_qty": long_fill.get("incremental_qty"),
                "long_fill_exec_qty": long_fill.get("exec_qty"),
                "long_fill_cumulative_qty": long_fill.get("cumulative_qty"),
                "long_fill_runtime_filled_qty": long_fill.get("runtime_filled_qty"),
            },
        )
        confirmed_closed_qty = self._safe_float(long_fill.get("closed_qty"), None)
        confirmed_closed_avg_price = self._safe_float(long_fill.get("closed_avg_price"), None)
        confirmed_closed_cost = self._safe_float(long_fill.get("closed_cost"), None)
        provisional_exec_pnl_total = self._safe_float(
            long_fill.get("provisional_exec_pnl_total"), None
        )
        provisional_runtime_pnl_total = self._safe_float(
            long_fill.get("provisional_runtime_pnl_total"), None
        )
        runtime_calculated_pnl = self._safe_float(long_fill.get("runtime_calculated_pnl"), None)
        exec_pnl = self._safe_float(long_fill.get("exec_pnl"), None)
        long_fill_confirmed_closed_pnl = self._safe_float(
            long_fill.get("confirmed_closed_pnl"), None
        )
        long_fill_closed_pnl = self._safe_float(long_fill.get("closed_pnl"), None)
        confirmed_closed_pnl = long_fill_confirmed_closed_pnl or long_fill_closed_pnl
        cycle_entry_long_add_confirmed_pnl = self._safe_float(
            cycle_sequence_entry.get("long_add_confirmed_pnl"), None
        )
        cycle_entry_long_reduce_closed_pnl = self._safe_float(
            cycle_sequence_entry.get("long_reduce_closed_pnl"), None
        )
        cycle_entry_long_add_loss_usdt = self._safe_float(
            cycle_sequence_entry.get("long_add_loss_usdt"), None
        )
        long_fill_metadata: dict[str, Any] = {}
        if isinstance(long_fill, dict):
            long_fill_metadata = dict(long_fill.get("metadata") or {})
        short_followup_pnl = None
        short_followup_pnl_source = None
        if cycle_entry_long_add_confirmed_pnl is not None:
            short_followup_pnl = cycle_entry_long_add_confirmed_pnl
            short_followup_pnl_source = "cycle_entry_long_add_confirmed_pnl"
        elif cycle_entry_long_reduce_closed_pnl is not None:
            short_followup_pnl = cycle_entry_long_reduce_closed_pnl
            short_followup_pnl_source = "cycle_entry_long_reduce_closed_pnl"
        elif long_fill_confirmed_closed_pnl is not None:
            short_followup_pnl = long_fill_confirmed_closed_pnl
            short_followup_pnl_source = "long_fill_confirmed_closed_pnl"
        elif long_fill_closed_pnl is not None:
            short_followup_pnl = long_fill_closed_pnl
            short_followup_pnl_source = "long_fill_closed_pnl"
        elif long_fill.get("long_reduce_closed_pnl") is not None:
            short_followup_pnl = self._safe_float(long_fill.get("long_reduce_closed_pnl"), None)
            short_followup_pnl_source = "long_fill_long_reduce_closed_pnl"
        elif long_fill_metadata.get("confirmed_closed_pnl") is not None:
            short_followup_pnl = long_fill_metadata.get("confirmed_closed_pnl")
            short_followup_pnl_source = "long_fill_metadata_confirmed_closed_pnl"
        elif long_fill_metadata.get("long_reduce_closed_pnl") is not None:
            short_followup_pnl = long_fill_metadata.get("long_reduce_closed_pnl")
            short_followup_pnl_source = "long_fill_metadata_long_reduce_closed_pnl"
        elif long_fill_metadata.get("closed_pnl") is not None:
            short_followup_pnl = long_fill_metadata.get("closed_pnl")
            short_followup_pnl_source = "long_fill_metadata_closed_pnl"
        elif self._safe_float(long_fill.get("pnl_this_fill"), None) is not None:
            short_followup_pnl = self._safe_float(long_fill.get("pnl_this_fill"), None)
            short_followup_pnl_source = "long_fill_pnl_this_fill"
        elif long_fill_metadata.get("runtime_calculated_pnl") is not None:
            short_followup_pnl = long_fill_metadata.get("runtime_calculated_pnl")
            short_followup_pnl_source = "long_fill_metadata_runtime_calculated_pnl"
        elif long_fill_metadata.get("exec_pnl") is not None:
            short_followup_pnl = long_fill_metadata.get("exec_pnl")
            short_followup_pnl_source = "long_fill_metadata_exec_pnl"
        elif provisional_exec_pnl_total is not None:
            short_followup_pnl = provisional_exec_pnl_total
            short_followup_pnl_source = "provisional_exec_pnl_total"
        elif provisional_runtime_pnl_total is not None:
            short_followup_pnl = provisional_runtime_pnl_total
            short_followup_pnl_source = "provisional_runtime_pnl_total"
        elif runtime_calculated_pnl is not None:
            short_followup_pnl = runtime_calculated_pnl
            short_followup_pnl_source = "long_fill_runtime_calculated_pnl"
        elif exec_pnl is not None:
            short_followup_pnl = exec_pnl
            short_followup_pnl_source = "long_fill_exec_pnl"
        elif cycle_entry_long_add_loss_usdt is not None:
            short_followup_pnl = -abs(cycle_entry_long_add_loss_usdt)
            short_followup_pnl_source = "cycle_entry_long_add_loss_usdt"
        else:
            short_followup_pnl = 0.0
        if short_followup_pnl_source is None:
            short_followup_pnl_source = "missing_assumed_zero"
        if second_leg_is_long:
            current_price = float(snapshot.current_price or 0.0)
            reference_price_candidates = [
                current_price,
                float(snapshot.long_avg or 0.0),
                float(snapshot.short_avg or 0.0),
                float(cycle_state.get("last_cycle_reference_price") or 0.0),
                float(long_fill_price or 0.0),
            ]
            reference_price = max(reference_price_candidates)
            current_long_qty = float(snapshot.long_qty or 0.0)
            initial_long_qty = float(state.get("initial_long_qty") or 0.0)
            long_qty = self._fixed_long_cycle_qty(
                initial_long_qty,
                current_long_qty,
                reference_price,
                runtime_state=runtime_state,
            )
            if long_qty <= 0:
                _emit_short_tp_follow_up_skip(
                    "long_reduce_qty_non_positive",
                    symbol=active_trade_symbol,
                    long_reduce_qty=long_reduce_qty,
                    current_long_qty=current_long_qty,
                    initial_long_qty=initial_long_qty,
                    reference_price=reference_price,
                    reduction_pct_per_fill=self.config.reduction_pct_per_fill,
                )
                return []
            distance_pct_config = self.config.long_fill_distance_pct
            distance_pct = self._clamp_pct_fraction(self._pct(distance_pct_config))
            raw_trigger_price = reference_price * (1.0 + distance_pct)
            trigger_price = self._normalize_price(raw_trigger_price, runtime_state)
            if trigger_price <= 0:
                _emit_short_tp_follow_up_skip(
                    "long_reduce_invalid_trigger_price",
                    symbol=active_trade_symbol,
                    trigger_price=trigger_price,
                    reference_price=reference_price,
                )
                return []
            symbol_value = snapshot.symbol or self.config.symbol
            metadata_long_reduce = {
                "cycle_index": cycle_index,
                "cycle_role": self._get_second_leg_cycle_role(),
                "symbol": symbol_value,
                "source": "second_leg_long_reduce_cycle_pricing",
                "parent_second_leg_purpose": purpose,
                "first_leg_cycle_role": self._get_first_leg_cycle_role(),
                "second_leg_cycle_role": self._get_second_leg_cycle_role(),
                "first_leg_fill_price": long_fill_price,
                "entry_price": reference_price,
                "entry_price_for_pnl": reference_price,
                "snapshot_price": current_price,
                "trigger_price": trigger_price,
                "trigger_direction": 1,
                "trigger_by": "LastPrice",
                "close_on_trigger": True,
                "position_idx": 1,
                "qty": long_reduce_qty,
                "distance_pct_config": distance_pct_config,
                "distance_pct_used": distance_pct,
                "long_reduce_qty_source": long_reduce_qty_source,
            }
            _log_event(
                "fixed_cycle_second_leg_long_reduce_cycle_pricing",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "purpose": purpose,
                    "current_price": current_price,
                    "reference_price": reference_price,
                    "trigger_price": trigger_price,
                    "distance_pct": distance_pct_config,
                    "distance_pct_used": distance_pct,
                    "long_reduce_qty": long_reduce_qty,
                    "long_reduce_qty_source": long_reduce_qty_source,
                    "reason": "second_leg_long_reduce_cycle_pricing",
                },
            )
            gate_allowed, gate_reason, gate_payload = self._can_submit_cycle_intent(
                runtime_state,
                snapshot,
                purpose=purpose,
                cycle_index=cycle_index,
                cycle_role="short_reduce",
            )
            gate_payload = {
                **gate_payload,
                "symbol": snapshot.symbol or self.config.symbol,
            }
            if not gate_allowed:
                gate_payload["reason"] = gate_reason or "short_followup_not_ready"
                gate_payload["expected_next_action"] = (
                    gate_payload.get("expected_next_action") or "build_short_followup"
                )
                _log_event("fixed_cycle_state_gate_intent_blocked", gate_payload)
                return []
            gate_payload["reason"] = "short_followup_allowed"
            _log_event("fixed_cycle_state_gate_intent_allowed", gate_payload)
            self._reserve_cycle_intent_slot(
                runtime_state,
                cycle_index=cycle_index,
                field_name=self._get_second_leg_status_field(),
                normalized_purpose=self._normalize_cycle_purpose(
                    purpose,
                    {"cycle_index": cycle_index, "cycle_role": "short_reduce"},
                ),
                qty=long_qty,
                trigger_price=trigger_price,
            )
            split_intents = self._maybe_build_normal_cycle_second_leg_split_intents(
                cycle_index=cycle_index,
                purpose=purpose,
                qty=long_qty,
                trigger_price=trigger_price,
                snapshot=snapshot,
                runtime_state=runtime_state,
                side="long",
                position_idx=1,
                trigger_direction=1,
                metadata=metadata_long_reduce,
            )
            if split_intents:
                return split_intents
            intent = StrategyIntent(
                side="long",
                qty=long_qty,
                purpose=purpose,
                order_type="Market",
                reduce_only=True,
                trigger_price=trigger_price,
                trigger_direction=1,
                trigger_by="LastPrice",
                close_on_trigger=True,
                position_idx=1,
                metadata=metadata_long_reduce,
            )
            _log_event(
                "fixed_cycle_short_followup_intent_built",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "purpose": purpose,
                    "qty": long_qty,
                    "trigger_price": trigger_price,
                    "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
                    "reason": "second_leg_long_reduce_cycle_pricing",
                },
            )
            return [intent]
        planned_short_tp_qty = self._safe_float(
            cycle_sequence_entry.get("short_tp_qty"), None
        )
        fresh_short_cycle_qty = float(short_qty or 0.0)
        current_short_qty = (
            float(snapshot.short_qty or 0.0)
            if float(snapshot.short_qty or 0.0) > 0
            else float(state.get("initial_short_qty") or 0.0)
        )
        normalized_current_short_qty = (
            self._normalize_qty(current_short_qty, runtime_state)
            if current_short_qty > 0
            else 0.0
        )
        short_followup_qty = planned_short_tp_qty
        short_followup_qty_source = "cycle_sequence_entry.short_tp_qty"
        if (
            planned_short_tp_qty is not None
            and planned_short_tp_qty > 0
            and fresh_short_cycle_qty > 0
            and planned_short_tp_qty > fresh_short_cycle_qty + 1e-9
        ):
            # Reserved short_tp_qty can aggregate prior split totals; re-anchor to cycle pct.
            short_followup_qty = fresh_short_cycle_qty
            short_followup_qty_source = "configured_short_cycle_qty_stale_reserved_qty_ignored"
        if short_followup_qty is None or short_followup_qty <= 0:
            short_followup_qty = fresh_short_cycle_qty
            short_followup_qty_source = "configured_short_cycle_qty"
        if short_followup_qty is None or short_followup_qty <= 0:
            short_followup_qty = normalized_current_short_qty
            short_followup_qty_source = "current_short_qty_normalized"
        if (short_followup_qty is None or short_followup_qty <= 0) and long_reduce_qty > 0:
            short_followup_qty = long_reduce_qty
            short_followup_qty_source = "resolved_long_reduce_qty"
        _log_event(
            "fixed_cycle_short_followup_qty_resolved",
            {
                "cycle_index": cycle_index,
                "purpose": purpose,
                "long_reduce_qty": long_reduce_qty,
                "long_reduce_qty_source": long_reduce_qty_source,
                "planned_short_tp_qty": planned_short_tp_qty,
                "short_qty": short_qty,
                "current_short_qty": current_short_qty,
                "normalized_current_short_qty": normalized_current_short_qty,
                "confirmed_closed_qty": confirmed_closed_qty,
                "short_followup_qty": short_followup_qty,
                "short_followup_qty_source": short_followup_qty_source,
            },
        )
        gate_decision = "allow"
        if not cycle_long_add_filled:
            gate_decision = "skip_long_reduce_not_confirmed_filled"
        elif short_followup_qty is None or short_followup_qty <= 0:
            gate_decision = "skip_short_followup_invalid_short_qty"
        _log_event(
            "fixed_cycle_short_followup_gate_check",
            {
                "cycle_index": cycle_index,
                "cycle_long_add_filled": cycle_long_add_filled,
                "cycle_waiting_for_short_tp": cycle_waiting_for_short_tp,
                "short_tp_pending_cycle": short_tp_pending_cycle,
                "long_reduce_qty_debug": long_reduce_qty,
                "short_followup_qty": short_followup_qty,
                "short_followup_qty_source": short_followup_qty_source,
                "decision": gate_decision,
            },
        )
        if not cycle_long_add_filled:
            _emit_short_tp_follow_up_skip(
                "long_reduce_not_confirmed_filled",
                symbol=active_trade_symbol,
                cycle_sequence_entry=dict(cycle_sequence_entry),
                long_add_status=long_add_status,
            )
            return []
        if short_followup_qty is None or short_followup_qty <= 0:
            _emit_short_tp_follow_up_skip(
                "short_followup_invalid_short_qty",
                symbol=active_trade_symbol,
                short_followup_qty=short_followup_qty,
                short_followup_qty_source=short_followup_qty_source,
            )
            return []
        if long_reduce_qty <= 0:
            _log_event(
                "fixed_cycle_short_followup_long_qty_ignored",
                {
                    "cycle_index": cycle_index,
                    "cycle_long_add_filled": cycle_long_add_filled,
                    "long_reduce_qty_debug": long_reduce_qty,
                    "long_reduce_qty_source": long_reduce_qty_source,
                    "short_followup_qty": short_followup_qty,
                    "short_followup_qty_source": short_followup_qty_source,
                },
            )
        short_qty = float(short_followup_qty or 0.0)
        logger.info(
            "short_tp_build_proceed",
            extra={
                "order_id": long_fill.get("order_id"),
                "cycle_index": cycle_index,
                "symbol": active_trade_symbol,
                "decision": "proceed",
                "closed_pnl": confirmed_closed_pnl,
                "closed_qty": confirmed_closed_qty,
                "short_followup_pnl": short_followup_pnl,
                "short_followup_pnl_source": short_followup_pnl_source,
                "long_fill_metadata_confirmed_closed_pnl": long_fill_metadata.get("confirmed_closed_pnl"),
                "long_fill_metadata_closed_pnl": long_fill_metadata.get("closed_pnl"),
                "long_fill_metadata_long_reduce_closed_pnl": long_fill_metadata.get("long_reduce_closed_pnl"),
                "long_fill_metadata_runtime_calculated_pnl": long_fill_metadata.get("runtime_calculated_pnl"),
                "long_fill_metadata_exec_pnl": long_fill_metadata.get("exec_pnl"),
                "short_followup_qty": short_followup_qty,
                "short_followup_qty_source": short_followup_qty_source,
                "long_reduce_qty": long_reduce_qty,
                "long_reduce_qty_source": long_reduce_qty_source,
                "closed_pnl_ready": closed_pnl_ready,
            },
        )
        short_entry_price = float(snapshot.short_avg or state.get("short_avg") or 0.0)
        short_reduce_reference = short_entry_price
        target_profit_usdt = float(self.config.target_profit_usdt or 0.0)
        fee_rate = 0.00055
        if short_qty <= 0 or short_entry_price <= 0 or fee_rate >= 1.0:
            _log_event(
                "fixed_cycle_short_followup_invalid_inputs_detail",
                {
                    "cycle_index": cycle_index,
                    "purpose": purpose,
                    "long_reduce_qty": long_reduce_qty,
                    "long_reduce_qty_source": long_reduce_qty_source,
                    "short_followup_qty": short_followup_qty,
                    "short_followup_qty_source": short_followup_qty_source,
                    "short_qty": short_qty,
                    "short_entry_price": short_entry_price,
                    "fee_rate": fee_rate,
                    "long_fill_keys": sorted(long_fill.keys()),
                },
            )
            _emit_short_tp_follow_up_skip(
                "short_tp_invalid_initial_inputs",
                symbol=active_trade_symbol,
                long_fill_price=long_fill_price,
                long_reduce_qty=long_reduce_qty,
                confirmed_closed_pnl=confirmed_closed_pnl,
                confirmed_closed_qty=confirmed_closed_qty,
                short_followup_pnl=short_followup_pnl,
                short_followup_pnl_source=short_followup_pnl_source,
                short_followup_qty=short_followup_qty,
                short_entry_price=short_entry_price,
                short_qty=short_qty,
                fee_rate=fee_rate,
            )
            context.audit.log_event(
                "fixed_cycle_downside_skip",
                strategy=self.name,
                skip_reason="short_tp_invalid",
                cycle_number=cycle_index,
                purpose=purpose,
                long_fill_price=long_fill_price,
                long_reduce_qty=long_reduce_qty,
                confirmed_closed_pnl=confirmed_closed_pnl,
                confirmed_closed_qty=confirmed_closed_qty,
                short_followup_pnl=short_followup_pnl,
                short_followup_pnl_source=short_followup_pnl_source,
                short_followup_qty=short_followup_qty,
                short_entry_price=short_entry_price,
                short_qty=short_qty,
                fee_rate=fee_rate,
            )
            return []

        short_entry_price = float(short_entry_price)
        short_qty = float(short_qty)
        fee_rate = float(fee_rate)

        long_loss_usdt = max(-float(short_followup_pnl or 0.0), 0.0)
        required_net = max(long_loss_usdt + target_profit_usdt, 0.0)
        required_remaining_profit = required_net
        required_price_move = required_net / short_qty if short_qty > 0 else 0.0
        if (
            long_loss_usdt > 0
            and required_net <= float(target_profit_usdt or 0.0)
        ):
            logger.warning(
                "short_tp_required_net_suspicious",
                extra={
                    "long_loss_usdt": long_loss_usdt,
                    "target_profit_usdt": target_profit_usdt,
                    "required_net": required_net,
                    "realized_net_pnl_total": self._get_realized_net_pnl_total(
                        runtime_state, snapshot
                    ),
                    "confirmed_closed_pnl": confirmed_closed_pnl,
                    "short_followup_pnl": short_followup_pnl,
                    "short_followup_pnl_source": short_followup_pnl_source,
                    "short_qty": short_qty,
                    "short_entry_price": short_entry_price,
                },
            )

        if short_qty <= 0:
            _emit_short_tp_follow_up_skip(
                "short_tp_invalid_short_qty_non_positive",
                symbol=active_trade_symbol,
                short_entry_price=short_entry_price,
                short_qty=short_qty,
            )
            context.audit.log_event(
                "fixed_cycle_downside_skip",
                strategy=self.name,
                skip_reason="short_tp_invalid",
                cycle_number=cycle_index,
                purpose=purpose,
                short_entry_price=short_entry_price,
                short_qty=short_qty,
            )
            return []

        tp_price = (
            (short_entry_price * (1 - fee_rate))
            - (required_net / short_qty)
        ) / (1 + fee_rate)

        if tp_price <= 0:
            _emit_short_tp_follow_up_skip(
                "short_tp_invalid_tp_price_non_positive",
                symbol=active_trade_symbol,
                tp_price=tp_price,
            )
            context.audit.log_event(
                "fixed_cycle_downside_skip",
                strategy=self.name,
                skip_reason="short_tp_invalid",
                cycle_number=cycle_index,
                purpose=purpose,
                tp_price=tp_price,
            )
            return []

        symbol, rules, _ = self._resolve_instrument_rules(runtime_state)
        tp_price = self._normalize_price(tp_price, runtime_state)
        instrument_tick_size = (
            float(rules["tick_size"]) if rules and rules.get("tick_size") else 0.0
        )
        price_tick_size = instrument_tick_size or float(self.config.price_tick_size or 0.0)
        if price_tick_size <= 0:
            price_tick_size = 0.01

        expected = required_net

        def compute_net(tp: float, qty: float) -> float:
            second_leg_cycle_role = self._get_second_leg_cycle_role()
            if second_leg_cycle_role == "short_reduce":
                return (
                    (short_entry_price - tp) * qty
                    - (short_entry_price * qty * fee_rate)
                    - (tp * qty * fee_rate)
                )
            # Long-second-leg (Mirror-Short-Bot): Profit, wenn Preis steigt.
            return (
                (tp - short_entry_price) * qty
                - (short_entry_price * qty * fee_rate)
                - (tp * qty * fee_rate)
            )

        net = compute_net(tp_price, short_qty)
        max_iterations = 50
        i = 0
        while net < expected and i < max_iterations:
            tp_price -= price_tick_size
            if tp_price <= 0:
                break
            tp_price = math.floor(tp_price / price_tick_size) * price_tick_size
            net = compute_net(tp_price, short_qty)
            i += 1

        raw_trigger_price = max(tp_price, price_tick_size)
        long_avg = float(snapshot.long_avg or 0.0)
        min_threshold_pct = float(self.config.short_tp_min_threshold_pct_after_long_reduce or 0.0)
        original_trigger_price_raw = raw_trigger_price
        safe_short_tp_price = None
        short_tp_guard_applied = False

        if (
            raw_trigger_price is not None
            and raw_trigger_price > 0
            and long_avg > 0
            and min_threshold_pct > 0
        ):
            safe_short_tp_price = long_avg * (1 - min_threshold_pct)

            if raw_trigger_price > safe_short_tp_price:
                raw_trigger_price = safe_short_tp_price
                short_tp_guard_applied = True
                logger.info(
                    "short_tp_min_threshold_guard_applied %s",
                    {
                        "cycle_index": cycle_index,
                        "long_avg": long_avg,
                        "short_avg": float(snapshot.short_avg or 0.0),
                        "current_price": float(snapshot.current_price or 0.0),
                        "original_trigger_price_raw": original_trigger_price_raw,
                        "safe_short_tp_price": safe_short_tp_price,
                        "final_trigger_price_raw": raw_trigger_price,
                        "min_threshold_pct": min_threshold_pct,
                        "short_qty": short_qty,
                        "reason": "short_tp_after_long_reduce_too_close_to_long_avg",
                    },
                )

        trigger_price = self._normalize_price(raw_trigger_price, runtime_state)
        short_reduce_cover_adjustment: dict[str, Any] = {}
        if self._get_second_leg_cycle_role() == "short_reduce" and required_net > 0:
            trigger_price, short_qty, short_reduce_cover_adjustment = (
                self._enforce_short_reduce_loss_cover_invariant(
                    trigger_price=trigger_price,
                    short_qty=short_qty,
                    short_entry_price=short_entry_price,
                    required_net=required_net,
                    fee_rate=fee_rate,
                    runtime_state=runtime_state,
                    snapshot=snapshot,
                    price_tick_size=price_tick_size,
                )
            )
            if short_reduce_cover_adjustment.get("adjusted"):
                raw_trigger_price = trigger_price
                _log_event(
                    "fixed_cycle_short_reduce_loss_cover_invariant_adjusted",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "purpose": purpose,
                        **short_reduce_cover_adjustment,
                    },
                )
        state["last_expected_short_tp_net"] = required_net
        state["last_short_tp_trigger_price"] = trigger_price
        state["last_short_tp_qty"] = short_qty

        # Direction-neutral distance zwischen erstem Bein und finalem Second-Leg-TP
        first_leg_fill_price = self._get_first_leg_fill_price(runtime_state, cycle_index)
        if first_leg_fill_price <= 0:
            first_leg_fill_price = float(cycle_state.get("last_cycle_reference_price") or 0.0)
        if first_leg_fill_price > 0 and trigger_price > 0:
            distance_pct_signed = (
                (trigger_price - first_leg_fill_price) / first_leg_fill_price
            ) * 100.0
            distance_pct_abs = abs(distance_pct_signed)
        else:
            distance_pct_abs = 0.0
        threshold_pct = float(self.config.max_post_recovery_long_reduce_distance_pct or 0.0)

        # Stage-Entscheidung auf Basis der bestehenden Recovery-Schwelle.
        # Profit-Staging (2/3 gewichtete Teil-TPs) gilt nur bei required_net > 0.
        # Normale Zyklen ohne Nettoloss (stage_count == 1) versuchen zuerst den
        # min_notional-basierten Equal-Split-Helper; bei Misserfolg Single-Fallback.
        stage_count = 1
        if required_net > 0 and threshold_pct > 0 and distance_pct_abs > 0:
            if distance_pct_abs <= 1.5:
                stage_count = 2
            elif distance_pct_abs <= threshold_pct:
                stage_count = 3

        if self._maybe_activate_recovery_after_first_leg_fill(
            snapshot,
            runtime_state,
            cycle_index=cycle_index,
            trigger_price=trigger_price,
            first_leg_purpose=first_leg_purpose or "",
            second_leg_purpose=second_leg_purpose or "",
            first_leg_loss_usdt=long_loss_usdt,
        ):
            return []
        realized_net_pnl_total = self._get_realized_net_pnl_total(runtime_state, snapshot)
        logger.debug(
            "short_tp_loss_recovery",
            extra={
                "realized_net_pnl_total": realized_net_pnl_total,
                "required_remaining_profit": required_remaining_profit,
                "required_price_move": required_price_move,
                "tp_price": tp_price,
            },
        )
        current_price = float(snapshot.current_price or 0.0)
        use_market_fallback = current_price > 0 and current_price <= trigger_price

        # Gemeinsame Größen für Single-TP und Staging
        required_price_move = short_entry_price - trigger_price
        required_short_gross = short_qty * required_price_move

        # Wenn wir keine Stages bauen (stage_count == 1), Single-TP-Logik wie bisher.
        # Staging wird nur verwendet, wenn wir innerhalb der Recovery-Schwelle liegen.
        if stage_count == 1 or use_market_fallback:
            price = self._normalize_price(
                max(trigger_price - self.config.price_tick_size, self.config.price_tick_size),
                runtime_state,
            )
            if short_qty <= 0 or trigger_price <= 0:
                _emit_short_tp_follow_up_skip(
                    "short_tp_invalid_final_trigger_inputs",
                    symbol=active_trade_symbol,
                    long_fill_price=long_fill_price,
                    short_qty=short_qty,
                    trigger_price=trigger_price,
                    final_limit_price=price,
                )
                context.audit.log_event(
                    "fixed_cycle_downside_skip",
                    strategy=self.name,
                    skip_reason="short_tp_invalid",
                    cycle_number=cycle_index,
                    purpose=purpose,
                    long_fill_price=long_fill_price,
                    short_qty=short_qty,
                    trigger_price=trigger_price,
                )
                return []

            logger.info(
                "short_tp_final_inputs",
                extra={
                    "order_id": long_fill.get("order_id"),
                    "cycle_index": cycle_index,
                    "symbol": active_trade_symbol,
                    "decision": "trigger_run",
                    "closed_pnl": confirmed_closed_pnl,
                    "closed_qty": confirmed_closed_qty,
                    "long_loss_usdt": long_loss_usdt,
                    "required_net_profit": required_net,
                    "trigger_price": trigger_price,
                    "short_qty": short_qty,
                    "short_tp_min_threshold_pct_after_long_reduce": min_threshold_pct,
                    "short_tp_guard_long_avg": long_avg,
                    "short_tp_guard_original_trigger_price_raw": original_trigger_price_raw,
                    "short_tp_guard_safe_short_tp_price": safe_short_tp_price,
                    "short_tp_guard_applied": short_tp_guard_applied,
                },
            )
            context.audit.log_event(
                "fixed_cycle_short_cycle_planned",
                strategy=self.name,
                cycle_index=cycle_index,
                side="short",
                purpose=purpose,
                entry_reference_price=float(state.get("entry_reference_price") or 0.0),
                long_reduce_qty=long_reduce_qty,
                confirmed_closed_pnl=confirmed_closed_pnl,
                confirmed_closed_qty=confirmed_closed_qty,
                confirmed_closed_avg_price=confirmed_closed_avg_price,
                confirmed_closed_cost=confirmed_closed_cost,
                confirmed_closed_pnl_updated_time=long_fill.get("closed_pnl_updated_time"),
                fill_count=long_fill.get("fill_count"),
                short_entry_price=short_entry_price,
                short_reduce_reference=short_reduce_reference,
                fee_rate=fee_rate,
                target_profit_usdt=target_profit_usdt,
                long_loss_usdt=long_loss_usdt,
                required_short_gross=required_short_gross,
                required_price_move=required_price_move,
                required_net=required_net,
                trigger_formula="((short_entry_price * (1 - fee_rate)) - (required_net / short_qty)) / (1 + fee_rate)",
                trigger_formula_details="tp_price is decremented by price_tick_size until compute_net(tp) >= required_net; compute_net subtracts both entry and exit fees",
                trigger_price_raw=raw_trigger_price,
                trigger_price_normalized=trigger_price,
                price_tick_size=price_tick_size,
                reduction_multiplier=reduction_multiplier,
                reduction_pct_used=effective_reduction_pct,
                qty_formula="current_short_qty * reduction_pct_per_fill * reduction_multiplier",
                qty_raw=snapshot.short_qty * self._pct(effective_reduction_pct),
                qty_normalized=short_qty,
                short_tp_min_threshold_pct_after_long_reduce=min_threshold_pct,
                short_tp_guard_long_avg=long_avg,
                short_tp_guard_original_trigger_price_raw=original_trigger_price_raw,
                short_tp_guard_safe_short_tp_price=safe_short_tp_price,
                short_tp_guard_applied=short_tp_guard_applied,
                order_type="Limit",
                reduce_only=True,
            )
            pending_after = float(state.get("pending_cycle_loss_usdt") or 0.0)
            _audit_calc(
                "short_tp_build_calc",
                {
                    "cycle_index": cycle_index,
                    "symbol": active_trade_symbol,
                    "long_fill_purpose": long_purpose,
                    "cycle_entry_long_add_confirmed_pnl": cycle_entry_long_add_confirmed_pnl,
                    "cycle_entry_long_reduce_closed_pnl": cycle_entry_long_reduce_closed_pnl,
                    "cycle_entry_long_add_loss_usdt": cycle_entry_long_add_loss_usdt,
                    "long_fill_confirmed_closed_pnl": long_fill_confirmed_closed_pnl,
                    "long_fill_closed_pnl": long_fill_closed_pnl,
                    "long_fill_pnl_this_fill": self._safe_float(long_fill.get("pnl_this_fill"), None),
                    "provisional_exec_pnl_total": provisional_exec_pnl_total,
                    "provisional_runtime_pnl_total": provisional_runtime_pnl_total,
                    "long_loss_usdt": long_loss_usdt,
                    "confirmed_closed_pnl": confirmed_closed_pnl,
                    "short_followup_pnl": short_followup_pnl,
                    "short_followup_pnl_source": short_followup_pnl_source,
                    "selected_short_followup_pnl_source": short_followup_pnl_source,
                    "long_fill_top_level_keys": sorted(list(long_fill.keys())),
                    "long_fill_metadata_keys": sorted(list(long_fill_metadata.keys())),
                    "metadata_confirmed_closed_pnl": long_fill_metadata.get("confirmed_closed_pnl"),
                    "metadata_long_reduce_closed_pnl": long_fill_metadata.get("long_reduce_closed_pnl"),
                    "metadata_closed_pnl": long_fill_metadata.get("closed_pnl"),
                    "metadata_runtime_calculated_pnl": long_fill_metadata.get("runtime_calculated_pnl"),
                    "metadata_exec_pnl": long_fill_metadata.get("exec_pnl"),
                    "target_profit_usdt": target_profit_usdt,
                    "required_net": required_net,
                    "short_entry_price": short_entry_price,
                    "short_qty": short_qty,
                    "fee_rate": fee_rate,
                    "trigger_price": trigger_price,
                    "raw_trigger_price": raw_trigger_price,
                    "short_tp_min_threshold_pct_after_long_reduce": min_threshold_pct,
                    "short_tp_guard_long_avg": long_avg,
                    "short_tp_guard_original_trigger_price_raw": original_trigger_price_raw,
                    "short_tp_guard_safe_short_tp_price": safe_short_tp_price,
                    "short_tp_guard_applied": short_tp_guard_applied,
                    "break_even_price": float(state.get("latest_break_even_price") or 0.0),
                    "expected_short_tp_net": required_net,
                    "pending_cycle_loss_usdt_before": pending_before,
                    "pending_cycle_loss_usdt_after": pending_after,
                    "order_purpose": purpose,
                    "cycle_role": "short_reduce",
                    "required_price_move": required_price_move,
                    "required_short_gross": required_short_gross,
                },
            )
        else:
            # Staged Second-Leg-TP: 2 oder 3 Teil-TPs, direction-neutral um first_leg_fill_price
            if short_qty <= 0 or trigger_price <= 0 or first_leg_fill_price <= 0:
                _emit_short_tp_follow_up_skip(
                    "staged_second_leg_tp_invalid_inputs",
                    symbol=active_trade_symbol,
                    long_fill_price=long_fill_price,
                    short_qty=short_qty,
                    trigger_price=trigger_price,
                    first_leg_fill_price=first_leg_fill_price,
                )
                context.audit.log_event(
                    "fixed_cycle_downside_skip",
                    strategy=self.name,
                    skip_reason="short_tp_invalid",
                    cycle_number=cycle_index,
                    purpose=purpose,
                    long_fill_price=long_fill_price,
                    short_qty=short_qty,
                    trigger_price=trigger_price,
                )
                return []

            if stage_count == 2:
                stage_weights = [0.4, 0.6]
                ratios = [0.5, 1.0]
            else:
                stage_weights = [0.2, 0.3, 0.5]
                ratios = [1.0 / 3.0, 2.0 / 3.0, 1.0]

            # Plan Stages
            delta = trigger_price - first_leg_fill_price
            remaining_qty = short_qty
            remaining_required_net = required_net
            stages: list[dict[str, Any]] = []
            for idx, (weight, ratio) in enumerate(zip(stage_weights, ratios)):
                stage_required_net = weight * required_net
                # linear Netto-Formel in qty → qty = stage_required_net / per_unit_net
                stage_trigger_price_raw = first_leg_fill_price + ratio * delta
                stage_trigger_price = self._normalize_price(stage_trigger_price_raw, runtime_state)
                per_unit_net = compute_net(stage_trigger_price, 1.0)
                if per_unit_net <= 0:
                    # Fallback: keine weitere Stage bauen
                    break
                desired_qty = min(remaining_qty, max(stage_required_net / per_unit_net, 0.0))
                if desired_qty <= 0:
                    break
                normalized_qty = self._normalize_qty(desired_qty, runtime_state)
                if normalized_qty <= 0:
                    break
                if idx == stage_count - 1:
                    # Letzte Stage bekommt Rest
                    normalized_qty = remaining_qty

                stage_net = compute_net(stage_trigger_price, normalized_qty)
                remaining_qty = max(remaining_qty - normalized_qty, 0.0)
                remaining_required_net = max(remaining_required_net - stage_net, 0.0)
                stages.append(
                    {
                        "index": idx,
                        "trigger_price": stage_trigger_price,
                        "qty": normalized_qty,
                        "expected_net": stage_net,
                    }
                )
                if remaining_qty <= 0:
                    break

            if not stages:
                _emit_short_tp_follow_up_skip(
                    "staged_second_leg_tp_no_valid_stages",
                    symbol=active_trade_symbol,
                    long_fill_price=long_fill_price,
                    short_qty=short_qty,
                    trigger_price=trigger_price,
                )
                return []

            # Gesamt-required_net für Exit-Pricing pro Cycle merken
            cycle_key = str(cycle_index)
            required_map = state.setdefault("staged_second_leg_tp_required_net_total", {})
            required_map[cycle_key] = required_net

            logger.info(
                "staged_second_leg_tp_plan_created",
                extra={
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "stage_count": len(stages),
                    "distance_pct_abs": distance_pct_abs,
                    "threshold_pct": threshold_pct,
                    "required_net_profit": required_net,
                    "first_leg_fill_price": first_leg_fill_price,
                    "final_second_leg_trigger_price": trigger_price,
                    "stages": stages,
                },
            )
        metadata = {
            "cycle_index": cycle_index,
            "cycle_role": "short_reduce",
            "symbol": active_trade_symbol,
            **(
                {"replace_open_purpose": purpose}
                if self._should_attach_replace_open_purpose(
                    snapshot,
                    runtime_state,
                    purpose,
                    cycle_index=cycle_index,
                    cycle_role="short_reduce",
                )
                else {}
            ),
            "entry_reference_price": float(state.get("entry_reference_price") or 0.0),
            "long_fill_price": long_fill_price,
            "long_reduce_qty": long_reduce_qty,
            "source_long_reduce_confirmed_pnl": confirmed_closed_pnl,
            "source_long_reduce_confirmed_qty": confirmed_closed_qty,
            "source_long_reduce_confirmed_avg_price": confirmed_closed_avg_price,
            "source_long_reduce_confirmed_cost": confirmed_closed_cost,
            "source_long_reduce_confirmed_pnl_updated_time": long_fill.get("closed_pnl_updated_time"),
            "short_entry_price": short_entry_price,
            "short_reduce_reference": short_reduce_reference,
            "fee_rate": fee_rate,
            "required_price_move": required_price_move,
            "required_net": required_net,
            "long_loss_usdt": long_loss_usdt,
            "target_profit_usdt": target_profit_usdt,
            "short_followup_pnl": short_followup_pnl,
            "short_followup_pnl_source": short_followup_pnl_source,
            "raw_trigger_price": raw_trigger_price,
            "trigger_price": trigger_price,
            "original_trigger_price_raw": original_trigger_price_raw,
            "short_tp_guard_applied": short_tp_guard_applied,
            "short_tp_guard_safe_short_tp_price": safe_short_tp_price,
            "short_tp_guard_original_trigger_price_raw": original_trigger_price_raw,
            "first_leg_fill_price": first_leg_fill_price,
            "distance_pct_abs": distance_pct_abs,
            "threshold_pct": threshold_pct,
            "stage_count": stage_count,
            "use_market_fallback": use_market_fallback,
            "short_reduce_loss_cover_invariant_adjusted": bool(
                short_reduce_cover_adjustment.get("adjusted")
            ),
            **(
                {
                    key: short_reduce_cover_adjustment[key]
                    for key in (
                        "original_short_qty",
                        "adjusted_short_qty",
                        "original_trigger_price",
                        "adjusted_trigger_price",
                        "expected_net_after_adjustment",
                        "reason",
                    )
                    if key in short_reduce_cover_adjustment
                }
                if short_reduce_cover_adjustment.get("adjusted")
                else {}
            ),
        }
        if use_market_fallback:
            metadata.update(
                {
                    "market_fallback": True,
                    "fallback_reason": "short_tp_trigger_already_crossed",
                    "original_trigger_price": trigger_price,
                    "current_price": current_price,
                }
            )
            context.audit.log_event(
                "fixed_cycle_short_cycle_market_fallback_planned",
                strategy=self.name,
                cycle_index=cycle_index,
                purpose=purpose,
                symbol=active_trade_symbol,
                trigger_price=trigger_price,
                current_price=current_price,
            )
        gate_allowed, gate_reason, gate_payload = self._can_submit_cycle_intent(
            runtime_state,
            snapshot,
            purpose=purpose,
            cycle_index=cycle_index,
            cycle_role="short_reduce",
        )
        gate_payload = {
            **gate_payload,
            "symbol": snapshot.symbol or self.config.symbol,
        }
        if not gate_allowed:
            gate_payload["reason"] = gate_reason or "short_followup_not_ready"
            gate_payload["expected_next_action"] = (
                gate_payload.get("expected_next_action") or "build_short_followup"
            )
            _log_event("fixed_cycle_state_gate_intent_blocked", gate_payload)
            return []
        gate_payload["reason"] = "short_followup_allowed"
        _log_event("fixed_cycle_state_gate_intent_allowed", gate_payload)
        normalized_second_leg_purpose = self._normalize_cycle_purpose(
            purpose,
            {"cycle_index": cycle_index, "cycle_role": "short_reduce"},
        )
        if _equivalent_second_leg_followup_planned(
            normalized_second_leg_purpose,
            trigger_price,
            short_qty,
        ):
            _emit_short_tp_follow_up_skip(
                "equivalent_second_leg_followup_already_planned",
                blocking_purpose=purpose,
                blocking_trigger_price=trigger_price,
                blocking_qty=short_qty,
            )
            return []
        if _has_equivalent_second_leg_order(trigger_price, short_qty):
            _emit_short_tp_follow_up_skip(
                "equivalent_second_leg_order_already_active",
                blocking_purpose=purpose,
                blocking_trigger_price=trigger_price,
                blocking_qty=short_qty,
            )
            return []
        self._reserve_cycle_intent_slot(
            runtime_state,
            cycle_index=cycle_index,
            field_name=self._get_second_leg_status_field(),
            normalized_purpose=normalized_second_leg_purpose,
            qty=short_qty,
            trigger_price=trigger_price,
        )
        _record_second_leg_followup_planned(
            normalized_second_leg_purpose,
            trigger_price,
            short_qty,
        )
        if not use_market_fallback:
            split_intents = self._maybe_build_normal_cycle_second_leg_split_intents(
                cycle_index=cycle_index,
                purpose=purpose,
                qty=short_qty,
                trigger_price=trigger_price,
                snapshot=snapshot,
                runtime_state=runtime_state,
                side="short",
                position_idx=2,
                trigger_direction=2,
                metadata=metadata,
            )
            if split_intents and required_net > SHORT_REDUCE_COVER_NET_EPS:
                split_intents, short_qty, trigger_price, split_adjustment = (
                    self._ensure_short_reduce_split_stages_cover_loss(
                        split_intents=split_intents,
                        trigger_price=trigger_price,
                        short_qty=short_qty,
                        short_entry_price=short_entry_price,
                        required_net=required_net,
                        fee_rate=fee_rate,
                        runtime_state=runtime_state,
                        snapshot=snapshot,
                        price_tick_size=price_tick_size,
                        cycle_index=cycle_index,
                        purpose=purpose,
                        side="short",
                        position_idx=2,
                        trigger_direction=2,
                        metadata=metadata,
                    )
                )
                if split_adjustment.get("adjusted"):
                    short_reduce_cover_adjustment = {
                        **short_reduce_cover_adjustment,
                        **split_adjustment,
                        "adjusted": True,
                        "reason": split_adjustment.get(
                            "reason",
                            "short_reduce_loss_cover_split_min_stage_adjusted",
                        ),
                    }
                    raw_trigger_price = trigger_price
                    state["last_short_tp_trigger_price"] = trigger_price
                    state["last_short_tp_qty"] = short_qty
                    metadata.update(
                        {
                            "short_reduce_loss_cover_invariant_adjusted": True,
                            "original_short_qty": split_adjustment.get(
                                "original_short_qty",
                                short_reduce_cover_adjustment.get("original_short_qty"),
                            ),
                            "adjusted_short_qty": short_qty,
                            "original_trigger_price": split_adjustment.get(
                                "original_trigger_price",
                                short_reduce_cover_adjustment.get("original_trigger_price"),
                            ),
                            "adjusted_trigger_price": trigger_price,
                            "expected_net_after_adjustment": split_adjustment.get(
                                "expected_net_after_adjustment"
                            ),
                            "reason": split_adjustment.get("reason"),
                        }
                    )
                    _log_event(
                        "fixed_cycle_short_reduce_loss_cover_invariant_adjusted",
                        {
                            "symbol": snapshot.symbol or self.config.symbol,
                            "cycle_index": cycle_index,
                            "purpose": purpose,
                            **short_reduce_cover_adjustment,
                        },
                    )
            if split_intents:
                split_intents = _dedupe_second_leg_intents(split_intents)
                return split_intents
            _, rules, _ = self._resolve_instrument_rules(runtime_state)
            min_order_qty = float(
                rules["min_order_qty"]
                if rules and rules.get("min_order_qty")
                else float(self.config.min_order_qty or 0.0)
            )
            min_notional_value = float(
                rules["min_notional"]
                if rules and rules.get("min_notional")
                else float(self.config.min_notional_usdt or 0.0)
            )
            _log_event(
                "fixed_cycle_normal_second_leg_split_disabled_for_short_reduce",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "purpose": purpose,
                    "qty": short_qty,
                    "trigger_price": trigger_price,
                    "min_order_qty": min_order_qty,
                    "min_notional_value": min_notional_value,
                    "side": "short",
                    "reason": "split_disabled_min_order_or_notional",
                },
            )

        # Staging: mehrere Second-Leg-TP-Intents mit Stage-Metadaten
        if stage_count > 1 and not use_market_fallback and "stages" in locals() and stages:
            second_leg_cycle_role = self._get_second_leg_cycle_role()
            if second_leg_cycle_role == "short_reduce":
                _log_event(
                    "fixed_cycle_staged_second_leg_disabled_for_short_reduce",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "purpose": purpose,
                        "qty": short_qty,
                        "trigger_price": trigger_price,
                        "reason": "single_25pct_reduce_required",
                    },
                )
            else:
                # Min-Notional-Grenze für Stages bestimmen (Exchange / Config)
                _, rules, _ = self._resolve_instrument_rules(runtime_state)
                min_notional = float(
                    rules["min_notional"]
                    if rules and rules.get("min_notional")
                    else float(self.config.min_notional_usdt or 0.0)
                )

                intents: list[StrategyIntent] = []
                rejected_stage_indices = []
                rejected_stage_notionals = []
                first_leg_cycle_role = self._get_first_leg_cycle_role()
                for stage in stages:
                    stage_index = int(stage.get("index") or 0)
                    stage_trigger_price = float(stage.get("trigger_price") or 0.0)
                    stage_qty = float(stage.get("qty") or 0.0)
                    stage_expected_net = float(stage.get("expected_net") or 0.0)
                    if stage_qty <= 0 or stage_trigger_price <= 0:
                        continue
                    stage_notional = stage_qty * stage_trigger_price
                    if min_notional > 0 and stage_notional + 1e-8 < min_notional:
                        rejected_stage_indices.append(stage_index)
                        rejected_stage_notionals.append(stage_notional)
                        continue
                    stage_metadata = {
                        **metadata,
                        "is_staged_second_leg_tp": True,
                        "stage_index": stage_index,
                        "stage_count": len(stages),
                        "stage_expected_net": stage_expected_net,
                        "stage_required_net_total": required_net,
                        "stage_trigger_price": stage_trigger_price,
                        "first_leg_fill_price": first_leg_fill_price,
                        "final_second_leg_trigger_price": trigger_price,
                        "distance_pct_abs": distance_pct_abs,
                        "threshold_pct": threshold_pct,
                        "first_leg_cycle_role": first_leg_cycle_role,
                        "second_leg_cycle_role": second_leg_cycle_role,
                        "parent_second_leg_purpose": purpose,
                    }
                    if second_leg_cycle_role == "short_reduce":
                        side = "short"
                        position_idx = 2
                    elif second_leg_cycle_role == "long_reduce":
                        side = "long"
                        position_idx = 1
                    else:
                        _emit_short_tp_follow_up_skip(
                            "staged_second_leg_tp_unknown_cycle_role",
                            symbol=active_trade_symbol,
                            cycle_index=cycle_index,
                            cycle_role=second_leg_cycle_role,
                        )
                        continue
                    intent = StrategyIntent(
                        side=side,
                        qty=stage_qty,
                        purpose=purpose,
                        order_type="Market",
                        reduce_only=True,
                        trigger_price=stage_trigger_price,
                        trigger_direction=2,
                        trigger_by="LastPrice",
                        close_on_trigger=True,
                        position_idx=position_idx,
                        metadata=stage_metadata,
                    )
                    intents.append(intent)

            if intents:
                intents = _dedupe_second_leg_intents(intents)
                _log_event(
                    "staged_second_leg_tp_intents_created",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "purpose": purpose,
                        "stage_count": len(intents),
                        "stages": [
                            {
                                "stage_index": m.metadata.get("stage_index") if hasattr(m, "metadata") else None,
                                "qty": getattr(m, "qty", None),
                                "trigger_price": getattr(m, "trigger_price", None),
                            }
                            for m in intents
                        ],
                    },
                )
                return intents

            # Alle Stages wurden aufgrund Min-Notional verworfen → Fallback/Block
            total_qty = float(short_qty or 0.0)
            effective_trigger = trigger_price if not use_market_fallback else float(snapshot.current_price or 0.0)
            total_notional = total_qty * effective_trigger if effective_trigger > 0 else 0.0

            _log_event(
                "fixed_cycle_second_leg_all_intents_rejected",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "purpose": purpose,
                    "total_qty": total_qty,
                    "total_notional": total_notional,
                    "min_notional": min_notional,
                    "original_stage_count": len(stages),
                    "rejected_stage_count": len(rejected_stage_indices),
                    "rejected_stage_indices": rejected_stage_indices,
                    "rejected_stage_notionals": rejected_stage_notionals,
                    "reason": "stage_below_min_notional",
                },
            )

            if min_notional > 0 and total_notional + 1e-8 < min_notional:
                # Gesamtorder ebenfalls unter Min-Notional → Build komplett blocken und Waiting-State zurücksetzen
                cycle_state = self._ensure_cycle_state(runtime_state)
                cycle_entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
                previous_status = self._get_second_leg_status(cycle_entry)
                self._set_second_leg_status(cycle_entry, "REJECTED")
                # generisches Pending-Feld der Second-Leg-Seite zurücksetzen
                pending_field = self._second_leg_pending_cycle_field()
                state[pending_field] = 0
                cycle_state[pending_field] = 0
                # vorhandene direction-spezifische Pending-Felder defensiv auf 0 setzen
                for pending_name in ("pending_short_cycle_index", "pending_long_cycle_index"):
                    if pending_name in state:
                        state[pending_name] = 0
                    if pending_name in cycle_state:
                        cycle_state[pending_name] = 0
                self._set_second_leg_waiting_state(
                    state,
                    cycle_state,
                    waiting=False,
                    cycle_index=0,
                )
                self._persist_cycle_sequence_state(runtime_state)
                _log_event(
                    "fixed_cycle_second_leg_build_blocked_min_notional",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "purpose": purpose,
                        "total_qty": total_qty,
                        "total_notional": total_notional,
                        "min_notional": min_notional,
                        "stage_count": len(stages),
                        "rejected_stage_indices": rejected_stage_indices,
                        "rejected_stage_notionals": rejected_stage_notionals,
                        "previous_second_leg_status": previous_status,
                        "new_second_leg_status": "REJECTED",
                    },
                )
                _log_event(
                    "fixed_cycle_second_leg_waiting_state_cleared_no_active_order",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "purpose": purpose,
                        "cycle_waiting_for_short_tp": False,
                        "pending_second_leg_cycle_index": 0,
                    },
                )
                return []

            # Fallback: einzelne Second-Leg-Order mit Gesamtmenge
            fallback_metadata = {
                **metadata,
                "split_fallback_reason": metadata.get(
                    "split_fallback_reason",
                    "stage_below_min_notional",
                ),
                "rejected_stage_count": len(rejected_stage_indices),
                "rejected_stage_notional_values": rejected_stage_notionals,
                "original_stage_count": len(stages),
                "fallback_to_single_second_leg": True,
            }
            # Side/Position dynamisch aus Second-Leg-Rolle ableiten
            if second_leg_cycle_role == "short_reduce":
                fallback_side = "short"
                fallback_position_idx = 2
            elif second_leg_cycle_role == "long_reduce":
                fallback_side = "long"
                fallback_position_idx = 1
            else:
                # defensiver Fallback: ursprüngliches Verhalten
                fallback_side = "short"
                fallback_position_idx = 2

            intent = StrategyIntent(
                side=fallback_side,
                qty=short_qty,
                purpose=purpose,
                order_type="Market",
                reduce_only=True,
                trigger_price=None if use_market_fallback else trigger_price,
                trigger_direction=None if use_market_fallback else 2,
                trigger_by=None if use_market_fallback else "LastPrice",
                close_on_trigger=None if use_market_fallback else True,
                position_idx=fallback_position_idx,
                metadata=fallback_metadata,
            )
            _log_event(
                "fixed_cycle_second_leg_split_fallback_to_single_second_leg",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "purpose": purpose,
                    "total_qty": total_qty,
                    "total_notional": total_notional,
                    "min_notional": min_notional,
                    "rejected_stage_indices": rejected_stage_indices,
                    "rejected_stage_notionals": rejected_stage_notionals,
                },
            )
            return [intent]

        # Single-TP-Intent (bestehender Pfad)
        intent = StrategyIntent(
            side="short",
            qty=short_qty,
            purpose=purpose,
            order_type="Market",
            reduce_only=True,
            trigger_price=None if use_market_fallback else trigger_price,
            trigger_direction=None if use_market_fallback else 2,
            trigger_by=None if use_market_fallback else "LastPrice",
            close_on_trigger=None if use_market_fallback else True,
            position_idx=2,
            metadata=metadata,
        )
        _log_event(
            "fixed_cycle_short_followup_intent_built",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "cycle_index": cycle_index,
                "purpose": purpose,
                "qty": short_qty,
                "trigger_price": trigger_price,
                "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
            },
        )
        return [intent]

    def _build_exit_intents(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        current_cycle: int,
        break_even_price: float,
        tp_price: float,
        hard_stop_active: bool,
        context: StrategyContext,
        *,
        force_exit_rebuild: bool = False,
        pending_loss_old_signature: Any = None,
        pending_cycle_intents: list[StrategyIntent] | None = None,
    ) -> list[StrategyIntent]:
        intents: list[StrategyIntent] = []
        state = runtime_state.strategy_state
        if self._is_refill_mode_active(state):
            symbol = snapshot.symbol or self.config.symbol
            self._log_event(
                "fixed_cycle_exit_intents_blocked_refill_mode_active",
                {
                    "symbol": symbol,
                    "refill_pending": bool(state.get("refill_pending")),
                    "refill_required": bool(state.get("refill_required")),
                    "refill_in_progress": bool(state.get("refill_in_progress")),
                    "bot_state": state.get("bot_state"),
                    "force_exit_rebuild": bool(state.get("force_exit_rebuild")),
                    "exit_locked": bool(state.get("exit_locked")),
                },
            )
            return []
        completed_cycles = int(state.get("cycle_completed_count") or 0)
        pair_count = int(state.get("cycle_pair_count") or 0)
        last_refill_completed_cycle_index = int(state.get("last_refill_completed_cycle_index") or 0)
        cycles_since_last_refill = completed_cycles - last_refill_completed_cycle_index
        if (
            bool(state.get("refill_pending"))
            or bool(state.get("refill_required"))
            or state.get("bot_state") == self.STATE_REFILL_PENDING
            or cycles_since_last_refill >= 2
        ):
            _log_event(
                "fixed_cycle_long_add_blocked_refill_required",
                {
                    "cycle_completed_count": completed_cycles,
                    "cycle_pair_count": pair_count,
                    "last_refill_completed_cycle_index": last_refill_completed_cycle_index,
                    "cycles_since_last_refill": cycles_since_last_refill,
                    "refill_pending": bool(state.get("refill_pending")),
                    "refill_required": bool(state.get("refill_required")),
                    "bot_state": state.get("bot_state"),
                },
            )
            self._mark_refill_required_after_cycle_pair(
                runtime_state,
                cycle_index=max(pair_count, completed_cycles),
                trigger_purpose="build_downside_cycle_guard",
                reason="long_add_blocked_refill_required",
            )
            return []
        cycle_state = self._ensure_cycle_state(runtime_state)
        _log_event(
            "fixed_cycle_exit_intent_cycle_state_loaded",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "long_add_pending": self._get_first_leg_pending(state, cycle_state),
                "second_leg_waiting": self._get_second_leg_waiting(state, cycle_state),
                "second_leg_pending_cycle": self._get_second_leg_pending_cycle(state, cycle_state),
            },
        )
        _log_event(
            "fixed_cycle_exit_intent_build_started",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "long_qty": snapshot.long_qty,
                "short_qty": snapshot.short_qty,
                "tp_price": tp_price,
                "break_even_price": break_even_price,
                "current_cycle": current_cycle,
                "hard_stop_active": hard_stop_active,
            },
        )
        if state.get("staged_second_leg_tp_realized_net") and bool(state.get("force_exit_rebuild")):
            realized_map = state.get("staged_second_leg_tp_realized_net") or {}
            required_map = state.get("staged_second_leg_tp_required_net_total") or {}
            cycle_key = str(current_cycle)
            realized_total = float(realized_map.get(cycle_key) or 0.0)
            required_total = float(required_map.get(cycle_key) or 0.0)
            remaining_required_net = max(required_total - realized_total, 0.0) if required_total else 0.0
            long_avg = float(snapshot.long_avg or 0.0)
            exit_distance_pct_from_avg = (
                ((tp_price - long_avg) / long_avg) * 100.0 if long_avg > 0 and tp_price > 0 else 0.0
            )
            _log_event(
                "staged_second_leg_tp_exit_rebuild_pricing",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "current_cycle": current_cycle,
                    "required_net": required_total,
                    "realized_total_net": realized_total,
                    "remaining_required_net": remaining_required_net,
                    "old_exit_price": float(state.get("latest_tp_price") or 0.0),
                    "new_exit_price": tp_price,
                    "exit_distance_pct_from_avg": exit_distance_pct_from_avg,
                    "long_avg": long_avg,
                },
            )
        if snapshot.long_qty <= 0 and snapshot.short_qty <= 0:
            logger.debug(
                "fixed_cycle_exit_build_skipped_flat_snapshot %s",
                {
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                    "current_cycle": current_cycle,
                    "force_exit_rebuild": force_exit_rebuild,
                },
            )
            _log_event(
                "fixed_cycle_exit_intent_build_skipped",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "reason": "flat_snapshot",
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                    "current_cycle": current_cycle,
                },
            )
            return intents
        if state.get("block_exit_rebuild_until_pnl_ready"):
            _log_event(
                "fixed_cycle_exit_intent_build_skipped",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "reason": "block_exit_rebuild_until_pnl_ready",
                },
            )
            return intents

        if self._release_exit_lock_if_unprotected_open_position(
            snapshot,
            runtime_state,
            context,
            reason="build_exit_intents_before_exit_locked_skip",
        ):
            force_exit_rebuild = True

        logger.debug(
            "fixed_cycle_exit_lock_check",
            {
                "exit_rebuild_allowed": state.get("exit_rebuild_allowed", True),
                "force_exit_rebuild": force_exit_rebuild,
                "last_exit_signature_is_none": state.get("last_exit_signature") is None,
                "tp_price": tp_price,
                "break_even_price": break_even_price,
            },
        )
        if (
            state.get("exit_locked")
            and force_exit_rebuild
            and state.get("exit_orders_stale_after_structure_fill")
        ):
            _log_event(
                "fixed_cycle_exit_locked_bypassed_due_to_structure_fill_rebuild",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "force_exit_rebuild": force_exit_rebuild,
                    "exit_orders_stale_after_structure_fill": True,
                },
            )
        if not state.get("exit_rebuild_allowed", True) and not force_exit_rebuild:
            active_order_purposes = [getattr(order, "purpose", None) for order in snapshot.active_orders]
            context.audit.log_event(
                "fixed_cycle_exit_skip",
                strategy=self.name,
                skip_reason="exit_locked",
                long_qty=snapshot.long_qty,
                short_qty=snapshot.short_qty,
                long_exit_filled=bool(state.get("long_exit_filled")),
                short_exit_filled=bool(state.get("short_exit_filled")),
                current_cycle=int(state.get("current_effective_cycle") or 0),
                active_order_purposes=active_order_purposes,
            )
            _log_event(
                "fixed_cycle_exit_intent_build_skipped",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "reason": "exit_locked",
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                    "current_cycle": int(state.get("current_effective_cycle") or 0),
                },
            )
            return intents
        if not state.get("initial_entry_confirmed"):
            context.audit.log_event(
                "fixed_cycle_exit_skip",
                strategy=self.name,
                skip_reason="initial_entry_not_confirmed",
                initial_entry_confirmed=bool(state.get("initial_entry_confirmed")),
            )
            _log_event(
                "fixed_cycle_exit_intent_build_skipped",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "reason": "initial_entry_not_confirmed",
                    "initial_entry_confirmed": bool(state.get("initial_entry_confirmed")),
                },
            )
            return intents

        exit_allowed = (
            snapshot.long_qty > 0
            and snapshot.short_qty > 0
            and snapshot.long_avg > 0
            and snapshot.short_avg > 0
        )
        if not exit_allowed:
            context.audit.log_event(
                "fixed_cycle_exit_skip",
                strategy=self.name,
                skip_reason="exit_not_allowed",
                long_qty=snapshot.long_qty,
                short_qty=snapshot.short_qty,
                long_avg=snapshot.long_avg,
                short_avg=snapshot.short_avg,
            )
            _log_event(
                "fixed_cycle_exit_intent_build_skipped",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "reason": "exit_not_allowed",
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                    "long_avg": snapshot.long_avg,
                    "short_avg": snapshot.short_avg,
                },
            )
            return intents

        if state.get("exit_orders_stale_after_structure_fill"):
            if context.cancel_open_orders_by_purpose:
                self._register_expected_exit_order_deactivations(runtime_state)
                context.cancel_open_orders_by_purpose(self._exit_purposes())
                _log_event(
                    "fixed_cycle_stale_final_exits_cancelled_after_structure_fill",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "pending_cycle_loss_usdt": float(
                            state.get("pending_cycle_loss_usdt") or 0.0
                        ),
                        "exit_orders_stale_after_structure_fill": True,
                    },
                )

        waiting_short = self._get_second_leg_waiting(state)
        short_tp_pending_cycle = self._get_second_leg_pending_cycle(state)
        long_add_pending = self._get_first_leg_pending(state, cycle_state)
        if long_add_pending and waiting_short and short_tp_pending_cycle > 0:
            context.audit.log_event(
                "fixed_cycle_exit_skip",
                strategy=self.name,
                skip_reason="long_add_pending_short_followup",
                long_add_pending=True,
                short_tp_pending_cycle=short_tp_pending_cycle,
            )
            _log_event(
                "fixed_cycle_exit_intent_build_skipped",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "reason": "long_add_pending_short_followup",
                    "long_add_pending": True,
                    "short_tp_pending_cycle": short_tp_pending_cycle,
                },
            )
            return intents
        short_pending_purpose = (
            self._cycle_purpose("short", short_tp_pending_cycle)
            if short_tp_pending_cycle > 0
            else None
        )
        short_cycle_entry = (
            self._get_cycle_sequence_entry(runtime_state, short_tp_pending_cycle)
            if short_tp_pending_cycle > 0
            else {}
        )
        short_tp_status = self._get_second_leg_status(short_cycle_entry)
        if waiting_short and short_tp_pending_cycle > 0 and short_pending_purpose:
            short_followup_active = (
                self._short_followup_active_for_cycle(
                    short_tp_pending_cycle, runtime_state, snapshot
                )
                or self._short_followup_pending_in_intents(
                    short_tp_pending_cycle, pending_cycle_intents
                )
            )
            if not self._has_cycle_purpose_already_filled_or_processed(
                runtime_state,
                short_pending_purpose,
                {
                    "cycle_index": short_tp_pending_cycle,
                    "cycle_role": "short_reduce",
                },
            ):
                if short_followup_active:
                    _log_event(
                        "fixed_cycle_exit_rebuild_allowed_after_short_followup_active",
                        {
                            "symbol": snapshot.symbol or self.config.symbol,
                            "short_tp_pending_cycle": short_tp_pending_cycle,
                            "short_pending_purpose": short_pending_purpose,
                            "short_tp_status": short_tp_status,
                            "active_short_followup_status": short_tp_status,
                            "short_followup_considered_active": True,
                            "cycle_waiting_for_short_tp": waiting_short,
                            "reason": "short_followup_active",
                        },
                    )
                elif force_exit_rebuild:
                    _log_event(
                        "fixed_cycle_exit_rebuild_forced_with_pending_short_followup",
                        {
                            "symbol": snapshot.symbol or self.config.symbol,
                            "short_tp_pending_cycle": short_tp_pending_cycle,
                            "short_pending_purpose": short_pending_purpose,
                            "cycle_waiting_for_short_tp": waiting_short,
                            "force_exit_rebuild": force_exit_rebuild,
                            "pending_cycle_loss_usdt": float(
                                state.get("pending_cycle_loss_usdt") or 0.0
                            ),
                            "reason": "cycle_fill_requires_exit_rebuild",
                        },
                    )
                else:
                    _log_event(
                        "fixed_cycle_exit_rebuild_with_pending_short_followup",
                        {
                            "symbol": snapshot.symbol or self.config.symbol,
                            "short_tp_pending_cycle": short_tp_pending_cycle,
                            "short_pending_purpose": short_pending_purpose,
                            "cycle_waiting_for_short_tp": waiting_short,
                            "pending_cycle_loss_usdt": float(
                                state.get("pending_cycle_loss_usdt") or 0.0
                            ),
                            "reason": "maintain_exits_alongside_short_followup",
                        },
                    )
                    state["force_exit_rebuild"] = True
                    state["exit_rebuild_allowed"] = True

        open_initial_orders = [
            {
                "purpose": getattr(order, "purpose", None),
                "status": getattr(order, "status", None),
            }
            for order in snapshot.active_orders
            if getattr(order, "purpose", None) in {
                self.LONG_ENTRY_PURPOSE,
                self.SHORT_ENTRY_PURPOSE,
            }
            and getattr(order, "status", None) in {"OPEN", "PARTIAL"}
        ]
        if open_initial_orders:
            context.audit.log_event(
                "fixed_cycle_exit_skip",
                strategy=self.name,
                skip_reason="initial_entry_order_still_open",
                open_initial_orders=open_initial_orders,
            )
            _log_event(
                "fixed_cycle_exit_intent_build_skipped",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "reason": "initial_entry_order_still_open",
                    "open_initial_orders": open_initial_orders,
                },
            )
            return intents

        tp_projection = self._calculate_tp_projection(
            break_even_price, snapshot, runtime_state
        )
        effective_tp_price = tp_projection.tp_price

        current_price = snapshot.current_price
        symbol, rules, source = self._resolve_instrument_rules(runtime_state)
        tick_decimal = rules["tick_size"] if rules and rules.get("tick_size", Decimal("0")) > 0 else Decimal(
            str(self.config.price_tick_size)
        )
        tick_size = float(tick_decimal)
        final_exit_tick_offset_ticks = max(float(self.config.final_exit_tick_offset or 0.0), 0.0)
        final_exit_tick_offset_price = tick_size * final_exit_tick_offset_ticks
        long_tp_price = effective_tp_price
        short_sl_price = max(effective_tp_price - final_exit_tick_offset_price, tick_size)
        logger.debug(
            "exit_tick_size %s",
            {
                "symbol": symbol,
                "tick_size": str(tick_decimal),
                "source": source,
                "price_tick_config": self.config.price_tick_size,
            },
        )
        long_tp_valid = False
        short_sl_valid = False
        if current_price < effective_tp_price:
            if current_price > 0:
                min_short_trigger = current_price + tick_size
                min_long_trigger = current_price + (2 * tick_size)
                logger.debug(
                    "exit_trigger_clamp %s",
                    {
                        "symbol": symbol,
                        "tp_price": tp_price,
                        "min_short_trigger": min_short_trigger,
                        "min_long_trigger": min_long_trigger,
                        "current_price": current_price,
                    },
                )
                short_sl_price = max(short_sl_price, min_short_trigger)
                long_tp_price = max(
                    long_tp_price,
                    short_sl_price + final_exit_tick_offset_price,
                    min_long_trigger,
                )
                logger.debug(
                    "exit_trigger_result %s",
                    {
                        "symbol": symbol,
                        "long_tp_price": long_tp_price,
                        "short_sl_price": short_sl_price,
                        "tp_price": tp_price,
                        "current_price": current_price,
                    },
                )
        if final_exit_tick_offset_ticks <= 0:
            same_exit_price = max(long_tp_price, short_sl_price)
            long_tp_price = same_exit_price
            short_sl_price = same_exit_price
        long_exit_purpose = self._get_final_long_exit_purpose()
        short_exit_purpose = self._get_final_short_exit_purpose()
        _log_event(
            "fixed_cycle_final_exit_tick_offset_config_applied",
            {
                "base_exit_price": effective_tp_price,
                "long_tp_trigger_price": long_tp_price,
                "short_sl_trigger_price": short_sl_price,
                "price_tick_size": float(tick_size),
                "final_exit_tick_offset_ticks": final_exit_tick_offset_ticks,
                "final_exit_tick_offset_price": final_exit_tick_offset_price,
                "same_price_mode": final_exit_tick_offset_ticks <= 0,
                "long_minus_short_ticks": (
                    round((long_tp_price - short_sl_price) / tick_size)
                    if tick_size > 0
                    else None
                ),
                "long_purpose": long_exit_purpose,
                "short_purpose": short_exit_purpose,
            },
        )
        def _resolve_exit_trigger(trigger_price: float, purpose: str) -> tuple[bool, int | None]:
            trigger_direction = None
            if current_price > 0:
                trigger_direction = 1 if trigger_price > current_price else 2
            _log_event(
                "fixed_cycle_exit_order_price_guard_check",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "purpose": purpose,
                    "current_price": float(current_price or 0.0),
                    "reference_price": float(effective_tp_price or 0.0),
                    "avg_price": float(
                        snapshot.long_avg
                        if purpose == self._get_final_long_exit_purpose()
                        else snapshot.short_avg or 0.0
                    ),
                    "trigger_price": float(trigger_price or 0.0),
                    "order_type": "Market",
                    "trigger_direction": trigger_direction,
                },
            )
            if current_price <= 0:
                return True, trigger_direction
            if trigger_direction == 1:
                valid = trigger_price >= current_price + tick_size
            else:
                valid = trigger_price <= max(current_price - tick_size, tick_size)
            if not valid:
                _log_event(
                    "fixed_cycle_exit_order_price_guard_blocked",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "purpose": purpose,
                        "current_price": float(current_price or 0.0),
                    "reference_price": float(effective_tp_price or 0.0),
                    "avg_price": float(
                        snapshot.long_avg
                        if purpose == self._get_final_long_exit_purpose()
                        else snapshot.short_avg or 0.0
                    ),
                        "trigger_price": float(trigger_price or 0.0),
                        "order_type": "Market",
                        "trigger_direction": trigger_direction,
                        "reason": "trigger_not_far_enough_from_market",
                    },
                )
            return valid, trigger_direction

        long_tp_valid, long_tp_trigger_direction = _resolve_exit_trigger(
            long_tp_price, long_exit_purpose
        )
        short_sl_valid, short_sl_trigger_direction = _resolve_exit_trigger(
            short_sl_price, short_exit_purpose
        )
        final_exit_economics = self._evaluate_final_exit_economics(
            long_tp_price=long_tp_price,
            short_sl_price=short_sl_price,
            snapshot=snapshot,
            runtime_state=runtime_state,
            projection=tp_projection,
        )
        if not final_exit_economics.sufficient:
            self._defer_final_exit_insufficient_coverage(
                runtime_state,
                context,
                economics=final_exit_economics,
                tp_price=effective_tp_price,
                long_tp_price=long_tp_price,
                short_sl_price=short_sl_price,
                snapshot=snapshot,
            )
            _log_event(
                "fixed_cycle_exit_intent_build_skipped",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "reason": "insufficient_target_delta",
                    "target_delta_usdt": final_exit_economics.target_delta_usdt,
                    "expected_total_net_after_exit": (
                        final_exit_economics.expected_total_net_after_exit
                    ),
                    "min_required_total_usdt": final_exit_economics.min_required_total_usdt,
                },
            )
            return []

        signature = {
            "basket_tp_price": effective_tp_price,
            "basket_break_even_price": break_even_price,
            "long_tp_price": long_tp_price,
            "short_sl_price": short_sl_price,
            "long_qty": snapshot.long_qty,
            "short_qty": snapshot.short_qty,
            "long_avg": snapshot.long_avg,
            "short_avg": snapshot.short_avg,
            "hard_stop_active": hard_stop_active,
            "current_effective_cycle": int(state.get("current_effective_cycle") or 0),
        }
        active_final_exit_purposes, _ = self._collect_active_final_exit_purposes(snapshot, runtime_state)
        expected_final_exit_purposes = self._get_final_exit_purposes()
        has_both_final_exits = all(
            purpose in active_final_exit_purposes
            for purpose in expected_final_exit_purposes
        )
        if (
            bool(state.get("initial_structure_built"))
            and state.get("last_exit_signature") == signature
            and has_both_final_exits
            and not force_exit_rebuild
            and not exit_rebuild_allowed
        ):
            _log_event(
                "fixed_cycle_final_exit_rebuild_skipped_signature_unchanged",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "reason": reason,
                    "last_exit_signature": state.get("last_exit_signature"),
                    "new_signature": signature,
                    "active_final_exit_purposes": active_final_exit_purposes,
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                    "tp_price": tp_price,
                    "break_even_price": break_even_price,
                },
            )
            return intents
        if state.get("last_exit_signature") == signature and not force_exit_rebuild:
            context.audit.log_event(
                "fixed_cycle_exit_skip",
                strategy=self.name,
                skip_reason="exit_signature_unchanged",
                signature=signature,
            )
            _log_event(
                "fixed_cycle_exit_intent_build_skipped",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "reason": "exit_signature_unchanged",
                    "signature": signature,
                },
            )
            return intents

        duplicate_exit_blocked = self._guard_duplicate_exit_purposes(snapshot, runtime_state)
        if duplicate_exit_blocked:
            active_snapshot_purposes, active_runtime_purposes = self._collect_active_final_exit_purposes(
                snapshot, runtime_state
            )
            _log_event(
                "fixed_cycle_duplicate_exit_rebuild_blocked",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "force_exit_rebuild": force_exit_rebuild,
                    "reason": "duplicate_final_exit_purposes",
                    "active_runtime_purposes": active_runtime_purposes,
                    "active_snapshot_purposes": active_snapshot_purposes,
                },
            )
            return []

        old_signature = pending_loss_old_signature
        exit_rebuild_allowed = state.get("exit_rebuild_allowed", True)
        if (
            state.get("last_exit_rebuild_skip_signature")
            and state.get("last_exit_rebuild_skip_signature") != signature
        ):
            state["last_exit_rebuild_skip_signature"] = None
        if (
            old_signature == signature
            and not force_exit_rebuild
            and not exit_rebuild_allowed
        ):
            last_skip_sig = state.get("last_exit_rebuild_skip_signature")
            if last_skip_sig != signature:
                state["last_exit_rebuild_skip_signature"] = signature
                pending_loss = float(state.get("pending_cycle_loss_usdt") or 0.0)
                _audit_calc(
                    "exit_rebuild_skipped_duplicate_signature",
                    {
                        "signature": signature,
                        "pending_loss_exit_old_signature": old_signature,
                        "last_exit_signature": state.get("last_exit_signature"),
                        "force_exit_rebuild": force_exit_rebuild,
                        "exit_rebuild_allowed": exit_rebuild_allowed,
                        "pending_cycle_loss_usdt": pending_loss,
                    },
                )
            _log_event(
                "fixed_cycle_exit_intent_build_skipped",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "reason": "duplicate_signature_blocked",
                    "signature": signature,
                    "exit_rebuild_allowed": exit_rebuild_allowed,
                },
            )
            return []

        if context.cancel_open_orders_by_purpose:
            self._register_expected_exit_order_deactivations(runtime_state)
            context.cancel_open_orders_by_purpose(self._exit_purposes())

        cycle_idx = int(state.get("current_effective_cycle") or 0)
        metadata_base = {
            "basket_break_even_price": break_even_price,
            "basket_tp_price": effective_tp_price,
            "exit_mode": "basket_exit",
        }

        def build_metadata(purpose: str, exit_type: str) -> dict[str, Any]:
            metadata = dict(metadata_base)
            if self._should_attach_replace_open_purpose(snapshot, runtime_state, purpose):
                metadata["replace_open_purpose"] = [purpose]
            metadata["exit_type"] = exit_type
            metadata["cycle_index"] = cycle_idx
            return metadata

        if long_tp_valid:
            intents.append(
                StrategyIntent(
                    side="long",
                    qty=snapshot.long_qty,
                    purpose=long_exit_purpose,
                    order_type="Market",
                    reduce_only=True,
                    trigger_price=long_tp_price,
                    trigger_direction=long_tp_trigger_direction,
                    trigger_by="LastPrice",
                    close_on_trigger=True,
                    position_idx=1,
                    metadata=build_metadata(long_exit_purpose, "long_exit"),
                )
            )
            _audit_calc(
                "exit_order_plan_calc",
                {
                    "purpose": long_exit_purpose,
                    "side": "long",
                    "qty": snapshot.long_qty,
                    "trigger_price": long_tp_price,
                    "expected_profit_or_loss": (long_tp_price - break_even_price) * snapshot.long_qty,
                    "cycle_index": cycle_idx,
                    "cycle_role": "long_exit",
                    "break_even_price": break_even_price,
                },
            )
        else:
            context.audit.log_event(
                "fixed_cycle_exit_skip",
                strategy=self.name,
                skip_reason="long_trigger_not_far_enough_from_market",
                current_price=current_price,
                trigger_price=long_tp_price,
                tick_size=tick_size,
            )
        if short_sl_valid:
            intents.append(
                StrategyIntent(
                    side="short",
                    qty=snapshot.short_qty,
                    purpose=short_exit_purpose,
                    order_type="Market",
                    reduce_only=True,
                    trigger_price=short_sl_price,
                    trigger_direction=short_sl_trigger_direction,
                    trigger_by="LastPrice",
                    close_on_trigger=True,
                    position_idx=2,
                    metadata=build_metadata(short_exit_purpose, "short_exit"),
                )
            )
            _audit_calc(
                "exit_order_plan_calc",
                {
                    "purpose": short_exit_purpose,
                    "side": "short",
                    "qty": snapshot.short_qty,
                    "trigger_price": short_sl_price,
                    "expected_profit_or_loss": (short_sl_price - break_even_price) * snapshot.short_qty,
                    "cycle_index": cycle_idx,
                    "cycle_role": "short_exit",
                    "break_even_price": break_even_price,
                },
            )
        else:
            context.audit.log_event(
                "fixed_cycle_exit_skip",
                strategy=self.name,
                skip_reason="short_trigger_not_far_enough_from_market",
                current_price=current_price,
                trigger_price=short_sl_price,
                tick_size=tick_size,
            )

        if not intents:
            return intents

        _log_event(
            "fixed_cycle_exit_intents_built",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "purposes": [intent.purpose for intent in intents],
                "tp_price": tp_price,
                "long_qty": snapshot.long_qty,
                "short_qty": snapshot.short_qty,
                "break_even_price": break_even_price,
            },
        )

        if intents and force_exit_rebuild:
            _log_event(
                "fixed_cycle_exit_rebuild_submitted_after_cycle_fill",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "purposes": [intent.purpose for intent in intents],
                    "signature": signature,
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                    "pending_loss_exit_rebuild_reason": state.get("pending_loss_exit_rebuild_reason"),
                    "pending_loss_exit_old_signature": pending_loss_old_signature,
                },
            )

        state["exit_rebuild_allowed"] = False

        cycle_idx = int(state.get("current_effective_cycle") or 0)
        if not state.get("exit_armed_marker_emitted"):
            _emit_analyzer_event(
                logger,
                "analyzer_exit_armed",
                {
                    "symbol": self.config.symbol,
                    "strategy": self.name,
                    "cycle_index": cycle_idx,
                    "exit_mode": metadata_base["exit_mode"],
                    "exit_reason": "exit_manifest",
                    "expected_long_exit_price": long_tp_price,
                    "expected_short_exit_price": short_sl_price,
                    "long_size": snapshot.long_qty,
                    "short_size": snapshot.short_qty,
                },
            )
            state["exit_armed_marker_emitted"] = True

        state["last_exit_signature"] = signature
        context.audit.log_event(
            "fixed_cycle_exit_manifest",
            strategy=self.name,
            break_even_price=break_even_price,
            tp_price=tp_price,
            signature=signature,
            purposes=[intent.purpose for intent in intents],
            prices=[intent.price for intent in intents],
            trigger_prices=[intent.trigger_price for intent in intents],
            pending_cycle_loss_usdt=float(state.get("pending_cycle_loss_usdt") or 0.0),
            force_exit_rebuild=force_exit_rebuild,
            exit_rebuild_allowed=state.get("exit_rebuild_allowed", True),
            last_exit_signature_is_none=state.get("last_exit_signature") is None,
        )
        return intents

    def _calc_short_tp_trigger_price_from_confirmed_loss(
        self,
        *,
        short_entry_price: float,
        short_qty: float,
        confirmed_long_closed_pnl: float,
        target_profit_usdt: float,
        fee_rate: float,
    ) -> float:
        required_net_profit = abs(float(confirmed_long_closed_pnl)) + float(target_profit_usdt)
        numerator = short_entry_price - (required_net_profit / short_qty)
        denominator = 1.0 + fee_rate
        return numerator / denominator

    @staticmethod
    def _compute_short_reduce_net(
        *,
        short_entry_price: float,
        trigger_price: float,
        qty: float,
        fee_rate: float,
    ) -> float:
        if qty <= 0 or short_entry_price <= 0 or trigger_price <= 0:
            return 0.0
        return (
            (short_entry_price - trigger_price) * qty
            - (short_entry_price * qty * fee_rate)
            - (trigger_price * qty * fee_rate)
        )

    @staticmethod
    def _compute_long_reduce_net(
        *,
        long_entry_price: float,
        trigger_price: float,
        qty: float,
        fee_rate: float,
    ) -> float:
        if qty <= 0 or long_entry_price <= 0 or trigger_price <= 0:
            return 0.0
        return (
            (trigger_price - long_entry_price) * qty
            - (long_entry_price * qty * fee_rate)
            - (trigger_price * qty * fee_rate)
        )

    @staticmethod
    def _floor_normalize_trigger_price(price: float, *, price_tick_size: float) -> float:
        if price <= 0:
            return 0.0
        tick = price_tick_size if price_tick_size > 0 else 0.0001
        return math.floor((price / tick) + 1e-12) * tick

    @staticmethod
    def _ceil_normalize_trigger_price(price: float, *, price_tick_size: float) -> float:
        if price <= 0:
            return 0.0
        tick = price_tick_size if price_tick_size > 0 else 0.0001
        return math.ceil((price / tick) - 1e-12) * tick

    def _enforce_short_reduce_loss_cover_invariant(
        self,
        *,
        trigger_price: float,
        short_qty: float,
        short_entry_price: float,
        required_net: float,
        fee_rate: float,
        runtime_state: RuntimeState,
        snapshot: HedgeSnapshot,
        price_tick_size: float,
    ) -> tuple[float, float, dict[str, Any]]:
        """Ensure submitted short-reduce (trigger, qty) covers required_net after rounding."""
        eps = SHORT_REDUCE_COVER_NET_EPS
        original_short_qty = float(short_qty)
        original_trigger_price = float(trigger_price)
        tick = price_tick_size if price_tick_size > 0 else float(self.config.price_tick_size or 0.0001)
        if tick <= 0:
            tick = 0.0001
        floor_price = tick

        adjustment: dict[str, Any] = {
            "original_short_qty": original_short_qty,
            "original_trigger_price": original_trigger_price,
            "adjusted_short_qty": original_short_qty,
            "adjusted_trigger_price": original_trigger_price,
            "required_net": float(required_net),
            "expected_net_after_adjustment": self._compute_short_reduce_net(
                short_entry_price=short_entry_price,
                trigger_price=original_trigger_price,
                qty=original_short_qty,
                fee_rate=fee_rate,
            ),
            "adjusted": False,
            "reason": "",
        }

        if (
            required_net <= eps
            or original_short_qty <= 0
            or short_entry_price <= 0
            or original_trigger_price <= 0
        ):
            return original_trigger_price, original_short_qty, adjustment

        adjusted_trigger = self._floor_normalize_trigger_price(
            original_trigger_price,
            price_tick_size=tick,
        )
        adjusted_qty = original_short_qty

        def net_at(tp: float, qty: float) -> float:
            return self._compute_short_reduce_net(
                short_entry_price=short_entry_price,
                trigger_price=tp,
                qty=qty,
                fee_rate=fee_rate,
            )

        def deepen_trigger(*, max_iterations: int = 500) -> None:
            nonlocal adjusted_trigger
            iterations = 0
            while (
                net_at(adjusted_trigger, adjusted_qty) + eps < required_net
                and adjusted_trigger > floor_price + eps
                and iterations < max_iterations
            ):
                adjusted_trigger = self._floor_normalize_trigger_price(
                    adjusted_trigger - tick,
                    price_tick_size=tick,
                )
                iterations += 1

        deepen_trigger()

        if net_at(adjusted_trigger, adjusted_qty) + eps < required_net:
            per_unit_net = net_at(adjusted_trigger, 1.0)
            if per_unit_net > eps:
                _, rules, _ = self._resolve_instrument_rules(runtime_state)
                min_order_qty = float(
                    rules["min_order_qty"]
                    if rules and rules.get("min_order_qty")
                    else float(self.config.min_order_qty or 0.0)
                )
                min_notional = float(
                    rules["min_notional"]
                    if rules and rules.get("min_notional")
                    else float(self.config.min_notional_usdt or 0.0)
                )
                available_short_qty = float(snapshot.short_qty or 0.0)
                if available_short_qty <= 0:
                    available_short_qty = float(
                        runtime_state.strategy_state.get("initial_short_qty") or 0.0
                    )
                available_short_qty = self._normalize_qty(available_short_qty, runtime_state)

                desired_qty = self._normalize_qty(required_net / per_unit_net, runtime_state)
                if min_notional > 0 and adjusted_trigger > 0:
                    min_notional_qty = self._normalize_qty(
                        min_notional / adjusted_trigger,
                        runtime_state,
                    )
                    if min_notional_qty > desired_qty:
                        desired_qty = min_notional_qty
                if min_order_qty > 0 and desired_qty + 1e-12 < min_order_qty:
                    if min_order_qty <= available_short_qty + 1e-12:
                        desired_qty = min_order_qty
                    else:
                        desired_qty = adjusted_qty
                desired_qty = min(desired_qty, available_short_qty)

                if desired_qty > adjusted_qty + eps:
                    adjusted_qty = desired_qty
                    adjustment["reason"] = "short_reduce_loss_cover_qty_increased"
                    deepen_trigger()

        final_net = net_at(adjusted_trigger, adjusted_qty)
        adjustment["adjusted_short_qty"] = adjusted_qty
        adjustment["adjusted_trigger_price"] = adjusted_trigger
        adjustment["expected_net_after_adjustment"] = final_net

        if (
            abs(adjusted_trigger - original_trigger_price) > eps
            or abs(adjusted_qty - original_short_qty) > eps
        ):
            adjustment["adjusted"] = True
            if not adjustment["reason"]:
                adjustment["reason"] = "short_reduce_loss_cover_trigger_deepened"

        return adjusted_trigger, adjusted_qty, adjustment

    def _enforce_long_reduce_loss_cover_invariant(
        self,
        *,
        trigger_price: float,
        long_qty: float,
        long_entry_price: float,
        required_net: float,
        fee_rate: float,
        runtime_state: RuntimeState,
        snapshot: HedgeSnapshot,
        price_tick_size: float,
    ) -> tuple[float, float, dict[str, Any]]:
        """Ensure submitted long-reduce (trigger, qty) covers required_net after rounding."""
        eps = SHORT_REDUCE_COVER_NET_EPS
        original_long_qty = float(long_qty)
        original_trigger_price = float(trigger_price)
        tick = price_tick_size if price_tick_size > 0 else float(self.config.price_tick_size or 0.0001)
        if tick <= 0:
            tick = 0.0001

        adjustment: dict[str, Any] = {
            "original_long_qty": original_long_qty,
            "original_trigger_price": original_trigger_price,
            "adjusted_long_qty": original_long_qty,
            "adjusted_trigger_price": original_trigger_price,
            "required_net": float(required_net),
            "expected_net_after_adjustment": self._compute_long_reduce_net(
                long_entry_price=long_entry_price,
                trigger_price=original_trigger_price,
                qty=original_long_qty,
                fee_rate=fee_rate,
            ),
            "adjusted": False,
            "reason": "",
        }

        if (
            required_net <= eps
            or original_long_qty <= 0
            or long_entry_price <= 0
            or original_trigger_price <= 0
        ):
            return original_trigger_price, original_long_qty, adjustment

        adjusted_trigger = self._ceil_normalize_trigger_price(
            original_trigger_price,
            price_tick_size=tick,
        )
        adjusted_qty = original_long_qty

        def net_at(tp: float, qty: float) -> float:
            return self._compute_long_reduce_net(
                long_entry_price=long_entry_price,
                trigger_price=tp,
                qty=qty,
                fee_rate=fee_rate,
            )

        def deepen_trigger(*, max_iterations: int = 500) -> None:
            nonlocal adjusted_trigger
            iterations = 0
            while (
                net_at(adjusted_trigger, adjusted_qty) + eps < required_net
                and iterations < max_iterations
            ):
                adjusted_trigger = self._ceil_normalize_trigger_price(
                    adjusted_trigger + tick,
                    price_tick_size=tick,
                )
                iterations += 1

        deepen_trigger()

        if net_at(adjusted_trigger, adjusted_qty) + eps < required_net:
            per_unit_net = net_at(adjusted_trigger, 1.0)
            if per_unit_net > eps:
                _, rules, _ = self._resolve_instrument_rules(runtime_state)
                min_order_qty = float(
                    rules["min_order_qty"]
                    if rules and rules.get("min_order_qty")
                    else float(self.config.min_order_qty or 0.0)
                )
                min_notional = float(
                    rules["min_notional"]
                    if rules and rules.get("min_notional")
                    else float(self.config.min_notional_usdt or 0.0)
                )
                available_long_qty = float(snapshot.long_qty or 0.0)
                if available_long_qty <= 0:
                    available_long_qty = float(
                        runtime_state.strategy_state.get("initial_long_qty") or 0.0
                    )
                available_long_qty = self._normalize_qty(available_long_qty, runtime_state)

                desired_qty = self._normalize_qty(required_net / per_unit_net, runtime_state)
                if min_notional > 0 and adjusted_trigger > 0:
                    min_notional_qty = self._normalize_qty(
                        min_notional / adjusted_trigger,
                        runtime_state,
                    )
                    if min_notional_qty > desired_qty:
                        desired_qty = min_notional_qty
                if min_order_qty > 0 and desired_qty + 1e-12 < min_order_qty:
                    if min_order_qty <= available_long_qty + 1e-12:
                        desired_qty = min_order_qty
                    else:
                        desired_qty = adjusted_qty
                desired_qty = min(desired_qty, available_long_qty)

                if desired_qty > adjusted_qty + eps:
                    adjusted_qty = desired_qty
                    adjustment["reason"] = "long_reduce_loss_cover_qty_increased"
                    deepen_trigger()

        final_net = net_at(adjusted_trigger, adjusted_qty)
        adjustment["adjusted_long_qty"] = adjusted_qty
        adjustment["adjusted_trigger_price"] = adjusted_trigger
        adjustment["expected_net_after_adjustment"] = final_net

        if (
            abs(adjusted_trigger - original_trigger_price) > eps
            or abs(adjusted_qty - original_long_qty) > eps
        ):
            adjustment["adjusted"] = True
            if not adjustment["reason"]:
                adjustment["reason"] = "long_reduce_loss_cover_trigger_raised"

        return adjusted_trigger, adjusted_qty, adjustment

    def _ensure_short_reduce_split_stages_cover_loss(
        self,
        *,
        split_intents: list[StrategyIntent],
        trigger_price: float,
        short_qty: float,
        short_entry_price: float,
        required_net: float,
        fee_rate: float,
        runtime_state: RuntimeState,
        snapshot: HedgeSnapshot,
        price_tick_size: float,
        cycle_index: int,
        purpose: str,
        side: str,
        position_idx: int,
        trigger_direction: int,
        metadata: dict[str, Any] | None,
    ) -> tuple[list[StrategyIntent], float, float, dict[str, Any]]:
        """Conservative fill model: any single split stage must cover required_net alone."""
        eps = SHORT_REDUCE_COVER_NET_EPS
        original_short_qty = float(short_qty)
        original_trigger_price = float(trigger_price)
        adjustment: dict[str, Any] = {
            "original_short_qty": original_short_qty,
            "original_trigger_price": original_trigger_price,
            "required_net": float(required_net),
            "adjusted": False,
            "reason": "",
        }
        if not split_intents or required_net <= eps:
            adjustment["expected_net_after_adjustment"] = self._compute_short_reduce_net(
                short_entry_price=short_entry_price,
                trigger_price=trigger_price,
                qty=min((intent.qty for intent in split_intents), default=short_qty),
                fee_rate=fee_rate,
            )
            return split_intents, trigger_price, short_qty, adjustment

        available_short_qty = float(snapshot.short_qty or 0.0)
        if available_short_qty <= 0:
            available_short_qty = float(
                runtime_state.strategy_state.get("initial_short_qty") or 0.0
            )
        available_short_qty = self._normalize_qty(available_short_qty, runtime_state)

        adjusted_trigger = float(trigger_price)
        adjusted_qty = float(short_qty)
        stage_count = len(split_intents)

        def min_stage_net() -> tuple[float, float]:
            min_qty = min(float(intent.qty or 0.0) for intent in split_intents)
            net = self._compute_short_reduce_net(
                short_entry_price=short_entry_price,
                trigger_price=adjusted_trigger,
                qty=min_qty,
                fee_rate=fee_rate,
            )
            return min_qty, net

        min_qty, min_net = min_stage_net()
        if min_net + eps >= required_net:
            adjustment["expected_net_after_adjustment"] = min_net
            return split_intents, adjusted_trigger, adjusted_qty, adjustment

        per_unit_net = self._compute_short_reduce_net(
            short_entry_price=short_entry_price,
            trigger_price=adjusted_trigger,
            qty=1.0,
            fee_rate=fee_rate,
        )
        if per_unit_net > eps:
            needed_min_stage_qty = self._normalize_qty(
                required_net / per_unit_net,
                runtime_state,
            )
            needed_total_qty = self._normalize_qty(
                needed_min_stage_qty * float(stage_count),
                runtime_state,
            )
            if needed_total_qty > adjusted_qty:
                adjusted_qty = min(needed_total_qty, available_short_qty)

        adjusted_trigger, adjusted_qty, inner_adjustment = (
            self._enforce_short_reduce_loss_cover_invariant(
                trigger_price=adjusted_trigger,
                short_qty=adjusted_qty,
                short_entry_price=short_entry_price,
                required_net=required_net,
                fee_rate=fee_rate,
                runtime_state=runtime_state,
                snapshot=snapshot,
                price_tick_size=price_tick_size,
            )
        )

        rebuilt = self._maybe_build_normal_cycle_second_leg_split_intents(
            cycle_index=cycle_index,
            purpose=purpose,
            qty=adjusted_qty,
            trigger_price=adjusted_trigger,
            snapshot=snapshot,
            runtime_state=runtime_state,
            side=side,
            position_idx=position_idx,
            trigger_direction=trigger_direction,
            metadata=metadata,
        )
        if rebuilt:
            split_intents = rebuilt
            min_qty, min_net = min_stage_net()
            if min_net + eps < required_net and adjusted_qty < available_short_qty - eps:
                per_unit_net = self._compute_short_reduce_net(
                    short_entry_price=short_entry_price,
                    trigger_price=adjusted_trigger,
                    qty=1.0,
                    fee_rate=fee_rate,
                )
                if per_unit_net > eps:
                    needed_min_stage_qty = self._normalize_qty(
                        required_net / per_unit_net,
                        runtime_state,
                    )
                    adjusted_qty = min(
                        available_short_qty,
                        self._normalize_qty(
                            needed_min_stage_qty * float(len(split_intents)),
                            runtime_state,
                        ),
                    )
                    adjusted_trigger, adjusted_qty, inner_adjustment = (
                        self._enforce_short_reduce_loss_cover_invariant(
                            trigger_price=adjusted_trigger,
                            short_qty=adjusted_qty,
                            short_entry_price=short_entry_price,
                            required_net=required_net,
                            fee_rate=fee_rate,
                            runtime_state=runtime_state,
                            snapshot=snapshot,
                            price_tick_size=price_tick_size,
                        )
                    )
                    rebuilt = self._maybe_build_normal_cycle_second_leg_split_intents(
                        cycle_index=cycle_index,
                        purpose=purpose,
                        qty=adjusted_qty,
                        trigger_price=adjusted_trigger,
                        snapshot=snapshot,
                        runtime_state=runtime_state,
                        side=side,
                        position_idx=position_idx,
                        trigger_direction=trigger_direction,
                        metadata=metadata,
                    )
                    if rebuilt:
                        split_intents = rebuilt
                        min_qty, min_net = min_stage_net()

        adjustment["adjusted"] = (
            abs(adjusted_trigger - original_trigger_price) > eps
            or abs(adjusted_qty - original_short_qty) > eps
            or bool(inner_adjustment.get("adjusted"))
        )
        if adjustment["adjusted"]:
            adjustment["reason"] = (
                inner_adjustment.get("reason")
                or "short_reduce_loss_cover_split_min_stage_adjusted"
            )
        adjustment["adjusted_short_qty"] = adjusted_qty
        adjustment["adjusted_trigger_price"] = adjusted_trigger
        adjustment["expected_net_after_adjustment"] = min_net
        adjustment["split_min_stage_qty"] = min_qty
        adjustment["split_stage_count"] = len(split_intents)
        return split_intents, adjusted_trigger, adjusted_qty, adjustment

    def _calculate_break_even(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> tuple[float, list[CalculationTrace]]:
        state = runtime_state.strategy_state

        long_qty = snapshot.long_qty
        short_qty = snapshot.short_qty
        long_avg = snapshot.long_avg
        short_avg = snapshot.short_avg
        denominator = long_qty - short_qty
        if abs(denominator) <= 1e-9:
            base_break_even = long_avg
        else:
            base_break_even = (
                (long_avg * long_qty) - (short_avg * short_qty)
            ) / denominator
        break_even_price = base_break_even
        logger.debug(
            "fixed_cycle_break_even_inputs %s",
            {
                "long_qty": snapshot.long_qty,
                "short_qty": snapshot.short_qty,
                "long_avg": snapshot.long_avg,
                "short_avg": snapshot.short_avg,
                "current_price": snapshot.current_price,
                "realized_pnl_total": snapshot.realized_pnl_total,
                "realized_long_pnl_total": snapshot.realized_long_pnl_total,
                "realized_short_pnl_total": snapshot.realized_short_pnl_total,
                "base_break_even": base_break_even,
                "final_break_even_price": break_even_price,
                "denominator": denominator,
            },
        )

        break_even_price = self._normalize_price(
            max(break_even_price, self.config.price_tick_size), runtime_state
        )

        traces = [
            CalculationTrace(
                name="break_even_price",
                formula="(long_avg * long_qty - short_avg * short_qty) / (long_qty - short_qty)",
                inputs={
                    "long_avg": snapshot.long_avg,
                    "short_avg": snapshot.short_avg,
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                    "denominator": denominator,
                },
                result={"break_even_price": break_even_price},
                details={"base_break_even": base_break_even},
            )
        ]
        return break_even_price, traces

    def _adaptive_tp_buffer_multiplier(self, snapshot: HedgeSnapshot) -> float:
        spread_reference = max(self._pct(self.config.long_fill_distance_pct), 1e-9)
        spread_penalty = min(snapshot.spread_pct / spread_reference, 1.0)
        target_short_ratio = max(self.config.hedge_ratio_short, 1e-9)
        ratio_penalty = min(abs(snapshot.short_ratio - self.config.hedge_ratio_short) / target_short_ratio, 1.0)
        structure_penalty = max(spread_penalty, ratio_penalty)
        return 0.75 + (0.5 * structure_penalty)

    def _calculate_tp_projection(
        self,
        break_even_price: float,
        snapshot: HedgeSnapshot | None = None,
        runtime_state: RuntimeState | None = None,
    ) -> TpProjection:
        state = runtime_state.strategy_state if runtime_state else {}
        snapshot_long_avg = snapshot.long_avg if snapshot else float(state.get("long_avg") or 0.0)
        snapshot_short_avg = snapshot.short_avg if snapshot else float(state.get("short_avg") or 0.0)
        snapshot_long_qty = snapshot.long_qty if snapshot else float(state.get("open_long_qty") or 0.0)
        snapshot_short_qty = snapshot.short_qty if snapshot else float(state.get("open_short_qty") or 0.0)
        realized_long_pnl = float((runtime_state.realized_long_pnl_total if runtime_state else 0.0) or 0.0)
        realized_short_pnl = float((runtime_state.realized_short_pnl_total if runtime_state else 0.0) or 0.0)
        realized_cycle_net = realized_long_pnl + realized_short_pnl
        pending_cycle_loss_usdt = float(state.get("pending_cycle_loss_usdt") or 0.0)
        effective_pending_loss_usdt = self._get_effective_pending_cycle_loss_usdt(runtime_state)
        components = calculate_hedge_exit_price(
            long_avg=snapshot_long_avg,
            long_qty=snapshot_long_qty,
            short_avg=snapshot_short_avg,
            short_qty=snapshot_short_qty,
            tp_profit_target_pct=float(self.config.tp_profit_target_pct or 0.0),
            tp_buffer_pct=float(self.config.tp_buffer_pct or 0.0),
            realized_cycle_net=realized_cycle_net,
            pending_cycle_loss_usdt=effective_pending_loss_usdt,
        )
        fee_rate = max(float(self.config.order_fee_rate_pct or 0.0), 0.0) / 100.0
        long_notional = snapshot_long_avg * snapshot_long_qty
        short_notional = snapshot_short_avg * snapshot_short_qty
        entry_fee_usdt = fee_rate * (long_notional + short_notional)
        close_fee_denominator = components.net_qty - fee_rate * (snapshot_long_qty + snapshot_short_qty)
        fee_adjusted_exit_price = components.exit_price
        if fee_rate > 0 and abs(close_fee_denominator) > 1e-12:
            fee_adjusted_exit_price = (
                long_notional
                - short_notional
                + components.required_profit_usdt
                + entry_fee_usdt
            ) / close_fee_denominator
        tp_price = self._normalize_price(fee_adjusted_exit_price, runtime_state)
        long_profit_at_exit = (tp_price - snapshot_long_avg) * snapshot_long_qty
        short_loss_at_exit = (tp_price - snapshot_short_avg) * snapshot_short_qty
        open_hedge_net_at_exit = long_profit_at_exit - short_loss_at_exit
        close_fee_usdt = fee_rate * tp_price * (snapshot_long_qty + snapshot_short_qty)
        total_fee_adjustment_usdt = entry_fee_usdt + close_fee_usdt
        open_hedge_net_after_fees = open_hedge_net_at_exit - total_fee_adjustment_usdt
        expected_total_net_after_exit = open_hedge_net_after_fees + components.realized_cycle_net
        min_profit_target_usdt = components.target_profit_usdt + components.buffer_usdt
        required_profit_to_cover_loss = max(effective_pending_loss_usdt, 0.0)
        min_required_total_usdt = required_profit_to_cover_loss + min_profit_target_usdt
        target_delta_usdt = expected_total_net_after_exit - min_required_total_usdt
        logger.debug(
            "fixed_cycle_tp_components %s",
            {
                "break_even_price": break_even_price,
                "fee_rate": fee_rate,
                "order_fee_rate_pct": float(self.config.order_fee_rate_pct or 0.0),
                "profit_basis_usdt": components.profit_basis_usdt,
                "target_profit_usdt": components.target_profit_usdt,
                "buffer_usdt": components.buffer_usdt,
                "realized_cycle_net": components.realized_cycle_net,
                "pending_cycle_loss_usdt": components.pending_cycle_loss_usdt,
                "required_profit_usdt": components.required_profit_usdt,
                "net_qty": components.net_qty,
                "entry_fee_usdt": entry_fee_usdt,
                "close_fee_usdt": close_fee_usdt,
                "total_fee_adjustment_usdt": total_fee_adjustment_usdt,
                "fee_adjusted_exit_price": fee_adjusted_exit_price,
                "raw_exit_price_without_fees": components.exit_price,
                "long_profit_at_exit": long_profit_at_exit,
                "short_loss_at_exit": short_loss_at_exit,
                "open_hedge_net_at_exit": open_hedge_net_at_exit,
                "open_hedge_net_after_fees": open_hedge_net_after_fees,
                "expected_total_net_after_exit": expected_total_net_after_exit,
                "target_total_profit_usdt": min_profit_target_usdt,
                "required_profit_to_cover_loss": required_profit_to_cover_loss,
                "min_required_total_usdt": min_required_total_usdt,
                "target_delta_usdt": target_delta_usdt,
                "tp_price": tp_price,
            },
        )
        return TpProjection(
            tp_price=tp_price,
            target_delta_usdt=target_delta_usdt,
            expected_total_net_after_exit=expected_total_net_after_exit,
            target_total_profit_usdt=min_profit_target_usdt,
            required_profit_to_cover_loss=required_profit_to_cover_loss,
            min_profit_target_usdt=min_profit_target_usdt,
            min_required_total_usdt=min_required_total_usdt,
            components=components,
            fee_rate=fee_rate,
            entry_fee_usdt=entry_fee_usdt,
            close_fee_usdt=close_fee_usdt,
            pending_cycle_loss_usdt=effective_pending_loss_usdt,
            realized_cycle_net=realized_cycle_net,
        )

    def _calculate_tp_price(
        self,
        break_even_price: float,
        snapshot: HedgeSnapshot | None = None,
        runtime_state: RuntimeState | None = None,
    ) -> float:
        return self._calculate_tp_projection(
            break_even_price, snapshot, runtime_state
        ).tp_price

    def _final_exit_coverage_tolerance_usdt(self, projection: TpProjection) -> float:
        min_profit_target = max(float(projection.min_profit_target_usdt or 0.0), 0.0)
        return max(
            FINAL_EXIT_MIN_PROFIT_FEE_TOLERANCE_FLOOR_USDT,
            min_profit_target * FINAL_EXIT_MIN_PROFIT_FEE_TOLERANCE_PCT,
        )

    def _evaluate_final_exit_economics(
        self,
        *,
        long_tp_price: float,
        short_sl_price: float,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        projection: TpProjection,
    ) -> FinalExitEconomics:
        fee_rate = projection.fee_rate
        long_avg = float(snapshot.long_avg or 0.0)
        short_avg = float(snapshot.short_avg or 0.0)
        long_qty = float(snapshot.long_qty or 0.0)
        short_qty = float(snapshot.short_qty or 0.0)
        long_profit_at_exit = (long_tp_price - long_avg) * long_qty
        short_loss_at_exit = (short_sl_price - short_avg) * short_qty
        open_hedge_net_at_exit = long_profit_at_exit - short_loss_at_exit
        close_fee_usdt = fee_rate * (
            long_tp_price * long_qty + short_sl_price * short_qty
        )
        open_hedge_net_after_fees = (
            open_hedge_net_at_exit - projection.entry_fee_usdt - close_fee_usdt
        )
        expected_total_net_after_exit = (
            open_hedge_net_after_fees + projection.realized_cycle_net
        )
        min_required_total_usdt = projection.min_required_total_usdt
        target_delta_usdt = expected_total_net_after_exit - min_required_total_usdt
        coverage_tolerance = self._final_exit_coverage_tolerance_usdt(projection)
        return FinalExitEconomics(
            expected_total_net_after_exit=expected_total_net_after_exit,
            target_delta_usdt=target_delta_usdt,
            required_profit_to_cover_loss=projection.required_profit_to_cover_loss,
            min_profit_target_usdt=projection.min_profit_target_usdt,
            min_required_total_usdt=min_required_total_usdt,
            sufficient=target_delta_usdt >= -coverage_tolerance,
        )

    def _defer_final_exit_insufficient_coverage(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        economics: FinalExitEconomics,
        tp_price: float,
        long_tp_price: float,
        short_sl_price: float,
        snapshot: HedgeSnapshot,
    ) -> None:
        state = runtime_state.strategy_state
        state["force_exit_rebuild"] = True
        state["exit_rebuild_allowed"] = True
        if context.cancel_open_orders_by_purpose:
            self._register_expected_exit_order_deactivations(runtime_state)
            context.cancel_open_orders_by_purpose(self._exit_purposes())
        _log_event(
            "final_exit_deferred_insufficient_target_delta",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "tp_price": tp_price,
                "long_tp_price": long_tp_price,
                "short_sl_price": short_sl_price,
                "target_delta_usdt": economics.target_delta_usdt,
                "expected_total_net_after_exit": economics.expected_total_net_after_exit,
                "required_profit_to_cover_loss": economics.required_profit_to_cover_loss,
                "min_profit_target_usdt": economics.min_profit_target_usdt,
                "min_required_total_usdt": economics.min_required_total_usdt,
                "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
                "current_price": snapshot.current_price,
            },
            runtime_state=runtime_state,
        )

    def _calculate_tp_components(
        self,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState | None,
    ) -> dict[str, float]:
        reference_price = self._tp_reference_price(snapshot, runtime_state)
        loss_recovery = self._loss_recovery_price_component(snapshot, runtime_state)
        pending_cycle_loss_usdt = float(
            (runtime_state.strategy_state.get("pending_cycle_loss_usdt") if runtime_state else 0.0)
            if runtime_state
            else 0.0
        )
        effective_pending_loss_usdt = self._get_effective_pending_cycle_loss_usdt(runtime_state)
        pending_loss_price_component = 0.0
        if snapshot:
            net_qty = float(snapshot.long_qty or 0.0) - float(snapshot.short_qty or 0.0)
            if effective_pending_loss_usdt > 0 and abs(net_qty) > 1e-9:
                pending_loss_price_component = effective_pending_loss_usdt / net_qty
        goal_profit = reference_price * self._pct(self.config.tp_profit_target_pct)
        buffer = reference_price * self._pct(self.config.tp_buffer_pct)
        return {
            "reference_price": reference_price,
            "loss_recovery": loss_recovery,
            "goal_profit": goal_profit,
            "buffer": buffer,
            "pending_cycle_loss_usdt": pending_cycle_loss_usdt,
            "pending_loss_price_component": pending_loss_price_component,
        }

    def _tp_reference_price(
        self, snapshot: HedgeSnapshot | None, runtime_state: RuntimeState | None
    ) -> float:
        candidates: list[float] = []
        if runtime_state:
            entry_ref = float(runtime_state.strategy_state.get("entry_reference_price") or 0.0)
            if entry_ref > 0:
                candidates.append(entry_ref)
        if snapshot:
            if snapshot.long_avg > 0:
                candidates.append(snapshot.long_avg)
            if snapshot.current_price > 0:
                candidates.append(snapshot.current_price)
        base_price = max(candidates) if candidates else 0.0
        return max(base_price, float(self.config.price_tick_size) or 1e-9)

    def _loss_recovery_price_component(
        self, snapshot: HedgeSnapshot | None, runtime_state: RuntimeState | None
    ) -> float:
        pending_cycle_loss_usdt = float(
            (runtime_state.strategy_state.get("pending_cycle_loss_usdt") if runtime_state else 0.0)
            or 0.0
        )
        if pending_cycle_loss_usdt <= 0 or not snapshot:
            return 0.0
        net_qty = float(snapshot.long_qty or 0.0) - float(snapshot.short_qty or 0.0)
        if abs(net_qty) <= 1e-9:
            return 0.0
        return pending_cycle_loss_usdt / net_qty

    def _get_realized_long_loss_total(
        self, runtime_state: RuntimeState | None
    ) -> float:
        stored_total = float(getattr(self, "realized_long_loss_total", 0.0) or 0.0)
        if runtime_state:
            stored_total = float(runtime_state.strategy_state.get("realized_long_loss_total") or stored_total)
        return stored_total

    def _add_realized_long_loss(self, runtime_state: RuntimeState, loss_usdt: float) -> None:
        if loss_usdt <= 0:
            return
        state = runtime_state.strategy_state
        total = float(state.get("realized_long_loss_total") or 0.0) + loss_usdt
        state["realized_long_loss_total"] = total
        self.realized_long_loss_total = total

    def _seed_initial_reference_if_missing(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> None:
        state = runtime_state.strategy_state

        cycle_state = self._ensure_cycle_state(runtime_state)

        if float(state.get("entry_reference_price") or 0.0) <= 0 and snapshot.current_price > 0:
            state["entry_reference_price"] = snapshot.current_price

        if float(state.get("initial_long_qty") or 0.0) <= 0 and snapshot.long_qty > 0:
            state["initial_long_qty"] = snapshot.long_qty

        if float(state.get("initial_short_qty") or 0.0) <= 0 and snapshot.short_qty > 0:
            state["initial_short_qty"] = snapshot.short_qty

        if float(state.get("initial_total_notional_usdt") or 0.0) <= 0:
            ref_price = float(state.get("entry_reference_price") or 0.0)
            initial_long_qty = float(state.get("initial_long_qty") or 0.0)
            initial_short_qty = float(state.get("initial_short_qty") or 0.0)
            if ref_price > 0 and (initial_long_qty > 0 or initial_short_qty > 0):
                state["initial_total_notional_usdt"] = (initial_long_qty * ref_price) + (initial_short_qty * ref_price)

        if float(state.get("entry_reference_price") or 0.0) > 0 and float(cycle_state.get("entry_price") or 0.0) <= 0:
            cycle_state["entry_price"] = float(state.get("entry_reference_price") or 0.0)
            self._write_cycle_state(cycle_state)

    def _sync_state_from_snapshot(self, snapshot: HedgeSnapshot, runtime_state: RuntimeState) -> None:
        state = runtime_state.strategy_state
        state["open_long_qty"] = snapshot.long_qty
        state["open_short_qty"] = snapshot.short_qty
        state["long_avg"] = snapshot.long_avg
        state["short_avg"] = snapshot.short_avg
        state["realized_pnl_total"] = snapshot.realized_pnl_total
        state["current_effective_cycle"] = max(
            int(state.get("current_short_cycle_index") or 0),
            int(state.get("cycle_completed_count") or 0),
        )

    def _try_complete_cycle_pair_after_confirmed_pnl(
        self,
        runtime_state: RuntimeState,
        cycle_index: int,
        trigger_purpose: str | None,
    ) -> None:
        if cycle_index <= 0:
            return
        current_purpose = str(trigger_purpose or "")
        if not self._is_second_leg_purpose(current_purpose):
            _log_event(
                "fixed_cycle_second_leg_completion_blocked_non_second_leg",
                {
                    "cycle_index": cycle_index,
                    "purpose": current_purpose or None,
                    "source": "_try_complete_cycle_pair_after_confirmed_pnl",
                },
            )
            return False
        state = runtime_state.strategy_state
        processed = set(state.get("processed_cycle_purposes") or [])
        cycle_state_entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
        # Direction-neutral First-/Second-Leg-Status aus dem Cycle-Entry ableiten.
        first_leg_field = self._get_first_leg_status_field()
        first_leg_status = str(cycle_state_entry.get(first_leg_field) or "NONE").upper()
        normalized_first_leg_purpose = self._normalize_cycle_purpose(
            self._get_first_leg_purpose(cycle_index),
            {"cycle_index": cycle_index, "cycle_role": self._get_first_leg_cycle_role()},
        )
        second_leg_status = self._get_second_leg_status(cycle_state_entry)
        normalized_second_leg_purpose = self._normalize_cycle_purpose(
            self._get_second_leg_purpose(cycle_index),
            {"cycle_index": cycle_index, "cycle_role": self._get_second_leg_cycle_role()},
        )
        fill_confirmed_field = self._second_leg_fill_confirmed_field()
        fill_price_field = self._second_leg_fill_price_field()
        second_leg_fill_confirmed = bool(cycle_state_entry.get(fill_confirmed_field))
        second_leg_fill_price = float(cycle_state_entry.get(fill_price_field) or 0.0)

        staged_required_map = state.get("staged_second_leg_tp_required_net_total") or {}
        split_stage_count_map = state.get("normal_cycle_second_leg_split_stage_count") or {}
        cycle_key = str(cycle_index)
        is_staged_cycle = cycle_key in staged_required_map
        is_normal_split_cycle = cycle_key in split_stage_count_map
        second_leg_filled_flag = bool(state.get("cycle_short_tp_filled"))
        if is_staged_cycle:
            # Für gestagte Second-Leg-TPs darf die Pair-Completion nicht am globalen Flag hängen,
            # sondern ausschließlich an der pro-Cycle Staging-Logik.
            has_real_config, diag = self._has_real_staged_second_leg_config(state, cycle_index, metadata=None)
            complete = bool(diag.get("complete"))
            if not has_real_config:
                is_staged_cycle = False
            elif not complete:
                _log_event(
                    "fixed_cycle_staged_second_leg_completion_insufficient_requirements",
                    diag,
                )
                return
            else:
                second_leg_filled_flag = True
        elif is_normal_split_cycle:
            complete, _ = self._is_normal_cycle_second_leg_split_complete(state, cycle_index)
            if not complete:
                return
            second_leg_filled_flag = True
        # Direction-neutral First-/Second-Leg-Filled-Status bestimmen.
        first_leg_filled = bool(
            first_leg_status in {"FILLED", "PROCESSED"}
            or normalized_first_leg_purpose in processed
            or state.get("cycle_long_add_filled")
        )
        second_leg_filled = bool(
            second_leg_status in {"FILLED", "PROCESSED"}
            or second_leg_fill_confirmed
            or second_leg_fill_price > 0.0
            or normalized_second_leg_purpose in processed
            or second_leg_filled_flag
            or state.get("cycle_short_tp_filled")
        )
        if not (first_leg_filled and second_leg_filled):
            _log_event(
                "fixed_cycle_pair_completion_waiting_for_entry_state",
                {
                    "cycle_index": cycle_index,
                    "purpose": current_purpose or None,
                    "first_leg_field": first_leg_field,
                    "first_leg_status": first_leg_status,
                    "second_leg_status": second_leg_status,
                    "second_leg_fill_confirmed": second_leg_fill_confirmed,
                    "second_leg_fill_price": second_leg_fill_price,
                    "normalized_first_leg_purpose": normalized_first_leg_purpose,
                    "normalized_second_leg_purpose": normalized_second_leg_purpose,
                    "processed_cycle_purposes": sorted(processed),
                    "cycle_long_add_filled_flag": bool(state.get("cycle_long_add_filled")),
                    "cycle_short_tp_filled_flag": bool(state.get("cycle_short_tp_filled")),
                },
            )
            return

        cycle_state = self._ensure_cycle_state(runtime_state)
        counts_before = {
            "cycle_completed_count": int(state.get("cycle_completed_count") or 0),
            "cycle_pair_count": int(state.get("cycle_pair_count") or 0),
            "current_effective_cycle": int(state.get("current_effective_cycle") or 0),
            "current_short_cycle_index": int(state.get("current_short_cycle_index") or 0),
        }
        counts_after = {
            "cycle_completed_count": max(counts_before["cycle_completed_count"], cycle_index),
            "cycle_pair_count": max(counts_before["cycle_pair_count"], cycle_index),
            "current_effective_cycle": max(counts_before["current_effective_cycle"], cycle_index),
            "current_short_cycle_index": max(counts_before["current_short_cycle_index"], cycle_index),
        }
        followup_before = {
            "cycle_waiting_for_short_tp": self._get_second_leg_waiting(state, cycle_state),
            "short_tp_pending_cycle": self._get_second_leg_pending_cycle(state, cycle_state),
            "pending_short_cycle_index": int(state.get("pending_short_cycle_index") or 0),
            "long_add_pending": self._get_first_leg_pending(state, cycle_state),
            "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
        }
        if not self._cycle_has_confirmed_pair_pnl(runtime_state, cycle_index):
            ledger = state.get("audit_pnl_ledger") or {}
            _log_event(
                "fixed_cycle_complete_blocked_missing_confirmed_pair_pnl",
                {
                    "cycle_index": cycle_index,
                    "long_flag": state.get("cycle_long_add_filled"),
                    "short_flag": state.get("cycle_short_tp_filled"),
                    "ledger_cycle_long_reduce_keys": list((ledger.get("cycle_long_reduce_pnl") or {}).keys()),
                    "ledger_cycle_short_tp_keys": list((ledger.get("cycle_short_tp_pnl") or {}).keys()),
                    "cycle_long_reduce_entry": (ledger.get("cycle_long_reduce_pnl") or {}).get(str(cycle_index)),
                    "cycle_short_tp_entry": (ledger.get("cycle_short_tp_pnl") or {}).get(str(cycle_index)),
                },
            )
            self._force_commit_short_reduce_completion_even_if_duplicate(
                runtime_state,
                cycle_index,
                followup_before=followup_before,
                counts_before=counts_before,
                counts_after=counts_after,
                trigger_purpose=trigger_purpose,
                reason="pending_pair_pnl",
            )
            return
        _log_event(
            "fixed_cycle_second_leg_completion_allowed",
            {
                "cycle_index": cycle_index,
                "purpose": current_purpose,
                "cycle_step": state.get("cycle_step"),
                "next_required_purpose": state.get("next_required_purpose"),
                "cycle_pair_count_before": counts_before["cycle_pair_count"],
                "cycle_pair_count_after": counts_after["cycle_pair_count"],
                "cycle_completed_count_before": counts_before["cycle_completed_count"],
                "cycle_completed_count_after": counts_after["cycle_completed_count"],
            },
        )
        self._force_commit_short_reduce_completion_even_if_duplicate(
            runtime_state,
            cycle_index,
            followup_before=followup_before,
            counts_before=counts_before,
            counts_after=counts_after,
            trigger_purpose=trigger_purpose,
        )
        logger.info(
            "[CYCLE-COMPLETE] cycle_count=%s",
            state.get("cycle_completed_count"),
        )
        _log_event(
            "fixed_cycle_cycle_pair_completed_after_confirmed_pnl_retry",
            {
                "cycle_index": cycle_index,
                "trigger_purpose": trigger_purpose,
                "cycle_completed_count": state.get("cycle_completed_count"),
                "cycle_pair_count": state.get("cycle_pair_count"),
            },
        )
        if bool(state.get("refill_pending")) or bool(state.get("refill_required")):
            return
        if not self._is_second_leg_purpose(current_purpose):
            _log_event(
                "fixed_cycle_second_leg_completion_blocked_non_second_leg",
                {
                    "cycle_index": cycle_index,
                    "purpose": current_purpose or None,
                    "source": "_try_complete_cycle_pair_after_confirmed_pnl_clear_followup",
                },
            )
            return
        self._clear_cycle_followup_state_after_short_reduce(
            runtime_state, cycle_index, followup_before, counts_before, counts_after
        )

    def _apply_cycle_completion_counts(
        self,
        runtime_state: RuntimeState,
        counts_after: dict[str, int],
    ) -> None:
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        state["cycle_completed_count"] = counts_after["cycle_completed_count"]
        state["cycle_pair_count"] = counts_after["cycle_pair_count"]
        state["current_effective_cycle"] = counts_after["current_effective_cycle"]
        state["current_short_cycle_index"] = counts_after["current_short_cycle_index"]
        cycle_state["cycle_completed_count"] = state["cycle_completed_count"]
        cycle_state["cycle_pair_count"] = state["cycle_pair_count"]
        cycle_state["current_effective_cycle"] = state["current_effective_cycle"]
        cycle_state["short_cycle_index"] = max(
            int(cycle_state.get("short_cycle_index") or 0), counts_after["current_short_cycle_index"]
        )

    def _force_commit_short_reduce_completion_even_if_duplicate(
        self,
        runtime_state: RuntimeState,
        cycle_index: int,
        *,
        followup_before: dict[str, Any] | None = None,
        counts_before: dict[str, int] | None = None,
        counts_after: dict[str, int] | None = None,
        trigger_purpose: str | None = None,
        fill_event: FillEvent | None = None,
        reason: str = "confirmed",
        duplicate: bool = False,
    ) -> None:
        current_purpose = str(trigger_purpose or (fill_event.purpose if fill_event else "") or "")
        if not self._is_second_leg_purpose(current_purpose):
            _log_event(
                "fixed_cycle_second_leg_completion_blocked_non_second_leg",
                {
                    "cycle_index": cycle_index,
                    "purpose": current_purpose or None,
                    "source": "_force_commit_short_reduce_completion_even_if_duplicate",
                    "reason": reason,
                    "duplicate": duplicate,
                },
            )
            return
        state = runtime_state.strategy_state
        entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
        metadata = dict(getattr(fill_event, "metadata", {}) or {})
        normalized_second_leg_purpose = self._normalize_cycle_purpose(
            current_purpose,
            {"cycle_index": cycle_index, "cycle_role": self._get_second_leg_cycle_role()},
        )
        cycle_key = str(cycle_index)
        staged_required_map = state.get("staged_second_leg_tp_required_net_total") or {}
        split_stage_count_map = state.get("normal_cycle_second_leg_split_stage_count") or {}
        is_staged_second_leg = bool(metadata.get("is_staged_second_leg_tp")) or (
            cycle_key in staged_required_map
        )
        is_normal_split_second_leg = bool(metadata.get("normal_cycle_second_leg_split")) or (
            cycle_key in split_stage_count_map
        )
        if is_staged_second_leg:
            has_real_config, diag = self._has_real_staged_second_leg_config(state, cycle_index, metadata)
            complete = bool(diag.get("complete"))
            # Root-Fix: Ein "staged" Cycle ohne echte Stage-Konfiguration darf die
            # Completion nicht blockieren. In diesem Fall den Second-Leg wie einen
            # normalen behandeln und die Staging-Gates überspringen.
            if not has_real_config:
                is_staged_second_leg = False
            elif not complete:
                payload = {
                    **diag,
                    "purpose": current_purpose,
                    "reason": "staged_second_leg_not_complete",
                }
                _log_event(
                    "fixed_cycle_force_commit_staged_second_leg_waiting",
                    payload,
                )
                return
        elif is_normal_split_second_leg:
            complete, diag = self._is_normal_cycle_second_leg_split_complete(state, cycle_index)
            if not complete:
                _log_event(
                    "fixed_cycle_force_commit_normal_split_second_leg_waiting",
                    {
                        **diag,
                        "purpose": current_purpose,
                        "reason": "normal_split_second_leg_not_complete",
                    },
                )
                return
        previous_complete = bool(entry.get("complete"))
        previous_second_leg_status = self._get_second_leg_status(entry)
        if previous_second_leg_status != "FILLED":
            self._set_second_leg_status(entry, "FILLED")
        if not previous_complete:
            entry["complete"] = True
            _log_event(
                "fixed_cycle_cycle_marked_complete",
                {
                    "cycle_index": cycle_index,
                    "purpose": current_purpose,
                    "source": "_force_commit_short_reduce_completion_even_if_duplicate",
                },
            )
            _log_event(
                "fixed_cycle_next_cycle_unlocked",
                {
                    "completed_cycle_index": cycle_index,
                    "next_cycle_index": cycle_index + 1,
                    "source": "_force_commit_short_reduce_completion_even_if_duplicate",
                },
            )
        processed = set(state.get("processed_cycle_purposes") or [])
        if normalized_second_leg_purpose not in processed:
            processed.add(normalized_second_leg_purpose)
            state["processed_cycle_purposes"] = sorted(processed)
        if fill_event is not None:
            second_leg_fill_price = (
                self._safe_float((fill_event.metadata or {}).get("confirmed_closed_avg_price"), None)
                or self._safe_float((fill_event.metadata or {}).get("closed_avg_price"), None)
                or self._safe_float(getattr(fill_event, "exec_price", None), None)
                or self._safe_float(entry.get("long_reduce_fill_price"), None)
            )
            if (
                self._get_second_leg_cycle_role() == "long_reduce"
                and second_leg_fill_price is not None
                and second_leg_fill_price > 0
            ):
                previous_long_reduce_fill_price = self._safe_float(
                    entry.get("long_reduce_fill_price"), 0.0
                )
                entry["long_reduce_fill_price"] = float(second_leg_fill_price)
                entry["long_reduce_fill_confirmed"] = True
                _log_event(
                    "fixed_cycle_long_reduce_fill_price_state_set",
                    {
                        "symbol": self.config.symbol,
                        "cycle_index": cycle_index,
                        "purpose": normalized_second_leg_purpose,
                        "long_reduce_fill_price": float(second_leg_fill_price),
                        "source": "force_commit",
                        "previous_long_reduce_fill_price": previous_long_reduce_fill_price,
                        "long_reduce_fill_confirmed": True,
                        "long_reduce_status": entry.get("long_reduce_status"),
                    },
                )
        snapshot = runtime_state.last_snapshot
        computed_counts_before = counts_before or {
            "cycle_completed_count": int(state.get("cycle_completed_count") or 0),
            "cycle_pair_count": int(state.get("cycle_pair_count") or 0),
            "current_effective_cycle": int(state.get("current_effective_cycle") or 0),
            "current_short_cycle_index": int(state.get("current_short_cycle_index") or 0),
        }
        computed_counts_after = counts_after or {
            "cycle_completed_count": max(computed_counts_before["cycle_completed_count"], cycle_index),
            "cycle_pair_count": max(computed_counts_before["cycle_pair_count"], cycle_index),
            "current_effective_cycle": max(computed_counts_before["current_effective_cycle"], cycle_index),
            "current_short_cycle_index": max(
                computed_counts_before["current_short_cycle_index"], cycle_index
            ),
        }
        computed_followup_before = followup_before or {
            "cycle_waiting_for_short_tp": self._get_second_leg_waiting(state),
            "short_tp_pending_cycle": self._get_second_leg_pending_cycle(state),
            "pending_short_cycle_index": int(state.get("pending_short_cycle_index") or 0),
            "long_add_pending": self._get_first_leg_pending(state),
            "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
        }
        state["cycle_long_add_filled"] = False
        state["cycle_short_tp_filled"] = False
        state["long_add_rebuild_allowed"] = True
        state["force_exit_rebuild"] = True
        state["exit_rebuild_allowed"] = True
        state["exit_locked"] = False
        self._apply_cycle_completion_counts(runtime_state, computed_counts_after)
        self._clear_cycle_followup_state_after_short_reduce(
            runtime_state,
            cycle_index,
            computed_followup_before,
            computed_counts_before,
            computed_counts_after,
        )
        # Nach forced completion den Sequencer explizit anhand der jetzt vollständigen
        # processed_cycle_purposes auf den nächsten Cycle weiterschieben.
        self._recover_cycle_sequence_state(runtime_state, state)
        self._persist_cycle_sequence_state(runtime_state)
        self._mark_refill_required_after_cycle_pair(
            runtime_state,
            cycle_index=cycle_index,
            trigger_purpose=trigger_purpose,
            reason="short_reduce_completion",
        )
        self._commit_short_reduce_terminal_fill(
            runtime_state,
            cycle_index,
            fill_event=fill_event,
            source="force_commit",
        )
        if duplicate:
            symbol = (
                self._active_trade_symbol(snapshot, runtime_state, fill_event=fill_event)
                if snapshot
                else self.config.symbol
            )
            _log_event(
                "fixed_cycle_duplicate_short_reduce_completion_commit_forced",
                {
                    "symbol": symbol,
                    "cycle_index": cycle_index,
                    "trigger_purpose": trigger_purpose or (fill_event.purpose if fill_event else None),
                    "reason": reason,
                    "cycle_completed_count": computed_counts_after["cycle_completed_count"],
                    "cycle_pair_count": computed_counts_after["cycle_pair_count"],
                },
            )
            _log_event(
                "fixed_cycle_duplicate_short_reduce_followup_state_cleared",
                {
                    "symbol": symbol,
                    "cycle_index": cycle_index,
                    "cycle_waiting_for_short_tp_before": computed_followup_before["cycle_waiting_for_short_tp"],
                    "short_tp_pending_cycle_before": computed_followup_before["short_tp_pending_cycle"],
                    "pending_short_cycle_index_before": computed_followup_before["pending_short_cycle_index"],
                    "long_add_pending_before": computed_followup_before["long_add_pending"],
                    "pending_cycle_loss_usdt_before": computed_followup_before["pending_cycle_loss_usdt"],
                },
            )
            _log_event(
                "fixed_cycle_duplicate_short_reduce_next_cycle_ready",
                {
                    "symbol": symbol,
                    "cycle_index": cycle_index,
                    "next_cycle_index": cycle_index + 1,
                    "cycle_completed_count": computed_counts_after["cycle_completed_count"],
                    "cycle_pair_count": computed_counts_after["cycle_pair_count"],
                },
            )

    def _commit_short_reduce_terminal_fill(
        self,
        runtime_state: RuntimeState,
        cycle_index: int,
        *,
        fill_event: FillEvent | None = None,
        avg_price: float | None = None,
        filled_qty: float | None = None,
        source: str = "terminal_fill",
    ) -> None:
        if cycle_index <= 0:
            return
        if source == "force_commit" and fill_event is not None:
            current_purpose = str(fill_event.purpose or "")
            if not self._is_second_leg_purpose(current_purpose):
                _log_event(
                    "fixed_cycle_second_leg_completion_blocked_non_second_leg",
                    {
                        "cycle_index": cycle_index,
                        "purpose": current_purpose or None,
                        "source": "fixed_cycle_short_reduce_fill_price_state_set",
                    },
                )
                return
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
        short_fills = cycle_state.setdefault("short_fills", {})
        fill_entry = short_fills.setdefault(str(cycle_index), {})
        fill_confirmed_field = self._second_leg_fill_confirmed_field()
        fill_price_field = self._second_leg_fill_price_field()

        normalized_purpose = self._normalize_cycle_purpose(
            self._cycle_purpose("short", cycle_index),
            {"cycle_index": cycle_index, "cycle_role": "short_reduce"},
        )

        if source == "force_commit" and fill_event is None:
            existing_price = float(entry.get(fill_price_field) or 0.0)
            repaired = self._repair_vwap_fill_entry(dict(fill_entry))
            repaired_avg = float(repaired.get("avg_price") or repaired.get("price") or 0.0)
            repaired_qty = float(repaired.get("qty") or repaired.get("exec_qty") or 0.0)
            if (
                existing_price > 0
                and bool(entry.get(fill_confirmed_field))
                and repaired_avg > 0
                and abs(existing_price - repaired_avg) / repaired_avg <= 0.005
            ):
                return
            if repaired_avg > 0:
                short_fills[str(cycle_index)] = repaired
                fill_entry = repaired

        price = self._safe_float(avg_price, None)
        if price is None and fill_event is not None:
            price = self._safe_float(getattr(fill_event, "exec_price", None), None)
        if price is None:
            repaired_entry = self._repair_vwap_fill_entry(dict(fill_entry))
            price = self._safe_float(repaired_entry.get("avg_price"), None)
        price = float(price or 0.0)

        qty = self._safe_float(filled_qty, None)
        if qty is None and fill_event is not None:
            qty = self._safe_float(getattr(fill_event, "exec_qty", None), None)
        if qty is None:
            repaired_entry = self._repair_vwap_fill_entry(dict(fill_entry))
            qty = self._safe_float(repaired_entry.get("total_qty"), None)
        if qty is None:
            qty = self._safe_float(fill_entry.get("qty"), None)
        qty = float(qty or 0.0)

        previous_short_reduce_fill_price = self._safe_float(entry.get("short_reduce_fill_price"), 0.0)
        entry["short_reduce_fill_price"] = price
        entry["short_reduce_fill_confirmed"] = True
        entry["short_reduce_status"] = "FILLED"

        fill_entry["price"] = price
        fill_entry["avg_price"] = price
        fill_entry["qty"] = qty
        fill_entry["total_qty"] = qty
        fill_entry["purpose"] = normalized_purpose

        cycle_state["last_confirmed_short_fill_price"] = price
        cycle_state["last_confirmed_short_fill_cycle_index"] = cycle_index
        cycle_state["last_confirmed_short_fill_purpose"] = normalized_purpose
        state["last_confirmed_short_fill_price"] = price
        _log_event(
            "fixed_cycle_short_reduce_fill_price_state_set",
            {
                "symbol": self.config.symbol,
                "cycle_index": cycle_index,
                "purpose": normalized_purpose,
                "short_reduce_fill_price": price,
                "source": "fill_event",
                "previous_short_reduce_fill_price": previous_short_reduce_fill_price,
                "short_reduce_fill_confirmed": True,
                "short_reduce_status": entry.get("short_reduce_status"),
            },
        )

        self._persist_cycle_sequence_state(runtime_state)
        _log_event(
            "fixed_cycle_short_reduce_terminal_commit",
            {
                "symbol": self.config.symbol,
                "cycle_index": cycle_index,
                "short_reduce_fill_confirmed": True,
                "short_reduce_fill_price": price,
                "short_tp_qty": qty,
                "source": source,
            },
        )

    def _mark_refill_required_after_cycle_pair(
        self,
        runtime_state: RuntimeState,
        *,
        cycle_index: int,
        trigger_purpose: str | None = None,
        reason: str = "cycle_pair_limit_reached",
    ) -> None:
        state = runtime_state.strategy_state
        completed = int(state.get("cycle_completed_count") or 0)
        pair_count = int(state.get("cycle_pair_count") or 0)
        last_refill_completed = int(state.get("last_refill_completed_cycle_index") or 0)
        cycles_since_last_refill = completed - last_refill_completed
        _log_event(
            "fixed_cycle_cycles_since_last_refill_calculated",
            {
                "cycle_completed_count": completed,
                "cycle_pair_count": pair_count,
                "last_refill_completed_cycle_index": last_refill_completed,
                "cycles_since_last_refill": cycles_since_last_refill,
            },
        )
        if cycles_since_last_refill < 2 and not bool(state.get("refill_pending")) and not bool(state.get("refill_required")):
            return
        if completed < 2 and pair_count < 2 and cycle_index < 2:
            return
        if state.get("skip_next_cycle_refill_after_time_distance"):
            state["skip_next_cycle_refill_after_time_distance"] = False
            _log_event(
                "normal_cycle_refill_skipped_after_recovery",
                {
                    "symbol": self.config.symbol,
                    "cycle_index": cycle_index,
                    "cycle_completed_count": completed,
                    "cycle_pair_count": pair_count,
                    "last_refill_completed_cycle_index": last_refill_completed,
                    "cycles_since_last_refill": cycles_since_last_refill,
                },
            )
            _log_event(
                "fixed_cycle_cycle_refill_skipped_after_time_distance",
                {
                    "symbol": self.config.symbol,
                    "cycle_index": cycle_index,
                    "cycle_completed_count": completed,
                    "cycle_pair_count": pair_count,
                    "last_refill_completed_cycle_index": last_refill_completed,
                    "cycles_since_last_refill": cycles_since_last_refill,
                },
            )
            trade_block_id = state.get("trade_block_id")
            if trade_block_id:
                try:
                    self._append_dashboard_event_to_confirmed_history(
                        {
                            "timestamp": datetime.now(timezone.utc).isoformat(),
                            "symbol": self.config.symbol,
                            "trade_block_id": trade_block_id,
                            "purpose": "CYCLE_REFILL_SKIPPED_AFTER_TIME_DISTANCE",
                            "record_type": "event",
                            "cycle_index": cycle_index,
                            "cycle_completed_count": completed,
                            "cycle_pair_count": pair_count,
                            "last_refill_completed_cycle_index": last_refill_completed,
                            "cycles_since_last_refill": cycles_since_last_refill,
                            "closed_pnl": 0.0,
                        }
                    )
                except Exception:
                    _log_warning_event(
                        "dashboard_event_confirmed_history_write_failed",
                        {
                            "symbol": self.config.symbol,
                            "trade_block_id": trade_block_id,
                            "purpose": "CYCLE_REFILL_SKIPPED_AFTER_TIME_DISTANCE",
                        },
                    )
            return
        self._enter_refill_mode(
            state,
            reason=reason,
            cycle_index=cycle_index,
            symbol=self.config.symbol,
        )
        state["refill_in_progress"] = False
        state["cycle_block_status"] = "REFILL_REQUIRED"
        state["refill_long_filled"] = False
        state["refill_short_filled"] = False
        state["long_add_pending"] = False
        state["cycle_waiting_for_short_tp"] = False
        state["short_tp_pending_cycle"] = 0
        state["pending_short_cycle_index"] = 0
        state["long_add_rebuild_allowed"] = False
        state["refill_trigger_cycle_completed_count"] = completed
        state["refill_trigger_cycle_pair_count"] = pair_count
        state["refill_trigger_purpose"] = trigger_purpose
        state["refill_trigger_reason"] = reason
        _log_event(
            "fixed_cycle_refill_required_after_two_cycles",
            {
                "cycle_index": cycle_index,
                "cycle_completed_count": completed,
                "cycle_pair_count": pair_count,
                "refill_pending": True,
                "refill_required": True,
                "bot_state": state.get("bot_state"),
                "trigger_purpose": trigger_purpose,
                "reason": reason,
            },
        )
        _log_event(
            "fixed_cycle_refill_triggered_from_short_reduce_completion_helper",
            {
                "cycle_index": cycle_index,
                "cycle_completed_count": completed,
                "cycle_pair_count": pair_count,
                "reason": reason,
            },
        )


    def _complete_refill(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext | None,
        *,
        completion_reason: str = "reconcile",
    ) -> None:
        state = runtime_state.strategy_state
        self._clear_refill_intent_registry(state)
        cycle_state = self._ensure_cycle_state(runtime_state)
        state["refill_fills_complete"] = False
        state["refill_completion_pending_reconcile"] = False
        short_tp_fallback_state_before = state.get("short_tp_fallback_state")
        short_tp_fallback_order_context_present_before = bool(
            state.get("short_tp_fallback_order_context")
        )
        self._exit_refill_mode_after_complete_refill(
            state,
            reason="refill_completed",
            symbol=self.config.symbol,
        )
        last_cycle_completed = int(state.get("cycle_completed_count") or 0)
        last_cycle_pairs = int(state.get("cycle_pair_count") or 0)
        state["last_refill_completed_cycle_index"] = last_cycle_completed
        state["last_refill_completed_cycle_pair_count"] = last_cycle_pairs
        _log_event(
            "fixed_cycle_refill_completed_cycle_marker_updated",
            {
                "symbol": self.config.symbol,
                "last_refill_completed_cycle_index": last_cycle_completed,
                "last_refill_completed_cycle_pair_count": last_cycle_pairs,
            },
        )
        self._reset_exit_state_for_new_structure(runtime_state, "refill_completed")
        completed_cycle_index = int(
            state.get("last_refill_completed_cycle_index")
            or state.get("cycle_completed_count")
            or 0
        )
        next_cycle_index = completed_cycle_index + 1
        next_purpose = self._get_first_leg_purpose(next_cycle_index)
        state["refill_required"] = False
        state["refill_pending"] = False
        state["refill_in_progress"] = False
        state["refill_fills_complete"] = False
        state["refill_completion_pending_reconcile"] = False
        state["refill_completed"] = True
        state["long_add_pending"] = False
        state["cycle_waiting_for_short_tp"] = False
        state["short_tp_pending_cycle"] = 0
        state["long_add_rebuild_allowed"] = True
        state["force_exit_rebuild"] = True
        state["exit_rebuild_allowed"] = True
        state["active_cycle_index"] = next_cycle_index
        state["cycle_step"] = STEP_WAITING_FOR_PAIR_FIRST_LEG
        state["next_required_purpose"] = next_purpose
        cycle_sequence_state = state.get("cycle_sequence_state") or {}
        cycle_sequence_state["active_cycle_index"] = next_cycle_index
        cycle_sequence_state["cycle_step"] = STEP_WAITING_FOR_PAIR_FIRST_LEG
        cycle_sequence_state["next_required_purpose"] = next_purpose
        state["cycle_sequence_state"] = cycle_sequence_state
        cycle_state["active_cycle_index"] = next_cycle_index
        cycle_state["cycle_step"] = STEP_WAITING_FOR_PAIR_FIRST_LEG
        cycle_state["next_required_purpose"] = next_purpose
        self._persist_cycle_sequence_state(runtime_state)
        state["post_refill_structure_rebuild_required"] = True
        state["post_refill_structure_rebuild_confirmed_purposes"] = []
        next_long_cycle_number = last_cycle_completed + 1
        _log_event(
            "fixed_cycle_refill_flags_cleared",
            {
                "symbol": self.config.symbol,
                "completion_reason": completion_reason,
                "refill_pending": bool(state.get("refill_pending")),
                "refill_required": bool(state.get("refill_required")),
                "refill_in_progress": bool(state.get("refill_in_progress")),
                "refill_completion_pending_reconcile": bool(
                    state.get("refill_completion_pending_reconcile")
                ),
                "cycle_block_status": state.get("cycle_block_status"),
                "bot_state": state.get("bot_state"),
            },
        )
        _log_event(
            "fixed_cycle_post_refill_cycle_continuation_allowed",
            {
                "symbol": self.config.symbol,
                "cycle_completed_count": last_cycle_completed,
                "cycle_pair_count": last_cycle_pairs,
                "last_refill_completed_cycle_index": state.get("last_refill_completed_cycle_index"),
                "next_long_cycle_number": next_long_cycle_number,
            },
        )
        _log_event(
            "fixed_cycle_post_refill_exit_rebuild_forced",
            {
                "symbol": self.config.symbol,
                "force_exit_rebuild": bool(state.get("force_exit_rebuild")),
                "exit_rebuild_allowed": bool(state.get("exit_rebuild_allowed")),
                "exit_locked": bool(state.get("exit_locked")),
            },
        )
        _log_event(
            "fixed_cycle_post_refill_structure_rebuild_required",
            {
                "symbol": self.config.symbol,
                "active_cycle_index": state.get("active_cycle_index"),
                "next_required_purpose": state.get("next_required_purpose"),
                "last_refill_completed_cycle_index": state.get("last_refill_completed_cycle_index"),
                "cycle_completed_count": state.get("cycle_completed_count"),
                "cycle_pair_count": state.get("cycle_pair_count"),
                "refill_pending": bool(state.get("refill_pending")),
                "refill_required": bool(state.get("refill_required")),
                "refill_in_progress": bool(state.get("refill_in_progress")),
                "cycle_block_status": state.get("cycle_block_status"),
                "force_exit_rebuild": bool(state.get("force_exit_rebuild")),
                "exit_rebuild_allowed": bool(state.get("exit_rebuild_allowed")),
            },
        )
        _log_event(
            "fixed_cycle_refill_completed_after_reconcile",
            {
                "symbol": self.config.symbol,
                "completion_reason": completion_reason,
                "cycle_completed_count": state.get("cycle_completed_count"),
                "cycle_pair_count": state.get("cycle_pair_count"),
                "refill_pending": state.get("refill_pending"),
                "refill_in_progress": state.get("refill_in_progress"),
                "refill_long_filled": bool(state.get("refill_long_filled")),
                "refill_short_filled": bool(state.get("refill_short_filled")),
            },
        )
        _log_event(
            "fixed_cycle_refill_completed_entry_like_cycle_state",
            {
                "completed_cycle_index": completed_cycle_index,
                "next_cycle_index": next_cycle_index,
                "next_required_purpose": state.get("next_required_purpose"),
                "active_cycle_index": state.get("active_cycle_index"),
                "cycle_step": state.get("cycle_step"),
                "cycle_sequence_state": state.get("cycle_sequence_state"),
                "refill_completed": bool(state.get("refill_completed")),
                "long_add_rebuild_allowed": bool(
                    state.get("long_add_rebuild_allowed", True)
                ),
                "cycle_completed_count": state.get("cycle_completed_count"),
                "cycle_pair_count": state.get("cycle_pair_count"),
                "processed_cycle_purposes": list(state.get("processed_cycle_purposes") or []),
                "completed_cycle_purposes": list(state.get("completed_cycle_purposes") or []),
            },
        )
        if state.get("refill_long_filled") or state.get("refill_short_filled"):
            _log_event(
                "fixed_cycle_refill_stale_fill_flags_cleared_after_complete",
                {
                    "symbol": self.config.symbol,
                    "completion_reason": completion_reason,
                    "refill_long_filled_before_clear": bool(
                        state.get("refill_long_filled")
                    ),
                    "refill_short_filled_before_clear": bool(
                        state.get("refill_short_filled")
                    ),
                    "refill_batch_id": state.get("refill_batch_id"),
                },
            )
        state["refill_long_filled"] = False
        state["refill_short_filled"] = False

    def _maybe_complete_refill_after_reconcile(
        self,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState,
        context: StrategyContext | None,
        *,
        reason: str,
    ) -> bool:
        state = runtime_state.strategy_state
        if not state.get("refill_completion_pending_reconcile"):
            return False
        if not (state.get("refill_long_filled") and state.get("refill_short_filled")):
            if state.get("refill_fills_complete") and snapshot:
                if self._try_complete_refill_after_dust_residual(
                    snapshot,
                    runtime_state,
                    context,
                    reason=f"{reason}_dust_residual",
                ):
                    return True
            return False
        if state.get("emergency_flat_required") or state.get("full_exit_reset_in_progress"):
            return False
        if not snapshot:
            snapshot = runtime_state.last_snapshot
        if not snapshot:
            return False
        if float(snapshot.long_qty or 0.0) <= 0 or float(snapshot.short_qty or 0.0) <= 0:
            return False
        active_refill_purposes = self._collect_active_refill_order_purposes(snapshot, runtime_state)
        if active_refill_purposes:
            active_refill_client_ids = [
                getattr(order, "client_order_id", None)
                for order in runtime_state.active_orders.values()
                if (getattr(order, "purpose", "") or "").upper() in {"REFILL_LONG", "REFILL_SHORT"}
            ]
            _log_event(
                "fixed_cycle_refill_completion_blocked_by_active_refill_orders",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "active_refill_purposes": active_refill_purposes,
                    "active_refill_client_ids": active_refill_client_ids,
                    "refill_pending": bool(state.get("refill_pending")),
                    "refill_in_progress": bool(state.get("refill_in_progress")),
                    "refill_fills_complete": bool(state.get("refill_fills_complete")),
                    "refill_completion_pending_reconcile": bool(
                        state.get("refill_completion_pending_reconcile")
                    ),
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                },
            )
            return False
        _log_event(
            "fixed_cycle_refill_completion_reconcile_ready",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "refill_pending": bool(state.get("refill_pending")),
                "refill_in_progress": bool(state.get("refill_in_progress")),
                "refill_long_filled": bool(state.get("refill_long_filled")),
                "refill_short_filled": bool(state.get("refill_short_filled")),
                "refill_completion_pending_reconcile": bool(state.get("refill_completion_pending_reconcile")),
                "active_refill_purposes": active_refill_purposes,
                "long_qty": snapshot.long_qty,
                "short_qty": snapshot.short_qty,
                "reason": reason,
            },
        )
        self._complete_refill(runtime_state, context, completion_reason=reason)
        return True
    def _advance_cycle_from_fill(
        self,
        fill_event: FillEvent,
        runtime_state: RuntimeState,
        context: StrategyContext | None = None,
    ) -> None:
        purpose = fill_event.purpose or ""
        exit_purposes = {
            self.LONG_TP_EXIT_PURPOSE,
            self.LONG_TP_EXIT_RECOVERY_PURPOSE,
            self.SHORT_SL_EXIT_PURPOSE,
            self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
        }
        is_exit_fill = fill_event.status == "FILLED" and purpose in exit_purposes

        state = runtime_state.strategy_state
        fill_info = {
            "fill_purpose": fill_event.purpose,
            "confirmed_closed_pnl": None,
        }
        cycle_state = self._ensure_cycle_state(runtime_state)
        snapshot = runtime_state.last_snapshot
        order_fully_completed = fill_event.status == "FILLED"
        cycle_state["trade_active"] = True
        cycle_state["symbol"] = self._active_trade_symbol(snapshot, runtime_state, fill_event=fill_event)
        processed = set(cycle_state.get("processed_fill_ids") or [])
        fill_key = self._fill_persistence_key(fill_event)
        if fill_key in processed and not is_exit_fill:
            return

        metadata = dict(fill_event.metadata or {})
        cycle_index = int(metadata.get("cycle_index") or 0)
        is_refill_fill = purpose in {"REFILL_LONG", "REFILL_SHORT"}
        if is_refill_fill:
            refill_state = state.setdefault("refill_state", {})
            _log_event(
                "fixed_cycle_refill_order_fill_received",
                {
                    "purpose": purpose,
                    "status": fill_event.status,
                    "exec_qty": fill_event.exec_qty,
                    "exec_price": fill_event.exec_price,
                    "expected_purposes": list(refill_state.get("expected_purposes") or []),
                    "refill_long_filled": bool(state.get("refill_long_filled")),
                    "refill_short_filled": bool(state.get("refill_short_filled")),
                },
            )
            if order_fully_completed:
                refill_state[purpose] = True
                if purpose == "REFILL_LONG":
                    state["refill_long_filled"] = True
                elif purpose == "REFILL_SHORT":
                    state["refill_short_filled"] = True
                registry_entry = self._update_refill_registry_status(
                    state,
                    purpose,
                    "FILLED",
                    filled_qty=float(fill_event.exec_qty or 0.0),
                )
                if registry_entry:
                    _log_event(
                        "fixed_cycle_refill_intent_marked_filled",
                        {
                            "symbol": snapshot.symbol or self.config.symbol,
                            "purpose": purpose,
                            "refill_batch_id": registry_entry.get("refill_batch_id"),
                            "exec_price": fill_event.exec_price,
                            "filled_qty": registry_entry.get("filled_qty"),
                            "client_order_id": fill_event.client_order_id,
                            "exchange_order_id": fill_event.exchange_order_id,
                        },
                    )
                refill_trigger_reason = state.get("refill_trigger_reason")
                refill_order_source = (
                    "time_distance_refill"
                    if str(refill_trigger_reason or "").strip() == "time_distance_refill"
                    else "cycle_refill"
                )
                self._write_refill_documentation_confirmed_row(
                    fill_event,
                    snapshot,
                    runtime_state,
                    state,
                    pnl_scope="refill",
                    pnl_source="refill_fill",
                    confirmed_via="refill_fill",
                    cycle_index=cycle_index or None,
                    order_source=refill_order_source,
                    refill_batch_id=(
                        registry_entry.get("refill_batch_id")
                        if registry_entry
                        else state.get("refill_batch_id")
                    ),
                    refill_trigger_reason=refill_trigger_reason,
                )
                self._mark_exit_orders_stale_after_structure_fill(
                    runtime_state,
                    fill_event=fill_event,
                    cycle_index=cycle_index,
                    structure_segment="refill",
                )

        if state.get("refill_long_filled") and state.get("refill_short_filled"):
            if not is_refill_fill:
                _log_event(
                    "refill_completion_ignored_for_non_refill_fill",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "fill_purpose": purpose,
                        "fill_status": fill_event.status,
                        "refill_long_filled": bool(state.get("refill_long_filled")),
                        "refill_short_filled": bool(state.get("refill_short_filled")),
                        "refill_completion_pending_reconcile": bool(
                            state.get("refill_completion_pending_reconcile")
                        ),
                        "refill_batch_id": state.get("refill_batch_id"),
                    },
                )
            else:
                state["refill_fills_complete"] = True
                state["refill_completion_pending_reconcile"] = True
                state["refill_pending"] = True
                state["refill_in_progress"] = True
                _log_event(
                    "fixed_cycle_refill_fills_complete_waiting_reconcile",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "refill_pending": state.get("refill_pending"),
                        "refill_in_progress": state.get("refill_in_progress"),
                        "refill_long_filled": bool(state.get("refill_long_filled")),
                        "refill_short_filled": bool(state.get("refill_short_filled")),
                        "refill_completion_pending_reconcile": True,
                        "long_qty": getattr(snapshot, "long_qty", None),
                        "short_qty": getattr(snapshot, "short_qty", None),
                    },
                )
                _log_event(
                    "fixed_cycle_refill_completion_deferred",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "reason": "awaiting_state_reconcile",
                    },
                )
                state["refill_state"] = {}
                processed.add(fill_key)
                cycle_state["processed_fill_ids"] = list(processed)
                self._write_cycle_state(cycle_state)
                return


        if cycle_index <= 0 and not is_exit_fill:
            return
        fill_type, _ = self._classify_exit_fill_for_audit(fill_event)

        normalized_purpose = self._normalize_cycle_purpose(fill_event.purpose, metadata)
        short_reduce_purpose = self._normalize_cycle_purpose(
            self._cycle_purpose("short", cycle_index),
            {"cycle_index": cycle_index, "cycle_role": "short_reduce"},
        )
        if order_fully_completed and normalized_purpose == short_reduce_purpose:
            entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
            existing_price = float(entry.get("short_reduce_fill_price") or 0.0)
            if existing_price <= 0:
                self._commit_short_reduce_terminal_fill(
                    runtime_state,
                    cycle_index,
                    fill_event=fill_event,
                    avg_price=self._safe_float(fill_event.exec_price, None),
                    filled_qty=self._safe_float(fill_event.exec_qty, None),
                    source="fill_event",
                )
        first_leg_purpose = self._normalize_cycle_purpose(
            self._get_first_leg_purpose(cycle_index),
            {
                "cycle_index": cycle_index,
                "cycle_role": self._get_first_leg_cycle_role(),
            },
        )
        second_leg_purpose = self._normalize_cycle_purpose(
            self._get_second_leg_purpose(cycle_index),
            {
                "cycle_index": cycle_index,
                "cycle_role": self._get_second_leg_cycle_role(),
            },
        )
        _, field_name = self._extract_cycle_sequence_target(
            normalized_purpose, {"cycle_index": cycle_index, **metadata}
        )
        cycle_role = metadata.get("cycle_role") or (
            "long_reduce" if "LONG" in normalized_purpose else "short_reduce"
        )
        is_staged_second_leg = bool((metadata or {}).get("is_staged_second_leg_tp"))
        is_normal_split_second_leg = bool((metadata or {}).get("normal_cycle_second_leg_split"))
        normal_split_completed = False
        is_long_add_fill = (
            cycle_role == "long_reduce"
            and "LONG_ADD" in (fill_event.purpose or "").upper()
        )
        short_first_leg_requires_confirmed_pnl = (
            normalized_purpose == first_leg_purpose
            and self._get_first_leg_cycle_role() == "short_reduce"
            and self._get_second_leg_cycle_role() == "long_reduce"
        )
        if (
            order_fully_completed
            and is_normal_split_second_leg
            and metadata.get("cycle_role") == self._get_second_leg_cycle_role()
        ):
            cycle_key = str(
                metadata.get("split_cycle_index") or metadata.get("cycle_index") or cycle_index or 0
            )
            filled_map = state.setdefault("normal_cycle_second_leg_split_filled_stages", {})
            filled_list = list(filled_map.get(cycle_key) or [])
            split_stage_index = int(metadata.get("split_stage_index") or 0)
            if split_stage_index not in filled_list:
                filled_list.append(split_stage_index)
            filled_map[cycle_key] = filled_list
            normal_split_completed, _ = self._is_normal_cycle_second_leg_split_complete(
                state, int(cycle_key or 0)
            )
            if normal_split_completed:
                state["cycle_short_tp_filled"] = True
        if order_fully_completed:
            symbol = self._active_trade_symbol(snapshot, runtime_state, fill_event=fill_event)
            confirmed_first_leg_pnl_ready = True
            if short_first_leg_requires_confirmed_pnl:
                confirmed_first_leg_pnl_ready = self._has_confirmed_cycle_closed_pnl(
                    fill_event,
                    "cycle_short_tp",
                )
                if not confirmed_first_leg_pnl_ready and context is not None:
                    confirmed_first_leg_pnl_ready = self._refresh_short_reduce_closed_pnl(
                        fill_event=fill_event,
                        runtime_state=runtime_state,
                        context=context,
                        cycle_index=cycle_index,
                    )
                if not confirmed_first_leg_pnl_ready:
                    _log_event(
                        "fixed_cycle_long_reduce_blocked_until_confirmed_pnl",
                        {
                            "symbol": symbol or self.config.symbol,
                            "cycle_index": cycle_index,
                            "purpose": self._get_second_leg_purpose(cycle_index),
                            "first_leg_purpose": fill_event.purpose,
                            "pending_cycle_loss_usdt": float(
                                state.get("pending_cycle_loss_usdt") or 0.0
                            ),
                            "reason": "short_reduce_closed_pnl_not_confirmed",
                        },
                    )
            if not short_first_leg_requires_confirmed_pnl or confirmed_first_leg_pnl_ready:
                # WICHTIG: Für gestagte Second-Leg-Orders darf der Sequencer das Pair erst dann
                # als "completed" betrachten, wenn der gestagte Second-Leg-TP für GENAU diesen
                # Cycle aus Sicht der PnL-Logik abgeschlossen ist. Einzelne Stage-Fills dürfen
                # den active_cycle_index NICHT auf den nächsten Cycle hochschalten.
                should_advance_sequence = True
                if is_staged_second_leg and normalized_purpose == second_leg_purpose:
                    staged_required_map = state.get("staged_second_leg_tp_required_net_total") or {}
                    cycle_key = str(cycle_index)
                    total_required = float(staged_required_map.get(cycle_key) or 0.0)
                    realized_map = state.get("staged_second_leg_tp_realized_net") or {}
                    total_after = float(realized_map.get(cycle_key) or 0.0)
                    pnl_completed = total_required > 0.0 and total_after >= total_required - 1e-8
                    if not pnl_completed:
                        should_advance_sequence = False
                elif is_normal_split_second_leg and normalized_purpose == second_leg_purpose:
                    split_complete, _ = self._is_normal_cycle_second_leg_split_complete(
                        state, cycle_index
                    )
                    if not split_complete:
                        should_advance_sequence = False
                if should_advance_sequence:
                    sequence_result = advance_cycle_sequence_after_fill(
                        fill_event.purpose or "", state, self._sequence_config
                    )
                    event_type = sequence_result.get("type")
                    if event_type:
                        event_name = {
                            "step_transition": "fixed_cycle_cycle_step_transition",
                            "pair_completed": "fixed_cycle_cycle_pair_completed",
                            "unexpected_fill": "fixed_cycle_sequence_unexpected_fill_detected",
                        }.get(event_type)
                        if event_name:
                            _log_event(
                                event_name,
                                {
                                    "symbol": symbol or self.config.symbol,
                                    "category": self.config.category,
                                    **sequence_result.get("payload", {}),
                                },
                            )
        if cycle_index > 0 and field_name:
            entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
            previous_status = str(entry.get(field_name) or "NONE").upper()
            if (
                self._cycle_status_finalized(previous_status)
                and fill_key not in processed
            ):
                _log_event(
                    "fixed_cycle_stale_duplicate_cycle_fill_detected",
                    {
                        "purpose": fill_event.purpose,
                        "normalized_purpose": normalized_purpose,
                        "cycle_index": cycle_index,
                        "cycle_role": cycle_role,
                        "client_order_id": fill_event.client_order_id,
                        "exchange_order_id": fill_event.exchange_order_id,
                        "exec_id": fill_event.exec_id,
                        "previous_status": previous_status,
                    },
                )
                if normalized_purpose == second_leg_purpose:
                    counts_before_dup = {
                        "cycle_completed_count": int(state.get("cycle_completed_count") or 0),
                        "cycle_pair_count": int(state.get("cycle_pair_count") or 0),
                        "current_effective_cycle": int(state.get("current_effective_cycle") or 0),
                        "current_short_cycle_index": int(state.get("current_short_cycle_index") or 0),
                    }
                    counts_after_dup = {
                        "cycle_completed_count": max(
                            counts_before_dup["cycle_completed_count"], cycle_index
                        ),
                        "cycle_pair_count": max(
                            counts_before_dup["cycle_pair_count"], cycle_index
                        ),
                        "current_effective_cycle": max(
                            counts_before_dup["current_effective_cycle"], cycle_index
                        ),
                        "current_short_cycle_index": max(
                            counts_before_dup["current_short_cycle_index"], cycle_index
                        ),
                    }
                    followup_before_dup = {
                        "cycle_waiting_for_short_tp": self._get_second_leg_waiting(state, cycle_state),
                        "short_tp_pending_cycle": self._get_second_leg_pending_cycle(state, cycle_state),
                        "pending_short_cycle_index": int(state.get("pending_short_cycle_index") or 0),
                        "long_add_pending": self._get_first_leg_pending(state, cycle_state),
                        "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
                    }
                    self._force_commit_short_reduce_completion_even_if_duplicate(
                        runtime_state,
                        cycle_index,
                        counts_before=counts_before_dup,
                        counts_after=counts_after_dup,
                        followup_before=followup_before_dup,
                        fill_event=fill_event,
                        trigger_purpose=fill_event.purpose,
                        duplicate=True,
                        reason="duplicate_fill",
                    )
                    self._complete_cycle_entry_if_done(runtime_state, cycle_index, normalized_purpose)
                elif normalized_purpose == first_leg_purpose:
                    duplicate_fill_pnl_ready = self._has_confirmed_cycle_closed_pnl(
                        fill_event,
                        "cycle_short_tp",
                    )
                    waiting_short = self._get_second_leg_waiting(state)
                    short_pending = int(self._get_second_leg_pending_cycle(state) or 0)
                    counts_before_dup = {
                        "cycle_completed_count": int(state.get("cycle_completed_count") or 0),
                        "cycle_pair_count": int(state.get("cycle_pair_count") or 0),
                        "current_effective_cycle": int(state.get("current_effective_cycle") or 0),
                    }
                    counts_after_dup = dict(counts_before_dup)
                    next_required = state.get("next_required_purpose")
                    last_completed = state.get("last_completed_purpose")
                    if not next_required:
                        next_required = self._get_second_leg_purpose(cycle_index)
                    _log_event(
                        "fixed_cycle_duplicate_first_leg_ignored_for_pair_completion",
                        {
                            "cycle_index": cycle_index,
                            "purpose": fill_event.purpose,
                            "next_required_purpose": next_required,
                            "cycle_pair_count_before": counts_before_dup["cycle_pair_count"],
                            "cycle_pair_count_after": counts_after_dup["cycle_pair_count"],
                            "cycle_completed_count_before": counts_before_dup["cycle_completed_count"],
                            "cycle_completed_count_after": counts_after_dup["cycle_completed_count"],
                            "current_effective_cycle_before": counts_before_dup["current_effective_cycle"],
                            "current_effective_cycle_after": counts_after_dup["current_effective_cycle"],
                            "last_completed_purpose_before": last_completed,
                            "last_completed_purpose_after": normalized_purpose,
                        },
                    )
                    if (
                        short_first_leg_requires_confirmed_pnl
                        and not duplicate_fill_pnl_ready
                    ):
                        _log_event(
                            "fixed_cycle_long_reduce_blocked_until_confirmed_pnl",
                            {
                                "cycle_index": cycle_index,
                                "purpose": self._get_second_leg_purpose(cycle_index),
                                "first_leg_purpose": fill_event.purpose,
                                "pending_cycle_loss_usdt": float(
                                    state.get("pending_cycle_loss_usdt") or 0.0
                                ),
                                "reason": "duplicate_short_reduce_without_confirmed_pnl",
                            },
                        )
                    elif not waiting_short or short_pending != cycle_index:
                        self._set_second_leg_waiting_state(
                            state, cycle_state, waiting=True, cycle_index=cycle_index
                        )
                        self._set_first_leg_pending(state, cycle_state, False)
                        state["pending_short_cycle_index"] = cycle_index
                        state["cycle_long_add_filled"] = True
                        state["cycle_short_tp_filled"] = False
                        cycle_state["pending_short_cycle_index"] = cycle_index
                        _log_event(
                            "fixed_cycle_duplicate_long_reduce_fill_repaired_missing_short_followup_state",
                            {
                                "cycle_index": cycle_index,
                                "cycle_waiting_for_short_tp": True,
                                "short_tp_pending_cycle": cycle_index,
                                "pending_short_cycle_index": cycle_index,
                            },
                        )
                    state["active_cycle_index"] = cycle_index
                    state["cycle_step"] = STEP_WAITING_FOR_PAIR_SECOND_LEG
                    state["next_required_purpose"] = second_leg_purpose
                    state["last_completed_purpose"] = normalized_purpose
                    state["sequence_recovery_blocked"] = False
                    self._persist_cycle_sequence_state(runtime_state)
                if is_long_add_fill:
                    fills = cycle_state.setdefault("long_fills", {})
                    existing_long_fill = dict(fills.get(str(cycle_index)) or {})
                    incoming_long_fill = {
                        **existing_long_fill,
                        "price": fill_event.exec_price,
                        "qty": fill_event.exec_qty,
                        "exec_qty": fill_event.exec_qty,
                        "incremental_qty": fill_event.incremental_qty,
                        "cumulative_qty": fill_event.cumulative_qty,
                        "client_order_id": fill_event.client_order_id,
                        "order_id": fill_event.exchange_order_id or existing_long_fill.get("order_id"),
                        "exchange_order_id": fill_event.exchange_order_id
                        or existing_long_fill.get("exchange_order_id"),
                        "exec_id": fill_event.exec_id,
                        "purpose": fill_event.purpose,
                        "symbol": self._active_trade_symbol(snapshot, runtime_state, fill_event=fill_event),
                        "pnl_this_fill": self._safe_float(
                            (fill_event.metadata or {}).get("pnl_this_fill"),
                            self._safe_float(getattr(fill_event, "pnl_this_fill", None), None),
                        ),
                        "closed_pnl": self._safe_float(
                            (fill_event.metadata or {}).get("closed_pnl"),
                            self._safe_float(getattr(fill_event, "closed_pnl", None), None),
                        ),
                        "confirmed_closed_pnl": self._safe_float(
                            (fill_event.metadata or {}).get("confirmed_closed_pnl"),
                            None,
                        ),
                        "long_reduce_closed_pnl": self._safe_float(
                            (fill_event.metadata or {}).get("long_reduce_closed_pnl"),
                            None,
                        ),
                        "runtime_calculated_pnl": self._safe_float(
                            (fill_event.metadata or {}).get("runtime_calculated_pnl"),
                            None,
                        ),
                        "exec_pnl": self._safe_float(
                            (fill_event.metadata or {}).get("exec_pnl"),
                            self._safe_float(getattr(fill_event, "exec_pnl", None), None),
                        ),
                        "metadata": dict(fill_event.metadata or {}),
                    }
                    merged_long_fill = self._merge_long_fill_pnl_metadata(
                        existing_long_fill,
                        incoming_long_fill,
                        fill_event=fill_event,
                        cycle_index=cycle_index,
                        source="stale_duplicate_before_return",
                    )
                    fills[str(cycle_index)] = merged_long_fill

                    pnl_candidates = [
                        ("metadata_confirmed_closed_pnl", (fill_event.metadata or {}).get("confirmed_closed_pnl")),
                        ("metadata_pnl_this_fill", (fill_event.metadata or {}).get("pnl_this_fill")),
                        ("metadata_closed_pnl", (fill_event.metadata or {}).get("closed_pnl")),
                        ("metadata_runtime_calculated_pnl", (fill_event.metadata or {}).get("runtime_calculated_pnl")),
                        ("metadata_exec_pnl", (fill_event.metadata or {}).get("exec_pnl")),
                        ("fill_event_closed_pnl", getattr(fill_event, "closed_pnl", None)),
                        ("fill_event_exec_pnl", getattr(fill_event, "exec_pnl", None)),
                        ("long_fill_confirmed_closed_pnl", merged_long_fill.get("confirmed_closed_pnl")),
                        ("long_fill_closed_pnl", merged_long_fill.get("closed_pnl")),
                    ]
                    selected_pnl_value = None
                    selected_pnl_source = None
                    for candidate_source, candidate_value in pnl_candidates:
                        parsed_value = self._safe_float(candidate_value, None)
                        if parsed_value is None:
                            continue
                        selected_pnl_value = float(parsed_value)
                        selected_pnl_source = candidate_source
                        break
                    if selected_pnl_value is not None:
                        cycle_entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
                        cycle_entry["long_add_confirmed_pnl"] = float(selected_pnl_value)
                        cycle_entry["long_reduce_closed_pnl"] = float(selected_pnl_value)
                        cycle_entry["long_add_loss_usdt"] = (
                            float(abs(selected_pnl_value)) if selected_pnl_value < 0 else 0.0
                        )
                        cycle_entry["short_followup_pnl_source"] = selected_pnl_source
                        self._persist_cycle_sequence_state(runtime_state)
                        _log_event(
                            "fixed_cycle_long_fill_pnl_metadata_merged",
                            {
                                "cycle_index": cycle_index,
                                "purpose": fill_event.purpose,
                                "pnl_value": selected_pnl_value,
                                "pnl_source": selected_pnl_source,
                                "branch": "stale_duplicate_before_return",
                                "long_add_loss_usdt": cycle_entry["long_add_loss_usdt"],
                                "fill_key": fill_key,
                                "order_id": fill_event.exchange_order_id,
                            },
                        )
                processed.add(fill_key)
                cycle_state["processed_fill_ids"] = list(processed)
                self._write_cycle_state(cycle_state)
                return

        if order_fully_completed:
            self._mark_cycle_purpose_status(
                runtime_state,
                purpose=fill_event.purpose,
                metadata=fill_event.metadata,
                status=fill_event.status,
            )

        if "_LONG_" in fill_event.purpose and normalized_purpose == first_leg_purpose:
            self._set_first_leg_pending(
                state, cycle_state, fill_event.status != "FILLED"
            )
            state["cycle_long_add_filled"] = True
            logger.info(
                "[CYCLE-LONG] purpose=%s status=%s long_flag=%s cycle_count=%s",
                fill_event.purpose,
                fill_event.status,
                state.get("cycle_long_add_filled"),
                state.get("cycle_completed_count"),
            )
            if order_fully_completed:
                state["exit_rebuild_allowed"] = True
                state["long_add_rebuild_allowed"] = True
                self._mark_exit_orders_stale_after_structure_fill(
                    runtime_state,
                    fill_event=fill_event,
                    cycle_index=cycle_index,
                    structure_segment="cycle_long_add",
                )
        if "_LONG_" in fill_event.purpose:
            state["current_long_cycle_index"] = max(int(state.get("current_long_cycle_index") or 0), cycle_index)
            if (
                normalized_purpose == first_leg_purpose
                and order_fully_completed
                and cycle_index > 0
            ):
                self._set_second_leg_waiting_state(
                    state, cycle_state, waiting=True, cycle_index=cycle_index
                )
                state["pending_long_cycle_index"] = cycle_index
                state["pending_short_cycle_index"] = cycle_index
                _log_event(
                    "fixed_cycle_long_reduce_fill_sets_short_followup_pending",
                    {
                        "cycle_index": cycle_index,
                        "cycle_waiting_for_short_tp": True,
                        "short_tp_pending_cycle": cycle_index,
                        "pending_short_cycle_index": cycle_index,
                    },
                )

        state["current_effective_cycle"] = max(
            int(state.get("current_short_cycle_index") or 0),
            int(state.get("cycle_completed_count") or 0),
        )

        if "_LONG_" in fill_event.purpose:
            fills = cycle_state.setdefault("long_fills", {})
            entry = dict(fills.get(str(cycle_index)) or {})
            total_qty = float(entry.get("total_qty") or 0.0) + float(fill_event.exec_qty or 0.0)
            weighted_price_sum = float(entry.get("weighted_price_sum") or 0.0) + (
                float(fill_event.exec_price or 0.0) * float(fill_event.exec_qty or 0.0)
            )
            avg_price = weighted_price_sum / total_qty if total_qty > 0 else 0.0
            exec_pnl_increment = self._safe_float((fill_event.metadata or {}).get("exec_pnl"), None)
            runtime_pnl_increment = self._safe_float(
                (fill_event.metadata or {}).get("runtime_calculated_pnl"), None
            )
            incoming_long_fill = {
                **entry,
                "price": fill_event.exec_price,
                "qty": fill_event.exec_qty,
                "exec_qty": fill_event.exec_qty,
                "incremental_qty": fill_event.incremental_qty,
                "cumulative_qty": fill_event.cumulative_qty,
                "runtime_filled_qty": self._safe_float(
                    (fill_event.metadata or {}).get("runtime_filled_qty"), None
                ),
                "total_qty": total_qty,
                "weighted_price_sum": weighted_price_sum,
                "avg_price": avg_price,
                "client_order_id": fill_event.client_order_id,
                "order_id": fill_event.exchange_order_id or entry.get("order_id"),
                "exchange_order_id": fill_event.exchange_order_id or entry.get("exchange_order_id"),
                "exec_id": fill_event.exec_id,
                "purpose": fill_event.purpose,
                "symbol": self._active_trade_symbol(snapshot, runtime_state, fill_event=fill_event),
                "confirmed_pnl_applied": bool(entry.get("confirmed_pnl_applied", False)),
                "provisional_exec_pnl_total": float(entry.get("provisional_exec_pnl_total") or 0.0)
                + (float(exec_pnl_increment) if exec_pnl_increment is not None else 0.0),
                "provisional_runtime_pnl_total": float(
                    entry.get("provisional_runtime_pnl_total") or 0.0
                )
                + (float(runtime_pnl_increment) if runtime_pnl_increment is not None else 0.0),
            }
            long_fill = self._merge_long_fill_pnl_metadata(
                entry,
                incoming_long_fill,
                fill_event=fill_event,
                cycle_index=cycle_index,
                source="advance_cycle_from_fill",
            )
            fills[str(cycle_index)] = long_fill
            self._seed_long_fill_closed_pnl_fields(long_fill, fill_event.exchange_order_id)
            long_fill_metadata = dict(fill_event.metadata or {})
            fill_closed_pnl = self._safe_float(getattr(fill_event, "closed_pnl", None), None)
            metadata_closed_pnl = self._safe_float(long_fill_metadata.get("closed_pnl"), None)
            metadata_confirmed_closed_pnl = self._safe_float(
                long_fill_metadata.get("confirmed_closed_pnl"), None
            )
            metadata_long_reduce_closed_pnl = self._safe_float(
                long_fill_metadata.get("long_reduce_closed_pnl"), None
            )
            fill_pnl_this_fill = self._safe_float(getattr(fill_event, "pnl_this_fill", None), None)

            if fill_pnl_this_fill is not None:
                long_fill["pnl_this_fill"] = fill_pnl_this_fill
            if long_fill.get("closed_pnl") is None and (
                fill_closed_pnl is not None or metadata_closed_pnl is not None
            ):
                long_fill["closed_pnl"] = (
                    fill_closed_pnl if fill_closed_pnl is not None else metadata_closed_pnl
                )
            if long_fill.get("confirmed_closed_pnl") is None and metadata_confirmed_closed_pnl is not None:
                long_fill["confirmed_closed_pnl"] = metadata_confirmed_closed_pnl
            if (
                fill_event.status == "FILLED"
                and "LONG_REDUCE" in (fill_event.purpose or "").upper()
            ):
                long_reduce_fill_price = (
                    self._safe_float(long_fill.get("confirmed_closed_avg_price"), None)
                    or self._safe_float(long_fill.get("avg_price"), None)
                    or self._safe_float(long_fill.get("price"), None)
                    or self._safe_float(fill_event.exec_price, None)
                )
                if long_reduce_fill_price is not None and long_reduce_fill_price > 0:
                    cycle_entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
                    cycle_entry["long_reduce_fill_price"] = float(long_reduce_fill_price)
                    cycle_entry["long_reduce_fill_confirmed"] = True
                    self._persist_cycle_sequence_state(runtime_state)
            if (
                long_fill.get("long_reduce_closed_pnl") is None
                and metadata_long_reduce_closed_pnl is not None
            ):
                long_fill["long_reduce_closed_pnl"] = metadata_long_reduce_closed_pnl
            if (
                long_fill.get("runtime_calculated_pnl") is None
                and long_fill_metadata.get("runtime_calculated_pnl") is not None
            ):
                long_fill["runtime_calculated_pnl"] = long_fill_metadata.get(
                    "runtime_calculated_pnl"
                )
            if long_fill.get("exec_pnl") is None and long_fill_metadata.get("exec_pnl") is not None:
                long_fill["exec_pnl"] = long_fill_metadata.get("exec_pnl")
            if long_fill_metadata:
                long_fill["metadata"] = dict(long_fill.get("metadata") or {}) | long_fill_metadata

            persisted_confirmed_closed_pnl = self._safe_float(
                long_fill.get("confirmed_closed_pnl"), None
            )
            persisted_long_reduce_closed_pnl = self._safe_float(
                long_fill.get("long_reduce_closed_pnl"), None
            )
            if (
                long_fill.get("closed_pnl_ready") is not True
                and (
                    persisted_confirmed_closed_pnl is not None
                    or persisted_long_reduce_closed_pnl is not None
                    or self._safe_float(long_fill.get("closed_pnl"), None) is not None
                )
            ):
                long_fill["closed_pnl_ready"] = True

            persisted_loss_source = (
                persisted_confirmed_closed_pnl
                if persisted_confirmed_closed_pnl is not None
                else persisted_long_reduce_closed_pnl
            )
            if persisted_loss_source is not None and float(persisted_loss_source) < 0:
                cycle_entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
                long_add_loss_usdt = abs(float(persisted_loss_source))
                if cycle_entry.get("long_add_confirmed_pnl") is None:
                    cycle_entry["long_add_confirmed_pnl"] = persisted_loss_source
                if cycle_entry.get("long_reduce_closed_pnl") is None:
                    cycle_entry["long_reduce_closed_pnl"] = persisted_loss_source
                cycle_entry["long_add_loss_usdt"] = long_add_loss_usdt
                if not cycle_entry.get("short_followup_pnl_source"):
                    cycle_entry["short_followup_pnl_source"] = "confirmed_closed_pnl"
                state["pending_cycle_loss_usdt"] = long_add_loss_usdt
                state["pending_short_cycle_index"] = cycle_index
                state["cycle_long_add_filled"] = True
                state["cycle_short_tp_filled"] = False
                cycle_state["pending_cycle_loss_usdt"] = long_add_loss_usdt
                cycle_state["pending_short_cycle_index"] = cycle_index
                self._persist_cycle_sequence_state(runtime_state)

            _log_event(
                "fixed_cycle_long_fill_pnl_metadata_persisted",
                {
                    "cycle_index": cycle_index,
                    "purpose": fill_event.purpose,
                    "exchange_order_id": fill_event.exchange_order_id,
                    "pnl_this_fill": long_fill.get("pnl_this_fill"),
                    "confirmed_closed_pnl": long_fill.get("confirmed_closed_pnl"),
                    "long_reduce_closed_pnl": long_fill.get("long_reduce_closed_pnl"),
                    "closed_pnl": long_fill.get("closed_pnl"),
                    "runtime_calculated_pnl": long_fill.get("runtime_calculated_pnl"),
                    "exec_pnl": long_fill.get("exec_pnl"),
                    "long_add_loss_usdt": (
                        abs(float(persisted_loss_source))
                        if persisted_loss_source is not None and float(persisted_loss_source) < 0
                        else float(
                            self._safe_float(
                                self._get_cycle_sequence_entry(runtime_state, cycle_index).get(
                                    "long_add_loss_usdt"
                                ),
                                0.0,
                            )
                            or 0.0
                        )
                    ),
                },
            )
            long_fill = self._merge_long_fill_pnl_metadata(
                fills.get(str(cycle_index)) or {},
                long_fill,
                fill_event=fill_event,
                cycle_index=cycle_index,
                source="advance_cycle_from_fill",
            )
            fills[str(cycle_index)] = long_fill
            cycle_state["last_cycle_reference_price"] = avg_price
            if order_fully_completed:
                long_index = int(state.get("current_long_cycle_index") or 0)
                cycle_state["long_cycle_index"] = max(long_index, cycle_index)
                self._set_second_leg_waiting_state(
                    state, cycle_state, waiting=True, cycle_index=cycle_index
                )
                cycle_state["pending_long_cycle_index"] = cycle_index
                if context is not None:
                    self._refresh_long_fill_closed_pnl(
                        cycle_index=cycle_index,
                        long_fill=long_fill,
                        runtime_state=runtime_state,
                        context=context,
                        occurred_at_ms=int(fill_event.occurred_at.timestamp() * 1000),
                        exec_id=fill_event.exec_id,
                        fill_event=fill_event,
                    )
                    if long_fill.get("confirmed_closed_pnl") is not None:
                        self._cleanup_order_pnl(runtime_state, long_fill.get("client_order_id"))
            confirmed_closed_pnl = long_fill.get("confirmed_closed_pnl")
            if confirmed_closed_pnl is not None:
                metadata = dict(fill_event.metadata or {})
                metadata["long_reduce_closed_pnl"] = confirmed_closed_pnl
                metadata["long_closed_pnl"] = confirmed_closed_pnl
                metadata["closed_pnl"] = confirmed_closed_pnl
                metadata["confirmed_closed_pnl"] = confirmed_closed_pnl
                fill_event.metadata = metadata
                fill_event.confirmed_pnl = confirmed_closed_pnl
                long_add_loss_usdt = max(-float(confirmed_closed_pnl), 0.0)
                long_fill["long_reduce_closed_pnl"] = confirmed_closed_pnl
                long_fill["last_long_add_loss_usdt"] = long_add_loss_usdt
                cycle_entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
                cycle_entry["long_add_confirmed_pnl"] = confirmed_closed_pnl
                cycle_entry["long_reduce_closed_pnl"] = confirmed_closed_pnl
                cycle_entry["long_add_loss_usdt"] = long_add_loss_usdt
                cycle_entry["short_followup_pnl_source"] = "confirmed_closed_pnl"
                self._persist_cycle_sequence_state(runtime_state)
                self._add_realized_long_loss(runtime_state, long_add_loss_usdt)
                _audit_calc(
                    "long_fill_loss_calc",
                    {
                        "purpose": fill_event.purpose,
                        "cycle_index": cycle_index,
                        "confirmed_closed_pnl": confirmed_closed_pnl,
                        "derived_long_loss_usdt": long_add_loss_usdt,
                        "qty": fill_event.exec_qty,
                        "exec_price": fill_event.exec_price,
                    },
                )
                fill_info["confirmed_closed_pnl"] = confirmed_closed_pnl
            if float(cycle_state.get("entry_price") or 0.0) <= 0:
                cycle_state["entry_price"] = fill_event.exec_price

        if "_SHORT_" in fill_event.purpose:
            if "SHORT_TP" in fill_event.purpose or "SHORT_REDUCE" in fill_event.purpose:
                if not (
                    is_normal_split_second_leg
                    and normalized_purpose == second_leg_purpose
                    and not normal_split_completed
                ):
                    state["cycle_short_tp_filled"] = True
                logger.info(
                    "[CYCLE-SHORT] purpose=%s status=%s short_flag=%s cycle_count=%s",
                    fill_event.purpose,
                    fill_event.status,
                    state.get("cycle_short_tp_filled"),
                    state.get("cycle_completed_count"),
                )
            fills = cycle_state.setdefault("short_fills", {})
            entry = dict(fills.get(str(cycle_index)) or {})
            sequence_entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
            fill_confirmed_field = self._second_leg_fill_confirmed_field()
            fill_price_field = self._second_leg_fill_price_field()
            terminal_second_leg_committed = (
                order_fully_completed
                and normalized_purpose == second_leg_purpose
                and bool(sequence_entry.get(fill_confirmed_field))
                and float(sequence_entry.get(fill_price_field) or 0.0) > 0
            )
            if terminal_second_leg_committed:
                committed_price = float(sequence_entry.get(fill_price_field) or 0.0)
                fill_qty = self._safe_float(fill_event.exec_qty, 0.0) or float(entry.get("qty") or 0.0)
                if float(entry.get("total_qty") or 0.0) > fill_qty * 1.001:
                    entry = self._repair_vwap_fill_entry(entry)
                if float(entry.get("avg_price") or 0.0) <= 0:
                    entry = {
                        **entry,
                        "price": committed_price,
                        "qty": fill_qty,
                        "total_qty": fill_qty,
                        "weighted_price_sum": committed_price * fill_qty,
                        "avg_price": committed_price,
                    }
                avg_price = float(entry.get("avg_price") or committed_price)
                fills[str(cycle_index)] = entry
            else:
                total_qty = float(entry.get("total_qty") or 0.0) + float(fill_event.exec_qty or 0.0)
                weighted_price_sum = float(entry.get("weighted_price_sum") or 0.0) + (
                    float(fill_event.exec_price or 0.0) * float(fill_event.exec_qty or 0.0)
                )
                avg_price = weighted_price_sum / total_qty if total_qty > 0 else 0.0
                fills[str(cycle_index)] = {
                    "price": fill_event.exec_price,
                    "qty": fill_event.exec_qty,
                    "total_qty": total_qty,
                    "weighted_price_sum": weighted_price_sum,
                    "avg_price": avg_price,
                }
            cycle_state["last_cycle_reference_price"] = avg_price
            if order_fully_completed:
                state["current_short_cycle_index"] = max(int(state.get("current_short_cycle_index") or 0), cycle_index)
                short_index = int(state.get("current_short_cycle_index") or 0)
                cycle_state["short_cycle_index"] = max(short_index, cycle_index)
            if float(cycle_state.get("entry_price") or 0.0) <= 0:
                cycle_state["entry_price"] = fill_event.exec_price
            if order_fully_completed and normalized_purpose == first_leg_purpose:
                if short_first_leg_requires_confirmed_pnl and not self._has_confirmed_cycle_closed_pnl(
                    fill_event,
                    "cycle_short_tp",
                ):
                    _log_event(
                        "fixed_cycle_long_reduce_blocked_until_confirmed_pnl",
                        {
                            "cycle_index": cycle_index,
                            "purpose": self._get_second_leg_purpose(cycle_index),
                            "first_leg_purpose": fill_event.purpose,
                            "pending_cycle_loss_usdt": float(
                                state.get("pending_cycle_loss_usdt") or 0.0
                            ),
                            "reason": "first_leg_fill_processed_waiting_for_confirmed_pnl",
                        },
                    )
                else:
                    self._set_second_leg_waiting_state(
                        state, cycle_state, waiting=True, cycle_index=cycle_index
                    )
                    self._set_first_leg_pending(state, cycle_state, False)
                    state["pending_short_cycle_index"] = cycle_index
                    cycle_state["pending_short_cycle_index"] = cycle_index
                    state["cycle_long_add_filled"] = True
                    state["cycle_short_tp_filled"] = False
            logger.info(
                "[CYCLE-CHECK] long_flag=%s short_flag=%s",
                state.get("cycle_long_add_filled"),
                state.get("cycle_short_tp_filled"),
            )
            self._try_complete_cycle_pair_after_confirmed_pnl(
                runtime_state, cycle_index, fill_event.purpose
            )
        if fill_event.purpose in {
            self.LONG_TP_EXIT_PURPOSE,
            self.LONG_TP_EXIT_RECOVERY_PURPOSE,
        } and order_fully_completed:
            state["long_exit_filled"] = True
            self._maybe_finalize_exit_after_leg_fill(runtime_state, context, fill_event.purpose)
        if (
            fill_event.purpose == self.SHORT_TP_EXIT_PURPOSE
            and order_fully_completed
        ):
            state["short_exit_filled"] = True
            self._maybe_finalize_exit_after_leg_fill(runtime_state, context, "SHORT_TP_EXIT")
            state["exit_rebuild_allowed"] = True
        if fill_event.purpose in {
            self.SHORT_SL_EXIT_PURPOSE,
            self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
        } and order_fully_completed:
            state["short_exit_filled"] = True
            self._maybe_finalize_exit_after_leg_fill(runtime_state, context, fill_event.purpose)
        state["current_effective_cycle"] = max(
            int(state.get("current_short_cycle_index") or 0),
            int(state.get("cycle_completed_count") or 0),
        )

        exit_purposes = {
            self.LONG_TP_EXIT_PURPOSE,
            self.LONG_TP_EXIT_RECOVERY_PURPOSE,
            self.SHORT_SL_EXIT_PURPOSE,
            self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
        }
        exit_orders_open = (
            snapshot.has_open_purpose(self.LONG_TP_EXIT_PURPOSE)
            or snapshot.has_open_purpose(self.LONG_TP_EXIT_RECOVERY_PURPOSE)
            or snapshot.has_open_purpose(self.SHORT_SL_EXIT_PURPOSE)
            or snapshot.has_open_purpose(self.SHORT_SL_EXIT_RECOVERY_PURPOSE)
        ) if snapshot else False
        block_closed_marker = bool(state.get("block_closed_marker_emitted"))
        if (
            snapshot
            and snapshot.long_qty == 0
            and snapshot.short_qty == 0
            and not exit_orders_open
            and fill_event.status == "FILLED"
            and fill_event.purpose in exit_purposes
            and not block_closed_marker
        ):
            cycle_index = int(state.get("current_effective_cycle") or 0)
            long_fill_entry = cycle_state.get("long_fills", {}).get(str(cycle_index), {})
            long_exit_order_link_id = long_fill_entry.get("client_order_id")
            short_exit_order_link_id = (
                fill_event.client_order_id if "_SHORT_" in fill_event.purpose else None
            )
            payload = {
                "symbol": self.config.symbol,
                "strategy": self.name,
                "cycle_index": cycle_index,
                "positions_flat": True,
                "long_final_size": snapshot.long_qty,
                "short_final_size": snapshot.short_qty,
                "long_realized_pnl": snapshot.realized_long_pnl_total,
                "short_realized_pnl": snapshot.realized_short_pnl_total,
                "net_realized_pnl": snapshot.realized_pnl_total,
            }
            if long_exit_order_link_id:
                payload["long_exit_order_link_id"] = long_exit_order_link_id
            if short_exit_order_link_id:
                payload["short_exit_order_link_id"] = short_exit_order_link_id
            _emit_analyzer_event(logger, "analyzer_block_closed", payload)
            state["block_closed_marker_emitted"] = True
            state["fresh_restart_required"] = True
            trading_stop_context = self._mark_trading_stop_flat_detected(
                state,
                symbol=self.config.symbol,
                reason="on_fill_block_closed",
                long_qty=float(snapshot.long_qty or 0.0),
                short_qty=float(snapshot.short_qty or 0.0),
            )
            _log_event(
                "fixed_cycle_trading_stop_final_exit_flat_pending_audit",
                {
                    "symbol": self.config.symbol,
                    "trade_block_id": trading_stop_context.get("trade_block_id"),
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                },
            )

        # Allgemeiner Flat-Reset für den Fall, dass der finale Exit über einen
        # Trading-Stop ausgelöst wurde, aber kein klassischer Exit-Fill-Purpose
        # (LONG_TP_EXIT/SHORT_SL_EXIT) erkennbar war.
        snapshot_for_reset = runtime_state.last_snapshot
        if (
            snapshot_for_reset
            and float(snapshot_for_reset.long_qty or 0.0) == 0.0
            and float(snapshot_for_reset.short_qty or 0.0) == 0.0
            and state.get("final_exit_trading_stop_active")
        ):
            trading_stop_context = self._mark_trading_stop_flat_detected(
                state,
                symbol=self.config.symbol,
                reason="on_fill_flat_zero",
                long_qty=float(snapshot_for_reset.long_qty or 0.0),
                short_qty=float(snapshot_for_reset.short_qty or 0.0),
            )
            # Alle Trading-Stop-basierten Exit-Orders aus dem Runtime-State entfernen.
            to_remove: list[str] = []
            for client_id, order in runtime_state.active_orders.items():
                if getattr(order, "metadata", None) and getattr(order, "metadata", {}).get("trading_stop_api"):
                    to_remove.append(client_id)
            for client_id in to_remove:
                order = runtime_state.active_orders.pop(client_id, None)
                if order and getattr(order, "exchange_order_id", None):
                    runtime_state.exchange_to_client_id.pop(order.exchange_order_id, None)
            _log_event(
                "fixed_cycle_trading_stop_final_exit_flat_pending_audit",
                {
                    "symbol": self.config.symbol,
                    "trade_block_id": trading_stop_context.get("trade_block_id"),
                    "long_qty": float(snapshot_for_reset.long_qty or 0.0),
                    "short_qty": float(snapshot_for_reset.short_qty or 0.0),
                },
            )
            self._ensure_post_exit_cleanup_required(
                runtime_state, reason="on_fill_final_exit_flat_zero"
            )
            _log_event(
                "fixed_cycle_full_exit_detected_deferred_to_post_exit_cleanup",
                {
                    "symbol": self.config.symbol,
                    "fresh_restart_required": True,
                    "pending_cycle_loss_usdt": state.get("pending_cycle_loss_usdt"),
                },
            )

        processed.add(fill_key)
        cycle_state["processed_fill_ids"] = list(processed)
        self._write_cycle_state(cycle_state)
        state["last_fill_info"] = fill_info

    def _has_no_strategy_orders(self, snapshot: HedgeSnapshot) -> bool:
        valid_purposes = set(self._all_cycle_purposes() + self._exit_purposes())
        valid_purposes.update({self.LONG_ENTRY_PURPOSE, self.SHORT_ENTRY_PURPOSE})
        return not any(order.purpose in valid_purposes for order in snapshot.active_orders)

    def _has_open_initial_entry_orders(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> bool:
        entry_purposes = {self.LONG_ENTRY_PURPOSE, self.SHORT_ENTRY_PURPOSE}
        if any(order.is_open() and order.purpose in entry_purposes for order in snapshot.active_orders):
            return True
        return any(
            not self._is_terminal_order_status(order.status) and order.purpose in entry_purposes
            for order in runtime_state.active_orders.values()
        )

    def _collect_active_initial_entry_orders(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> list[dict[str, Any]]:
        active_orders: list[dict[str, Any]] = []
        entry_purposes = {self.LONG_ENTRY_PURPOSE, self.SHORT_ENTRY_PURPOSE}

        for order in snapshot.active_orders:
            purpose = str(getattr(order, "purpose", "") or "")
            status = str(getattr(order, "status", "") or "")
            if purpose not in entry_purposes or self._is_terminal_order_status(status):
                continue
            active_orders.append(
                {
                    "source": "snapshot",
                    "purpose": purpose,
                    "status": status,
                    "client_order_id": getattr(order, "client_order_id", None),
                    "exchange_order_id": getattr(order, "exchange_order_id", None),
                }
            )

        for order in runtime_state.active_orders.values():
            purpose = str(getattr(order, "purpose", "") or "")
            status = str(getattr(order, "status", "") or "")
            if purpose not in entry_purposes or self._is_terminal_order_status(status):
                continue
            active_orders.append(
                {
                    "source": "runtime_state",
                    "purpose": purpose,
                    "status": status,
                    "client_order_id": getattr(order, "client_order_id", None),
                    "exchange_order_id": getattr(order, "exchange_order_id", None),
                }
            )
        return active_orders

    def _initial_entry_reconcile_gate_ready(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> bool:
        state = runtime_state.strategy_state
        return (
            float(snapshot.long_qty or 0.0) > 0.0
            and float(snapshot.short_qty or 0.0) > 0.0
            and bool(state.get("initial_long_entry_reconciled"))
            and bool(state.get("initial_short_entry_reconciled"))
            and not self._collect_active_initial_entry_orders(snapshot, runtime_state)
        )

    def _initial_entry_reconcile_log_payload(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        *,
        purpose: str | None,
        source: str,
        reason: str,
    ) -> dict[str, Any]:
        state = runtime_state.strategy_state
        return {
            "purpose": purpose,
            "source": source,
            "long_qty": float(snapshot.long_qty or 0.0),
            "short_qty": float(snapshot.short_qty or 0.0),
            "initial_entry_submitted": bool(state.get("initial_entry_submitted")),
            "initial_entry_confirmed": bool(state.get("initial_entry_confirmed")),
            "initial_long_entry_reconciled": bool(state.get("initial_long_entry_reconciled")),
            "initial_short_entry_reconciled": bool(state.get("initial_short_entry_reconciled")),
            "initial_structure_built": bool(state.get("initial_structure_built")),
            "active_initial_entry_orders": self._collect_active_initial_entry_orders(snapshot, runtime_state),
            "reason": reason,
        }

    def _maybe_build_initial_structure_once(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        purpose: str | None,
        source: str,
        reason: str,
        rebuild_reason: str,
        allow_build: bool = True,
    ) -> list[StrategyIntent]:
        state = runtime_state.strategy_state
        payload = {
            **self._initial_entry_reconcile_log_payload(
                snapshot,
                runtime_state,
                purpose=purpose,
                source=source,
                reason=reason,
            ),
            "allow_build": allow_build,
        }
        if not self._initial_entry_reconcile_gate_ready(snapshot, runtime_state):
            _log_event("fixed_cycle_initial_entry_reconcile_gate_wait", payload)
            return []

        _log_event("fixed_cycle_initial_entry_reconcile_gate_ready", payload)
        if not allow_build:
            if (
                bool(state.get("initial_entry_confirmed"))
                and state.get("initial_long_entry_reconciled")
                and state.get("initial_short_entry_reconciled")
                and not payload["active_initial_entry_orders"]
                and not state.get("initial_structure_built")
            ):
                # allow_build wurde vom Aufrufer auf False gesetzt, ist aber nach Reconcile erlaubt.
                # Für Logs explizit markieren, dass wir es lokal auf True promoten.
                payload["allow_build_original"] = payload.get("allow_build", False)
                allow_build = True
                payload["allow_build"] = True
                payload["allow_build_promoted_after_reconcile"] = True
                _log_event(
                    "fixed_cycle_initial_structure_build_allowed_after_reconcile",
                    payload,
                )
            else:
                _log_event(
                    "fixed_cycle_initial_structure_build_blocked_with_reason",
                    {
                        **payload,
                        "block_reason": "allow_build_false_from_caller",
                        "purpose": purpose,
                        "source": source,
                        "reason": reason,
                        "initial_long_entry_reconciled": bool(
                            state.get("initial_long_entry_reconciled")
                        ),
                        "initial_short_entry_reconciled": bool(
                            state.get("initial_short_entry_reconciled")
                        ),
                    },
                )
                return []

        if state.get("initial_structure_built"):
            _log_event("fixed_cycle_initial_structure_build_once_skipped_duplicate", payload)
            return []

        previously_confirmed = bool(state.get("initial_entry_confirmed"))
        state["initial_entry_confirmed"] = True
        state["initial_entry_submitted"] = True
        if not previously_confirmed:
            self._reset_exit_state_for_new_structure(runtime_state, "initial_entry_confirmed")
        intents = self._rebuild_structure(snapshot, runtime_state, context, reason=rebuild_reason)

        # Nur dann als vollständige Initial-Struktur markieren, wenn
        # - der erwartete First-Leg-Cycle-Intent vorhanden ist und
        # - beide direction-aware Final-Exit-Intents vorhanden sind.
        cycle_index = int(state.get("current_effective_cycle") or 0) + 1
        purposes = [intent.purpose for intent in intents]
        first_leg_purpose = self._get_first_leg_purpose(cycle_index)
        exit_purposes = self._get_final_exit_purposes()
        purpose_set = set(purposes)
        has_first_leg = first_leg_purpose in purpose_set
        has_all_exits = exit_purposes.issubset(purpose_set)
        initial_complete = has_first_leg and has_all_exits
        state["initial_structure_built"] = initial_complete
        _log_event(
            "fixed_cycle_initial_structure_build_once_triggered",
            {
                **{
                    **payload,
                    "initial_structure_built": initial_complete,
                },
                "reason": rebuild_reason,
            },
        )
        _log_event(
            "fixed_cycle_initial_structure_intents_created",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "cycle_index": int(state.get("current_effective_cycle") or 0) + 1,
                "purposes": purposes,
                "sides": [intent.side for intent in intents],
                "qtys": [float(intent.qty or 0.0) for intent in intents],
                "trigger_prices": [float(intent.trigger_price or 0.0) for intent in intents],
            },
        )
        return intents

    def _finalize_initial_entry_orders_from_snapshot(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> None:
        state = runtime_state.strategy_state
        initial_long_qty = float(state.get("initial_long_qty") or 0.0)
        initial_short_qty = float(state.get("initial_short_qty") or 0.0)
        if initial_long_qty <= 0 or initial_short_qty <= 0:
            return
        long_confirmed = float(snapshot.long_qty) >= initial_long_qty - 1e-9
        short_confirmed = float(snapshot.short_qty) >= initial_short_qty - 1e-9
        if not (long_confirmed and short_confirmed):
            return
        updated_orders: list[str] = []
        for order in runtime_state.active_orders.values():
            if order.purpose == self.LONG_ENTRY_PURPOSE and long_confirmed:
                if self._is_terminal_order_status(order.status):
                    continue
                order.status = "FILLED"
                order.filled_qty = order.qty
                order.remaining_qty = 0.0
                updated_orders.append(order.client_order_id)
            if order.purpose == self.SHORT_ENTRY_PURPOSE and short_confirmed:
                if self._is_terminal_order_status(order.status):
                    continue
                order.status = "FILLED"
                order.filled_qty = order.qty
                order.remaining_qty = 0.0
                updated_orders.append(order.client_order_id)
        if updated_orders:
            _log_event(
                "fixed_cycle_initial_entry_orders_marked_filled",
                {
                    "symbol": self.config.symbol,
                    "initial_long_qty": initial_long_qty,
                    "initial_short_qty": initial_short_qty,
                    "snapshot_long_qty": snapshot.long_qty,
                    "snapshot_short_qty": snapshot.short_qty,
                    "updated_order_ids": updated_orders,
                },
            )

    def _update_initial_entry_confirmation(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> bool:
        state = runtime_state.strategy_state
        self._finalize_initial_entry_orders_from_snapshot(snapshot, runtime_state)
        confirmed = self._initial_entry_reconcile_gate_ready(snapshot, runtime_state)
        previously_confirmed = bool(state.get("initial_entry_confirmed"))
        state["initial_entry_confirmed"] = confirmed
        if confirmed:
            state["initial_entry_submitted"] = True
            if not previously_confirmed:
                self._reset_exit_state_for_new_structure(runtime_state, "initial_entry_confirmed")
            if state.get("startup_flat_reset_applied"):
                state["startup_flat_reset_applied"] = False
                _log_event(
                    "fixed_cycle_startup_flat_reset_guard_lifted_after_initial_entry",
                    {
                        "symbol": self.config.symbol,
                        "long_qty": snapshot.long_qty,
                        "short_qty": snapshot.short_qty,
                        "long_avg": snapshot.long_avg,
                        "short_avg": snapshot.short_avg,
                    },
                )
        return confirmed

    def _refill_qty_below_min_notional(
        self,
        qty: float,
        reference_price: float,
        runtime_state: RuntimeState | None = None,
    ) -> bool:
        if qty <= 0:
            return True
        if reference_price <= 0:
            return False
        normalized = self._normalize_qty(qty, runtime_state)
        if normalized <= 0:
            return True
        return normalized * reference_price < self.config.min_notional_usdt

    def _refill_residual_snapshot_payload(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> dict[str, float]:
        state = runtime_state.strategy_state
        current_price = float(snapshot.current_price or 0.0)
        initial_long_qty = float(state.get("initial_long_qty") or 0.0)
        initial_short_qty = float(state.get("initial_short_qty") or 0.0)
        current_long_qty = float(snapshot.long_qty or 0.0)
        current_short_qty = float(snapshot.short_qty or 0.0)
        missing_long_qty = max(initial_long_qty - current_long_qty, 0.0)
        missing_short_qty = max(initial_short_qty - current_short_qty, 0.0)
        refill_long_qty = (
            self._normalize_qty(missing_long_qty, runtime_state) if missing_long_qty > 0 else 0.0
        )
        refill_short_qty = (
            self._normalize_qty(missing_short_qty, runtime_state) if missing_short_qty > 0 else 0.0
        )
        return {
            "current_price": current_price,
            "initial_long_qty": initial_long_qty,
            "initial_short_qty": initial_short_qty,
            "current_long_qty": current_long_qty,
            "current_short_qty": current_short_qty,
            "missing_long_qty": missing_long_qty,
            "missing_short_qty": missing_short_qty,
            "refill_long_qty": refill_long_qty,
            "refill_short_qty": refill_short_qty,
        }

    def _apply_refill_dust_residual_filter(
        self,
        residual: dict[str, float],
        runtime_state: RuntimeState,
        *,
        reason: str,
        log_event: bool = True,
    ) -> dict[str, float]:
        current_price = residual["current_price"]
        dust_long = (
            residual["missing_long_qty"] > 0
            and self._refill_qty_below_min_notional(
                residual["missing_long_qty"], current_price, runtime_state
            )
        )
        dust_short = (
            residual["missing_short_qty"] > 0
            and self._refill_qty_below_min_notional(
                residual["missing_short_qty"], current_price, runtime_state
            )
        )
        if not dust_long and not dust_short:
            return residual
        ignored: dict[str, float] = {}
        if dust_long:
            ignored["missing_long_qty"] = residual["missing_long_qty"]
            ignored["refill_long_qty"] = residual["refill_long_qty"]
            residual["missing_long_qty"] = 0.0
            residual["refill_long_qty"] = 0.0
        if dust_short:
            ignored["missing_short_qty"] = residual["missing_short_qty"]
            ignored["refill_short_qty"] = residual["refill_short_qty"]
            residual["missing_short_qty"] = 0.0
            residual["refill_short_qty"] = 0.0
        if not log_event:
            return residual
        _log_event(
            "fixed_cycle_refill_dust_residual_ignored",
            {
                "symbol": self.config.symbol,
                "reason": reason,
                "min_notional_usdt": self.config.min_notional_usdt,
                "current_price": current_price,
                **ignored,
                "cycle_completed_count": runtime_state.strategy_state.get("cycle_completed_count"),
                "cycle_pair_count": runtime_state.strategy_state.get("cycle_pair_count"),
            },
        )
        return residual

    def _refill_residual_is_dust_only(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> bool:
        residual = self._apply_refill_dust_residual_filter(
            self._refill_residual_snapshot_payload(snapshot, runtime_state),
            runtime_state,
            reason="dust_only_check",
            log_event=False,
        )
        return residual["missing_long_qty"] <= 0 and residual["missing_short_qty"] <= 0

    def _try_complete_refill_after_dust_residual(
        self,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState,
        context: StrategyContext | None,
        *,
        reason: str,
        residual_payload: dict[str, Any] | None = None,
    ) -> bool:
        state = runtime_state.strategy_state
        if not (
            state.get("refill_fills_complete")
            or state.get("refill_completion_pending_reconcile")
        ):
            return False
        if not snapshot:
            snapshot = runtime_state.last_snapshot
        if not snapshot:
            return False
        if float(snapshot.long_qty or 0.0) <= 0 or float(snapshot.short_qty or 0.0) <= 0:
            return False
        if self._collect_active_refill_order_purposes(snapshot, runtime_state):
            return False
        if not self._refill_residual_is_dust_only(snapshot, runtime_state):
            return False
        state["refill_long_filled"] = True
        state["refill_short_filled"] = True
        _log_event(
            "fixed_cycle_refill_completed_after_dust_reconcile",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "reason": reason,
                "cycle_completed_count": state.get("cycle_completed_count"),
                "cycle_pair_count": state.get("cycle_pair_count"),
                **(residual_payload or {}),
            },
        )
        self._complete_refill(runtime_state, context, completion_reason="dust_reconcile")
        return True

    def _collect_open_initial_entry_orders(self, snapshot: HedgeSnapshot) -> list[dict[str, str | None]]:
        entry_purposes = {self.LONG_ENTRY_PURPOSE, self.SHORT_ENTRY_PURPOSE}
        return [
            {
                "purpose": getattr(order, "purpose", None),
                "status": getattr(order, "status", None),
            }
            for order in snapshot.active_orders
            if getattr(order, "purpose", None) in entry_purposes
            and getattr(order, "status", None) in {"OPEN", "PARTIAL"}
        ]

    def _fixed_long_cycle_qty(
        self,
        initial_long_qty: float,
        current_open_long_qty: float,
        reference_price: float,
        runtime_state: RuntimeState | None = None,
    ) -> float:
        raw_qty = current_open_long_qty * self._pct(self.config.reduction_pct_per_fill)
        normalized = self._normalize_qty(raw_qty, runtime_state)
        if normalized <= 0:
            return 0.0
        if reference_price <= 0:
            return 0.0
        if normalized * reference_price < self.config.min_notional_usdt:
            return 0.0
        return normalized

    def _fixed_short_cycle_qty(
        self,
        initial_short_qty: float,
        current_open_short_qty: float,
        reference_price: float,
        reduction_multiplier: float = 1.0,
        runtime_state: RuntimeState | None = None,
    ) -> float:
        effective_pct = self.config.reduction_pct_per_fill * reduction_multiplier
        raw_qty = current_open_short_qty * self._pct(effective_pct)
        normalized = self._normalize_qty(min(raw_qty, current_open_short_qty), runtime_state)
        if normalized <= 0:
            return 0.0
        if reference_price <= 0:
            return 0.0
        if normalized * reference_price < self.config.min_notional_usdt:
            return 0.0
        return normalized

    def _price_to_qty(self, *, notional_usdt: float, price: float, runtime_state: RuntimeState | None) -> float:
        if notional_usdt <= 0 or price <= 0:
            return 0.0
        qty = notional_usdt / price
        return self._normalize_qty(qty, runtime_state)

    def _set_recovery_lifecycle_state(
        self,
        state: dict[str, Any],
        new_state: str,
        *,
        event: str,
        extra: dict[str, Any] | None = None,
    ) -> None:
        """
        Beobachtender Lifecycle-State für den Recovery-/Refill-Ablauf.

        - Verändert keine bestehende Guard- oder Flag-Logik.
        - Dient nur zur Diagnose und besseren Nachvollziehbarkeit.
        """
        old_state = state.get("recovery_lifecycle_state")
        state["recovery_lifecycle_state"] = new_state
        cycle_state = state.get("cycle_state") or {}
        payload: dict[str, Any] = {
            "symbol": self.config.symbol,
            "bot_name": self.config.bot_name,
            "trade_block_id": state.get("trade_block_id"),
            "cycle_index": (
                state.get("recovery_reference_cycle_index")
                or cycle_state.get("recovery_reference_cycle_index")
                or state.get("active_cycle_index")
                or 0
            ),
            "event": event,
            "old_state": old_state,
            "new_state": new_state,
        }
        if extra:
            payload.update(extra)
        _log_event("fixed_cycle_recovery_lifecycle_transition", payload)

    def _apply_recovery_refill_state(
        self,
        runtime_state: RuntimeState,
        long_notional: float,
        short_notional: float,
        *,
        long_qty: float | None = None,
        short_qty: float | None = None,
    ) -> None:
        state = runtime_state.strategy_state
        cycle_state = state.get("cycle_state") or {}
        state["recovery_required"] = True
        state["recovery_in_progress"] = True
        state["cycle_state"] = cycle_state
        cycle_state["recovery_required"] = True
        cycle_state["recovery_in_progress"] = True
        self._set_recovery_reload_state_value(
            state, cycle_state, "recovery_reload_required", True
        )
        self._set_recovery_reload_state_value(
            state, cycle_state, "recovery_reload_long_pending", True
        )
        self._set_recovery_reload_state_value(
            state, cycle_state, "recovery_reload_short_pending", True
        )
        self._set_recovery_reload_state_value(
            state, cycle_state, "recovery_reload_long_filled", False
        )
        self._set_recovery_reload_state_value(
            state, cycle_state, "recovery_reload_short_filled", False
        )
        self._set_recovery_reload_state_value(
            state, cycle_state, "recovery_reload_completed", False
        )
        self._set_recovery_reload_state_value(
            state, cycle_state, "recovery_reload_long_notional_usdt", long_notional
        )
        self._set_recovery_reload_state_value(
            state, cycle_state, "recovery_reload_short_notional_usdt", short_notional
        )
        if long_qty is not None:
            self._set_recovery_reload_state_value(
                state, cycle_state, "recovery_reload_long_qty", float(long_qty)
            )
        if short_qty is not None:
            self._set_recovery_reload_state_value(
                state, cycle_state, "recovery_reload_short_qty", float(short_qty)
            )
        state["recovery_reload_size_source"] = "base_notional_usdt"
        cycle_state["recovery_reload_size_source"] = "base_notional_usdt"
        state["recovery_refill_size_source"] = "base_notional_usdt"
        cycle_state["recovery_refill_size_source"] = "base_notional_usdt"
        self._write_cycle_state(cycle_state)

    def _clear_recovery_state(self, runtime_state: RuntimeState) -> None:
        state = runtime_state.strategy_state
        cycle_state = state.get("cycle_state") or {}
        keys = [
            "recovery_required",
            "recovery_in_progress",
            "recovery_reload_required",
            "recovery_reload_long_pending",
            "recovery_reload_short_pending",
            "recovery_reload_long_filled",
            "recovery_reload_short_filled",
            "recovery_reload_long_notional_usdt",
            "recovery_reload_short_notional_usdt",
            "recovery_reload_long_qty",
            "recovery_reload_short_qty",
            "recovery_reload_long_fill_price",
            "recovery_reload_short_fill_price",
            "recovery_reload_completed",
            "recovery_reload_size_source",
            "recovery_refill_required",
            "recovery_refill_long_pending",
            "recovery_refill_short_pending",
            "recovery_refill_long_filled",
            "recovery_refill_short_filled",
            "recovery_refill_long_notional_usdt",
            "recovery_refill_short_notional_usdt",
            "recovery_refill_size_source",
            "recovery_refill_long_fill_price",
            "recovery_refill_short_fill_price",
        ]
        for key in keys:
            state.pop(key, None)
            cycle_state.pop(key, None)

        old_block_status = state.get("cycle_block_status")
        old_block_reason = state.get("cycle_block_reason")
        cycle_old_block_status = cycle_state.get("cycle_block_status")
        cycle_old_block_reason = cycle_state.get("cycle_block_reason")
        cleaned = False
        if old_block_status == "RECOVERY_REQUIRED":
            state.pop("cycle_block_status", None)
            state.pop("cycle_block_reason", None)
            cleaned = True
        if cycle_old_block_status == "RECOVERY_REQUIRED":
            cycle_state.pop("cycle_block_status", None)
            cycle_state.pop("cycle_block_reason", None)
            cleaned = True
            # prefer logging the state-level reason if already recorded
            if not old_block_status and cycle_old_block_status:
                old_block_status = cycle_old_block_status
                old_block_reason = cycle_old_block_reason
        if cleaned:
            payload = {
                "symbol": self.config.symbol,
                "old_cycle_block_status": old_block_status,
                "old_cycle_block_reason": old_block_reason,
                "recovery_completed_cycle_index": state.get(
                    "recovery_completed_cycle_index"
                ),
                "source": "_clear_recovery_state",
            }
            _log_event("fixed_cycle_recovery_block_status_cleared", payload)
        self._write_cycle_state(cycle_state)

    # wallet-baseline helpers
    def _resolve_recovery_wallet_state_paths(self) -> tuple[Path | None, Path | None]:
        cached = getattr(self, "_cached_recovery_wallet_paths", None)
        if cached is not None:
            return cached
        bot_name = (self.config.bot_name or "").strip()
        state_dir: Path | None = None
        profile_dir: Path | None = None
        if bot_name:
            for profile_candidate in PER_BOT_CONFIG_ROOT.iterdir():
                if not profile_candidate.is_dir():
                    continue
                candidate = profile_candidate / bot_name
                if not candidate.is_dir():
                    continue
                config_path = candidate / "config" / "fixed_cycle_config.json"
                if not config_path.exists():
                    continue
                state_dir = candidate / "state"
                state_dir.mkdir(parents=True, exist_ok=True)
                profile_dir = profile_candidate
                break
        self._cached_recovery_wallet_paths = (state_dir, profile_dir)
        return self._cached_recovery_wallet_paths

    def _recovery_wallet_baseline_path(self) -> Path | None:
        state_dir, _ = self._resolve_recovery_wallet_state_paths()
        if not state_dir:
            return None
        return state_dir / "recovery_wallet_baseline.json"

    def _watchdog_wallet_guard_path(self) -> Path | None:
        state_dir, _ = self._resolve_recovery_wallet_state_paths()
        if not state_dir:
            return None
        return state_dir / "wallet_guard.json"

    def _load_watchdog_wallet_guard(self) -> tuple[Path | None, dict[str, Any] | None]:
        guard_path = self._watchdog_wallet_guard_path()
        if not guard_path or not guard_path.exists():
            return None, None
        try:
            payload = json.loads(guard_path.read_text(encoding="utf-8") or "{}")
        except Exception:
            return guard_path, None
        if not isinstance(payload, dict):
            return guard_path, None
        return guard_path, payload

    def _save_watchdog_wallet_guard(self, path: Path, data: dict[str, Any]) -> None:
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception:
            # Guard-Speicherfehler sollen den Bot nicht hart stoppen; Logging erfolgt im Aufrufer.
            return

    def _load_watchdog_start_wallet_usdt(self) -> float | None:
        guard_path = self._watchdog_wallet_guard_path()
        if not guard_path or not guard_path.exists():
            return None
        try:
            payload = json.loads(guard_path.read_text(encoding="utf-8") or "{}")
        except Exception:
            return None
        try:
            value = float(payload.get("start_wallet_usdt") or 0.0)
        except (TypeError, ValueError):
            return None
        return value if value > 0 else None

    def _wallet_transfer_executor_paths(self) -> tuple[Path | None, Path | None]:
        source_group_dir, _ = self._wallet_transfer_source_group_dir()
        if not source_group_dir:
            return None, None
        executor = source_group_dir / "watchdog" / "wallet_transfer_executor.py"
        json_log = source_group_dir / "logs" / "wallet_transfer_executor.jsonl"
        return (executor if executor.exists() else None, json_log)

    def _wallet_transfer_profile_name(self) -> str | None:
        bot_name = str(self.config.bot_name or "").strip().lower()
        match = re.match(r"^(?:long|short)_bot_(\d+)$", bot_name)
        if not match:
            return None
        return f"bot_{match.group(1)}"

    def _wallet_transfer_is_short_target(self) -> bool:
        bot_name = str(self.config.bot_name or "").strip().lower()
        strategy_side = str(getattr(self.config, "strategy_side", "") or "").strip().lower()
        return bot_name.startswith("short_bot_") or strategy_side == "short"

    def _wallet_transfer_source_group_dir(self) -> tuple[Path | None, str]:
        _, current_group_dir = self._resolve_recovery_wallet_state_paths()
        if self._wallet_transfer_is_short_target():
            long_group_dir = PROJECT_ROOT / "live_bots" / "100_50_hedge_bot"
            if long_group_dir.exists():
                return long_group_dir, "paired_long_bot_group"
            return None, "paired_long_bot_group_missing"
        if current_group_dir:
            return current_group_dir, "current_bot_group"
        return None, "current_bot_group_missing"

    def _resolve_wallet_transfer_config_path(
        self, group_dir: Path
    ) -> tuple[Path | None, str | None]:
        """
        Resolve the wallet transfer config path in the same way as the wallet_refill_watchdog.

        Priority:
        - wallet_transfer.transfer_config_file
        - transfer_config_file
        - fallback to config/config.yaml under the group directory
        """
        base_config = group_dir / "config" / "config.yaml"
        if not base_config.exists():
            return None, None
        try:
            raw = yaml.safe_load(base_config.read_text(encoding="utf-8")) or {}
        except Exception:
            # If parsing fails, fall back to the base config path (no secrets logged)
            return base_config, "group_config_fallback_on_parse_error"
        transfer_section = raw.get("wallet_transfer") or {}
        override_path = transfer_section.get("transfer_config_file") or raw.get("transfer_config_file")
        if not override_path:
            return base_config, "group_config"
        override_path = Path(str(override_path))
        if not override_path.is_absolute():
            override_path = base_config.parent / override_path
        if transfer_section.get("transfer_config_file"):
            return override_path, "wallet_transfer.transfer_config_file"
        return override_path, "transfer_config_file"

    def _wallet_transfer_get_section_case_insensitive(
        self, config: dict[str, Any], key: str
    ) -> tuple[str | None, dict[str, Any]]:
        if key in config:
            section = config[key]
            if isinstance(section, dict):
                return str(key), section
            return None, {}
        key_lower = key.lower()
        for existing_key, value in config.items():
            if str(existing_key).lower() == key_lower and isinstance(value, dict):
                return str(existing_key), value
        return None, {}

    def _wallet_transfer_get_value_case_insensitive(
        self, section: dict[str, Any], key: str
    ) -> Any | None:
        if key in section:
            return section[key]
        key_lower = key.lower()
        for existing_key, value in section.items():
            if str(existing_key).lower() == key_lower:
                return value
        return None

    def _wallet_transfer_get_first_field(
        self, section: dict[str, Any], candidates: tuple[str, ...]
    ) -> tuple[str, str | None]:
        for candidate in candidates:
            value = self._wallet_transfer_get_value_case_insensitive(section, candidate)
            if value is not None and str(value).strip():
                return str(value).strip(), candidate
        return "", None

    def _wallet_transfer_find_main_account_section(
        self, config: dict[str, Any]
    ) -> tuple[str | None, dict[str, Any] | None]:
        main_candidates = (
            "Main_bot",
            "main_bot",
            "master",
            "Master",
            "main",
            "main_account",
        )
        uid_candidates = ("uid", "main_uid", "account_uid", "member_id")
        for candidate in main_candidates:
            section_key, section = self._wallet_transfer_get_section_case_insensitive(config, candidate)
            if not section:
                continue
            api_key = str(
                self._wallet_transfer_get_value_case_insensitive(section, "api_key") or ""
            ).strip()
            secret_key = str(
                self._wallet_transfer_get_value_case_insensitive(section, "secret_key") or ""
            ).strip()
            uid_value, _ = self._wallet_transfer_get_first_field(section, uid_candidates)
            if api_key and secret_key and uid_value:
                return section_key or candidate, section
        profiles_key, profiles_section = self._wallet_transfer_get_section_case_insensitive(
            config, "profiles"
        )
        if profiles_section:
            section_key, section = self._wallet_transfer_get_section_case_insensitive(
                profiles_section, "main"
            )
            if section:
                api_key = str(
                    self._wallet_transfer_get_value_case_insensitive(section, "api_key") or ""
                ).strip()
                secret_key = str(
                    self._wallet_transfer_get_value_case_insensitive(section, "secret_key") or ""
                ).strip()
                uid_value, _ = self._wallet_transfer_get_first_field(section, uid_candidates)
                if api_key and secret_key and uid_value:
                    label = f"{profiles_key or 'profiles'}.{section_key or 'main'}"
                    return label, section
        return None, None

    def _inspect_wallet_transfer_config(
        self,
        config_path: Path,
        *,
        target_bot_name: str,
        target_profile: str | None,
        source_config_origin: str,
    ) -> dict[str, Any]:
        payload_base = {
            "source_config_origin": source_config_origin,
            "target_bot_name": target_bot_name,
            "target_profile": target_profile,
        }
        if not config_path.exists():
            return {**payload_base, "ok": False, "reason": "config_missing"}
        try:
            raw = yaml.safe_load(config_path.read_text(encoding="utf-8")) or {}
        except Exception as exc:
            return {
                **payload_base,
                "ok": False,
                "reason": "config_parse_failed",
                "error": str(exc),
            }
        if not isinstance(raw, dict):
            return {**payload_base, "ok": False, "reason": "config_not_object"}

        source_account_label, main_section = self._wallet_transfer_find_main_account_section(raw)
        if not main_section:
            return {
                **payload_base,
                "ok": False,
                "reason": "missing_main_account_section",
            }

        target_account_label = target_bot_name
        profiles_key, profiles_section = self._wallet_transfer_get_section_case_insensitive(
            raw, "profiles"
        )
        if profiles_section and target_profile:
            _, profile_section = self._wallet_transfer_get_section_case_insensitive(
                profiles_section, target_profile
            )
            if profile_section:
                account_key = "short_account" if self._wallet_transfer_is_short_target() else "long_account"
                resolved_account = self._wallet_transfer_get_value_case_insensitive(
                    profile_section, account_key
                )
                if resolved_account is not None and str(resolved_account).strip():
                    target_account_label = str(resolved_account).strip()

        target_section_label, target_section = self._wallet_transfer_get_section_case_insensitive(
            raw, target_account_label
        )
        if not target_section and target_account_label.lower() != target_bot_name.lower():
            target_section_label, target_section = self._wallet_transfer_get_section_case_insensitive(
                raw, target_bot_name
            )
            if target_section:
                target_account_label = target_bot_name
        if not target_section:
            return {
                **payload_base,
                "ok": False,
                "reason": "missing_target_account_section",
                "source_account_label": source_account_label,
                "target_account_label": target_account_label,
                "profiles_section": profiles_key,
            }

        target_uid, target_uid_field = self._wallet_transfer_get_first_field(
            target_section, ("sub_uid", "uid", "account_uid", "member_id")
        )
        if not target_uid:
            return {
                **payload_base,
                "ok": False,
                "reason": "missing_target_sub_uid",
                "source_account_label": source_account_label,
                "target_account_label": target_section_label or target_account_label,
            }

        return {
            **payload_base,
            "ok": True,
            "source_account_label": source_account_label,
            "target_account_label": target_section_label or target_account_label,
            "target_uid_field": target_uid_field,
        }

    def _format_transfer_amount_for_executor(self, amount: float) -> str:
        quantized = Decimal(str(amount)).quantize(Decimal("0.01"), rounding=ROUND_DOWN)
        text = format(quantized, "f")
        if "." in text:
            text = text.rstrip("0").rstrip(".")
        return text or "0"

    @staticmethod
    def _recovery_wallet_transfer_audit_event_name(suffix: str) -> str:
        if suffix == "baseline_updated_after_transfer":
            return "fixed_cycle_recovery_wallet_baseline_updated_after_transfer"
        return f"fixed_cycle_recovery_wallet_transfer_{suffix}"

    @staticmethod
    def _truncate_recovery_wallet_transfer_log_text(text: str, *, limit: int = 500) -> str:
        raw = str(text or "")
        if len(raw) <= limit:
            return raw
        return raw[: limit - 3] + "..."

    def _extract_executor_transfer_audit_fields(
        self, executor_event: dict[str, Any] | None
    ) -> dict[str, Any]:
        if not isinstance(executor_event, dict):
            return {}
        fields: dict[str, Any] = {}
        for key, target in (
            ("status", "bybit_status"),
            ("requested_amount", "requested_amount_usdt"),
            ("final_amount", "rounded_amount_usdt"),
            ("from_account_type", "from_account_type"),
            ("to_account_type", "to_account_type"),
            ("transfer_id", "bybit_transfer_id"),
        ):
            value = executor_event.get(key)
            if value is not None:
                fields[target] = value
        return fields

    def _build_recovery_wallet_transfer_envelope(
        self,
        runtime_state: RuntimeState,
        *,
        baseline: dict[str, Any] | None = None,
        cycle_index: int | None = None,
        transfer_context: dict[str, Any] | None = None,
        transfer_amount_usdt: float | None = None,
        transfer_required: bool | None = None,
        transfer_id: str | None = None,
        extra: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        state = runtime_state.strategy_state
        baseline_payload = baseline if isinstance(baseline, dict) else {}
        transfer_context = transfer_context if isinstance(transfer_context, dict) else {}
        if transfer_amount_usdt is None:
            payload_base = transfer_context.get("payload_base") or {}
            if isinstance(payload_base, dict):
                transfer_amount_usdt = float(payload_base.get("transfer_amount_usdt") or 0.0)
            else:
                transfer_amount_usdt = 0.0
        requested_amount = float(transfer_amount_usdt or 0.0)
        rounded_amount = float(self._format_transfer_amount_for_executor(requested_amount) or 0.0)
        recovery_cycle_index = cycle_index
        if recovery_cycle_index is None:
            recovery_cycle_index = int(
                state.get("recovery_reference_cycle_index")
                or state.get("active_cycle_index")
                or 0
            )
        envelope: dict[str, Any] = {
            "symbol": self.config.symbol,
            "bot_name": self.config.bot_name,
            "strategy_side": getattr(self.config, "strategy_side", None) or self.config.side,
            "trade_block_id": state.get("trade_block_id"),
            "recovery_reload_id": state.get("recovery_reload_id"),
            "recovery_cycle_index": recovery_cycle_index,
            "trigger_reason": state.get("recovery_activation_reason"),
            "recovery_activation_reason": state.get("recovery_activation_reason"),
            "coin": "USDT",
            "asset": "USDT",
            "from_account_type": "FUND",
            "to_account_type": "UNIFIED",
            "source_account_label": transfer_context.get("source_account_label"),
            "target_account_label": transfer_context.get("target_account_label"),
            "initial_wallet_balance_usdt": baseline_payload.get("initial_wallet_balance_usdt"),
            "allocated_wallet_balance_usdt": baseline_payload.get("allocated_wallet_balance_usdt"),
            "total_transferred_recovery_usdt": baseline_payload.get(
                "total_transferred_recovery_usdt"
            ),
            "pending_recovery_transfer_usdt": baseline_payload.get("pending_recovery_transfer_usdt"),
        }
        if transfer_required is not None:
            envelope["transfer_required"] = transfer_required
        if requested_amount > 0:
            envelope["transfer_amount_usdt"] = requested_amount
            envelope["requested_amount_usdt"] = requested_amount
            envelope["rounded_amount_usdt"] = rounded_amount
        if transfer_id:
            envelope["transfer_id"] = transfer_id
            envelope["bybit_transfer_id"] = transfer_id
        if extra:
            for key, value in extra.items():
                if key not in envelope:
                    envelope[key] = value
        return envelope

    def _log_recovery_wallet_transfer_audit(
        self,
        context: StrategyContext | None,
        suffix: str,
        runtime_state: RuntimeState,
        *,
        baseline: dict[str, Any] | None = None,
        cycle_index: int | None = None,
        transfer_context: dict[str, Any] | None = None,
        transfer_amount_usdt: float | None = None,
        transfer_required: bool | None = None,
        transfer_id: str | None = None,
        also_audit: bool = True,
        extra: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        payload = self._build_recovery_wallet_transfer_envelope(
            runtime_state,
            baseline=baseline,
            cycle_index=cycle_index,
            transfer_context=transfer_context,
            transfer_amount_usdt=transfer_amount_usdt,
            transfer_required=transfer_required,
            transfer_id=transfer_id,
            extra=extra,
        )
        event = self._recovery_wallet_transfer_audit_event_name(suffix)
        _log_event(event, payload)
        if also_audit and context is not None and getattr(context, "audit", None) is not None:
            context.audit.log_event(event, **payload)
        return payload

    def _enrich_recovery_wallet_transfer_record(
        self,
        record: dict[str, Any],
        runtime_state: RuntimeState,
        transfer_context: dict[str, Any],
        transfer_amount_usdt: float,
        executor_event: dict[str, Any] | None,
        executor_log_path: Path | None,
    ) -> dict[str, Any]:
        state = runtime_state.strategy_state
        requested_amount = float(transfer_amount_usdt or 0.0)
        rounded_amount = float(self._format_transfer_amount_for_executor(requested_amount) or 0.0)
        executor_fields = self._extract_executor_transfer_audit_fields(executor_event)
        enriched = dict(record)
        enriched.update(
            {
                "requested_amount_usdt": executor_fields.get(
                    "requested_amount_usdt", requested_amount
                ),
                "rounded_amount_usdt": executor_fields.get(
                    "rounded_amount_usdt", rounded_amount
                ),
                "from_account_type": executor_fields.get("from_account_type") or "FUND",
                "to_account_type": executor_fields.get("to_account_type") or "UNIFIED",
                "source_account_label": transfer_context.get("source_account_label"),
                "target_account_label": transfer_context.get("target_account_label"),
                "recovery_reload_id": state.get("recovery_reload_id"),
                "recovery_activation_reason": state.get("recovery_activation_reason"),
                "executor_log_path": str(executor_log_path) if executor_log_path else None,
            }
        )
        if executor_fields.get("bybit_status") is not None:
            enriched["bybit_status"] = executor_fields.get("bybit_status")
        if executor_fields.get("bybit_transfer_id") is not None:
            enriched["bybit_transfer_id"] = executor_fields.get("bybit_transfer_id")
        return enriched

    def _is_flat_snapshot_for_baseline(
        self, snapshot: HedgeSnapshot, runtime_state: RuntimeState
    ) -> bool:
        long_qty = float(snapshot.long_qty or 0.0)
        short_qty = float(snapshot.short_qty or 0.0)
        has_snapshot_orders = bool(snapshot.active_orders)
        has_runtime_orders = bool(runtime_state.active_orders)
        return long_qty <= 0.0 and short_qty <= 0.0 and not (has_snapshot_orders or has_runtime_orders)

    def _load_recovery_wallet_baseline(self, path: Path) -> dict[str, Any] | None:
        if not path.exists():
            return None
        try:
            raw = json.loads(path.read_text(encoding="utf-8") or "{}")
        except Exception as exc:
            _log_event(
                "fixed_cycle_wallet_baseline_invalid",
                {
                    "symbol": self.config.symbol,
                    "bot_name": self.config.bot_name,
                    "error": str(exc),
                    "path": str(path),
                },
            )
            return None
        if not isinstance(raw, dict):
            _log_event(
                "fixed_cycle_wallet_baseline_invalid",
                {
                    "symbol": self.config.symbol,
                    "bot_name": self.config.bot_name,
                    "error": "payload_not_object",
                    "path": str(path),
                },
            )
            return None
        return raw

    def _save_recovery_wallet_baseline(self, path: Path, payload: dict[str, Any]) -> None:
        try:
            path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as exc:
            _log_event(
                "fixed_cycle_wallet_baseline_save_failed",
                {
                    "symbol": self.config.symbol,
                    "bot_name": self.config.bot_name,
                    "error": str(exc),
                    "path": str(path),
                },
            )

    def _capture_recovery_wallet_baseline(
        self,
        trade_block_id: str | None,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        baseline_context: str | None = None,
    ) -> dict[str, Any] | None:
        baseline_path = self._recovery_wallet_baseline_path()
        existing = self._load_recovery_wallet_baseline(baseline_path) if baseline_path else None
        if (
            existing
            and existing.get("trade_block_id") == trade_block_id
            and float(existing.get("initial_wallet_balance_usdt") or 0.0) > 0.0
        ):
            _log_event(
                "fixed_cycle_recovery_reload_wallet_baseline_loaded",
                {
                    "symbol": self.config.symbol,
                    "bot_name": self.config.bot_name,
                    "trade_block_id": trade_block_id,
                    "path": str(baseline_path),
                    "initial_wallet_balance_usdt": existing.get("initial_wallet_balance_usdt"),
                },
            )
            return existing
        payload_base = {
            "symbol": self.config.symbol,
            "bot_name": self.config.bot_name,
            "trade_block_id": trade_block_id,
        }
        _log_event("fixed_cycle_wallet_baseline_capture_started", payload_base)
        if not baseline_path:
            _log_event(
                "fixed_cycle_wallet_baseline_capture_failed",
                {**payload_base, "reason": "baseline_path_missing"},
            )
            return None
        order_manager = context.order_manager
        if not order_manager or not hasattr(order_manager, "fetch_wallet_balance"):
            _log_event(
                "fixed_cycle_wallet_baseline_capture_failed",
                {**payload_base, "reason": "order_manager_missing"},
            )
            return None
        balance, metric = order_manager.fetch_wallet_balance(account_type="UNIFIED", coin="USDT")
        source = baseline_context or "startup_before_trade"
        if balance is None or balance <= 0:
            start_wallet_usdt = self._load_watchdog_start_wallet_usdt()
            if start_wallet_usdt and start_wallet_usdt > 0:
                balance = start_wallet_usdt
                metric = "wallet_guard.start_wallet_usdt"
                source = "wallet_guard_start_wallet_usdt"
            elif baseline_context == "recovery_active_trade":
                fallback_amount = float(self.config.base_notional_usdt or 0.0) + (
                    float(self.config.base_notional_usdt or 0.0)
                    * float(getattr(self.config, "hedge_ratio_short", 0.0) or 0.0)
                )
                if fallback_amount > 0:
                    balance = fallback_amount
                    metric = "config_notional_fallback"
                    source = "late_capture_config_fallback"
                    _log_event(
                        "fixed_cycle_recovery_reload_wallet_baseline_missing_using_late_capture",
                        {
                            **payload_base,
                            "amount_usdt": fallback_amount,
                            "baseline_context": baseline_context,
                        },
                    )
            if balance is None or balance <= 0:
                _log_event(
                    "fixed_cycle_wallet_baseline_capture_failed",
                    {
                        **payload_base,
                        "reason": "balance_invalid",
                        "balance": balance,
                        "metric": metric,
                    },
                )
                return None
        captured_at = datetime.now(timezone.utc).isoformat()
        initial_wallet_balance = float(balance)
        baseline_payload = {
            "symbol": self.config.symbol,
            "bot_name": self.config.bot_name,
            "strategy_side": self.config.strategy_side,
            "captured_at": captured_at,
            "trade_block_id": trade_block_id,
            "initial_wallet_balance_usdt": initial_wallet_balance,
            "account_type": "UNIFIED",
            "coin": "USDT",
            "source": source,
            "total_transferred_recovery_usdt": 0.0,
            "allocated_wallet_balance_usdt": initial_wallet_balance,
            "pending_recovery_transfer_usdt": 0.0,
            "recovery_transfers": [],
            "wallet_metric": metric,
        }
        if baseline_context:
            baseline_payload["baseline_context"] = baseline_context
        self._save_recovery_wallet_baseline(baseline_path, baseline_payload)
        _log_event(
            "fixed_cycle_recovery_reload_wallet_baseline_captured",
            {
                **payload_base,
                "path": str(baseline_path),
                "initial_wallet_balance_usdt": initial_wallet_balance,
                "account_type": "UNIFIED",
                "coin": "USDT",
                "source": source,
            },
        )
        _log_event(
            "fixed_cycle_wallet_baseline_captured",
            {
                **baseline_payload,
                "path": str(baseline_path),
            },
        )
        if baseline_context == "recovery_active_trade":
            _log_event(
                "fixed_cycle_recovery_wallet_baseline_captured_active_trade",
                {
                    **baseline_payload,
                    "path": str(baseline_path),
                },
            )
        return baseline_payload

    def _ensure_recovery_wallet_baseline(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> dict[str, Any] | None:
        baseline_path = self._recovery_wallet_baseline_path()
        state = runtime_state.strategy_state
        trade_block_id = state.get("trade_block_id") or ""
        baseline = self._load_recovery_wallet_baseline(baseline_path) if baseline_path else None
        has_flat_snapshot = self._is_flat_snapshot_for_baseline(snapshot, runtime_state)
        cycle_state = self._ensure_cycle_state(runtime_state)
        recovery_required = bool(
            state.get("recovery_required") or cycle_state.get("recovery_required")
        )
        if baseline and baseline.get("trade_block_id") == trade_block_id:
            loaded_for = state.get("recovery_wallet_baseline_loaded_for")
            if trade_block_id and loaded_for != trade_block_id:
                _log_event(
                    "fixed_cycle_recovery_reload_wallet_baseline_loaded",
                    {
                        "symbol": self.config.symbol,
                        "bot_name": self.config.bot_name,
                        "trade_block_id": trade_block_id,
                        "path": str(baseline_path),
                        "initial_wallet_balance_usdt": baseline.get("initial_wallet_balance_usdt"),
                    },
                )
                _log_event(
                    "fixed_cycle_wallet_baseline_loaded",
                    {
                        "symbol": self.config.symbol,
                        "bot_name": self.config.bot_name,
                        "trade_block_id": trade_block_id,
                        "path": str(baseline_path),
                        "initial_wallet_balance_usdt": baseline.get("initial_wallet_balance_usdt"),
                    },
                )
                state["recovery_wallet_baseline_loaded_for"] = trade_block_id
            return baseline
        if has_flat_snapshot or recovery_required:
            baseline_context = (
                "recovery_active_trade" if recovery_required else "start_of_trade_flat"
            )
            return self._capture_recovery_wallet_baseline(
                trade_block_id,
                snapshot,
                runtime_state,
                context,
                baseline_context=baseline_context,
            )
        _log_event(
            "fixed_cycle_wallet_baseline_missing_active_trade_blocked",
            {
                "symbol": self.config.symbol,
                "bot_name": self.config.bot_name,
                "trade_block_id": trade_block_id,
                "has_positions": float(snapshot.long_qty or 0.0) > 0.0
                or float(snapshot.short_qty or 0.0) > 0.0,
                "active_runtime_orders": bool(runtime_state.active_orders),
                "active_snapshot_orders": bool(snapshot.active_orders),
                "recovery_required": bool(state.get("recovery_required")),
                "recovery_reload_pending": bool(
                    self._get_recovery_reload_state_value(
                        state, cycle_state, "recovery_reload_long_pending", default=False
                    )
                    or self._get_recovery_reload_state_value(
                        state, cycle_state, "recovery_reload_short_pending", default=False
                    )
                ),
            },
        )
        return None

    def _recovery_wallet_transfer_already_completed(
        self, baseline: dict[str, Any], cycle_index: int
    ) -> bool:
        transfers = baseline.get("recovery_transfers") or []
        for transfer in transfers:
            if (
                int(transfer.get("cycle_index") or 0) == cycle_index
                and str(transfer.get("status") or "").lower() == "completed"
            ):
                return True
        return False

    def _find_latest_wallet_transfer_success_event(
        self,
        log_path: Path | None,
        start_time: datetime,
        bot_name: str,
        expected_transfer_id: str | None = None,
    ) -> dict[str, Any] | None:
        if not log_path or not log_path.exists():
            return None
        entry: dict[str, Any] | None = None
        try:
            for line in log_path.read_text(encoding="utf-8").splitlines():
                if not line.strip():
                    continue
                try:
                    record = json.loads(line)
                except Exception:
                    continue
                timestamp_raw = record.get("timestamp")
                if not timestamp_raw:
                    continue
                try:
                    occurred = datetime.fromisoformat(timestamp_raw)
                except ValueError:
                    continue
                if occurred.tzinfo is None:
                    occurred = occurred.replace(tzinfo=timezone.utc)
                if occurred < start_time:
                    continue
                if record.get("event") != "wallet_transfer_success":
                    continue
                payload = {
                    key: value
                    for key, value in record.items()
                    if key not in {"event", "timestamp"}
                }
                if payload.get("bot_name") != bot_name or payload.get("direction") != "refill":
                    continue
                if expected_transfer_id and str(payload.get("transfer_id") or "").strip() != expected_transfer_id:
                    continue
                entry = payload
        except Exception:
            return None
        return entry

    @staticmethod
    def _recovery_wallet_transfer_tracking_fields() -> tuple[str, ...]:
        return (
            "recovery_reload_transfer_signature",
            "recovery_reload_transfer_status",
            "recovery_reload_transfer_started_at",
            "recovery_reload_transfer_completed_at",
            "recovery_reload_transfer_id",
            "recovery_reload_transfer_amount_usdt",
            "recovery_reload_transfer_cycle_index",
            "recovery_reload_transfer_target_bot_name",
            "recovery_reload_transfer_target_profile",
            "recovery_reload_transfer_source_account_label",
            "recovery_reload_transfer_target_account_label",
            "recovery_reload_transfer_source_config_origin",
            "recovery_reload_transfer_exchange_transfer_id",
        )

    def _sync_recovery_wallet_transfer_tracking_state(
        self,
        state: dict[str, Any],
        baseline: dict[str, Any],
    ) -> None:
        for field in self._recovery_wallet_transfer_tracking_fields():
            if field in baseline:
                state[field] = baseline.get(field)
            else:
                state.pop(field, None)

        status = str(baseline.get("recovery_reload_transfer_status") or "").strip().upper()
        state["recovery_reload_transfer_required"] = status != "COMPLETED"
        state["recovery_reload_transfer_submitted"] = status in {
            "IN_PROGRESS",
            "SUBMITTED",
            "COMPLETED",
            "CHECK_REQUIRED",
            "UNKNOWN",
        }
        state["recovery_reload_transfer_confirmed"] = status == "COMPLETED"
        amount = baseline.get("recovery_reload_transfer_amount_usdt")
        if amount is not None:
            state["recovery_reload_transfer_amount_usdt"] = amount
        transfer_id = baseline.get("recovery_reload_transfer_id")
        if transfer_id:
            state["recovery_reload_transfer_exchange_transfer_id"] = transfer_id
        if status in {"WAITING_FOR_WALLET_CONFIG", "WAITING_FOR_FUNDS", "CHECK_REQUIRED", "UNKNOWN"}:
            state["recovery_reload_transfer_error"] = str(status).lower()
        elif status == "COMPLETED":
            state.pop("recovery_reload_transfer_error", None)

    def _set_recovery_wallet_transfer_tracking(
        self,
        baseline: dict[str, Any],
        state: dict[str, Any],
        **fields: Any,
    ) -> None:
        for key, value in fields.items():
            baseline[key] = value
        self._sync_recovery_wallet_transfer_tracking_state(state, baseline)

    def _recovery_wallet_transfer_lock_path(self) -> Path | None:
        baseline_path = self._recovery_wallet_baseline_path()
        if not baseline_path:
            return None
        return baseline_path.with_name(f"{baseline_path.name}.transfer.lock")

    @contextmanager
    def _recovery_wallet_transfer_lock(self):
        lock_path = self._recovery_wallet_transfer_lock_path()
        if not lock_path:
            yield None
            return
        lock_path.parent.mkdir(parents=True, exist_ok=True)
        handle = lock_path.open("a+", encoding="utf-8")
        try:
            fcntl.flock(handle.fileno(), fcntl.LOCK_EX)
            yield lock_path
        finally:
            try:
                fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
            finally:
                handle.close()

    def _build_recovery_wallet_transfer_signature(
        self,
        *,
        trade_block_id: str | None,
        recovery_reload_id: str | None,
        cycle_index: int,
        target_bot_name: str,
        target_profile: str | None,
        source_account_label: str | None,
        target_account_label: str | None,
        transfer_amount_usdt: float,
    ) -> str:
        signature_payload = {
            "trade_block_id": str(trade_block_id or ""),
            "recovery_reload_id": str(recovery_reload_id or ""),
            "cycle_index": int(cycle_index),
            "direction": "refill",
            "target_bot_name": str(target_bot_name or ""),
            "target_profile": str(target_profile or ""),
            "source_account_label": str(source_account_label or ""),
            "target_account_label": str(target_account_label or ""),
            "transfer_amount_usdt": self._format_transfer_amount_for_executor(
                transfer_amount_usdt
            ),
        }
        serialized = json.dumps(
            signature_payload,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        )
        return hashlib.sha256(serialized.encode("utf-8")).hexdigest()

    def _build_recovery_wallet_transfer_id(self, signature: str) -> str:
        return str(uuid5(NAMESPACE_URL, f"fixed-cycle-recovery-wallet-transfer:{signature}"))

    def _resolve_recovery_wallet_transfer_context(
        self,
        runtime_state: RuntimeState,
        cycle_index: int,
        transfer_amount_usdt: float,
    ) -> dict[str, Any]:
        executor_path, log_path = self._wallet_transfer_executor_paths()
        source_group_dir, group_origin = self._wallet_transfer_source_group_dir()
        config_path, config_origin = (
            self._resolve_wallet_transfer_config_path(source_group_dir)
            if source_group_dir
            else (None, None)
        )
        target_profile = self._wallet_transfer_profile_name()
        source_config_origin = group_origin
        if config_origin:
            source_config_origin = f"{group_origin}:{config_origin}"
        payload_base = {
            "symbol": self.config.symbol,
            "bot_name": self.config.bot_name,
            "cycle_index": cycle_index,
            "transfer_amount_usdt": transfer_amount_usdt,
            "group_origin": group_origin,
            "source_config_origin": source_config_origin,
            "executor_path_exists": bool(executor_path and executor_path.exists()),
            "config_path_exists": bool(config_path and config_path.exists()),
            "target_bot_name": self.config.bot_name,
            "target_profile": target_profile,
        }
        if not executor_path or not config_path or not config_path.exists():
            return {
                "ok": False,
                "reason": "executor_or_config_missing",
                "executor_path": executor_path,
                "log_path": log_path,
                "config_path": config_path,
                "group_origin": group_origin,
                "source_config_origin": source_config_origin,
                "target_profile": target_profile,
                "payload_base": payload_base,
                "source_account_label": None,
                "target_account_label": self.config.bot_name,
            }
        inspection = self._inspect_wallet_transfer_config(
            config_path,
            target_bot_name=str(self.config.bot_name or ""),
            target_profile=target_profile,
            source_config_origin=source_config_origin,
        )
        if not inspection.get("ok"):
            return {
                "ok": False,
                "reason": str(inspection.get("reason") or "config_inspection_failed"),
                "executor_path": executor_path,
                "log_path": log_path,
                "config_path": config_path,
                "group_origin": group_origin,
                "source_config_origin": source_config_origin,
                "target_profile": target_profile,
                "payload_base": payload_base,
                "source_account_label": inspection.get("source_account_label"),
                "target_account_label": inspection.get("target_account_label")
                or self.config.bot_name,
            }
        return {
            "ok": True,
            "reason": None,
            "executor_path": executor_path,
            "log_path": log_path,
            "config_path": config_path,
            "group_origin": group_origin,
            "source_config_origin": source_config_origin,
            "target_profile": target_profile,
            "inspection": inspection,
            "payload_base": payload_base,
            "source_account_label": inspection.get("source_account_label"),
            "target_account_label": inspection.get("target_account_label"),
        }

    def _cancel_pre_recovery_reload_orders(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        recovery_cycle_index: int,
    ) -> bool:
        """
        Cancel all stale pre-recovery exit and cycle orders before submitting
        Recovery-Reload-Orders.
        """
        state = runtime_state.strategy_state
        symbol = snapshot.symbol or self.config.symbol
        trade_block_id = state.get("trade_block_id")
        recovery_reload_id = state.get("recovery_reload_id")
        _, profile_dir = self._resolve_recovery_wallet_state_paths()
        profile = profile_dir.name if profile_dir else None
        # aktive Zwecke vor Cancel
        active_runtime_purposes_before = sorted(
            {
                str(getattr(order, "purpose", "") or "")
                for order in runtime_state.active_orders.values()
                if not self._is_terminal_order_status(getattr(order, "status", None))
            }
        )
        active_snapshot_purposes_before = sorted(
            {
                str(getattr(order, "purpose", "") or "")
                for order in getattr(snapshot, "active_orders", []) or []
                if not self._is_terminal_order_status(getattr(order, "status", None))
            }
        )
        active_order_purposes_before = sorted(
            set(active_runtime_purposes_before) | set(active_snapshot_purposes_before)
        )
        _log_event(
            "fixed_cycle_recovery_pre_reload_cancel_started",
            {
                "symbol": symbol,
                "bot_name": self.config.bot_name,
                "profile": profile,
                "trade_block_id": trade_block_id,
                "recovery_reload_id": recovery_reload_id,
                "recovery_cycle_index": recovery_cycle_index,
                "active_order_purposes_before": active_order_purposes_before,
            },
        )

        exit_purposes = {str(p) for p in self._exit_purposes()}
        cycle_purposes = {str(p) for p in self._all_cycle_purposes()}
        recovery_purposes = {
            str(self.RECOVERY_RELOAD_LONG_ENTRY),
            str(self.RECOVERY_RELOAD_SHORT_ENTRY),
            str(self.RECOVERY_REFILL_LONG),
            str(self.RECOVERY_REFILL_SHORT),
        }
        order_manager = getattr(context, "order_manager", None)
        canceled_client_ids: list[str] = []
        canceled_exchange_ids: list[str] = []
        canceled_purposes: list[str] = []

        for client_id, order in list(runtime_state.active_orders.items()):
            purpose_raw = getattr(order, "purpose", None)
            if not purpose_raw:
                continue
            purpose = str(purpose_raw)
            purpose_upper = purpose.upper()
            if purpose_upper in recovery_purposes:
                # Recovery-Reload-Orders selbst nie canceln.
                continue
            if purpose_upper not in exit_purposes and purpose_upper not in cycle_purposes:
                continue
            status = str(getattr(order, "status", "") or "").upper()
            if self._is_terminal_order_status(status):
                _log_event(
                    "fixed_cycle_recovery_pre_reload_cancel_order_missing_or_terminal",
                    {
                        "symbol": symbol,
                        "bot_name": self.config.bot_name,
                        "profile": profile,
                        "trade_block_id": trade_block_id,
                        "recovery_reload_id": recovery_reload_id,
                        "recovery_cycle_index": recovery_cycle_index,
                        "purpose": purpose,
                        "client_order_id": client_id,
                        "exchange_order_id": getattr(order, "exchange_order_id", None),
                        "reason": "terminal_status",
                    },
                )
                continue
            metadata = getattr(order, "metadata", None) or {}
            exchange_order_id = str(getattr(order, "exchange_order_id", "") or "").strip()
            payload_base = {
                "symbol": symbol,
                "bot_name": self.config.bot_name,
                "profile": profile,
                "trade_block_id": trade_block_id,
                "recovery_reload_id": recovery_reload_id,
                "recovery_cycle_index": recovery_cycle_index,
                "purpose": purpose,
                "client_order_id": client_id,
                "exchange_order_id": exchange_order_id,
                "active_order_purposes_before": active_order_purposes_before,
            }
            # Trading-Stop-basierte Exit-Orders (LONG_TP_EXIT/SHORT_SL_EXIT) werden als
            # positionsgebundene TP/SL über /v5/position/trading-stop verwaltet und
            # besitzen bewusst keine klassische exchange_order_id im Runtime-State.
            # Sie werden im Anschluss an den Recovery-Reload über den Exit-Rebuild
            # neu gesetzt und dürfen den Pre-Reload-Cancel nicht blockieren.
            if metadata.get("trading_stop_api"):
                _log_event(
                    "fixed_cycle_recovery_pre_reload_trading_stop_exit_skipped",
                    {
                        **payload_base,
                        "reason": "trading_stop_exit_managed_via_position_trading_stop",
                    },
                )
                continue
            _log_event(
                "fixed_cycle_recovery_pre_reload_cancel_order_requested",
                payload_base,
            )
            if not exchange_order_id or not order_manager:
                _log_event(
                    "fixed_cycle_recovery_pre_reload_cancel_order_missing_or_terminal",
                    {**payload_base, "reason": "missing_exchange_order_id_or_manager"},
                )
                _log_event(
                    "fixed_cycle_recovery_reload_blocked_waiting_for_pre_reload_cancel",
                    payload_base,
                )
                return False
            try:
                canceled = order_manager.cancel_order(
                    exchange_order_id,
                    symbol=symbol,
                    category=self.config.category,
                )
            except Exception as exc:
                _log_event(
                    "fixed_cycle_recovery_pre_reload_cancel_order_missing_or_terminal",
                    {**payload_base, "reason": str(exc)},
                )
                _log_event(
                    "fixed_cycle_recovery_reload_blocked_waiting_for_pre_reload_cancel",
                    payload_base,
                )
                return False
            if not canceled:
                _log_event(
                    "fixed_cycle_recovery_pre_reload_cancel_order_missing_or_terminal",
                    {**payload_base, "reason": "cancel_failed"},
                )
                _log_event(
                    "fixed_cycle_recovery_reload_blocked_waiting_for_pre_reload_cancel",
                    payload_base,
                )
                return False
            canceled_client_ids.append(str(client_id))
            if exchange_order_id:
                canceled_exchange_ids.append(exchange_order_id)
            canceled_purposes.append(purpose)
            runtime_state.active_orders.pop(client_id, None)
            if exchange_order_id:
                runtime_state.exchange_to_client_id.pop(exchange_order_id, None)
            _log_event(
                "fixed_cycle_recovery_pre_reload_cancel_order_confirmed",
                {
                    **payload_base,
                    "reason": "cancel_confirmed",
                },
            )

        active_runtime_purposes_after = sorted(
            {
                str(getattr(order, "purpose", "") or "")
                for order in runtime_state.active_orders.values()
                if not self._is_terminal_order_status(getattr(order, "status", None))
            }
        )
        active_snapshot_purposes_after = sorted(
            {
                str(getattr(order, "purpose", "") or "")
                for order in getattr(snapshot, "active_orders", []) or []
                if not self._is_terminal_order_status(getattr(order, "status", None))
            }
        )
        active_order_purposes_after = sorted(
            set(active_runtime_purposes_after) | set(active_snapshot_purposes_after)
        )
        _log_event(
            "fixed_cycle_recovery_pre_reload_cancel_completed",
            {
                "symbol": symbol,
                "bot_name": self.config.bot_name,
                "profile": profile,
                "trade_block_id": trade_block_id,
                "recovery_reload_id": recovery_reload_id,
                "recovery_cycle_index": recovery_cycle_index,
                "active_order_purposes_before": active_order_purposes_before,
                "active_order_purposes_after": active_order_purposes_after,
                "canceled_order_purposes": sorted(canceled_purposes),
                "canceled_order_ids": canceled_client_ids,
                "canceled_exchange_order_ids": canceled_exchange_ids,
            },
        )
        return True

    def _current_recovery_reference_cycle_index(
        self, runtime_state: RuntimeState
    ) -> int:
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        for key in ("recovery_reference_cycle_index",):
            value = int(state.get(key) or cycle_state.get(key) or 0)
            if value > 0:
                return value
        return int(state.get("recovery_reference_cycle_index") or cycle_state.get("recovery_reference_cycle_index") or 0)

    def _execute_recovery_wallet_transfer(
        self,
        runtime_state: RuntimeState,
        transfer_context: dict[str, Any],
        transfer_id: str,
        *,
        context: StrategyContext | None = None,
        baseline: dict[str, Any] | None = None,
        cycle_index: int | None = None,
    ) -> tuple[bool, str | None, str, dict[str, Any] | None]:
        state = runtime_state.strategy_state
        payload_base = dict(transfer_context.get("payload_base") or {})
        payload_base["transfer_id"] = transfer_id
        executor_path = transfer_context.get("executor_path")
        log_path = transfer_context.get("log_path")
        config_path = transfer_context.get("config_path")
        source_account_label = transfer_context.get("source_account_label")
        target_account_label = transfer_context.get("target_account_label")
        transfer_amount_usdt = float(payload_base.get("transfer_amount_usdt") or 0.0)
        if not transfer_context.get("ok"):
            _log_event(
                "recovery_wallet_transfer_blocked_missing_config",
                {
                    **payload_base,
                    "reason": transfer_context.get("reason"),
                    "source_account_label": source_account_label,
                    "target_account_label": target_account_label or self.config.bot_name,
                },
            )
            self._log_recovery_wallet_transfer_audit(
                context,
                "failed",
                runtime_state,
                baseline=baseline,
                cycle_index=cycle_index,
                transfer_context=transfer_context,
                transfer_amount_usdt=transfer_amount_usdt,
                transfer_required=True,
                transfer_id=transfer_id,
                extra={
                    "reason": transfer_context.get("reason") or "missing_config",
                    "failure_phase": "config_resolution",
                },
            )
            _log_event(
                "fixed_cycle_recovery_wallet_transfer_failed",
                {**payload_base, "reason": transfer_context.get("reason")},
            )
            state["recovery_reload_transfer_required"] = True
            state["recovery_reload_transfer_submitted"] = False
            state["recovery_reload_transfer_confirmed"] = False
            state["recovery_reload_transfer_error"] = "waiting_for_wallet_config"
            return False, transfer_id, "waiting_for_wallet_config", None
        _log_event(
            "recovery_wallet_transfer_config_resolved",
            {
                **payload_base,
                "source_account_label": source_account_label,
                "target_account_label": target_account_label,
            },
        )
        _log_event(
            "recovery_wallet_transfer_target_resolved",
            {
                **payload_base,
                "source_account_label": source_account_label,
                "target_account_label": target_account_label,
            },
        )
        if transfer_context.get("group_origin") == "paired_long_bot_group":
            _log_event(
                "recovery_wallet_transfer_using_master_funding_source",
                {
                    **payload_base,
                    "source_account_label": source_account_label,
                    "target_account_label": target_account_label,
                },
            )
        cmd = [
            sys.executable,
            str(executor_path),
            "--config-file",
            str(config_path),
            "--bot-name",
            self.config.bot_name,
            "--direction",
            "refill",
            "--amount",
            self._format_transfer_amount_for_executor(transfer_amount_usdt),
            "--coin",
            "USDT",
            "--transfer-id",
            transfer_id,
        ]
        self._log_recovery_wallet_transfer_audit(
            context,
            "started",
            runtime_state,
            baseline=baseline,
            cycle_index=cycle_index,
            transfer_context=transfer_context,
            transfer_amount_usdt=transfer_amount_usdt,
            transfer_required=True,
            transfer_id=transfer_id,
            extra={"cmd": cmd, "executor_log_path": str(log_path) if log_path else None},
        )
        _log_event("fixed_cycle_recovery_wallet_transfer_started", {**payload_base, "cmd": cmd})
        start_time = datetime.now(timezone.utc)
        try:
            result = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                cwd=PROJECT_ROOT,
            )
        except Exception as exc:
            self._log_recovery_wallet_transfer_audit(
                context,
                "failed",
                runtime_state,
                baseline=baseline,
                cycle_index=cycle_index,
                transfer_context=transfer_context,
                transfer_amount_usdt=transfer_amount_usdt,
                transfer_required=True,
                transfer_id=transfer_id,
                extra={
                    "reason": str(exc),
                    "failure_phase": "subprocess",
                    "error": str(exc),
                },
            )
            _log_event(
                "fixed_cycle_recovery_wallet_transfer_failed",
                {**payload_base, "error": str(exc), "phase": "subprocess"},
            )
            state["recovery_reload_transfer_required"] = True
            state["recovery_reload_transfer_submitted"] = True
            state["recovery_reload_transfer_confirmed"] = False
            state["recovery_reload_transfer_error"] = "check_required"
            _log_event(
                "recovery_wallet_transfer_unknown_result_requires_manual_check",
                {**payload_base, "reason": "subprocess_exception"},
            )
            return False, transfer_id, "check_required", None
        stderr = result.stderr or ""
        stdout = result.stdout or ""
        failure = (
            result.returncode != 0
            or "ERROR:" in stderr
            or "Transfer failed" in stderr
        )
        transfer_event = self._find_latest_wallet_transfer_success_event(
            log_path,
            start_time,
            self.config.bot_name,
            expected_transfer_id=transfer_id,
        )
        if failure and transfer_event:
            failure = False
        if failure:
            stderr_lower = stderr.lower()
            stdout_lower = stdout.lower()
            insufficient_balance = (
                "131212" in stderr
                or "131212" in stdout
                or "insufficient balance" in stderr_lower
                or "insufficient balance" in stdout_lower
            )
            failure_reason = "waiting_for_funds" if insufficient_balance else "check_required"
            self._log_recovery_wallet_transfer_audit(
                context,
                "failed",
                runtime_state,
                baseline=baseline,
                cycle_index=cycle_index,
                transfer_context=transfer_context,
                transfer_amount_usdt=transfer_amount_usdt,
                transfer_required=True,
                transfer_id=transfer_id,
                extra={
                    "reason": failure_reason,
                    "failure_phase": "executor",
                    "returncode": result.returncode,
                    "stderr": self._truncate_recovery_wallet_transfer_log_text(stderr),
                    "stdout": self._truncate_recovery_wallet_transfer_log_text(stdout),
                },
            )
            _log_event(
                "fixed_cycle_recovery_wallet_transfer_failed",
                {
                    **payload_base,
                    "returncode": result.returncode,
                    "stderr": stderr,
                    "stdout": stdout,
                },
            )
            state["recovery_reload_transfer_required"] = True
            state["recovery_reload_transfer_submitted"] = True
            state["recovery_reload_transfer_confirmed"] = False
            if insufficient_balance:
                state["recovery_reload_transfer_error"] = "waiting_for_funds"
                return False, transfer_id, "waiting_for_funds", None
            state["recovery_reload_transfer_error"] = "check_required"
            _log_event(
                "recovery_wallet_transfer_unknown_result_requires_manual_check",
                {
                    **payload_base,
                    "returncode": result.returncode,
                    "stderr": stderr,
                    "stdout": stdout,
                },
            )
            return False, transfer_id, "check_required", None
        transfer_id = (
            str(transfer_event.get("transfer_id") or "").strip()
            if transfer_event
            else transfer_id
        )
        executor_audit = self._extract_executor_transfer_audit_fields(transfer_event)
        self._log_recovery_wallet_transfer_audit(
            context,
            "success",
            runtime_state,
            baseline=baseline,
            cycle_index=cycle_index,
            transfer_context=transfer_context,
            transfer_amount_usdt=transfer_amount_usdt,
            transfer_required=False,
            transfer_id=transfer_id,
            extra={
                **executor_audit,
                "executor_log_path": str(log_path) if log_path else None,
            },
        )
        # Erfolgreicher Transfer: Recovery-Reload-Transfer-State setzen (falls aktiv).
        if state.get("recovery_reload_id"):
            state["recovery_reload_transfer_required"] = False
            state["recovery_reload_transfer_submitted"] = True
            state["recovery_reload_transfer_confirmed"] = True
            state["recovery_reload_transfer_amount_usdt"] = transfer_amount_usdt
            state["recovery_reload_transfer_exchange_transfer_id"] = transfer_id
            state["recovery_reload_transfer_source_account"] = "FUND"
            state["recovery_reload_transfer_target_account"] = "UNIFIED"
            state["recovery_reload_transfer_source_config_origin"] = transfer_context.get(
                "source_config_origin"
            )
            state["recovery_reload_transfer_source_account_label"] = source_account_label
            state["recovery_reload_transfer_target_profile"] = transfer_context.get(
                "target_profile"
            )
            state["recovery_reload_transfer_target_account_label"] = target_account_label
            state["recovery_reload_transfer_config_path"] = str(config_path)
            state["recovery_reload_transfer_script_path"] = str(executor_path)
            state.pop("recovery_reload_transfer_error", None)
        return True, transfer_id, "completed", transfer_event

    def _reserve_recovery_wallet_and_watcher_baselines(
        self,
        baseline: dict[str, Any],
        transfer_amount_usdt: float,
        cycle_index: int,
        runtime_state: RuntimeState,
    ) -> bool:
        """
        Reserve the recovery wallet baseline and the profit/refill watcher
        baseline before executing a real wallet transfer.
        """
        state = runtime_state.strategy_state
        trade_block_id = state.get("trade_block_id")
        baseline_path = self._recovery_wallet_baseline_path()
        guard_path, guard = self._load_watchdog_wallet_guard()
        symbol = self.config.symbol
        bot_name = self.config.bot_name
        _, profile_dir = self._resolve_recovery_wallet_state_paths()
        profile = profile_dir.name if profile_dir else None

        initial_wallet_balance = float(baseline.get("initial_wallet_balance_usdt") or 0.0)
        total_transferred_before = float(baseline.get("total_transferred_recovery_usdt") or 0.0)
        pending_before = float(baseline.get("pending_recovery_transfer_usdt") or 0.0)
        allocated_before = float(baseline.get("allocated_wallet_balance_usdt") or 0.0)
        if allocated_before <= 0:
            allocated_before = initial_wallet_balance + total_transferred_before + pending_before

        watcher_start_before = float((guard or {}).get("start_wallet_usdt") or 0.0)
        watcher_baseline_before = float((guard or {}).get("baseline_wallet_usdt") or watcher_start_before)

        payload_base: dict[str, Any] = {
            "symbol": symbol,
            "bot_name": bot_name,
            "profile": profile,
            "trade_block_id": trade_block_id,
            "cycle_index": cycle_index,
            "transfer_amount_usdt": float(transfer_amount_usdt),
            "initial_wallet_balance_usdt": initial_wallet_balance,
            "total_transferred_recovery_usdt_before": total_transferred_before,
            "pending_recovery_transfer_usdt_before": pending_before,
            "allocated_wallet_balance_usdt_before": allocated_before,
            "watcher_baseline_before": watcher_baseline_before,
            "watcher_start_wallet_before": watcher_start_before,
        }
        _log_event("fixed_cycle_recovery_wallet_baseline_reservation_started", payload_base)

        if not baseline_path or not guard_path or guard is None:
            _log_event(
                "fixed_cycle_recovery_wallet_baseline_reservation_rolled_back",
                {
                    **payload_base,
                    "rollback_applied": False,
                    "reason": "baseline_or_guard_missing",
                },
            )
            return False

        # Idempotenz: bestehende Reservation für dieselbe (cycle_index, amount) respektieren.
        existing_pending = float(baseline.get("pending_recovery_transfer_usdt") or 0.0)
        existing_cycle = int(baseline.get("pending_recovery_transfer_cycle_index") or 0)
        if existing_pending == float(transfer_amount_usdt) and existing_cycle == int(cycle_index):
            _log_event(
                "fixed_cycle_recovery_wallet_baseline_reserved_before_transfer",
                {
                    **payload_base,
                    "allocated_wallet_balance_usdt_after": baseline.get("allocated_wallet_balance_usdt"),
                    "pending_recovery_transfer_usdt": existing_pending,
                    "rollback_applied": False,
                    "reason": "existing_reservation_reused",
                },
            )
            return True

        # Kopien für potentiellen Rollback sichern.
        original_baseline = json.loads(json.dumps(baseline, ensure_ascii=False))
        original_guard = json.loads(json.dumps(guard, ensure_ascii=False))

        baseline["pending_recovery_transfer_usdt"] = float(transfer_amount_usdt)
        baseline["pending_recovery_transfer_cycle_index"] = int(cycle_index)
        allocated_after = initial_wallet_balance + total_transferred_before + float(transfer_amount_usdt)
        baseline["allocated_wallet_balance_usdt"] = allocated_after

        guard["pending_recovery_transfer_usdt"] = float(transfer_amount_usdt)
        guard["pending_recovery_transfer_cycle_index"] = int(cycle_index)
        guard["start_wallet_usdt"] = watcher_start_before + float(transfer_amount_usdt)
        guard["baseline_wallet_usdt"] = watcher_baseline_before + float(transfer_amount_usdt)
        guard["updated_at"] = datetime.now(timezone.utc).isoformat()

        watcher_baseline_after = float(guard.get("baseline_wallet_usdt") or 0.0)

        try:
            self._save_recovery_wallet_baseline(baseline_path, baseline)
            _log_event(
                "fixed_cycle_recovery_wallet_baseline_reserved_before_transfer",
                {
                    **payload_base,
                    "allocated_wallet_balance_usdt_after": allocated_after,
                    "pending_recovery_transfer_usdt": float(transfer_amount_usdt),
                    "rollback_applied": False,
                    "reason": "reservation_persisted",
                },
            )
            self._save_watchdog_wallet_guard(guard_path, guard)
            _log_event(
                "fixed_cycle_profit_watcher_baseline_reserved_before_transfer",
                {
                    **payload_base,
                    "watcher_baseline_after": watcher_baseline_after,
                    "watcher_start_wallet_after": guard.get("start_wallet_usdt"),
                },
            )
        except Exception as exc:
            # Best-effort-Rollback beider Dateien.
            self._save_recovery_wallet_baseline(baseline_path, original_baseline)
            self._save_watchdog_wallet_guard(guard_path, original_guard)
            _log_event(
                "fixed_cycle_recovery_wallet_baseline_reservation_rolled_back",
                {
                    **payload_base,
                    "rollback_applied": True,
                    "reason": f"reservation_persist_failed:{exc}",
                },
            )
            _log_event(
                "fixed_cycle_profit_watcher_baseline_reservation_rolled_back",
                {
                    **payload_base,
                    "rollback_applied": True,
                    "reason": f"reservation_persist_failed:{exc}",
                },
            )
            return False

        return True

    def _rollback_recovery_wallet_and_watcher_baseline_reservation(
        self,
        baseline: dict[str, Any],
        cycle_index: int,
        runtime_state: RuntimeState,
        *,
        reason: str,
    ) -> None:
        state = runtime_state.strategy_state
        trade_block_id = state.get("trade_block_id")
        baseline_path = self._recovery_wallet_baseline_path()
        guard_path, guard = self._load_watchdog_wallet_guard()
        symbol = self.config.symbol
        bot_name = self.config.bot_name
        _, profile_dir = self._resolve_recovery_wallet_state_paths()
        profile = profile_dir.name if profile_dir else None

        initial_wallet_balance = float(baseline.get("initial_wallet_balance_usdt") or 0.0)
        total_transferred_before = float(baseline.get("total_transferred_recovery_usdt") or 0.0)
        pending_before = float(baseline.get("pending_recovery_transfer_usdt") or 0.0)
        allocated_before = float(baseline.get("allocated_wallet_balance_usdt") or 0.0)
        if allocated_before <= 0:
            allocated_before = initial_wallet_balance + total_transferred_before + pending_before

        watcher_start_before = float((guard or {}).get("start_wallet_usdt") or 0.0)
        watcher_baseline_before = float((guard or {}).get("baseline_wallet_usdt") or watcher_start_before)

        payload_base: dict[str, Any] = {
            "symbol": symbol,
            "bot_name": bot_name,
            "profile": profile,
            "trade_block_id": trade_block_id,
            "cycle_index": cycle_index,
            "initial_wallet_balance_usdt": initial_wallet_balance,
            "total_transferred_recovery_usdt_before": total_transferred_before,
            "pending_recovery_transfer_usdt_before": pending_before,
            "allocated_wallet_balance_usdt_before": allocated_before,
            "watcher_baseline_before": watcher_baseline_before,
            "watcher_start_wallet_before": watcher_start_before,
            "reason": reason,
        }

        # Baseline-Rollback.
        if baseline_path:
            baseline["pending_recovery_transfer_usdt"] = 0.0
            baseline["pending_recovery_transfer_cycle_index"] = None
            baseline["allocated_wallet_balance_usdt"] = initial_wallet_balance + total_transferred_before
            try:
                self._save_recovery_wallet_baseline(baseline_path, baseline)
                _log_event(
                    "fixed_cycle_recovery_wallet_baseline_reservation_rolled_back",
                    {
                        **payload_base,
                        "rollback_applied": True,
                        "allocated_wallet_balance_usdt_after": baseline.get(
                            "allocated_wallet_balance_usdt"
                        ),
                    },
                )
            except Exception:
                _log_event(
                    "fixed_cycle_recovery_wallet_baseline_reservation_rolled_back",
                    {
                        **payload_base,
                        "rollback_applied": False,
                        "reason": f"{reason}:baseline_rollback_failed",
                    },
                )

        # Watcher-Rollback.
        if guard_path and guard is not None:
            pending_amount = float(guard.get("pending_recovery_transfer_usdt") or 0.0)
            guard["pending_recovery_transfer_usdt"] = 0.0
            guard["pending_recovery_transfer_cycle_index"] = None
            # Start-/Baseline-Wallet nur zurücksetzen, falls eine Reservation vorgenommen wurde.
            if pending_amount > 0:
                guard["start_wallet_usdt"] = max(0.0, watcher_start_before - pending_amount)
                guard["baseline_wallet_usdt"] = max(0.0, watcher_baseline_before - pending_amount)
            guard["updated_at"] = datetime.now(timezone.utc).isoformat()
            try:
                self._save_watchdog_wallet_guard(guard_path, guard)
                _log_event(
                    "fixed_cycle_profit_watcher_baseline_reservation_rolled_back",
                    {
                        **payload_base,
                        "rollback_applied": True,
                        "watcher_baseline_after": guard.get("baseline_wallet_usdt"),
                        "watcher_start_wallet_after": guard.get("start_wallet_usdt"),
                    },
                )
            except Exception:
                _log_event(
                    "fixed_cycle_profit_watcher_baseline_reservation_rolled_back",
                    {
                        **payload_base,
                        "rollback_applied": False,
                        "reason": f"{reason}:watcher_rollback_failed",
                    },
                )

    def _ensure_recovery_wallet_transfer(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        cycle_index: int,
    ) -> bool:
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        baseline = self._ensure_recovery_wallet_baseline(snapshot, runtime_state, context)
        self._set_recovery_lifecycle_state(
            state,
            "WAITING_WALLET_TRANSFER",
            event="recovery_wallet_transfer_check_started",
            extra={"cycle_index": cycle_index},
        )
        if not baseline:
            state["recovery_wallet_transfer_pending"] = True
            state["recovery_reload_transfer_required"] = True
            state["recovery_reload_transfer_submitted"] = False
            state["recovery_reload_transfer_confirmed"] = False
            state["recovery_reload_transfer_error"] = "baseline_missing"
            _log_event(
                "fixed_cycle_recovery_refill_blocked_by_wallet_baseline",
                {
                    "symbol": self.config.symbol,
                    "bot_name": self.config.bot_name,
                    "cycle_index": cycle_index,
                    "trade_block_id": state.get("trade_block_id"),
                },
            )
            self._set_recovery_lifecycle_state(
                state,
                "FAILED",
                event="recovery_wallet_transfer_baseline_missing",
                extra={"cycle_index": cycle_index},
            )
            return False
        if self._recovery_wallet_transfer_already_completed(baseline, cycle_index):
            state["recovery_wallet_transfer_pending"] = False
            self._log_recovery_wallet_transfer_audit(
                context,
                "skipped",
                runtime_state,
                baseline=baseline,
                cycle_index=cycle_index,
                transfer_required=False,
                extra={"skip_reason": "already_completed"},
            )
            _log_event(
                "fixed_cycle_recovery_wallet_transfer_already_completed",
                {
                    "symbol": self.config.symbol,
                    "bot_name": self.config.bot_name,
                    "cycle_index": cycle_index,
                    "trade_block_id": state.get("trade_block_id"),
                },
            )
            self._set_recovery_lifecycle_state(
                state,
                "WALLET_TRANSFER_COMPLETED",
                event="recovery_wallet_transfer_already_completed",
                extra={"cycle_index": cycle_index},
            )
            # Bereits abgeschlossener Transfer: Reload-Transfer-State aus Baseline ableiten.
            if state.get("recovery_reload_id"):
                transfers = baseline.get("recovery_transfers") or []
                matching = [
                    t
                    for t in transfers
                    if int(t.get("cycle_index") or 0) == cycle_index
                    and str(t.get("status") or "").lower() == "completed"
                ]
                record = matching[-1] if matching else None
                amount = float(record.get("amount_usdt") or 0.0) if record else float(
                    baseline.get("initial_wallet_balance_usdt") or 0.0
                )
                state["recovery_reload_transfer_required"] = False
                state["recovery_reload_transfer_submitted"] = True
                state["recovery_reload_transfer_confirmed"] = True
                state["recovery_reload_transfer_amount_usdt"] = amount
                state["recovery_reload_transfer_exchange_transfer_id"] = (
                    record.get("transfer_id") if record else None
                )
                state["recovery_reload_transfer_source_account"] = "FUND"
                state["recovery_reload_transfer_target_account"] = "UNIFIED"
                executor_path, _ = self._wallet_transfer_executor_paths()
                if executor_path:
                    state["recovery_reload_transfer_script_path"] = str(executor_path)
                state.pop("recovery_reload_transfer_error", None)
            return True
        transfer_required_payload = {
            "symbol": self.config.symbol,
            "bot_name": self.config.bot_name,
            "cycle_index": cycle_index,
            "trade_block_id": state.get("trade_block_id"),
            "initial_wallet_balance_usdt": baseline.get("initial_wallet_balance_usdt"),
        }
        _log_event(
            "fixed_cycle_recovery_wallet_transfer_required",
            transfer_required_payload,
        )
        initial_wallet_balance = float(baseline.get("initial_wallet_balance_usdt") or 0.0)
        total_transferred_before = float(baseline.get("total_transferred_recovery_usdt") or 0.0)
        pending_before = float(baseline.get("pending_recovery_transfer_usdt") or 0.0)
        allocated_before = float(baseline.get("allocated_wallet_balance_usdt") or 0.0)
        if allocated_before <= 0:
            allocated_before = initial_wallet_balance + total_transferred_before + pending_before
        transfer_amount_usdt = allocated_before
        self._log_recovery_wallet_transfer_audit(
            context,
            "planned",
            runtime_state,
            baseline=baseline,
            cycle_index=cycle_index,
            transfer_amount_usdt=transfer_amount_usdt,
            transfer_required=True,
            extra={
                "total_transferred_recovery_usdt_before": total_transferred_before,
                "pending_recovery_transfer_usdt_before": pending_before,
                "allocated_wallet_balance_usdt_before": allocated_before,
            },
        )
        _log_event(
            "fixed_cycle_recovery_next_transfer_amount_resolved",
            {
                **transfer_required_payload,
                "total_transferred_recovery_usdt_before": total_transferred_before,
                "pending_recovery_transfer_usdt": pending_before,
                "allocated_wallet_balance_usdt_before": allocated_before,
                "resolved_transfer_amount_usdt": transfer_amount_usdt,
            },
        )
        if transfer_amount_usdt <= 0:
            self._log_recovery_wallet_transfer_audit(
                context,
                "failed",
                runtime_state,
                baseline=baseline,
                cycle_index=cycle_index,
                transfer_amount_usdt=transfer_amount_usdt,
                transfer_required=True,
                extra={
                    "reason": "invalid_transfer_amount",
                    "failure_phase": "amount_resolution",
                },
            )
            _log_event(
                "fixed_cycle_recovery_wallet_transfer_failed",
                {
                    **transfer_required_payload,
                    "reason": "invalid_transfer_amount",
                },
            )
            _log_event(
                "fixed_cycle_recovery_refill_blocked_waiting_for_wallet_transfer",
                transfer_required_payload,
            )
            state["recovery_wallet_transfer_pending"] = True
            state["recovery_reload_transfer_required"] = True
            state["recovery_reload_transfer_submitted"] = False
            state["recovery_reload_transfer_confirmed"] = False
            state["recovery_reload_transfer_error"] = "invalid_transfer_amount"
            self._set_recovery_lifecycle_state(
                state,
                "FAILED",
                event="recovery_wallet_transfer_invalid_amount",
                extra={"cycle_index": cycle_index},
            )
            return False
        transfer_context = self._resolve_recovery_wallet_transfer_context(
            runtime_state,
            cycle_index,
            transfer_amount_usdt,
        )
        baseline_path = self._recovery_wallet_baseline_path()
        transfer_signature: str | None = None
        transfer_id = str(state.get("recovery_reload_transfer_id") or "").strip()
        reservation_applied = False
        if transfer_context.get("ok"):
            transfer_signature = self._build_recovery_wallet_transfer_signature(
                trade_block_id=state.get("trade_block_id"),
                recovery_reload_id=state.get("recovery_reload_id"),
                cycle_index=cycle_index,
                target_bot_name=str(self.config.bot_name or ""),
                target_profile=transfer_context.get("target_profile"),
                source_account_label=transfer_context.get("source_account_label"),
                target_account_label=transfer_context.get("target_account_label"),
                transfer_amount_usdt=transfer_amount_usdt,
            )
        with self._recovery_wallet_transfer_lock():
            if baseline_path:
                locked_baseline = self._load_recovery_wallet_baseline(baseline_path)
                if isinstance(locked_baseline, dict):
                    baseline = locked_baseline
            if self._recovery_wallet_transfer_already_completed(baseline, cycle_index):
                self._sync_recovery_wallet_transfer_tracking_state(state, baseline)
                state["recovery_wallet_transfer_pending"] = False
                self._log_recovery_wallet_transfer_audit(
                    context,
                    "skipped",
                    runtime_state,
                    baseline=baseline,
                    cycle_index=cycle_index,
                    transfer_context=transfer_context,
                    transfer_required=False,
                    transfer_id=str(
                        baseline.get("recovery_reload_transfer_id")
                        or baseline.get("recovery_reload_transfer_exchange_transfer_id")
                        or ""
                    ).strip()
                    or None,
                    extra={"skip_reason": "already_completed"},
                )
                _log_event(
                    "recovery_wallet_transfer_existing_completed_reused",
                    {
                        **transfer_required_payload,
                        "cycle_index": cycle_index,
                        "transfer_id": baseline.get("recovery_reload_transfer_id")
                        or baseline.get("recovery_reload_transfer_exchange_transfer_id"),
                    },
                )
                self._set_recovery_lifecycle_state(
                    state,
                    "WALLET_TRANSFER_COMPLETED",
                    event="recovery_wallet_transfer_already_completed",
                    extra={"cycle_index": cycle_index},
                )
                return True
            if transfer_context.get("ok"):
                _log_event(
                    "recovery_wallet_transfer_signature_resolved",
                    {
                        **(transfer_context.get("payload_base") or {}),
                        "trade_block_id": state.get("trade_block_id"),
                        "recovery_reload_id": state.get("recovery_reload_id"),
                        "recovery_reload_transfer_signature": transfer_signature,
                        "source_account_label": transfer_context.get("source_account_label"),
                        "target_account_label": transfer_context.get("target_account_label"),
                    },
                )
                existing_signature = str(
                    baseline.get("recovery_reload_transfer_signature") or ""
                ).strip()
                existing_status = str(
                    baseline.get("recovery_reload_transfer_status") or ""
                ).strip().upper()
                existing_transfer_id = str(
                    baseline.get("recovery_reload_transfer_id") or ""
                ).strip()
                blocking_statuses = {
                    "IN_PROGRESS",
                    # SUBMITTED ist aktuell nur ein reservierter Zukunftsstatus.
                    # Vor dem Executor-Start wird derzeit IN_PROGRESS verwendet.
                    "SUBMITTED",
                    "COMPLETED",
                    "WAITING_FOR_WALLET_CONFIG",
                    "WAITING_FOR_FUNDS",
                    "CHECK_REQUIRED",
                    "UNKNOWN",
                }
                if existing_signature == transfer_signature and existing_status in blocking_statuses:
                    self._sync_recovery_wallet_transfer_tracking_state(state, baseline)
                    if existing_status == "COMPLETED" or self._recovery_wallet_transfer_already_completed(
                        baseline, cycle_index
                    ):
                        self._log_recovery_wallet_transfer_audit(
                            context,
                            "skipped",
                            runtime_state,
                            baseline=baseline,
                            cycle_index=cycle_index,
                            transfer_context=transfer_context,
                            transfer_required=False,
                            transfer_id=existing_transfer_id or None,
                            extra={
                                "skip_reason": "existing_completed_reused",
                                "existing_status": existing_status,
                            },
                        )
                        _log_event(
                            "recovery_wallet_transfer_existing_completed_reused",
                            {
                                **(transfer_context.get("payload_base") or {}),
                                "trade_block_id": state.get("trade_block_id"),
                                "recovery_reload_id": state.get("recovery_reload_id"),
                                "recovery_reload_transfer_signature": transfer_signature,
                                "transfer_id": existing_transfer_id,
                                "source_account_label": transfer_context.get("source_account_label"),
                                "target_account_label": transfer_context.get("target_account_label"),
                            },
                        )
                        self._set_recovery_lifecycle_state(
                            state,
                            "WALLET_TRANSFER_COMPLETED",
                            event="recovery_wallet_transfer_existing_completed_reused",
                            extra={"cycle_index": cycle_index},
                        )
                        return True
                    self._log_recovery_wallet_transfer_audit(
                        context,
                        "skipped",
                        runtime_state,
                        baseline=baseline,
                        cycle_index=cycle_index,
                        transfer_context=transfer_context,
                        transfer_required=False,
                        transfer_id=existing_transfer_id or None,
                        extra={
                            "skip_reason": "duplicate_suppressed",
                            "existing_status": existing_status,
                        },
                    )
                    _log_event(
                        "recovery_wallet_transfer_duplicate_suppressed",
                        {
                            **(transfer_context.get("payload_base") or {}),
                            "trade_block_id": state.get("trade_block_id"),
                            "recovery_reload_id": state.get("recovery_reload_id"),
                            "recovery_reload_transfer_signature": transfer_signature,
                            "transfer_id": existing_transfer_id,
                            "existing_status": existing_status,
                            "source_account_label": transfer_context.get("source_account_label"),
                            "target_account_label": transfer_context.get("target_account_label"),
                        },
                    )
                    return False
                if (
                    existing_signature
                    and existing_signature != transfer_signature
                    and existing_status in {"IN_PROGRESS", "SUBMITTED", "CHECK_REQUIRED", "UNKNOWN"}
                ):
                    self._sync_recovery_wallet_transfer_tracking_state(state, baseline)
                    self._log_recovery_wallet_transfer_audit(
                        context,
                        "skipped",
                        runtime_state,
                        baseline=baseline,
                        cycle_index=cycle_index,
                        transfer_context=transfer_context,
                        transfer_required=False,
                        transfer_id=existing_transfer_id or None,
                        extra={
                            "skip_reason": "duplicate_suppressed",
                            "existing_status": existing_status,
                            "existing_transfer_signature": existing_signature,
                        },
                    )
                    _log_event(
                        "recovery_wallet_transfer_duplicate_suppressed",
                        {
                            **(transfer_context.get("payload_base") or {}),
                            "trade_block_id": state.get("trade_block_id"),
                            "recovery_reload_id": state.get("recovery_reload_id"),
                            "recovery_reload_transfer_signature": transfer_signature,
                            "existing_transfer_signature": existing_signature,
                            "transfer_id": existing_transfer_id,
                            "existing_status": existing_status,
                            "reason": "different_signature_active_or_unknown",
                            "source_account_label": transfer_context.get("source_account_label"),
                            "target_account_label": transfer_context.get("target_account_label"),
                        },
                    )
                    return False
                if not self._reserve_recovery_wallet_and_watcher_baselines(
                    baseline, transfer_amount_usdt, cycle_index, runtime_state
                ):
                    self._log_recovery_wallet_transfer_audit(
                        context,
                        "failed",
                        runtime_state,
                        baseline=baseline,
                        cycle_index=cycle_index,
                        transfer_context=transfer_context,
                        transfer_amount_usdt=transfer_amount_usdt,
                        transfer_required=True,
                        extra={
                            "reason": "baseline_reservation_failed",
                            "failure_phase": "baseline_reservation",
                        },
                    )
                    _log_event(
                        "fixed_cycle_recovery_wallet_transfer_failed",
                        {
                            **transfer_required_payload,
                            "reason": "baseline_reservation_failed",
                            "resolved_transfer_amount_usdt": transfer_amount_usdt,
                        },
                    )
                    state["recovery_wallet_transfer_pending"] = True
                    state["recovery_reload_transfer_required"] = True
                    state["recovery_reload_transfer_submitted"] = False
                    state["recovery_reload_transfer_confirmed"] = False
                    state["recovery_reload_transfer_error"] = "baseline_reservation_failed"
                    self._set_recovery_lifecycle_state(
                        state,
                        "FAILED",
                        event="recovery_wallet_transfer_reservation_failed",
                        extra={"cycle_index": cycle_index},
                    )
                    return False
                reservation_applied = True
                transfer_id = existing_transfer_id or self._build_recovery_wallet_transfer_id(
                    transfer_signature
                )
                started_at = datetime.now(timezone.utc).isoformat()
                self._set_recovery_wallet_transfer_tracking(
                    baseline,
                    state,
                    recovery_reload_transfer_signature=transfer_signature,
                    recovery_reload_transfer_status="IN_PROGRESS",
                    recovery_reload_transfer_started_at=started_at,
                    recovery_reload_transfer_completed_at=None,
                    recovery_reload_transfer_id=transfer_id,
                    recovery_reload_transfer_amount_usdt=float(transfer_amount_usdt),
                    recovery_reload_transfer_cycle_index=int(cycle_index),
                    recovery_reload_transfer_target_bot_name=str(self.config.bot_name or ""),
                    recovery_reload_transfer_target_profile=transfer_context.get("target_profile"),
                    recovery_reload_transfer_source_account_label=transfer_context.get(
                        "source_account_label"
                    ),
                    recovery_reload_transfer_target_account_label=transfer_context.get(
                        "target_account_label"
                    ),
                    recovery_reload_transfer_source_config_origin=transfer_context.get(
                        "source_config_origin"
                    ),
                    recovery_reload_transfer_exchange_transfer_id=transfer_id,
                )
                state["recovery_wallet_transfer_pending"] = True
                if baseline_path:
                    self._save_recovery_wallet_baseline(baseline_path, baseline)
                _log_event(
                    "recovery_wallet_transfer_inflight_marked",
                    {
                        **(transfer_context.get("payload_base") or {}),
                        "trade_block_id": state.get("trade_block_id"),
                        "recovery_reload_id": state.get("recovery_reload_id"),
                        "recovery_reload_transfer_signature": transfer_signature,
                        "transfer_id": transfer_id,
                        "source_account_label": transfer_context.get("source_account_label"),
                        "target_account_label": transfer_context.get("target_account_label"),
                    },
                )
        success, transfer_id, result_code, executor_event = self._execute_recovery_wallet_transfer(
            runtime_state,
            transfer_context,
            transfer_id,
            context=context,
            baseline=baseline,
            cycle_index=cycle_index,
        )
        if not success:
            status_map = {
                "waiting_for_wallet_config": "WAITING_FOR_WALLET_CONFIG",
                "waiting_for_funds": "WAITING_FOR_FUNDS",
                "check_required": "CHECK_REQUIRED",
            }
            if reservation_applied and result_code in {"waiting_for_wallet_config", "waiting_for_funds"}:
                self._rollback_recovery_wallet_and_watcher_baseline_reservation(
                    baseline,
                    cycle_index,
                    runtime_state,
                    reason=result_code,
                )
            with self._recovery_wallet_transfer_lock():
                if baseline_path:
                    locked_baseline = self._load_recovery_wallet_baseline(baseline_path)
                    if isinstance(locked_baseline, dict):
                        baseline = locked_baseline
                self._set_recovery_wallet_transfer_tracking(
                    baseline,
                    state,
                    recovery_reload_transfer_signature=transfer_signature,
                    recovery_reload_transfer_status=status_map.get(result_code, "CHECK_REQUIRED"),
                    recovery_reload_transfer_id=transfer_id or baseline.get(
                        "recovery_reload_transfer_id"
                    ),
                    recovery_reload_transfer_amount_usdt=float(transfer_amount_usdt),
                    recovery_reload_transfer_cycle_index=int(cycle_index),
                    recovery_reload_transfer_target_bot_name=str(self.config.bot_name or ""),
                    recovery_reload_transfer_target_profile=transfer_context.get("target_profile"),
                    recovery_reload_transfer_source_account_label=transfer_context.get(
                        "source_account_label"
                    ),
                    recovery_reload_transfer_target_account_label=transfer_context.get(
                        "target_account_label"
                    ),
                    recovery_reload_transfer_source_config_origin=transfer_context.get(
                        "source_config_origin"
                    ),
                    recovery_reload_transfer_exchange_transfer_id=transfer_id
                    or baseline.get("recovery_reload_transfer_exchange_transfer_id"),
                )
                if baseline_path:
                    self._save_recovery_wallet_baseline(baseline_path, baseline)
            _log_event(
                "fixed_cycle_recovery_refill_blocked_waiting_for_wallet_transfer",
                transfer_required_payload,
            )
            state["recovery_wallet_transfer_pending"] = True
            state["recovery_reload_transfer_required"] = True
            state["recovery_reload_transfer_submitted"] = result_code == "check_required"
            state["recovery_reload_transfer_confirmed"] = False
            failure_reason = str(state.get("recovery_reload_transfer_error") or "").strip()
            if failure_reason not in {
                "waiting_for_wallet_config",
                "waiting_for_funds",
                "check_required",
            }:
                failure_reason = "check_required" if result_code == "check_required" else "executor_failed"
            state["recovery_reload_transfer_error"] = failure_reason
            lifecycle_state = "FAILED"
            lifecycle_event = "recovery_wallet_transfer_failed"
            if failure_reason == "waiting_for_wallet_config":
                lifecycle_state = "WAITING_FOR_WALLET_CONFIG"
                lifecycle_event = "recovery_wallet_transfer_blocked_missing_config"
            elif failure_reason == "waiting_for_funds":
                lifecycle_state = "WAITING_FOR_FUNDS"
                lifecycle_event = "recovery_wallet_transfer_insufficient_funds"
            elif failure_reason == "check_required":
                lifecycle_state = "CHECK_REQUIRED"
                lifecycle_event = "recovery_wallet_transfer_unknown_result_requires_manual_check"
            self._set_recovery_lifecycle_state(
                state,
                lifecycle_state,
                event=lifecycle_event,
                extra={"cycle_index": cycle_index},
            )
            return False
        state["recovery_wallet_transfer_pending"] = False
        state["recovery_wallet_transfer_completed"] = True
        state["recovery_wallet_transfer_cycle_index"] = cycle_index
        state["recovery_wallet_transfer_amount_usdt"] = transfer_amount_usdt
        state["recovery_wallet_transfer_id"] = transfer_id
        state["recovery_wallet_transfer_status"] = "completed"
        cycle_state["recovery_wallet_transfer_completed"] = True
        cycle_state["recovery_wallet_transfer_cycle_index"] = cycle_index
        cycle_state["recovery_wallet_transfer_amount_usdt"] = transfer_amount_usdt
        cycle_state["recovery_wallet_transfer_id"] = transfer_id
        cycle_state["recovery_wallet_transfer_status"] = "completed"
        completed_at = datetime.now(timezone.utc).isoformat()
        with self._recovery_wallet_transfer_lock():
            if baseline_path:
                locked_baseline = self._load_recovery_wallet_baseline(baseline_path)
                if isinstance(locked_baseline, dict):
                    baseline = locked_baseline
            total_transferred_after = float(
                baseline.get("total_transferred_recovery_usdt") or 0.0
            ) + transfer_amount_usdt
            baseline["total_transferred_recovery_usdt"] = total_transferred_after
            baseline["pending_recovery_transfer_usdt"] = 0.0
            baseline["pending_recovery_transfer_cycle_index"] = None
            baseline["allocated_wallet_balance_usdt"] = float(
                baseline.get("initial_wallet_balance_usdt") or 0.0
            ) + total_transferred_after
            self._set_recovery_wallet_transfer_tracking(
                baseline,
                state,
                recovery_reload_transfer_signature=transfer_signature,
                recovery_reload_transfer_status="COMPLETED",
                recovery_reload_transfer_completed_at=completed_at,
                recovery_reload_transfer_id=transfer_id,
                recovery_reload_transfer_amount_usdt=float(transfer_amount_usdt),
                recovery_reload_transfer_cycle_index=int(cycle_index),
                recovery_reload_transfer_target_bot_name=str(self.config.bot_name or ""),
                recovery_reload_transfer_target_profile=transfer_context.get("target_profile"),
                recovery_reload_transfer_source_account_label=transfer_context.get(
                    "source_account_label"
                ),
                recovery_reload_transfer_target_account_label=transfer_context.get(
                    "target_account_label"
                ),
                recovery_reload_transfer_source_config_origin=transfer_context.get(
                    "source_config_origin"
                ),
                recovery_reload_transfer_exchange_transfer_id=transfer_id,
            )
            transfer_record = {
                "cycle_index": cycle_index,
                "amount_usdt": transfer_amount_usdt,
                "direction": "refill",
                "transfer_id": transfer_id,
                "status": "completed",
                "timestamp": completed_at,
            }
            transfer_record = self._enrich_recovery_wallet_transfer_record(
                transfer_record,
                runtime_state,
                transfer_context,
                transfer_amount_usdt,
                executor_event,
                transfer_context.get("log_path"),
            )
            baseline_transfers = baseline.get("recovery_transfers")
            if isinstance(baseline_transfers, list):
                if not any(
                    str(item.get("transfer_id") or "").strip() == str(transfer_id or "").strip()
                    for item in baseline_transfers
                    if isinstance(item, dict)
                ):
                    baseline_transfers.append(transfer_record)
            else:
                baseline["recovery_transfers"] = [transfer_record]
            if baseline_path:
                self._save_recovery_wallet_baseline(baseline_path, baseline)
        self._log_recovery_wallet_transfer_audit(
            context,
            "baseline_updated_after_transfer",
            runtime_state,
            baseline=baseline,
            cycle_index=cycle_index,
            transfer_context=transfer_context,
            transfer_amount_usdt=transfer_amount_usdt,
            transfer_required=False,
            transfer_id=transfer_id,
            extra={
                "total_transferred_recovery_usdt_before": total_transferred_before,
                "total_transferred_recovery_usdt_after": total_transferred_after,
                "allocated_wallet_balance_usdt_before": allocated_before,
                "allocated_wallet_balance_usdt_after": baseline.get(
                    "allocated_wallet_balance_usdt"
                ),
                "recovery_transfers_count": len(baseline.get("recovery_transfers") or []),
            },
        )
        _log_event(
            "fixed_cycle_recovery_wallet_transfer_completed",
            {
                **transfer_required_payload,
                "transfer_id": transfer_id,
                "total_transferred_recovery_usdt_before": total_transferred_before,
                "total_transferred_recovery_usdt_after": total_transferred_after,
                "allocated_wallet_balance_usdt_after": baseline.get(
                    "allocated_wallet_balance_usdt"
                ),
            },
        )
        _log_event(
            "fixed_cycle_recovery_wallet_transfer_confirmed",
            {
                **transfer_required_payload,
                "transfer_id": transfer_id,
                "total_transferred_recovery_usdt_before": total_transferred_before,
                "total_transferred_recovery_usdt_after": total_transferred_after,
                "allocated_wallet_balance_usdt_before": allocated_before,
                "allocated_wallet_balance_usdt_after": baseline.get(
                    "allocated_wallet_balance_usdt"
                ),
            },
        )
        self._write_cycle_state(cycle_state)
        self._set_recovery_lifecycle_state(
            state,
            "WALLET_TRANSFER_COMPLETED",
            event="recovery_wallet_transfer_completed",
            extra={"cycle_index": cycle_index},
        )
        return True
    def _build_recovery_debug_payload(
        self,
        runtime_state: RuntimeState | None,
        snapshot: HedgeSnapshot | None,
        cycle_state: dict[str, Any] | None,
    ) -> dict[str, Any]:
        strategy_state: dict[str, Any] = {}
        if runtime_state:
            strategy_state = getattr(runtime_state, "strategy_state", {}) or {}
        cycle_state = cycle_state or strategy_state.get("cycle_state") or {}
        def _flag(name: str) -> bool:
            return bool(strategy_state.get(name) is True or cycle_state.get(name) is True)
        recovery_reload_long_pending = bool(
            self._get_recovery_reload_state_value(
                strategy_state, cycle_state, "recovery_reload_long_pending", default=False
            )
        )
        recovery_reload_short_pending = bool(
            self._get_recovery_reload_state_value(
                strategy_state, cycle_state, "recovery_reload_short_pending", default=False
            )
        )
        recovery_reload_long_filled = bool(
            self._get_recovery_reload_state_value(
                strategy_state, cycle_state, "recovery_reload_long_filled", default=False
            )
        )
        recovery_reload_short_filled = bool(
            self._get_recovery_reload_state_value(
                strategy_state, cycle_state, "recovery_reload_short_filled", default=False
            )
        )
        recovery_required = _flag("recovery_required")
        post_refill_required = bool(
            strategy_state.get("post_refill_structure_rebuild_required")
            or cycle_state.get("post_refill_structure_rebuild_required")
        )
        runtime_orders = []
        runtime_active_order_purposes: list[str] = []
        runtime_active_order_count = 0
        if runtime_state:
            raw_runtime_orders = getattr(runtime_state, "active_orders", {})
            if isinstance(raw_runtime_orders, dict):
                runtime_orders = list(raw_runtime_orders.values())
            elif isinstance(raw_runtime_orders, list):
                runtime_orders = raw_runtime_orders
            runtime_active_order_count = len(runtime_orders)
            for order in runtime_orders:
                purpose = self._safe_order_field(order, "purpose")
                if purpose:
                    runtime_active_order_purposes.append(purpose)
        snapshot_orders = []
        snapshot_active_order_purposes: list[str] = []
        snapshot_active_order_count = 0
        if snapshot:
            active = getattr(snapshot, "active_orders", None) or []
            if isinstance(active, list):
                snapshot_orders = active
            elif isinstance(active, dict):
                snapshot_orders = list(active.values())
            snapshot_active_order_count = len(snapshot_orders)
            for order in snapshot_orders:
                purpose = self._safe_order_field(order, "purpose")
                if purpose:
                    snapshot_active_order_purposes.append(purpose)
        def _order_dict(order: Any) -> dict[str, Any]:
            return {
                "purpose": self._safe_order_field(order, "purpose"),
                "order_id": self._safe_order_field(order, "exchange_order_id")
                or self._safe_order_field(order, "order_id"),
                "side": self._safe_order_field(order, "side"),
                "qty": self._safe_order_field(order, "qty"),
                "price": self._safe_order_field(order, "price"),
                "status": self._safe_order_field(order, "status"),
            }
        def _filter_recovery(orders: list[Any]) -> list[dict[str, Any]]:
            filtered: list[dict[str, Any]] = []
            for order in orders:
                purpose = (
                    str(self._safe_order_field(order, "purpose") or "").upper()
                )
                if self._is_recovery_reload_purpose(purpose):
                    filtered.append(_order_dict(order))
            return filtered
        runtime_recovery_active_orders = _filter_recovery(runtime_orders)
        snapshot_recovery_active_orders = _filter_recovery(snapshot_orders)
        recovery_reload_pending = recovery_reload_long_pending or recovery_reload_short_pending
        missing_reason = None
        if recovery_reload_pending and not (
            runtime_recovery_active_orders or snapshot_recovery_active_orders
        ):
            missing_reason = "pending_flag_true_but_no_active_order"
        return {
            "recovery_required": recovery_required,
            "recovery_reload_long_pending": recovery_reload_long_pending,
            "recovery_reload_short_pending": recovery_reload_short_pending,
            "recovery_reload_long_filled": recovery_reload_long_filled,
            "recovery_reload_short_filled": recovery_reload_short_filled,
            "recovery_reload_pending": recovery_reload_pending,
            "recovery_reload_completed": recovery_reload_long_filled
            and recovery_reload_short_filled,
            # legacy debug aliases
            "recovery_refill_long_pending": recovery_reload_long_pending,
            "recovery_refill_short_pending": recovery_reload_short_pending,
            "recovery_refill_long_filled": recovery_reload_long_filled,
            "recovery_refill_short_filled": recovery_reload_short_filled,
            "recovery_refill_pending": recovery_reload_pending,
            "recovery_refill_completed": recovery_reload_long_filled
            and recovery_reload_short_filled,
            "post_refill_structure_rebuild_required": post_refill_required,
            "runtime_active_order_count": runtime_active_order_count,
            "snapshot_active_order_count": snapshot_active_order_count,
            "runtime_active_order_purposes": runtime_active_order_purposes,
            "snapshot_active_order_purposes": snapshot_active_order_purposes,
            "runtime_recovery_active_orders": runtime_recovery_active_orders,
            "snapshot_recovery_active_orders": snapshot_recovery_active_orders,
            "missing_recovery_order_reason": missing_reason,
        }

    def _clear_stale_recovery_reload_pending_flags(
        self,
        runtime_state: RuntimeState,
        cycle_state: dict[str, Any],
        debug_payload: dict[str, Any],
    ) -> None:
        """
        Wenn Pending-Flags gesetzt sind, aber keine aktiven Recovery-Orders existieren,
        wurden die Orders vermutlich vom Exchange rejected. In diesem Fall die
        Pending-Flags zurücksetzen, damit der Bot nicht dauerhaft blockiert bleibt.
        """
        state = runtime_state.strategy_state
        symbol = self.config.symbol
        trade_block_id = state.get("trade_block_id")
        recovery_reload_long_pending = bool(debug_payload.get("recovery_reload_long_pending"))
        recovery_reload_short_pending = bool(debug_payload.get("recovery_reload_short_pending"))
        if not (recovery_reload_long_pending or recovery_reload_short_pending):
            return
        # Flags auf State- und Cycle-Ebene zurücksetzen (inkl. Legacy-Aliase).
        self._set_recovery_reload_state_value(
            state,
            cycle_state,
            "recovery_reload_long_pending",
            False,
        )
        self._set_recovery_reload_state_value(
            state,
            cycle_state,
            "recovery_reload_short_pending",
            False,
        )
        payload = {
            "symbol": symbol,
            "bot_name": self.config.bot_name,
            "trade_block_id": trade_block_id,
            "recovery_reload_long_pending_before": recovery_reload_long_pending,
            "recovery_reload_short_pending_before": recovery_reload_short_pending,
            "runtime_recovery_active_orders": debug_payload.get("runtime_recovery_active_orders"),
            "snapshot_recovery_active_orders": debug_payload.get("snapshot_recovery_active_orders"),
            "missing_recovery_order_reason": debug_payload.get("missing_recovery_order_reason"),
        }
        _log_event("fixed_cycle_recovery_reload_order_rejected_pending_flags_cleared", payload)

    def _safe_order_field(self, order: Any, field: str) -> Any:
        if isinstance(order, dict):
            return order.get(field)
        return getattr(order, field, None)

    @staticmethod
    def _dedupe_preserve_order(items: list[Any]) -> list[Any]:
        unique: list[Any] = []
        seen: set[Any] = set()
        for item in items:
            if item in seen:
                continue
            seen.add(item)
            unique.append(item)
        return unique

    def _build_recovery_refill_intents(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent] | None:
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        if self._get_recovery_reload_state_value(
            state, cycle_state, "recovery_reload_long_pending", default=False
        ) or self._get_recovery_reload_state_value(
            state, cycle_state, "recovery_reload_short_pending", default=False
        ):
            return []
        active = list(runtime_state.active_orders.values()) + list(snapshot.active_orders)
        for order in active:
            purpose = getattr(order, "purpose", None)
            if self._is_recovery_reload_purpose(purpose):
                return []
        base_notional = float(self.config.base_notional_usdt or 0.0)
        if base_notional <= 0:
            _log_warning_event(
                "fixed_cycle_recovery_refill_no_safe_size",
                {"symbol": self.config.symbol, "reason": "base_notional_invalid"},
            )
            return None
        short_ratio = max(float(getattr(self.config, "hedge_ratio_short", 0.0) or 0.0), 0.5)
        short_notional = base_notional * short_ratio
        long_price = float(snapshot.long_avg or snapshot.current_price or 0.0)
        short_price = float(snapshot.short_avg or snapshot.current_price or long_price)
        if long_price <= 0 or short_price <= 0:
            _log_warning_event(
                "fixed_cycle_recovery_refill_no_safe_size",
                {
                    "symbol": self.config.symbol,
                    "long_price": long_price,
                    "short_price": short_price,
                },
            )
            return None
        long_qty = self._price_to_qty(notional_usdt=base_notional, price=long_price, runtime_state=runtime_state)
        short_qty = self._price_to_qty(
            notional_usdt=short_notional,
            price=short_price,
            runtime_state=runtime_state,
        )
        if long_qty <= 0 and short_qty <= 0:
            _log_warning_event(
                "fixed_cycle_recovery_refill_no_safe_size",
                {
                    "symbol": self.config.symbol,
                    "long_qty": long_qty,
                    "short_qty": short_qty,
                    "long_price": long_price,
                    "short_price": short_price,
                },
            )
            return None
        intents: list[StrategyIntent] = []
        entry_spread_pct = 0.0
        if long_price > 0 and short_price > 0:
            entry_spread_pct = abs(long_price - short_price) / (
                (long_price + short_price) / 2
            ) * 100
        recovery_cycle_index = self._current_recovery_reference_cycle_index(runtime_state)
        metadata_base = {
            "source": "recovery_capital_reload",
            "recovery_reload": True,
            "entry_spread_pct": entry_spread_pct,
            "recovery_activation_timing": state.get("recovery_activation_timing"),
            "recovery_reload_id": state.get("recovery_reload_id"),
            "parent_trade_block_id": state.get("trade_block_id"),
            "recovery_cycle_index": recovery_cycle_index,
            "base_notional_usdt": base_notional,
            "hedge_ratio_short": short_ratio,
        }
        if long_qty > 0:
            intents.append(
                StrategyIntent(
                    side="long",
                    qty=long_qty,
                    price=None,
                    purpose=self.RECOVERY_RELOAD_LONG_ENTRY,
                    order_type="Market",
                    reduce_only=False,
                    position_idx=1,
                    metadata={
                        **metadata_base,
                        "long_notional_usdt": base_notional,
                        "short_notional_usdt": short_notional,
                        "recovery_reload_notional_usdt": base_notional,
                        "recovery_reload_reference_price": long_price,
                        "entry_role": "recovery_reload_long_entry",
                    },
                )
            )
        if short_qty > 0:
            intents.append(
                StrategyIntent(
                    side="short",
                    qty=short_qty,
                    price=None,
                    purpose=self.RECOVERY_RELOAD_SHORT_ENTRY,
                    order_type="Market",
                    reduce_only=False,
                    position_idx=2,
                    metadata={
                        **metadata_base,
                        "long_notional_usdt": base_notional,
                        "short_notional_usdt": short_notional,
                        "recovery_reload_notional_usdt": short_notional,
                        "recovery_reload_reference_price": short_price,
                        "entry_role": "recovery_reload_short_entry",
                    },
                )
            )
        if not intents:
            return None
        if not self._ensure_recovery_wallet_transfer(
            snapshot, runtime_state, context, recovery_cycle_index
        ):
            return []
        # Vor dem eigentlichen Recovery-Reload-Entry alle alten Exit- und
        # Cycle-Orders canceln, damit die neue Struktur nicht mit der alten
        # Pre-Recovery-Struktur kollidiert.
        if not self._cancel_pre_recovery_reload_orders(
            snapshot, runtime_state, context, recovery_cycle_index
        ):
            return []
        # Nach erfolgreichem Cancel den Second-Leg-/Short-TP-State des
        # Recovery-Referenz-Cycles bereinigen, damit keine alte
        # CYCLE_N_SHORT_REDUCE-Struktur den Reload blockiert.
        self._clear_recovery_pre_reload_stale_cycle_state(
            runtime_state,
            recovery_cycle_index,
            reason="pre_recovery_reload_cancel",
        )
        # Nach dem Bereinigen des Second-Leg-States muss explizit signalisiert werden,
        # dass nun ein neuer Second-Leg-Order (z.B. CYCLE_N_SHORT_REDUCE) für den
        # Recovery-Referenz-Cycle erwartet wird. Ohne diesen Schritt würde die
        # nachgelagerte Rebuild-Logik zwar den Sequenz-State (next_required_purpose)
        # sehen, aber keine klaren Waiting-/Pending-Flags für den Second-Leg
        # vorfinden und deshalb keine neuen Second-Leg-Intents aufbauen.
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        self._set_second_leg_waiting_state(
            state,
            cycle_state,
            waiting=True,
            cycle_index=recovery_cycle_index,
        )
        state["pending_short_cycle_index"] = recovery_cycle_index
        cycle_state["pending_short_cycle_index"] = recovery_cycle_index
        _log_event(
            "fixed_cycle_recovery_post_clear_second_leg_expected_set",
            {
                "symbol": self.config.symbol,
                "bot_name": self.config.bot_name,
                "trade_block_id": state.get("trade_block_id"),
                "recovery_reload_id": state.get("recovery_reload_id"),
                "recovery_cycle_index": recovery_cycle_index,
                "cycle_waiting_for_short_tp": self._get_second_leg_waiting(state, cycle_state),
                "short_tp_pending_cycle": self._get_second_leg_pending_cycle(state, cycle_state),
                "pending_short_cycle_index": int(
                    state.get("pending_short_cycle_index")
                    or cycle_state.get("pending_short_cycle_index")
                    or 0
                ),
            },
        )
        self._apply_recovery_refill_state(
            runtime_state,
            base_notional,
            short_notional,
            long_qty=long_qty,
            short_qty=short_qty,
        )
        _log_event(
            "fixed_cycle_recovery_reload_entry_planned",
            {
                "symbol": self.config.symbol,
                "trade_block_id": state.get("trade_block_id"),
                "recovery_reload_id": state.get("recovery_reload_id"),
                "cycle_index": recovery_cycle_index,
                "long_qty": long_qty,
                "short_qty": short_qty,
                "long_notional_usdt": base_notional,
                "short_notional_usdt": short_notional,
            },
        )
        _log_event(
            "fixed_cycle_recovery_refill_intents_created",
            {
                "symbol": self.config.symbol,
                "long_qty": long_qty,
                "short_qty": short_qty,
                "long_price": long_price,
                "short_price": short_price,
                "entry_spread_pct": entry_spread_pct,
                "short_ratio": short_ratio,
            },
        )
        _log_event(
            "fixed_cycle_recovery_reload_entry_submitted",
            {
                "symbol": self.config.symbol,
                "trade_block_id": state.get("trade_block_id"),
                "recovery_reload_id": state.get("recovery_reload_id"),
                "cycle_index": recovery_cycle_index,
                "intent_purposes": [intent.purpose for intent in intents],
            },
        )
        self._set_recovery_lifecycle_state(
            state,
            "REFILL_INTENTS_CREATED",
            event="recovery_refill_intents_created",
            extra={"cycle_index": recovery_cycle_index},
        )
        return intents

    def _handle_recovery_refill_fill(
        self,
        fill_event: FillEvent,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> None:
        if not fill_event.purpose:
            return
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        side = "long" if self._is_recovery_reload_long_purpose(fill_event.purpose) else "short"
        pending_key = f"recovery_reload_{side}_pending"
        filled_key = f"recovery_reload_{side}_filled"
        fill_price_key = f"recovery_reload_{side}_fill_price"
        pending_state = bool(
            self._get_recovery_reload_state_value(state, cycle_state, pending_key, default=False)
        )
        pending_cycle = pending_state
        filled_state = bool(
            self._get_recovery_reload_state_value(state, cycle_state, filled_key, default=False)
        )
        filled_cycle = filled_state
        recovery_required_state = bool(state.get("recovery_required"))
        recovery_required_cycle = bool(cycle_state.get("recovery_required"))
        recovery_active = bool(
            recovery_required_state
            or recovery_required_cycle
            or pending_state
            or pending_cycle
            or filled_state
            or filled_cycle
        )
        if not recovery_active:
            _log_event(
                "fixed_cycle_recovery_refill_late_fill_ignored",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "side": side,
                    "purpose": fill_event.purpose,
                    "order_id": fill_event.exchange_order_id,
                    "exec_id": fill_event.exec_id,
                    "recovery_required_state": recovery_required_state,
                    "recovery_required_cycle": recovery_required_cycle,
                    "pending_state": pending_state,
                    "pending_cycle": pending_cycle,
                    "filled_state": filled_state,
                    "filled_cycle": filled_cycle,
                },
            )
            return
        already_filled_state = bool(
            self._get_recovery_reload_state_value(state, cycle_state, filled_key, default=False)
        )
        already_filled_cycle = already_filled_state
        if already_filled_state or already_filled_cycle:
            _log_event(
                "fixed_cycle_recovery_refill_duplicate_fill_ignored",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "side": side,
                    "purpose": fill_event.purpose,
                    "order_id": fill_event.exchange_order_id,
                    "exec_id": fill_event.exec_id,
                    "already_filled_state": already_filled_state,
                    "already_filled_cycle": already_filled_cycle,
                    "recovery_required_state": bool(state.get("recovery_required")),
                    "recovery_required_cycle": bool(cycle_state.get("recovery_required")),
                },
            )
            return
        # Vor dem Update merken, ob bereits eine Seite als gefüllt markiert war,
        # um den Übergang REFILL_PARTIALLY_FILLED beobachten zu können.
        long_filled_before = bool(
            self._get_recovery_reload_state_value(
                state, cycle_state, "recovery_reload_long_filled", default=False
            )
        )
        short_filled_before = bool(
            self._get_recovery_reload_state_value(
                state, cycle_state, "recovery_reload_short_filled", default=False
            )
        )
        fill_price = float(fill_event.exec_price or 0.0)
        self._set_recovery_reload_state_value(state, cycle_state, pending_key, False)
        self._set_recovery_reload_state_value(state, cycle_state, filled_key, True)
        if fill_price > 0:
            self._set_recovery_reload_state_value(
                state, cycle_state, fill_price_key, fill_price
            )
        payload = {
            "symbol": snapshot.symbol or self.config.symbol,
            "purpose": fill_event.purpose,
            "exec_price": fill_price,
            "exec_qty": float(fill_event.exec_qty or 0.0),
            "recovery_reload_long_filled": bool(
                self._get_recovery_reload_state_value(
                    state, cycle_state, "recovery_reload_long_filled", default=False
                )
            ),
            "recovery_reload_short_filled": bool(
                self._get_recovery_reload_state_value(
                    state, cycle_state, "recovery_reload_short_filled", default=False
                )
            ),
        }
        _log_event("fixed_cycle_recovery_refill_fill_detected", payload)
        recovery_cycle_index = int(
            state.get("recovery_reference_cycle_index")
            or cycle_state.get("recovery_reference_cycle_index")
            or 0
        ) or None
        self._write_refill_documentation_confirmed_row(
            fill_event,
            snapshot,
            runtime_state,
            state,
            pnl_scope="recovery_reload",
            pnl_source="recovery_reload_fill",
            confirmed_via="recovery_reload_fill",
            cycle_index=recovery_cycle_index,
            order_source="recovery_capital_reload",
            recovery_reload_id=state.get("recovery_reload_id"),
            refill_batch_id=state.get("refill_batch_id"),
            stage_index=state.get("recovery_stage_index") or cycle_state.get("recovery_stage_index"),
            stage_count=state.get("recovery_stage_count") or cycle_state.get("recovery_stage_count"),
        )
        reload_fill_payload = {
            **payload,
            "recovery_reload_id": state.get("recovery_reload_id"),
            "trade_block_id": state.get("trade_block_id"),
        }
        if side == "long":
            _log_event("fixed_cycle_recovery_reload_long_filled", reload_fill_payload)
        else:
            _log_event("fixed_cycle_recovery_reload_short_filled", reload_fill_payload)
        self._write_cycle_state(cycle_state)
        # Lifecycle-Transition: erster Teil-Fill der Recovery-Refills.
        long_filled_after = bool(
            self._get_recovery_reload_state_value(
                state, cycle_state, "recovery_reload_long_filled", default=False
            )
        )
        short_filled_after = bool(
            self._get_recovery_reload_state_value(
                state, cycle_state, "recovery_reload_short_filled", default=False
            )
        )
        if (
            (long_filled_after or short_filled_after)
            and not (long_filled_after and short_filled_after)
            and not (long_filled_before or short_filled_before)
        ):
            self._set_recovery_lifecycle_state(
                state,
                "REFILL_PARTIALLY_FILLED",
                event="recovery_refill_partial_fill",
            )
        if long_filled_after and short_filled_after:
            completed_cycle_index = int(
                state.get("recovery_reference_cycle_index")
                or cycle_state.get("recovery_reference_cycle_index")
                or 0
            )
            if completed_cycle_index > 0:
                state["recovery_completed_cycle_index"] = completed_cycle_index
                cycle_state["recovery_completed_cycle_index"] = completed_cycle_index
            _log_event("fixed_cycle_recovery_refill_complete", payload)
            _log_event(
                "fixed_cycle_recovery_reload_complete",
                {
                    **payload,
                    "recovery_reload_id": state.get("recovery_reload_id"),
                    "trade_block_id": state.get("trade_block_id"),
                    "cycle_index": completed_cycle_index or None,
                },
            )
            self._set_recovery_reload_state_value(
                state, cycle_state, "recovery_reload_completed", True
            )
            # REST-Reconcile als Pflichtschritt nach Recovery-Reload-Entry markieren.
            state["recovery_reload_rest_reconcile_required"] = True
            state["recovery_reload_rest_reconcile_confirmed"] = False
            # Erster Reconcile-Versuch unmittelbar nach vollständigem Fill.
            refresh_snapshot = getattr(context, "refresh_snapshot", None)
            trade_block_id = state.get("trade_block_id")
            recovery_reload_id = state.get("recovery_reload_id")
            reconcile_base_payload: dict[str, Any] = {
                "symbol": snapshot.symbol or self.config.symbol,
                "trade_block_id": trade_block_id,
                "cycle_index": completed_cycle_index or None,
                "recovery_reload_id": recovery_reload_id,
                "prev_long_qty": float(snapshot.long_qty or 0.0),
                "prev_short_qty": float(snapshot.short_qty or 0.0),
                "prev_long_avg": float(snapshot.long_avg or 0.0),
                "prev_short_avg": float(snapshot.short_avg or 0.0),
            }
            if callable(refresh_snapshot):
                _log_event(
                    "fixed_cycle_recovery_reload_rest_reconcile_started",
                    reconcile_base_payload,
                )
                try:
                    reconciled_snapshot = refresh_snapshot("recovery_reload_rest")
                    runtime_state.last_snapshot = reconciled_snapshot
                    state["recovery_reload_rest_reconcile_confirmed"] = True
                    state["recovery_reload_rest_reconcile_required"] = False
                    state.pop("recovery_reload_rest_reconcile_error", None)
                    reconcile_completed_payload = {
                        **reconcile_base_payload,
                        "actual_long_qty": float(reconciled_snapshot.long_qty or 0.0),
                        "actual_short_qty": float(reconciled_snapshot.short_qty or 0.0),
                        "actual_long_avg_price": float(reconciled_snapshot.long_avg or 0.0),
                        "actual_short_avg_price": float(reconciled_snapshot.short_avg or 0.0),
                        "snapshot_source": getattr(reconciled_snapshot, "source", None),
                    }
                    _log_event(
                        "fixed_cycle_recovery_reload_rest_reconcile_completed",
                        reconcile_completed_payload,
                    )
                    snapshot = reconciled_snapshot
                except Exception as exc:  # pragma: no cover - Reconcile darf nie blockierend fehlschlagen
                    state["recovery_reload_rest_reconcile_error"] = str(exc)
                    _log_event(
                        "fixed_cycle_recovery_reload_rest_reconcile_failed",
                        {
                            **reconcile_base_payload,
                            "error": str(exc),
                        },
                    )

            self._set_recovery_lifecycle_state(
                state,
                "REFILL_FILLED",
                event="recovery_refill_filled",
            )
            state["post_refill_structure_rebuild_required"] = True
            _log_event("fixed_cycle_recovery_exit_rebuild_requested", payload)
            # Time-Distance-Recovery hat den normalen Refill-Mode via _enter_refill_mode aktiviert.
            # Sobald beide Recovery-Refill-Orders gefüllt sind, verlassen wir den Refill-Mode
            # explizit über den bestehenden Lifecycle-Helfer, damit refill_*- und Exit-Blocker
            # (refill_pending/refill_required/exit_locked/cycle_block_status=REFILL_REQUIRED etc.)
            # sauber zurückgesetzt werden.
            self._exit_refill_mode_after_complete_refill(
                state,
                reason="recovery_refill_completed",
                symbol=self.config.symbol,
            )
            self._clear_recovery_state(runtime_state)
            self._set_recovery_lifecycle_state(
                state,
                "REBUILDING_STRUCTURE",
                event="recovery_refill_mode_exited",
            )
            _log_event("fixed_cycle_recovery_required_cleared", payload)
            # Diagnose-Log mit den (ggf. über REST) neu abgeglichenen Positionsgrößen.
            last_snapshot = getattr(runtime_state, "last_snapshot", None) or snapshot
            _log_event(
                "fixed_cycle_recovery_reload_cycle_resumed_with_reconciled_sizes",
                {
                    "symbol": last_snapshot.symbol or self.config.symbol,
                    "trade_block_id": trade_block_id,
                    "cycle_index": completed_cycle_index or None,
                    "recovery_reload_id": recovery_reload_id,
                    "actual_long_qty": float(getattr(last_snapshot, "long_qty", 0.0) or 0.0),
                    "actual_short_qty": float(getattr(last_snapshot, "short_qty", 0.0) or 0.0),
                    "actual_long_avg_price": float(getattr(last_snapshot, "long_avg", 0.0) or 0.0),
                    "actual_short_avg_price": float(getattr(last_snapshot, "short_avg", 0.0) or 0.0),
                },
            )
            _log_event("fixed_cycle_recovery_normal_cycle_resumed", payload)

    def _select_pre_recovery_reference_price(
        self,
        runtime_state: RuntimeState,
        cycle_state: dict[str, Any],
        *,
        cycle_index: int,
        first_leg_reference: float,
        entry_reference_price: float,
    ) -> tuple[float, str]:
        latest_confirmed_short_fill_price = float(
            cycle_state.get("last_confirmed_short_fill_price") or 0.0
        )
        if latest_confirmed_short_fill_price > 0:
            return latest_confirmed_short_fill_price, "last_confirmed_short_fill_price"

        previous_short_reduce_fill_price = self._get_confirmed_previous_short_reduce_fill_price(
            runtime_state,
            cycle_index,
        )
        if previous_short_reduce_fill_price and previous_short_reduce_fill_price > 0:
            return previous_short_reduce_fill_price, "previous_short_reduce_fill_price"

        last_cycle_reference_price = float(cycle_state.get("last_cycle_reference_price") or 0.0)
        if last_cycle_reference_price > 0:
            return last_cycle_reference_price, "last_cycle_reference_price"

        if first_leg_reference > 0:
            return float(first_leg_reference), "first_leg_reference"

        if entry_reference_price > 0:
            return float(entry_reference_price), "entry_reference_price"

        return 0.0, "missing_reference"

    def _build_long_reduce_cover_projection(
        self,
        *,
        current_price: float,
        long_avg: float,
        short_avg: float,
        current_long_qty: float,
        current_short_qty: float,
        projected_short_reduce_fill_price: float,
        projected_short_reduce_qty: float,
        projected_long_reduce_qty: float,
        last_relevant_fill_price: float,
        runtime_state: RuntimeState,
    ) -> dict[str, Any]:
        target_profit_usdt = float(self.config.target_profit_usdt or 0.0)
        fee_rate_used = 0.00055
        projected_short_reduce_loss_usdt = max(
            0.0,
            (projected_short_reduce_fill_price - short_avg) * projected_short_reduce_qty,
        )
        projected_required_profit_to_cover_loss = max(
            projected_short_reduce_loss_usdt + target_profit_usdt,
            0.0,
        )
        projected_loss_per_long_reduce_unit = (
            projected_required_profit_to_cover_loss / projected_long_reduce_qty
            if projected_long_reduce_qty > 0
            else 0.0
        )
        projected_required_long_reduce_price = 0.0
        estimated_fee_component = 0.0
        if projected_long_reduce_qty > 0 and long_avg > 0 and fee_rate_used < 1.0:
            projected_required_long_reduce_price = (
                (projected_required_profit_to_cover_loss / projected_long_reduce_qty)
                + (long_avg * (1.0 + fee_rate_used))
            ) / (1.0 - fee_rate_used)
            projected_required_long_reduce_price = self._normalize_price(
                projected_required_long_reduce_price,
                runtime_state,
            )
            estimated_fee_component = (
                (long_avg * projected_long_reduce_qty * fee_rate_used)
                + (
                    projected_required_long_reduce_price
                    * projected_long_reduce_qty
                    * fee_rate_used
                )
            )
        distance_pct_from_last_fill = (
            (
                (projected_required_long_reduce_price - last_relevant_fill_price)
                / last_relevant_fill_price
            )
            * 100.0
            if projected_required_long_reduce_price > 0 and last_relevant_fill_price > 0
            else 0.0
        )
        distance_pct_from_long_avg = (
            ((projected_required_long_reduce_price - long_avg) / long_avg) * 100.0
            if projected_required_long_reduce_price > 0 and long_avg > 0
            else 0.0
        )
        distance_pct_from_current_price = (
            ((projected_required_long_reduce_price - current_price) / current_price) * 100.0
            if projected_required_long_reduce_price > 0 and current_price > 0
            else 0.0
        )
        return {
            "current_price": current_price,
            "long_avg": long_avg,
            "short_avg": short_avg,
            "current_long_qty": current_long_qty,
            "current_short_qty": current_short_qty,
            "projected_short_reduce_qty": projected_short_reduce_qty,
            "projected_long_reduce_qty": projected_long_reduce_qty,
            "projected_short_reduce_fill_price": projected_short_reduce_fill_price,
            "projected_short_reduce_loss_usdt": projected_short_reduce_loss_usdt,
            "target_profit_usdt": target_profit_usdt,
            "projected_required_profit_to_cover_loss": projected_required_profit_to_cover_loss,
            "projected_loss_per_long_reduce_unit": projected_loss_per_long_reduce_unit,
            "projected_required_long_reduce_price": projected_required_long_reduce_price,
            "distance_pct_from_last_fill": distance_pct_from_last_fill,
            "distance_pct_from_long_avg": distance_pct_from_long_avg,
            "distance_pct_from_current_price": distance_pct_from_current_price,
            "remaining_short_qty_after_projected_reduce": max(
                current_short_qty - projected_short_reduce_qty,
                0.0,
            ),
            "remaining_long_qty_after_projected_reduce": max(
                current_long_qty - projected_long_reduce_qty,
                0.0,
            ),
            "included_realized_cycle_net": 0.0,
            "included_buffer": 0.0,
            "fee_rate_used": fee_rate_used,
            "estimated_fee_component": estimated_fee_component,
        }

    def _set_recovery_required_state(
        self,
        runtime_state: RuntimeState,
        cycle_state: dict[str, Any],
        *,
        recovery_fields: dict[str, Any],
    ) -> None:
        state = runtime_state.strategy_state
        for key, value in recovery_fields.items():
            state[key] = value
            cycle_state[key] = value
        state["cycle_block_status"] = "RECOVERY_REQUIRED"
        state["cycle_block_reason"] = recovery_fields.get("recovery_activation_reason")
        cycle_state["cycle_block_status"] = "RECOVERY_REQUIRED"
        cycle_state["cycle_block_reason"] = recovery_fields.get("recovery_activation_reason")
        self._write_cycle_state(cycle_state)

    def _second_leg_pair_purpose(self, cycle_index: int) -> str:
        return self._get_second_leg_purpose(cycle_index)

    def _short_tp_pair_purpose(self, cycle_index: int) -> str:
        return self._second_leg_pair_purpose(cycle_index)

    def _build_short_tp_pair_intent(
        self,
        snapshot: HedgeSnapshot,
        state: dict,
        runtime_state: RuntimeState,
        trigger_price: float,
        long_cycle_number: int,
        context: StrategyContext,
    ) -> StrategyIntent | None:
        purpose = self._second_leg_pair_purpose(long_cycle_number)
        if snapshot.has_open_purpose(purpose):
            return None

        effective_pct = self.config.reduction_pct_per_fill
        current_short_qty = (
            snapshot.short_qty
            if snapshot.short_qty > 0
            else float(state.get("initial_short_qty") or 0.0)
        )
        if current_short_qty <= 0:
            return None
        short_qty = self._fixed_short_cycle_qty(
            float(state.get("initial_short_qty") or 0.0),
            current_short_qty,
            trigger_price,
            runtime_state=runtime_state,
        )
        if short_qty <= 0 or trigger_price <= 0:
            return None

        normalized_price = self._normalize_price(trigger_price, runtime_state)
        context.audit.log_event(
            "fixed_cycle_short_tp_pair_planned",
            strategy=self.name,
            cycle_index=long_cycle_number,
            side="short",
            purpose=purpose,
            entry_reference_price=float(state.get("entry_reference_price") or 0.0),
            trigger_formula="long_reduce_trigger_price",
            current_short_qty=current_short_qty,
            trigger_price_raw=trigger_price,
            trigger_price_normalized=normalized_price,
            reduction_pct_used=effective_pct,
            qty_formula="current_short_qty * reduction_pct_per_fill",
            qty_raw=current_short_qty * self._pct(effective_pct),
            qty_normalized=short_qty,
            order_type="Limit",
            reduce_only=True,
        )
        return StrategyIntent(
            side="short",
            qty=short_qty,
            purpose=purpose,
            order_type="Limit",
            price=normalized_price,
            reduce_only=True,
            trigger_price=normalized_price,
            trigger_direction=2,
            trigger_by="LastPrice",
            order_filter="StopOrder",
            position_idx=2,
            metadata={
                "cycle_index": long_cycle_number,
                "cycle_role": "short_tp_pair",
                "replace_open_purpose": purpose,
                "entry_reference_price": float(state.get("entry_reference_price") or 0.0),
                "long_reduce_trigger_price": trigger_price,
            },
        )

    def _normalize_qty(self, qty: float, runtime_state: RuntimeState | None = None) -> float:
        if qty <= 0:
            return 0.0
        symbol, rules, source = self._resolve_instrument_rules(runtime_state)
        qty_step = rules["qty_step"] if rules and rules.get("qty_step", Decimal("0")) > 0 else Decimal(
            str(self.config.qty_step)
        )
        min_order_qty = rules["min_order_qty"] if rules and rules.get("min_order_qty", Decimal("0")) > 0 else Decimal(
            str(self.config.min_order_qty)
        )
        min_notional = rules["min_notional"] if rules and rules.get("min_notional", Decimal("0")) > 0 else Decimal(
            str(self.config.min_notional_usdt)
        )
        qty_dec = Decimal(str(qty))
        if qty_step > 0:
            stepped = (qty_dec / qty_step).to_integral_value(rounding=ROUND_DOWN) * qty_step
        else:
            stepped = qty_dec
        normalized = rounded_value = max(stepped, Decimal("0"))
        if normalized <= 0 and min_order_qty > 0:
            normalized = min_order_qty
        elif min_order_qty > 0 and normalized < min_order_qty:
            normalized = min_order_qty
        rounded_float = float(normalized)
        logger.debug(
            "normalize_qty %s",
            {
                "symbol": symbol,
                "input_qty": qty,
                "qty_step_used": str(qty_step),
                "rounded_qty": rounded_float,
                "source": source,
            },
        )
        logger.debug(
            "normalize_qty_debug %s", {"symbol": symbol, "has_rules": source == "instrument_rules"}
        )
        return rounded_float

    def _normalize_price(self, price: float, runtime_state: RuntimeState | None = None) -> float:
        if price <= 0:
            return 0.0
        symbol, rules, source = self._resolve_instrument_rules(runtime_state)
        tick_size = (
            rules["tick_size"]
            if rules and rules.get("tick_size", Decimal("0")) > 0
            else Decimal(str(self.config.price_tick_size))
        )
        if tick_size <= 0:
            tick_size = Decimal(str(self.config.price_tick_size))
            source = "config_fallback"
        price_dec = Decimal(str(price))
        divisor = (price_dec / tick_size).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        rounded = (divisor * tick_size).quantize(Decimal("1e-12"), rounding=ROUND_HALF_UP)
        round_mode = "up" if rounded >= price_dec else "down"
        normalized = float(rounded)
        logger.debug(
            "normalize_price %s",
            {
                "symbol": symbol,
                "input_price": price,
                "tick_size_used": str(tick_size),
                "rounded_price": normalized,
                "round_mode": round_mode,
                "source": source,
            },
        )
        logger.debug(
            "normalize_price_debug %s",
            {"symbol": symbol, "has_rules": source == "instrument_rules"},
        )
        return normalized

    def _resolve_instrument_rules(
        self, runtime_state: RuntimeState | None, *, symbol_override: str | None = None
    ) -> tuple[str, dict[str, Decimal] | None, str]:
        symbol = str(symbol_override or self.config.symbol or "").upper()
        if not runtime_state:
            return symbol, None, "config_fallback"
        rules = runtime_state.instrument_rules.get(symbol)
        if rules:
            return symbol, rules, "instrument_rules"
        if symbol not in runtime_state.instrument_rules_fallback_warned:
            runtime_state.instrument_rules_fallback_warned.add(symbol)
            logger.warning(
                "instrument_rules_missing_fallback %s",
                {
                    "symbol": symbol,
                    "reason": "rules_not_found_in_runtime_state",
                },
            )
        return symbol, None, "config_fallback"

    def _active_trade_symbol(
        self,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState | None,
        *,
        fill_event: FillEvent | None = None,
        payload: dict[str, Any] | None = None,
    ) -> str:
        state = runtime_state.strategy_state if runtime_state is not None else {}
        cycle_state = (state.get("cycle_state") or {}) if isinstance(state, dict) else {}
        fill_metadata = dict(getattr(fill_event, "metadata", {}) or {})
        payload_data = payload or {}
        payload_fill = payload_data.get("fill") or {}
        payload_metadata = payload_fill.get("metadata") or {}
        candidates = [
            fill_metadata.get("symbol"),
            payload_data.get("symbol"),
            payload_fill.get("symbol"),
            payload_metadata.get("symbol"),
            getattr(snapshot, "symbol", None),
            getattr(getattr(runtime_state, "last_snapshot", None), "symbol", None),
            cycle_state.get("symbol"),
            state.get("last_trade_symbol"),
            self.config.symbol,
        ]
        for candidate in candidates:
            text = str(candidate or "").strip().upper()
            if text:
                return text
        return ""

    @staticmethod
    def _pct(value: float) -> float:
        return value / 100.0

    @staticmethod
    def _clamp_pct_fraction(value: float, max_fraction: float = 0.9999) -> float:
        return max(min(value, max_fraction), 0.0)

    def _fast_path_second_order(
        self,
        fill_event: FillEvent,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent]:
        open_initial_orders = self._collect_open_initial_entry_orders(snapshot)
        if open_initial_orders:
            self._emit_throttled_strategy_audit(
                runtime_state,
                context,
                "fixed_cycle_fast_path_skip",
                {
                    "skip_reason": "initial_entry_order_still_open",
                    "open_initial_orders": open_initial_orders,
                },
                signature_key="fast_path_skip",
                interval_ms=120000,
            )
            return []

        side = fill_event.side
        state = runtime_state.strategy_state
        key = "current_long_cycle_index" if side == "long" else "current_short_cycle_index"
        current_cycle_index = int(state.get(key) or 0)
        if current_cycle_index < 1:
            return []

        target_cycle = current_cycle_index + 1
        purpose = self._cycle_purpose(side, target_cycle)
        candidate = next(
            (
                order
                for order in snapshot.active_orders
                if order.purpose == purpose and order.is_open()
            ),
            None,
        )
        if not candidate:
            return []

        trigger_price = self._safe_float(candidate.metadata.get("trigger_price"), None)
        if trigger_price is None:
            return []

        distance_pct = self._pct(
            self.config.long_fill_distance_pct
            if side == "long"
            else self.config.short_fill_distance_pct
        )
        extra_offset = self._pct(self.config.second_order_safety_offset_pct) if target_cycle == 2 else 0.0
        multiplier = 1 - (distance_pct * target_cycle) - extra_offset
        corrected_trigger_price = self._normalize_price(
            max(fill_event.exec_price * multiplier, self.config.price_tick_size),
            runtime_state,
        )

        tick = self.config.price_tick_size or 1e-9
        too_high = (
            trigger_price > corrected_trigger_price + tick
            if side == "long"
            else trigger_price < corrected_trigger_price - tick
        )
        if not too_high:
            return []

        if context.cancel_open_orders_by_purpose:
            self._register_expected_exit_order_deactivations(runtime_state, purposes=[purpose], replacement_purpose=purpose)
            context.cancel_open_orders_by_purpose([purpose])

        current_price = snapshot.current_price
        limit_still_valid = (
            (side == "long" and current_price > corrected_trigger_price)
            or (side == "short" and current_price < corrected_trigger_price)
        )

        intents: list[StrategyIntent] = []
        metadata = dict(candidate.metadata)
        metadata.setdefault("cycle_index", target_cycle)
        metadata.setdefault("replace_open_purpose", purpose)
        metadata.setdefault("entry_reference_price", float(state.get("entry_reference_price") or snapshot.current_price))

        if not limit_still_valid:
            context.audit.log_event(
                "limit_rejected_market_fallback",
                strategy=self.name,
                purpose=purpose,
                side=side,
                qty=candidate.qty,
                price=trigger_price,
                order_link_id=candidate.client_order_id,
                original_order_type="Limit",
                fallback_order_type="Market",
                slippage_tolerance_type=self.config.market_fallback_slippage_type,
                slippage_tolerance=self.config.market_fallback_slippage_value,
            )
            metadata["slippage_tolerance_type"] = self.config.market_fallback_slippage_type
            metadata["slippage_tolerance"] = self.config.market_fallback_slippage_value
            intents.append(
                StrategyIntent(
                    side=side,
                    qty=candidate.qty,
                    purpose=purpose,
                    order_type="Market",
                    reduce_only=(side == "short"),
                    metadata=metadata,
                )
            )
        else:
            metadata["trigger_price"] = corrected_trigger_price
            intents.append(
                StrategyIntent(
                    side=side,
                    qty=candidate.qty,
                    purpose=purpose,
                    order_type="Limit",
                    price=corrected_trigger_price + (self.config.price_tick_size if side == "long" else -self.config.price_tick_size),
                    reduce_only=(side == "short"),
                    trigger_price=corrected_trigger_price,
                    trigger_direction=2,
                    trigger_by="LastPrice",
                    order_filter="StopOrder",
                    metadata=metadata,
                )
            )
        return intents

    @staticmethod
    def _seed_long_fill_closed_pnl_fields(long_fill: dict, order_id: str | None = None) -> None:
        if order_id:
            long_fill["order_id"] = order_id
        long_fill.setdefault("order_id", "")
        long_fill.setdefault("closed_pnl", None)
        long_fill.setdefault("closed_qty", None)
        long_fill.setdefault("closed_avg_price", None)
        long_fill.setdefault("closed_cost", None)
        long_fill.setdefault("closed_pnl_ready", False)
        long_fill.setdefault("closed_pnl_updated_time", None)
        long_fill.setdefault("fill_count", None)

    def _merge_long_fill_pnl_metadata(
        self,
        existing_long_fill: dict[str, Any] | None,
        new_long_fill: dict[str, Any] | None,
        *,
        fill_event: FillEvent | None = None,
        cycle_index: int | None = None,
        source: str,
    ) -> dict[str, Any]:
        existing = dict(existing_long_fill or {})
        incoming = dict(new_long_fill or {})
        merged = dict(existing)
        for key, value in incoming.items():
            if value is not None or key not in merged:
                merged[key] = value

        existing_metadata = dict(existing.get("metadata") or {})
        incoming_metadata = dict(incoming.get("metadata") or {})
        fill_metadata = dict(getattr(fill_event, "metadata", {}) or {})
        metadata = dict(existing_metadata)
        for key, value in incoming_metadata.items():
            if value is not None or key not in metadata:
                metadata[key] = value
        for key, value in fill_metadata.items():
            if value is not None or key not in metadata:
                metadata[key] = value

        def _first_numeric(*values: Any) -> float | None:
            for candidate in values:
                parsed = self._safe_float(candidate, None)
                if parsed is not None:
                    return parsed
            return None

        def _first_value(*values: Any) -> Any:
            for candidate in values:
                if candidate is not None:
                    return candidate
            return None

        merged["pnl_this_fill"] = _first_numeric(
            merged.get("pnl_this_fill"),
            getattr(fill_event, "pnl_this_fill", None),
        )
        merged["closed_pnl"] = _first_numeric(
            merged.get("closed_pnl"),
            getattr(fill_event, "closed_pnl", None),
            metadata.get("closed_pnl"),
        )
        merged["confirmed_closed_pnl"] = _first_numeric(
            merged.get("confirmed_closed_pnl"),
            metadata.get("confirmed_closed_pnl"),
        )
        merged["long_reduce_closed_pnl"] = _first_numeric(
            merged.get("long_reduce_closed_pnl"),
            metadata.get("long_reduce_closed_pnl"),
        )
        merged["long_add_confirmed_pnl"] = _first_numeric(
            merged.get("long_add_confirmed_pnl"),
            metadata.get("long_add_confirmed_pnl"),
        )
        merged["runtime_calculated_pnl"] = _first_numeric(
            merged.get("runtime_calculated_pnl"),
            metadata.get("runtime_calculated_pnl"),
        )
        merged["exec_pnl"] = _first_numeric(
            merged.get("exec_pnl"),
            metadata.get("exec_pnl"),
        )
        merged["long_closed_pnl"] = _first_numeric(
            merged.get("long_closed_pnl"),
            metadata.get("long_closed_pnl"),
        )
        merged["confirmed_closed_qty"] = _first_numeric(
            merged.get("confirmed_closed_qty"),
            metadata.get("confirmed_closed_qty"),
        )
        merged["confirmed_closed_avg_price"] = _first_numeric(
            merged.get("confirmed_closed_avg_price"),
            metadata.get("confirmed_closed_avg_price"),
        )
        merged["closed_pnl_source"] = _first_value(
            merged.get("closed_pnl_source"),
            metadata.get("closed_pnl_source"),
        )
        merged["pnl_source"] = _first_value(
            merged.get("pnl_source"),
            metadata.get("pnl_source"),
        )

        loss_source = _first_numeric(
            merged.get("confirmed_closed_pnl"),
            merged.get("long_reduce_closed_pnl"),
        )
        existing_long_add_loss_usdt = _first_numeric(
            merged.get("long_add_loss_usdt"),
            metadata.get("long_add_loss_usdt"),
        )
        if loss_source is not None and float(loss_source) < 0:
            merged["long_add_loss_usdt"] = abs(float(loss_source))
        elif (
            existing_long_add_loss_usdt is not None
            and float(existing_long_add_loss_usdt) > 0
        ):
            merged["long_add_loss_usdt"] = float(existing_long_add_loss_usdt)
        else:
            merged["long_add_loss_usdt"] = 0.0
        merged["closed_pnl_ready"] = bool(
            merged.get("closed_pnl_ready")
            or merged.get("confirmed_closed_pnl") is not None
            or merged.get("long_reduce_closed_pnl") is not None
            or merged.get("closed_pnl") is not None
        )

        mirror_fields = (
            "closed_pnl",
            "confirmed_closed_pnl",
            "long_reduce_closed_pnl",
            "long_add_confirmed_pnl",
            "runtime_calculated_pnl",
            "exec_pnl",
            "long_closed_pnl",
            "confirmed_closed_qty",
            "confirmed_closed_avg_price",
            "closed_pnl_source",
            "pnl_source",
            "pnl_this_fill",
        )
        for field in mirror_fields:
            top_level_value = merged.get(field)
            metadata_value = metadata.get(field)
            if top_level_value is not None and metadata_value is None:
                metadata[field] = top_level_value
            elif metadata_value is not None and top_level_value is None:
                merged[field] = metadata_value
        merged["metadata"] = metadata

        _log_event(
            "fixed_cycle_long_fill_pnl_metadata_merged",
            {
                "cycle_index": cycle_index,
                "purpose": merged.get("purpose") or getattr(fill_event, "purpose", None),
                "exchange_order_id": merged.get("exchange_order_id")
                or merged.get("order_id")
                or getattr(fill_event, "exchange_order_id", None),
                "long_fill_top_level_keys": sorted(list(merged.keys())),
                "long_fill_metadata_keys": sorted(list(metadata.keys())),
                "pnl_this_fill": merged.get("pnl_this_fill"),
                "closed_pnl": merged.get("closed_pnl"),
                "confirmed_closed_pnl": merged.get("confirmed_closed_pnl"),
                "long_reduce_closed_pnl": merged.get("long_reduce_closed_pnl"),
                "runtime_calculated_pnl": merged.get("runtime_calculated_pnl"),
                "exec_pnl": merged.get("exec_pnl"),
                "long_add_loss_usdt": merged.get("long_add_loss_usdt"),
                "closed_pnl_ready": bool(merged.get("closed_pnl_ready")),
                "source": source,
            },
        )
        return merged

    def _make_closed_pnl_signature(self, row: dict[str, Any]) -> str:
        return "|".join([
            str(row.get("symbol") or ""),
            str(row.get("side") or ""),
            str(row.get("closedSize") or row.get("qty") or ""),
            str(row.get("avgEntryPrice") or ""),
            str(row.get("avgExitPrice") or ""),
            str(row.get("closedPnl") or ""),
            str(row.get("createdTime") or ""),
            str(row.get("updatedTime") or ""),
        ])

    def _expected_bybit_closed_pnl_side(self, long_fill: dict[str, Any]) -> str | None:
        purpose = (long_fill.get("purpose") or "").upper()
        if "LONG" in purpose:
            return "Sell"
        if "SHORT" in purpose:
            return "Buy"
        role = (long_fill.get("cycle_role") or "").lower()
        if role == "long_reduce":
            return "Sell"
        if role == "short_reduce":
            return "Buy"
        return None

    @staticmethod
    def _is_close(a: float | None, b: float | None, tol: float) -> bool:
        if a is None or b is None:
            return False
        try:
            return abs(float(a) - float(b)) <= tol
        except Exception:
            return False

    def _select_closed_pnl_match(
        self,
        rows: list[dict[str, Any]],
        *,
        expected_symbol: str,
        expected_side: str | None,
        expected_qty: float,
        expected_fill_price: float,
        start_time_ms: int | None,
        end_time_ms: int | None,
        processed_signatures: set[str],
        qty_tolerance: float,
        price_tolerance: float,
    ) -> tuple[dict[str, Any] | None, str | None, int | None]:
        best = None
        best_score = -1
        best_sig = None
        for row in rows:
            if str(row.get("symbol") or "").upper() != expected_symbol.upper():
                continue
            sig = self._make_closed_pnl_signature(row)
            if sig in processed_signatures:
                continue
            row_side = row.get("side")
            if expected_side and row_side != expected_side:
                continue
            row_qty = row.get("closedSize") or row.get("qty")
            row_price = row.get("avgExitPrice")
            score = 0
            if self._is_close(row_qty, expected_qty, qty_tolerance):
                score += 40
            if self._is_close(row_price, expected_fill_price, price_tolerance):
                score += 40
            row_time = row.get("updatedTime") or row.get("createdTime")
            try:
                row_time_ms = int(row_time) if row_time is not None else None
            except Exception:
                row_time_ms = None
            if row_time_ms and start_time_ms is not None and end_time_ms is not None and start_time_ms <= row_time_ms <= end_time_ms:
                score += 20
            if score > best_score:
                best = row
                best_score = score
                best_sig = sig
        if best_score >= 80:
            return best, best_sig, best_score
        return None, None, None

    def _make_closed_pnl_signature(self, row: dict[str, Any]) -> str:
        parts = [
            str(row.get("symbol") or ""),
            str(row.get("side") or ""),
            str(row.get("closedSize") or row.get("qty") or ""),
            str(row.get("avgEntryPrice") or ""),
            str(row.get("avgExitPrice") or ""),
            str(row.get("closedPnl") or ""),
            str(row.get("createdTime") or ""),
            str(row.get("updatedTime") or ""),
        ]
        return "|".join(parts)

    def _expected_bybit_closed_pnl_side(self, long_fill: dict[str, Any]) -> str | None:
        purpose = (long_fill.get("purpose") or "").upper()
        if "LONG" in purpose:
            return "Sell"
        if "SHORT" in purpose:
            return "Buy"
        role = (long_fill.get("cycle_role") or "").lower()
        if role == "long_reduce":
            return "Sell"
        if role == "short_reduce":
            return "Buy"
        return None

    @staticmethod
    def _is_close(a: float | None, b: float | None, tol: float) -> bool:
        if a is None or b is None:
            return False
        try:
            return abs(float(a) - float(b)) <= tol
        except Exception:
            return False

    def _select_closed_pnl_match(
        self,
        rows: list[dict[str, Any]],
        *,
        expected_symbol: str,
        expected_side: str | None,
        expected_qty: float,
        expected_fill_price: float,
        start_time_ms: int | None,
        end_time_ms: int | None,
        processed_signatures: set[str],
        qty_tolerance: float,
        price_tolerance: float,
    ) -> tuple[dict[str, Any] | None, str | None, int | None]:
        best_row: dict[str, Any] | None = None
        best_score = -1
        best_sig: str | None = None
        for row in rows:
            if str(row.get("symbol") or "").upper() != expected_symbol.upper():
                continue
            sig = self._make_closed_pnl_signature(row)
            if sig in processed_signatures:
                continue
            if expected_side and row.get("side") != expected_side:
                continue
            row_qty = row.get("closedSize") or row.get("qty")
            row_price = row.get("avgExitPrice")
            score = 0
            if self._is_close(row_qty, expected_qty, qty_tolerance):
                score += 40
            if self._is_close(row_price, expected_fill_price, price_tolerance):
                score += 40
            row_time = row.get("updatedTime") or row.get("createdTime")
            try:
                row_time_ms = int(row_time) if row_time is not None else None
            except Exception:
                row_time_ms = None
            if (
                row_time_ms
                and start_time_ms is not None
                and end_time_ms is not None
                and start_time_ms <= row_time_ms <= end_time_ms
            ):
                score += 20
            if score > best_score:
                best_row = row
                best_score = score
                best_sig = sig
        if best_score >= 80:
            return best_row, best_sig, best_score
        return None, None, None

    def _make_closed_pnl_signature(self, row: dict[str, Any]) -> str:
        parts = [
            str(row.get("symbol") or ""),
            str(row.get("side") or ""),
            str(row.get("closedSize") or row.get("qty") or ""),
            str(row.get("avgEntryPrice") or ""),
            str(row.get("avgExitPrice") or ""),
            str(row.get("closedPnl") or ""),
            str(row.get("createdTime") or ""),
            str(row.get("updatedTime") or ""),
        ]
        return "|".join(parts)

    def _expected_bybit_closed_pnl_side(self, long_fill: dict[str, Any]) -> str | None:
        purpose = (long_fill.get("purpose") or "").upper()
        if "LONG" in purpose:
            return "Sell"
        if "SHORT" in purpose:
            return "Buy"
        cycle_role = (long_fill.get("cycle_role") or "").lower()
        if cycle_role == "long_reduce":
            return "Sell"
        if cycle_role == "short_reduce":
            return "Buy"
        return None

    @staticmethod
    def _is_close(a: float | None, b: float | None, tol: float) -> bool:
        if a is None or b is None:
            return False
        try:
            return abs(float(a) - float(b)) <= tol
        except Exception:
            return False

    def _select_closed_pnl_match(
        self,
        rows: list[dict[str, Any]],
        *,
        expected_symbol: str,
        expected_side: str | None,
        expected_qty: float,
        expected_fill_price: float,
        start_time_ms: int | None,
        end_time_ms: int | None,
        processed_signatures: set[str],
        qty_tolerance: float,
        price_tolerance: float,
    ) -> tuple[dict[str, Any] | None, str | None, int | None]:
        best: dict[str, Any] | None = None
        best_score = -1
        best_sig: str | None = None
        for row in rows:
            row_symbol = str(row.get("symbol") or "")
            if row_symbol.upper() != expected_symbol.upper():
                logger.info(
                    "closed_pnl_robust_candidate_rejected",
                    extra={
                        "reason": "symbol_mismatch",
                        "expected_symbol": expected_symbol,
                        "row_symbol": row_symbol,
                        "row_order_id": row.get("orderId"),
                        "row_qty": row.get("closedSize") or row.get("qty"),
                        "row_avg_exit": row.get("avgExitPrice"),
                        "row_closed_pnl": row.get("closedPnl"),
                    },
                )
                continue
            sig = self._make_closed_pnl_signature(row)
            if sig in processed_signatures:
                logger.debug(
                    "closed_pnl_signature_skipped %s",
                    {
                        "signature": sig,
                        "reason": "already_processed",
                        "row_order_id": row.get("orderId"),
                    },
                )
                continue
            row_qty = row.get("closedSize") or row.get("qty")
            row_price = row.get("avgExitPrice")
            row_side = str(row.get("side") or "").strip().lower()
            expected_side_norm = str(expected_side or "").strip().lower()
            if expected_side_norm and row_side != expected_side_norm:
                logger.info(
                    "closed_pnl_robust_candidate_rejected",
                    extra={
                        "reason": "side_mismatch",
                        "expected_side": expected_side,
                        "row_side": row.get("side"),
                        "row_order_id": row.get("orderId"),
                        "row_symbol": row_symbol,
                        "row_qty": row_qty,
                        "row_avg_exit": row_price,
                        "row_closed_pnl": row.get("closedPnl"),
                        "signature": sig,
                    },
                )
                continue
            score = 0
            if self._is_close(row_qty, expected_qty, qty_tolerance):
                score += 40
            if self._is_close(row_price, expected_fill_price, price_tolerance):
                score += 40
            row_time = row.get("updatedTime") or row.get("createdTime")
            try:
                row_time_int = int(row_time) if row_time is not None else None
            except Exception:
                row_time_int = None
            if (
                row_time_int
                and start_time_ms is not None
                and end_time_ms is not None
                and start_time_ms <= row_time_int <= end_time_ms
            ):
                score += 20
            if score > best_score:
                best = row
                best_score = score
                best_sig = sig
                logger.info(
                    "closed_pnl_robust_candidate",
                    extra={
                        "expected_symbol": expected_symbol,
                        "row_order_id": row.get("orderId"),
                        "signature": sig,
                        "score": score,
                        "row_side": row_side,
                        "row_qty": row_qty,
                        "row_avg_exit": row_price,
                        "expected_qty": expected_qty,
                        "expected_fill_price": expected_fill_price,
                        "qty_tolerance": qty_tolerance,
                        "price_tolerance": price_tolerance,
                        "start_time_ms": start_time_ms,
                        "end_time_ms": end_time_ms,
                        "row_time_ms": row_time_int,
                    },
                )
        if best_score >= 80:
            return best, best_sig, best_score
        return None, None, None

    def _refresh_long_fill_closed_pnl(
        self,
        *,
        cycle_index: int,
        long_fill: dict,
        runtime_state: RuntimeState,
        context: StrategyContext,
        occurred_at_ms: int | None = None,
        exec_id: str | None = None,
        fill_event: FillEvent | None = None,
    ) -> bool:
        self._seed_long_fill_closed_pnl_fields(long_fill)
        order_id = str(long_fill.get("order_id") or "").strip()
        order_manager = getattr(context, "order_manager", None)
        fetcher = getattr(order_manager, "fetch_closed_pnl", None) if order_manager else None
        if not order_id and fill_event is not None:
            seeded_order_id = str(fill_event.exchange_order_id or "").strip()
            if seeded_order_id:
                order_id = seeded_order_id
                long_fill["order_id"] = seeded_order_id
                _log_event(
                    "closed_pnl_fetch_seeded_from_fill_event_order_id",
                    {
                        "cycle_index": cycle_index,
                        "exchange_order_id": seeded_order_id,
                        "client_order_id": fill_event.client_order_id,
                        "exec_id": fill_event.exec_id,
                        "purpose": fill_event.purpose,
                    },
                )
        if not order_id or not callable(fetcher):
            return False
        fetch_symbol = self._active_trade_symbol(
            runtime_state.last_snapshot,
            runtime_state,
            fill_event=fill_event,
            payload=long_fill,
        )

        logger.debug(
            "closed_pnl_fetch_started",
            extra={
                "order_id": order_id,
                "cycle_index": cycle_index,
                "symbol": fetch_symbol,
                "decision": "fetch",
                "closed_pnl": long_fill.get("closed_pnl"),
                "closed_qty": long_fill.get("closed_qty"),
            },
        )
        start_time_ms = max(occurred_at_ms - 300_000, 0) if occurred_at_ms is not None else None
        end_time_ms = (
            (occurred_at_ms + 15 * 60 * 1000) if occurred_at_ms is not None else None
        )
        start_time_iso = (
            datetime.fromtimestamp(start_time_ms / 1000, tz=timezone.utc).isoformat()
            if start_time_ms is not None
            else None
        )
        end_time_iso = (
            datetime.fromtimestamp(end_time_ms / 1000, tz=timezone.utc).isoformat()
            if end_time_ms is not None
            else None
        )
        expected_side = long_fill.get("side") or "long"
        expected_qty = long_fill.get("qty") or long_fill.get("total_qty") or 0.0
        expected_fill_price = long_fill.get("price") or 0.0
        if fetch_symbol and fetch_symbol != str(self.config.symbol or "").upper():
            _log_event(
                "fixed_cycle_closed_pnl_retry_uses_fill_symbol",
                {
                    "expected_order_id": order_id,
                    "cycle_index": cycle_index,
                    "fill_symbol": fetch_symbol,
                    "config_symbol": str(self.config.symbol or "").upper(),
                    "purpose": long_fill.get("purpose"),
                },
            )
        logger.info(
            "closed_pnl_fetch_window",
            extra={
                "expected_order_id": order_id,
                "expected_symbol": fetch_symbol,
                "expected_side": expected_side,
                "expected_qty": expected_qty,
                "expected_fill_price": expected_fill_price,
                "cycle_index": cycle_index,
                "occurred_at_ms": occurred_at_ms,
                "start_time_ms": start_time_ms,
                "end_time_ms": end_time_ms,
                "start_time_iso_utc": start_time_iso,
                "end_time_iso_utc": end_time_iso,
                "source": "strict_order_id_match_current",
            },
        )
        rows = fetcher(
            fetch_symbol,
            self.config.category,
            limit=100,
            start_time_ms=start_time_ms,
        )
        rows_preview = []
        if rows:
            for row in rows[:10]:
                created_time = row.get("createdTime")
                updated_time = row.get("updatedTime")
                try:
                    created_time = int(created_time) if created_time is not None else None
                except Exception:
                    created_time = None
                try:
                    updated_time = int(updated_time) if updated_time is not None else None
                except Exception:
                    updated_time = None
                rows_preview.append(
                    {
                        "orderId": row.get("orderId"),
                        "symbol": row.get("symbol"),
                        "side": row.get("side"),
                        "closedSize": row.get("closedSize") or row.get("qty"),
                        "avgEntryPrice": row.get("avgEntryPrice"),
                        "avgExitPrice": row.get("avgExitPrice"),
                        "closedPnl": row.get("closedPnl"),
                        "createdTime": created_time,
                        "updatedTime": updated_time,
                        "createdTime_iso_utc": datetime.fromtimestamp(
                            created_time / 1000, tz=timezone.utc
                        ).isoformat()
                        if created_time
                        else None,
                        "updatedTime_iso_utc": datetime.fromtimestamp(
                            updated_time / 1000, tz=timezone.utc
                        ).isoformat()
                        if updated_time
                        else None,
                    }
                )
        logger.info(
            "closed_pnl_rows_received",
            extra={
                "expected_order_id": order_id,
                "rows_count": len(rows or []),
                "rows_preview": rows_preview,
            },
        )
        if not rows:
            logger.debug(
                "closed_pnl_not_yet_available",
                extra={
                    "order_id": order_id,
                    "cycle_index": cycle_index,
                    "symbol": fetch_symbol,
                    "decision": "deferred",
                    "closed_pnl": None,
                    "closed_qty": None,
                },
            )
            logger.debug(
                "closed_pnl_no_match_debug %s",
                {
                    "expected_order_id": order_id,
                    "expected_symbol": fetch_symbol,
                    "expected_qty": expected_qty,
                    "expected_fill_price": expected_fill_price,
                    "rows_count": 0,
                    "row_order_ids": [],
                    "row_symbols": [],
                    "row_sizes": [],
                    "row_exit_prices": [],
                    "row_closed_pnls": [],
                    "reason": "strict_order_id_symbol_match_failed",
                },
            )
            return False

        cycle_state = runtime_state.strategy_state.setdefault("cycle_state", {})
        processed_signatures = set(cycle_state.get("processed_closed_pnl_signatures") or [])
        symbol, rules, _ = self._resolve_instrument_rules(
            runtime_state,
            symbol_override=fetch_symbol,
        )
        expected_symbol = symbol
        expected_order_id = order_id
        expected_qty = float(
            long_fill.get("total_qty")
            or long_fill.get("qty")
            or long_fill.get("closed_qty")
            or 0.0
        )
        expected_fill_price = float(
            long_fill.get("avg_fill_price")
            or long_fill.get("price")
            or long_fill.get("fill_price")
            or 0.0
        )
        expected_side = self._expected_bybit_closed_pnl_side(long_fill)
        fallback_rules = rules or {}
        qty_step = float(fallback_rules.get("qty_step") or Decimal("0.0001"))
        tick_size_candidate = fallback_rules.get("tick_size")
        tick_size = float(
            tick_size_candidate
            if tick_size_candidate
            else Decimal(str(self.config.price_tick_size or 0.0001))
        )
        qty_tolerance = max(qty_step, expected_qty * 0.001)
        price_tolerance = max(tick_size * 2, expected_fill_price * 0.0005)

        matched = None
        matched_sig = None
        matched_score = None
        match_source = None
        for row in rows:
            if (
                str(row.get("orderId") or "").strip() == expected_order_id
                and str(row.get("symbol") or "").upper() == expected_symbol.upper()
            ):
                matched = row
                matched_sig = self._make_closed_pnl_signature(row)
                match_source = "strict_order_id"
                break
        if not matched:
            logger.info(
                "closed_pnl_strict_match_failed",
                extra={
                    "expected_order_id": expected_order_id,
                    "expected_symbol": expected_symbol,
                    "expected_qty": expected_qty,
                    "expected_fill_price": expected_fill_price,
                },
            )
            matched, matched_sig, matched_score = self._select_closed_pnl_match(
                rows,
                expected_symbol=expected_symbol,
                expected_side=expected_side,
                expected_qty=expected_qty,
                expected_fill_price=expected_fill_price,
                start_time_ms=start_time_ms,
                end_time_ms=end_time_ms,
                processed_signatures=processed_signatures,
                qty_tolerance=qty_tolerance,
                price_tolerance=price_tolerance,
            )
            if matched and matched_sig:
                match_source = "robust_signature_match"
                logger.debug(
                    "closed_pnl_robust_match_selected %s",
                    {
                        "expected_order_id": expected_order_id,
                        "expected_symbol": expected_symbol,
                        "signature": matched_sig,
                        "score": matched_score,
                    },
                )
        if not matched:
            row_order_ids = [row.get("orderId") for row in rows]
            row_symbols = [row.get("symbol") for row in rows]
            row_sizes = [row.get("closedSize") or row.get("qty") for row in rows]
            row_exit_prices = [row.get("avgExitPrice") for row in rows]
            row_closed_pnls = [row.get("closedPnl") for row in rows]
            logger.debug(
                "closed_pnl_no_match_debug %s",
                {
                    "expected_order_id": expected_order_id,
                    "expected_symbol": expected_symbol,
                    "expected_qty": expected_qty,
                    "expected_fill_price": expected_fill_price,
                    "rows_count": len(rows),
                    "row_order_ids": row_order_ids,
                    "row_symbols": row_symbols,
                    "row_sizes": row_sizes,
                    "row_exit_prices": row_exit_prices,
                    "row_closed_pnls": row_closed_pnls,
                    "reason": "strict_order_id_symbol_match_failed",
                },
            )
            return False

        if not matched_sig:
            matched_sig = self._make_closed_pnl_signature(matched)
        if matched_sig in processed_signatures:
            logger.debug(
                "closed_pnl_signature_skipped %s",
                {
                    "signature": matched_sig,
                    "reason": "already_processed",
                    "match_source": match_source,
                },
            )
            return False
        processed_signatures.add(matched_sig)
        cycle_state["processed_closed_pnl_signatures"] = list(processed_signatures)[-200:]

        if matched.get("closedPnl") is None:
            _log_event(
                "fixed_cycle_closed_pnl_order_found_but_pnl_missing",
                {
                    "order_id": order_id,
                    "cycle_index": cycle_index,
                    "symbol": fetch_symbol,
                    "match_source": match_source,
                    "reason": "closed_pnl_missing",
                    "row_order_id": matched.get("orderId"),
                },
            )
        matched_pnl = float(matched.get("closedPnl") or 0)
        matched_qty = float(matched.get("closedSize") or matched.get("qty") or 0)
        logger.debug(
            "closed_pnl_row_found",
            extra={
                "order_id": order_id,
                "cycle_index": cycle_index,
                "symbol": fetch_symbol,
                "decision": "found",
                "closed_pnl": matched_pnl,
                "closed_qty": matched_qty,
            },
        )
        logger.info(
            "closed_pnl_row_matched",
            extra={
                "order_id": order_id,
                "cycle_index": cycle_index,
                "symbol": fetch_symbol,
                "decision": "matched",
                "closed_pnl": matched_pnl,
                "closed_qty": matched_qty,
            },
        )

        long_fill["order_id"] = order_id
        long_fill["closed_pnl"] = matched_pnl
        long_fill["closed_qty"] = matched_qty
        long_fill["closed_avg_price"] = self._safe_float(matched.get("avgExitPrice"), None)
        long_fill["closed_cost"] = self._safe_float(matched.get("cumExitValue"), None)
        long_fill["closed_pnl_ready"] = True
        long_fill["closed_pnl_updated_time"] = self._safe_int(
            matched.get("updatedTime") or matched.get("createdTime")
        )
        long_fill["fill_count"] = self._safe_int(matched.get("fillCount"))
        long_fill["confirmed_closed_pnl"] = matched_pnl
        long_fill["confirmed_closed_qty"] = matched_qty
        long_fill["closed_pnl_signature"] = matched_sig
        long_fill["closed_pnl_source"] = match_source or "strict_order_id"
        closed_qty = self._safe_float(matched.get("closedSize") or matched.get("qty"), None)
        closed_avg_price = self._safe_float(matched.get("avgExitPrice") or matched.get("orderPrice"), None)
        closed_cost = self._safe_float(matched.get("cumExitValue"), None)
        if closed_cost is None and closed_qty is not None and closed_avg_price is not None:
            closed_cost = closed_qty * closed_avg_price

        long_fill["order_id"] = order_id
        long_fill["closed_pnl"] = self._safe_float(matched.get("closedPnl"), None)
        long_fill["closed_qty"] = closed_qty
        long_fill["closed_avg_price"] = closed_avg_price
        long_fill["closed_cost"] = closed_cost
        long_fill["closed_pnl_ready"] = long_fill["closed_pnl"] is not None
        long_fill["closed_pnl_updated_time"] = self._safe_int(matched.get("updatedTime") or matched.get("createdTime"))
        long_fill["fill_count"] = self._safe_int(matched.get("fillCount"))
        long_fill["confirmed_closed_pnl"] = long_fill["closed_pnl"]
        long_fill["confirmed_closed_qty"] = closed_qty
        long_fill["confirmed_closed_avg_price"] = closed_avg_price
        long_fill["confirmed_closed_pnl_updated_time"] = long_fill["closed_pnl_updated_time"]
        long_fill["confirmed_pnl_applied"] = long_fill.get("confirmed_pnl_applied", False)
        long_fill["closed_pnl_signature"] = matched_sig
        long_fill["closed_pnl_source"] = match_source or "strict_order_id"
        long_fill["pnl_source"] = long_fill["closed_pnl_source"]
        long_fills = cycle_state.setdefault("long_fills", {})
        long_fill = self._merge_long_fill_pnl_metadata(
            long_fills.get(str(cycle_index)) or {},
            long_fill,
            fill_event=fill_event,
            cycle_index=cycle_index,
            source="refresh_long_fill_closed_pnl",
        )
        long_fills[str(cycle_index)] = long_fill
        self._apply_confirmed_realized_pnl(
            runtime_state=runtime_state,
            client_order_id=long_fill.get("client_order_id"),
            confirmed_pnl=long_fill["confirmed_closed_pnl"],
            side="long",
            exec_id=exec_id or long_fill.get("exec_id"),
            purpose=self._cycle_purpose("long", cycle_index),
            position_idx=1,
            cycle_role="long_reduce",
        )
        if fill_event is not None:
            metadata_applied = self._merge_cycle_closed_pnl_metadata(
                fill_event,
                cycle_index=cycle_index,
                cycle_role="long_reduce",
                confirmed_closed_pnl=long_fill["confirmed_closed_pnl"],
                closed_qty=long_fill["confirmed_closed_qty"],
                closed_avg_price=long_fill["confirmed_closed_avg_price"],
                confirmed_pnl_updated_time=long_fill["confirmed_closed_pnl_updated_time"],
                pnl_source=long_fill["pnl_source"],
            )
            if metadata_applied:
                _log_event(
                    "fixed_cycle_cycle_pnl_refreshed_metadata_applied",
                    {
                        "cycle_index": cycle_index,
                        "client_order_id": long_fill.get("client_order_id"),
                        "exchange_order_id": order_id,
                        "exec_id": exec_id,
                        "confirmed_closed_pnl": long_fill["confirmed_closed_pnl"],
                        "confirmed_closed_qty": long_fill["confirmed_closed_qty"],
                        "confirmed_closed_avg_price": long_fill["confirmed_closed_avg_price"],
                        "pnl_source": long_fill["pnl_source"],
                        "match_source": match_source or "strict_order_id",
                    },
                )
        self._write_confirmed_order_pnl_history(
            {
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "symbol": fetch_symbol,
                "exchange_order_id": order_id,
                "client_order_id": long_fill.get("client_order_id"),
                "purpose": (
                    fill_event.purpose
                    if fill_event is not None and fill_event.purpose
                    else self._cycle_purpose("long", cycle_index)
                ),
                "closed_pnl": long_fill.get("confirmed_closed_pnl"),
                "trade_block_id": self._resolve_active_trade_block_id(runtime_state.strategy_state),
                "cycle_index": cycle_index,
                "pnl_scope": "cycle",
                # Optional: bereits gemergte Stage-/Split-/Role-Felder aus long_fill übernehmen, falls vorhanden.
                "parent_purpose": long_fill.get("parent_second_leg_purpose") or long_fill.get("parent_purpose"),
                "parent_second_leg_purpose": long_fill.get("parent_second_leg_purpose"),
                "stage_index": long_fill.get("stage_index"),
                "stage_count": long_fill.get("stage_count"),
                "split_index": long_fill.get("split_stage_index") or long_fill.get("split_index"),
                "split_count": long_fill.get("split_stage_count") or long_fill.get("split_count"),
                "cycle_role": long_fill.get("cycle_role"),
                "first_leg_cycle_role": long_fill.get("first_leg_cycle_role"),
                "second_leg_cycle_role": long_fill.get("second_leg_cycle_role"),
                "order_source": long_fill.get("order_source") or long_fill.get("source"),
                "qty": long_fill.get("confirmed_closed_qty"),
                "exec_qty": long_fill.get("confirmed_closed_qty"),
                "side": long_fill.get("side"),
                "fill_price": long_fill.get("confirmed_closed_avg_price"),
                "avg_fill_price": long_fill.get("confirmed_closed_avg_price"),
            },
            runtime_state=runtime_state,
        )
        return bool(long_fill["closed_pnl_ready"])

    def _maybe_write_provisional_confirmed_cycle_order_pnl(
        self,
        fill_event: FillEvent,
        runtime_state: RuntimeState,
        *,
        fill_type: str,
        cycle_index: int,
        reason: str,
    ) -> bool:
        if fill_type not in {"cycle_long_reduce", "cycle_short_tp"}:
            return False
        if self._has_confirmed_cycle_closed_pnl(fill_event, fill_type):
            return False
        metadata = fill_event.metadata or {}
        provisional_pnl = self._safe_float(metadata.get("runtime_calculated_pnl"), None)
        pnl_source = "provisional_runtime_calculated_pnl"
        if provisional_pnl is None:
            provisional_pnl = self._safe_float(metadata.get("exec_pnl"), None)
            pnl_source = "provisional_exec_pnl"
        if provisional_pnl is None:
            return False
        exchange_order_id = str(fill_event.exchange_order_id or "").strip()
        purpose = str(fill_event.purpose or "").strip()
        if not exchange_order_id or not purpose:
            return False
        dedupe_key = f"{exchange_order_id}:{purpose}"
        written_keys = set(
            str(value)
            for value in (runtime_state.strategy_state.get("processed_confirmed_order_keys") or [])
        )
        if dedupe_key in written_keys:
            return True
        self._merge_cycle_closed_pnl_metadata(
            fill_event,
            cycle_index=cycle_index,
            cycle_role="long_reduce" if fill_type == "cycle_long_reduce" else "short_reduce",
            confirmed_closed_pnl=float(provisional_pnl),
            closed_qty=float(fill_event.exec_qty or 0.0) or None,
            closed_avg_price=float(fill_event.exec_price or 0.0) or None,
            pnl_source=pnl_source,
        )
        fill_event.confirmed_pnl = float(provisional_pnl)
        self._write_confirmed_order_pnl_history(
            {
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "symbol": self._active_trade_symbol(
                    runtime_state.last_snapshot,
                    runtime_state,
                    fill_event=fill_event,
                ),
                "exchange_order_id": exchange_order_id,
                "client_order_id": fill_event.client_order_id,
                "purpose": purpose,
                "closed_pnl": float(provisional_pnl),
                "trade_block_id": self._resolve_active_trade_block_id(runtime_state.strategy_state),
                "cycle_index": cycle_index,
                "pnl_scope": "cycle",
                "pnl_source": pnl_source,
                "confirmed_via": reason,
                # Split-/Stage-Metadata direkt aus dem Fill übernehmen, falls vorhanden.
                "parent_purpose": (fill_event.metadata or {}).get("parent_second_leg_purpose")
                or (fill_event.metadata or {}).get("parent_purpose"),
                "parent_second_leg_purpose": (fill_event.metadata or {}).get("parent_second_leg_purpose"),
                "stage_index": (fill_event.metadata or {}).get("stage_index"),
                "stage_count": (fill_event.metadata or {}).get("stage_count"),
                "split_index": (fill_event.metadata or {}).get("split_stage_index"),
                "split_count": (fill_event.metadata or {}).get("split_stage_count"),
                "cycle_role": (fill_event.metadata or {}).get("cycle_role"),
                "first_leg_cycle_role": (fill_event.metadata or {}).get("first_leg_cycle_role"),
                "second_leg_cycle_role": (fill_event.metadata or {}).get("second_leg_cycle_role"),
                "order_source": (fill_event.metadata or {}).get("source"),
                "qty": float(fill_event.exec_qty or 0.0) if fill_event.exec_qty is not None else None,
                "exec_qty": float(fill_event.exec_qty or 0.0) if fill_event.exec_qty is not None else None,
                "side": fill_event.side,
                "fill_price": float(fill_event.exec_price or 0.0) if fill_event.exec_price is not None else None,
                "avg_fill_price": (
                    float((fill_event.metadata or {}).get("confirmed_closed_avg_price") or 0.0)
                    if (fill_event.metadata or {}).get("confirmed_closed_avg_price") is not None
                    else None
                ),
            },
            runtime_state=runtime_state,
        )
        _log_event(
            "fixed_cycle_confirmed_order_pnl_written_from_provisional_fallback",
            {
                "exchange_order_id": exchange_order_id,
                "client_order_id": fill_event.client_order_id,
                "purpose": purpose,
                "cycle_index": cycle_index,
                "fill_type": fill_type,
                "closed_pnl": float(provisional_pnl),
                "pnl_source": pnl_source,
                "reason": reason,
            },
        )
        return True

    def _write_refill_documentation_confirmed_row(
        self,
        fill_event: FillEvent,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        state: dict[str, Any],
        *,
        pnl_scope: str,
        pnl_source: str,
        confirmed_via: str,
        cycle_index: int | None = None,
        order_source: str | None = None,
        recovery_reload_id: str | None = None,
        refill_batch_id: str | None = None,
        refill_trigger_reason: str | None = None,
        stage_index: int | None = None,
        stage_count: int | None = None,
    ) -> None:
        if fill_event.status != "FILLED":
            return
        exchange_order_id = str(fill_event.exchange_order_id or "").strip()
        purpose = str(fill_event.purpose or "").strip()
        if not exchange_order_id or not purpose:
            return
        if self._cycle_order_confirmed(runtime_state, exchange_order_id, purpose):
            return

        exec_qty = float(fill_event.exec_qty or 0.0)
        fill_price = float(fill_event.exec_price or 0.0)
        side = str(fill_event.side or "").strip().lower()
        if side not in {"long", "short"}:
            if purpose == "REFILL_LONG" or self._is_recovery_reload_long_purpose(purpose):
                side = "long"
            elif purpose == "REFILL_SHORT" or self._is_recovery_reload_short_purpose(purpose):
                side = "short"
            else:
                side = ""

        metadata = dict(fill_event.metadata or {})
        resolved_cycle_index = cycle_index
        if resolved_cycle_index is None or resolved_cycle_index <= 0:
            try:
                resolved_cycle_index = int(metadata.get("cycle_index") or 0) or None
            except (TypeError, ValueError):
                resolved_cycle_index = None
        if resolved_cycle_index is None or resolved_cycle_index <= 0:
            try:
                active_cycle = int(state.get("active_cycle_index") or 0)
                resolved_cycle_index = active_cycle or None
            except (TypeError, ValueError):
                resolved_cycle_index = None

        occurred_at = fill_event.occurred_at
        timestamp = (
            occurred_at.isoformat()
            if occurred_at is not None
            else datetime.now(timezone.utc).isoformat()
        )

        payload: dict[str, Any] = {
            "timestamp": timestamp,
            "symbol": snapshot.symbol or self.config.symbol,
            "exchange_order_id": exchange_order_id,
            "client_order_id": fill_event.client_order_id,
            "purpose": purpose,
            "closed_pnl": 0.0,
            "trade_block_id": self._resolve_active_trade_block_id(state),
            "cycle_index": resolved_cycle_index,
            "pnl_scope": pnl_scope,
            "pnl_source": pnl_source,
            "confirmed_via": confirmed_via,
            "qty": exec_qty,
            "exec_qty": exec_qty,
            "side": side or None,
        }
        if fill_price > 0:
            payload["fill_price"] = fill_price
            payload["avg_fill_price"] = fill_price
        if order_source:
            payload["order_source"] = order_source
        if refill_batch_id:
            payload["refill_batch_id"] = refill_batch_id
        if refill_trigger_reason is not None:
            payload["refill_trigger_reason"] = refill_trigger_reason
        if recovery_reload_id:
            payload["recovery_reload_id"] = recovery_reload_id
        if stage_index is not None:
            payload["stage_index"] = stage_index
        if stage_count is not None:
            payload["stage_count"] = stage_count

        try:
            self._write_confirmed_order_pnl_history(payload, runtime_state=runtime_state)
        except Exception:
            _log_warning_event(
                "fixed_cycle_refill_confirmed_history_write_failed",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "purpose": purpose,
                    "trade_block_id": payload.get("trade_block_id"),
                    "cycle_index": resolved_cycle_index,
                    "client_order_id": fill_event.client_order_id,
                    "exchange_order_id": exchange_order_id,
                    "pnl_scope": pnl_scope,
                },
            )

    def _write_confirmed_order_pnl_history(
        self,
        payload: dict[str, Any],
        runtime_state: RuntimeState | None = None,
    ) -> None:
        record = {
            "timestamp": payload.get("timestamp") or datetime.now(timezone.utc).isoformat(),
            "symbol": payload.get("symbol") or self.config.symbol,
            "exchange_order_id": payload.get("exchange_order_id"),
            "client_order_id": payload.get("client_order_id"),
            "purpose": payload.get("purpose"),
            "closed_pnl": payload.get("closed_pnl"),
            "source": "bot_confirmed_pnl",
            "trade_block_id": payload.get("trade_block_id"),
            "cycle_index": payload.get("cycle_index"),
            "pnl_scope": payload.get("pnl_scope"),
            "pnl_source": payload.get("pnl_source"),
            "confirmed_via": payload.get("confirmed_via"),
        }
        # Optionale Split-/Stage-/Role-Metadata aus payload direkt in den Record übernehmen,
        # damit das Dashboard ohne Heuristiken arbeiten kann.
        for key in (
            "parent_purpose",
            "parent_second_leg_purpose",
            "stage_index",
            "stage_count",
            "split_index",
            "split_count",
            "cycle_role",
            "first_leg_cycle_role",
            "second_leg_cycle_role",
            "order_source",
            "split_source",
            "qty",
            "exec_qty",
            "side",
            "fill_price",
            "avg_fill_price",
            "refill_batch_id",
            "refill_trigger_reason",
            "recovery_reload_id",
        ):
            if key in payload:
                record[key] = payload.get(key)
        pnl_scope_normalized = str(record.get("pnl_scope") or "").strip().lower()
        if pnl_scope_normalized in {"refill", "recovery_reload"}:
            record["closed_pnl"] = 0.0
        exchange_order_id = str(record.get("exchange_order_id") or "").strip()
        purpose = str(record.get("purpose") or "").strip()
        closed_pnl = record.get("closed_pnl")
        pnl_source = str(record.get("pnl_source") or "")
        if not exchange_order_id or not purpose or closed_pnl is None:
            _log_warning_event(
                "confirmed_order_pnl_missing_required_fields",
                {
                    "exchange_order_id": record.get("exchange_order_id"),
                    "purpose": record.get("purpose"),
                    "closed_pnl": record.get("closed_pnl"),
                    "client_order_id": record.get("client_order_id"),
                    "trade_block_id": record.get("trade_block_id"),
                    "pnl_scope": record.get("pnl_scope"),
                },
            )
            return
        try:
            record["closed_pnl"] = float(closed_pnl)
        except (TypeError, ValueError):
            _log_warning_event(
                "confirmed_order_pnl_missing_required_fields",
                {
                    "exchange_order_id": exchange_order_id,
                    "purpose": purpose,
                    "closed_pnl": closed_pnl,
                    "reason": "closed_pnl_not_numeric",
                },
            )
            return
        strategy_state = runtime_state.strategy_state if runtime_state is not None else {}
        payload_trade_block_id = str(record.get("trade_block_id") or "").strip()
        trade_block_id, trade_block_id_source = resolve_trade_block_id_with_source(
            strategy_state,
            payload_trade_block_id=payload_trade_block_id or None,
        )
        if not trade_block_id:
            trade_block_id = "unknown"
            record["trade_block_id_source"] = "missing_fallback"
            _log_warning_event(
                "confirmed_order_pnl_trade_block_id_missing_wrote_anyway",
                {
                    "exchange_order_id": exchange_order_id,
                    "purpose": purpose,
                    "client_order_id": record.get("client_order_id"),
                    "pnl_scope": record.get("pnl_scope"),
                    "payload_trade_block_id": payload_trade_block_id or None,
                    "last_trade_block_id": strategy_state.get("last_trade_block_id"),
                },
            )
        else:
            record["trade_block_id_source"] = trade_block_id_source
        record["trade_block_id"] = trade_block_id
        record["dedupe_key"] = f"{exchange_order_id}:{purpose}"
        dedupe_key = record["dedupe_key"]
        owner_bot_name = str(default_bot_name or "").strip().lower()
        if owner_bot_name.startswith(("long_bot_", "short_bot_")):
            target_bot_name = owner_bot_name
            target_path = confirmed_order_pnl_history_path
            route_reason = "owner_bot"
            route_side = "short" if owner_bot_name.startswith("short_bot_") else "long"
        else:
            route_reason = "fallback_purpose_side"
            route_side = purpose_implies_bot_side(purpose)
            if route_side is None:
                raw_side = str(record.get("side") or "").strip().lower()
                if raw_side in {"long", "short"}:
                    route_side = raw_side
            if not route_side:
                purpose_upper = str(purpose or "").upper()
                if "SHORT" in purpose_upper:
                    route_side = "short"
                elif "LONG" in purpose_upper:
                    route_side = "long"
            target_bot_name, target_path = _resolve_confirmed_pnl_history_target(
                route_side=route_side or "long",
                default_bot=default_bot_name,
                base_path=confirmed_order_pnl_history_path,
            )
        skip_write, skip_reason, skip_context = should_skip_foreign_confirmed_pnl_write(
            payload=payload,
            default_bot_name=default_bot_name,
            target_bot_name=target_bot_name,
            target_path=target_path,
            purpose=purpose,
        )
        if skip_write:
            _log_warning_event(
                "confirmed_pnl_history_foreign_bot_row_skipped",
                {
                    **skip_context,
                    "reason": skip_reason,
                },
            )
            return
        record["bot_name"] = target_bot_name
        _log_event(
            "confirmed_pnl_history_route",
            {
                "purpose": record.get("purpose"),
                "side": record.get("side"),
                "source_bot_name": default_bot_name,
                "self_bot_name": default_bot_name,
                "target_bot": target_bot_name,
                "target_path": str(target_path),
                "trade_block_id": record.get("trade_block_id"),
                "exchange_order_id": record.get("exchange_order_id"),
                "route_reason": route_reason,
                "route_side": route_side,
            },
        )
        state = runtime_state.strategy_state if runtime_state is not None else None
        written_keys = set(str(value) for value in ((state or {}).get("processed_confirmed_order_keys") or []))
        is_provisional_source = pnl_source in {
            "provisional_runtime_calculated_pnl",
            "provisional_exec_pnl",
        }
        path = target_path
        try:
            # Für Upserts benötigen wir nicht nur die Existenz des Schlüssels,
            # sondern auch die bisherige pnl_source, um provisional vs. confirmed
            # korrekt zu priorisieren.
            existing_records: dict[str, dict[str, Any]] = {}
            if path.exists():
                lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
                for line in lines[-500:]:
                    if not line.strip():
                        continue
                    try:
                        existing_payload = json.loads(line)
                    except Exception:
                        continue
                    existing_key = str(existing_payload.get("dedupe_key") or "").strip()
                    if existing_key:
                        existing_records[existing_key] = existing_payload

            existing_payload = existing_records.get(dedupe_key)
            if existing_payload is not None:
                existing_source = str(existing_payload.get("pnl_source") or "")
                existing_is_provisional = existing_source in {
                    "provisional_runtime_calculated_pnl",
                    "provisional_exec_pnl",
                }
                # Priorisierung:
                # - Wenn bereits ein nicht-provisorischer Wert existiert und der neue nur provisional ist,
                #   behalten wir den bestehenden und schreiben NICHT erneut.
                # - Wenn bisher nur provisional existiert und jetzt ein bestätigter Wert kommt,
                #   erlauben wir ein Upsert per Append (Dashboard nimmt den letzten Eintrag).
                # - Bei gleicher "Qualität" (beide provisional oder beide confirmed) loggen wir ein Duplicate
                #   und schreiben nicht erneut.
                if (not existing_is_provisional and is_provisional_source) or (
                    existing_is_provisional == is_provisional_source
                ):
                    if state is not None:
                        written_keys.add(dedupe_key)
                        state["processed_confirmed_order_keys"] = sorted(written_keys)[-2000:]
                    _log_event(
                        "confirmed_order_pnl_skipped_duplicate",
                        {
                            "dedupe_key": dedupe_key,
                            "exchange_order_id": exchange_order_id,
                            "purpose": purpose,
                            "pnl_scope": record.get("pnl_scope"),
                            "duplicate_source": "history_file",
                            "existing_pnl_source": existing_source or None,
                            "new_pnl_source": pnl_source or None,
                        },
                    )
                    return
                # Upsert-Fall: existierender provisional-Eintrag wird durch confirmed/upgraded ersetzt.
                _log_event(
                    "confirmed_order_pnl_upgraded_from_provisional",
                    {
                        "dedupe_key": dedupe_key,
                        "exchange_order_id": exchange_order_id,
                        "purpose": purpose,
                        "old_pnl_source": existing_source or None,
                        "old_closed_pnl": existing_payload.get("closed_pnl"),
                        "new_pnl_source": pnl_source or None,
                        "new_closed_pnl": record.get("closed_pnl"),
                    },
                )

            path.parent.mkdir(parents=True, exist_ok=True)
            with path.open("a", encoding="utf-8") as fh:
                fh.write(json.dumps(_safe_audit_value(record), ensure_ascii=False) + "\n")
            if state is not None:
                written_keys.add(dedupe_key)
                state["processed_confirmed_order_keys"] = sorted(written_keys)[-2000:]
            _log_event(
                "confirmed_order_pnl_written",
                {
                    "dedupe_key": dedupe_key,
                    "exchange_order_id": exchange_order_id,
                    "client_order_id": record.get("client_order_id"),
                    "purpose": purpose,
                    "closed_pnl": record.get("closed_pnl"),
                    "trade_block_id": record.get("trade_block_id"),
                    "cycle_index": record.get("cycle_index"),
                    "pnl_scope": record.get("pnl_scope"),
                    "path": str(path),
                },
            )
        except Exception as exc:
            _log_warning_event(
                "confirmed_order_pnl_write_failed",
                {
                    "dedupe_key": dedupe_key,
                    "exchange_order_id": exchange_order_id,
                    "client_order_id": record.get("client_order_id"),
                    "purpose": purpose,
                    "pnl_scope": record.get("pnl_scope"),
                    "error": str(exc),
                    "path": str(path),
                },
            )

    def _append_dashboard_event_to_confirmed_history(
        self,
        payload: dict[str, Any],
    ) -> None:
        """
        Append a synthetic dashboard event record to the confirmed_order_pnl_history
        file without affecting trading logic or PnL calculations.
        """
        record = _safe_audit_value(dict(payload))
        path = confirmed_order_pnl_history_path
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            with path.open("a", encoding="utf-8") as fh:
                fh.write(json.dumps(record, ensure_ascii=False) + "\n")
        except Exception as exc:
            _log_warning_event(
                "dashboard_event_confirmed_history_write_failed",
                {
                    "path": str(path),
                    "payload": record,
                    "exception": str(exc),
                },
            )

    def _apply_confirmed_realized_pnl(
        self,
        runtime_state: RuntimeState,
        client_order_id: str | None,
        confirmed_pnl: float | None,
        side: str,
        exec_id: str | None = None,
        purpose: str | None = None,
        position_idx: int | None = None,
        cycle_role: str | None = None,
        short_tp_fallback: bool = False,
    ) -> None:
        if not client_order_id or confirmed_pnl is None:
            return
        if not exec_id and not client_order_id:
            return
        state = runtime_state.strategy_state
        processed_value = state.setdefault("processed_pnl_exec_ids", [])
        processed = set(processed_value)
        order = state.setdefault("processed_pnl_exec_ids_order", [])
        exec_key = exec_id or client_order_id
        if exec_key in processed:
            return
        applied = runtime_state.confirmed_pnl_applied
        if client_order_id in applied:
            return
        purpose_value = str(purpose or client_order_id or "")
        purpose_upper = purpose_value.upper()
        cycle_role_value = str(cycle_role or "").lower()
        is_relevant_cycle_repair_fill = (
            ("CYCLE_" in purpose_upper and "LONG_ADD" in purpose_upper)
            or ("CYCLE_" in purpose_upper and "SHORT_REDUCE" in purpose_upper)
            or ("TRAILING_SHORT_REDUCE" in purpose_upper)
            or (cycle_role_value in {"long_reduce", "short_reduce"})
            or bool(short_tp_fallback)
        )
        is_ignored_fill = any(
            token in purpose_upper
            for token in (
                "INITIAL_LONG_ENTRY",
                "INITIAL_SHORT_ENTRY",
                "LONG_TP_EXIT",
                "SHORT_SL_EXIT",
                "REFILL_LONG",
                "REFILL_SHORT",
            )
        )
        previous_pending = float(state.get("pending_cycle_loss_usdt") or 0.0)
        if is_relevant_cycle_repair_fill and not is_ignored_fill:
            if confirmed_pnl < 0:
                new_pending = previous_pending + abs(confirmed_pnl)
                update_reason = "loss_added"
            elif confirmed_pnl > 0:
                new_pending = max(previous_pending - confirmed_pnl, 0.0)
                update_reason = "profit_deducted"
            else:
                new_pending = previous_pending
                update_reason = "zero_pnl_no_change"
            state["pending_cycle_loss_usdt"] = new_pending
            if new_pending != previous_pending:
                state["exit_rebuild_allowed"] = True
                state["pending_loss_exit_old_signature"] = state.get("last_exit_signature")
                state["pending_loss_exit_rebuild_reason"] = update_reason
                state["last_exit_signature"] = None
                state["force_exit_rebuild"] = True
                self._set_final_exit_missing_block(
                    runtime_state, self.FINAL_EXIT_MISSING_FORCE_BLOCK_SEC
                )
                state["pending_loss_updated_in_fill"] = True
                _audit_calc(
                    "pending_cycle_loss_update_calc",
                    {
                        "before": previous_pending,
                        "added_loss": new_pending - previous_pending,
                        "after": new_pending,
                        "reason": update_reason,
                        "cycle_index": self._get_second_leg_pending_cycle(state),
                    },
                )
        else:
            update_reason = "ignored_non_cycle_fill"
        logger.info(
            "pending_cycle_loss_updated %s",
            {
                "purpose": purpose,
                "side": side,
                "position_idx": position_idx,
                "cycle_role": cycle_role,
                "exec_id": exec_id,
                "client_order_id": client_order_id,
                "confirmed_pnl": confirmed_pnl,
                "previous_pending_cycle_loss_usdt": previous_pending,
                "new_pending_cycle_loss_usdt": state.get("pending_cycle_loss_usdt"),
                "update_reason": update_reason,
            },
        )
        logger.info(
            "pending_cycle_loss_exit_rebuild_state",
            {
                "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
                "exit_rebuild_allowed": state.get("exit_rebuild_allowed", True),
                "force_exit_rebuild": bool(state.get("force_exit_rebuild")),
                "pending_loss_updated_in_fill": bool(state.get("pending_loss_updated_in_fill")),
                "last_exit_signature": state.get("last_exit_signature"),
                "update_reason": update_reason,
                "confirmed_pnl": confirmed_pnl,
                "purpose": purpose,
                "exec_id": exec_id,
                "client_order_id": client_order_id,
            },
        )
        had_temp = client_order_id in runtime_state.temporary_pnl_by_order
        temp_pnl = runtime_state.temporary_pnl_by_order.pop(client_order_id, 0.0)
        if not had_temp:
            logger.warning(
                "missing_temp_pnl",
                extra={
                    "client_order_id": client_order_id,
                    "side": side,
                    "confirmed_pnl": confirmed_pnl,
                },
            )
        state = runtime_state.strategy_state
        net_long = float(state.get("net_long_loss_balance") or 0.0)
        net_short = float(state.get("net_short_loss_balance") or 0.0)
        side_norm = (side or "").lower()
        if side_norm in {"long", "buy"}:
            if temp_pnl != 0.0:
                runtime_state.realized_long_pnl_total -= temp_pnl
            runtime_state.realized_long_pnl_total += confirmed_pnl
            if confirmed_pnl < 0:
                net_long += abs(confirmed_pnl)
            else:
                net_short = max(net_short - confirmed_pnl, 0.0)
        elif side_norm in {"short", "sell"}:
            if temp_pnl != 0.0:
                runtime_state.realized_short_pnl_total -= temp_pnl
            runtime_state.realized_short_pnl_total += confirmed_pnl
            if confirmed_pnl < 0:
                net_short += abs(confirmed_pnl)
            else:
                net_long = max(net_long - confirmed_pnl, 0.0)
        else:
            logger.warning(
                "invalid_side_for_pnl",
                extra={
                    "side": side,
                    "confirmed_pnl": confirmed_pnl,
                    "client_order_id": client_order_id,
                },
            )
            return
        applied.add(client_order_id)
        processed.add(exec_key)
        if isinstance(order, list):
            order.append(exec_key)
            if len(order) > 5000:
                old = order.pop(0)
                processed.discard(old)
        state["processed_pnl_exec_ids"] = list(processed)
        state["processed_pnl_exec_ids_order"] = order
        state["net_long_loss_balance"] = net_long
        state["net_short_loss_balance"] = net_short

    def _cleanup_order_pnl(self, runtime_state: RuntimeState, client_order_id: str | None) -> None:
        if not client_order_id:
            return
        runtime_state.temporary_pnl_by_order.pop(client_order_id, None)
        runtime_state.confirmed_pnl_applied.discard(client_order_id)

    @classmethod
    @staticmethod
    def _safe_float(value: Any, default: float | None) -> float | None:
        if value in (None, ""):
            return default
        try:
            return float(value)
        except (TypeError, ValueError):
            return default

    @staticmethod
    def _safe_int(value: Any, default: int | None = None) -> int | None:
        if value in (None, ""):
            return default
        try:
            return int(value)
        except (TypeError, ValueError):
            return default

    def _cycle_purpose(cls, side: str, cycle_index: int) -> str:
        if side.lower() == "long":
            return purpose_mapping.cycle_long_add(cycle_index)
        return purpose_mapping.cycle_short_reduce(cycle_index)

    @staticmethod
    def _cycle_build_blocking_statuses() -> set[str]:
        return {
            "INTENT_BUILT",
            "SUBMITTING",
            "SUBMITTED",
            "OPEN",
            "NEW",
            "UNTRIGGERED",
            "PARTIALLY_FILLED",
            "FILLED",
            "PROCESSED",
        }

    @staticmethod
    def _cycle_build_allowed_statuses() -> set[str]:
        return {
            "NONE",
            "CANCELLED",
            "CANCELED",
            "REJECTED",
            "EXPIRED",
            "DEACTIVATED",
        }

    @staticmethod
    def _cycle_finalized_statuses() -> set[str]:
        return {"FILLED", "PROCESSED"}

    def _cycle_status_finalized(self, status: Any) -> bool:
        return self._normalize_cycle_order_status(status) in self._cycle_finalized_statuses()

    @staticmethod
    def _normalize_cycle_order_status(status: Any) -> str:
        upper = str(status or "NONE").upper()
        if upper == "PARTIAL":
            return "PARTIALLY_FILLED"
        if upper == "TRIGGERED":
            return "SUBMITTED"
        return upper

    def _cycle_status_blocks_build(self, status: Any) -> bool:
        return self._normalize_cycle_order_status(status) in self._cycle_build_blocking_statuses()

    def _cycle_build_block_active(self, state: dict[str, Any]) -> bool:
        return bool(
            state.get("refill_pending")
            or state.get("refill_required")
            or state.get("refill_in_progress")
            or state.get("bot_state") == self.STATE_REFILL_PENDING
            or state.get("cycle_block_status") == "REFILL_REQUIRED"
        )

    def _maybe_trigger_time_distance_refill(
        self,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState,
        context: StrategyContext | None,
    ) -> bool:
        """
        Optionally trigger an early refill using the existing refill mode based on:

        - First leg of cycle 2 filled (short or long reduce depending on bot side)
        - Second-leg reduce order for cycle 2 still open
        - Trade age >= configured minimum minutes
        - Current price has reached at least the midpoint between avg price and the
          second-leg reduce order price (direction-aware).

        This is the "recovery mode" midpoint trigger and is intended to re-use the
        normal refill lifecycle while skipping the next regular cycle-refill once.
        """
        cfg_minutes = getattr(self.config, "time_distance_refill_trigger_minutes", 0)
        if cfg_minutes <= 0 or snapshot is None:
            return False

        state = runtime_state.strategy_state
        symbol = snapshot.symbol or self.config.symbol

        def _active_order_purposes() -> list[str]:
            purposes: list[str] = []
            for order in runtime_state.active_orders.values():
                if isinstance(order, dict):
                    purpose = order.get("purpose")
                else:
                    purpose = getattr(order, "purpose", None)
                if purpose:
                    purposes.append(str(purpose))
            for order in getattr(snapshot, "active_orders", []) or []:
                if isinstance(order, dict):
                    purpose = order.get("purpose")
                else:
                    purpose = getattr(order, "purpose", None)
                if purpose:
                    purposes.append(str(purpose))
            return self._dedupe_preserve_order(purposes)

        def _log_candidate_skipped(reason: str, extra: dict[str, Any] | None = None) -> None:
            payload: dict[str, Any] = {
                "symbol": symbol,
                "reason": reason,
            }
            if extra:
                payload.update(extra)
            _log_event("recovery_mode_candidate_skipped", payload)

        trade_started_at = state.get("trade_started_at")
        trade_block_id = state.get("trade_block_id")
        if not trade_started_at or not trade_block_id:
            return False
        try:
            started = datetime.fromisoformat(str(trade_started_at))
        except Exception:
            return False
        now = datetime.now(timezone.utc)
        age_minutes = (now - started).total_seconds() / 60.0

        # Basic guards: existing refill mode or active refill orders or explicit refill block.
        if self._is_refill_mode_active(state):
            _log_candidate_skipped(
                "refill_already_active",
                {
                    "trade_block_id": trade_block_id,
                    "age_minutes": age_minutes,
                    "min_age_minutes": float(cfg_minutes),
                    "refill_required": bool(state.get("refill_required")),
                    "refill_pending": bool(state.get("refill_pending")),
                    "refill_in_progress": bool(state.get("refill_in_progress")),
                    "cycle_block_status": state.get("cycle_block_status"),
                    "active_order_purposes": _active_order_purposes(),
                },
            )
            return
        if state.get("cycle_block_status") == "REFILL_REQUIRED":
            _log_candidate_skipped(
                "blocked_by_cycle_gate",
                {
                    "trade_block_id": trade_block_id,
                    "age_minutes": age_minutes,
                    "min_age_minutes": float(cfg_minutes),
                    "cycle_block_status": state.get("cycle_block_status"),
                    "active_order_purposes": _active_order_purposes(),
                },
            )
            return False

        active_refill_purposes = self._collect_active_refill_order_purposes(snapshot, runtime_state)
        if active_refill_purposes:
            _log_candidate_skipped(
                "refill_already_active",
                {
                    "trade_block_id": trade_block_id,
                    "age_minutes": age_minutes,
                    "min_age_minutes": float(cfg_minutes),
                    "active_refill_purposes": active_refill_purposes,
                    "active_order_purposes": _active_order_purposes(),
                },
            )
            return False

        if age_minutes < float(cfg_minutes):
            _log_candidate_skipped(
                "age_below_minimum",
                {
                    "trade_block_id": trade_block_id,
                    "age_minutes": age_minutes,
                    "min_age_minutes": float(cfg_minutes),
                },
            )
            return False

        # Determine side und Rollen. Für die Richtung verwenden wir die
        # First-Leg-Rolle, damit Short-Bot-Varianten ohne explizites
        # strategy_side-Flag korrekt gespiegelt werden.
        strategy_side = str(getattr(self.config, "strategy_side", "") or "").lower()
        is_short_side = self._get_first_leg_cycle_role() == "short_reduce"
        long_qty = float(getattr(snapshot, "long_qty", 0.0) or 0.0)
        short_qty = float(getattr(snapshot, "short_qty", 0.0) or 0.0)
        if is_short_side:
            if short_qty <= 0.0:
                _log_candidate_skipped(
                    "cycle_state_inconsistent",
                    {
                        "trade_block_id": trade_block_id,
                        "age_minutes": age_minutes,
                        "min_age_minutes": float(cfg_minutes),
                        "strategy_side": strategy_side,
                        "long_qty": long_qty,
                        "short_qty": short_qty,
                    },
                )
                return False
        else:
            if long_qty <= 0.0:
                _log_candidate_skipped(
                    "cycle_state_inconsistent",
                    {
                        "trade_block_id": trade_block_id,
                        "age_minutes": age_minutes,
                        "min_age_minutes": float(cfg_minutes),
                        "strategy_side": strategy_side,
                        "long_qty": long_qty,
                        "short_qty": short_qty,
                    },
                )
                return False

        current_price = getattr(snapshot, "current_price", None)
        if current_price is None:
            _log_candidate_skipped(
                "missing_current_price",
                {
                    "trade_block_id": trade_block_id,
                    "age_minutes": age_minutes,
                    "min_age_minutes": float(cfg_minutes),
                    "strategy_side": strategy_side,
                },
            )
            return False
        # Require the specific cycle-2 phase depending on side. If the dedicated
        # cycle_state entry is missing or inconsistent, we try to infer the
        # first-/second-leg status from more robust sources (processed purposes
        # and active/closed orders) instead of blindly returning.
        cycle_states_map = state.get("cycle_states") or {}
        entry = cycle_states_map.get("2") or cycle_states_map.get(2)
        processed_cycle_purposes = {
            str(item or "") for item in state.get("processed_cycle_purposes") or []
        }
        last_completed_purpose = str(state.get("last_completed_purpose") or "")

        # Raw flags from cycle_state, may be missing/False due to earlier bugs.
        short_reduce_done_flag = bool(entry.get("short_reduce_fill_confirmed")) if isinstance(entry, dict) else False
        long_reduce_done_flag = bool(entry.get("long_reduce_fill_confirmed")) if isinstance(entry, dict) else False
        short_reduce_status_norm = self._normalize_cycle_order_status(
            (entry or {}).get("short_reduce_status") if isinstance(entry, dict) else None
        )
        long_reduce_status_norm = self._normalize_cycle_order_status(
            (entry or {}).get("long_reduce_status") if isinstance(entry, dict) else None
        )

        # Expected first-/second-leg purposes für Cycle 2 ausschließlich über die
        # direction-neutralen Helper bestimmen, damit Long- und Short-Bot exakt
        # gespiegelt sind (z.B. CYCLE_2_LONG_REDUCE statt CYCLE_2_LONG_ADD auf
        # der Short-Seite).
        first_leg_purpose = self._get_first_leg_purpose(2)
        second_leg_purpose = self._get_second_leg_purpose(2)

        # Inference: first leg is considered filled if either the cycle_state flag
        # is set, the status is bereits finalisiert (FILLED/PROCESSED), or we see
        # die Purpose in processed_cycle_purposes / last_completed_purpose.
        inferred_first_leg_filled = False
        if is_short_side:
            short_status_finalized = self._cycle_status_finalized(short_reduce_status_norm)
            inferred_first_leg_filled = bool(
                short_reduce_done_flag
                or short_status_finalized
                or first_leg_purpose in processed_cycle_purposes
                or last_completed_purpose == first_leg_purpose
            )
            # Diagnose-Log: Short-First-Leg wurde nur über Status/Fallback als
            # gefüllt erkannt, obwohl das ursprüngliche Fill-Flag noch False war.
            if not short_reduce_done_flag and short_status_finalized and inferred_first_leg_filled:
                _log_event(
                    "short_recovery_first_leg_state_reconciled",
                    {
                        "symbol": symbol,
                        "trade_block_id": trade_block_id,
                        "cycle_index": 2,
                        "strategy_side": strategy_side,
                        "short_reduce_status": short_reduce_status_norm,
                        "short_reduce_fill_confirmed": short_reduce_done_flag,
                        "first_leg_purpose": first_leg_purpose,
                        "processed_cycle_purposes": list(processed_cycle_purposes),
                        "last_completed_purpose": last_completed_purpose,
                    },
                )
        else:
            long_status_finalized = self._cycle_status_finalized(long_reduce_status_norm)
            inferred_first_leg_filled = bool(
                long_reduce_done_flag
                or long_status_finalized
                or first_leg_purpose in processed_cycle_purposes
                or last_completed_purpose == first_leg_purpose
            )

        # Prevent multiple recovery-mode activations für dieselbe (Trade, Cycle)-Kombination.
        # Fachlich ist die aktuelle Time-Distance-Regel bewusst auf Cycle 2 beschränkt.
        resolved_cycle_index = 2
        active_cycle_index_state = int(state.get("active_cycle_index") or 0)
        used_cycle = int(state.get("recovery_midpoint_used_for_cycle_index") or 0)
        trigger_key = f"{trade_block_id}:{resolved_cycle_index}"
        previous_key = str(state.get("time_distance_refill_triggered_key") or "")

        # Diagnose-Log, welcher Cycle für den Time-Distance-Refill verwendet wird.
        def _is_same_second_leg_purpose(a: Any, b: Any) -> bool:
            """
            Lokaler Helper nur für den Recovery-Time-Distance-Pfad:
            - behandelt CYCLE_N_LONG_REDUCE als Alias zu CYCLE_N_LONG_ADD auf der Short-Seite,
              damit offene Second-Leg-Orders korrekt erkannt werden.
            """
            a_text = str(a or "")
            b_text = str(b or "")
            if a_text == b_text:
                return True
            if is_short_side:
                a_up = a_text.upper()
                b_up = b_text.upper()
                ma = re.fullmatch(r"CYCLE_(\d+)_LONG_REDUCE", a_up)
                mb = re.fullmatch(r"CYCLE_(\d+)_LONG_ADD", b_up)
                if ma and mb and ma.group(1) == mb.group(1):
                    return True
                # Symmetrisch auch LONG_ADD vs. LONG_REDUCE behandeln, falls second_leg_purpose gespiegelt ist.
                ma2 = re.fullmatch(r"CYCLE_(\d+)_LONG_ADD", a_up)
                mb2 = re.fullmatch(r"CYCLE_(\d+)_LONG_REDUCE", b_up)
                if ma2 and mb2 and ma2.group(1) == mb2.group(1):
                    return True
            return False

        _log_event(
            "fixed_cycle_time_distance_refill_cycle_resolved",
            {
                "symbol": symbol,
                "trade_block_id": trade_block_id,
                "resolved_cycle_index": resolved_cycle_index,
                "source": "cycle_2_only",
                "active_cycle_index_state": active_cycle_index_state,
                "current_effective_cycle": int(state.get("current_effective_cycle") or 0),
                "current_long_cycle_index": int(state.get("current_long_cycle_index") or 0),
                "current_short_cycle_index": int(state.get("current_short_cycle_index") or 0),
                "pending_long_cycle_index": int(state.get("pending_long_cycle_index") or 0),
                "pending_short_cycle_index": int(state.get("pending_short_cycle_index") or 0),
                "cycle_pair_count": int(state.get("cycle_pair_count") or 0),
                "cycle_completed_count": int(state.get("cycle_completed_count") or 0),
                "open_second_leg_purposes": [
                    p
                    for p in _active_order_purposes()
                    if _is_same_second_leg_purpose(p, second_leg_purpose)
                ],
                "processed_cycle_purposes": list(processed_cycle_purposes),
            },
        )

        active_cycle_index = resolved_cycle_index
        if used_cycle == active_cycle_index or previous_key == trigger_key:
            _log_event(
                "fixed_cycle_time_distance_refill_already_triggered_skipped",
                {
                    "symbol": symbol,
                    "trade_block_id": trade_block_id,
                    "cycle_index": active_cycle_index,
                    "age_minutes": age_minutes,
                    "min_age_minutes": float(cfg_minutes),
                    "first_leg_purpose": first_leg_purpose,
                    "second_leg_purpose": second_leg_purpose,
                },
                runtime_state=runtime_state,
            )
            return False

        # Find the target second-leg order (pending reduce); this also serves as
        # our inference source for "second_leg_open".
        second_leg_order_id = None
        second_leg_price_source: str | None = None
        second_leg_price_raw: Any = None

        def _find_target_order_price() -> float | None:
            nonlocal second_leg_order_id, second_leg_price_source, second_leg_price_raw
            prices: list[float] = []

            def _matches_second_leg(order: Any) -> bool:
                if isinstance(order, dict):
                    purpose = order.get("purpose")
                    meta = order.get("metadata") or {}
                else:
                    purpose = getattr(order, "purpose", None)
                    meta = getattr(order, "metadata", None) or {}
                parent_second_leg = meta.get("parent_second_leg_purpose")
                replace_open = meta.get("replace_open_purpose")
                purpose_text = str(purpose or "")
                # Nutze den lokalen Helper, um CYCLE_N_LONG_REDUCE vs. CYCLE_N_LONG_ADD
                # im Recovery-Second-Leg-Matching zu harmonisieren.
                return bool(
                    _is_same_second_leg_purpose(purpose_text, second_leg_purpose)
                    or _is_same_second_leg_purpose(parent_second_leg, second_leg_purpose)
                    or _is_same_second_leg_purpose(replace_open, second_leg_purpose)
                )

            def _extract_price(order: Any, meta: dict[str, Any]) -> float | None:
                nonlocal second_leg_price_source, second_leg_price_raw
                """
                Extract the most reliable trigger price for the second-leg reduce.

                Priority (from most to least specific):
                1) metadata.final_second_leg_trigger_price
                2) metadata.stage_trigger_price
                3) metadata.trigger_price
                4) order.trigger_price
                5) order.stop_price
                6) order.price
                """
                candidates: list[tuple[str, Any]] = []
                # Metadata-based trigger prices first.
                candidates.append(("meta_final_second_leg_trigger_price", meta.get("final_second_leg_trigger_price")))
                candidates.append(("meta_stage_trigger_price", meta.get("stage_trigger_price")))
                candidates.append(("meta_trigger_price", meta.get("trigger_price")))
                # Then order-level fields.
                if isinstance(order, dict):
                    candidates.append(("order_trigger_price", order.get("trigger_price")))
                    candidates.append(("order_stop_price", order.get("stop_price")))
                    candidates.append(("order_price", order.get("price")))
                else:
                    candidates.append(("order_trigger_price", getattr(order, "trigger_price", None)))
                    candidates.append(("order_stop_price", getattr(order, "stop_price", None)))
                    candidates.append(("order_price", getattr(order, "price", None)))

                for source, value in candidates:
                    if value is None:
                        continue
                    try:
                        price_f = float(value)
                    except (TypeError, ValueError):
                        continue
                    second_leg_price_source = source
                    second_leg_price_raw = value
                    return price_f
                return None

            for order in runtime_state.active_orders.values():
                if not _matches_second_leg(order):
                    continue
                if isinstance(order, dict):
                    meta = order.get("metadata") or {}
                else:
                    meta = getattr(order, "metadata", None) or {}
                price = _extract_price(order, meta)
                if price is None:
                    continue
                try:
                    prices.append(float(price))
                    if isinstance(order, dict):
                        second_leg_order_id = (
                            order.get("exchange_order_id")
                            or order.get("order_id")
                            or order.get("client_order_id")
                            or second_leg_order_id
                        )
                    else:
                        second_leg_order_id = getattr(order, "exchange_order_id", None) or getattr(
                            order, "order_id", None
                        )
                except (TypeError, ValueError):
                    continue
            for order in getattr(snapshot, "active_orders", []) or []:
                if not _matches_second_leg(order):
                    continue
                if isinstance(order, dict):
                    meta = order.get("metadata") or {}
                else:
                    meta = getattr(order, "metadata", None) or {}
                price = _extract_price(order, meta)
                if price is None:
                    continue
                try:
                    prices.append(float(price))
                    if second_leg_order_id is None:
                        if isinstance(order, dict):
                            second_leg_order_id = (
                                order.get("exchange_order_id")
                                or order.get("order_id")
                                or order.get("client_order_id")
                                or second_leg_order_id
                            )
                        else:
                            second_leg_order_id = getattr(order, "exchange_order_id", None) or getattr(
                                order, "order_id", None
                            )
                except (TypeError, ValueError):
                    continue
            return prices[0] if prices else None

        target_price = _find_target_order_price()
        inferred_second_leg_open = target_price is not None

        # Diagnose-Log für die Zuordnung von First-/Second-Leg im
        # Recovery-Reload-Gate, um Long- und Short-Bot-Verhalten direkt
        # vergleichen zu können.
        _log_event(
            "recovery_reload_gate_leg_mapping",
            {
                "symbol": symbol,
                "trade_block_id": trade_block_id,
                "cycle_index": resolved_cycle_index,
                "strategy_side": strategy_side,
                "first_leg_purpose": first_leg_purpose,
                "second_leg_purpose": second_leg_purpose,
                "first_leg_status_field": self._get_first_leg_status_field(),
                "second_leg_status_field": self._get_second_leg_status_field(),
                "first_leg_cycle_role": self._get_first_leg_cycle_role(),
                "second_leg_cycle_role": self._get_second_leg_cycle_role(),
                "inferred_first_leg_filled": inferred_first_leg_filled,
                "inferred_second_leg_open": inferred_second_leg_open,
            },
        )

        cycle_state_entry = entry if isinstance(entry, dict) else {}
        # Log a detailed inconsistency snapshot if the raw cycle_state does not
        # agree with the inferred reality.
        if not isinstance(entry, dict) or not inferred_first_leg_filled or not inferred_second_leg_open:
            _log_candidate_skipped(
                "cycle_state_inconsistent",
                {
                    "trade_block_id": trade_block_id,
                    "age_minutes": age_minutes,
                    "min_age_minutes": float(cfg_minutes),
                    "strategy_side": strategy_side,
                    "cycle_index": 2,
                    "cycle_state_entry": cycle_state_entry,
                    "processed_cycle_purposes": list(processed_cycle_purposes),
                    "active_order_purposes": _active_order_purposes(),
                    "inferred_first_leg_filled": inferred_first_leg_filled,
                    "inferred_second_leg_open": inferred_second_leg_open,
                    "first_leg_purpose": first_leg_purpose,
                    "second_leg_purpose": second_leg_purpose,
                    "short_reduce_done_flag": short_reduce_done_flag,
                    "long_reduce_done_flag": long_reduce_done_flag,
                },
            )

        # If we cannot reconstruct a valid first/second-leg combination, abort.
        if not inferred_first_leg_filled:
            # Spezieller Diagnose-Log für den Short-Bot: First-Leg-Order ist noch
            # nicht final gefüllt (SUBMITTED / PARTIALLY_FILLED).
            if is_short_side:
                _log_event(
                    "short_recovery_first_leg_blocked_partial_fill",
                    {
                        "symbol": symbol,
                        "trade_block_id": trade_block_id,
                        "cycle_index": 2,
                        "age_minutes": age_minutes,
                        "min_age_minutes": float(cfg_minutes),
                        "first_leg_purpose": first_leg_purpose,
                        "short_reduce_status": short_reduce_status_norm,
                        "short_reduce_fill_confirmed": short_reduce_done_flag,
                        "processed_cycle_purposes": list(processed_cycle_purposes),
                        "last_completed_purpose": last_completed_purpose,
                    },
                )
            _log_candidate_skipped(
                "first_leg_not_filled",
                {
                    "trade_block_id": trade_block_id,
                    "age_minutes": age_minutes,
                    "min_age_minutes": float(cfg_minutes),
                    "cycle_index": 2,
                    "first_leg_purpose": first_leg_purpose,
                    "first_leg_status": (cycle_state_entry or {}).get(
                        "short_reduce_status" if is_short_side else "long_reduce_status"
                    ),
                },
            )
            return False
        if not inferred_second_leg_open:
            _log_candidate_skipped(
                "second_leg_not_open",
                {
                    "trade_block_id": trade_block_id,
                    "age_minutes": age_minutes,
                    "min_age_minutes": float(cfg_minutes),
                    "cycle_index": 2,
                    "second_leg_purpose": second_leg_purpose,
                    "second_leg_status": (cycle_state_entry or {}).get(
                        "long_reduce_status" if is_short_side else "short_reduce_status"
                    ),
                },
            )
            return False

        # Determine avg price based on second-leg direction (long/short reduce).
        second_leg_is_long = "LONG" in str(second_leg_purpose or "").upper()
        avg_price = getattr(snapshot, "long_avg" if second_leg_is_long else "short_avg", None)
        avg_source = "long_avg" if second_leg_is_long else "short_avg"
        qty_source = "long_qty" if second_leg_is_long else "short_qty"
        if avg_price is None:
            _log_candidate_skipped(
                "missing_avg_price",
                {
                    "trade_block_id": trade_block_id,
                    "age_minutes": age_minutes,
                    "min_age_minutes": float(cfg_minutes),
                    "strategy_side": strategy_side,
                },
            )
            return False

        try:
            target_price_f = float(target_price)
        except (TypeError, ValueError):
            _log_candidate_skipped(
                "invalid_second_leg_price",
                {
                    "trade_block_id": trade_block_id,
                    "age_minutes": age_minutes,
                    "min_age_minutes": float(cfg_minutes),
                    "strategy_side": strategy_side,
                    "second_leg_purpose": second_leg_purpose,
                    "second_leg_price_raw": target_price,
                },
            )
            return False

        try:
            avg_price_f = float(avg_price)
            current_price_f = float(current_price)
        except (TypeError, ValueError):
            _log_candidate_skipped(
                "missing_current_price",
                {
                    "trade_block_id": trade_block_id,
                    "age_minutes": age_minutes,
                    "min_age_minutes": float(cfg_minutes),
                    "strategy_side": strategy_side,
                },
            )
            return False

        midpoint_price = (avg_price_f + target_price_f) / 2.0

        # (alter, einfacher Helper für second-leg price wurde entfernt – die robuste
        # Variante oberhalb ist nun die einzige Quelle für target_price.)
        if target_price_f >= avg_price_f:
            hit = current_price_f >= midpoint_price
            if target_price_f == avg_price_f:
                price_progress_pct = 1.0
            else:
                price_progress_pct = max(
                    0.0, min(1.0, (current_price_f - avg_price_f) / (target_price_f - avg_price_f))
                )
        else:
            hit = current_price_f <= midpoint_price
            if target_price_f == avg_price_f:
                price_progress_pct = 1.0
            else:
                price_progress_pct = max(
                    0.0, min(1.0, (avg_price_f - current_price_f) / (avg_price_f - target_price_f))
                )

        # Normaler Midpoint-Trigger (Produktiv-Standard).
        trigger_price_used = midpoint_price
        trigger_mode = "normal"

        candidate_payload: dict[str, Any] = {
            "symbol": symbol,
            "cycle_index": active_cycle_index,
            "trade_block_id": trade_block_id,
            "first_leg_purpose": first_leg_purpose,
            "first_leg_status": cycle_state_entry.get("short_reduce_status")
            if is_short_side
            else cycle_state_entry.get("long_reduce_status"),
            "first_leg_filled_at": None,
            "second_leg_purpose": second_leg_purpose,
            "second_leg_status": cycle_state_entry.get("long_reduce_status")
            if is_short_side
            else cycle_state_entry.get("short_reduce_status"),
            "second_leg_order_id": second_leg_order_id,
            "second_leg_trigger_price": target_price_f,
            "second_leg_price_source": second_leg_price_source,
            "second_leg_price_raw": second_leg_price_raw,
            "avg_price": avg_price_f,
            "current_price": current_price_f,
            "midpoint_price": midpoint_price,
            "price_progress_pct": price_progress_pct,
            "strategy_side": strategy_side,
            "avg_source": avg_source,
            "qty_source": qty_source,
            "short_reduce_done_flag": short_reduce_done_flag,
            "long_reduce_done_flag": long_reduce_done_flag,
            "inferred_first_leg_filled": inferred_first_leg_filled,
            "inferred_second_leg_open": inferred_second_leg_open,
            "first_leg_filled_detected": inferred_first_leg_filled,
            "second_leg_open_detected": inferred_second_leg_open,
            "processed_cycle_purposes": list(processed_cycle_purposes),
            "last_completed_purpose": last_completed_purpose,
            "age_minutes": age_minutes,
            "min_age_minutes": float(cfg_minutes),
            "refill_required": bool(state.get("refill_required")),
            "refill_pending": bool(state.get("refill_pending")),
            "refill_in_progress": bool(state.get("refill_in_progress")),
            "recovery_mode_already_used": used_cycle == active_cycle_index,
            "next_cycle_refill_skip_armed": bool(state.get("skip_next_cycle_refill_after_time_distance")),
            "active_order_purposes": _active_order_purposes(),
        }
        _log_event("recovery_mode_trigger_normal_calculated", candidate_payload)

        # Optionaler Test-Override für den Recovery-/Time-Distance-Trigger.
        override_enabled = bool(
            getattr(self.config, "recovery_mode_trigger_override_enabled", False)
        )
        override_pct = getattr(self.config, "recovery_mode_trigger_override_pct", None)
        override_ticks = getattr(self.config, "recovery_mode_trigger_override_ticks", None)
        if override_enabled:
            _log_event(
                "recovery_mode_trigger_override_active",
                {
                    "symbol": symbol,
                    "trade_block_id": trade_block_id,
                    "override_enabled": override_enabled,
                    "override_pct": float(override_pct) if override_pct is not None else None,
                    "override_ticks": int(override_ticks) if override_ticks is not None else None,
                },
            )

            # Bestimme Richtung: target > avg => Aufwärtsbewegung, sonst Abwärtsbewegung.
            direction_up = target_price_f >= avg_price_f

            # Ticks haben Vorrang vor Prozent.
            if override_ticks is not None and int(override_ticks) > 0:
                ticks_int = int(override_ticks)
                # Versuche, eine Tick-Size aus Instrument-Regeln oder Config zu verwenden.
                symbol_rules, rules, _ = self._resolve_instrument_rules(runtime_state)
                tick_decimal = (
                    rules["tick_size"]
                    if rules and rules.get("tick_size", Decimal("0")) > 0
                    else Decimal(str(self.config.price_tick_size or 0.0))
                )
                try:
                    tick_size = float(tick_decimal)
                except Exception:
                    tick_size = float(self.config.price_tick_size or 0.0)
                if tick_size > 0:
                    delta = tick_size * float(ticks_int)
                    raw_trigger = avg_price_f + (delta if direction_up else -delta)
                    # Clamp nicht weiter als Target.
                    if direction_up:
                        override_trigger_price = min(raw_trigger, target_price_f)
                        override_hit = current_price_f >= override_trigger_price
                    else:
                        override_trigger_price = max(raw_trigger, target_price_f)
                        override_hit = current_price_f <= override_trigger_price
                    trigger_price_used = override_trigger_price
                    hit = override_hit
                    trigger_mode = "ticks_override"
                    _log_event(
                        "recovery_mode_trigger_override_ticks_applied",
                        {
                            "symbol": symbol,
                            "trade_block_id": trade_block_id,
                            "base_price": avg_price_f,
                            "target_price": target_price_f,
                            "tick_size": tick_size,
                            "override_ticks": ticks_int,
                            "override_trigger_price": override_trigger_price,
                            "current_price": current_price_f,
                            "hit": override_hit,
                        },
                    )
                else:
                    _log_event(
                        "recovery_mode_trigger_override_ticks_applied",
                        {
                            "symbol": symbol,
                            "trade_block_id": trade_block_id,
                            "base_price": avg_price_f,
                            "target_price": target_price_f,
                            "tick_size": tick_size,
                            "override_ticks": ticks_int,
                            "override_trigger_price": None,
                            "current_price": current_price_f,
                            "hit": False,
                            "reason": "invalid_tick_size",
                        },
                    )
            elif override_pct is not None and float(override_pct) > 0.0:
                pct = float(override_pct)
                move = avg_price_f * (pct / 100.0)
                raw_trigger = avg_price_f + (move if direction_up else -move)
                # Clamp nicht weiter als Target.
                if direction_up:
                    override_trigger_price = min(raw_trigger, target_price_f)
                    override_hit = current_price_f >= override_trigger_price
                else:
                    override_trigger_price = max(raw_trigger, target_price_f)
                    override_hit = current_price_f <= override_trigger_price
                trigger_price_used = override_trigger_price
                hit = override_hit
                trigger_mode = "pct_override"
                _log_event(
                    "recovery_mode_trigger_override_pct_applied",
                    {
                        "symbol": symbol,
                        "trade_block_id": trade_block_id,
                        "base_price": avg_price_f,
                        "target_price": target_price_f,
                        "override_pct": pct,
                        "override_trigger_price": override_trigger_price,
                        "current_price": current_price_f,
                        "hit": override_hit,
                    },
                )

        _log_event("fixed_cycle_time_distance_refill_candidate_checked", candidate_payload)

        if not hit:
            _log_candidate_skipped(
                "midpoint_not_reached",
                {
                    **candidate_payload,
                    "reason": "midpoint_not_reached",
                },
            )
            return False

        _log_event(
            "recovery_mode_entered",
            {
                **candidate_payload,
                "strategy_side": strategy_side,
                "trigger_mode": trigger_mode,
                "trigger_price_used": trigger_price_used,
            },
        )

        _log_event(
            "fixed_cycle_time_distance_refill_triggered",
            {
                "symbol": symbol,
                "trade_block_id": trade_block_id,
                "cycle_index": active_cycle_index,
                "strategy_side": strategy_side,
                "trade_age_minutes": age_minutes,
                "avg_price": avg_price_f,
                "target_cycle_order_price": target_price_f,
                "trigger_price": trigger_price_used,
                "current_price": current_price_f,
                "time_distance_refill_trigger_minutes": cfg_minutes,
            },
        )
        _log_event(
            "recovery_mode_trigger_condition_met",
            {
                "symbol": symbol,
                "trade_block_id": trade_block_id,
                "cycle_index": active_cycle_index,
                "strategy_side": strategy_side,
                "trigger_mode": trigger_mode,
                "trigger_price": trigger_price_used,
                "current_price": current_price_f,
            },
        )

        # Root-Fix: statt den normalen Cycle-Refill-Modus zu aktivieren,
        # setzen wir einen expliziten Recovery-Reload-State, der anschließend
        # den bestehenden Recovery-/Wallet-Transfer-Flow verwendet.
        cycle_state = self._ensure_cycle_state(runtime_state)
        recovery_fields: dict[str, Any] = {
            "recovery_required": True,
            "recovery_activation_timing": cycle_state.get("recovery_activation_timing")
            or state.get("recovery_activation_timing")
            or "after_first_leg_reduce_fill",
            "recovery_activation_reason": "time_distance_refill",
            "recovery_reference_price": trigger_price_used,
            "recovery_reference_cycle_index": active_cycle_index,
        }
        self._set_recovery_required_state(runtime_state, cycle_state, recovery_fields=recovery_fields)

        # Spezieller Recovery-Reload-State für Diagnose und Idempotenz.
        reload_id = f"{trade_block_id}:recovery_reload:{active_cycle_index}"
        state["recovery_reload_required"] = True
        state["recovery_reload_cycle_index"] = active_cycle_index
        state["recovery_reload_id"] = reload_id

        self._set_recovery_lifecycle_state(
            state,
            "TRIGGERED",
            event="time_distance_refill_triggered",
            extra={"cycle_index": active_cycle_index},
        )

        # Zusätzlicher Diagnose-Log speziell für den Short-Bot:
        # First-Leg wurde nun als Basis für den Recovery-Reload bestätigt.
        if is_short_side:
            _log_event(
                "short_recovery_first_leg_confirmed_for_reload",
                {
                    "symbol": symbol,
                    "trade_block_id": trade_block_id,
                    "cycle_index": active_cycle_index,
                    "recovery_reload_id": reload_id,
                    "short_reduce_status": short_reduce_status_norm,
                    "short_reduce_fill_confirmed": short_reduce_done_flag,
                    "first_leg_purpose": first_leg_purpose,
                },
            )

        _log_event(
            "fixed_cycle_recovery_reload_required",
            {
                **candidate_payload,
                "recovery_reload_id": reload_id,
                "recovery_reload_cycle_index": active_cycle_index,
                "recovery_activation_reason": "time_distance_refill",
            },
        )
        # Wichtig: Kein Eintritt in den normalen REFILL-Modus und keine
        # REFILL_LONG/REFILL_SHORT-Orders. Der weitere Ablauf erfolgt über
        # den bestehenden Recovery-Builder (_build_recovery_refill_intents),
        # der zunächst den Wallet-Transfer sicherstellt und danach neue
        # Hedge-Entry-Orders nach Config baut.
        state["recovery_midpoint_used_for_cycle_index"] = active_cycle_index
        state["time_distance_refill_triggered_key"] = trigger_key
        return True

    def _cycle_state_file_path(self) -> Path:
        return cycle_state_file_path_override or (Path(__file__).resolve().parent / "state.json")

    def _default_cycle_state(self) -> dict:
        return {
            "trade_active": False,
            "symbol": self.config.symbol,
            "entry_price": 0.0,
            "last_cycle_reference_price": 0.0,
            "last_confirmed_short_fill_price": 0.0,
            "last_confirmed_short_fill_cycle_index": 0,
            "last_confirmed_short_fill_purpose": None,
            "long_cycle_index": 0,
            "short_cycle_index": 0,
            "long_add_pending": False,
            "long_fills": {},
            "short_fills": {},
            "processed_fill_ids": [],
            "cycle_completed_count": 0,
            "cycle_waiting_for_short_tp": False,
            "pending_long_cycle_index": 0,
            "short_tp_pending_cycle": 0,
            "pending_short_cycle_index": 0,
            "current_effective_cycle": 0,
            "cycle_states": {},
            "processed_cycle_purposes": [],
            "recovery_required": False,
            "recovery_activation_timing": None,
            "recovery_activation_reason": None,
            "recovery_reference_price": 0.0,
            "recovery_reference_cycle_index": 0,
            "recovery_long_reduce_distance_pct": 0.0,
            "recovery_required_long_reduce_price": 0.0,
            "recovery_projected_short_reduce_loss_usdt": 0.0,
            "recovery_projected_long_reduce_price": 0.0,
            "recovery_confirmed_short_reduce_loss_usdt": 0.0,
            "recovery_completed_cycle_index": 0,
        }

    def _load_cycle_state(self) -> dict:
        path = self._cycle_state_file_path()
        if not path.exists():
            return self._default_cycle_state()
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (ValueError, OSError):
            return self._default_cycle_state()
        state = self._default_cycle_state()
        state.update({k: v for k, v in payload.items() if k in state or k in {"entry_price", "trade_active", "symbol"}})
        state["long_fills"] = dict(payload.get("long_fills") or {})
        state["short_fills"] = dict(payload.get("short_fills") or {})
        state["cycle_states"] = dict(payload.get("cycle_states") or {})
        state["processed_cycle_purposes"] = list(payload.get("processed_cycle_purposes") or [])
        return state

    def _write_cycle_state(self, cycle_state: dict) -> None:
        if not self.config.restart:
            return
        path = self._cycle_state_file_path()
        tmp_path = path.with_suffix(path.suffix + ".tmp")
        tmp_path.write_text(json.dumps(cycle_state), encoding="utf-8")
        tmp_path.replace(path)

    def _ensure_cycle_state(self, runtime_state: RuntimeState) -> dict:
        state = runtime_state.strategy_state
        cycle_state = state.get("cycle_state")
        if not cycle_state:
            cycle_state = self._load_cycle_state() if self.config.restart else self._default_cycle_state()
        if cycle_state.get("symbol") != self.config.symbol:
            cycle_state = self._default_cycle_state()
            if self.config.restart:
                self._write_cycle_state(cycle_state)
        state["cycle_state"] = cycle_state
        state.setdefault("current_long_cycle_index", int(cycle_state.get("long_cycle_index") or 0))
        state.setdefault("current_short_cycle_index", int(cycle_state.get("short_cycle_index") or 0))
        waiting_field = self._second_leg_waiting_flag_field()
        pending_field = self._second_leg_pending_cycle_field()
        if waiting_field in state:
            state[waiting_field] = bool(state.get(waiting_field))
        else:
            state[waiting_field] = bool(cycle_state.get(waiting_field))
        if pending_field in state:
            state[pending_field] = int(state.get(pending_field) or 0)
        else:
            state[pending_field] = int(cycle_state.get(pending_field) or 0)
        state["pending_long_cycle_index"] = max(
            int(state.get("pending_long_cycle_index") or 0),
            int(cycle_state.get("pending_long_cycle_index") or 0),
        )
        state.setdefault("long_add_pending", bool(cycle_state.get("long_add_pending")))
        if "cycle_states" in state:
            state["cycle_states"] = dict(state.get("cycle_states") or {})
        else:
            state["cycle_states"] = dict(cycle_state.get("cycle_states") or {})
        if "processed_cycle_purposes" in state:
            state["processed_cycle_purposes"] = list(state.get("processed_cycle_purposes") or [])
        else:
            state["processed_cycle_purposes"] = list(
                cycle_state.get("processed_cycle_purposes") or []
            )
        state.setdefault("exit_rebuild_allowed", True)
        state.setdefault("long_add_rebuild_allowed", True)
        return cycle_state

    @staticmethod
    def _default_cycle_sequence_entry() -> dict[str, Any]:
        return {
            "long_add_status": "NONE",
            "short_tp_status": "NONE",
            "short_reduce_status": "NONE",
            "long_reduce_status": "NONE",
            "long_add_qty": 0.0,
            "long_add_trigger_price": 0.0,
            "long_add_reserved_at": 0,
            "long_add_purpose": None,
            "short_tp_qty": 0.0,
            "short_tp_trigger_price": 0.0,
            "short_tp_reserved_at": 0,
            "short_tp_purpose": None,
            "long_add_confirmed_pnl": None,
            "long_reduce_closed_pnl": None,
            "long_reduce_fill_price": 0.0,
            "long_reduce_fill_confirmed": False,
            "long_add_loss_usdt": 0.0,
            "short_followup_pnl_source": None,
            "short_reduce_fill_price": 0.0,
            "short_reduce_fill_confirmed": False,
            "complete": False,
        }

    def _ensure_cycle_sequence_state(self, runtime_state: RuntimeState) -> dict[str, dict[str, Any]]:
        state = runtime_state.strategy_state
        cycle_states = state.get("cycle_states")
        if not isinstance(cycle_states, dict):
            cycle_states = {}
        normalized: dict[str, dict[str, Any]] = {}
        for key, value in cycle_states.items():
            if not isinstance(value, dict):
                continue
            entry = self._default_cycle_sequence_entry()
            entry.update(
                {
                    "long_add_status": str(value.get("long_add_status") or "NONE").upper(),
                    "short_tp_status": str(value.get("short_tp_status") or "NONE").upper(),
                    "short_reduce_status": str(value.get("short_reduce_status") or "NONE").upper(),
                    "long_reduce_status": str(value.get("long_reduce_status") or "NONE").upper(),
                    "long_add_qty": float(value.get("long_add_qty") or 0.0),
                    "long_add_trigger_price": float(value.get("long_add_trigger_price") or 0.0),
                    "long_add_reserved_at": int(value.get("long_add_reserved_at") or 0),
                    "long_add_purpose": value.get("long_add_purpose"),
                    "short_tp_qty": float(value.get("short_tp_qty") or 0.0),
                    "short_tp_trigger_price": float(value.get("short_tp_trigger_price") or 0.0),
                    "short_tp_reserved_at": int(value.get("short_tp_reserved_at") or 0),
                    "short_tp_purpose": value.get("short_tp_purpose"),
                    "long_add_confirmed_pnl": value.get("long_add_confirmed_pnl"),
                    "long_reduce_closed_pnl": value.get("long_reduce_closed_pnl"),
                    "long_reduce_fill_price": float(value.get("long_reduce_fill_price") or 0.0),
                    "long_reduce_fill_confirmed": bool(value.get("long_reduce_fill_confirmed")),
                    "long_add_loss_usdt": float(value.get("long_add_loss_usdt") or 0.0),
                    "short_followup_pnl_source": value.get("short_followup_pnl_source"),
                    "short_reduce_fill_price": float(value.get("short_reduce_fill_price") or 0.0),
                    "short_reduce_fill_confirmed": bool(value.get("short_reduce_fill_confirmed")),
                    "complete": bool(value.get("complete")),
                }
            )
            normalized[str(key)] = entry
        state["cycle_states"] = normalized
        processed = state.get("processed_cycle_purposes")
        if not isinstance(processed, list):
            processed = list(processed or [])
        state["processed_cycle_purposes"] = sorted(
            {
                self._normalize_cycle_purpose(item)
                for item in processed
                if str(item or "")
            }
        )
        if "active_cycle_index" not in state or "cycle_step" not in state:
            init_payload = initialize_cycle_sequence_state(state, self._sequence_config)
            _log_event(
                "fixed_cycle_sequence_state_initialized",
                {
                    "symbol": self.config.symbol,
                    "category": self.config.category,
                    **init_payload,
                },
            )
        elif "next_required_purpose" not in state:
            next_required = derive_next_required_purpose(
                self._sequence_config,
                int(state.get("active_cycle_index") or 1),
                state.get("cycle_step"),
            )
            state["next_required_purpose"] = next_required
        recovered = self._recover_cycle_sequence_state(runtime_state, state)
        if recovered:
            self._persist_cycle_sequence_state(runtime_state)
        cycle_state = state.get("cycle_state")
        if isinstance(cycle_state, dict):
            cycle_state["cycle_states"] = dict(normalized)
            cycle_state["processed_cycle_purposes"] = list(state["processed_cycle_purposes"])
        return normalized

    def _reset_after_full_exit_for_next_trade(
        self,
        runtime_state: RuntimeState,
        snapshot: HedgeSnapshot,
        *,
        reason: str = "full_exit",
    ) -> None:
        state = runtime_state.strategy_state
        if float(snapshot.long_qty or 0.0) != 0.0 or float(snapshot.short_qty or 0.0) != 0.0:
            return
        _log_event(
            "fixed_cycle_post_exit_reset_started",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "category": self.config.category,
                "reason": reason,
            },
        )
        # canceling already done; just clean state
        state["initial_entry_submitted"] = False
        state["initial_entry_confirmed"] = False
        state["initial_structure_built"] = False
        state["cycle_completed_count"] = 0
        state["cycle_pair_count"] = 0
        state["current_effective_cycle"] = 0
        state["current_long_cycle_index"] = 0
        state["current_short_cycle_index"] = 0
        state["pending_cycle_loss_usdt"] = 0.0
        state["processed_cycle_purposes"] = []
        state["completed_cycle_purposes"] = []
        state["cycle_states"] = {}
        state["sequence_recovery_blocked"] = False
        state["cycle_completed_count"] = 0
        state["cycle_pair_count"] = 0
        state["current_effective_cycle"] = 0
        state["current_long_cycle_index"] = 0
        state["current_short_cycle_index"] = 0
        state["active_cycle_index"] = 1
        state["cycle_step"] = STEP_WAITING_FOR_PAIR_FIRST_LEG
        state["last_completed_purpose"] = None
        state["refill_required"] = False
        self._clear_second_leg_followup_residuals(runtime_state, clear_cycle_states=False)
        state["refill_exit_orders_cancel_required"] = False
        state["exit_locked"] = False
        state["exit_rebuild_allowed"] = True
        state["force_exit_rebuild"] = False
        state["last_exit_signature"] = None
        state["fresh_restart_required"] = False
        state["fresh_entry_blocked_until_next_tick"] = True
        state["last_confirmed_short_fill_price"] = 0.0
        state["last_confirmed_short_fill_cycle_index"] = 0
        state["last_confirmed_short_fill_purpose"] = None
        state["cycle_state"] = {}
        initialize_cycle_sequence_state(state, self._sequence_config)
        state["post_exit_reset_in_progress"] = True
        self._persist_cycle_sequence_state(runtime_state)
        _log_event(
            "fixed_cycle_post_exit_reset_completed",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "category": self.config.category,
                "active_cycle_index": state.get("active_cycle_index"),
                "cycle_step": state.get("cycle_step"),
                "next_required_purpose": state.get("next_required_purpose"),
                "sequence_recovery_blocked": state.get("sequence_recovery_blocked"),
            },
        )

    def _recover_cycle_sequence_state(self, runtime_state: RuntimeState, state: dict[str, Any]) -> bool:
        config = self._sequence_config
        processed = {
            str(item or "").upper()
            for item in state.get("processed_cycle_purposes") or []
        }
        active_cycle_index = int(state.get("active_cycle_index") or 1)
        first_purpose = f"{config.cycle_prefix}_{active_cycle_index}_{config.first_leg}".upper()
        second_purpose = (
            f"{config.cycle_prefix}_{active_cycle_index}_{config.second_leg}".upper()
        )
        first_done = first_purpose in processed
        second_done = second_purpose in processed
        updated = False
        log_payload_base = {
            "symbol": self.config.symbol,
            "category": self.config.category,
            "active_cycle_index": active_cycle_index,
            "cycle_step": state.get("cycle_step"),
            "next_required_purpose": state.get("next_required_purpose"),
            "last_completed_purpose": state.get("last_completed_purpose"),
            "processed_cycle_purposes": list(state.get("processed_cycle_purposes") or []),
        }
        if first_done and not second_done:
            before_recovery = (
                str(state.get("cycle_step") or ""),
                str(state.get("next_required_purpose") or "").upper(),
                str(state.get("last_completed_purpose") or "").upper(),
                int(state.get("active_cycle_index") or active_cycle_index),
            )
            if state.get("cycle_step") != STEP_WAITING_FOR_PAIR_SECOND_LEG:
                state["cycle_step"] = STEP_WAITING_FOR_PAIR_SECOND_LEG
            state["next_required_purpose"] = derive_next_required_purpose(
                config, active_cycle_index, state["cycle_step"]
            )
            state["last_completed_purpose"] = first_purpose
            state["sequence_recovery_blocked"] = False
            after_recovery = (
                str(state.get("cycle_step") or ""),
                str(state.get("next_required_purpose") or "").upper(),
                str(state.get("last_completed_purpose") or "").upper(),
                int(state.get("active_cycle_index") or active_cycle_index),
            )
            if before_recovery != after_recovery:
                _log_event(
                    "fixed_cycle_sequence_state_recovered_to_second_leg",
                    {
                        **log_payload_base,
                        "cycle_step": state["cycle_step"],
                        "next_required_purpose": state["next_required_purpose"],
                        "last_completed_purpose": state["last_completed_purpose"],
                        "sequence_recovery_blocked": False,
                    },
                )
                updated = True
        elif first_done and second_done:
            next_index = active_cycle_index + 1
            state["active_cycle_index"] = next_index
            state["cycle_step"] = STEP_WAITING_FOR_PAIR_FIRST_LEG
            state["next_required_purpose"] = derive_next_required_purpose(
                config, next_index, state["cycle_step"]
            )
            state["last_completed_purpose"] = second_purpose
            state["sequence_recovery_blocked"] = False
            _log_event(
                "fixed_cycle_sequence_state_recovered_to_next_cycle",
                {
                    **log_payload_base,
                    "active_cycle_index": state["active_cycle_index"],
                    "cycle_step": state["cycle_step"],
                    "next_required_purpose": state["next_required_purpose"],
                    "last_completed_purpose": state["last_completed_purpose"],
                    "sequence_recovery_blocked": False,
                },
            )
            updated = True
        elif second_done and not first_done:
            if not state.get("sequence_recovery_blocked"):
                state["sequence_recovery_blocked"] = True
                _log_event(
                    "fixed_cycle_sequence_state_inconsistent",
                    {
                        **log_payload_base,
                        "sequence_recovery_blocked": True,
                    },
                )
                _log_event(
                    "fixed_cycle_sequence_recovery_blocked",
                    {
                        **log_payload_base,
                        "sequence_recovery_blocked": True,
                    },
                )
            return False
        else:
            state.setdefault("sequence_recovery_blocked", False)
        return updated

    def _persist_cycle_sequence_state(self, runtime_state: RuntimeState) -> None:
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        cycle_state["cycle_states"] = dict(state.get("cycle_states") or {})
        cycle_state["processed_cycle_purposes"] = list(
            state.get("processed_cycle_purposes") or []
        )
        self._write_cycle_state(cycle_state)

    def _normalize_cycle_purpose(
        self,
        purpose: Any,
        metadata: dict[str, Any] | None = None,
    ) -> str:
        purpose_text = str(purpose or "").upper()
        metadata = metadata or {}
        cycle_index, field_name = self._extract_cycle_sequence_target(purpose_text, metadata)
        if cycle_index > 0 and self._is_cycle_first_leg_field(field_name):
            return self._cycle_purpose("long", cycle_index)
        if cycle_index > 0 and field_name == self._get_second_leg_status_field():
            return self._cycle_purpose("short", cycle_index)
        match = re.search(r"CYCLE_(\d+)_(LONG_ADD|SHORT_REDUCE|SHORT_TP)", purpose_text)
        if match:
            cycle_suffix = match.group(2)
            if cycle_suffix == "SHORT_TP":
                cycle_suffix = "SHORT_REDUCE"
            return f"CYCLE_{int(match.group(1))}_{cycle_suffix}"
        return purpose_text

    def _first_leg_pending_field(self) -> str:
        return "long_add_pending"

    def _second_leg_waiting_flag_field(self) -> str:
        return "cycle_waiting_for_short_tp"

    def _second_leg_pending_cycle_field(self) -> str:
        return "short_tp_pending_cycle"

    def _set_first_leg_pending(
        self,
        state: dict[str, Any],
        cycle_state: dict[str, Any] | None,
        value: bool,
    ) -> None:
        field = self._first_leg_pending_field()
        state[field] = bool(value)
        if cycle_state is not None:
            cycle_state[field] = bool(value)

    def _get_first_leg_pending(
        self, state: dict[str, Any], cycle_state: dict[str, Any] | None = None
    ) -> bool:
        field = self._first_leg_pending_field()
        if field in state:
            return bool(state.get(field))
        if cycle_state is not None:
            return bool(cycle_state.get(field))
        return False

    def _set_second_leg_pending_cycle(self, state: dict[str, Any], cycle_index: int) -> None:
        field = self._second_leg_pending_cycle_field()
        state[field] = cycle_index

    def _get_second_leg_pending_cycle(
        self, state: dict[str, Any], cycle_state: dict[str, Any] | None = None
    ) -> int:
        field = self._second_leg_pending_cycle_field()
        if field in state:
            return int(state.get(field) or 0)
        if cycle_state is not None:
            return int(cycle_state.get(field) or 0)
        return 0

    def _set_second_leg_waiting_state(
        self,
        state: dict[str, Any],
        cycle_state: dict[str, Any] | None = None,
        *,
        waiting: bool,
        cycle_index: int | None = None,
    ) -> None:
        waiting_field = self._second_leg_waiting_flag_field()
        pending_field = self._second_leg_pending_cycle_field()
        state[waiting_field] = waiting
        if cycle_state is not None:
            cycle_state[waiting_field] = waiting
        if cycle_index is not None:
            pending_value = int(cycle_index if waiting else 0)
            state[pending_field] = pending_value
            if cycle_state is not None:
                cycle_state[pending_field] = pending_value

    def _clear_second_leg_waiting_state(self, state: dict[str, Any]) -> None:
        self._set_second_leg_waiting_state(state, waiting=False, cycle_index=0)

    def _clear_second_leg_followup_residuals(
        self,
        runtime_state: RuntimeState,
        *,
        clear_cycle_states: bool = False,
    ) -> None:
        """Remove stale second-leg waiting/pending flags before a fresh structure."""
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        self._set_second_leg_waiting_state(state, cycle_state, waiting=False, cycle_index=0)
        state["cycle_waiting_for_short_tp"] = False
        state["short_tp_pending_cycle"] = 0
        state["cycle_waiting_for_long_reduce"] = False
        state["long_reduce_pending_cycle"] = 0
        state["pending_short_cycle_index"] = 0
        state["pending_long_cycle_index"] = 0
        state["refill_pending"] = False
        state["refill_in_progress"] = False
        state["post_refill_structure_rebuild_required"] = False
        state["cycle_long_add_filled"] = False
        state["cycle_short_tp_filled"] = False
        state["long_add_pending"] = False
        state["short_tp_pending"] = False
        if isinstance(cycle_state, dict):
            cycle_state["cycle_waiting_for_short_tp"] = False
            cycle_state["short_tp_pending_cycle"] = 0
            cycle_state["cycle_waiting_for_long_reduce"] = False
            cycle_state["long_reduce_pending_cycle"] = 0
            cycle_state["pending_short_cycle_index"] = 0
            cycle_state["pending_long_cycle_index"] = 0
            cycle_state["refill_pending"] = False
            cycle_state["refill_in_progress"] = False
            cycle_state["processed_cycle_purposes"] = list(
                state.get("processed_cycle_purposes") or []
            )
            if clear_cycle_states:
                cycle_state["cycle_states"] = {}
            elif "cycle_states" in state:
                cycle_state["cycle_states"] = dict(state.get("cycle_states") or {})
        if clear_cycle_states:
            state["cycle_states"] = {}
            if isinstance(cycle_state, dict):
                cycle_state["cycle_states"] = {}

    def _get_second_leg_waiting(
        self, state: dict[str, Any], cycle_state: dict[str, Any] | None = None
    ) -> bool:
        waiting_field = self._second_leg_waiting_flag_field()
        if waiting_field in state:
            return bool(state.get(waiting_field))
        if cycle_state is not None:
            return bool(cycle_state.get(waiting_field))
        return False

    def _get_second_leg_status(self, entry: dict[str, Any]) -> str:
        field_name = self._get_second_leg_status_field()
        return str(entry.get(field_name) or "NONE").upper()

    def _set_second_leg_status(self, entry: dict[str, Any], status: str) -> None:
        field_name = self._get_second_leg_status_field()
        entry[field_name] = str(status or "").upper()

    def _clear_recovery_pre_reload_stale_cycle_state(
        self,
        runtime_state: RuntimeState,
        recovery_cycle_index: int,
        *,
        reason: str = "pre_recovery_reload_cancel",
    ) -> None:
        """
        Bereinigt Second-Leg-/Short-TP-State für den Recovery-Referenz-Cycle,
        damit alte Pre-Recovery-Second-Leg-Orders den Reload nicht blockieren.
        """
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        cycle_entry = self._get_cycle_sequence_entry(runtime_state, recovery_cycle_index)
        if not isinstance(cycle_entry, dict):
            return
        symbol = self.config.symbol
        trade_block_id = state.get("trade_block_id")
        recovery_reload_id = state.get("recovery_reload_id")
        # Vorher-Zustand erfassen
        cycle_waiting_before = self._get_second_leg_waiting(state, cycle_state)
        short_tp_pending_before = self._get_second_leg_pending_cycle(state, cycle_state)
        pending_short_before = int(
            state.get("pending_short_cycle_index")
            or cycle_state.get("pending_short_cycle_index")
            or 0
        )
        next_required_before = state.get("next_required_purpose")
        cycle_step_before = state.get("cycle_step")
        short_tp_purpose = str(self._get_second_leg_purpose(recovery_cycle_index))
        long_add_rebuild_allowed_before = bool(state.get("long_add_rebuild_allowed", True))

        # Waiting-/Pending-Flags zurücksetzen
        self._set_second_leg_waiting_state(
            state,
            cycle_state,
            waiting=False,
            cycle_index=0,
        )
        state["pending_short_cycle_index"] = 0
        cycle_state["pending_short_cycle_index"] = 0

        # Second-Leg-Status und zugehörige Felder neutralisieren
        self._set_second_leg_status(cycle_entry, "NONE")
        for key, value in (
            ("short_tp_purpose", None),
            ("short_tp_qty", 0.0),
            ("short_tp_trigger_price", 0.0),
            ("short_tp_reserved_at", 0),
        ):
            if key in cycle_entry or value is not None:
                cycle_entry[key] = value

        # Nach dem Bereinigen des Second-Leg-States darf der Cycle-Builder
        # erneut Second-Leg-/Followup-Orders auf Basis der neuen
        # Recovery-Reload-Struktur aufbauen. Ein eventuell zuvor gesetztes
        # long_add_rebuild_allowed=False (z.B. nach dem ursprünglichen
        # LONG_ADD) würde diesen Rebuild sonst vollständig blockieren.
        state["long_add_rebuild_allowed"] = True

        self._persist_cycle_sequence_state(runtime_state)
        cycle_waiting_after = self._get_second_leg_waiting(state, cycle_state)
        short_tp_pending_after = self._get_second_leg_pending_cycle(state, cycle_state)
        pending_short_after = int(
            state.get("pending_short_cycle_index")
            or cycle_state.get("pending_short_cycle_index")
            or 0
        )
        next_required_after = state.get("next_required_purpose")
        cycle_step_after = state.get("cycle_step")
        long_add_rebuild_allowed_after = bool(state.get("long_add_rebuild_allowed", True))

        _log_event(
            "fixed_cycle_recovery_pre_reload_stale_cycle_state_cleared",
            {
                "symbol": symbol,
                "bot_name": self.config.bot_name,
                "trade_block_id": trade_block_id,
                "recovery_reload_id": recovery_reload_id,
                "recovery_cycle_index": recovery_cycle_index,
                "stale_cycle_purpose": short_tp_purpose,
                "cycle_waiting_for_short_tp_before": cycle_waiting_before,
                "cycle_waiting_for_short_tp_after": cycle_waiting_after,
                "short_tp_pending_cycle_before": short_tp_pending_before,
                "short_tp_pending_cycle_after": short_tp_pending_after,
                "pending_short_cycle_index_before": pending_short_before,
                "pending_short_cycle_index_after": pending_short_after,
                "next_required_purpose_before": next_required_before,
                "next_required_purpose_after": next_required_after,
                "cycle_step_before": cycle_step_before,
                "cycle_step_after": cycle_step_after,
                "long_add_rebuild_allowed_before": long_add_rebuild_allowed_before,
                "long_add_rebuild_allowed_after": long_add_rebuild_allowed_after,
                "reason": reason,
            },
        )

    def _maybe_clear_second_leg_waiting_without_orders(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
    ) -> None:
        """
        Guard gegen Broken-State:
        - cycle_waiting_for_short_tp ist True,
        - pending_short_cycle_index > 0,
        - aber keine aktiven Second-Leg-Orders mehr vorhanden.
        In diesem Fall wird der Waiting-State zurückgesetzt.
        """
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        waiting = self._get_second_leg_waiting(state, cycle_state)
        pending_cycle = self._get_second_leg_pending_cycle(state, cycle_state)
        if not waiting or pending_cycle <= 0:
            return

        # Prüfen, ob es faktisch noch ein aktives Second-Leg-Followup für diesen Cycle gibt
        second_leg_purpose = self._get_second_leg_purpose(pending_cycle)
        normalized_second_leg_purpose = self._normalize_cycle_purpose(second_leg_purpose)

        def _purpose_from_order(order: Any) -> str:
            if isinstance(order, dict):
                return str(order.get("purpose") or "").upper()
            return str(getattr(order, "purpose", "") or "").upper()

        def _status_from_order(order: Any) -> str:
            if isinstance(order, dict):
                return str(order.get("status") or "").upper()
            return str(getattr(order, "status", "") or "").upper()

        active_second_leg = False
        for order in runtime_state.active_orders.values():
            if _purpose_from_order(order) != normalized_second_leg_purpose:
                continue
            if self._is_terminal_order_status(_status_from_order(order)):
                continue
            active_second_leg = True
            break
        if not active_second_leg:
            for order in getattr(snapshot, "active_orders", []):
                if _purpose_from_order(order) != normalized_second_leg_purpose:
                    continue
                if self._is_terminal_order_status(_status_from_order(order)):
                    continue
                active_second_leg = True
                break
        if active_second_leg:
            return

        cycle_entry = self._get_cycle_sequence_entry(runtime_state, pending_cycle)
        previous_status = self._get_second_leg_status(cycle_entry)
        normalized_prev = self._normalize_cycle_order_status(previous_status)
        # Root-Fix 1: Ein reiner Waiting-State ohne jemals gebauten Second-Leg
        # (Status "NONE") darf nicht als REJECT interpretiert werden. In diesem
        # Fall wurde die Second-Leg-Order schlicht noch nicht gebaut.
        if normalized_prev == "NONE":
            return
        # Wenn der Second-Leg-Zustand bereits klar auf FILLED/PROCESSED steht bzw.
        # als gefüllt bestätigt wurde, darf dieser Guard den Status nicht auf
        # REJECTED drehen.
        fill_confirmed_field = self._second_leg_fill_confirmed_field()
        fill_price_field = self._second_leg_fill_price_field()
        second_leg_fill_confirmed = bool(cycle_entry.get(fill_confirmed_field))
        second_leg_fill_price = float(cycle_entry.get(fill_price_field) or 0.0)
        if normalized_prev in {"FILLED", "PROCESSED"} or second_leg_fill_confirmed or second_leg_fill_price > 0.0:
            _log_event(
                "fixed_cycle_second_leg_pending_state_kept_already_filled",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": pending_cycle,
                    "purpose": second_leg_purpose,
                    "second_leg_status": previous_status,
                    "second_leg_fill_confirmed": second_leg_fill_confirmed,
                    "second_leg_fill_price": second_leg_fill_price,
                    "cycle_waiting_for_second_leg": waiting,
                    "pending_second_leg_cycle_index": pending_cycle,
                },
            )
            return
        # Root-Fix 2: Für laufende Second-Legs (INTENT_BUILT/SUBMITTED/OPEN/…)
        # ist das Fehlen einer aktiven Order kein hinreichender Grund für REJECT.
        # In diesem Fall lediglich als "warte auf terminale Bestätigung" loggen.
        if normalized_prev in {
            "INTENT_BUILT",
            "SUBMITTING",
            "SUBMITTED",
            "OPEN",
            "NEW",
            "UNTRIGGERED",
            "PARTIALLY_FILLED",
        }:
            if normalized_prev == "INTENT_BUILT":
                # Recovery-Guard: Slot reserviert, aber keine aktive Second-Leg-Order vorhanden.
                # Status auf NONE zurücksetzen, Waiting/Pending beibehalten, damit ein neuer Intent
                # gebaut werden kann.
                self._set_second_leg_status(cycle_entry, "NONE")
                self._persist_cycle_sequence_state(runtime_state)
                _log_event(
                    "fixed_cycle_second_leg_intent_built_cleared_due_to_missing_order",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": pending_cycle,
                        "purpose": second_leg_purpose,
                        "previous_second_leg_status": previous_status,
                        "new_second_leg_status": "NONE",
                        "cycle_waiting_for_second_leg": waiting,
                        "pending_second_leg_cycle_index": pending_cycle,
                    },
                )
                return
            _log_event(
                "fixed_cycle_second_leg_active_order_missing_waiting_for_terminal_confirmation",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": pending_cycle,
                    "purpose": second_leg_purpose,
                    "second_leg_status": previous_status,
                    "normalized_second_leg_status": normalized_prev,
                    "cycle_waiting_for_second_leg": waiting,
                    "pending_second_leg_cycle_index": pending_cycle,
                },
            )
            return

        active_order_purposes: list[str] = []
        for order in getattr(snapshot, "active_orders", []):
            purpose = _purpose_from_order(order)
            if purpose:
                active_order_purposes.append(purpose)

        _log_event(
            "fixed_cycle_second_leg_all_intents_rejected",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "cycle_index": pending_cycle,
                "purpose": second_leg_purpose,
                "second_leg_status": previous_status,
                "cycle_waiting_for_short_tp": waiting,
                "pending_second_leg_cycle_index": pending_cycle,
                "active_order_purposes": active_order_purposes,
                "reason": "no_active_second_leg_order_for_pending_cycle",
            },
        )

        # Status auf REJECTED setzen und Waiting-Flags zurücksetzen.
        self._set_second_leg_status(cycle_entry, "REJECTED")
        self._set_second_leg_waiting_state(state, cycle_state, waiting=False, cycle_index=0)
        # generisches Pending-Feld der Second-Leg-Seite zurücksetzen
        pending_field = self._second_leg_pending_cycle_field()
        state[pending_field] = 0
        cycle_state[pending_field] = 0
        # vorhandene direction-spezifische Pending-Felder defensiv auf 0 setzen
        for pending_name in ("pending_short_cycle_index", "pending_long_cycle_index"):
            if pending_name in state:
                state[pending_name] = 0
            if pending_name in cycle_state:
                cycle_state[pending_name] = 0
        self._persist_cycle_sequence_state(runtime_state)

        _log_event(
            "fixed_cycle_second_leg_waiting_state_cleared_no_active_order",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "cycle_index": pending_cycle,
                "purpose": second_leg_purpose,
                "previous_second_leg_status": previous_status,
                "new_second_leg_status": "REJECTED",
                "cycle_waiting_for_short_tp": False,
                "pending_second_leg_cycle_index": 0,
            },
        )

    def _get_second_leg_status_field(self) -> str:
        return "short_tp_status"

    def _second_leg_fill_price_field(self) -> str:
        return "short_reduce_fill_price"

    def _second_leg_fill_confirmed_field(self) -> str:
        return "short_reduce_fill_confirmed"

    def _get_second_leg_cycle_role(self) -> str:
        # Für die Basisstrategie (Long-Bot) ist das zweite Cycle-Bein
        # ein Short-Reduce-TP und wird deshalb als "short_reduce" geführt.
        # Der Short-Bot überschreibt diese Methode mit "long_reduce".
        return "short_reduce"

    def _get_second_leg_purpose(self, cycle_index: int) -> str:
        return purpose_mapping.cycle_short_reduce(cycle_index)

    def _is_second_leg_purpose(self, purpose: str) -> bool:
        normalized = self._normalize_cycle_purpose(purpose)
        return bool(
            re.fullmatch(r"CYCLE_\d+_SHORT_REDUCE", normalized)
            or re.fullmatch(r"CYCLE_\d+_SHORT_TP", normalized)
        )

    def _maybe_build_normal_cycle_second_leg_split_intents(
        self,
        *,
        cycle_index: int,
        purpose: str,
        qty: float,
        trigger_price: float,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        side: str,
        position_idx: int,
        trigger_direction: int,
        metadata: dict[str, Any] | None = None,
    ) -> list[StrategyIntent] | None:
        if bool(runtime_state.strategy_state.get("recovery_required")):
            return None
        if self._normalize_cycle_purpose(purpose) != self._normalize_cycle_purpose(
            self._get_second_leg_purpose(cycle_index),
            {"cycle_index": cycle_index, "cycle_role": self._get_second_leg_cycle_role()},
        ):
            return None

        normalized_trigger_price = self._normalize_price(trigger_price, runtime_state)
        total_qty = self._normalize_qty(qty, runtime_state)
        if normalized_trigger_price <= 0 or total_qty <= 0:
            return None

        _, rules, _ = self._resolve_instrument_rules(runtime_state)
        min_order_qty = float(
            rules["min_order_qty"]
            if rules and rules.get("min_order_qty")
            else float(self.config.min_order_qty or 0.0)
        )
        min_notional = float(
            rules["min_notional"]
            if rules and rules.get("min_notional")
            else float(self.config.min_notional_usdt or 0.0)
        )

        stage_qtys: list[float] = []
        for candidate_stage_count in (3, 2):
            remaining_qty = total_qty
            candidate_qtys: list[float] = []
            valid = True
            desired_stage_qty = total_qty / float(candidate_stage_count)

            for idx in range(candidate_stage_count):
                if idx == candidate_stage_count - 1:
                    stage_qty = remaining_qty
                else:
                    stage_qty = self._normalize_qty(desired_stage_qty, runtime_state)
                if stage_qty <= 0 or stage_qty > remaining_qty + 1e-12:
                    valid = False
                    break
                stage_notional = stage_qty * normalized_trigger_price
                if (min_order_qty > 0 and stage_qty + 1e-12 < min_order_qty) or (
                    min_notional > 0 and stage_notional + 1e-8 < min_notional
                ):
                    valid = False
                    break
                candidate_qtys.append(stage_qty)
                remaining_qty = max(remaining_qty - stage_qty, 0.0)

            if valid and candidate_qtys and remaining_qty <= 1e-12:
                stage_qtys = candidate_qtys
                break

        if not stage_qtys:
            return None

        # Sicherheit: Vor Rückgabe prüfen, dass jede Stage das Min-Notional erfüllt.
        rejected_stage_indices: list[int] = []
        rejected_stage_notionals: list[float] = []
        if min_notional > 0:
            for idx, stage_qty in enumerate(stage_qtys):
                stage_notional = stage_qty * normalized_trigger_price
                if stage_notional + 1e-8 < min_notional:
                    rejected_stage_indices.append(idx)
                    rejected_stage_notionals.append(stage_notional)
        if rejected_stage_indices:
            _log_event(
                "fixed_cycle_second_leg_split_stage_below_min_notional",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "purpose": purpose,
                    "stage_count": len(stage_qtys),
                    "rejected_stage_indices": rejected_stage_indices,
                    "rejected_stage_notionals": rejected_stage_notionals,
                    "min_notional": min_notional,
                    "total_qty": total_qty,
                    "total_notional": total_qty * normalized_trigger_price,
                    "source": "normal_cycle_second_leg_split",
                },
            )
            return None

        state = runtime_state.strategy_state
        cycle_key = str(cycle_index)
        stage_count_map = state.setdefault("normal_cycle_second_leg_split_stage_count", {})
        stage_count_map[cycle_key] = len(stage_qtys)
        filled_map = state.setdefault("normal_cycle_second_leg_split_filled_stages", {})
        filled_map.setdefault(cycle_key, [])

        split_metadata = dict(metadata or {})
        split_metadata.pop("replace_open_purpose", None)
        split_metadata.update(
            {
                "normal_cycle_second_leg_split": True,
                "split_cycle_index": cycle_index,
                "split_stage_count": len(stage_qtys),
                "split_total_qty": total_qty,
                "split_stage_qtys": list(stage_qtys),
            }
        )
        intents: list[StrategyIntent] = []
        for stage_index, stage_qty in enumerate(stage_qtys):
            intent_metadata = {
                **split_metadata,
                "split_stage_index": stage_index,
            }
            intents.append(
                StrategyIntent(
                    side=side,
                    qty=stage_qty,
                    purpose=purpose,
                    order_type="Market",
                    reduce_only=True,
                    trigger_price=normalized_trigger_price,
                    trigger_direction=trigger_direction,
                    trigger_by="LastPrice",
                    close_on_trigger=True,
                    position_idx=position_idx,
                    metadata=intent_metadata,
                )
            )

        _log_event(
            "fixed_cycle_normal_cycle_second_leg_split_created",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "cycle_index": cycle_index,
                "purpose": purpose,
                "stage_count": len(stage_qtys),
                "total_qty": total_qty,
                "stage_qtys": stage_qtys,
                "trigger_price": normalized_trigger_price,
            },
        )
        return intents

    def _resolve_recovery_activation_role(self) -> str:
        timing = str(self.config.recovery_activation_timing or "").strip().lower()
        if timing == "after_first_leg_reduce_fill":
            return "first_leg"
        if timing == "after_short_reduce_fill":
            return "second_leg"
        return "second_leg"

    def _get_first_leg_fill_price(self, runtime_state: RuntimeState, cycle_index: int) -> float:
        cycle_state = self._ensure_cycle_state(runtime_state)
        side = self._get_first_leg_side()
        fills = cycle_state.get("long_fills" if side == "long" else "short_fills") or {}
        fill = fills.get(str(cycle_index)) or {}
        return float(fill.get("price") or 0.0)

    def _maybe_activate_recovery_after_first_leg_fill(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        *,
        cycle_index: int,
        trigger_price: float,
        first_leg_purpose: str,
        second_leg_purpose: str,
        first_leg_loss_usdt: float,
    ) -> bool:
        activation_role = self._resolve_recovery_activation_role()
        resolved_trigger_purpose = (
            first_leg_purpose if activation_role == "first_leg" else second_leg_purpose
        )
        _log_event(
            "fixed_cycle_recovery_activation_role_resolved",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "cycle_index": cycle_index,
                "bot_side": self.config.side,
                "activation_timing": self.config.recovery_activation_timing,
                "trigger_role": activation_role,
                "trigger_purpose": resolved_trigger_purpose,
            },
        )
        if activation_role != "first_leg":
            _log_event(
                "fixed_cycle_recovery_skipped_waiting_for_wrong_leg",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "bot_side": self.config.side,
                    "activation_timing": self.config.recovery_activation_timing,
                    "trigger_role": activation_role,
                    "trigger_purpose": resolved_trigger_purpose,
                },
            )
            return False
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        first_leg_fill_price = self._get_first_leg_fill_price(runtime_state, cycle_index)
        if first_leg_fill_price <= 0:
            first_leg_fill_price = float(cycle_state.get("last_cycle_reference_price") or 0.0)
        distance_pct_signed = (
            ((trigger_price - first_leg_fill_price) / first_leg_fill_price) * 100.0
            if first_leg_fill_price > 0
            else 0.0
        )
        distance_pct_abs = abs(distance_pct_signed)
        threshold_pct = float(self.config.max_post_recovery_long_reduce_distance_pct or 0.0)
        would_set_recovery_required = distance_pct_abs > threshold_pct
        _log_event(
            "fixed_cycle_post_first_leg_recovery_projection",
            {
                "symbol": snapshot.symbol or self.config.symbol,
                "cycle_index": cycle_index,
                "fill_price": first_leg_fill_price,
                "projected_next_reduce_price": trigger_price,
                "distance_pct_signed": distance_pct_signed,
                "distance_pct_abs": distance_pct_abs,
                "threshold_pct": threshold_pct,
                "would_set_recovery_required": would_set_recovery_required,
                "first_leg_loss_usdt": first_leg_loss_usdt,
            },
        )
        if not would_set_recovery_required:
            return False
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        recovery_completed_cycle_index = int(
            state.get("recovery_completed_cycle_index")
            or cycle_state.get("recovery_completed_cycle_index")
            or 0
        )
        active_cycle_index = int(state.get("active_cycle_index") or 0)
        normalized_next_required_purpose = self._normalize_cycle_purpose(
            state.get("next_required_purpose") or ""
        )
        processed_cycle_purposes = list(state.get("processed_cycle_purposes") or [])
        normalized_first_leg_purpose = self._normalize_cycle_purpose(
            first_leg_purpose or "",
            {
                "cycle_index": cycle_index,
                "cycle_role": self._get_first_leg_cycle_role(),
            },
        )
        normalized_second_leg_purpose = self._normalize_cycle_purpose(
            second_leg_purpose or "",
            {
                "cycle_index": cycle_index,
                "cycle_role": self._get_second_leg_cycle_role(),
            },
        )
        recovery_reactivation_skip = (
            cycle_index > 0
            and recovery_completed_cycle_index == cycle_index
            and active_cycle_index == cycle_index
            and normalized_next_required_purpose == normalized_second_leg_purpose
            and normalized_first_leg_purpose in processed_cycle_purposes
        )
        if recovery_reactivation_skip:
            _log_event(
                "fixed_cycle_recovery_reactivation_skipped_after_completed_refill",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "cycle_index": cycle_index,
                    "recovery_completed_cycle_index": recovery_completed_cycle_index,
                    "active_cycle_index": active_cycle_index,
                    "next_required_purpose": normalized_next_required_purpose,
                    "first_leg_purpose": normalized_first_leg_purpose,
                    "second_leg_purpose": normalized_second_leg_purpose,
                    "processed_cycle_purposes": processed_cycle_purposes,
                    "distance_pct_signed": distance_pct_signed,
                    "distance_pct_abs": distance_pct_abs,
                    "threshold_pct": threshold_pct,
                },
            )
        return False

    def _first_leg_reduce_role(self) -> str:
        return "long_reduce"

    def _second_leg_reduce_role(self) -> str:
        return "short_reduce"

    def _first_leg_cycle_pnl_key(self) -> str:
        return "cycle_long_reduce_pnl"

    def _second_leg_cycle_pnl_key(self) -> str:
        return "cycle_short_tp_pnl"

    def _first_leg_closed_pnl_field(self) -> str:
        return "long_reduce_closed_pnl"

    def _second_leg_closed_pnl_field(self) -> str:
        return "short_reduce_closed_pnl"

    def _second_leg_fill_price_field(self) -> str:
        return "short_reduce_fill_price"

    def _second_leg_fill_confirmed_field(self) -> str:
        return "short_reduce_fill_confirmed"

    def _clear_cycle_entry_reservation(
        self,
        runtime_state: RuntimeState,
        entry: dict[str, Any],
        *,
        field_name: str,
        new_status: str,
    ) -> None:
        state = runtime_state.strategy_state
        prefix = self._cycle_entry_prefix(field_name)
        entry[field_name] = new_status
        entry[f"{prefix}_qty"] = 0.0
        entry[f"{prefix}_trigger_price"] = 0.0
        entry[f"{prefix}_reserved_at"] = 0
        entry[f"{prefix}_purpose"] = None
        cycle_state = self._ensure_cycle_state(runtime_state)
        if self._is_cycle_first_leg_field(field_name):
            self._set_first_leg_pending(state, cycle_state, False)
        else:
            self._clear_second_leg_waiting_state(state)
            self._set_second_leg_pending_cycle(state, 0)
            self._clear_second_leg_waiting_state(cycle_state)
            self._set_second_leg_pending_cycle(cycle_state, 0)

    def _get_first_leg_status_field(self) -> str:
        return "long_add_status"

    def _cycle_entry_role(self, field_name: str) -> str:
        return "first_leg" if field_name == self._get_first_leg_status_field() else "second_leg"

    def _cycle_entry_prefix(self, field_name: str) -> str:
        role = self._cycle_entry_role(field_name)
        return "long_add" if role == "first_leg" else "short_tp"

    def _is_cycle_first_leg_field(self, field_name: str) -> bool:
        return self._cycle_entry_role(field_name) == "first_leg"

    def _get_first_leg_side(self) -> str:
        return "long"

    def _get_first_leg_position_idx(self) -> int:
        return 1

    def _get_first_leg_cycle_role(self) -> str:
        return "long_reduce"

    def _get_first_leg_purpose(self, cycle_index: int) -> str:
        return self._cycle_purpose(self._get_first_leg_side(), cycle_index)

    def _reserve_cycle_intent_slot(
        self,
        runtime_state: RuntimeState,
        *,
        cycle_index: int,
        field_name: str,
        normalized_purpose: str,
        qty: float,
        trigger_price: float,
    ) -> None:
        state = runtime_state.strategy_state
        entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
        prefix = self._cycle_entry_prefix(field_name)
        previous_status = str(entry.get(field_name) or "NONE").upper()
        entry[field_name] = "INTENT_BUILT"
        entry[f"{prefix}_qty"] = float(qty or 0.0)
        entry[f"{prefix}_trigger_price"] = float(trigger_price or 0.0)
        entry[f"{prefix}_reserved_at"] = int(time.time() * 1000)
        entry[f"{prefix}_purpose"] = normalized_purpose
        cycle_state = self._ensure_cycle_state(runtime_state)
        if self._is_cycle_first_leg_field(field_name):
            self._set_first_leg_pending(state, cycle_state, True)
            log_event_name = "fixed_cycle_cycle_long_add_intent_reserved"
        else:
            self._set_second_leg_waiting_state(
                state, cycle_state, waiting=True, cycle_index=cycle_index
            )
            cycle_state["pending_short_cycle_index"] = cycle_index
            log_event_name = "fixed_cycle_cycle_short_tp_intent_reserved"
        self._persist_cycle_sequence_state(runtime_state)
        _log_event(
            log_event_name,
            {
                "symbol": self.config.symbol,
                "cycle_index": cycle_index,
                "purpose": normalized_purpose,
                "previous_status": previous_status,
                "new_status": "INTENT_BUILT",
                "qty": float(qty or 0.0),
                "trigger_price": float(trigger_price or 0.0),
            },
        )

    def _collect_active_cycle_order_matches(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        *,
        purpose: str,
        cycle_index: int,
        cycle_role: str,
    ) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        target_purpose = self._normalize_cycle_purpose(
            purpose,
            {"cycle_index": cycle_index, "cycle_role": cycle_role},
        )
        first_leg_role = self._get_first_leg_cycle_role()
        second_leg_role = self._get_second_leg_cycle_role()
        if cycle_role == first_leg_role:
            target_field = self._get_first_leg_status_field()
        elif cycle_role == second_leg_role:
            target_field = self._get_second_leg_status_field()
        else:
            target_field = self._get_second_leg_status_field()

        def _matches(order: Any) -> bool:
            metadata = getattr(order, "metadata", None)
            metadata = metadata if isinstance(metadata, dict) else {}
            normalized_status = self._normalize_cycle_order_status(getattr(order, "status", None))
            if not self._cycle_status_blocks_build(normalized_status):
                return False
            normalized_order_purpose = self._normalize_cycle_purpose(
                getattr(order, "purpose", None),
                metadata,
            )
            if normalized_order_purpose == target_purpose:
                return True
            order_cycle_index, order_field = self._extract_cycle_sequence_target(
                getattr(order, "purpose", None),
                metadata,
            )
            return order_cycle_index == cycle_index and order_field == target_field

        def _summarize(order: Any, source: str) -> dict[str, Any]:
            metadata = getattr(order, "metadata", None)
            metadata = metadata if isinstance(metadata, dict) else {}
            normalized_status = self._normalize_cycle_order_status(getattr(order, "status", None))
            return {
                "source": source,
                "client_order_id": getattr(order, "client_order_id", None),
                "exchange_order_id": getattr(order, "exchange_order_id", None),
                "purpose": getattr(order, "purpose", None),
                "normalized_purpose": self._normalize_cycle_purpose(
                    getattr(order, "purpose", None),
                    metadata,
                ),
                "status": getattr(order, "status", None),
                "normalized_status": normalized_status,
                "remaining_qty": float(getattr(order, "remaining_qty", 0.0) or 0.0),
                "qty": float(getattr(order, "qty", 0.0) or 0.0),
                "filled_qty": float(getattr(order, "filled_qty", 0.0) or 0.0),
                "split_stage_index": metadata.get("split_stage_index"),
                "split_stage_count": metadata.get("split_stage_count"),
                "normal_cycle_second_leg_split": bool(metadata.get("normal_cycle_second_leg_split")),
            }

        runtime_matches = [
            _summarize(order, "runtime")
            for order in runtime_state.active_orders.values()
            if _matches(order)
        ]
        snapshot_matches = [
            _summarize(order, "snapshot")
            for order in snapshot.active_orders
            if _matches(order)
        ]
        return runtime_matches, snapshot_matches

    def _reconcile_cycle_intent_reservation(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        *,
        cycle_index: int,
        field_name: str,
        purpose: str,
        cycle_role: str,
    ) -> tuple[dict[str, Any], list[dict[str, Any]], list[dict[str, Any]]]:
        entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
        runtime_matches, snapshot_matches = self._collect_active_cycle_order_matches(
            snapshot,
            runtime_state,
            purpose=purpose,
            cycle_index=cycle_index,
            cycle_role=cycle_role,
        )
        status = (
            self._get_second_leg_status(entry)
            if field_name == self._get_second_leg_status_field()
            else str(entry.get(field_name) or "NONE").upper()
        )
        prefix = self._cycle_entry_prefix(field_name)
        if runtime_matches or snapshot_matches:
            matched_status = str(
                (runtime_matches + snapshot_matches)[0].get("normalized_status") or "SUBMITTED"
            ).upper()
            if self._cycle_status_blocks_build(matched_status) and matched_status != status:
                if field_name == self._get_second_leg_status_field():
                    self._set_second_leg_status(entry, matched_status)
                else:
                    entry[field_name] = matched_status
                self._persist_cycle_sequence_state(runtime_state)
            return entry, runtime_matches, snapshot_matches
        if status == "INTENT_BUILT":
            reserved_at = int(entry.get(f"{prefix}_reserved_at") or 0)
            stale_after_ms = max(int(self.config.order_refresh_cooldown_ms or 0) * 20, 15000)
            now_ms = int(time.time() * 1000)
            if reserved_at > 0 and now_ms - reserved_at >= stale_after_ms:
                self._clear_cycle_entry_reservation(
                    runtime_state,
                    entry,
                    field_name=field_name,
                    new_status="EXPIRED",
                )
                self._persist_cycle_sequence_state(runtime_state)
                _log_event(
                    "fixed_cycle_cycle_intent_marked_stale",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": cycle_index,
                        "purpose": self._normalize_cycle_purpose(
                            purpose,
                            {"cycle_index": cycle_index, "cycle_role": cycle_role},
                        ),
                        "field_name": field_name,
                        "previous_status": status,
                        "new_status": "EXPIRED",
                        "stale_after_ms": stale_after_ms,
                    },
                )
        return entry, runtime_matches, snapshot_matches

    def _safety_structure_watchdog(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent] | None:
        """
        Vereinfachter Safety-Watchdog:
        - prüft die erwartete Order-Struktur auf Vollständigkeit
        - loggt fehlende Pflicht-Orders zur Diagnose
        - löst nur optional einen Emergency-Flat aus, wenn
          internal_safety_watchdog_mode == "emergency_flat" konfiguriert ist
        """
        state = runtime_state.strategy_state
        long_qty = float(snapshot.long_qty or 0.0)
        short_qty = float(snapshot.short_qty or 0.0)

        # Flat → kein Safety-Close nötig.
        if long_qty <= 0.0 and short_qty <= 0.0:
            return None

        bot_state = state.get("bot_state")

        # Initial Entry / Strukturaufbau läuft noch → Watchdog überspringen.
        if not state.get("initial_structure_built") or not state.get("initial_entry_confirmed"):
            _log_event(
                "fixed_cycle_safety_watchdog_skipped_initial_entry",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "bot_state": bot_state,
                    "initial_structure_built": bool(state.get("initial_structure_built")),
                    "initial_entry_confirmed": bool(state.get("initial_entry_confirmed")),
                },
            )
            return None

        # Finaler Exit / Fresh-Restart / Emergency / Reset-Pfade → nicht doppelt eingreifen.
        if state.get("fresh_restart_required") or state.get("full_exit_reset_in_progress") or state.get(
            "emergency_flat_required"
        ):
            _log_event(
                "fixed_cycle_safety_watchdog_skipped_final_exit",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "bot_state": bot_state,
                    "fresh_restart_required": bool(state.get("fresh_restart_required")),
                    "full_exit_reset_in_progress": bool(state.get("full_exit_reset_in_progress")),
                    "emergency_flat_required": bool(state.get("emergency_flat_required")),
                },
            )
            return None

        # Refill-Aktivität: hier prüfen wir die erwarteten Refill-Orders statt Cycle-Order.
        refill_pending = bool(state.get("refill_pending"))
        refill_required = bool(state.get("refill_required"))
        refill_in_progress = bool(state.get("refill_in_progress"))
        refill_active = refill_pending or refill_required or refill_in_progress or bot_state == self.STATE_REFILL_PENDING

        now_ms = int(time.time() * 1000)
        last_refresh_ms = int(state.get("last_structure_refresh_ms") or 0)
        base_cooldown_ms = int(self.config.order_refresh_cooldown_ms or 0)
        grace_ms = max(5000, min(15000, base_cooldown_ms or 5000))

        # Grace-Phase nach Struktur-Refresh/Exit-Rebuild, damit wir nicht während
        # laufender Submit/Cancel-Phasen auslösen.
        if last_refresh_ms > 0 and now_ms - last_refresh_ms < grace_ms:
            _log_event(
                "fixed_cycle_safety_watchdog_grace_active",
                {
                    "symbol": snapshot.symbol or self.config.symbol,
                    "bot_state": bot_state,
                    "age_ms": now_ms - last_refresh_ms,
                    "grace_ms": grace_ms,
                    "last_structure_refresh_ms": last_refresh_ms,
                },
            )
            return None

        # Erwartete Exit-Orders bei offener Position: direction-aware Final-Exits
        expected_purposes: set[str] = set()
        if long_qty > 0.0 or short_qty > 0.0:
            expected_purposes.update(self._get_final_exit_purposes())

        next_required_purpose = str(state.get("next_required_purpose") or "").upper()
        active_cycle_index = int(state.get("active_cycle_index") or 0)
        cycle_waiting_for_short_tp = self._get_second_leg_waiting(state, state.get("cycle_state") or {})

        # Erwartete Cycle- oder Refill-Orders ergänzen.
        if refill_active:
            refill_state = state.get("refill_state") or {}
            expected_refill = refill_state.get("expected_purposes") or []
            if expected_refill:
                for purpose in expected_refill:
                    if purpose:
                        expected_purposes.add(str(purpose).upper())
            else:
                _log_event(
                    "fixed_cycle_safety_watchdog_skipped_refill_transition",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "bot_state": bot_state,
                        "refill_pending": refill_pending,
                        "refill_required": refill_required,
                        "refill_in_progress": refill_in_progress,
                    },
                )
                return None
        else:
            # Nur wenn eine echte Cycle-Order als nächster Schritt erwartet wird.
            if next_required_purpose.startswith("CYCLE_"):
                expected_purposes.add(self._normalize_cycle_purpose(next_required_purpose))

        # Tatsächlich vorhandene Zwecke (inkl. Trading-Stop-logischer Exits).
        present_purposes: set[str] = set()

        def _collect(order: Any) -> None:
            purpose = getattr(order, "purpose", None)
            status = str(getattr(order, "status", "") or "").upper()
            if not purpose:
                return
            if self._is_terminal_order_status(status):
                return
            normalized = self._normalize_cycle_purpose(str(purpose or "").upper())
            present_purposes.add(normalized)

        for order in runtime_state.active_orders.values():
            _collect(order)
        for order in getattr(snapshot, "active_orders", []) or []:
            _collect(order)

        normalized_expected = {self._normalize_cycle_purpose(p) for p in expected_purposes}
        missing_purposes = sorted(normalized_expected - present_purposes)

        payload = {
            "symbol": snapshot.symbol or self.config.symbol,
            "expected_purposes": sorted(normalized_expected),
            "present_purposes": sorted(present_purposes),
            "missing_purposes": missing_purposes,
            "long_qty": long_qty,
            "short_qty": short_qty,
            "next_required_purpose": next_required_purpose,
            "active_cycle_index": active_cycle_index,
            "cycle_waiting_for_short_tp": cycle_waiting_for_short_tp,
            "refill_required": refill_required,
            "refill_pending": refill_pending,
            "refill_in_progress": refill_in_progress,
            "bot_state": bot_state,
        }

        _log_event("fixed_cycle_safety_watchdog_expected_structure", payload)

        if not missing_purposes:
            _log_event("fixed_cycle_safety_watchdog_structure_complete", payload)
            return None

        # Fehlende Pflicht-Order → je nach Modus nur loggen oder optional Emergency-Flat auslösen.
        _log_event("fixed_cycle_safety_watchdog_missing_required_order_detected", payload)

        mode = (self.config.internal_safety_watchdog_mode or "log_only").lower()
        if mode != "emergency_flat":
            # Standard: Nur Logging, kein interner Close. Externer Watchdog bleibt die einzige
            # Instanz, die Positionen aktiv schließen darf.
            return None

        triggered = self._trigger_emergency_flat_for_remaining_positions(
            snapshot,
            runtime_state,
            context,
            "safety_watchdog_missing_required_order",
        )
        if triggered:
            _log_event(
                "fixed_cycle_safety_watchdog_emergency_flat_triggered",
                payload,
            )
        return self._maybe_handle_emergency_exit_tick(snapshot, runtime_state, context)

    def _get_cycle_sequence_entry(
        self, runtime_state: RuntimeState, cycle_index: int
    ) -> dict[str, Any]:
        cycle_states = self._ensure_cycle_sequence_state(runtime_state)
        cycle_key = str(max(int(cycle_index or 0), 0))
        if cycle_key not in cycle_states:
            cycle_states[cycle_key] = self._default_cycle_sequence_entry()
        return cycle_states[cycle_key]

    def _extract_cycle_sequence_target(
        self,
        purpose: str,
        metadata: dict[str, Any] | None = None,
    ) -> tuple[int, str | None]:
        purpose_text = str(purpose or "").upper()
        metadata = metadata or {}
        exit_mode = str(metadata.get("exit_mode") or "").lower()
        exit_type = str(metadata.get("exit_type") or "").lower()
        known_final_exit_purposes = {
            "LONG_TP_EXIT",
            "LONG_TP_EXIT_RECOVERY",
            "LONG_SL_EXIT",
            "SHORT_TP_EXIT",
            "SHORT_SL_EXIT",
            "SHORT_SL_EXIT_RECOVERY",
            "SHORT_HARD_STOP",
            "SHORT_HARD_STOP_EXIT",
            "FINAL_LONG_EXIT",
            "FINAL_SHORT_EXIT",
        }
        cycle_index = 0
        try:
            cycle_index = int(metadata.get("cycle_index") or 0)
        except (TypeError, ValueError):
            cycle_index = 0
        if (
            purpose_text in known_final_exit_purposes
            or exit_mode == "basket_exit"
            or exit_type in {"long_tp", "short_sl"}
        ):
            _log_event(
                "fixed_cycle_final_exit_purpose_excluded_from_cycle_normalization",
                {
                    "purpose": purpose_text,
                    "exit_mode": exit_mode,
                    "exit_type": exit_type,
                    "cycle_index": cycle_index,
                },
            )
            return 0, None
        if cycle_index <= 0:
            match = re.search(r"CYCLE_(\d+)_", purpose_text)
            if match:
                cycle_index = int(match.group(1))
        if cycle_index <= 0:
            return 0, None
        cycle_role = str(metadata.get("cycle_role") or "").lower()
        first_leg_field = self._get_first_leg_status_field()
        second_leg_field = self._get_second_leg_status_field()
        first_leg_purpose = self._get_first_leg_purpose(cycle_index)
        second_leg_purpose = self._get_second_leg_purpose(cycle_index)
        if cycle_role == self._get_first_leg_cycle_role() or purpose_text == first_leg_purpose:
            return cycle_index, first_leg_field
        if cycle_role == self._get_second_leg_cycle_role() or purpose_text == second_leg_purpose:
            return cycle_index, second_leg_field
        return 0, None

    def _mark_cycle_purpose_status(
        self,
        runtime_state: RuntimeState,
        *,
        purpose: str,
        metadata: dict[str, Any] | None,
        status: str,
    ) -> None:
        cycle_index, field_name = self._extract_cycle_sequence_target(purpose, metadata)
        if cycle_index <= 0 or not field_name:
            return
        state = runtime_state.strategy_state
        entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
        normalized_status = str(status or "").upper()
        normalized_purpose = self._normalize_cycle_purpose(purpose, metadata)
        previous_status = str(entry.get(field_name) or "NONE").upper()
        if previous_status != normalized_status:
            entry[field_name] = normalized_status
            if normalized_status == "FILLED":
                event_name = (
                    "fixed_cycle_cycle_long_add_marked_filled"
                    if self._is_cycle_first_leg_field(field_name)
                    else "fixed_cycle_cycle_short_tp_marked_filled"
                )
                _log_event(
                    event_name,
                    {
                        "cycle_index": cycle_index,
                        "purpose": purpose,
                        "previous_status": previous_status,
                        "new_status": normalized_status,
                    },
                )
        if normalized_status == "FILLED":
            processed = set(state.get("processed_cycle_purposes") or [])
            # Für gestagte Second-Leg-TPs darf die Cycle-Purpose erst dann als processed gelten,
            # wenn der gestagte TP insgesamt abgeschlossen ist (alle Stages gefüllt oder Nettoprofit gedeckt).
            is_staged_second_leg = bool((metadata or {}).get("is_staged_second_leg_tp"))
            is_normal_split_second_leg = bool((metadata or {}).get("normal_cycle_second_leg_split"))
            if is_staged_second_leg:
                # Stage-Fill: Status-Feld kann auf FILLED gehen, aber Purpose bleibt vorerst unprocessed.
                # Ob der Cycle wirklich abgeschlossen ist, entscheidet ausschließlich
                # die pro-Cycle Staging-Logik in _complete_cycle_entry_if_done.
                self._complete_cycle_entry_if_done(runtime_state, cycle_index, purpose)
                return
            if is_normal_split_second_leg:
                complete, _ = self._is_normal_cycle_second_leg_split_complete(state, cycle_index)
                if not complete:
                    self._complete_cycle_entry_if_done(runtime_state, cycle_index, purpose)
                    return
            if normalized_purpose not in processed:
                exchange_order_id = str((metadata or {}).get("exchange_order_id") or "").strip()
                requires_confirmed_row = purpose_requires_confirmed_history_row(normalized_purpose)
                has_confirmed_row = (
                    not requires_confirmed_row
                    or self._confirmed_history_has_purpose(
                        runtime_state,
                        normalized_purpose,
                        exchange_order_id=exchange_order_id or None,
                    )
                )
                if has_confirmed_row:
                    processed.add(normalized_purpose)
                    state["processed_cycle_purposes"] = sorted(processed)
                    _log_event(
                        "fixed_cycle_cycle_purpose_marked_processed",
                        {
                            "cycle_index": cycle_index,
                            "purpose": purpose,
                            "normalized_purpose": normalized_purpose,
                            "phase": field_name,
                        },
                    )
                else:
                    _log_warning_event(
                        "fixed_cycle_cycle_purpose_deferred_until_confirmed_history",
                        {
                            "cycle_index": cycle_index,
                            "purpose": purpose,
                            "normalized_purpose": normalized_purpose,
                            "phase": field_name,
                            "exchange_order_id": exchange_order_id or None,
                        },
                    )
            cycle_index, _ = self._extract_cycle_sequence_target(purpose, metadata)
            if cycle_index > 0 and self._is_cycle_first_leg_field(field_name):
                self._purge_filled_long_add_orders(runtime_state, cycle_index)
            normalized_second_leg_purpose = self._normalize_cycle_purpose(
                self._get_second_leg_purpose(cycle_index),
                {
                    "cycle_index": cycle_index,
                    "cycle_role": self._get_second_leg_cycle_role(),
                },
            )
            if (
                cycle_index > 0
                and normalized_purpose == normalized_second_leg_purpose
                and int(state.get("recovery_completed_cycle_index") or 0) == cycle_index
            ):
                state.pop("recovery_completed_cycle_index", None)
                cycle_state = self._ensure_cycle_state(runtime_state)
                cycle_state.pop("recovery_completed_cycle_index", None)
        self._complete_cycle_entry_if_done(runtime_state, cycle_index, purpose)

    def _complete_cycle_entry_if_done(
        self,
        runtime_state: RuntimeState,
        cycle_index: int,
        purpose: str,
    ) -> None:
        if cycle_index <= 0:
            return
        state = runtime_state.strategy_state
        # Für gestagte Second-Leg-TPs darf der Cycle erst dann als vollständig gelten,
        # wenn die gestagte Second-Leg-TP-Logik den Abschluss für GENAU diesen Cycle signalisiert.
        # Dafür verwenden wir die pro-Cycle Nettoprofit-Maps, nicht das globale Flag cycle_short_tp_filled.
        staged_required_map = state.get("staged_second_leg_tp_required_net_total") or {}
        split_stage_count_map = state.get("normal_cycle_second_leg_split_stage_count") or {}
        cycle_key = str(cycle_index)
        is_staged_cycle = cycle_key in staged_required_map
        is_normal_split_cycle = cycle_key in split_stage_count_map
        if is_staged_cycle:
            has_real_config, diag = self._has_real_staged_second_leg_config(state, cycle_index, metadata=None)
            complete = bool(diag.get("complete"))
            # Root-Fix: Wenn weder Stage-Count noch Required-Net für diesen Cycle
            # gesetzt sind, liegt keine echte Staging-Konfiguration vor. In diesem
            # Fall Staging-Gates ignorieren und die Completion über die normalen
            # First-/Second-Leg-Status laufen lassen.
            if not has_real_config:
                is_staged_cycle = False
            elif not complete:
                _log_event(
                    "fixed_cycle_staged_second_leg_completion_insufficient_requirements",
                    diag,
                )
                # Für diesen gestagten Cycle ist der TP aus Sicht der Staging-Logik
                # noch nicht vollständig.
                return
        elif is_normal_split_cycle:
            complete, _ = self._is_normal_cycle_second_leg_split_complete(state, cycle_index)
            if not complete:
                return
        entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
        # Root-Cause-Härtung: Wenn ein gestagter Second-Leg-TP für diesen Cycle laut PnL-Logik
        # abgeschlossen ist, der direction-neutrale Second-Leg-Status aber noch auf
        # "NONE"/nicht-FILLED steht, setzen wir ihn hier explizit auf "FILLED", damit der Cycle
        # konsistent als vollständig gelten kann.
        if is_staged_cycle or is_normal_split_cycle:
            second_leg_status = self._get_second_leg_status(entry)
            if second_leg_status != "FILLED":
                self._set_second_leg_status(entry, "FILLED")
        first_leg_field = self._get_first_leg_status_field()
        if (
            entry.get(first_leg_field) != "FILLED"
            or self._get_second_leg_status(entry) != "FILLED"
            or entry.get("complete")
        ):
            return
        entry["complete"] = True
        _log_event(
            "fixed_cycle_cycle_marked_complete",
            {
                "cycle_index": cycle_index,
                "purpose": purpose,
            },
        )
        _log_event(
            "fixed_cycle_next_cycle_unlocked",
            {
                "completed_cycle_index": cycle_index,
                "next_cycle_index": cycle_index + 1,
            },
        )
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        # Direction-neutral Second-Leg-Followup-Flags über Helper zurücksetzen
        self._set_second_leg_waiting_state(state, cycle_state, waiting=False, cycle_index=0)
        pending_field = self._second_leg_pending_cycle_field()
        state[pending_field] = 0
        cycle_state[pending_field] = 0
        self._persist_cycle_sequence_state(runtime_state)

    def _clear_cycle_followup_state_after_short_reduce(
        self,
        runtime_state: RuntimeState,
        cycle_index: int,
        followup_before: dict[str, Any],
        counts_before: dict[str, int],
        counts_after: dict[str, int],
    ) -> None:
        if cycle_index <= 0:
            return
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        before = followup_before
        # Direction-neutral Second-Leg-Waiting/Pending-State zurücksetzen
        self._set_second_leg_waiting_state(state, cycle_state, waiting=False, cycle_index=0)
        pending_field = self._second_leg_pending_cycle_field()
        state[pending_field] = 0
        cycle_state[pending_field] = 0
        state["pending_short_cycle_index"] = 0
        state["long_add_pending"] = False
        state["pending_cycle_loss_usdt"] = 0.0
        state["short_tp_fallback_state"] = None
        cycle_state["pending_short_cycle_index"] = 0
        cycle_state["long_add_pending"] = False
        cycle_state["cycle_completed_count"] = counts_after["cycle_completed_count"]
        cycle_state["current_effective_cycle"] = counts_after["current_effective_cycle"]
        cycle_state["short_cycle_index"] = max(
            int(cycle_state.get("short_cycle_index") or 0), counts_after["current_short_cycle_index"]
        )
        _log_event(
            "fixed_cycle_cycle_followup_state_cleared_after_short_reduce_fill",
            {
                "symbol": self.config.symbol,
                "cycle_index": cycle_index,
                "cycle_waiting_for_short_tp_before": before["cycle_waiting_for_short_tp"],
                "cycle_waiting_for_short_tp_after": False,
                "short_tp_pending_cycle_before": before["short_tp_pending_cycle"],
                "short_tp_pending_cycle_after": 0,
                "pending_short_cycle_index_before": before["pending_short_cycle_index"],
                "pending_short_cycle_index_after": 0,
                "long_add_pending_before": before["long_add_pending"],
                "long_add_pending_after": False,
                "pending_cycle_loss_usdt_before": before["pending_cycle_loss_usdt"],
                "pending_cycle_loss_usdt_after": 0.0,
                "cycle_completed_count_before": counts_before["cycle_completed_count"],
                "cycle_completed_count_after": counts_after["cycle_completed_count"],
                "cycle_pair_count_before": counts_before["cycle_pair_count"],
                "cycle_pair_count_after": counts_after["cycle_pair_count"],
                "current_effective_cycle_before": counts_before["current_effective_cycle"],
                "current_effective_cycle_after": counts_after["current_effective_cycle"],
                "current_short_cycle_index_before": counts_before["current_short_cycle_index"],
                "current_short_cycle_index_after": counts_after["current_short_cycle_index"],
                "processed_cycle_purposes": state.get("processed_cycle_purposes"),
            },
        )

    def _has_cycle_purpose_already_filled_or_processed(
        self,
        runtime_state: RuntimeState,
        purpose: str,
        metadata: dict[str, Any] | None = None,
    ) -> bool:
        state = runtime_state.strategy_state
        normalized_purpose = self._normalize_cycle_purpose(purpose, metadata)
        if normalized_purpose in set(state.get("processed_cycle_purposes") or []):
            return True
        cycle_index, field_name = self._extract_cycle_sequence_target(purpose, metadata)
        if cycle_index <= 0 or not field_name:
            return False
        entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
        entry_status = self._normalize_cycle_order_status(entry.get(field_name))
        return entry_status in self._cycle_finalized_statuses()

    def _blocking_cycle_before_long_add(
        self, runtime_state: RuntimeState, cycle_index: int
    ) -> tuple[int, dict[str, Any]] | None:
        if cycle_index <= 0:
            return None
        for prior_cycle in range(1, cycle_index + 1):
            entry = self._get_cycle_sequence_entry(runtime_state, prior_cycle)
            if prior_cycle == cycle_index:
                if (
                    self._cycle_status_blocks_build(entry.get("long_add_status"))
                    and self._get_second_leg_status(entry) != "FILLED"
                ):
                    return prior_cycle, entry
                continue
            if not bool(entry.get("complete")) and (
                self._cycle_status_blocks_build(entry.get("long_add_status"))
                or self._cycle_status_blocks_build(self._get_second_leg_status(entry))
            ):
                return prior_cycle, entry
        return None

    def _cancel_all_pending_orders(
        self,
        context: StrategyContext,
        snapshot: HedgeSnapshot | None = None,
        runtime_state: RuntimeState | None = None,
    ) -> None:
        canceler = context.cancel_open_orders_by_purpose
        if not canceler:
            return
        cycle_purposes = self._all_cycle_purposes()
        exit_purposes = self._exit_purposes()
        unsettled_orders: list[dict[str, Any]] = []
        if runtime_state is not None:
            unsettled_orders.extend(
                self._strategy_order_summary(order)
                for order in runtime_state.active_orders.values()
                if self._is_unsettled_strategy_order(order) and getattr(order, "purpose", None) in exit_purposes
            )
        if snapshot is not None:
            unsettled_orders.extend(
                self._strategy_order_summary(order)
                for order in snapshot.active_orders
                if self._is_unsettled_strategy_order(order) and getattr(order, "purpose", None) in exit_purposes
            )
        skipped_exit_purposes = sorted(
            {
                str(order.get("purpose") or "")
                for order in unsettled_orders
                if str(order.get("purpose") or "")
            }
        )
        if skipped_exit_purposes:
            context.audit.log_event(
                "fixed_cycle_cancel_pending_skipped_unsettled_final_exit",
                strategy=self.name,
                skipped_exit_purposes=skipped_exit_purposes,
                unsettled_orders=unsettled_orders,
            )
        self._register_expected_exit_order_deactivations(runtime_state, purposes=exit_purposes)
        canceler(cycle_purposes + [purpose for purpose in exit_purposes if purpose not in skipped_exit_purposes])

    def _maybe_finalize_exit_after_leg_fill(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext | None,
        reason: str,
    ) -> None:
        state = runtime_state.strategy_state
        snapshot = runtime_state.last_snapshot
        long_qty = float(snapshot.long_qty) if snapshot else float(state.get("open_long_qty") or 0.0)
        short_qty = float(snapshot.short_qty) if snapshot else float(state.get("open_short_qty") or 0.0)
        long_done = bool(state.get("long_exit_filled")) or long_qty <= 0
        short_done = bool(state.get("short_exit_filled")) or short_qty <= 0
        logger.info(
            "exit_leg_filled",
            {
                "purpose": reason,
                "long_exit_filled": long_done,
                "short_exit_filled": short_done,
                "long_qty": long_qty,
                "short_qty": short_qty,
            },
        )
        active_order_purposes = sorted(
            {
                str(getattr(order, "purpose", "") or "")
                for order in runtime_state.active_orders.values()
                if not self._is_terminal_order_status(getattr(order, "status", None))
            }
            | {
                str(getattr(order, "purpose", "") or "")
                for order in (snapshot.active_orders if snapshot else [])
                if not self._is_terminal_order_status(getattr(order, "status", None))
            }
        )
        missing_long = reason in {
            self.SHORT_SL_EXIT_PURPOSE,
            self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
        } and long_qty > 0 and self.LONG_TP_EXIT_PURPOSE not in active_order_purposes and self.LONG_TP_EXIT_RECOVERY_PURPOSE not in active_order_purposes
        missing_short = reason in {
            self.LONG_TP_EXIT_PURPOSE,
            self.LONG_TP_EXIT_RECOVERY_PURPOSE,
            self.LONG_SL_EXIT_PURPOSE,
        } and short_qty > 0 and self.SHORT_SL_EXIT_PURPOSE not in active_order_purposes and self.SHORT_SL_EXIT_RECOVERY_PURPOSE not in active_order_purposes
        missing_triggered = False
        if missing_long or missing_short:
            block_active = self._is_final_exit_missing_block_active(runtime_state)
            snapshot_for_orders = snapshot or runtime_state.last_snapshot
            if snapshot_for_orders:
                (
                    active_snapshot_order_purposes,
                    active_runtime_order_purposes,
                ) = self._collect_active_strategy_order_purposes(snapshot_for_orders, runtime_state)
            else:
                active_snapshot_order_purposes = []
                active_runtime_order_purposes = []
            expected_missing_purposes: list[str] = []
            if missing_long:
                expected_missing_purposes.extend(
                    [self.LONG_TP_EXIT_PURPOSE, self.LONG_TP_EXIT_RECOVERY_PURPOSE]
                )
            if missing_short:
                expected_missing_purposes.extend(
                    [self.SHORT_SL_EXIT_PURPOSE, self.SHORT_SL_EXIT_RECOVERY_PURPOSE]
                )
            expected_missing_purposes = sorted(set(expected_missing_purposes))
            payload = {
                "reason": reason,
                "missing_long": missing_long,
                "missing_short": missing_short,
                "expected_missing_purposes": expected_missing_purposes,
                "active_runtime_purposes": active_runtime_order_purposes,
                "active_exchange_purposes": active_snapshot_order_purposes,
                "active_order_purposes": active_order_purposes,
                "bot_state": state.get("bot_state"),
                "long_qty": long_qty,
                "short_qty": short_qty,
                "final_long_exit_order_context_present": bool(
                    state.get("final_long_exit_order_context")
                ),
                "final_short_exit_order_context_present": bool(
                    state.get("final_short_exit_order_context")
                ),
                "exit_rebuild_allowed": bool(state.get("exit_rebuild_allowed")),
                "force_exit_rebuild": bool(state.get("force_exit_rebuild")),
                "fresh_restart_required": bool(state.get("fresh_restart_required")),
                "fresh_restart_in_progress": block_active,
                "final_exit_missing_block_until": state.get("final_exit_missing_block_until"),
            }
            log_fn = _log_event if block_active else _log_warning_event
            event_name = (
                "fixed_cycle_final_exit_missing_opposite_exit_blocked"
                if block_active
                else "fixed_cycle_final_exit_missing_opposite_exit"
            )
            log_fn(event_name, payload)
            if not block_active:
                missing_triggered = self._trigger_emergency_flat_for_remaining_positions(
                    snapshot,
                    runtime_state,
                    context,
                    "final_exit_missing_opposite_exit",
                )
        if long_done and short_done:
            unsettled_runtime_orders, unsettled_snapshot_orders = (
                self._collect_unsettled_strategy_orders(snapshot, runtime_state)
                if snapshot
                else ([], [])
            )
            unsettled_final_exit_orders = [
                order
                for order in unsettled_runtime_orders + unsettled_snapshot_orders
                if str(order.get("purpose") or "").upper()
                in {
                    self.LONG_TP_EXIT_PURPOSE,
                    self.LONG_TP_EXIT_RECOVERY_PURPOSE,
                    self.LONG_SL_EXIT_PURPOSE,
                    self.SHORT_TP_EXIT_PURPOSE,
                    self.SHORT_SL_EXIT_PURPOSE,
                    self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
                    self.SHORT_HARD_STOP_PURPOSE,
                }
            ]
            if unsettled_final_exit_orders:
                logger.warning(
                    "final_exit_cleanup_delayed_unsettled_final_orders %s",
                    {
                        "reason": reason,
                        "long_qty": long_qty,
                        "short_qty": short_qty,
                        "unsettled_final_exit_orders": unsettled_final_exit_orders,
                    },
                )
                if context:
                    context.audit.log_event(
                        "final_exit_cleanup_delayed_unsettled_final_orders",
                        strategy=self.name,
                        reason=reason,
                        long_qty=long_qty,
                        short_qty=short_qty,
                        unsettled_final_exit_orders=unsettled_final_exit_orders,
                    )
                self._emit_final_trade_pnl_if_complete_or_fetch(runtime_state, context, reason)
                return
            if not state.get("exit_locked"):
                state["exit_locked"] = True
                state["exit_rebuild_allowed"] = False
                logger.info(
                    "final_exit_completed_both_legs",
                    {
                        "reason": reason,
                        "long_qty": long_qty,
                        "short_qty": short_qty,
                    },
                )
                if context:
                    self._cancel_all_orders_after_exit(runtime_state, context)
                    self._ensure_post_exit_cleanup_required(
                        runtime_state, reason="final_exit_completed_both_legs"
                    )
                    logger.info(
                        "exit_cancel_all_after_both_legs_only",
                        {
                            "reason": reason,
                            "long_qty": long_qty,
                            "short_qty": short_qty,
                        },
                    )
            self._emit_final_trade_pnl_if_complete_or_fetch(runtime_state, context, reason)
            return
        waiting_side = "short" if not short_done else "long"
        if not missing_triggered:
            logger.info(
                "final_exit_waiting_other_leg",
                {
                    "waiting_for": waiting_side,
                    "reason": reason,
                    "long_qty": long_qty,
                    "short_qty": short_qty,
                },
            )

    def _ensure_final_exit_pnl_from_exchange(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext | None,
        reason: str,
    ) -> bool:
        state = runtime_state.strategy_state
        snapshot = runtime_state.last_snapshot
        long_qty = float(snapshot.long_qty) if snapshot else float(state.get("open_long_qty") or 0.0)
        short_qty = float(snapshot.short_qty) if snapshot else float(state.get("open_short_qty") or 0.0)
        if long_qty > 0 or short_qty > 0:
            return bool(state.get("final_long_exit_audited") and state.get("final_short_exit_audited"))
        fetcher = getattr(context.order_manager, "fetch_closed_pnl", None) if context and context.order_manager else None
        if not callable(fetcher):
            return bool(state.get("final_long_exit_audited") and state.get("final_short_exit_audited"))
        trading_stop_context = dict(state.get("final_exit_trading_stop_context") or {})
        trading_stop_flat_reconcile_active = bool(
            state.get("final_exit_trading_stop_active")
            and long_qty <= 0
            and short_qty <= 0
            and trading_stop_context
        )
        if trading_stop_flat_reconcile_active:
            trading_stop_context = self._mark_trading_stop_flat_detected(
                state,
                symbol=str((snapshot.symbol if snapshot else None) or self.config.symbol or ""),
                reason=reason,
                long_qty=long_qty,
                short_qty=short_qty,
            )

        ledger = state.setdefault(
            "audit_pnl_ledger",
            {
                "cycle_long_reduce_pnl": {},
                "cycle_short_tp_pnl": {},
                "cycle_pnl_entries": {},
                "final_long_exit_pnl": None,
                "final_short_exit_pnl": None,
                "total_realized_pnl": 0.0,
            },
        )
        processed_signatures = set(state.get("final_exit_closed_pnl_signatures") or [])
        _, rules, _ = self._resolve_instrument_rules(runtime_state)
        qty_step = float(rules.get("qty_step") or Decimal("0.0001")) if rules else 0.0001
        tick_size = (
            float(rules.get("tick_size"))
            if rules and rules.get("tick_size")
            else float(self.config.price_tick_size or 0.0001)
        )

        def _parse_occurred_at_ms(raw: Any) -> int | None:
            if not raw:
                return None
            try:
                parsed = datetime.fromisoformat(str(raw))
            except (TypeError, ValueError):
                return None
            if parsed.tzinfo is None:
                parsed = parsed.replace(tzinfo=timezone.utc)
            return int(parsed.timestamp() * 1000)

        def _is_required_side(side_key: str) -> bool:
            qty_before = self._safe_float(trading_stop_context.get(f"{side_key}_qty_before"), None)
            if qty_before is None:
                return True
            return float(qty_before) > 1e-12

        def _fetch_for_side(
            *,
            side_key: str,
            state_key: str,
            ledger_key: str,
            audited_key: str,
            expected_side: str,
            purpose: str,
        ) -> None:
            if state.get(audited_key):
                return
            if trading_stop_flat_reconcile_active and not _is_required_side(side_key):
                if ledger.get(ledger_key) is None:
                    ledger[ledger_key] = 0.0
                state[audited_key] = True
                _log_event(
                    "fixed_cycle_final_exit_pnl_fetch_skipped_no_expected_qty",
                    {
                        "reason": reason,
                        "state_key": state_key,
                        "side": side_key,
                        "trade_block_id": trading_stop_context.get("trade_block_id"),
                    },
                )
                return

            order_context = state.get(state_key) or {}
            expected_symbol = str(
                order_context.get("symbol")
                or trading_stop_context.get("symbol")
                or (snapshot.symbol if snapshot else self.config.symbol)
                or ""
            )
            expected_order_id = str(order_context.get("exchange_order_id") or "").strip()
            expected_client_order_id = str(order_context.get("client_order_id") or "").strip()
            expected_qty = float(
                self._safe_float(
                    order_context.get("exec_qty"),
                    self._safe_float(trading_stop_context.get(f"{side_key}_qty_before"), 0.0),
                )
                or 0.0
            )
            expected_fill_price = float(
                self._safe_float(
                    order_context.get("exec_price"),
                    self._safe_float(order_context.get("trigger_price"), 0.0),
                )
                or 0.0
            )
            occurred_at_ms = _parse_occurred_at_ms(order_context.get("occurred_at"))
            set_time_ms = (
                self._safe_int(order_context.get("set_time_ms"), None)
                or self._safe_int(trading_stop_context.get("set_time_ms"), None)
                or occurred_at_ms
            )
            flat_detected_time_ms = (
                self._safe_int(order_context.get("flat_detected_time_ms"), None)
                or self._safe_int(trading_stop_context.get("flat_detected_time_ms"), None)
                or _current_time_ms()
            )
            if trading_stop_flat_reconcile_active and set_time_ms is not None:
                start_time_ms = max(int(set_time_ms) - 120_000, 0)
                end_time_ms = int(flat_detected_time_ms) + 120_000
            else:
                start_time_ms = max(occurred_at_ms - 300_000, 0) if occurred_at_ms is not None else None
                end_time_ms = occurred_at_ms + 900_000 if occurred_at_ms is not None else None

            _log_event(
                "fixed_cycle_final_exit_pnl_fetch_started",
                {
                    "reason": reason,
                    "state_key": state_key,
                    "side": side_key,
                    "symbol": expected_symbol or (snapshot.symbol if snapshot else self.config.symbol),
                    "exchange_order_id": expected_order_id or None,
                    "client_order_id": expected_client_order_id or None,
                    "trade_block_id": trading_stop_context.get("trade_block_id") or order_context.get("trade_block_id"),
                    "trading_stop_flat_reconcile": trading_stop_flat_reconcile_active,
                    "start_time_ms": start_time_ms,
                    "end_time_ms": end_time_ms,
                },
            )
            if not order_context and not trading_stop_flat_reconcile_active:
                _log_event(
                    "fixed_cycle_final_exit_pnl_fetch_missing",
                    {"reason": reason, "state_key": state_key, "missing": "order_context"},
                )
                return

            rows = fetcher(
                expected_symbol or self.config.symbol,
                self.config.category,
                limit=100,
                start_time_ms=start_time_ms,
                end_time_ms=end_time_ms,
            ) or []
            matched = None
            matched_sig = None
            match_source = None
            expected_order_id_is_synthetic = expected_order_id.startswith("trading-stop:")
            for row in rows:
                row_order_id = str(row.get("orderId") or "").strip()
                row_link_id = str(row.get("orderLinkId") or "").strip()
                if expected_order_id and not expected_order_id_is_synthetic and row_order_id == expected_order_id:
                    matched = row
                    matched_sig = self._make_closed_pnl_signature(row)
                    match_source = "orderId"
                    break
                if expected_client_order_id and row_link_id == expected_client_order_id:
                    matched = row
                    matched_sig = self._make_closed_pnl_signature(row)
                    match_source = "orderLinkId"
                    break
            if not matched:
                qty_tolerance = max(qty_step, expected_qty * 0.001, 1e-9)
                price_tolerance = max(tick_size * 2, expected_fill_price * 0.0005, 1e-9)
                matched, matched_sig, _ = self._select_closed_pnl_match(
                    rows,
                    expected_symbol=expected_symbol or self.config.symbol,
                    expected_side=expected_side,
                    expected_qty=expected_qty,
                    expected_fill_price=expected_fill_price,
                    start_time_ms=start_time_ms,
                    end_time_ms=end_time_ms,
                    processed_signatures=processed_signatures,
                    qty_tolerance=qty_tolerance,
                    price_tolerance=price_tolerance,
                )
                if matched:
                    match_source = "fallback_symbol_qty_price_side"
            # Zusätzlicher, Trading-Stop-spezifischer Fallback:
            # Wenn trotz aller Heuristiken kein Match gefunden wurde, aber ein
            # Trading-Stop-Flat-Reconcile aktiv ist und der Bot flat ist,
            # verwende die neueste, noch nicht verarbeitete Row nach Symbol+Side.
            if not matched and trading_stop_flat_reconcile_active and rows:
                latest_candidate: dict[str, Any] | None = None
                latest_sig: str | None = None
                latest_time: int = -1
                expected_symbol_upper = (expected_symbol or self.config.symbol or "").upper()
                for row in rows:
                    row_symbol = str(row.get("symbol") or "").upper()
                    if row_symbol != expected_symbol_upper:
                        continue
                    row_side = str(row.get("side") or "").strip()
                    if row_side != expected_side:
                        continue
                    sig = self._make_closed_pnl_signature(row)
                    if sig in processed_signatures:
                        continue
                    raw_time = row.get("updatedTime") or row.get("createdTime")
                    try:
                        time_ms = int(raw_time)
                    except (TypeError, ValueError):
                        time_ms = 0
                    if time_ms >= latest_time:
                        latest_time = time_ms
                        latest_candidate = row
                        latest_sig = sig
                if latest_candidate is not None and latest_sig is not None:
                    matched = latest_candidate
                    matched_sig = latest_sig
                    match_source = "trading_stop_flat_latest_side"
            closed_pnl = self._safe_float((matched or {}).get("closedPnl"), None)
            if matched and closed_pnl is not None:
                ledger[ledger_key] = float(closed_pnl)
                state[audited_key] = True
                if matched_sig:
                    processed_signatures.add(matched_sig)
                    state["final_exit_closed_pnl_signatures"] = list(processed_signatures)
                resolved_exchange_order_id = (
                    matched.get("orderId")
                    or (None if expected_order_id_is_synthetic else expected_order_id)
                    or f"bybit-closed-pnl:{matched_sig or side_key}:{expected_symbol}"
                )
                resolved_trade_block_id = self._resolve_active_trade_block_id(runtime_state.strategy_state)
                _log_event(
                    "fixed_cycle_final_exit_pnl_fetch_matched",
                    {
                        "reason": reason,
                        "state_key": state_key,
                        "ledger_key": ledger_key,
                        "match_source": match_source,
                        "exchange_order_id": expected_order_id,
                        "client_order_id": expected_client_order_id,
                        "matched_order_id": matched.get("orderId"),
                        "matched_order_link_id": matched.get("orderLinkId"),
                        "closed_pnl": float(closed_pnl),
                        "resolved_trade_block_id": resolved_trade_block_id,
                    },
                )
                self._write_confirmed_order_pnl_history(
                    {
                        "timestamp": datetime.now(timezone.utc).isoformat(),
                        "symbol": expected_symbol or self.config.symbol,
                        "exchange_order_id": resolved_exchange_order_id,
                        "client_order_id": expected_client_order_id or matched.get("orderLinkId"),
                        "purpose": purpose,
                        "closed_pnl": float(closed_pnl),
                        "trade_block_id": resolved_trade_block_id,
                        "cycle_index": None,
                        "pnl_scope": "final_exit",
                        "pnl_source": (
                            "bybit_closed_pnl_flat_reconcile"
                            if trading_stop_flat_reconcile_active
                            else "bybit_closed_pnl"
                        ),
                        "confirmed_via": (
                            "final_exit_flat_reconcile"
                            if trading_stop_flat_reconcile_active
                            else "final_exit_closed_pnl_fetch"
                        ),
                        "side": side_key,
                        "cycle_role": None,
                    },
                    runtime_state=runtime_state,
                )
                return
            _log_event(
                "fixed_cycle_final_exit_pnl_fetch_missing",
                {
                    "reason": reason,
                    "state_key": state_key,
                    "exchange_order_id": expected_order_id,
                    "client_order_id": expected_client_order_id,
                    "rows_count": len(rows),
                    "side": side_key,
                    "trade_block_id": trading_stop_context.get("trade_block_id") or order_context.get("trade_block_id"),
                    "trading_stop_flat_reconcile": trading_stop_flat_reconcile_active,
                    "start_time_ms": start_time_ms,
                    "end_time_ms": end_time_ms,
                },
            )

        _fetch_for_side(
            side_key="long",
            state_key="final_long_exit_order_context",
            ledger_key="final_long_exit_pnl",
            audited_key="final_long_exit_audited",
            expected_side="Sell",
            purpose=self._get_final_long_exit_purpose(),
        )
        _fetch_for_side(
            side_key="short",
            state_key="final_short_exit_order_context",
            ledger_key="final_short_exit_pnl",
            audited_key="final_short_exit_audited",
            expected_side="Buy",
            purpose=self._get_final_short_exit_purpose(),
        )
        long_required = _is_required_side("long")
        short_required = _is_required_side("short")
        final_long_exit_audited = bool(state.get("final_long_exit_audited"))
        final_short_exit_audited = bool(state.get("final_short_exit_audited"))
        if state.get("final_exit_trading_stop_active"):
            if ((not long_required or final_long_exit_audited) and (not short_required or final_short_exit_audited)):
                self._clear_final_exit_trading_stop_state(state)
                _log_event(
                    "fixed_cycle_trading_stop_final_exit_audit_completed",
                    {
                        "reason": reason,
                        "trade_block_id": trading_stop_context.get("trade_block_id"),
                        "long_required": long_required,
                        "short_required": short_required,
                        "final_long_exit_audited": final_long_exit_audited,
                        "final_short_exit_audited": final_short_exit_audited,
                    },
                )
            else:
                _log_event(
                    "fixed_cycle_trading_stop_final_exit_audit_pending",
                    {
                        "reason": reason,
                        "trade_block_id": trading_stop_context.get("trade_block_id"),
                        "long_required": long_required,
                        "short_required": short_required,
                        "final_long_exit_audited": final_long_exit_audited,
                        "final_short_exit_audited": final_short_exit_audited,
                    },
                )
        snapshot_for_reset = snapshot or runtime_state.last_snapshot
        if not (final_long_exit_audited and final_short_exit_audited):
            if (
                snapshot_for_reset
                and snapshot_for_reset.long_qty <= 0
                and snapshot_for_reset.short_qty <= 0
                and not snapshot_for_reset.active_orders
                and not runtime_state.active_orders
                and not state.get("verified_flat_runtime_reset_done")
                and not state.get("final_exit_trading_stop_active")
            ):
                if self._perform_verified_flat_runtime_reset(
                    snapshot=snapshot_for_reset,
                    runtime_state=runtime_state,
                    context=context,
                    reason=f"{reason}_flat_final_exit_missing",
                    allow_unknown_final_pnl=True,
                ):
                    _log_event(
                        "fixed_cycle_pre_entry_flat_state_clean_reset_applied",
                        {
                            "reason": f"{reason}_flat_final_exit_missing",
                            "symbol": snapshot_for_reset.symbol,
                            "long_qty": snapshot_for_reset.long_qty,
                            "short_qty": snapshot_for_reset.short_qty,
                        },
                    )
                    return False
        return bool(state.get("final_long_exit_audited") and state.get("final_short_exit_audited"))

    def _side_realized_by_cycle_pnl(
        self,
        runtime_state: RuntimeState,
        *,
        side: str,
    ) -> tuple[bool, float, str]:
        state = runtime_state.strategy_state
        snapshot = runtime_state.last_snapshot
        ledger = state.get("audit_pnl_ledger") or {}
        if side == "long":
            remaining_qty = (
                float(snapshot.long_qty)
                if snapshot is not None
                else float(state.get("open_long_qty") or 0.0)
            )
            cycle_total = sum(
                float(value or 0.0)
                for value in (ledger.get("cycle_long_reduce_pnl") or {}).values()
            )
            runtime_realized_total = float(runtime_state.realized_long_pnl_total or 0.0)
            confirmed_source = "cycle_long_reduce_confirmed_pnl"
            fallback_source = "runtime_realized_long_pnl_fallback"
        elif side == "short":
            remaining_qty = (
                float(snapshot.short_qty)
                if snapshot is not None
                else float(state.get("open_short_qty") or 0.0)
            )
            cycle_total = sum(
                float(value or 0.0)
                for value in (ledger.get("cycle_short_tp_pnl") or {}).values()
            )
            runtime_realized_total = float(runtime_state.realized_short_pnl_total or 0.0)
            confirmed_source = "cycle_short_tp_confirmed_pnl"
            fallback_source = "runtime_realized_short_pnl_fallback"
        else:
            raise ValueError(f"unsupported side for cycle pnl audit: {side}")

        if remaining_qty > 0:
            return False, 0.0, ""
        if abs(cycle_total) > 1e-12:
            return True, cycle_total, confirmed_source
        if abs(runtime_realized_total) > 1e-12:
            return True, runtime_realized_total, fallback_source
        return False, 0.0, ""

    def _emit_final_trade_pnl_if_complete_or_fetch(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext | None,
        reason: str,
    ) -> bool:
        state = runtime_state.strategy_state
        current_trade_block_id = state.get("trade_block_id")
        last_trade_block_id = state.get("last_trade_block_id")
        if (
            state.get("final_trade_pnl_audited")
            and bool(state.get("last_trade_pnl_complete"))
            and state.get("last_trade_pnl_usdt") is not None
            and current_trade_block_id
            and last_trade_block_id == current_trade_block_id
        ):
            return True
        if (
            state.get("final_trade_pnl_audited")
            and bool(state.get("last_trade_pnl_complete"))
            and state.get("last_trade_pnl_usdt") is not None
            and current_trade_block_id
            and last_trade_block_id != current_trade_block_id
        ):
            _log_event(
                "fixed_cycle_stale_final_pnl_state_ignored",
                {
                    "reason": reason,
                    "trade_block_id": current_trade_block_id,
                    "last_trade_block_id": last_trade_block_id,
                    "last_trade_pnl_usdt": state.get("last_trade_pnl_usdt"),
                },
            )
        ledger = state.get("audit_pnl_ledger") or {}
        final_long_exit_pnl = ledger.get("final_long_exit_pnl")
        final_short_exit_pnl = ledger.get("final_short_exit_pnl")
        if final_long_exit_pnl is None or final_short_exit_pnl is None:
            self._ensure_final_exit_pnl_from_exchange(runtime_state, context, reason)
            ledger = state.get("audit_pnl_ledger") or {}
            final_long_exit_pnl = ledger.get("final_long_exit_pnl")
            final_short_exit_pnl = ledger.get("final_short_exit_pnl")
        if final_long_exit_pnl is None or final_short_exit_pnl is None:
            attempts = int(state.get("final_exit_pnl_fetch_attempts") or 0) + 1
            state["final_exit_pnl_fetch_attempts"] = attempts
            emergency_context = self._in_emergency_final_exit_context(state)
            snapshot_info = runtime_state.last_snapshot
            long_qty = float(snapshot_info.long_qty or 0.0) if snapshot_info else 0.0
            short_qty = float(snapshot_info.short_qty or 0.0) if snapshot_info else 0.0
            if emergency_context:
                reason_tag = state.get("emergency_exit_reason") or "emergency_cleanup_priority"
                if not state.get("final_exit_pnl_fetch_deferred_cleanup"):
                    _log_event(
                        "fixed_cycle_final_exit_pnl_fetch_deferred_cleanup_continues",
                        {
                            "reason": reason_tag,
                            "attempts": attempts,
                            "emergency_exit_reason": reason_tag,
                            "fresh_restart_required": bool(state.get("fresh_restart_required")),
                            "post_exit_cleanup_required": bool(state.get("post_exit_cleanup_required")),
                            "long_qty": long_qty,
                            "short_qty": short_qty,
                        },
                    )
                state["final_exit_pnl_fetch_deferred_cleanup"] = True
                state["last_trade_pnl_pending"] = True
                self._ensure_post_exit_cleanup_required(
                    runtime_state, reason="emergency_cleanup_priority"
                )
                return False
            if attempts >= FINAL_EXIT_PNL_FETCH_MAX_ATTEMPTS:
                if not state.get("final_exit_pnl_fetch_deferred_cleanup"):
                    _log_event(
                        "fixed_cycle_final_exit_pnl_fetch_deferred_cleanup_continues",
                        {
                            "reason": reason,
                            "attempts": attempts,
                            "fresh_restart_required": bool(state.get("fresh_restart_required")),
                            "post_exit_cleanup_required": bool(state.get("post_exit_cleanup_required")),
                            "long_qty": long_qty,
                            "short_qty": short_qty,
                        },
                    )
                state["final_exit_pnl_fetch_deferred_cleanup"] = True
                self._ensure_post_exit_cleanup_required(
                    runtime_state, reason="final_exit_pnl_missing_cleanup"
                )
            return False
        cycle_long_reduce_entries = dict(ledger.get("cycle_long_reduce_pnl") or {})
        cycle_short_tp_entries = dict(ledger.get("cycle_short_tp_pnl") or {})
        cycle_long_reduce_pnl = sum(float(value or 0.0) for value in cycle_long_reduce_entries.values())
        cycle_short_tp_pnl = sum(float(value or 0.0) for value in cycle_short_tp_entries.values())
        long_side_satisfied, long_side_pnl, long_side_source = self._side_realized_by_cycle_pnl(
            runtime_state,
            side="long",
        )
        short_side_satisfied, short_side_pnl, short_side_source = self._side_realized_by_cycle_pnl(
            runtime_state,
            side="short",
        )
        cycle_net_pnl = cycle_long_reduce_pnl + cycle_short_tp_pnl
        final_exit_net_pnl = final_long_exit_pnl + final_short_exit_pnl
        total_trade_pnl = cycle_net_pnl + final_exit_net_pnl
        realized_long_pnl = float(runtime_state.realized_long_pnl_total or 0.0)
        realized_short_pnl = float(runtime_state.realized_short_pnl_total or 0.0)
        trade_block_id = self._resolve_active_trade_block_id(state)
        if not trade_block_id:
            _log_warning_event(
                "fixed_cycle_finalize_missing_trade_block_id",
                {
                    "reason": reason,
                    "trade_block_id": state.get("trade_block_id"),
                    "last_trade_block_id": state.get("last_trade_block_id"),
                },
            )
            return False
        source = "bybit_closed_pnl"
        finalized_at = datetime.now(timezone.utc).isoformat()
        breakdown = {
            "realized_long_pnl_total": realized_long_pnl,
            "realized_short_pnl_total": realized_short_pnl,
            "cycle_long_reduce_pnl": cycle_long_reduce_entries,
            "cycle_short_tp_pnl": cycle_short_tp_entries,
            "cycle_long_reduce_pnl_total": cycle_long_reduce_pnl,
            "cycle_short_tp_pnl_total": cycle_short_tp_pnl,
            "cycle_net_pnl": cycle_net_pnl,
            "final_long_exit_pnl": final_long_exit_pnl,
            "final_short_exit_pnl": final_short_exit_pnl,
            "final_exit_net_pnl": final_exit_net_pnl,
            "total_trade_pnl": total_trade_pnl,
            "source": source,
            "pnl_complete": True,
            "finalized_at": finalized_at,
            "long_side_satisfied": long_side_satisfied,
            "long_side_pnl": long_side_pnl,
            "long_side_source": long_side_source,
            "short_side_satisfied": short_side_satisfied,
            "short_side_pnl": short_side_pnl,
            "short_side_source": short_side_source,
        }
        if (
            abs(realized_long_pnl) > 1e-12 or abs(realized_short_pnl) > 1e-12
        ) and not cycle_long_reduce_entries and not cycle_short_tp_entries:
            _log_event(
                "fixed_cycle_runtime_realized_pnl_not_counted_as_cycle_pnl",
                {
                    "reason": reason,
                    "realized_long_pnl_total": realized_long_pnl,
                    "realized_short_pnl_total": realized_short_pnl,
                    "cycle_long_reduce_entries": cycle_long_reduce_entries,
                    "cycle_short_tp_entries": cycle_short_tp_entries,
                    "final_long_exit_pnl": final_long_exit_pnl,
                    "final_short_exit_pnl": final_short_exit_pnl,
                    "final_exit_net_pnl": final_exit_net_pnl,
                    "total_trade_pnl": total_trade_pnl,
                    "explanation": "runtime realized PnL is not counted as cycle PnL to avoid double counting confirmed final exits",
                },
            )
        _log_event(
            "fixed_cycle_final_exit_pnl_confirmed",
            {
                "reason": reason,
                "trade_block_id": trade_block_id,
                "final_long_exit_pnl": final_long_exit_pnl,
                "final_short_exit_pnl": final_short_exit_pnl,
                "final_long_exit_order_context_present": bool(state.get("final_long_exit_order_context")),
                "final_short_exit_order_context_present": bool(state.get("final_short_exit_order_context")),
                "cycle_net_pnl": cycle_net_pnl,
                "source": source,
            },
        )
        self._persist_last_trade_pnl_summary(
            runtime_state,
            total_trade_pnl=total_trade_pnl,
            breakdown=breakdown,
            source=source,
            pnl_complete=True,
            trade_block_id=trade_block_id,
            finalized_at=finalized_at,
        )
        payload_persist = {
            "symbol": self.config.symbol,
            "trade_block_id": trade_block_id,
            "total_trade_pnl": total_trade_pnl,
            "source": source,
            "pnl_complete": True,
            "finalized_at": finalized_at,
            "breakdown": breakdown,
        }
        _log_event("fixed_cycle_last_trade_pnl_persisted", payload_persist)
        payload_finalized = {
            "symbol": self.config.symbol,
            "trade_block_id": trade_block_id,
            "cycle_long_reduce_pnl_total": cycle_long_reduce_pnl,
            "cycle_short_tp_pnl_total": cycle_short_tp_pnl,
            "cycle_net_pnl": cycle_net_pnl,
            "final_long_exit_pnl": final_long_exit_pnl,
            "final_short_exit_pnl": final_short_exit_pnl,
            "final_exit_net_pnl": final_exit_net_pnl,
            "total_trade_pnl": total_trade_pnl,
            "realized_long_pnl_total": realized_long_pnl,
            "realized_short_pnl_total": realized_short_pnl,
            "source": source,
            "pnl_complete": True,
            "finalized_at": finalized_at,
            "reason": reason,
        }
        _log_event("fixed_cycle_trade_pnl_finalized", payload_finalized)
        state["final_trade_pnl_audited"] = True
        state["current_trade_pnl_state_reset_for_entry"] = False
        self._ensure_post_exit_cleanup_required(runtime_state, reason=reason)
        return True

    def _purge_filled_long_add_orders(
        self, runtime_state: RuntimeState, cycle_index: int, *, purge_stale: bool = False
    ) -> bool:
        symbol = self.config.symbol
        purpose = self._cycle_purpose("long", cycle_index)
        removed_client_ids: list[str] = []
        removed_exchange_ids: list[str] = []
        for client_order_id, order in list(runtime_state.active_orders.items()):
            if getattr(order, "purpose", "") != purpose:
                continue
            removed_client_ids.append(client_order_id)
            exchange_id = getattr(order, "exchange_order_id", None)
            if exchange_id:
                removed_exchange_ids.append(exchange_id)
                runtime_state.exchange_to_client_id.pop(exchange_id, None)
            runtime_state.active_orders.pop(client_order_id, None)
        has_removed = bool(removed_client_ids or removed_exchange_ids)
        if purge_stale:
            if has_removed:
                _log_event(
                    "fixed_cycle_stale_cycle_order_purged",
                    {
                        "symbol": symbol,
                        "cycle_index": cycle_index,
                        "purpose": purpose,
                        "removed_client_ids": removed_client_ids,
                        "removed_exchange_ids": removed_exchange_ids,
                        "reason": "processed_cycle_long_add_cleaned",
                    },
                )
            return has_removed
        if has_removed:
            _log_event(
                "fixed_cycle_cycle_long_reduce_orders_purged_after_fill",
                {
                    "symbol": symbol,
                    "cycle_index": cycle_index,
                    "purpose": purpose,
                    "removed_client_ids": removed_client_ids,
                    "removed_exchange_ids": removed_exchange_ids,
                    "reason": "long_reduce_filled_short_followup_priority",
                },
            )
        return has_removed

    def _load_best_coin_symbol_from_file(self, path: str | Path) -> Optional[dict[str, Any]]:
        file_path = Path(path)
        if not file_path.exists():
            logger.debug("best_coin_file_missing", {"path": str(file_path)})
            return None
        try:
            payload = json.loads(file_path.read_text(encoding="utf-8") or "{}")
        except Exception as exc:
            _log_event(
                "best_coin_file_invalid",
                {"path": str(file_path), "error": str(exc)},
            )
            return None
        if not isinstance(payload, dict):
            logger.info(
                "best_coin_file_invalid",
                {"path": str(file_path), "error": "payload not object"},
            )
            return None
        symbol = payload.get("symbol")
        score = payload.get("score")
        timestamp_raw = payload.get("timestamp")
        reason = payload.get("reason")
        if not symbol or not isinstance(symbol, str):
            logger.info(
                "best_coin_file_invalid",
                {"path": str(file_path), "error": "missing symbol"},
            )
            return None
        if not timestamp_raw or not isinstance(timestamp_raw, str):
            logger.info(
                "best_coin_file_invalid",
                {"path": str(file_path), "error": "missing timestamp"},
            )
            return None
        try:
            timestamp = datetime.fromisoformat(timestamp_raw)
        except ValueError as exc:
            logger.info(
                "best_coin_file_invalid",
                {"path": str(file_path), "error": str(exc)},
            )
            return None
        if timestamp.tzinfo is None:
            timestamp = timestamp.replace(tzinfo=timezone.utc)
        age_minutes = (datetime.now(timezone.utc) - timestamp).total_seconds() / 60
        max_age = float(self.config.best_coin_max_age_minutes or 0) or 0
        if max_age and age_minutes > max_age:
            _log_event(
                "best_coin_file_stale",
                {
                    "path": str(file_path),
                    "symbol": symbol,
                    "score": score,
                    "age_minutes": round(age_minutes, 1),
                },
            )
            return None
        _log_event(
            "best_coin_file_loaded",
            {
                "path": str(file_path),
                "symbol": symbol,
                "score": score,
                "timestamp": timestamp_raw,
                "reason": reason,
            },
        )
        return {
            "symbol": symbol,
            "score": score,
            "timestamp": timestamp,
            "age_minutes": age_minutes,
            "reason": reason,
        }

    def _trigger_restart_script_after_full_exit(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext | None,
        desired_symbol: str,
        active_snapshot_order_purposes: list[str],
        active_runtime_order_purposes: list[str],
        *,
        reason: str,
    ) -> bool:
        state = runtime_state.strategy_state
        if state.get("restart_requested_after_full_exit"):
            return False
        blocking_conditions = {
            "emergency_flat_required": state.get("emergency_flat_required"),
            "emergency_flat_in_progress": state.get("emergency_flat_in_progress"),
            "post_exit_cleanup_required": state.get("post_exit_cleanup_required"),
            "post_exit_cleanup_verified": state.get("post_exit_cleanup_verified"),
            "fresh_restart_required": state.get("fresh_restart_required"),
            "final_pnl_pending": state.get("final_pnl_pending"),
            "final_pnl_context_missing_logged": state.get("final_pnl_context_missing_logged"),
            "final_exit_pnl_fetch_deferred_cleanup": state.get("final_exit_pnl_fetch_deferred_cleanup"),
        }
        active_blockers = [name for name, value in blocking_conditions.items() if value]
        if active_blockers:
            _log_event(
                "fixed_cycle_external_restart_suppressed_runtime_recovery",
                {
                    "symbol": self.config.symbol,
                    "desired_symbol": desired_symbol,
                    "reason": reason,
                    "active_blockers": active_blockers,
                },
            )
            return False
        current_symbol = str(self.config.symbol or "").upper()
        snapshot_symbol = str(snapshot.symbol or "").upper()
        script_path = Path(__file__).resolve().parents[1] / "scripts" / "restart_fixed_cycle.sh"
        payload = {
            "current_config_symbol": current_symbol,
            "snapshot_symbol": snapshot_symbol,
            "desired_symbol": desired_symbol,
            "reason": reason,
            "long_qty": snapshot.long_qty,
            "short_qty": snapshot.short_qty,
            "active_snapshot_order_purposes": active_snapshot_order_purposes,
            "active_runtime_order_purposes": active_runtime_order_purposes,
            "restart_script": str(script_path),
        }
        state["pending_dynamic_symbol"] = desired_symbol
        state["dynamic_symbol_restart_required"] = True
        state["restart_requested_after_full_exit"] = desired_symbol
        _log_event("dynamic_symbol_restart_script_requested", payload)
        if not script_path.exists():
            _log_warning_event(
                "dynamic_symbol_restart_script_missing",
                {**payload, "message": "restart script missing"},
            )
            return False
        try:
            subprocess.Popen([str(script_path)], cwd=str(script_path.parent.parent))
            _log_event(
                "dynamic_symbol_restart_script_spawned",
                {**payload, "message": "restart script spawn requested"},
            )
            return True
        except Exception as exc:
            _log_warning_event(
                "dynamic_symbol_restart_script_failed",
                {**payload, "error": str(exc)},
            )
            return False

    def _compute_next_dynamic_scan_ready_at(self, now: datetime) -> datetime:
        base = now.replace(second=0, microsecond=0)
        minute = base.minute
        if minute < 30:
            slot = base.replace(minute=30)
        else:
            slot = (base + timedelta(hours=1)).replace(minute=0)
        return slot + timedelta(minutes=3)

    def _maybe_start_dynamic_symbol_hold_after_flat(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        reason: str,
    ) -> None:
        state = runtime_state.strategy_state
        if not self.config.dynamic_symbol_enabled:
            return
        if state.get("dynamic_entry_hold_initialized"):
            return
        if snapshot.long_qty > 0 or snapshot.short_qty > 0:
            return
        if snapshot.active_orders:
            return
        active_runtime_orders = [
            order
            for order in runtime_state.active_orders.values()
            if order.status not in {"FILLED", "CANCELED", "CANCELLED", "REJECTED"}
        ]
        if active_runtime_orders:
            return
        now = datetime.now(timezone.utc)
        next_ready = self._compute_next_dynamic_scan_ready_at(now)
        minutes_until_ready = (next_ready - now).total_seconds() / 60
        hold_minutes = float(self.config.dynamic_symbol_hold_minutes or 0) or 0
        state["last_trade_closed_at"] = now.isoformat()
        state["dynamic_entry_hold_initialized"] = True
        if minutes_until_ready <= hold_minutes:
            state["next_dynamic_entry_allowed_at"] = next_ready.isoformat()
            _log_event(
                "dynamic_entry_hold_started",
                {
                    "reason": reason,
                    "now": now.isoformat(),
                    "next_dynamic_entry_allowed_at": next_ready.isoformat(),
                    "minutes_until_ready": round(minutes_until_ready, 2),
                    "dynamic_symbol_hold_minutes": hold_minutes,
                },
            )
        else:
            state["next_dynamic_entry_allowed_at"] = now.isoformat()
            _log_event(
                "dynamic_entry_no_hold_needed",
                {
                    "reason": reason,
                    "now": now.isoformat(),
                    "next_dynamic_entry_allowed_at": now.isoformat(),
                    "next_dynamic_scan_ready_at": next_ready.isoformat(),
                    "minutes_until_ready": round(minutes_until_ready, 2),
                    "dynamic_symbol_hold_minutes": hold_minutes,
                },
            )

    def _dynamic_symbol_entry_gate_allows_entry(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext,
        reason: str,
    ) -> bool:
        if not self.config.dynamic_symbol_enabled:
            return True
        state = runtime_state.strategy_state
        allowed_at_raw = state.get("next_dynamic_entry_allowed_at")
        if not allowed_at_raw:
            return True
        try:
            allowed_at = datetime.fromisoformat(allowed_at_raw)
        except ValueError:
            _log_warning_event(
                "dynamic_entry_allowed_at_invalid",
                {"value": allowed_at_raw},
            )
            return True
        if allowed_at.tzinfo is None:
            allowed_at = allowed_at.replace(tzinfo=timezone.utc)
        now = datetime.now(timezone.utc)
        seconds_remaining = (allowed_at - now).total_seconds()
        if now < allowed_at:
            _log_event(
                "dynamic_entry_waiting_for_next_scan_result",
                {
                    "reason": reason,
                    "now": now.isoformat(),
                    "next_dynamic_entry_allowed_at": allowed_at.isoformat(),
                    "seconds_remaining": max(0.0, round(seconds_remaining, 2)),
                },
            )
            return False
        _log_event(
            "dynamic_entry_allowed_after_hold",
            {
                "reason": reason,
                "now": now.isoformat(),
                "next_dynamic_entry_allowed_at": allowed_at.isoformat(),
                "seconds_past_due": max(0.0, round(-seconds_remaining, 2)),
            },
        )
        return True

    def _maybe_update_symbol_from_best_coin(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext | None,
        reason: str,
    ) -> None:
        if not self.config.dynamic_symbol_enabled:
            return
        best_coin = self._load_best_coin_symbol_from_file(
            self.config.best_coin_file or "logs/best_coin.json"
        )
        if not best_coin:
            _log_event(
                "dynamic_symbol_selection_skipped",
                {
                    "reason": reason,
                    "symbol": self.config.symbol,
                },
            )
            return
        desired_symbol = best_coin["symbol"].upper()
        is_blacklisted, blacklist_entry = self._is_symbol_blacklisted(desired_symbol)
        if is_blacklisted:
            _log_event(
                "dynamic_symbol_blacklisted_symbol_skipped",
                {
                    "symbol": desired_symbol,
                    "reason": blacklist_entry.get("reason") if isinstance(blacklist_entry, dict) else None,
                    "ret_code": blacklist_entry.get("ret_code") if isinstance(blacklist_entry, dict) else None,
                    "ret_msg": blacklist_entry.get("ret_msg") if isinstance(blacklist_entry, dict) else None,
                },
            )
            return
        current_symbol = str(self.config.symbol or "").upper()
        if desired_symbol == current_symbol:
            return
        state = runtime_state.strategy_state
        snapshot = runtime_state.last_snapshot
        cycle_state = state.get("cycle_state") or {}
        snapshot_active_order_count = len(getattr(snapshot, "active_orders", []) or [])
        active_orders = [
            order
            for order in runtime_state.active_orders.values()
            if not self._is_terminal_order_status(getattr(order, "status", None))
        ]
        pending_closed_pnl_count = len(state.get("pending_cycle_closed_pnl_fills") or [])
        long_qty = float(snapshot.long_qty or 0.0) if snapshot else float(state.get("open_long_qty") or 0.0)
        short_qty = float(snapshot.short_qty or 0.0) if snapshot else float(state.get("open_short_qty") or 0.0)
        trade_active = bool(state.get("trade_active"))
        cycle_trade_active = bool(cycle_state.get("trade_active"))
        final_exit_pending = bool(
            state.get("final_long_exit_order_context") or state.get("final_short_exit_order_context")
        )
        block_reasons: list[str] = []
        if long_qty > 0:
            block_reasons.append("long_qty_open")
        if short_qty > 0:
            block_reasons.append("short_qty_open")
        if trade_active:
            block_reasons.append("trade_active")
        if cycle_trade_active:
            block_reasons.append("cycle_trade_active")
        if active_orders:
            block_reasons.append("active_orders_present")
        if snapshot_active_order_count > 0:
            block_reasons.append("snapshot_active_orders_present")
        if pending_closed_pnl_count > 0:
            block_reasons.append("pending_closed_pnl_fills")
        if state.get("refill_pending"):
            block_reasons.append("refill_pending")
        if state.get("refill_in_progress"):
            block_reasons.append("refill_in_progress")
        if final_exit_pending:
            block_reasons.append("final_exit_context_present")
        if state.get("cycle_waiting_for_short_tp"):
            block_reasons.append("cycle_waiting_for_short_tp")
        if state.get("long_add_pending"):
            block_reasons.append("long_add_pending")
        if int(state.get("short_tp_pending_cycle") or 0) > 0:
            block_reasons.append("short_tp_pending_cycle")
        if block_reasons:
            _log_event(
                "fixed_cycle_dynamic_symbol_switch_blocked_active_trade",
                {
                    "current_symbol": current_symbol,
                    "desired_symbol": desired_symbol,
                    "long_qty": long_qty,
                    "short_qty": short_qty,
                    "active_order_count": len(active_orders),
                    "snapshot_active_order_count": snapshot_active_order_count,
                    "trade_active": trade_active,
                    "cycle_trade_active": cycle_trade_active,
                    "pending_closed_pnl_count": pending_closed_pnl_count,
                    "refill_pending": bool(state.get("refill_pending")),
                    "refill_in_progress": bool(state.get("refill_in_progress")),
                    "reason": ",".join(block_reasons),
                },
            )
            return
        _log_event(
            "fixed_cycle_dynamic_symbol_switch_allowed_flat",
            {
                "current_symbol": current_symbol,
                "desired_symbol": desired_symbol,
                "long_qty": long_qty,
                "short_qty": short_qty,
                "active_order_count": len(active_orders),
                "snapshot_active_order_count": snapshot_active_order_count,
                "pending_closed_pnl_count": pending_closed_pnl_count,
                "reason": reason,
            },
        )
        self.config.symbol = desired_symbol
        reselect_reason = state.pop("dynamic_symbol_reselection_reason", None)
        if reselect_reason and desired_symbol != current_symbol:
            _log_event(
                "dynamic_symbol_reselected_after_reject",
                {
                    "new_symbol": desired_symbol,
                    "old_symbol": current_symbol,
                    "reason": reselect_reason,
                },
            )
        _log_event(
            "dynamic_symbol_selected_for_fresh_entry",
            {
                "reason": reason,
                "new_symbol": desired_symbol,
                "score": best_coin.get("score"),
            },
        )

    def _reset_exit_state_for_new_structure(
        self,
        runtime_state: RuntimeState,
        reason: str,
    ) -> None:
        state = runtime_state.strategy_state
        snapshot = runtime_state.last_snapshot
        long_qty = float(snapshot.long_qty) if snapshot else float(state.get("open_long_qty") or 0.0)
        short_qty = float(snapshot.short_qty) if snapshot else float(state.get("open_short_qty") or 0.0)
        state["exit_locked"] = False
        state["long_exit_filled"] = False
        state["short_exit_filled"] = False
        state["short_exit_recovery_submitted"] = False
        state["long_exit_recovery_submitted"] = False
        state["exit_recovery_marker"] = False
        state["force_exit_rebuild"] = True
        init_payload = initialize_cycle_sequence_state(state, self._sequence_config)
        clear_cycle_states = reason == "initial_entry_confirmed"
        if clear_cycle_states:
            state["processed_cycle_purposes"] = []
            state.pop("completed_cycle_purposes", None)
            state["cycle_completed_count"] = 0
            state["cycle_pair_count"] = 0
            state["current_effective_cycle"] = 0
            state["current_long_cycle_index"] = 0
            state["current_short_cycle_index"] = 0
            state["last_refill_completed_cycle_index"] = None
        self._clear_second_leg_followup_residuals(
            runtime_state,
            clear_cycle_states=clear_cycle_states,
        )
        _log_event(
            "fixed_cycle_sequence_state_initialized",
            {
                "symbol": self.config.symbol,
                "category": self.config.category,
                **init_payload,
            },
        )
        self._set_final_exit_missing_block(
            runtime_state, self.FINAL_EXIT_MISSING_REBUILD_BLOCK_SEC
        )
        logger.info(
            "exit_state_reset_for_new_structure",
            {
                "reason": reason,
                "long_qty": long_qty,
                "short_qty": short_qty,
            },
        )

    def _blacklist_file_path(self) -> Path:
        """
        Resolve the blacklist file path in the same way as the runtime:
        - Absolute path rooted at the project root (two levels above this file)
        - Grouped by bot_name / strategy_side into long vs short hedge groups.
        """
        from pathlib import Path as _Path  # local import to avoid cycles at module import time

        project_root = _Path(__file__).resolve().parents[1]
        bot_name = getattr(self.config, "bot_name", None)
        strategy_side = getattr(self.config, "strategy_side", None)

        if (isinstance(bot_name, str) and bot_name.startswith("short_bot_")) or strategy_side == "short":
            base = project_root / "live_bots" / "short_hedge_bot"
        else:
            base = project_root / "live_bots" / "100_50_hedge_bot"

        path = base / "state" / "blacklisted_symbols.json"
        path.parent.mkdir(parents=True, exist_ok=True)
        return path

    def _load_blacklisted_symbols(self) -> dict[str, dict[str, Any]]:
        path = self._blacklist_file_path()
        if not path.exists():
            return {}
        try:
            payload = json.loads(path.read_text(encoding="utf-8") or "{}")
        except Exception:
            return {}
        if not isinstance(payload, dict):
            return {}
        return payload

    def _is_symbol_blacklisted(self, symbol: str) -> tuple[bool, dict[str, Any] | None]:
        normalized = str(symbol or "").upper()
        blacklist = self._load_blacklisted_symbols()
        entry = blacklist.get(normalized)
        return (entry is not None, entry)

    def _reset_current_trade_pnl_state(self, runtime_state: RuntimeState, *, reason: str) -> None:
        state = runtime_state.strategy_state
        previous_trade_block_id = state.get("trade_block_id")
        keys_to_reset_or_pop = [
            "final_trade_pnl_audited",
            "final_long_exit_audited",
            "final_short_exit_audited",
            "final_long_exit_order_context",
            "final_short_exit_order_context",
            "final_exit_trading_stop_context",
            "final_exit_closed_pnl_signatures",
            "audit_processed_exit_fill_ids",
            "audit_completed_cycle_indices",
            "processed_pnl_exec_ids",
            "processed_pnl_exec_ids_order",
            "flat_waiting_order_cleanup_logged",
            "flat_waiting_final_pnl_logged",
            "flat_final_pnl_ready_logged",
            "final_pnl_context_missing_logged",
            "restart_delayed_pending_final_pnl_logged",
            "final_exit_context_missing_but_flat_confirmed",
            "final_exit_fallback_reason",
            "final_exit_fallback_applied_at",
        ]

        for key in keys_to_reset_or_pop:
            state.pop(key, None)

        state["audit_pnl_ledger"] = {
            "cycle_long_reduce_pnl": {},
            "cycle_short_tp_pnl": {},
            "cycle_pnl_entries": {},
            "final_long_exit_pnl": None,
            "final_short_exit_pnl": None,
            "total_realized_pnl": 0.0,
        }
        runtime_state.realized_long_pnl_total = 0.0
        runtime_state.realized_short_pnl_total = 0.0
        # Start a fresh trade block and timestamp; clear any time-distance refill skip marker.
        state["trade_block_id"] = str(uuid4())
        state["trade_started_at"] = datetime.now(timezone.utc).isoformat()
        state.pop("skip_next_cycle_refill_after_time_distance", None)
        state.pop("time_distance_refill_triggered_key", None)
        state["recovery_midpoint_used_for_cycle_index"] = 0
        state.pop("normal_cycle_second_leg_split_stage_count", None)
        state.pop("normal_cycle_second_leg_split_filled_stages", None)
        _log_event(
            "fixed_cycle_current_trade_pnl_state_reset",
            {
                "reason": reason,
                "previous_trade_block_id": previous_trade_block_id,
                "trade_block_id": state.get("trade_block_id"),
                "last_trade_block_id": state.get("last_trade_block_id"),
            },
        )

    def _cancel_all_orders_after_exit(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> None:
        order_manager = context.order_manager
        symbol = context.symbol or self.config.symbol
        category = context.category or self.config.category
        canceled = False
        if order_manager and symbol:
            try:
                canceled = order_manager.cancel_all_orders(symbol=symbol, category=category)
            except Exception as exc:
                logger.warning(
                    "exit_cancel_all_failed",
                    {
                        "symbol": symbol,
                        "category": category,
                        "error": str(exc),
                    },
                )
        self._purge_active_orders(runtime_state, self._all_cycle_purposes() + self._exit_purposes())
        _audit_calc(
            "exit_cancel_all",
            {
                "symbol": symbol,
                "category": category,
                "cancel_success": canceled,
            },
        )

    def _purge_active_orders(
        self,
        runtime_state: RuntimeState,
        purposes: list[str],
    ) -> None:
        removed = 0
        skipped = 0
        exit_purposes = set(self._exit_purposes())
        for client_id, order in list(runtime_state.active_orders.items()):
            if order.purpose not in purposes:
                continue
            if order.purpose in exit_purposes and self._is_unsettled_strategy_order(order):
                skipped += 1
                logger.info(
                    "purge_active_orders_skipped_unsettled_exit %s",
                    {
                        "client_order_id": client_id,
                        "exchange_order_id": order.exchange_order_id,
                        "purpose": order.purpose,
                        "status": order.status,
                        "filled_qty": order.filled_qty,
                        "remaining_qty": order.remaining_qty,
                    },
                )
                continue
            runtime_state.active_orders.pop(client_id, None)
            removed += 1
            if order.exchange_order_id:
                runtime_state.exchange_to_client_id.pop(order.exchange_order_id, None)
        logger.info(
            "purged_active_orders",
            {
                "removed": removed,
                "skipped": skipped,
                "purposes": purposes,
            },
        )

    def _cancel_refill_exit_orders(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext,
        state: dict[str, Any],
    ) -> bool:
        """Cancel exit orders and keep the shared guard reusable for any bot.

        Future short-bot variants should override `_exit_purposes()` rather than this helper.
        """
        symbol = context.symbol or self.config.symbol
        category = context.category or self.config.category
        exit_purposes = set(self._exit_purposes())
        active_exit_orders = [
            order
            for order in runtime_state.active_orders.values()
            if (
                order.purpose in exit_purposes
                or self._is_refill_stale_cycle_reduce_purpose(order.purpose)
            )
            and self._is_unsettled_strategy_order(order)
        ]
        active_order_purposes = sorted(
            {order.purpose for order in runtime_state.active_orders.values() if order.purpose}
        )

        # Partition active exit orders into Trading-Stop-logische Exit-Orders und
        # normale, über /v5/order/cancel stornierbare Orders. Trading-Stop-Orders
        # besitzen bewusst keine exchange_order_id und dürfen den Refill nicht über
        # den normalen Cancel-Pfad blockieren.
        logical_trading_stop_orders: list[Any] = []
        cancelable_exit_orders: list[Any] = []
        for order in active_exit_orders:
            metadata = dict(getattr(order, "metadata", None) or {})
            is_trading_stop_logical = bool(metadata.get("trading_stop_api")) and not str(
                getattr(order, "exchange_order_id", "") or ""
            ).strip()
            if is_trading_stop_logical:
                logical_trading_stop_orders.append(order)
            else:
                cancelable_exit_orders.append(order)

        base_payload = {
            "symbol": symbol,
            "category": category,
            "active_exit_order_count": len(active_exit_orders),
            "active_order_purposes": active_order_purposes,
            "refill_exit_orders_cancel_required": bool(state.get("refill_exit_orders_cancel_required")),
        }

        # Trading-Stop-logische Exit-Orders werden immer lokal aus dem
        # Runtime-State entfernt, dürfen aber den Refill-Guard nicht daran
        # hindern, echte Exchange-Orders normal zu canceln.
        if logical_trading_stop_orders:
            removed_client_ids: list[str] = []
            removed_exchange_ids: list[str] = []
            removed_purposes: set[str] = set()
            for order in logical_trading_stop_orders:
                client_id = getattr(order, "client_order_id", None)
                if client_id:
                    if runtime_state.active_orders.pop(client_id, None) is not None:
                        removed_client_ids.append(str(client_id))
                exchange_order_id = getattr(order, "exchange_order_id", None)
                if exchange_order_id:
                    if runtime_state.exchange_to_client_id.pop(exchange_order_id, None) is not None:
                        removed_exchange_ids.append(str(exchange_order_id))
                purpose = getattr(order, "purpose", None)
                if purpose:
                    removed_purposes.add(str(purpose))

            payload = {
                **base_payload,
                "logical_exit_order_count": len(logical_trading_stop_orders),
                "removed_client_order_ids": removed_client_ids,
                "removed_exchange_order_ids": removed_exchange_ids,
                "removed_purposes": sorted(removed_purposes),
                "has_cancelable_exit_orders": bool(cancelable_exit_orders),
            }
            _log_event("fixed_cycle_refill_trading_stop_logical_exit_orders_removed", payload)

            # Wenn ausschließlich Trading-Stop-logische Exit-Orders existierten,
            # ist der Cancel-Guard nach der lokalen Bereinigung vollständig
            # erledigt.
            if not cancelable_exit_orders:
                state["refill_exit_orders_cancel_required"] = False
                _log_event(
                    "fixed_cycle_refill_exit_cancel_completed_after_logical_trading_stop_cleanup",
                    payload,
                )
                return True

        # Keine aktiven Exit-Orders mehr nach der Partitionierung: Refill darf
        # ohne zusätzliche Cancel-Schritte fortgesetzt werden.
        if not cancelable_exit_orders:
            _log_event("fixed_cycle_refill_exit_order_cancel_noop", base_payload)
            state["refill_exit_orders_cancel_required"] = False
            return True
        order_manager = context.order_manager
        for order in cancelable_exit_orders:
            payload = {
                **base_payload,
                "purpose": order.purpose,
                "client_order_id": order.client_order_id,
                "exchange_order_id": order.exchange_order_id,
            }
            exchange_order_id = str(order.exchange_order_id or "").strip()
            if not exchange_order_id:
                _log_event("fixed_cycle_refill_exit_order_cancel_missing_exchange_id", payload)
                return False
            if not order_manager or not symbol:
                _log_event(
                    "fixed_cycle_refill_exit_order_cancel_failed",
                    {**payload, "error": "order_manager_missing"},
                )
                return False
            _log_event("fixed_cycle_refill_exit_order_cancel_attempt", payload)
            try:
                canceled = order_manager.cancel_order(
                    exchange_order_id, symbol=symbol, category=category
                )
            except Exception as exc:
                _log_event(
                    "fixed_cycle_refill_exit_order_cancel_failed",
                    {**payload, "error": str(exc)},
                )
                return False
            if not canceled:
                _log_event(
                    "fixed_cycle_refill_exit_order_cancel_failed",
                    {**payload, "error": "cancel_after_submit_failed"},
                )
                return False
            _log_event("fixed_cycle_refill_exit_order_cancel_success", payload)
            runtime_state.active_orders.pop(order.client_order_id, None)
            if order.exchange_order_id:
                runtime_state.exchange_to_client_id.pop(order.exchange_order_id, None)
        state["refill_exit_orders_cancel_required"] = False
        _log_event(
            "fixed_cycle_refill_exit_order_cancel_done",
            {
                **base_payload,
                "initial_exit_order_count": len(active_exit_orders),
            },
        )
        return True

    def _is_fixed_cycle_exchange_order(self, order: dict[str, Any] | None) -> bool:
        if not order:
            return False
        for key in ("orderLinkId", "order_link_id", "clientOrderId", "client_order_id"):
            value = str(order.get(key) or "").strip()
            if value.startswith("fixed_cycle-"):
                return True
        return False

    def _refresh_short_reduce_closed_pnl(
        self,
        *,
        fill_event: FillEvent,
        runtime_state: RuntimeState,
        context: StrategyContext,
        cycle_index: int,
    ) -> bool:
        self._enrich_fill_event_for_confirmed_pnl(fill_event)
        if cycle_index <= 0:
            cycle_index = cycle_index_from_purpose(fill_event.purpose or "")
        metadata = fill_event.metadata or {}
        processed_key = "processed_closed_pnl_signatures"
        cycle_state = self._ensure_cycle_state(runtime_state)
        processed_signatures = set(cycle_state.get(processed_key) or [])

        order_id = str(
            (fill_event.exchange_order_id or fill_event.client_order_id or "").strip()
        )
        fetcher = getattr(context.order_manager, "fetch_closed_pnl", None) if context.order_manager else None
        if not order_id or not callable(fetcher):
            return False
        fetch_symbol = self._active_trade_symbol(runtime_state.last_snapshot, runtime_state, fill_event=fill_event)

        occurred_at_ms = (
            int(fill_event.occurred_at.timestamp() * 1000)
            if getattr(fill_event, "occurred_at", None)
            else None
        )
        start_time_ms = max(0, occurred_at_ms - 300_000) if occurred_at_ms is not None else None
        end_time_ms = (
            occurred_at_ms + 900_000 if occurred_at_ms is not None else None
        )
        if fetch_symbol and fetch_symbol != str(self.config.symbol or "").upper():
            _log_event(
                "fixed_cycle_closed_pnl_retry_uses_fill_symbol",
                {
                    "expected_order_id": order_id,
                    "cycle_index": cycle_index,
                    "fill_symbol": fetch_symbol,
                    "config_symbol": str(self.config.symbol or "").upper(),
                    "purpose": fill_event.purpose,
                },
            )
        rows = fetcher(
            fetch_symbol,
            self.config.category,
            limit=100,
            start_time_ms=start_time_ms,
        ) or []

        if not rows:
            return False

        symbol, rules, _ = self._resolve_instrument_rules(
            runtime_state,
            symbol_override=fetch_symbol,
        )
        expected_qty = float(fill_event.exec_qty or 0.0)
        expected_price = float(fill_event.exec_price or 0.0)
        expected_side = self._expected_bybit_closed_pnl_side(
            {
                "purpose": fill_event.purpose,
                "cycle_role": metadata.get("cycle_role", "short_reduce"),
            }
        )
        qty_step = float(rules.get("qty_step") or Decimal("0.0001")) if rules else float(Decimal("0.0001"))
        tick_size = float(
            rules.get("tick_size")
            if rules and rules.get("tick_size")
            else Decimal(str(self.config.price_tick_size or 0.0001))
        )
        qty_tolerance = max(qty_step, expected_qty * 0.001)
        price_tolerance = max(tick_size * 2, expected_price * 0.0005)

        matched = None
        matched_sig = None
        match_source = None
        for row in rows:
            if (
                str(row.get("orderId") or "").strip() == order_id
                and str(row.get("symbol") or "").upper() == symbol.upper()
            ):
                matched = row
                matched_sig = self._make_closed_pnl_signature(row)
                match_source = "strict_order_id"
                break
        if not matched:
            matched, matched_sig, score = self._select_closed_pnl_match(
                rows,
                expected_symbol=symbol,
                expected_side=expected_side,
                expected_qty=expected_qty,
                expected_fill_price=expected_price,
                start_time_ms=start_time_ms,
                end_time_ms=end_time_ms,
                processed_signatures=processed_signatures,
                qty_tolerance=qty_tolerance,
                price_tolerance=price_tolerance,
            )
            if matched and matched_sig:
                match_source = "robust_signature_match"
        if not matched:
            return False
        if matched_sig in processed_signatures:
            return False
        processed_signatures.add(matched_sig)
        cycle_state[processed_key] = list(processed_signatures)[-200:]

        closed_pnl = self._safe_float(matched.get("closedPnl"), None)
        if closed_pnl is None:
            return False
        metadata["short_reduce_closed_pnl"] = closed_pnl
        metadata["short_closed_pnl"] = closed_pnl
        metadata["closed_pnl"] = closed_pnl
        metadata["confirmed_closed_pnl"] = closed_pnl
        metadata["closed_pnl_updated_time"] = self._safe_int(
            matched.get("updatedTime") or matched.get("createdTime")
        )
        metadata["closed_pnl_source"] = match_source or "closed_pnl"
        metadata["cycle_index"] = int(metadata.get("cycle_index") or cycle_index)
        metadata.setdefault("cycle_role", "short_reduce")
        fill_event.metadata = metadata
        fill_event.confirmed_pnl = closed_pnl
        self._apply_confirmed_realized_pnl(
            runtime_state=runtime_state,
            client_order_id=fill_event.client_order_id,
            confirmed_pnl=closed_pnl,
            side="short",
            exec_id=fill_event.exec_id,
            purpose=fill_event.purpose,
            position_idx=2,
            cycle_role="short_reduce",
        )
        cycle_entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
        cycle_entry["long_add_confirmed_pnl"] = float(closed_pnl)
        cycle_entry["long_add_loss_usdt"] = max(-float(closed_pnl), 0.0)
        cycle_entry["short_followup_pnl_source"] = match_source or "confirmed_closed_pnl"
        if (
            str(fill_event.status or "").upper() == "FILLED"
            and self._get_first_leg_cycle_role() == "short_reduce"
            and self._get_second_leg_cycle_role() == "long_reduce"
        ):
            state = runtime_state.strategy_state
            cycle_state = self._ensure_cycle_state(runtime_state)
            sequence_state = get_cycle_sequence_state(state, self._sequence_config)
            expected_first_leg_purpose = self._normalize_cycle_purpose(
                self._get_first_leg_purpose(cycle_index),
                {
                    "cycle_index": cycle_index,
                    "cycle_role": self._get_first_leg_cycle_role(),
                },
            )
            current_purpose = self._normalize_cycle_purpose(
                fill_event.purpose,
                {
                    "cycle_index": cycle_index,
                    **metadata,
                },
            )
            if (
                current_purpose == expected_first_leg_purpose
                and int(sequence_state.get("active_cycle_index") or 0) == cycle_index
                and str(sequence_state.get("cycle_step") or "") == STEP_WAITING_FOR_PAIR_FIRST_LEG
            ):
                sequence_result = advance_cycle_sequence_after_fill(
                    fill_event.purpose or "",
                    state,
                    self._sequence_config,
                )
                event_type = sequence_result.get("type")
                event_name = {
                    "step_transition": "fixed_cycle_cycle_step_transition",
                    "pair_completed": "fixed_cycle_cycle_pair_completed",
                    "unexpected_fill": "fixed_cycle_sequence_unexpected_fill_detected",
                }.get(event_type)
                if event_name:
                    _log_event(
                        event_name,
                        {
                            "symbol": fetch_symbol or self.config.symbol,
                            "category": self.config.category,
                            **sequence_result.get("payload", {}),
                            "reason": "confirmed_short_reduce_closed_pnl",
                        },
                    )
            if (
                not self._get_second_leg_waiting(state, cycle_state)
                or self._get_second_leg_pending_cycle(state, cycle_state) != cycle_index
            ):
                self._set_second_leg_waiting_state(
                    state,
                    cycle_state,
                    waiting=True,
                    cycle_index=cycle_index,
                )
                self._set_first_leg_pending(state, cycle_state, False)
                state["pending_short_cycle_index"] = cycle_index
                cycle_state["pending_short_cycle_index"] = cycle_index
                state["cycle_long_add_filled"] = True
                state["cycle_short_tp_filled"] = False
                _log_event(
                    "fixed_cycle_long_reduce_unblocked_after_confirmed_pnl",
                    {
                        "cycle_index": cycle_index,
                        "purpose": self._get_second_leg_purpose(cycle_index),
                        "confirmed_short_reduce_pnl": closed_pnl,
                        "pending_cycle_loss_usdt": float(
                            state.get("pending_cycle_loss_usdt") or 0.0
                        ),
                    },
                )
            self._persist_cycle_sequence_state(runtime_state)

        _log_event(
            "fixed_cycle_short_reduce_pnl_confirmed",
            {
                "symbol": fetch_symbol,
                "cycle_index": cycle_index,
                "order_id": order_id,
                "closed_pnl": closed_pnl,
                "match_source": match_source,
            },
        )
        self._write_confirmed_order_pnl_history(
            {
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "symbol": fetch_symbol,
                "exchange_order_id": matched.get("orderId") or fill_event.exchange_order_id or order_id,
                "client_order_id": fill_event.client_order_id,
                "purpose": fill_event.purpose,
                "closed_pnl": closed_pnl,
                "trade_block_id": self._resolve_active_trade_block_id(runtime_state.strategy_state),
                "cycle_index": cycle_index,
                "pnl_scope": "cycle",
                # Split-/Stage-/Role-Metadata auch für History-Match-Weg durchreichen.
                "parent_purpose": (fill_event.metadata or {}).get("parent_second_leg_purpose")
                or (fill_event.metadata or {}).get("parent_purpose"),
                "parent_second_leg_purpose": (fill_event.metadata or {}).get("parent_second_leg_purpose"),
                "stage_index": (fill_event.metadata or {}).get("stage_index"),
                "stage_count": (fill_event.metadata or {}).get("stage_count"),
                "split_index": (fill_event.metadata or {}).get("split_stage_index"),
                "split_count": (fill_event.metadata or {}).get("split_stage_count"),
                "cycle_role": (fill_event.metadata or {}).get("cycle_role"),
                "first_leg_cycle_role": (fill_event.metadata or {}).get("first_leg_cycle_role"),
                "second_leg_cycle_role": (fill_event.metadata or {}).get("second_leg_cycle_role"),
                "order_source": (fill_event.metadata or {}).get("source"),
                "qty": float(fill_event.exec_qty or 0.0) if fill_event.exec_qty is not None else None,
                "exec_qty": float(fill_event.exec_qty or 0.0) if fill_event.exec_qty is not None else None,
                "side": fill_event.side,
                "fill_price": float(fill_event.exec_price or 0.0) if fill_event.exec_price is not None else None,
                "avg_fill_price": (
                    float((fill_event.metadata or {}).get("confirmed_closed_avg_price") or 0.0)
                    if (fill_event.metadata or {}).get("confirmed_closed_avg_price") is not None
                    else None
                ),
            },
            runtime_state=runtime_state,
        )
        _log_event(
            "closed_pnl_row_matched",
            {
                "order_id": order_id,
                "cycle_index": cycle_index,
                "symbol": fetch_symbol,
                "closed_pnl": closed_pnl,
                "match_source": match_source,
            },
        )
        return True

    def _ensure_post_exit_cleanup_required(
        self, runtime_state: RuntimeState, *, reason: str | None = None
    ) -> None:
        state = runtime_state.strategy_state
        now_iso = datetime.now(timezone.utc).isoformat()
        state["post_exit_cleanup_required"] = True
        state["post_exit_cleanup_verified"] = False
        state["post_exit_cleanup_in_progress"] = False
        state["post_exit_cleanup_attempts"] = 0
        state["post_exit_cleanup_started_at"] = now_iso
        state["post_exit_cleanup_verified_at"] = None
        _log_event(
            "fixed_cycle_post_exit_cleanup_required",
            {
                "symbol": self.config.symbol,
                "reason": reason or "final_exit",
                "trade_block_id": state.get("trade_block_id"),
                "last_trade_block_id": state.get("last_trade_block_id"),
            },
        )

    def _post_exit_cleanup_pending(self, runtime_state: RuntimeState) -> bool:
        state = runtime_state.strategy_state
        return bool(state.get("post_exit_cleanup_required") and not state.get("post_exit_cleanup_verified"))

    def _attempt_post_exit_cleanup(
        self, snapshot: HedgeSnapshot, runtime_state: RuntimeState, context: StrategyContext
    ) -> bool:
        state = runtime_state.strategy_state
        if not self._post_exit_cleanup_pending(runtime_state):
            return True
        state["post_exit_cleanup_attempts"] = int(state.get("post_exit_cleanup_attempts") or 0) + 1
        state["post_exit_cleanup_in_progress"] = True
        if not state.get("post_exit_cleanup_started_at"):
            state["post_exit_cleanup_started_at"] = datetime.now(timezone.utc).isoformat()
        attempts = int(state.get("post_exit_cleanup_attempts") or 0)

        symbol = context.symbol or self.config.symbol
        category = context.category or self.config.category
        cancel_success = False
        order_manager = context.order_manager

        if order_manager and symbol:
            try:
                cancel_success = order_manager.cancel_all_orders(symbol=symbol, category=category)
            except Exception as exc:
                logger.warning(
                    "post_exit_cleanup_cancel_failed",
                    {
                        "symbol": symbol,
                        "category": category,
                        "error": str(exc),
                    },
                )
        _log_event(
            "fixed_cycle_post_exit_cleanup_cancel_requested",
            {
                "symbol": symbol,
                "category": category,
                "attempt": attempts,
                "cancel_success": cancel_success,
            },
        )

        open_orders: list[dict[str, Any]] = []
        fetch_failed = False
        if order_manager and symbol:
            try:
                open_orders = order_manager.fetch_open_orders(symbol=symbol, category=category) or []
            except Exception as exc:
                fetch_failed = True
                logger.warning(
                    "post_exit_cleanup_fetch_failed",
                    {
                        "symbol": symbol,
                        "category": category,
                        "error": str(exc),
                    },
                )
        else:
            fetch_failed = True
        if fetch_failed:
            _log_event(
                "fixed_cycle_post_exit_cleanup_failed",
                {
                    "symbol": symbol,
                    "category": category,
                    "attempt": attempts,
                    "reason": "fetch_failed",
                },
            )

        remaining_fixed_cycle_orders = [
            order for order in open_orders if self._is_fixed_cycle_exchange_order(order)
        ]
        snapshot_purposes, runtime_purposes = self._collect_active_strategy_order_purposes(
            snapshot, runtime_state
        )
        long_qty = float(snapshot.long_qty or 0.0)
        short_qty = float(snapshot.short_qty or 0.0)

        # State-basierter Root-Fix: Wenn der Bot sicher flat ist, die Exchange
        # keine aktiven fixed_cycle-Orders mehr kennt und nur noch lokale
        # Strategy-Exit-Orders übrig sind, dürfen diese im Runtime-State
        # bereinigt werden.
        if (
            not fetch_failed
            and long_qty == 0.0
            and short_qty == 0.0
            and not remaining_fixed_cycle_orders
            and (snapshot_purposes or runtime_purposes)
        ):
            snapshot_purposes_before = list(snapshot_purposes)
            runtime_purposes_before = list(runtime_purposes)
            remaining_exchange_orders_before = len(remaining_fixed_cycle_orders)
            if self._force_cleanup_flat_final_exit_orders(
                snapshot,
                runtime_state,
                context,
                reason="post_exit_cleanup_final_exit_only_state_cleanup",
            ):
                _log_event(
                    "fixed_cycle_flat_unsettled_exit_orders_cleared_state_basis",
                    {
                        "symbol": symbol,
                        "category": category,
                        "long_qty": long_qty,
                        "short_qty": short_qty,
                        "snapshot_purposes_before": snapshot_purposes_before,
                        "runtime_purposes_before": runtime_purposes_before,
                        "remaining_exchange_orders_before": remaining_exchange_orders_before,
                        "reason": "post_exit_cleanup_final_exit_only_state_cleanup",
                    },
                )
                snapshot_purposes, runtime_purposes = self._collect_active_strategy_order_purposes(
                    snapshot, runtime_state
                )

        clean_snapshot = (
            not snapshot_purposes
            and not runtime_purposes
            and long_qty == 0.0
            and short_qty == 0.0
        )
        clean_rest = not remaining_fixed_cycle_orders and clean_snapshot and not fetch_failed
        state["post_exit_cleanup_in_progress"] = False
        refreshed_snapshot = None
        if clean_rest and callable(context.refresh_snapshot):
            try:
                refreshed_snapshot = context.refresh_snapshot("post_exit_cleanup")
            except Exception as exc:
                logger.warning(
                    "post_exit_cleanup_snapshot_refresh_failed",
                    {
                        "symbol": symbol,
                        "category": category,
                        "error": str(exc),
                    },
                )
        snapshot_to_check = refreshed_snapshot or snapshot
        runtime_state.last_snapshot = snapshot_to_check
        snapshot_purposes, runtime_purposes = self._collect_active_strategy_order_purposes(
            snapshot_to_check, runtime_state
        )
        long_qty = float(snapshot_to_check.long_qty or 0.0)
        short_qty = float(snapshot_to_check.short_qty or 0.0)

        clean_snapshot = (
            not snapshot_purposes
            and not runtime_purposes
            and long_qty == 0.0
            and short_qty == 0.0
        )
        if clean_rest and clean_snapshot:
            now_iso = datetime.now(timezone.utc).isoformat()
            state["post_exit_cleanup_verified"] = True
            state["post_exit_cleanup_required"] = False
            state["post_exit_cleanup_verified_at"] = now_iso
            state["post_exit_cleanup_verified_snapshot_updated_at"] = (
                snapshot_to_check.updated_at.isoformat()
                if snapshot_to_check and snapshot_to_check.updated_at
                else now_iso
            )
            self._purge_active_orders(
                runtime_state,
                self._all_cycle_purposes() + self._exit_purposes(),
            )
            if state.get("final_exit_pnl_fetch_deferred_cleanup"):
                state["final_exit_pnl_deferred_allows_fresh_entry"] = True
            reset_performed = self._perform_verified_flat_runtime_reset(
                snapshot_to_check,
                runtime_state,
                context,
                reason="post_exit_cleanup_verified",
                allow_unknown_final_pnl=True,
            )
            _log_event(
                "fixed_cycle_post_exit_verified_runtime_reset_result",
                {
                    "symbol": self.config.symbol,
                    "reset_performed": bool(reset_performed),
                    "verified_flat_runtime_reset_done": bool(
                        runtime_state.strategy_state.get("verified_flat_runtime_reset_done")
                    ),
                    "fresh_restart_required": bool(
                        runtime_state.strategy_state.get("fresh_restart_required")
                    ),
                    "initial_entry_submitted": bool(
                        runtime_state.strategy_state.get("initial_entry_submitted")
                    ),
                    "initial_entry_confirmed": bool(
                        runtime_state.strategy_state.get("initial_entry_confirmed")
                    ),
                },
            )
            _log_event(
                "fixed_cycle_post_exit_cleanup_verified",
                {
                    "symbol": symbol,
                    "category": category,
                    "attempt": attempts,
                },
            )
            return True

        wait_payload = {
            "symbol": symbol,
            "category": category,
            "post_exit_cleanup_started_at": state.get("post_exit_cleanup_started_at"),
            "remaining_exchange_orders": len(remaining_fixed_cycle_orders),
            "snapshot_orders": len(snapshot_purposes),
            "runtime_orders": len(runtime_purposes),
            "long_qty": long_qty,
            "short_qty": short_qty,
        }
        self._emit_throttled_strategy_audit(
            runtime_state,
            context,
            "fixed_cycle_post_exit_cleanup_waiting",
            wait_payload,
            signature_key="post_exit_cleanup_waiting",
            interval_ms=120000,
        )
        if remaining_fixed_cycle_orders and attempts >= POST_EXIT_CLEANUP_MAX_ATTEMPTS:
            _log_event(
                "fixed_cycle_post_exit_cleanup_failed",
                {
                    "symbol": symbol,
                    "category": category,
                    "attempt": attempts,
                    "remaining_exchange_orders": len(remaining_fixed_cycle_orders),
                },
            )
        return False

    def _ensure_post_exit_cleanup_ready_for_fresh_restart(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        reason: str,
    ) -> HedgeSnapshot | None:
        if not self._post_exit_cleanup_pending(runtime_state):
            return snapshot
        success = self._attempt_post_exit_cleanup(snapshot, runtime_state, context)
        if not success:
            self._emit_throttled_strategy_audit(
                runtime_state,
                context,
                "fixed_cycle_fresh_restart_blocked_post_exit_cleanup_pending",
                {
                    "symbol": self.config.symbol,
                    "reason": reason,
                    "trade_block_id": runtime_state.strategy_state.get("trade_block_id"),
                    "last_trade_block_id": runtime_state.strategy_state.get("last_trade_block_id"),
                    "post_exit_cleanup_started_at": runtime_state.strategy_state.get(
                        "post_exit_cleanup_started_at"
                    ),
                    "post_exit_cleanup_required": bool(
                        runtime_state.strategy_state.get("post_exit_cleanup_required")
                    ),
                    "post_exit_cleanup_verified": bool(
                        runtime_state.strategy_state.get("post_exit_cleanup_verified")
                    ),
                },
                signature_key="fresh_restart_blocked_post_exit_cleanup_pending",
                interval_ms=120000,
            )
            return None
        refreshed = runtime_state.last_snapshot or snapshot
        if (
            (refreshed.long_qty or 0.0) > 0
            or (refreshed.short_qty or 0.0) > 0
            or bool(refreshed.active_orders)
            or bool(runtime_state.active_orders)
        ):
            self._emit_throttled_strategy_audit(
                runtime_state,
                context,
                "fixed_cycle_fresh_restart_blocked_post_exit_cleanup_not_clean",
                {
                    "symbol": self.config.symbol,
                    "reason": reason,
                    "snapshot_long_qty": refreshed.long_qty,
                    "snapshot_short_qty": refreshed.short_qty,
                    "snapshot_active_orders": len(refreshed.active_orders or ()),
                    "runtime_active_orders": len(runtime_state.active_orders),
                    "post_exit_cleanup_required": bool(
                        runtime_state.strategy_state.get("post_exit_cleanup_required")
                    ),
                    "post_exit_cleanup_verified": bool(
                        runtime_state.strategy_state.get("post_exit_cleanup_verified")
                    ),
                },
                signature_key="fresh_restart_blocked_post_exit_cleanup_not_clean",
                interval_ms=120000,
            )
            return None
        return refreshed

    def _reset_cycle_state(self, runtime_state: RuntimeState) -> dict:
        state = runtime_state.strategy_state
        preserved_last_trade = self._preserve_last_trade_pnl_fields(state)
        previous_cycle_state = state.get("cycle_state") or {}
        old_refill_pending = bool(state.get("refill_pending"))
        old_refill_required = bool(state.get("refill_required"))
        old_refill_in_progress = bool(state.get("refill_in_progress"))
        old_cycle_block_status = previous_cycle_state.get("cycle_block_status")
        old_cycle_waiting_for_short_tp = bool(previous_cycle_state.get("cycle_waiting_for_short_tp"))
        old_short_tp_pending_cycle = int(previous_cycle_state.get("short_tp_pending_cycle") or 0)
        old_long_add_pending = bool(previous_cycle_state.get("long_add_pending"))
        old_exit_locked = bool(state.get("exit_locked"))
        old_exit_rebuild_allowed = bool(state.get("exit_rebuild_allowed"))
        old_last_exit_signature_present = bool(state.get("last_exit_signature"))
        old_cycle_completed_count = int(state.get("cycle_completed_count") or 0)
        old_cycle_pair_count = int(state.get("cycle_pair_count") or 0)
        cycle_state = self._default_cycle_state()
        cycle_state.update(
            {
                "refill_pending": False,
                "refill_required": False,
                "refill_in_progress": False,
                "refill_long_filled": False,
                "refill_short_filled": False,
                "refill_exit_orders_cancel_required": False,
                "refill_completed": False,
                "cycle_block_status": None,
                "cycle_block_reason": None,
                "cycle_waiting_for_short_tp": False,
                "short_tp_pending_cycle": 0,
                "long_add_pending": False,
                "pending_long_cycle_index": 0,
                "pending_short_cycle_index": 0,
                "current_effective_cycle": 0,
                "cycle_completed_count": 0,
                "cycle_pair_count": 0,
                "processed_cycle_purposes": [],
                "processed_fill_ids": [],
                "long_fills": {},
                "short_fills": {},
                "cycle_states": {},
            }
        )
        for key in (
            "last_confirmed_short_fill_price",
            "last_confirmed_short_fill_cycle_index",
            "last_confirmed_short_fill_purpose",
        ):
            cycle_state.pop(key, None)
        cycle_state["pending_loss_exit_old_signature"] = None
        cycle_state["pending_loss_exit_rebuild_reason"] = None
        cycle_state["cycle_waiting_for_short_tp"] = False
        state["cycle_state"] = cycle_state
        state["current_long_cycle_index"] = 0
        state["current_short_cycle_index"] = 0
        state["current_effective_cycle"] = 0
        state["cycle_waiting_for_short_tp"] = False
        state["pending_long_cycle_index"] = 0
        state["short_tp_pending_cycle"] = 0
        state["long_add_pending"] = False
        state["cycle_states"] = {}
        state["processed_cycle_purposes"] = []
        state.pop("completed_cycle_purposes", None)
        state["block_closed_marker_emitted"] = False
        state["recovery_marker_emitted"] = False
        state["exit_armed_marker_emitted"] = False
        state["exit_rebuild_allowed"] = True
        state["long_add_rebuild_allowed"] = True
        state["fresh_restart_required"] = False
        state["entry_reference_price"] = None
        state["last_exit_signature"] = None
        state["cycle_block_status"] = None
        state["cycle_block_reason"] = None
        state["current_effective_cycle"] = 0
        cycle_state["entry_price"] = None
        state["entry_reference_price"] = None
        state["last_exit_signature"] = None
        cycle_state["entry_price"] = None
        state["net_long_loss_balance"] = 0.0
        state["net_short_loss_balance"] = 0.0
        state["pending_cycle_loss_usdt"] = 0.0
        state["realized_long_loss_total"] = 0.0
        self.realized_long_loss_total = 0.0
        state["processed_pnl_exec_ids"] = []
        state["processed_pnl_exec_ids_order"] = []
        state["long_exit_filled"] = False
        state["short_exit_filled"] = False
        state["short_exit_recovery_submitted"] = False
        state["long_exit_recovery_submitted"] = False
        state["exit_recovery_marker"] = False
        state["exit_locked"] = False
        state["pending_loss_exit_old_signature"] = None
        state["pending_loss_exit_rebuild_reason"] = None
        state["last_completed_purpose"] = None
        state["next_required_purpose"] = self._cycle_purpose("long", 1)
        self._reset_initial_entry_reconcile_state(runtime_state, reset_submission_state=True)
        state.pop("flat_waiting_order_cleanup_logged", None)
        state.pop("flat_waiting_final_pnl_logged", None)
        state.pop("flat_final_pnl_ready_logged", None)
        state.pop("final_pnl_context_missing_logged", None)
        lifecycle_dirty = any(
            [
                old_refill_pending,
                old_refill_required,
                old_refill_in_progress,
                old_cycle_block_status is not None,
                old_cycle_waiting_for_short_tp,
                old_short_tp_pending_cycle != 0,
                old_long_add_pending,
                old_exit_locked,
                old_exit_rebuild_allowed,
                old_last_exit_signature_present,
                old_cycle_completed_count != 0,
                old_cycle_pair_count != 0,
            ]
        )
        if lifecycle_dirty:
            _log_event(
                "fixed_cycle_flat_fresh_start_lifecycle_state_cleared",
                {
                    "symbol": self.config.symbol,
                    "old_refill_pending": old_refill_pending,
                    "old_refill_required": old_refill_required,
                    "old_refill_in_progress": old_refill_in_progress,
                    "old_cycle_block_status": old_cycle_block_status,
                    "old_cycle_waiting_for_short_tp": old_cycle_waiting_for_short_tp,
                    "old_short_tp_pending_cycle": old_short_tp_pending_cycle,
                    "old_long_add_pending": old_long_add_pending,
                    "old_exit_locked": old_exit_locked,
                    "old_exit_rebuild_allowed": old_exit_rebuild_allowed,
                    "old_last_exit_signature_present": old_last_exit_signature_present,
                    "old_cycle_completed_count": old_cycle_completed_count,
                    "old_cycle_pair_count": old_cycle_pair_count,
                    "reason": "flat_exchange_fresh_start",
                },
            )
        self._write_cycle_state(cycle_state)
        self._restore_last_trade_pnl_fields(state, preserved_last_trade)
        return cycle_state

    def _preserve_last_trade_pnl_fields(self, strategy_state: dict[str, Any]) -> dict[str, Any]:
        return {key: value for key, value in strategy_state.items() if key.startswith("last_trade_")}

    def _restore_last_trade_pnl_fields(self, strategy_state: dict[str, Any], preserved: dict[str, Any]) -> None:
        for key, value in preserved.items():
            strategy_state[key] = value

    def _persist_last_trade_pnl_summary(
        self,
        runtime_state: RuntimeState,
        *,
        total_trade_pnl: float,
        breakdown: dict[str, Any],
        source: str,
        pnl_complete: bool,
        trade_block_id: str,
        finalized_at: str,
    ) -> None:
        state = runtime_state.strategy_state
        state["last_trade_pnl_usdt"] = total_trade_pnl
        state["last_trade_pnl_finalized_at"] = finalized_at
        state["last_trade_symbol"] = self.config.symbol
        state["last_trade_block_id"] = trade_block_id
        state["last_trade_pnl_source"] = source
        state["last_trade_pnl_complete"] = pnl_complete
        state["last_trade_pnl_breakdown"] = breakdown
    def _cycle_state_last_fill_price(self, fills: dict) -> float | None:
        if not fills:
            return None
        try:
            last_index = max(int(key) for key in fills.keys())
        except ValueError:
            return None
        entry = fills.get(str(last_index)) or {}
        price = entry.get("price")
        return float(price) if price is not None else None

    def _get_confirmed_previous_short_reduce_fill_price(
        self, runtime_state: RuntimeState, cycle_index: int
    ) -> float | None:
        if cycle_index <= 1:
            return None
        previous_index = cycle_index - 1
        entry = self._get_cycle_sequence_entry(runtime_state, previous_index)
        price = float(entry.get(self._second_leg_fill_price_field()) or 0.0)
        confirmed = bool(entry.get(self._second_leg_fill_confirmed_field()))
        if confirmed and price > 0:
            return price
        return None

    def _fill_persistence_key(self, fill_event: FillEvent) -> str:
        if fill_event.exec_id:
            return fill_event.exec_id
        return f"{fill_event.client_order_id or ''}|{fill_event.purpose}|{fill_event.exec_price}|{fill_event.exec_qty}"

    def _all_cycle_purposes(self) -> list[str]:
        purposes: list[str] = []
        for cycle_index in range(1, self.config.max_cycles + 1):
            purposes.append(self._cycle_purpose("long", cycle_index))
            purposes.append(self._cycle_purpose("short", cycle_index))
            purposes.append(self._second_leg_pair_purpose(cycle_index))
        return purposes

    def _exit_purposes(self) -> list[str]:
        """Return the exit purposes covered by the shared refill gate.

        This helper stays direction-neutral so mirrored short-bots can override
        the list without touching the refill lifecycle logic.
        """
        return [
            self.LONG_TP_EXIT_PURPOSE,
            self.LONG_TP_EXIT_RECOVERY_PURPOSE,
            self.LONG_SL_EXIT_PURPOSE,
            self.SHORT_TP_EXIT_PURPOSE,
            self.SHORT_SL_EXIT_PURPOSE,
            self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
        ]

    def _is_cycle_fill_purpose(self, purpose: str | None) -> bool:
        if not purpose:
            return False
        normalized = purpose.upper()
        return normalized.startswith("CYCLE_") and (
            "_LONG_ADD" in normalized
            or "_LONG_REDUCE" in normalized
            or "_SHORT_REDUCE" in normalized
            or "_SHORT_TP" in normalized
        )

    def _is_refill_stale_cycle_reduce_purpose(self, purpose: str | None) -> bool:
        """Return whether a cycle reduce order must be rebuilt after refill.

        Refill changes long_avg/short_avg and position sizes. Open cycle-reduce
        orders are therefore stale because their coverage was calculated from
        the pre-refill position state.
        """
        if not purpose:
            return False
        normalized = str(purpose).upper()
        return bool(re.fullmatch(r"CYCLE_\d+_(SHORT_REDUCE|LONG_REDUCE)", normalized))

    def _is_staged_second_leg_cycle_complete(
        self,
        state: dict[str, Any],
        cycle_index: int,
    ) -> tuple[bool, dict[str, Any]]:
        cycle_key = str(cycle_index)
        required_map = state.get("staged_second_leg_tp_required_net_total") or {}
        realized_map = state.get("staged_second_leg_tp_realized_net") or {}
        filled_map = state.get("staged_second_leg_tp_filled_stages") or {}
        stage_count_map = state.get("staged_second_leg_tp_stage_count") or {}

        total_required = float(required_map.get(cycle_key) or 0.0)
        total_after = float(realized_map.get(cycle_key) or 0.0)
        filled_stages = list(filled_map.get(cycle_key) or [])
        stage_count = int(stage_count_map.get(cycle_key) or 0)

        completed_by_pnl = total_required > 0.0 and total_after >= total_required - 1e-8
        all_stages_done = stage_count > 0 and len(filled_stages) >= stage_count

        complete = completed_by_pnl or all_stages_done

        diagnostics = {
            "cycle_index": cycle_index,
            "cycle_key": cycle_key,
            "stage_count": stage_count,
            "filled_stages": filled_stages,
            "realized_total_net": total_after,
            "required_total_net": total_required,
            "completed_by_pnl": completed_by_pnl,
            "all_stages_done": all_stages_done,
        }

        return complete, diagnostics

    def _has_real_staged_second_leg_config(
        self,
        state: dict[str, Any],
        cycle_index: int,
        metadata: dict[str, Any] | None = None,
    ) -> tuple[bool, dict[str, Any]]:
        """
        Bestimmt, ob für den gegebenen Cycle eine echte Staging-Konfiguration
        für den Second-Leg-TP existiert.

        Wichtig: Ein Eintrag in staged_second_leg_tp_required_net_total mit
        required_total_net > 0 allein gilt NICHT als echte Staging-Konfiguration.
        Es muss wenigstens einer der folgenden Punkte erfüllt sein:
        - metadata["is_staged_second_leg_tp"] == True
        - stage_count > 0
        - gefüllte Stages in staged_second_leg_tp_filled_stages vorhanden
        """
        metadata = metadata or {}
        complete, diag = self._is_staged_second_leg_cycle_complete(state, cycle_index)
        stage_count = int(diag.get("stage_count") or 0)
        filled_stages = list(diag.get("filled_stages") or [])
        meta_flag = bool(metadata.get("is_staged_second_leg_tp"))
        has_real_config = bool(meta_flag or stage_count > 0 or filled_stages)
        return has_real_config, {**diag, "complete": complete}

    def _is_normal_cycle_second_leg_split_complete(
        self,
        state: dict[str, Any],
        cycle_index: int,
    ) -> tuple[bool, dict[str, Any]]:
        cycle_key = str(cycle_index)
        filled_map = state.get("normal_cycle_second_leg_split_filled_stages") or {}
        stage_count_map = state.get("normal_cycle_second_leg_split_stage_count") or {}

        filled_stages = list(filled_map.get(cycle_key) or [])
        stage_count = int(stage_count_map.get(cycle_key) or 0)
        all_stages_done = stage_count > 0 and len(filled_stages) >= stage_count

        diagnostics = {
            "cycle_index": cycle_index,
            "cycle_key": cycle_key,
            "stage_count": stage_count,
            "filled_stages": filled_stages,
            "all_stages_done": all_stages_done,
        }
        return all_stages_done, diagnostics

    def _is_refill_mode_active(self, state: dict[str, Any]) -> bool:
        """Answer whether refill lifecycle protection is currently holding."""
        return bool(
            state.get("refill_pending")
            or state.get("refill_required")
            or state.get("refill_in_progress")
            or state.get("bot_state") in {self.STATE_REFILL_PENDING, self.STATE_REFILL_IN_PROGRESS}
        )

    def _enter_refill_mode(
        self,
        state: dict[str, Any],
        *,
        reason: str,
        cycle_index: int | None = None,
        symbol: str | None = None,
    ) -> None:
        """Activate the shared refill lifecycle by locking exits and tracking the cancel requirement.

        Keep this direction-neutral so future mirrored bots override `_exit_purposes()` instead
        of the gate itself.
        """
        state["refill_pending"] = True
        state["refill_required"] = True
        state["force_exit_rebuild"] = False
        state["exit_locked"] = True
        state["refill_exit_orders_cancel_required"] = True
        state["bot_state"] = self.STATE_REFILL_PENDING
        _log_event(
            "fixed_cycle_refill_mode_entered",
            {
                "symbol": symbol,
                "reason": reason,
                "cycle_index": cycle_index,
                "refill_pending": state["refill_pending"],
                "refill_required": state["refill_required"],
                "refill_in_progress": bool(state.get("refill_in_progress")),
                "force_exit_rebuild": state["force_exit_rebuild"],
                "exit_locked": state["exit_locked"],
                "bot_state": state["bot_state"],
                "refill_exit_orders_cancel_required": state["refill_exit_orders_cancel_required"],
            },
        )

    def _exit_refill_mode_after_complete_refill(
        self,
        state: dict[str, Any],
        *,
        reason: str = "refill_completed",
        symbol: str | None = None,
    ) -> None:
        """Reset the refill lifecycle so exit intents may resume.

        This shared helper stays reusable across mirrored bots without behavior changes.
        """
        state["refill_pending"] = False
        state["refill_required"] = False
        state["refill_in_progress"] = False
        state["refill_exit_orders_cancel_required"] = False
        state["exit_locked"] = False
        state["force_exit_rebuild"] = True
        state["bot_state"] = self.STATE_RUNNING
        previous_cycle_block_status = state.get("cycle_block_status")
        state.pop("cycle_block_status", None)
        _log_event(
            "fixed_cycle_refill_block_status_reset",
            {
                "symbol": symbol,
                "reason": reason,
                "previous_cycle_block_status": previous_cycle_block_status,
                "cycle_block_status": state.get("cycle_block_status"),
            },
        )
        _log_event(
            "fixed_cycle_refill_mode_completed_exit_rebuild_allowed",
            {
                "symbol": symbol,
                "reason": reason,
                "refill_pending": state["refill_pending"],
                "refill_required": state["refill_required"],
                "refill_in_progress": state["refill_in_progress"],
                "force_exit_rebuild": state["force_exit_rebuild"],
                "exit_locked": state["exit_locked"],
                "bot_state": state["bot_state"],
            },
        )

    def _force_exit_rebuild_after_cycle_fill(
        self, runtime_state: RuntimeState, fill_event: FillEvent
    ) -> None:
        state = runtime_state.strategy_state
        previous_exit_locked = bool(state.get("exit_locked"))
        previous_signature = state.get("last_exit_signature")
        snapshot = runtime_state.last_snapshot
        symbol = self._active_trade_symbol(snapshot, runtime_state, fill_event=fill_event) or self.config.symbol
        long_qty = float(snapshot.long_qty or 0.0) if snapshot else 0.0
        short_qty = float(snapshot.short_qty or 0.0) if snapshot else 0.0

        if (fill_event.metadata or {}).get("is_staged_second_leg_tp"):
            _log_event(
                "staged_second_leg_tp_exit_rebuild_requested",
                {
                    "symbol": symbol,
                    "fill_purpose": fill_event.purpose,
                    "cycle_index": (fill_event.metadata or {}).get("cycle_index"),
                    "stage_index": (fill_event.metadata or {}).get("stage_index"),
                    "stage_count": (fill_event.metadata or {}).get("stage_count"),
                },
            )

        if self._is_refill_mode_active(state):
            state["force_exit_rebuild"] = False
            state["exit_locked"] = True
            _log_event(
                "fixed_cycle_exit_rebuild_blocked_refill_mode_active",
                {
                    "symbol": symbol,
                    "fill_purpose": fill_event.purpose,
                    "refill_pending": state.get("refill_pending"),
                    "refill_required": state.get("refill_required"),
                },
            )
            return

        state["exit_locked"] = False
        state["exit_rebuild_allowed"] = True
        state["force_exit_rebuild"] = True
        state["pending_loss_updated_in_fill"] = True
        state["pending_loss_exit_old_signature"] = previous_signature
        state["pending_loss_exit_rebuild_reason"] = "cycle_fill_structure_changed"
        state["last_exit_signature"] = None
        state.pop("last_exit_rebuild_skip_signature", None)

        _log_event(
            "fixed_cycle_exit_rebuild_forced_after_cycle_fill",
            {
                "symbol": symbol,
                "fill_purpose": fill_event.purpose,
                "fill_status": fill_event.status,
                "long_qty": long_qty,
                "short_qty": short_qty,
                "pending_cycle_loss_usdt": float(state.get("pending_cycle_loss_usdt") or 0.0),
                "previous_exit_locked": previous_exit_locked,
                "previous_last_exit_signature": previous_signature,
                "pending_loss_exit_rebuild_reason": state.get("pending_loss_exit_rebuild_reason"),
                "force_exit_rebuild": True,
            },
        )
        if previous_exit_locked:
            _log_event(
                "fixed_cycle_exit_lock_overridden_after_cycle_fill",
                {
                    "symbol": symbol,
                    "fill_purpose": fill_event.purpose,
                    "long_qty": long_qty,
                    "short_qty": short_qty,
                    "previous_exit_locked": previous_exit_locked,
                },
            )

    @staticmethod
    def _safe_recovery_qty(value: Decimal | float | str | int | None) -> float:
        if value in (None, ""):
            return 0.0
        try:
            return float(Decimal(str(value)))
        except Exception:
            return 0.0

    def _recover_purpose_from_order_update(self, payload: dict[str, Any]) -> str:
        candidates = [
            payload.get("orderLinkId"),
            payload.get("order_link_id"),
            payload.get("clientOrderId"),
            payload.get("client_order_id"),
        ]
        for candidate in candidates:
            text = str(candidate or "").strip()
            if not text:
                continue
            upper = text.upper()
            if "REFILL_LONG" in upper:
                return "REFILL_LONG"
            if "REFILL_SHORT" in upper:
                return "REFILL_SHORT"
            if "SHORT_SL_EXIT_RECOVERY" in upper:
                return self.SHORT_SL_EXIT_RECOVERY_PURPOSE
            if "LONG_TP_EXIT_RECOVERY" in upper:
                return self.LONG_TP_EXIT_RECOVERY_PURPOSE
            if "LONG_SL_EXIT" in upper:
                return self.LONG_SL_EXIT_PURPOSE
            if "SHORT_TP_EXIT" in upper:
                return self.SHORT_TP_EXIT_PURPOSE
            if "SHORT_SL_EXIT" in upper:
                return self.SHORT_SL_EXIT_PURPOSE
            if "LONG_TP_EXIT" in upper:
                return self.LONG_TP_EXIT_PURPOSE
        return ""

    def _recover_purpose_from_exchange_order(self, order: dict[str, Any]) -> str:
        recovered = self._recover_purpose_from_order_update(order)
        if recovered:
            return recovered
        candidates = [
            order.get("orderLinkId"),
            order.get("order_link_id"),
            order.get("clientOrderId"),
            order.get("client_order_id"),
        ]
        prefix = f"{self.name}-"
        recovered_prefix = f"recovered-{self.name}-"
        for candidate in candidates:
            client_id = str(candidate or "").strip()
            if not client_id:
                continue
            if client_id.startswith(prefix):
                remainder = client_id[len(prefix):]
                if "-" in remainder:
                    return remainder.rsplit("-", 1)[0].upper()
            if client_id.startswith(recovered_prefix):
                remainder = client_id[len(recovered_prefix):]
                if remainder.startswith("-") and "--" in remainder[1:]:
                    purpose_part = remainder[1:].split("--", 1)[0]
                    if purpose_part:
                        return purpose_part.upper()
                if "-" in remainder:
                    return remainder.rsplit("-", 1)[0].upper()
        return ""

    def _expected_cycle_purpose_for_deactivation_check(
        self,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState,
    ) -> str | None:
        state = runtime_state.strategy_state
        next_required_purpose = str(state.get("next_required_purpose") or "").strip().upper()
        if next_required_purpose.startswith("CYCLE_"):
            return next_required_purpose

        cycle_index = int(state.get("active_cycle_index") or 0)
        if cycle_index <= 0:
            cycle_index = int(state.get("current_effective_cycle") or 0)
        if cycle_index <= 0 and state.get("current_long_cycle_index"):
            cycle_index = int(state.get("current_long_cycle_index") or 0)
        if cycle_index <= 0 and state.get("current_short_cycle_index"):
            cycle_index = int(state.get("current_short_cycle_index") or 0)

        if cycle_index <= 0:
            _log_event(
                "fixed_cycle_deactivation_expected_cycle_purpose_unknown",
                {
                    "symbol": self.config.symbol,
                    "state_cycle_index": state.get("active_cycle_index"),
                    "current_effective_cycle": state.get("current_effective_cycle"),
                    "current_long_cycle_index": state.get("current_long_cycle_index"),
                    "current_short_cycle_index": state.get("current_short_cycle_index"),
                    "cycle_step": state.get("cycle_step"),
                    "next_required_purpose": next_required_purpose,
                },
            )
            return None

        cycle_step = state.get("cycle_step") or STEP_WAITING_FOR_PAIR_FIRST_LEG
        if cycle_step == STEP_WAITING_FOR_PAIR_SECOND_LEG:
            return self._get_second_leg_purpose(cycle_index)
        return self._get_first_leg_purpose(cycle_index)

    def _verify_structure_intact_before_deactivation_recovery(
        self,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        purpose: str,
        order_link_id: str,
        exchange_order_id: str,
        reason: str,
    ) -> tuple[bool, dict[str, Any]]:
        symbol = context.symbol or self.config.symbol
        category = context.category or self.config.category
        order_manager = context.order_manager or self.order_manager
        expected_cycle_purpose = self._expected_cycle_purpose_for_deactivation_check(
            snapshot, runtime_state
        )
        rest_open_purposes: list[str] = []
        fetch_error: str | None = None

        if order_manager and symbol:
            try:
                open_orders = order_manager.fetch_open_orders(symbol=symbol, category=category) or []
                for order in open_orders:
                    if not self._is_fixed_cycle_exchange_order(order):
                        continue
                    recovered = self._recover_purpose_from_exchange_order(order)
                    if recovered:
                        rest_open_purposes.append(recovered)
            except Exception as exc:
                fetch_error = str(exc)
        else:
            fetch_error = "fetch_open_orders_unavailable"

        rest_open_purposes = sorted(set(rest_open_purposes))
        has_cycle_order = bool(
            expected_cycle_purpose and expected_cycle_purpose in rest_open_purposes
        )
        long_exit_purpose = self._get_final_long_exit_purpose()
        short_exit_purpose = self._get_final_short_exit_purpose()
        has_long_exit = long_exit_purpose in rest_open_purposes
        has_short_exit = short_exit_purpose in rest_open_purposes

        missing_purposes: list[str] = []
        if not has_cycle_order:
            missing_purposes.append(expected_cycle_purpose or "CURRENT_CYCLE_ORDER")
        if not has_long_exit:
            missing_purposes.append(long_exit_purpose)
        if not has_short_exit:
            missing_purposes.append(short_exit_purpose)
        if fetch_error:
            missing_purposes.append("REST_FETCH_FAILED")

        details = {
            "symbol": symbol,
            "category": category,
            "deactivated_purpose": purpose,
            "order_link_id": order_link_id or None,
            "exchange_order_id": exchange_order_id or None,
            "reason": reason,
            "rest_open_purposes": rest_open_purposes,
            "expected_cycle_purpose": expected_cycle_purpose,
            "has_cycle_order": has_cycle_order,
            "has_long_tp_exit": has_long_exit,
            "has_short_sl_exit": has_short_exit,
            "missing_purposes": missing_purposes,
        }
        if fetch_error:
            details["rest_fetch_error"] = fetch_error

        return (not missing_purposes), details

    def _build_force_exit_recovery_intent(
        self,
        *,
        side: str,
        qty: Decimal | float | str,
        symbol: str,
        purpose: str,
        reason: str,
        source_order_id: str | None = None,
        source_order_link_id: str | None = None,
    ) -> StrategyIntent:
        runtime_side = "short" if str(side or "").strip().lower() == "short" else "long"
        position_idx = 2 if runtime_side == "short" else 1
        normalized_qty = self._safe_recovery_qty(qty)
        return StrategyIntent(
            side=runtime_side,
            qty=normalized_qty,
            purpose=purpose,
            order_type="Market",
            reduce_only=True,
            close_on_trigger=True,
            position_idx=position_idx,
            metadata={
                "recovery_force": True,
                "reason": reason,
                "symbol": symbol,
                "source_order_id": source_order_id,
                "source_order_link_id": source_order_link_id,
                "original_exit_cancelled": True,
                "position_idx": position_idx,
            },
        )

    def _emergency_exit_signature(self, payload: dict[str, Any]) -> str | None:
        for key in ("orderId", "orderLinkId", "order_link_id", "clientOrderId", "client_order_id"):
            candidate = str(payload.get(key) or "").strip()
            if candidate:
                return candidate.upper()
        return None

    def _emergency_exit_purposes(self) -> set[str]:
        return {
            *self._get_final_exit_purposes(),
            self.LONG_TP_EXIT_RECOVERY_PURPOSE,
            self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
            self.SHORT_HARD_STOP_PURPOSE,
            "FINAL_LONG_EXIT",
            "FINAL_SHORT_EXIT",
        }

    def _should_trigger_emergency_exit(
        self,
        state: dict[str, Any],
        purpose: str | None,
        status: str,
        reason_upper: str,
        payload: dict[str, Any],
    ) -> bool:
        if not purpose:
            return False
        if purpose not in self._emergency_exit_purposes():
            return False
        reason_matches = reason_upper == self.EMERGENCY_REJECT_REASON
        if status not in self.EMERGENCY_EXIT_STATUSES and not reason_matches:
            return False
        if state.get("emergency_flat_required"):
            existing_signature = state.get("emergency_exit_signature")
            current_signature = self._emergency_exit_signature(payload)
            if current_signature and current_signature == existing_signature:
                return False
        return True

    def _register_expected_exit_order_deactivations(
        self,
        runtime_state: RuntimeState,
        *,
        purposes: list[str] | None = None,
        replacement_purpose: str | None = None,
    ) -> None:
        if purposes is None:
            purposes = self._exit_purposes()
        state = runtime_state.strategy_state
        registry: list[dict[str, Any]] = state.get("expected_exit_cancels") or []
        now = time.monotonic()
        expires_at = now + EXPECTED_EXIT_ORDER_CANCEL_TIMEOUT_SECONDS
        seen: set[tuple[str | None, str | None, str | None]] = set()
        for entry in registry:
            if not isinstance(entry, dict):
                continue
            seen.add(
                (
                    entry.get("client_order_id"),
                    entry.get("exchange_order_id"),
                    entry.get("purpose"),
                )
            )
        for order in runtime_state.active_orders.values():
            if not order:
                continue
            purpose = str(order.purpose or "").strip()
            if not purpose or purpose not in purposes:
                continue
            # Trading-stop-basierte Exit-Orders werden nicht über expected_exit_cancels
            # verfolgt, da sie keine klassischen Order-Deaktivierungen durchlaufen.
            if getattr(order, "metadata", None) and getattr(order, "metadata", {}).get("trading_stop_api"):
                continue
            status = str(order.status or "").upper()
            if status in {"FILLED", "CANCELED", "CANCELLED", "REJECTED", "EXPIRED"}:
                continue
            client_id = order.client_order_id or ""
            exchange_id = order.exchange_order_id or ""
            if not client_id and not exchange_id:
                _log_event(
                    "fixed_cycle_expected_deactivation_registration_skipped_missing_ids",
                    {
                        "symbol": self.config.symbol,
                        "purpose": purpose,
                        "status": status,
                    },
                )
                continue
            key = (client_id, exchange_id, purpose)
            if key in seen:
                continue
            seen.add(key)
            entry = {
                "purpose": purpose,
                "client_order_id": client_id,
                "exchange_order_id": exchange_id,
                "replacement_purpose": replacement_purpose,
                "registered_at_monotonic": now,
                "expires_at_monotonic": expires_at,
            }
            registry.append(entry)
            _log_event(
                "fixed_cycle_exit_order_marked_expected_deactivation",
                {
                    "symbol": self.config.symbol,
                    "purpose": purpose,
                    "client_order_id": order.client_order_id,
                    "exchange_order_id": order.exchange_order_id,
                    "replacement_purpose": replacement_purpose,
                    "status": order.status,
                },
            )
        state["expected_exit_cancels"] = registry

    def _guard_duplicate_exit_purposes(
        self,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState,
    ) -> bool:
        counts: dict[str, int] = {}
        seen: set[str] = set()
        exit_purposes = {purpose.upper() for purpose in self._exit_purposes()}

        def _dedupe_key(order: ManagedOrder) -> str:
            exchange_id = str(order.exchange_order_id or "").strip()
            client_id = str(order.client_order_id or "").strip()
            purpose = str(order.purpose or "").strip()
            side = str(order.side or "").strip()
            qty = str(order.qty or "")
            status = str(order.status or "").upper()
            price = str(getattr(order, "price", "") or getattr(order, "trigger_price", "") or "")
            if exchange_id:
                return f"ex:{exchange_id}"
            if client_id:
                return f"cl:{client_id}"
            return f"fallback:{purpose}:{side}:{qty}:{price}:{status}"

        def _count_order(order: ManagedOrder, source: str) -> None:
            purpose = str(order.purpose or "").upper()
            status = str(order.status or "").upper()
            if purpose not in exit_purposes:
                return
            if status in {"FILLED", "CANCELED", "CANCELLED", "REJECTED", "EXPIRED"}:
                return
            key = _dedupe_key(order)
            if key in seen:
                _log_event(
                    "fixed_cycle_duplicate_exit_source_deduped",
                    {
                        "symbol": self.config.symbol,
                        "purpose": purpose,
                        "source": source,
                        "client_order_id": order.client_order_id,
                        "exchange_order_id": order.exchange_order_id,
                        "dedupe_key": key,
                    },
                )
                return
            seen.add(key)
            counts[purpose] = counts.get(purpose, 0) + 1

        for order in runtime_state.active_orders.values():
            _count_order(order, "runtime_state")
        if snapshot:
            for order in snapshot.active_orders:
                managed = ManagedOrder(
                    client_order_id=order.client_order_id,
                    side=order.side,
                    qty=order.qty,
                    purpose=order.purpose,
                    price=order.price,
                    order_type=order.order_type,
                    reduce_only=order.reduce_only,
                    exchange_order_id=order.exchange_order_id,
                    status=order.status,
                )
                _count_order(managed, "snapshot")

        duplicates = {purpose: count for purpose, count in counts.items() if count > 1}
        if not duplicates:
            return False
        duplicates_detail: list[dict[str, Any]] = []
        seen_detail: set[str] = set()

        def _collect_details(order: ManagedOrder, source: str) -> None:
            purpose = str(order.purpose or "").upper()
            status = str(order.status or "").upper()
            if purpose not in duplicates:
                return
            if status in {"FILLED", "CANCELED", "CANCELLED", "REJECTED", "EXPIRED"}:
                return
            key = _dedupe_key(order)
            if key in seen_detail:
                return
            seen_detail.add(key)
            duplicates_detail.append(
                {
                    "source": source,
                    "purpose": purpose,
                    "side": order.side,
                    "status": status,
                    "client_order_id": order.client_order_id,
                    "exchange_order_id": order.exchange_order_id,
                    "qty": order.qty,
                    "reduce_only": order.reduce_only,
                    "dedupe_key": key,
                }
            )

        for order in runtime_state.active_orders.values():
            _collect_details(order, "runtime_state")
        if snapshot:
            for order in snapshot.active_orders:
                managed = ManagedOrder(
                    client_order_id=order.client_order_id,
                    side=order.side,
                    qty=order.qty,
                    purpose=order.purpose,
                    price=order.price,
                    order_type=order.order_type,
                    reduce_only=order.reduce_only,
                    exchange_order_id=order.exchange_order_id,
                    status=order.status,
                )
                _collect_details(managed, "snapshot")
        _log_warning_event(
            "fixed_cycle_duplicate_exit_purpose_blocked",
            {
                "symbol": self.config.symbol,
                "duplicates": duplicates,
                "snapshot_source": getattr(snapshot, "source", None),
                "duplicates_detail": duplicates_detail,
            },
        )
        return True

    def _can_submit_cycle_intent(
        self,
        runtime_state: RuntimeState,
        snapshot: HedgeSnapshot,
        *,
        purpose: str,
        cycle_index: int,
        cycle_role: str,
    ) -> tuple[bool, str, dict[str, Any]]:
        state = runtime_state.strategy_state
        cycle_state = self._ensure_cycle_state(runtime_state)
        first_leg_cycle_role = self._get_first_leg_cycle_role()
        second_leg_cycle_role = self._get_second_leg_cycle_role()
        first_leg_status_field = self._get_first_leg_status_field()
        second_leg_status_field = self._get_second_leg_status_field()
        normalized_purpose = self._normalize_cycle_purpose(
            purpose,
            {"cycle_index": cycle_index, "cycle_role": cycle_role},
        )
        first_leg_purpose = self._normalize_cycle_purpose(
            self._get_first_leg_purpose(cycle_index),
            {"cycle_index": cycle_index, "cycle_role": first_leg_cycle_role},
        )
        second_leg_purpose = self._normalize_cycle_purpose(
            self._get_second_leg_purpose(cycle_index),
            {"cycle_index": cycle_index, "cycle_role": second_leg_cycle_role},
        )
        is_first_leg_purpose = normalized_purpose == first_leg_purpose
        is_second_leg_purpose = normalized_purpose == second_leg_purpose
        processed_purposes = sorted(
            {
                self._normalize_cycle_purpose(item)
                for item in state.get("processed_cycle_purposes") or []
                if str(item or "")
            }
        )
        long_fills = cycle_state.get("long_fills") or {}
        short_fills = cycle_state.get("short_fills") or {}
        first_leg_side = self._get_first_leg_side()
        first_leg_fill_exists = (
            str(cycle_index) in long_fills
            if first_leg_side == "long"
            else str(cycle_index) in short_fills
        )
        second_leg_fill_exists = (
            str(cycle_index) in short_fills
            if first_leg_side == "long"
            else str(cycle_index) in long_fills
        )
        field_name = (
            first_leg_status_field
            if is_first_leg_purpose
            else second_leg_status_field
            if is_second_leg_purpose
            else first_leg_status_field
            if cycle_role == first_leg_cycle_role
            else second_leg_status_field
        )
        cycle_entry, runtime_matches, snapshot_matches = self._reconcile_cycle_intent_reservation(
            snapshot,
            runtime_state,
            cycle_index=cycle_index,
            field_name=field_name,
            purpose=purpose,
            cycle_role=cycle_role,
        )
        waiting_short_flag = self._get_second_leg_waiting(state, cycle_state)
        short_tp_pending = self._get_second_leg_pending_cycle(state, cycle_state)
        waiting_short = waiting_short_flag
        if short_tp_pending:
            pending_entry = self._get_cycle_sequence_entry(runtime_state, short_tp_pending)
            if pending_entry and pending_entry.get("complete"):
                waiting_short = False
                short_tp_pending = 0
                _log_event(
                    "fixed_cycle_state_gate_stale_pending_cycle_ignored",
                    {
                        "symbol": snapshot.symbol or self.config.symbol,
                        "cycle_index": short_tp_pending,
                        "reason": "pending_cycle_already_complete",
                    },
                )
        active_order_count = len(runtime_matches) + len(snapshot_matches)
        active_same_purpose = bool(runtime_matches or snapshot_matches)
        entry_status = str(cycle_entry.get(field_name) or "NONE").upper()
        waiting_short_active = waiting_short and short_tp_pending > 0
        expected_cycle_index = int(state.get("active_cycle_index") or 0)
        details = {
            "symbol": snapshot.symbol or self.config.symbol,
            "purpose": normalized_purpose,
            "cycle_index": cycle_index,
            "cycle_role": cycle_role,
            "active_cycle_index": int(state.get("active_cycle_index") or 0),
            "next_required_purpose": str(state.get("next_required_purpose") or ""),
            "cycle_waiting_for_short_tp": waiting_short_active,
            "short_tp_pending_cycle": short_tp_pending,
            "processed_cycle_purposes": processed_purposes,
            "active_order_count": active_order_count,
            "entry_status": entry_status,
            "long_fill_exists": str(cycle_index) in long_fills,
            "short_fill_exists": str(cycle_index) in short_fills,
            "first_leg_fill_exists": first_leg_fill_exists,
            "second_leg_fill_exists": second_leg_fill_exists,
            "active_runtime_order_matches": runtime_matches,
            "active_snapshot_order_matches": snapshot_matches,
        }
        allowed_purposes: list[str] = (
            [self._get_second_leg_purpose(cycle_index), self.SHORT_SL_EXIT_PURPOSE]
            if is_first_leg_purpose
            else [self._get_second_leg_purpose(cycle_index)]
            if is_second_leg_purpose
            else []
        )
        expected_next_action = ""
        reason = ""
        if is_first_leg_purpose:
            _log_event(
                "fixed_cycle_first_leg_gate_check",
                {
                    **details,
                    "allowed_purposes": allowed_purposes,
                    "expected_cycle_index": expected_cycle_index,
                    "expected_next_action": expected_next_action,
                    "is_first_leg_purpose": True,
                    "is_second_leg_purpose": is_second_leg_purpose,
                },
            )
        if self._cycle_build_block_active(state):
            reason = "refill_required"
            expected_next_action = "refill"
            if is_first_leg_purpose:
                _log_event(
                    "fixed_cycle_first_leg_gate_blocked",
                    {
                        **details,
                        "allowed_purposes": allowed_purposes,
                        "expected_cycle_index": expected_cycle_index,
                        "expected_next_action": expected_next_action,
                        "is_first_leg_purpose": True,
                        "is_second_leg_purpose": is_second_leg_purpose,
                        "reason": reason,
                    },
                )
            return False, reason, {**details, **{"expected_next_action": expected_next_action, "allowed_purposes": allowed_purposes}}
        if is_first_leg_purpose:
            allowed_purposes = [
                self._get_second_leg_purpose(cycle_index),
                self.SHORT_SL_EXIT_PURPOSE,
            ]
            if waiting_short_active:
                reason = "waiting_for_short_followup_no_long_reduce_allowed"
                expected_next_action = "build_short_followup"
                expected_cycle_index = short_tp_pending
                details["expected_cycle_index"] = expected_cycle_index
                _log_event(
                    "fixed_cycle_first_leg_gate_blocked",
                    {
                        **details,
                        "allowed_purposes": allowed_purposes,
                        "expected_cycle_index": expected_cycle_index,
                        "expected_next_action": expected_next_action,
                        "is_first_leg_purpose": True,
                        "is_second_leg_purpose": is_second_leg_purpose,
                        "reason": reason,
                    },
                )
                return False, reason, {**details, **{"expected_next_action": expected_next_action, "allowed_purposes": allowed_purposes}}
            if (
                first_leg_fill_exists
                or normalized_purpose in processed_purposes
                or self._cycle_status_blocks_build(entry_status)
            ):
                reason = (
                    f"{first_leg_cycle_role}_slot_reserved"
                    if entry_status in {"INTENT_BUILT", "SUBMITTING", "SUBMITTED", "OPEN", "NEW", "UNTRIGGERED", "PARTIALLY_FILLED"}
                    else f"{first_leg_cycle_role}_already_processed"
                )
                expected_next_action = "build_short_followup"
                _log_event(
                    "fixed_cycle_first_leg_gate_blocked",
                    {
                        **details,
                        "allowed_purposes": allowed_purposes,
                        "expected_cycle_index": expected_cycle_index,
                        "expected_next_action": expected_next_action,
                        "is_first_leg_purpose": True,
                        "is_second_leg_purpose": is_second_leg_purpose,
                        "reason": reason,
                    },
                )
                return False, reason, {**details, **{"expected_next_action": expected_next_action, "allowed_purposes": allowed_purposes}}
            if active_same_purpose:
                missing_split_stages = self._missing_normal_split_stage_indices(
                    state,
                    runtime_state,
                    snapshot,
                    cycle_index=cycle_index,
                    purpose=purpose,
                    cycle_role=first_leg_cycle_role,
                )
                if not missing_split_stages:
                    reason = f"{first_leg_cycle_role}_order_still_open"
                    expected_next_action = "await_existing_long_reduce"
                    _log_event(
                        "fixed_cycle_first_leg_gate_blocked",
                        {
                            **details,
                            "allowed_purposes": allowed_purposes,
                            "expected_cycle_index": expected_cycle_index,
                            "expected_next_action": expected_next_action,
                            "is_first_leg_purpose": True,
                            "is_second_leg_purpose": is_second_leg_purpose,
                            "reason": reason,
                        },
                    )
                    return False, reason, {**details, **{"expected_next_action": expected_next_action, "allowed_purposes": allowed_purposes}}
            _log_event(
                "fixed_cycle_first_leg_gate_allowed",
                {
                    **details,
                    "allowed_purposes": allowed_purposes,
                    "expected_cycle_index": expected_cycle_index,
                    "expected_next_action": "order_allowed",
                    "is_first_leg_purpose": True,
                    "is_second_leg_purpose": is_second_leg_purpose,
                },
            )
        elif is_second_leg_purpose:
            allowed_purposes = [
                self._get_second_leg_purpose(cycle_index),
            ]
            first_leg_entry = self._get_cycle_sequence_entry(runtime_state, cycle_index)
            first_leg_processed = (
                first_leg_fill_exists
                or first_leg_purpose in processed_purposes
                or str(first_leg_entry.get(first_leg_status_field) or "NONE").upper() in {"FILLED", "PROCESSED"}
            )
            waiting_for_short = waiting_short_active and short_tp_pending == cycle_index
            details["allowed_purposes"] = allowed_purposes
            missing_split_stages = self._missing_normal_split_stage_indices(
                state,
                runtime_state,
                snapshot,
                cycle_index=cycle_index,
                purpose=purpose,
                cycle_role=second_leg_cycle_role,
            )
            if not waiting_for_short or not first_leg_processed:
                reason = "short_followup_not_ready"
                expected_next_action = "build_short_followup"
                expected_cycle_index = short_tp_pending
                details["expected_cycle_index"] = expected_cycle_index
                return False, reason, {**details, **{"expected_next_action": expected_next_action, "allowed_purposes": allowed_purposes}}
            if second_leg_fill_exists or normalized_purpose in processed_purposes:
                reason = f"{second_leg_cycle_role}_already_processed"
                expected_next_action = "await_existing_second_leg"
                return False, reason, {**details, **{"expected_next_action": expected_next_action, "allowed_purposes": allowed_purposes}}
            if self._cycle_status_blocks_build(entry_status) and not missing_split_stages:
                reason = (
                    f"{second_leg_cycle_role}_slot_reserved"
                    if entry_status in {"INTENT_BUILT", "SUBMITTING", "SUBMITTED", "OPEN", "NEW", "UNTRIGGERED", "PARTIALLY_FILLED"}
                    else f"{second_leg_cycle_role}_already_processed"
                )
                expected_next_action = "await_existing_second_leg"
                return False, reason, {**details, **{"expected_next_action": expected_next_action, "allowed_purposes": allowed_purposes}}
            if active_same_purpose and not missing_split_stages:
                reason = f"{second_leg_cycle_role}_order_still_open"
                expected_next_action = "await_existing_second_leg"
                return False, reason, {**details, **{"expected_next_action": expected_next_action, "allowed_purposes": allowed_purposes}}
        return True, reason, {**details, **{"expected_next_action": "order_allowed", "allowed_purposes": allowed_purposes}}

    def _expected_exit_cancel_purposes(self) -> set[str]:
        base_finals = self._get_final_exit_purposes()
        return {
            *base_finals,
            self.LONG_TP_EXIT_RECOVERY_PURPOSE,
            self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
            "FINAL_LONG_EXIT",
            "FINAL_SHORT_EXIT",
        }

    def _consume_expected_exit_cancel(
        self,
        runtime_state: RuntimeState,
        *,
        purpose: str | None,
        source_order_id: str | None,
        source_order_link_id: str | None,
        status: str,
    ) -> bool:
        if purpose not in self._expected_exit_cancel_purposes():
            return False
        state = runtime_state.strategy_state
        registry = state.get("expected_exit_cancels")
        if not isinstance(registry, list) or not registry:
            return False
        now = time.monotonic()
        matched = False
        new_registry: list[dict[str, Any]] = []
        for entry in registry:
            if not isinstance(entry, dict):
                continue
            expires_at = float(entry.get("expires_at_monotonic") or 0.0)
            if expires_at and expires_at < now:
                continue
            entry_exchange_id = entry.get("exchange_order_id")
            entry_client_id = entry.get("client_order_id")
            same_exchange = (
                bool(entry_exchange_id)
                and bool(source_order_id)
                and entry_exchange_id == source_order_id
            )
            same_client = (
                bool(entry_client_id)
                and bool(source_order_link_id)
                and entry_client_id == source_order_link_id
            )
            if (
                not matched
                and entry.get("purpose") == purpose
                and (same_exchange or same_client)
            ):
                entry = dict(entry)
                entry["consumed"] = True
                entry["consumed_at_monotonic"] = now
                matched = True
                _log_event(
                    "fixed_cycle_emergency_exit_suppressed_expected_cancel",
                    {
                        "symbol": self.config.symbol,
                        "purpose": purpose,
                        "status": status,
                        "client_order_id": entry.get("client_order_id"),
                        "exchange_order_id": entry.get("exchange_order_id"),
                        "replacement_purpose": entry.get("replacement_purpose"),
                    },
                )
                _log_event(
                    "fixed_cycle_deactivation_ignored_expected_replace",
                    {
                        "symbol": self.config.symbol,
                        "purpose": purpose,
                        "status": status,
                        "client_order_id": entry.get("client_order_id"),
                        "exchange_order_id": entry.get("exchange_order_id"),
                        "replacement_purpose": entry.get("replacement_purpose"),
                    },
                )
                continue
            new_registry.append(entry)
        state["expected_exit_cancels"] = new_registry
        return matched

    def _check_expected_cancel_replacement_timeouts(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent] | None:
        state = runtime_state.strategy_state
        registry = state.get("expected_exit_cancels")
        if not isinstance(registry, list) or not registry:
            return None
        now = time.monotonic()
        active_replacement_purposes = {
            str(getattr(order, "purpose", "") or "")
            for order in runtime_state.active_orders.values()
            if not self._is_terminal_order_status(getattr(order, "status", None))
        } | {
            str(getattr(order, "purpose", "") or "")
            for order in snapshot.active_orders
            if not self._is_terminal_order_status(getattr(order, "status", None))
        }
        new_registry: list[dict[str, Any]] = []
        timeout_triggered = False
        for entry in registry:
            if not isinstance(entry, dict):
                continue
            expires_at = float(entry.get("expires_at_monotonic") or 0.0)
            replacement_purpose = str(entry.get("replacement_purpose") or "")
            if replacement_purpose and replacement_purpose in active_replacement_purposes:
                continue
            if entry.get("consumed") and expires_at and expires_at < now:
                _log_warning_event(
                    "fixed_cycle_expected_cancel_replacement_missing",
                    {
                        "symbol": self.config.symbol,
                        "purpose": entry.get("purpose"),
                        "client_order_id": entry.get("client_order_id"),
                        "exchange_order_id": entry.get("exchange_order_id"),
                        "replacement_purpose": replacement_purpose,
                    },
                )
                timeout_triggered = True
                continue
            if expires_at and expires_at < now and not entry.get("consumed"):
                continue
            new_registry.append(entry)
        state["expected_exit_cancels"] = new_registry
        if not timeout_triggered:
            return None
        if not self._trigger_emergency_flat_for_remaining_positions(
            snapshot,
            runtime_state,
            context,
            "expected_cancel_replacement_missing",
        ):
            if runtime_state.strategy_state.get("emergency_flat_required"):
                return None
            return []
        return self._maybe_handle_emergency_exit_tick(snapshot, runtime_state, context)

    def _resolve_emergency_snapshot(self, snapshot: HedgeSnapshot, context: StrategyContext | None) -> HedgeSnapshot:
        if snapshot and (
            (snapshot.long_qty or 0.0) > 0
            or (snapshot.short_qty or 0.0) > 0
            or (snapshot.active_orders or ())
        ):
            return snapshot
        if context and context.refresh_snapshot:
            try:
                return context.refresh_snapshot("emergency_exit")
            except Exception:
                pass
        return snapshot

    def _clear_emergency_state(self, runtime_state: RuntimeState) -> None:
        for key in (
            "emergency_flat_required",
            "emergency_exit_signature",
            "emergency_exit_reason",
            "emergency_exit_attempts",
            "emergency_exit_verify_attempts",
        ):
            runtime_state.strategy_state.pop(key, None)

    def _transition_emergency_flat_to_cleanup(
        self,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        remaining_active_orders: list[ManagedOrder],
    ) -> None:
        state = runtime_state.strategy_state
        remaining_purposes = [
            getattr(order, "purpose", None) or getattr(order, "client_order_id", None)
            for order in remaining_active_orders
        ]
        _log_event(
            "fixed_cycle_emergency_exit_transition_to_cleanup",
            {
                "symbol": self.config.symbol,
                "reason": state.get("emergency_exit_reason"),
                "remaining_active_orders": len(remaining_active_orders),
                "remaining_active_order_purposes": remaining_purposes,
            },
        )
        self._cancel_all_orders_after_exit(runtime_state, context)
        state["fresh_restart_required"] = True
        self._ensure_post_exit_cleanup_required(
            runtime_state, reason="emergency_flat_positions_closed"
        )
        for key in (
            "emergency_flat_required",
            "emergency_exit_signature",
            "emergency_exit_attempts",
            "emergency_exit_verify_attempts",
        ):
            state.pop(key, None)

    def _build_emergency_close_intents(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        *,
        reason: str,
    ) -> list[StrategyIntent]:
        state = runtime_state.strategy_state
        intents: list[StrategyIntent] = []
        long_qty = float(snapshot.long_qty or 0.0)
        short_qty = float(snapshot.short_qty or 0.0)
        if long_qty <= 0 and short_qty <= 0:
            return []
        trigger_ts = state.get("emergency_trigger_monotonic")
        latency_ms = (
            max(0, int((time.monotonic() - trigger_ts) * 1000))
            if trigger_ts and trigger_ts > 0
            else None
        )
        previous_attempts = int(state.get("emergency_exit_attempts") or 0)
        attempt = previous_attempts + 1
        state["emergency_exit_attempts"] = attempt
        normalized_long = self._safe_recovery_qty(long_qty)
        normalized_short = self._safe_recovery_qty(short_qty)
        for side, qty, purpose, position_idx in (
            ("long", normalized_long, self.EMERGENCY_FLAT_LONG_PURPOSE, 1),
            ("short", normalized_short, self.EMERGENCY_FLAT_SHORT_PURPOSE, 2),
        ):
            if qty <= 0:
                continue
            intent = StrategyIntent(
                side=side,
                qty=qty,
                purpose=purpose,
                order_type="Market",
                reduce_only=True,
                close_on_trigger=False,
                position_idx=position_idx,
                metadata={
                    "emergency_reason": reason,
                    "emergency_attempt": attempt,
                    "emergency_signature": state.get("emergency_exit_signature"),
                },
            )
            intents.append(intent)
            _log_event(
                "fixed_cycle_emergency_exit_close_submitted",
                {
                    "symbol": self.config.symbol,
                    "side": side,
                    "qty": qty,
                    "position_idx": position_idx,
                    "purpose": purpose,
                    "attempt": attempt,
                    "reason": reason,
                    **(
                        {"emergency_latency_ms": latency_ms}
                        if latency_ms is not None
                        else {}
                    ),
                },
            )
        return intents

    def _trigger_emergency_exit(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext | None,
        payload: dict[str, Any],
        reason: str,
        *,
        allow_repeat: bool = False,
    ) -> list[StrategyIntent]:
        state = runtime_state.strategy_state
        snapshot = self._resolve_emergency_snapshot(snapshot, context)
        signature = self._emergency_exit_signature(payload) or state.get("emergency_exit_signature")
        if signature:
            state["emergency_exit_signature"] = signature
        self._record_emergency_trigger(runtime_state)
        state["emergency_exit_reason"] = reason
        state["emergency_flat_required"] = True
        state["emergency_exit_verify_attempts"] = 0
        guard_payload = {
            "symbol": self.config.symbol,
            "long_qty": snapshot.long_qty,
            "short_qty": snapshot.short_qty,
            "current_price": snapshot.current_price,
            "signature": signature,
            "reason": reason,
            "status": payload.get("orderStatus"),
        }
        _log_warning_event("fixed_cycle_emergency_exit_guard_triggered", guard_payload)
        _log_event(
            "fixed_cycle_emergency_exit_snapshot",
            {
                **guard_payload,
                "active_orders": len(snapshot.active_orders or ()),
            },
        )
        intents = self._build_emergency_close_intents(snapshot, runtime_state, reason=reason)
        if not intents:
            _log_event(
                "fixed_cycle_emergency_exit_completed",
                {
                    "symbol": self.config.symbol,
                    "reason": reason,
                    "long_qty": snapshot.long_qty,
                    "short_qty": snapshot.short_qty,
                },
            )
            self._clear_emergency_state(runtime_state)
        return intents

    def _maybe_handle_emergency_exit_tick(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent] | None:
        state = runtime_state.strategy_state
        if not state.get("emergency_flat_required"):
            return None
        long_qty = float(snapshot.long_qty or 0.0)
        short_qty = float(snapshot.short_qty or 0.0)
        active_orders = [
            order
            for order in runtime_state.active_orders.values()
            if getattr(order, "status", None) not in {"FILLED", "CANCELED", "CANCELLED", "REJECTED"}
        ]
        emergency_orders = [
            order
            for order in active_orders
            if getattr(order, "purpose", None) in {self.EMERGENCY_FLAT_LONG_PURPOSE, self.EMERGENCY_FLAT_SHORT_PURPOSE}
        ]
        verify_attempts = int(state.get("emergency_exit_verify_attempts") or 0) + 1
        state["emergency_exit_verify_attempts"] = verify_attempts
        _log_event(
            "fixed_cycle_emergency_exit_verify_flat",
            {
                "symbol": self.config.symbol,
                "long_qty": long_qty,
                "short_qty": short_qty,
                "active_orders": len(active_orders),
                "emergency_orders": len(emergency_orders),
                "attempt": verify_attempts,
                "reason": state.get("emergency_exit_reason"),
            },
        )
        if long_qty <= 0 and short_qty <= 0 and not emergency_orders:
            self._transition_emergency_flat_to_cleanup(
                runtime_state,
                context,
                remaining_active_orders=active_orders,
            )
            return []
        if emergency_orders:
            return []
        if verify_attempts <= self.EMERGENCY_EXIT_MAX_RETRIES:
            intents = self._build_emergency_close_intents(
                snapshot,
                runtime_state,
                reason=str(state.get("emergency_exit_reason") or ""),
            )
            if intents:
                return intents
            return []
        _log_warning_event(
            "fixed_cycle_emergency_exit_failed",
            {
                "symbol": self.config.symbol,
                "reason": state.get("emergency_exit_reason"),
                "long_qty": long_qty,
                "short_qty": short_qty,
                "verify_attempts": verify_attempts,
            },
        )
        return []

    def _record_emergency_trigger(self, runtime_state: RuntimeState) -> None:
        runtime_state.strategy_state["emergency_trigger_monotonic"] = time.monotonic()

    def _trigger_emergency_flat_for_remaining_positions(
        self,
        snapshot: HedgeSnapshot | None,
        runtime_state: RuntimeState,
        context: StrategyContext | None,
        reason: str,
    ) -> bool:
        state = runtime_state.strategy_state
        if state.get("emergency_flat_required"):
            return False
        emerg_snapshot = snapshot or runtime_state.last_snapshot
        long_qty = float(getattr(emerg_snapshot, "long_qty", 0.0) or 0.0)
        short_qty = float(getattr(emerg_snapshot, "short_qty", 0.0) or 0.0)
        if long_qty <= 0 and short_qty <= 0:
            return False
        self._record_emergency_trigger(runtime_state)
        guard_payload = {
            "symbol": self.config.symbol,
            "reason": reason,
            "long_qty": long_qty,
            "short_qty": short_qty,
            "active_orders": len(getattr(emerg_snapshot, "active_orders", ()) or ()),
        }
        _log_warning_event("fixed_cycle_emergency_exit_guard_triggered_missing_or_incomplete_final_exit", guard_payload)
        _log_event(
            "fixed_cycle_emergency_exit_remaining_position_detected",
            {
                **guard_payload,
                "snapshot_source": getattr(emerg_snapshot, "source", None),
            },
        )
        state["emergency_flat_required"] = True
        state["emergency_exit_reason"] = reason
        state["emergency_exit_signature"] = f"missing-{reason}"
        state["emergency_exit_attempts"] = 0
        return True

    def on_order_update(
        self,
        payload,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
    ) -> list[StrategyIntent]:
        payload_data = payload if isinstance(payload, dict) else {}
        source_order_id = str(payload_data.get("orderId") or "").strip()
        purpose = self._recover_purpose_from_order_update(payload_data)
        if not purpose:
            purpose = str(payload_data.get("purpose") or "").strip().upper()
        if not purpose and source_order_id:
            for order in runtime_state.active_orders.values():
                if str(getattr(order, "exchange_order_id", "") or "").strip() == source_order_id:
                    purpose = str(getattr(order, "purpose", "") or "").strip().upper()
                    break
        # Fallback: Purpose aus Snapshot-Orders rekonstruieren, falls Runtime-Orders bereits bereinigt wurden.
        if not purpose and source_order_id and snapshot is not None:
            for order in getattr(snapshot, "active_orders", []) or []:
                try:
                    ex_id = str(getattr(order, "exchange_order_id", "") or "").strip()
                except Exception:
                    ex_id = ""
                if ex_id and ex_id == source_order_id:
                    try:
                        purpose = str(getattr(order, "purpose", "") or "").strip().upper()
                    except Exception:
                        purpose = ""
                    if purpose:
                        break
        status = str(payload_data.get("orderStatus") or "").upper()
        reject_reason = str(payload_data.get("rejectReason") or "").strip()
        reason_upper = reject_reason.upper()
        source_order_link_id = (
            str(payload_data.get("orderLinkId") or "").strip()
            or str(payload_data.get("order_link_id") or "").strip()
            or str(payload_data.get("clientOrderId") or "").strip()
            or str(payload_data.get("client_order_id") or "").strip()
            or str(payload_data.get("order_link_id") or "").strip()
            or ""
        )
        metadata_link = payload_data.get("metadata") or {}
        if not source_order_link_id:
            source_order_link_id = str(metadata_link.get("order_link_id") or "").strip()
        if not source_order_link_id and source_order_id:
            source_order_link_id = source_order_id
        state = runtime_state.strategy_state
        expected_suppressed = False
        if (
            purpose in self._expected_exit_cancel_purposes()
            and status in self.EMERGENCY_EXIT_STATUSES
            and reason_upper != self.EMERGENCY_REJECT_REASON
            and self._consume_expected_exit_cancel(
                runtime_state,
                purpose=purpose,
                source_order_id=source_order_id or None,
                source_order_link_id=source_order_link_id or None,
                status=status,
            )
        ):
            expected_suppressed = True
            return []

        current_snapshot = snapshot or runtime_state.last_snapshot
        long_qty = (
            float(current_snapshot.long_qty or 0.0)
            if current_snapshot
            else float(state.get("open_long_qty") or 0.0)
        )
        short_qty = (
            float(current_snapshot.short_qty or 0.0)
            if current_snapshot
            else float(state.get("open_short_qty") or 0.0)
        )
        has_exit_signature = bool(state.get("last_exit_signature"))
        exit_order_history = bool(state.get("exit_orders_submitted_once"))
        latest_tp_price = float(state.get("latest_tp_price") or 0.0)
        latest_break_even_price = float(state.get("latest_break_even_price") or 0.0)
        has_exit_prices = latest_tp_price > 0 or latest_break_even_price > 0
        fallback_marker = bool(state.get("final_exit_context_missing_but_flat_confirmed"))
        if (
            purpose in self._get_final_exit_purposes()
            and status == "DEACTIVATED"
            and long_qty <= 0
            and short_qty <= 0
            and (has_exit_signature or exit_order_history)
            and has_exit_prices
        ):
            if not fallback_marker:
                state["final_exit_context_missing_but_flat_confirmed"] = True
                state["final_exit_fallback_reason"] = "deactivated_after_flat_final_exit"
                state["final_exit_fallback_applied_at"] = datetime.now(timezone.utc).isoformat()
                state["fresh_restart_required"] = True
            _log_event(
                "fixed_cycle_final_exit_deactivated_ignored_after_flat_fallback",
                {
                    "symbol": self.config.symbol,
                    "purpose": purpose,
                    "status": status,
                    "reason": state.get("final_exit_fallback_reason")
                    or "deactivated_after_flat_final_exit",
                    "client_order_id": source_order_link_id or source_order_id or None,
                    "exchange_order_id": source_order_id or None,
                    "long_qty": long_qty,
                    "short_qty": short_qty,
                    "latest_tp_price": latest_tp_price,
                    "latest_break_even_price": latest_break_even_price,
                },
            )
            return []

        if status == "DEACTIVATED" and state.get("refill_completion_pending_reconcile"):
            _log_event(
                "fixed_cycle_exit_deactivation_deferred_during_refill_reconcile",
                {
                    "symbol": self.config.symbol,
                    "purpose": purpose,
                    "status": status,
                    "refill_pending": bool(state.get("refill_pending")),
                    "refill_in_progress": bool(state.get("refill_in_progress")),
                    "refill_long_filled": bool(state.get("refill_long_filled")),
                    "refill_short_filled": bool(state.get("refill_short_filled")),
                    "refill_fills_complete": bool(state.get("refill_fills_complete")),
                    "refill_completion_pending_reconcile": True,
                    "long_qty": long_qty,
                    "short_qty": short_qty,
                },
            )
            return []

        managed_cycle_deactivation = self._is_cycle_fill_purpose(purpose)
        managed_exit_deactivation = purpose in self._expected_exit_cancel_purposes()
        if status == "DEACTIVATED" and (managed_cycle_deactivation or managed_exit_deactivation):
            structure_intact, structure_details = (
                self._verify_structure_intact_before_deactivation_recovery(
                    snapshot,
                    runtime_state,
                    context,
                    purpose=purpose,
                    order_link_id=source_order_link_id,
                    exchange_order_id=source_order_id,
                    reason=reason_upper or status,
                )
            )
            if structure_intact:
                _log_event(
                    "fixed_cycle_ws_deactivated_ignored_structure_intact",
                    structure_details,
                )
                return []
            _log_event(
                "fixed_cycle_ws_deactivated_structure_missing_orders",
                {
                    "symbol": self.config.symbol,
                    "deactivated_purpose": purpose,
                    "order_link_id": source_order_link_id or None,
                    "exchange_order_id": source_order_id or None,
                    "rest_open_purposes": structure_details.get("rest_open_purposes", []),
                    "expected_cycle_purpose": structure_details.get("expected_cycle_purpose"),
                    "missing_purposes": structure_details.get("missing_purposes", []),
                },
            )

        if (
            purpose in self._get_final_exit_purposes()
            and status == "DEACTIVATED"
            and not expected_suppressed
        ):
            recovery_intents = self._attempt_exit_deactivated_recovery(
                snapshot,
                runtime_state,
                context,
                purpose=purpose,
                source_order_id=source_order_id,
                source_order_link_id=source_order_link_id,
                status=status,
                reason=reason_upper or status,
            )
            if recovery_intents:
                return recovery_intents

            # Wenn eine aktive Exit-Order unerwartet deaktiviert wird, während noch Position offen ist,
            # muss der Exit-Lock gelöst und ein Rebuild erzwungen werden.
            if long_qty > 0 or short_qty > 0:
                snapshot_purposes, runtime_purposes = self._collect_active_final_exit_purposes(
                    current_snapshot, runtime_state
                )
                active_final_exit_purposes = sorted(
                    set(snapshot_purposes or []) | set(runtime_purposes or [])
                )
                long_exit_purpose = self._get_final_long_exit_purpose()
                short_exit_purpose = self._get_final_short_exit_purpose()
                missing_long_exit = long_exit_purpose not in active_final_exit_purposes
                missing_short_exit = short_exit_purpose not in active_final_exit_purposes
                if missing_long_exit or missing_short_exit:
                    exit_locked_before = bool(state.get("exit_locked"))
                    exit_rebuild_allowed_before = bool(state.get("exit_rebuild_allowed", True))
                    state["exit_locked"] = False
                    state["exit_rebuild_allowed"] = True
                    state["force_exit_rebuild"] = True
                    state["pending_loss_exit_rebuild_reason"] = "missing_exit_protection_after_deactivation"
                    state["pending_loss_exit_old_signature"] = state.get("last_exit_signature")
                    _log_event(
                        "fixed_cycle_unexpected_exit_order_deactivated_rebuild_required",
                        {
                            "symbol": self.config.symbol,
                            "purpose": purpose,
                            "status": status,
                            "reason": reason_upper or status,
                            "long_qty": long_qty,
                            "short_qty": short_qty,
                            "missing_long_exit": missing_long_exit,
                            "missing_short_exit": missing_short_exit,
                            "active_final_exit_purposes": active_final_exit_purposes,
                            "exit_locked_before": exit_locked_before,
                            "exit_rebuild_allowed_before": exit_rebuild_allowed_before,
                        },
                    )
                    _log_event(
                        "fixed_cycle_exit_lock_lifted_for_missing_exit_protection",
                        {
                            "symbol": self.config.symbol,
                            "purpose": purpose,
                            "long_qty": long_qty,
                            "short_qty": short_qty,
                            "missing_long_exit": missing_long_exit,
                            "missing_short_exit": missing_short_exit,
                        },
                    )
        if (
            purpose in self._expected_exit_cancel_purposes()
            and status == "DEACTIVATED"
            and not expected_suppressed
        ):
            _log_event(
                "fixed_cycle_unexpected_exit_deactivation_emergency",
                {
                    "symbol": self.config.symbol,
                    "purpose": purpose,
                    "status": status,
                    "reason": reason_upper or status,
                    "client_order_id": source_order_link_id or source_order_id or None,
                    "exchange_order_id": source_order_id or None,
                },
            )
        if self._should_trigger_emergency_exit(
            state,
            purpose,
            status,
            reason_upper,
            payload_data,
        ):
            intents = self._trigger_emergency_exit(snapshot, runtime_state, context, payload_data, reason_upper or status)
            return intents
        if status not in {"CANCELED", "CANCELLED", "REJECTED", "DEACTIVATED", "EXPIRED"}:
            return []

        if purpose in {"REFILL_LONG", "REFILL_SHORT"}:
            self._reconcile_refill_gate_state(snapshot, runtime_state)
            return []
        if purpose not in {
            self.LONG_TP_EXIT_PURPOSE,
            self.SHORT_SL_EXIT_PURPOSE,
            self.LONG_TP_EXIT_RECOVERY_PURPOSE,
            self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
        }:
            return []

        if purpose in {self.SHORT_SL_EXIT_PURPOSE, self.SHORT_SL_EXIT_RECOVERY_PURPOSE}:
            if short_qty <= 0:
                _log_event(
                    "fixed_cycle_short_exit_force_market_recovery_not_needed",
                    {
                        "symbol": self.config.symbol,
                        "side": "short",
                        "qty": short_qty,
                        "purpose": self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
                        "original_purpose": purpose,
                        "source_order_id": source_order_id,
                        "source_order_link_id": source_order_link_id,
                        "reason": status,
                        "exit_locked": bool(state.get("exit_locked")),
                        "exit_rebuild_allowed": bool(state.get("exit_rebuild_allowed")),
                    },
                )
                return []
            if state.get("short_exit_recovery_submitted"):
                _log_event(
                    "fixed_cycle_short_exit_force_market_recovery_skipped_duplicate",
                    {
                        "symbol": self.config.symbol,
                        "side": "short",
                        "qty": short_qty,
                        "purpose": self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
                        "original_purpose": purpose,
                        "source_order_id": source_order_id,
                        "source_order_link_id": source_order_link_id,
                        "reason": status,
                        "exit_locked": bool(state.get("exit_locked")),
                        "exit_rebuild_allowed": bool(state.get("exit_rebuild_allowed")),
                    },
                )
                return []
            state["exit_rebuild_allowed"] = True
            state["exit_locked"] = False
            state["exit_recovery_marker"] = True
            state["short_exit_recovery_submitted"] = True
            intent = self._build_force_exit_recovery_intent(
                side="short",
                qty=short_qty,
                symbol=self.config.symbol,
                purpose=self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
                reason=status,
                source_order_id=source_order_id,
                source_order_link_id=source_order_link_id,
            )
            _log_warning_event(
                "fixed_cycle_short_exit_force_market_recovery",
                {
                    "symbol": self.config.symbol,
                    "side": "short",
                    "qty": short_qty,
                    "purpose": self.SHORT_SL_EXIT_RECOVERY_PURPOSE,
                    "original_purpose": purpose,
                    "source_order_id": source_order_id,
                    "source_order_link_id": source_order_link_id,
                    "reason": status,
                    "exit_locked": bool(state.get("exit_locked")),
                    "exit_rebuild_allowed": bool(state.get("exit_rebuild_allowed")),
                },
            )
            return [intent]

        if purpose in {self.LONG_TP_EXIT_PURPOSE, self.LONG_TP_EXIT_RECOVERY_PURPOSE}:
            if long_qty <= 0:
                _log_event(
                    "fixed_cycle_long_exit_force_market_recovery_not_needed",
                    {
                        "symbol": self.config.symbol,
                        "side": "long",
                        "qty": long_qty,
                        "purpose": self.LONG_TP_EXIT_RECOVERY_PURPOSE,
                        "original_purpose": purpose,
                        "source_order_id": source_order_id,
                        "source_order_link_id": source_order_link_id,
                        "reason": status,
                        "exit_locked": bool(state.get("exit_locked")),
                        "exit_rebuild_allowed": bool(state.get("exit_rebuild_allowed")),
                    },
                )
                return []
            if state.get("long_exit_recovery_submitted"):
                _log_event(
                    "fixed_cycle_long_exit_force_market_recovery_skipped_duplicate",
                    {
                        "symbol": self.config.symbol,
                        "side": "long",
                        "qty": long_qty,
                        "purpose": self.LONG_TP_EXIT_RECOVERY_PURPOSE,
                        "original_purpose": purpose,
                        "source_order_id": source_order_id,
                        "source_order_link_id": source_order_link_id,
                        "reason": status,
                        "exit_locked": bool(state.get("exit_locked")),
                        "exit_rebuild_allowed": bool(state.get("exit_rebuild_allowed")),
                    },
                )
                return []
            state["exit_rebuild_allowed"] = True
            state["exit_locked"] = False
            state["exit_recovery_marker"] = True
            state["long_exit_recovery_submitted"] = True
            intent = self._build_force_exit_recovery_intent(
                side="long",
                qty=long_qty,
                symbol=self.config.symbol,
                purpose=self.LONG_TP_EXIT_RECOVERY_PURPOSE,
                reason=status,
                source_order_id=source_order_id,
                source_order_link_id=source_order_link_id,
            )
            _log_warning_event(
                "fixed_cycle_long_exit_force_market_recovery",
                {
                    "symbol": self.config.symbol,
                    "side": "long",
                    "qty": long_qty,
                    "purpose": self.LONG_TP_EXIT_RECOVERY_PURPOSE,
                    "original_purpose": purpose,
                    "source_order_id": source_order_id,
                    "source_order_link_id": source_order_link_id,
                    "reason": status,
                    "exit_locked": bool(state.get("exit_locked")),
                    "exit_rebuild_allowed": bool(state.get("exit_rebuild_allowed")),
                },
            )
            return [intent]

        return []

    def _remove_exit_order_from_runtime(
        self,
        runtime_state: RuntimeState,
        *,
        source_order_id: str | None,
        source_order_link_id: str | None,
    ) -> ManagedOrder | None:
        client_key = source_order_link_id or ""
        managed_order = runtime_state.active_orders.pop(client_key, None)
        if not managed_order and source_order_id:
            for client_order_id, order in list(runtime_state.active_orders.items()):
                if (getattr(order, "exchange_order_id", "") or "") == source_order_id:
                    managed_order = runtime_state.active_orders.pop(client_order_id, None)
                    client_key = client_order_id
                    break
        if managed_order and getattr(managed_order, "exchange_order_id", None):
            runtime_state.exchange_to_client_id.pop(managed_order.exchange_order_id, None)
        return managed_order

    def _attempt_exit_deactivated_recovery(
        self,
        snapshot: HedgeSnapshot,
        runtime_state: RuntimeState,
        context: StrategyContext,
        *,
        purpose: str,
        source_order_id: str,
        source_order_link_id: str,
        status: str,
        reason: str,
    ) -> list[StrategyIntent] | None:
        state = runtime_state.strategy_state
        if state.get("refill_completion_pending_reconcile"):
            _log_event(
                "fixed_cycle_exit_deactivation_deferred_during_refill_reconcile",
                {
                    "symbol": self.config.symbol,
                    "purpose": purpose,
                    "status": status,
                    "refill_pending": bool(state.get("refill_pending")),
                    "refill_in_progress": bool(state.get("refill_in_progress")),
                    "refill_long_filled": bool(state.get("refill_long_filled")),
                    "refill_short_filled": bool(state.get("refill_short_filled")),
                },
            )
            return None
        if state.get("emergency_flat_required"):
            return None
        current_snapshot = snapshot or runtime_state.last_snapshot
        long_qty = float(getattr(current_snapshot, "long_qty", 0.0) or 0.0)
        short_qty = float(getattr(current_snapshot, "short_qty", 0.0) or 0.0)
        if long_qty <= 0 and short_qty <= 0:
            return None
        raw_attempts = state.setdefault("exit_deactivation_recovery_attempts", [])
        if isinstance(raw_attempts, set):
            attempts = set(str(value) for value in raw_attempts if value)
        elif isinstance(raw_attempts, list):
            attempts = set(str(value) for value in raw_attempts if value)
        else:
            attempts = set()
        attempt_key = (source_order_id or "") or (source_order_link_id or "")
        if not attempt_key:
            attempt_key = f"{purpose}:{status}"
        attempt_key = str(attempt_key)
        if attempt_key in attempts:
            state["exit_deactivation_recovery_attempts"] = sorted(attempts)
            return None
        attempts.add(attempt_key)
        state["exit_deactivation_recovery_attempts"] = sorted(attempts)
        _log_event(
            "fixed_cycle_unexpected_exit_deactivation_recovery_attempt",
            {
                "symbol": self.config.symbol,
                "purpose": purpose,
                "status": status,
                "reason": reason,
                "client_order_id": source_order_link_id or None,
                "exchange_order_id": source_order_id or None,
                "long_qty": long_qty,
                "short_qty": short_qty,
            },
        )
        self._remove_exit_order_from_runtime(
            runtime_state,
            source_order_id=source_order_id,
            source_order_link_id=source_order_link_id,
        )
        state["exit_rebuild_allowed"] = True
        state["exit_locked"] = False
        state["force_exit_rebuild"] = True
        state["pending_loss_exit_rebuild_reason"] = reason
        intents = self._rebuild_structure(
            current_snapshot,
            runtime_state,
            context,
            reason="unexpected_exit_deactivated_recovery",
        )
        if intents:
            _log_event(
                "fixed_cycle_unexpected_exit_deactivation_recovery_succeeded",
                {
                    "symbol": self.config.symbol,
                    "purpose": purpose,
                    "status": status,
                    "client_order_id": source_order_link_id or None,
                    "exchange_order_id": source_order_id or None,
                    "intents": [intent.purpose for intent in intents],
                },
            )
            return intents
        _log_event(
            "fixed_cycle_unexpected_exit_deactivation_recovery_failed",
            {
                "symbol": self.config.symbol,
                "purpose": purpose,
                "status": status,
                "client_order_id": source_order_link_id or None,
                "exchange_order_id": source_order_id or None,
                "intents": [],
            },
        )
        return None


class ShortFixedCycleHedgeStrategy(FixedCycleHedgeStrategy):
    """Minimal short-bot skeleton overriding helper names."""

    def __init__(self, config: FixedCycleHedgeConfig | None = None) -> None:
        super().__init__(config)
        direction = direction_config.get_direction_config("short_primary")
        self._sequence_config = CycleSequenceConfig(
            cycle_prefix="CYCLE",
            first_leg=direction.cycle_first_leg,
            second_leg=direction.cycle_second_leg,
        )

    def _get_first_leg_side(self) -> str:
        return "short"

    def _get_first_leg_position_idx(self) -> int:
        return 2

    def _get_first_leg_purpose(self, cycle_index: int) -> str:
        return purpose_mapping.cycle_short_reduce(cycle_index)

    def _get_first_leg_status_field(self) -> str:
        return "short_reduce_status"

    def _get_second_leg_purpose(self, cycle_index: int) -> str:
        return purpose_mapping.cycle_long_reduce(cycle_index)

    def _get_first_leg_cycle_role(self) -> str:
        return "short_reduce"

    def _get_second_leg_cycle_role(self) -> str:
        return "long_reduce"

    def _get_second_leg_status_field(self) -> str:
        return "long_reduce_status"

    def _second_leg_fill_price_field(self) -> str:
        return "long_reduce_fill_price"

    def _second_leg_fill_confirmed_field(self) -> str:
        return "long_reduce_fill_confirmed"

    def _first_leg_pending_field(self) -> str:
        return "short_reduce_pending"

    def _second_leg_waiting_flag_field(self) -> str:
        return "cycle_waiting_for_long_reduce"

    def _second_leg_pending_cycle_field(self) -> str:
        return "long_reduce_pending_cycle"

    def _normalize_cycle_purpose(
        self,
        purpose: Any,
        metadata: dict[str, Any] | None = None,
    ) -> str:
        purpose_text = str(purpose or "").upper()
        if re.fullmatch(r"CYCLE_\d+_SHORT_REDUCE", purpose_text):
            return purpose_text
        if re.fullmatch(r"CYCLE_\d+_LONG_REDUCE", purpose_text):
            return purpose_text
        metadata = metadata or {}
        cycle_index, field_name = self._extract_cycle_sequence_target(purpose_text, metadata)
        if cycle_index > 0 and field_name == self._get_second_leg_status_field():
            return self._get_second_leg_purpose(cycle_index)
        return super()._normalize_cycle_purpose(purpose, metadata)

    def _is_second_leg_purpose(self, purpose: str) -> bool:
        normalized = self._normalize_cycle_purpose(purpose)
        return bool(re.fullmatch(r"CYCLE_\d+_LONG_REDUCE", normalized))

    def _get_final_long_exit_purpose(self) -> str:
        # Für den Short-Bot ist der Long-Bein-Exit gespiegelt ein Stop-Loss.
        return self.LONG_SL_EXIT_PURPOSE

    def _get_final_short_exit_purpose(self) -> str:
        # Für den Short-Bot ist der Short-Bein-Exit gespiegelt ein Take-Profit.
        return self.SHORT_TP_EXIT_PURPOSE

